# SetResourceCustomName notifies qrenderdoc viewers synchronously. Keep the
# indivisible GUI transaction small even when a valid manifest contains many
# deterministic aliases; oversized plans fail before any name mutation.
MAX_SYMBOL_ALIAS_UI_RENAME_RESOURCES = 256
SYMBOL_ALIAS_ROLLBACK_SCHEMA = "renderdoc-ultra-alias-rollback/v1"
SYMBOL_ALIAS_ROLLBACK_VERSION = 1
SYMBOL_ALIAS_TRANSACTION_STATUS_SCHEMA = (
    "renderdoc-ultra-alias-transaction-status/v1")
SYMBOL_ALIAS_TRANSACTION_STATUS_VERSION = 1

# Aliases are kept outside RenderDoc's immutable shader reflection. The active list only
# contains aliases that passed validation (and confirmation when requested by the loader).
_symbol_alias_overlay = {
    "schema": SYMBOL_ALIAS_SCHEMA,
    "schemaVersion": SYMBOL_ALIAS_VERSION,
    "captureId": "",
    "sourcePath": "",
    "confirmedOnly": True,
    "allAliases": [],
    "aliases": [],
}

# The alias manifest is only meaningful for the exact capture catalog that was exported by this
# bridge instance. ResourceId values are capture-local and therefore never survive this reset.
_symbol_capture_snapshot = {
    "captureId": "",
    "capturePath": "",
    "shaderKeys": set(),
    "usesByKey": {},
}
_known_catalog_capture_ids = {}
_known_catalog_identity_pairs = set()
# The same authorisation, keyed by an identity a stored workspace can reproduce
# after a restart: (stableCaptureId, stableIdentityEvidenceSha256).
_known_catalog_stable_pairs = set()
_project_shader_index_jobs = {}
_project_shader_index_jobs_guard = threading.RLock()
_shader_catalog_export_jobs = {}
_shader_catalog_export_jobs_guard = threading.RLock()
_shader_catalog_finalize_workers = set()
_shader_catalog_finalize_stopping = False
_current_context_freeze_jobs = {}
_current_context_freeze_jobs_guard = threading.RLock()
_replay_recovery_path = ""
_replay_recovery_coordinator = None
_request_event_state = threading.local()
_request_dispatch_state = threading.local()
_symbol_resource_renames = {}
_symbol_rename_capture_token = None
# A strict alias transaction is physically implemented by a sequence of
# qrenderdoc name updates, so it cannot be physically atomic.  Publish this
# single bounded ledger before the first update and retain it after commit so
# a lost response or a partial forward/rollback failure remains recoverable.
_symbol_alias_recovery_ledger = None
_symbol_alias_last_rollback_receipt = None

# Target shaders used by event-scoped overrides are owned by the active replay
# controller.  Never carry these ResourceIds across a capture lifecycle.
_event_shader_overrides = {}
_event_shader_targets = {}
_event_shader_override_capture_token = None
# Successful rollback receipts outlive their active override records so a lost
# IPC response can be retried without mutating replay a second time. Entries
# are capture-session-local and explicitly ordered for bounded Python 3.6
# eviction (do not rely on dict insertion order here).
_event_shader_rollback_tombstones = {}
_event_shader_rollback_tombstone_order = []

# Resource-scoped shader replacements preserve RenderDoc's captured sharing
# relationship: exactly one generated target is owned for each original shader
# ResourceId, and ReplayController.ReplaceResource makes every use of that
# captured resource observe it.  These records are deliberately separate from
# the opt-in event-scoped override table above so the two scopes can never be
# mistaken for one another.
_shared_shader_replacements = {}
_shared_shader_orphan_targets = []
_shared_shader_manual_target_cache = []
_shared_shader_replacement_capture_token = None
# A caller-issued operation token closes the gap between a committed replay
# mutation and a lost/corrupt IPC response. Outcomes remain capture-local and
# bounded; the recovery route can prove no-op/absence or roll back the exact
# replacement without guessing a replacementId.
_shared_shader_operation_outcomes = {}
_shared_shader_operation_outcome_order = []
_shared_shader_rollback_tombstones = {}
_shared_shader_rollback_tombstone_order = []
# Monotonic process-local generation for the bridge-owned shared replacement
# map. It is evidence for the exact linearization point of a composite restore,
# not a promise that no later request can mutate replay again.
_shared_shader_mutation_epoch = 0

# Event-scoped CBuffer snapshots own immutable captured bytes plus a deterministic
# reflected leaf allow-list.  Mutable override bytes are always reconstructed from
# that baseline; callers can never submit an unconstrained byte buffer.
_event_cbuffer_snapshots = {}
_event_cbuffer_snapshot_keys = {}
_event_cbuffer_released_snapshots = {}
_event_cbuffer_release_serial = 0
_event_cbuffer_capture_token = None


def _native_filesystem_path(path):
    """Return an absolute path usable by Win32 long-path-aware file APIs.

    qrenderdoc still embeds Python 3.6 on supported Windows builds.  Even when
    the machine enables long paths, that runtime can route ordinary absolute
    paths through the legacy MAX_PATH ABI.  Keep protocol/catalog paths in
    their normal form, but use the extended prefix for physical I/O.
    """
    absolute = os.path.abspath(path)
    if os.name != "nt" or absolute.startswith("\\\\?\\"):
        return absolute
    if absolute.startswith("\\\\"):
        return "\\\\?\\UNC\\" + absolute[2:]
    return "\\\\?\\" + absolute


def _atomic_write_bytes(path, data):
    """Write bytes with a same-directory atomic replace (Python 3.6 compatible)."""
    absolute_path = os.path.abspath(path)
    directory = os.path.dirname(absolute_path)
    native_directory = _native_filesystem_path(directory)
    if not os.path.exists(native_directory):
        os.makedirs(native_directory)
    tmp_path = "%s.tmp.%d.%d" % (
        absolute_path, os.getpid(), int(time.time() * 1000000))
    native_tmp_path = _native_filesystem_path(tmp_path)
    native_path = _native_filesystem_path(absolute_path)
    try:
        with open(native_tmp_path, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        for replace_attempt in range(5):
            try:
                os.replace(native_tmp_path, native_path)
                break
            except OSError as exc:
                # Discovery/mailbox readers can briefly hold a Win32 handle
                # without FILE_SHARE_DELETE. Retry only that replace, keeping
                # the old document intact and bounding GUI-thread waits to
                # 150 ms in total. Persistent or unrelated failures still fail.
                if (getattr(exc, "winerror", None) not in (5, 32, 33) or
                        replace_attempt == 4):
                    raise
                time.sleep(0.01 * (2 ** replace_attempt))
    finally:
        if os.path.exists(native_tmp_path):
            try:
                os.remove(native_tmp_path)
            except Exception:
                pass


def _ipc_json_bytes(value):
    """Return the exact bytes used by every JSON mailbox response."""
    # Do not sort: some legacy bridge responses contain a mixture of integer
    # and string keys, which Python 3.6 cannot compare while sorting.
    # Evidence is hashed again by AgentHost with strict JSON semantics.  Do not
    # let Python's non-standard NaN/Infinity spellings cross the IPC boundary
    # and turn a successful RenderDoc read into a later Host-admission failure.
    payload = json.dumps(
        value, ensure_ascii=True, indent=2, default=str, allow_nan=False)
    return payload.encode("utf-8")


def _frame_flow_result(value):
    if not isinstance(value, dict):
        return None
    result = value.get("result")
    if isinstance(result, dict) and result.get("schema") in FRAME_FLOW_RESULT_SCHEMAS:
        return result
    if value.get("schema") in FRAME_FLOW_RESULT_SCHEMAS:
        return value
    return None


def _atomic_write_json(path, value):
    """Write portable Unicode JSON atomically so readers never see a partial document.

    IPC documents are UTF-8, and escaping non-ASCII code points additionally
    keeps every byte on this Windows machine boundary ASCII. ``json.load``
    reconstructs the exact Unicode string, so Chinese capture paths survive
    even when a legacy intermediary accidentally applies an ANSI code page.
    """
    encoded = _ipc_json_bytes(value)
    if (_frame_flow_result(value) is not None and
            len(encoded) > MAX_FRAME_FLOW_SERIALIZED_BYTES):
        raise ValueError("Frame-flow IPC response exceeds the 8 MiB hard limit")
    _atomic_write_bytes(path, encoded)


def _read_ipc_request_json(path):
    """Read one bounded regular-file IPC request without following a symlink."""
    before = os.lstat(path)
    if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
        raise ValueError("IPC request must be a regular file")
    if before.st_size > MAX_IPC_REQUEST_BYTES:
        raise ValueError("IPC request exceeds the maximum size")

    flags = os.O_RDONLY
    if hasattr(os, "O_BINARY"):
        flags |= os.O_BINARY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW

    descriptor = os.open(path, flags)
    try:
        opened = os.fstat(descriptor)
        if (not stat.S_ISREG(opened.st_mode) or
                not os.path.samestat(before, opened)):
            raise ValueError("IPC request changed before it could be read")
        with os.fdopen(descriptor, "rb") as stream:
            descriptor = None
            encoded = stream.read(MAX_IPC_REQUEST_BYTES + 1)
    finally:
        if descriptor is not None:
            os.close(descriptor)

    if len(encoded) > MAX_IPC_REQUEST_BYTES:
        raise ValueError("IPC request exceeds the maximum size")
    try:
        text = encoded.decode("utf-8")
    except UnicodeDecodeError:
        raise ValueError("IPC request is not valid UTF-8")
    return json.loads(text)


def _shader_catalog_progress_binding(params):
    """Resolve an optional export-progress file only from a random token."""
    token = str(params.get("progress_token", "") or "").strip()
    session_id = str(
        params.get("progress_capture_session_id", "") or "").strip()
    if not token and not session_id:
        return None
    if (len(token) != 32 or
            any(character not in "0123456789abcdef" for character in token)):
        raise ValueError("progress_token must be 32 lowercase hexadecimal characters")
    if (len(session_id) != 32 or
            any(character not in "0123456789abcdef" for character in session_id)):
        raise ValueError(
            "progress_capture_session_id must be 32 lowercase hexadecimal characters")
    if session_id != _capture_session_id:
        raise RuntimeError("Capture session changed before Shader catalog export")
    instance_root = os.path.abspath(IPC_DIR)
    path = os.path.abspath(os.path.join(
        instance_root, "shader-catalog-progress-%s.json" % token))
    try:
        if os.path.commonpath((instance_root, path)) != instance_root:
            raise ValueError("Shader catalog progress path escapes the instance IPC root")
    except ValueError:
        raise ValueError("Shader catalog progress path escapes the instance IPC root")
    return {
        "token": token,
        "captureSessionId": session_id,
        "path": path,
        "lastPublishMonotonic": None,
    }


def _atomic_write_progress_json(path, value):
    """Atomically replace advisory progress without a durability fsync."""
    payload = json.dumps(
        value, ensure_ascii=False, separators=(",", ":"))
    encoded = payload.encode("utf-8")
    if len(encoded) > MAX_SHADER_CATALOG_PROGRESS_BYTES:
        return False
    directory = os.path.dirname(os.path.abspath(path))
    if not os.path.isdir(directory) or os.path.islink(directory):
        return False
    temporary = "%s.tmp.%d.%s" % (path, os.getpid(), uuid.uuid4().hex)
    try:
        with open(temporary, "xb") as stream:
            stream.write(encoded)
            stream.flush()
        os.replace(temporary, path)
        return True
    finally:
        if os.path.exists(temporary):
            try:
                os.remove(temporary)
            except Exception:
                pass


def _publish_shader_catalog_progress(binding, event_id, current, total):
    """Best-effort display telemetry which never changes export semantics."""
    if binding is None:
        return
    try:
        current_value = int(current)
        total_value = int(total)
        event_value = int(event_id)
        if (current_value < 1 or total_value < 1 or
                current_value > total_value or
                total_value > MAX_SHADER_CATALOG_PROGRESS_EVENTS or
                event_value < 0 or event_value > 0xFFFFFFFF):
            return
        job_id = str(binding.get("jobId", "") or "")
        if job_id:
            _update_shader_catalog_export_progress(
                job_id, event_value, current_value, total_value)
        # An asynchronous export job always tracks its latest progress in
        # memory. The optional sidecar remains available for legacy callers
        # and for Host telemetry, but is not required for GUI responsiveness.
        if not binding.get("path"):
            return
        now = time.monotonic()
        previous = binding.get("lastPublishMonotonic")
        if (current_value not in (1, total_value) and previous is not None and
                now - previous < SHADER_CATALOG_PROGRESS_INTERVAL_SECONDS):
            return
        path = binding["path"]
        if os.path.islink(path):
            return
        written = _atomic_write_progress_json(path, {
            "schema": SHADER_CATALOG_PROGRESS_SCHEMA,
            "schemaVersion": SHADER_CATALOG_PROGRESS_VERSION,
            "operationToken": binding["token"],
            "instanceId": INSTANCE_ID,
            "captureSessionId": binding["captureSessionId"],
            "phase": "export-shader-bindings",
            "eventId": event_value,
            "current": current_value,
            "total": total_value,
            "updatedUnixMs": int(time.time() * 1000),
        })
        if written:
            binding["lastPublishMonotonic"] = now
    except Exception:
        # Progress is display-only. Never alter catalog contents, identity, or
        # physical Shader/ABI gates because telemetry could not be published.
        pass


def _publish_instance_manifest(activity=False, stopped=False):
    """Publish bounded discovery state without capture/shader data or secrets."""
    global _instance_activity_unix_ms
    now_ms = int(time.time() * 1000)
    if activity:
        _instance_activity_unix_ms = now_ms
    loaded = False
    capture_path = ""
    try:
        loaded = bool(_ctx and _ctx.IsCaptureLoaded())
        if loaded:
            capture_path = str(_ctx.GetCaptureFilename() or "")
    except Exception:
        loaded = False
        capture_path = ""
    _atomic_write_json(INSTANCE_FILE, {
        "schema": "replaylab-bridge-instance/v1",
        "instanceId": INSTANCE_ID,
        "pid": os.getpid(),
        "protocolVersion": BRIDGE_PROTOCOL_VERSION,
        "bridgeVersion": BRIDGE_INTEGRATION_VERSION,
        "shaderRestoreBatchLimit": 16,
        "verifiedRestoreMappingCheck": True,
        "startedUnixMs": _instance_started_unix_ms,
        "lastActivityUnixMs": _instance_activity_unix_ms,
        "heartbeatUnixMs": now_ms,
        "captureLoaded": loaded,
        "captureSessionId": (
            str(_capture_session_id or "") if loaded else ""),
        # This path is local discovery metadata. It is never sent over the
        # unauthenticated HTTP health endpoint.
        "capturePath": capture_path,
        "stopped": bool(stopped),
    })


def _find_replaylab_host():
    """Locate only the packaged Python 3.10+ host; never use embedded 3.6."""
    candidates = []
    for env_name in ("BREAD_MCP_HOST", "REPLAYLAB_MCP_HOST"):
        configured = os.environ.get(env_name, "").strip()
        if configured:
            candidates.append(configured)
    host_names = (
        "BreadMCP.unicode.exe",
        "BreadMCP.exe",
    )
    if HAS_UI:
        try:
            app_dir = str(QtCore.QCoreApplication.applicationDirPath())
            for name in host_names:
                candidates.append(os.path.join(app_dir, "replaylab", name))
                candidates.append(os.path.join(app_dir, name))
        except Exception:
            pass
    integration_dir = os.path.dirname(os.path.abspath(__file__))
    # The installed package is fixed at
    # <application>/integrations/replaylab/python/renderdoc_mcp_bridge.  Derive
    # the application directory only as a fallback for non-Qt contract hosts;
    # qrenderdoc itself always contributes applicationDirPath() above.
    installed_app_dir = os.path.abspath(os.path.join(
        integration_dir, os.pardir, os.pardir, os.pardir, os.pardir))
    for name in host_names:
        candidates.append(os.path.join(installed_app_dir, "replaylab", name))
    for candidate in candidates:
        if os.path.isfile(candidate) and not os.path.islink(candidate):
            return os.path.abspath(candidate)
    return ""


def _external_mcp_autostart_enabled():
    """Return whether qrenderdoc should own the external-client loopback host.

    ReplayLabMCP is an external-client adapter, not an internal qrenderdoc
    dependency.  The external Codex/IDE service is enabled by default and keeps
    qrenderdoc's owner lifecycle; an installation that does not expose external
    clients can explicitly opt out without changing any internal Agent,
    project-restore, or Shader-save route.
    """

    value = os.environ.get("REPLAYLAB_EXTERNAL_MCP_AUTOSTART", "")
    return value.strip().lower() not in ("0", "false", "no", "off")


def _find_replaylab_internal_host():
    """Locate qrenderdoc's private high-level service executable only."""

    configured = os.environ.get("REPLAYLAB_INTERNAL_HOST", "").strip()
    candidates = []
    if configured:
        candidates.append(configured)
    if HAS_UI:
        try:
            app_dir = str(QtCore.QCoreApplication.applicationDirPath())
            candidates.extend([
                os.path.join(app_dir, "replaylab", "ReplayLabInternal.exe"),
                os.path.join(app_dir, "ReplayLabInternal.exe"),
            ])
        except Exception:
            pass
    integration_dir = os.path.dirname(os.path.abspath(__file__))
    installed_app_dir = os.path.abspath(os.path.join(
        integration_dir, os.pardir, os.pardir, os.pardir, os.pardir))
    candidates.append(os.path.join(
        installed_app_dir, "replaylab", "ReplayLabInternal.exe"))
    for candidate in candidates:
        if os.path.isfile(candidate) and not os.path.islink(candidate):
            return os.path.abspath(candidate)
    return ""


def _hidden_process_flags():
    if os.name != "nt":
        return 0
    return (getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000) |
            getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200))


def _track_replaylab_control_process(process, label, timeout_seconds=30.0):
    """Reap a short-lived ensure controller with a hard upper bound."""

    bounded_timeout = max(0.0, float(timeout_seconds))

    with _replaylab_control_processes_lock:
        _replaylab_control_processes[process] = str(label)

    def _reap():
        try:
            try:
                process.wait(timeout=bounded_timeout)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass
                try:
                    process.wait(timeout=2.0)
                except Exception:
                    pass
        finally:
            with _replaylab_control_processes_lock:
                _replaylab_control_processes.pop(process, None)

    thread = threading.Thread(
        target=_reap, name="ReplayLab-%s-control-reaper" % label)
    thread.daemon = True
    try:
        thread.start()
    except Exception:
        with _replaylab_control_processes_lock:
            _replaylab_control_processes.pop(process, None)
        try:
            process.kill()
            process.wait(timeout=1.0)
        except Exception:
            pass
        raise


def _drain_replaylab_control_processes(label, timeout_seconds=5.0):
    """Bound shutdown even if an ensure controller is waiting on a lock."""

    deadline = time.monotonic() + max(0.0, float(timeout_seconds))
    with _replaylab_control_processes_lock:
        processes = [
            process for process, process_label in
            _replaylab_control_processes.items()
            if process_label == str(label)
        ]
    for process in processes:
        remaining = deadline - time.monotonic()
        if remaining > 0:
            try:
                process.wait(timeout=remaining)
            except Exception:
                pass
        try:
            if process.poll() is None:
                process.kill()
                process.wait(timeout=1.0)
        except Exception:
            pass
        with _replaylab_control_processes_lock:
            _replaylab_control_processes.pop(process, None)


def _start_replaylab_host():
    """Ask the packaged singleton launcher to ensure the loopback host exists."""
    global _replaylab_host_executable, _replaylab_host_control_process
    global _replaylab_host_owner_active
    if _replaylab_host_owner_active:
        return True
    executable = _find_replaylab_host()
    _replaylab_host_executable = executable
    if not executable:
        print("[Bread] Packaged MCP host (BreadMCP.exe) not found; stdio clients may still "
              "launch a separately registered host")
        return False
    try:
        _replaylab_host_control_process = subprocess.Popen(
            [executable, "ensure", "--owner-pid", str(os.getpid())],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            cwd=os.path.dirname(executable),
            shell=False,
            creationflags=_hidden_process_flags())
        _track_replaylab_control_process(
            _replaylab_host_control_process, "mcp-ensure")
        _replaylab_host_owner_active = True
        print("[Bread] Starting/attaching packaged MCP host: %s" % executable)
        return True
    except Exception as exc:
        print("[Bread] Host startup error: %s" % str(exc))
        _replaylab_host_owner_active = False
        _replaylab_host_control_process = None
        return False


def _start_replaylab_internal_host(force=False):
    """Ensure qrenderdoc's private high-level service is running."""

    global _replaylab_internal_host_executable
    global _replaylab_internal_control_process
    global _replaylab_internal_owner_active
    if _replaylab_internal_owner_active and not force:
        return True
    if (force and _replaylab_internal_control_process is not None and
            _replaylab_internal_control_process.poll() is None):
        return True
    executable = _find_replaylab_internal_host()
    _replaylab_internal_host_executable = executable
    if not executable:
        print("[Bread] Packaged internal host (ReplayLabInternal.exe) not found; internal "
              "project and Shader Workspace services are unavailable")
        return False
    try:
        _replaylab_internal_control_process = subprocess.Popen(
            [executable, "ensure", "--owner-pid", str(os.getpid())],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            cwd=os.path.dirname(executable),
            shell=False,
            creationflags=_hidden_process_flags())
        _track_replaylab_control_process(
            _replaylab_internal_control_process, "internal-ensure",
            timeout_seconds=75.0)
        _replaylab_internal_owner_active = True
        print("[Bread] Starting/attaching private internal host: %s" %
              executable)
        return True
    except Exception as exc:
        print("[Bread] Internal host startup error: %s" % str(exc))
        _replaylab_internal_owner_active = False
        _replaylab_internal_control_process = None
        return False


def _ensure_internal_shader_service(params):
    """Restart only this application's fixed Host, independent of AI shell policy."""
    expected = _shader_override_hex(params.get('expected_capture_session_id'),
                                    'expected_capture_session_id', 32)
    if expected != _capture_session_id or not _request_capture_loaded():
        raise RuntimeError('Capture changed before internal Shader service recovery')
    if not _start_replaylab_internal_host(force=True):
        raise RuntimeError('The packaged internal Shader Host could not be started')
    return {'startupScheduled': True, 'captureSessionId': expected}


def _release_packaged_owner(executable, label):
    if not executable or not os.path.isfile(executable):
        return
    try:
        process = subprocess.Popen(
            [executable, "release", "--owner-pid", str(os.getpid())],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            cwd=os.path.dirname(executable),
            shell=False,
            creationflags=_hidden_process_flags())
        try:
            process.wait(timeout=3.0)
        except Exception:
            try:
                process.kill()
                process.wait(timeout=1.0)
            except Exception:
                pass
    except Exception as exc:
        print("[Bread] %s owner release error: %s" % (label, str(exc)))


def _release_replaylab_host_owner():
    """Release only this qrenderdoc PID; the last live owner stops the host."""
    global _replaylab_host_control_process
    global _replaylab_host_owner_active
    if not _replaylab_host_owner_active:
        return
    _replaylab_host_owner_active = False
    _drain_replaylab_control_processes("mcp-ensure")
    _release_packaged_owner(_replaylab_host_executable, "MCP host")
    _replaylab_host_control_process = None


def _release_replaylab_internal_host_owner():
    """Release qrenderdoc's private Host owner without touching MCP state."""

    global _replaylab_internal_control_process
    global _replaylab_internal_owner_active
    if not _replaylab_internal_owner_active:
        return
    _replaylab_internal_owner_active = False
    _drain_replaylab_control_processes("internal-ensure")
    _release_packaged_owner(
        _replaylab_internal_host_executable, "internal host")
    _replaylab_internal_control_process = None


# =====================================================================
# IPC Poller using QObject.startTimer (most reliable in RenderDoc)
# =====================================================================

def _lower_current_worker_priority_best_effort():
    """Let qrenderdoc's GUI/replay foreground work win CPU scheduling on Windows."""
    if os.name != "nt":
        return
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        get_current_thread = kernel32.GetCurrentThread
        get_current_thread.restype = ctypes.c_void_p
        set_thread_priority = kernel32.SetThreadPriority
        set_thread_priority.argtypes = [ctypes.c_void_p, ctypes.c_int]
        set_thread_priority.restype = ctypes.c_int
        # THREAD_PRIORITY_BELOW_NORMAL. Failure is deliberately best-effort:
        # older Wine builds and restricted hosts may not expose this API.
        set_thread_priority(get_current_thread(), -1)
    except Exception:
        pass

# These methods own qrenderdoc widgets or mutate CaptureContext collections whose
# viewer notifications must stay on Qt's GUI thread. The mailbox is still claimed
# and supervised by the worker; only the narrow UI transaction is marshalled back.
IPC_GUI_THREAD_METHODS = frozenset((
    "load_pass_classification",
    "close_pass_panel",
    "open_capture",
    "recover_replay",
    "begin_export_shader_catalog",
    "consume_export_shader_catalog",
    "begin_rdc_project_shader_resource_index",
    "poll_rdc_project_shader_resource_index",
    "commit_rdc_project_shader_resource_index",
))

if HAS_UI:
    class CaptureLifecycleViewer(qrd.CaptureViewer):
        """Invalidate capture-local symbol state even when the same file is reopened."""

        def __init__(self):
            super(CaptureLifecycleViewer, self).__init__()
            self._selected_event_id = None
            self._visible_event_id = None

        def _remember_current_events(self):
            try:
                if _ctx and _ctx.IsCaptureLoaded():
                    self._selected_event_id = _safe_int(
                        _ctx.CurSelectedEvent(), 0)
                    self._visible_event_id = _safe_int(_ctx.CurEvent(), 0)
                    return
            except Exception:
                pass
            self._selected_event_id = None
            self._visible_event_id = None

        def OnCaptureLoaded(self):
            global _active_capture_token
            if (_replay_recovery_path and _ctx.IsCaptureLoaded() and
                    _capture_path_key(_ctx.GetCaptureFilename()) == _replay_recovery_path):
                self._remember_current_events()
                return
            poller = globals().get("_poller")
            if poller:
                poller.cancel_active_for_user_activity(capture_changed=True)
            self._remember_current_events()
            _abandon_project_launcher_restore()
            if _material_panel_ui:
                _material_panel_ui.capture_changed()
            elif _material_panel_controller:
                _material_panel_controller.forget_all()
            if _pass_panel_ui:
                _pass_panel_ui.capture_changed()
            _reset_symbol_state(restore_names=False)
            _active_capture_token = _current_capture_token()
            _publish_instance_manifest(activity=True)
            _notify_shader_capture_changed(_shader_workspace_capture_binding())
            _publish_console_event(
                "capture", "info", "RenderDoc 捕获已加载",
                phase="捕获", code="captureLoaded")
            # The new symbol/session state and GUI binding must be visible
            # before the deferred timer starts project matching and restore.
            _schedule_project_auto_activation()
            _schedule_frame_render_flow_restore()

        def OnCaptureClosed(self):
            global _active_capture_token
            if _replay_recovery_path:
                return
            poller = globals().get("_poller")
            if poller:
                poller.cancel_active_for_user_activity(capture_changed=True)
            self._selected_event_id = None
            self._visible_event_id = None
            _abandon_project_launcher_restore()
            if _material_panel_ui:
                _material_panel_ui.capture_changed()
            elif _material_panel_controller:
                _material_panel_controller.forget_all()
            if _pass_panel_ui:
                _pass_panel_ui.capture_changed()
            _reset_symbol_state(restore_names=True)
            _active_capture_token = None
            _publish_instance_manifest(activity=True)
            _notify_shader_capture_changed(None)
            _cancel_project_auto_activation()
            _publish_console_event(
                "capture", "info", "RenderDoc 捕获已关闭",
                phase="捕获", code="captureClosed")

        def OnSelectedEventChanged(self, event_id):
            event_id = _safe_int(event_id, 0)
            changed = (
                self._selected_event_id is None or
                self._selected_event_id != event_id)
            self._selected_event_id = event_id
            poller = globals().get("_poller")
            if poller and changed and not _replay_recovery_path:
                poller.cancel_active_for_user_activity()
            _publish_instance_manifest(activity=True)

        def OnEventChanged(self, event_id):
            event_id = _safe_int(event_id, 0)
            changed = (
                self._visible_event_id is None or
                self._visible_event_id != event_id)
            self._visible_event_id = event_id
            poller = globals().get("_poller")
            if poller and changed and not _replay_recovery_path:
                poller.cancel_active_for_user_activity()
            _publish_instance_manifest(activity=True)


    class JsonPoller(QtCore.QObject):
        """Claim IPC files on Qt and execute non-UI tools on one bounded worker."""

        _WORKER_STOP = object()

        def __init__(self, handler_fn, parent=None):
            super(JsonPoller, self).__init__(parent)
            self._handler = handler_fn
            self._timer_id = 0
            self._last_manifest_ms = 0
            self._last_poll_monotonic = None
            self._request_queue = queue.Queue(MAX_IPC_BACKGROUND_REQUESTS)
            self._stop_event = threading.Event()
            self._active_guard = threading.RLock()
            self._active_item = None
            self._user_activity_generation = 0
            self._worker = None
            self._accepting = False

        def start(self):
            if not os.path.exists(IPC_DIR):
                os.makedirs(IPC_DIR)
            for directory in (REQUEST_DIR, RESPONSE_DIR, PROCESSING_DIR):
                if not os.path.exists(directory):
                    os.makedirs(directory)
            # Clean stale files
            for f in [REQ_FILE, RESP_FILE, READY_FILE]:
                if os.path.exists(f):
                    try:
                        os.remove(f)
                    except Exception:
                        pass
            # This mailbox is only the optional external-client adapter. Native
            # material/project controls do not queue requests here.
            self._stop_event.clear()
            self._accepting = True
            self._worker = threading.Thread(
                target=self._worker_main, name="ReplayLab-IPC-worker")
            self._worker.daemon = True
            self._worker.start()
            self._timer_id = self.startTimer(IPC_POLL_INTERVAL_MS)
            _publish_instance_manifest(activity=True)
            print("[Bread] Poller started (timer_id=%d, interval=%dms, dir=%s)" %
                  (self._timer_id, IPC_POLL_INTERVAL_MS, IPC_DIR))

        def stop(self):
            if self._timer_id:
                self.killTimer(self._timer_id)
                self._timer_id = 0
            self._accepting = False
            self._stop_event.set()
            with self._active_guard:
                active = self._active_item
            if active is not None:
                active["cancelEvent"].set()

            while True:
                try:
                    item = self._request_queue.get_nowait()
                except queue.Empty:
                    break
                if item is self._WORKER_STOP:
                    continue
                item["cancelEvent"].set()
                self._finish_item(
                    item, self._cancelled_response(
                        item["requestId"], "Bread IPC bridge is stopping"))

            try:
                self._request_queue.put_nowait(self._WORKER_STOP)
            except queue.Full:
                pass

            worker = self._worker
            if worker is not None:
                worker.join(IPC_WORKER_STOP_TIMEOUT_SECONDS)
                if worker.is_alive():
                    raise RuntimeError(
                        "Bread IPC worker did not stop before its deadline")
            self._worker = None
            print("[Bread] Poller stopped")

        def cancel_active_for_user_activity(self, capture_changed=False):
            """Invalidate queued work and signal the active tool for a real UI context change."""
            with self._active_guard:
                self._user_activity_generation += 1
                active = self._active_item
            if active is not None:
                if capture_changed:
                    active["captureInvalidatedEvent"].set()
                else:
                    active["selectionPreemptedEvent"].set()
                active["cancelEvent"].set()

        @staticmethod
        def _cancelled_response(request_id, message):
            return {
                "id": request_id,
                "error": {"code": -32010, "message": str(message)},
            }

        def _finish_item(self, item, response):
            published = False
            try:
                if item.get("stageTiming") is not None and isinstance(response, dict):
                    try:
                        timed_response = dict(response, bridgeTiming=_bridge_request_timing(item))
                        if (_frame_flow_result(timed_response) is None or
                                len(_ipc_json_bytes(timed_response)) <= MAX_FRAME_FLOW_SERIALIZED_BYTES):
                            response = timed_response
                    except Exception:
                        pass
                _atomic_write_json(item["responsePath"], response)
                published = True
            except Exception as exc:
                print("[Bread] Response write error: %s" % str(exc))
                traceback.print_exc()
                try:
                    _atomic_write_json(item["responsePath"], {
                        "id": item.get("requestId", "?"),
                        "error": {
                            "code": -1,
                            "message": "Bread could not persist the full response",
                        },
                    })
                    published = True
                except Exception as fallback_exc:
                    print("[Bread] Fallback response write error: %s" %
                          str(fallback_exc))
            finally:
                claim_path = item.get("claimPath")
                # A retained claim is the durable evidence that an operation may
                # already have committed. Never make a failed response publish
                # look like an unclaimed request that is safe to retry blindly.
                if published and claim_path:
                    try:
                        if os.path.lexists(claim_path):
                            os.remove(claim_path)
                    except Exception:
                        pass

        def _invoke_handler_on_ui(self, item):
            completed = threading.Event()
            response = [None]
            error = [None]
            phase_guard = threading.Lock()
            phase = ["pending"]
            timing = item.get("stageTiming")
            posted_at = time.monotonic() if timing is not None else None
            callback_started = [None]
            callback_finished = [None]
            callback_cpu_started = [None]
            callback_cpu_finished = [None]

            def _invoke():
                with phase_guard:
                    if phase[0] != "pending":
                        completed.set()
                        return
                    if item["cancelEvent"].is_set():
                        phase[0] = "cancelled"
                        completed.set()
                        return
                    phase[0] = "running"
                if timing is not None:
                    callback_started[0] = time.monotonic()
                    callback_cpu_started[0] = _bridge_thread_cpu_seconds()
                try:
                    response[0] = self._handler(item["request"])
                except BaseException as exc:
                    error[0] = exc
                finally:
                    if timing is not None:
                        callback_cpu_finished[0] = _bridge_thread_cpu_seconds()
                        callback_finished[0] = time.monotonic()
                    with phase_guard:
                        phase[0] = "done"
                    completed.set()

            # InvokeOntoUIThread belongs to IMiniQtHelper in qrenderdoc's
            # Python API. IExtensionManager exposes only GetMiniQtHelper(); a
            # direct call on Extensions() works in permissive test doubles but
            # fails in the real SWIG object.
            _ctx.Extensions().GetMiniQtHelper().InvokeOntoUIThread(_invoke)
            while not completed.wait(0.05):
                if item["cancelEvent"].is_set():
                    with phase_guard:
                        if phase[0] == "pending":
                            phase[0] = "cancelled"
                            completed.set()
            with phase_guard:
                final_phase = phase[0]
            if timing is not None:
                _record_bridge_ui_timing(timing, "uiHandler", posted_at,
                    callback_started[0], callback_finished[0],
                    callback_cpu_started[0], callback_cpu_finished[0], final_phase)
            if final_phase == "cancelled":
                return self._cancelled_response(
                    item["requestId"], _request_preemption_message(
                        item, "Bread IPC request was cancelled"))
            if error[0] is not None:
                raise error[0]
            return response[0]

        def _prepare_item_request(self, item):
            request = item.get("request")
            if request is None:
                request = _read_ipc_request_json(item["claimPath"])
                if not isinstance(request, dict):
                    raise ValueError("Request root must be an object")
                expected_id = item.get("expectedId")
                if (expected_id is not None and
                        str(request.get("id", "")) != expected_id):
                    return {
                        "id": expected_id,
                        "error": {
                            "code": -32600,
                            "message": "Request id does not match its mailbox filename",
                        },
                    }
                item["request"] = request
            item["selectionIndependent"] = _selection_independent_request(request)
            return None

        def _execute_item(self, item):
            invalid_request = self._prepare_item_request(item)
            if invalid_request is not None:
                return invalid_request
            request = item["request"]
            method = str(request.get("method", "") or "")
            if method in IPC_GUI_THREAD_METHODS:
                return self._invoke_handler_on_ui(item)

            previous = getattr(_request_dispatch_state, "current", None)
            _request_dispatch_state.current = {
                "backgroundReplayTag": item["replayTag"],
                "cancelEvent": item["cancelEvent"],
                "captureInvalidatedEvent": item["captureInvalidatedEvent"],
                "selectionPreemptedEvent": item["selectionPreemptedEvent"],
                "stopEvent": self._stop_event,
                "selectionIndependent": item["selectionIndependent"],
                "captureSnapshot": item["captureSnapshot"],
                "foregroundReplayGeneration": item["foregroundReplayGeneration"],
                "stageTiming": item.get("stageTiming"),
            }
            try:
                return self._handler(request)
            finally:
                if previous is None:
                    try:
                        del _request_dispatch_state.current
                    except AttributeError:
                        pass
                else:
                    _request_dispatch_state.current = previous

        def _worker_main(self):
            _lower_current_worker_priority_best_effort()
            while True:
                item = self._request_queue.get()
                if item is self._WORKER_STOP:
                    return
                with self._active_guard:
                    self._active_item = item
                timing = item.get("stageTiming")
                if timing is not None:
                    timing["workerStartedMonotonic"] = time.monotonic()
                    timing["workerStartedCpuSeconds"] = _bridge_thread_cpu_seconds()
                try:
                    with self._active_guard:
                        stale_activity = (
                            item["activityGeneration"] !=
                            self._user_activity_generation)
                    if self._stop_event.is_set():
                        response = self._cancelled_response(
                            item["requestId"], "Bread IPC bridge is stopping")
                    else:
                        invalid_request = self._prepare_item_request(item)
                        if invalid_request is not None:
                            response = invalid_request
                        elif (item["cancelEvent"].is_set() or stale_activity) and (
                                not item["selectionIndependent"] or
                                _request_dispatch_cancelled(item)):
                            response = self._cancelled_response(
                                item["requestId"],
                                _request_preemption_message(item,
                                    "Bread IPC request was superseded by user activity",
                                    selection_changed=stale_activity))
                        else:
                            response = self._execute_item(item)
                except BaseException as exc:
                    print("[Bread] Background request error: %s" % str(exc))
                    traceback.print_exc()
                    response = {
                        "id": item["requestId"],
                        "error": {"code": -1, "message": str(exc)},
                    }
                finally:
                    if timing is not None:
                        timing["workerFinishedCpuSeconds"] = _bridge_thread_cpu_seconds()
                        timing["workerFinishedMonotonic"] = time.monotonic()
                    with self._active_guard:
                        if self._active_item is item:
                            self._active_item = None
                self._finish_item(item, response)

        def _new_item(self, request_id, response_path, claim_path, request,
                      expected_id, poll_timing=None):
            # This method is called only by the Qt timer. Capture the small UI-owned
            # state here so the worker never needs to discover the user's selection.
            claim_started = time.monotonic()
            claim_cpu_started = _bridge_thread_cpu_seconds()
            claim_age_ms = None
            if claim_path:
                try:
                    claim_age_ms = max(0.0, (time.time() - os.stat(claim_path).st_mtime) * 1000.0)
                except OSError:
                    pass
            _synchronise_capture_lifecycle()
            try:
                capture_identity = _capture_identity_on_ui()
                capture_loaded = capture_identity.get("loaded") is True
                visible_event_id = _safe_int(_ctx.CurEvent(), 0) if capture_loaded else 0
                selected_event_id = (
                    _safe_int(_ctx.CurSelectedEvent(), visible_event_id)
                    if capture_loaded else 0)
                replay_manager = _ctx.Replay() if _ctx else None
            except Exception:
                capture_identity = None
                capture_loaded = False
                visible_event_id = 0
                selected_event_id = 0
                replay_manager = None
            with self._active_guard:
                activity_generation = self._user_activity_generation
            capture_token = _current_capture_token()
            foreground_generation = _foreground_replay_generation()
            claim_cpu_finished = _bridge_thread_cpu_seconds()
            return {
                "request": request,
                "expectedId": expected_id,
                "requestId": request_id,
                "responsePath": response_path,
                "claimPath": claim_path,
                "cancelEvent": threading.Event(),
                "captureInvalidatedEvent": threading.Event(),
                "selectionPreemptedEvent": threading.Event(),
                "stopEvent": self._stop_event,
                "replayTag": IPC_BACKGROUND_REPLAY_TAG_PREFIX + uuid.uuid4().hex,
                "activityGeneration": activity_generation,
                "foregroundReplayGeneration": foreground_generation,
                "stageTiming": {
                    "claimStartedMonotonic": claim_started,
                    "claimFinishedMonotonic": time.monotonic(),
                    "claimStartedCpuSeconds": claim_cpu_started,
                    "claimFinishedCpuSeconds": claim_cpu_finished,
                    "mailboxAgeAtClaimMs": claim_age_ms,
                    "pollGapMs": (poll_timing or {}).get("pollGapMs"),
                    "pendingRequestsAtPoll": (poll_timing or {}).get("pendingRequestsAtPoll"),
                    "manifestPublishWallMs": (poll_timing or {}).get("manifestPublishWallMs"),
                    "uiTransactions": [],
                    "replayTransactions": [],
                },
                "captureSnapshot": {
                    "captureLoaded": capture_loaded,
                    "captureSessionId": _capture_session_id,
                    "visibleEventId": visible_event_id,
                    "selectedEventId": selected_event_id,
                    "captureToken": capture_token,
                    "replayManager": replay_manager,
                    "captureIdentity": capture_identity,
                },
            }

        def _enqueue_item(self, item):
            request_id = item["requestId"]
            if not self._accepting or self._stop_event.is_set():
                self._finish_item(item, self._cancelled_response(
                    request_id, "Bread IPC bridge is not accepting requests"))
                return False
            try:
                self._request_queue.put_nowait(item)
            except queue.Full:
                self._finish_item(
                    item, self._cancelled_response(
                        request_id, "Bread IPC background queue is full"))
                return False
            return True

        def _submit_request(self, request, response_path, claim_path=None):
            request_id = str(request.get("id", "?") or "?")
            return self._enqueue_item(self._new_item(
                request_id, response_path, claim_path, request, None))

        def _submit_claimed_request(self, request_id, response_path, claim_path,
                                    expected_id=None, poll_timing=None):
            return self._enqueue_item(self._new_item(
                str(request_id or "?"), response_path, claim_path, None,
                expected_id, poll_timing))

        def timerEvent(self, event):
            """Called by Qt at the bounded IPC polling interval."""
            entered = time.monotonic()
            previous = self._last_poll_monotonic
            self._last_poll_monotonic = entered
            poll_timing = {
                # Python callback entry includes both Qt scheduling and GIL
                # acquisition. This is not a native Qt-only queue measurement.
                "pollGapMs": (round(max(0.0, entered - previous) * 1000.0, 3)
                              if previous is not None else None),
                "pendingRequestsAtPoll": 0,
                "manifestPublishWallMs": 0.0,
            }
            now_ms = int(time.time() * 1000)
            if now_ms - self._last_manifest_ms >= 1000:
                manifest_started = time.monotonic()
                _publish_instance_manifest()
                poll_timing["manifestPublishWallMs"] = round(
                    max(0.0, time.monotonic() - manifest_started) * 1000.0, 3)
                self._last_manifest_ms = now_ms
            # Protocol v2: each caller owns one UUID-named request/response pair. Claiming by
            # rename is atomic, so multiple RenderDoc processes can never execute one request.
            if self._process_queued_request(poll_timing):
                return

            # Protocol v1 is retained for older MCP clients.
            # Only read when the READY signal file exists
            if not os.path.exists(READY_FILE):
                return
            if not os.path.exists(REQ_FILE):
                return
            claim_path = None
            try:
                # Remove ready signal first
                os.remove(READY_FILE)
                claim_name = "legacy-request.json.claim.%d.%d" % (
                    os.getpid(), int(time.time() * 1000000))
                claim_path = os.path.join(PROCESSING_DIR, claim_name)
                os.replace(REQ_FILE, claim_path)
                self._submit_claimed_request(
                    "?", RESP_FILE, claim_path, poll_timing=poll_timing)
            except Exception as e:
                print("[Bread] Error: %s" % str(e))
                traceback.print_exc()
                try:
                    if os.path.lexists(REQ_FILE):
                        os.remove(REQ_FILE)
                    if claim_path and os.path.lexists(claim_path):
                        os.remove(claim_path)
                    _atomic_write_json(
                        RESP_FILE, {"error": {"code": -1, "message": str(e)}})
                except Exception:
                    pass

        def _process_queued_request(self, poll_timing=None):
            try:
                pending = []
                for name in os.listdir(REQUEST_DIR):
                    if not name.endswith(".json"):
                        continue
                    try:
                        info = os.stat(os.path.join(REQUEST_DIR, name))
                    except OSError:
                        # A different claimant/client may have removed it.
                        continue
                    if stat.S_ISREG(info.st_mode):
                        pending.append((info.st_mtime_ns, name))
                pending.sort()
            except Exception:
                return False
            if poll_timing is not None:
                poll_timing["pendingRequestsAtPoll"] = len(pending)
            if not pending:
                return False
            claimed = False
            # Mtime is caller publication order, unlike random UUID sorting.
            # A fixed attempt budget also bounds races/errors on the GUI thread.
            for unused_modified_ns, name in pending[:IPC_MAX_CLAIMS_PER_TICK]:
                if self._stop_event.is_set() or not self._accepting:
                    break
                request_path = os.path.join(REQUEST_DIR, name)
                claim_name = "%s.claim.%d.%d" % (
                    name, os.getpid(), int(time.time() * 1000000))
                claim_path = os.path.join(PROCESSING_DIR, claim_name)
                response_path = os.path.join(RESPONSE_DIR, name)
                try:
                    # Atomic rename gives exactly one owner, including races.
                    os.replace(request_path, claim_path)
                except (FileNotFoundError, PermissionError, OSError):
                    continue
                claimed = True
                expected_id = name[:-5]
                try:
                    self._submit_claimed_request(
                        expected_id, response_path, claim_path, expected_id,
                        poll_timing=poll_timing)
                except Exception as exc:
                    print("[Bread] Queued request error: %s" % str(exc))
                    traceback.print_exc()
                    self._finish_item({
                        "requestId": expected_id,
                        "responsePath": response_path,
                        "claimPath": claim_path,
                    }, {
                        "id": expected_id,
                        "error": {"code": -1, "message": str(exc)},
                    })
            return claimed


# =====================================================================
# Request handler — executes commands using pyrenderdoc
# =====================================================================

def _console_module_for_method(method):
    """Classify only a registered bridge method into a fixed console module."""
    value = str(method or "").lower()
    if "project" in value:
        return "project"
    if "shader" in value:
        return "shader"
    if "cbuffer" in value or "material" in value or "bound_texture" in value:
        return "material"
    if ("pass" in value or "frame" in value or "draw" in value or
            "counter" in value or "timing" in value):
        return "pass"
    if "capture" in value:
        return "capture"
    if ("texture" in value or "buffer" in value or "resource" in value or
            "pixel" in value or "vertex" in value or "pipeline" in value):
        return "replay"
    return "bridge"


CONSOLE_QUIET_REQUEST_METHODS = frozenset((
    # These methods are background liveness/context/status polls. Logging two
    # rows for every successful poll would evict useful user operations from
    # the bounded Console. Failures are still always published below.
    "ping",
    "get_capture_status",
    "get_current_renderdoc_context",
    "get_shared_shader_replacements",
    "get_shader_cbuffer_alias_identity",
    "get_shader_cbuffer_display_identity",
    "get_shader_workspace_ui_state",
    "get_application_ui_state",
    "capture_mesh_uv_evidence",
    "recover_shader_candidate_shared_resource_operation",
    "get_symbol_alias_transaction",
    "get_event_cbuffer_override_status",
    "poll_export_shader_catalog",
    "poll_rdc_project_shader_resource_index",
))

class _ReplayLabBackgroundPreempted(BaseException):
    """Control-flow signal that ordinary tool error recovery must not swallow."""
    pass


def _request_dispatch_context():
    return getattr(_request_dispatch_state, "current", None)


def _selection_independent_request(request):
    """Small capture identity/source observations do not depend on a UI EID."""
    if not isinstance(request, dict):
        return False
    method = request.get("method")
    if method == "get_current_renderdoc_context":
        # The request freezes its dispatch EID, not whichever EID is selected
        # later. Capture close/reload and explicit task cancellation still win.
        return True
    params = request.get("params") or {}
    if (method in ("inspect_event", "inspect_event_api_parameters",
                   "inspect_frame_render_stage", "get_draw_call_details",
                   "get_pipeline_state", "get_shader_info", "get_bound_textures",
                   "get_constant_buffer_values", "get_post_vs_data", "get_draw_geometry",
                   "get_cbuffer_navigation_target") and
            isinstance(params, dict) and _safe_int(params.get("event_id", 0), 0) > 0):
        return True
    return method in (
        "ping", "get_capture_status", "get_shader_workspace_ui_state", "read_shader_workspace_source",
        "get_frame_summary", "get_draw_calls", "get_pass_classification_inputs",
        "get_current_frame_flow_inputs",
        "get_application_ui_state", "control_application_ui", "open_document", "capture_mesh_uv_evidence",
        "get_shader_cbuffer_display_identity",
        "get_frame_render_flow_outline", "show_frame_render_flow", "resolve_shader_effect_presentation",
        "get_saved_frame_render_flow", "save_frame_render_flow",
        "show_shader_organization_preview",
    )


def _request_dispatch_cancelled(dispatch):
    """Separate selection preemption from capture invalidation and shutdown."""
    for name in ("stopEvent", "captureInvalidatedEvent"):
        event = dispatch.get(name)
        if event is not None and event.is_set():
            return True
    expected_session = str(dispatch.get("captureSnapshot", {}).get(
        "captureSessionId", "") or "")
    if expected_session and expected_session != str(_capture_session_id or ""):
        return True
    event = dispatch.get("cancelEvent")
    if event is None or not event.is_set():
        return False
    selected = dispatch.get("selectionPreemptedEvent")
    return not (dispatch.get("selectionIndependent") is True and expected_session and
                selected is not None and selected.is_set())


def _request_preemption_message(dispatch, fallback, selection_changed=False):
    """Only an observed EID change on the same capture is resumable."""
    if not isinstance(dispatch, dict):
        return fallback
    for name in ("stopEvent", "captureInvalidatedEvent"):
        event = dispatch.get(name)
        if event is not None and event.is_set():
            return fallback
    session = str(dispatch.get("captureSnapshot", {}).get("captureSessionId", "") or "")
    selected = dispatch.get("selectionPreemptedEvent")
    if (session and session == str(_capture_session_id or "") and
            (selection_changed or (selected is not None and selected.is_set()))):
        return "Bread background tool yielded after a user replay operation; retry it if still needed"
    return fallback


def _bridge_thread_cpu_seconds():
    """Measure this thread's CPU, including the bundled Python 3.6 on Windows."""
    try:
        clock = getattr(time, "thread_time", None)
        if clock is not None:
            return clock()
        if os.name == "nt":
            import ctypes
            kernel = ctypes.WinDLL("kernel32", use_last_error=True)
            kernel.GetCurrentThread.restype = ctypes.c_void_p
            kernel.GetThreadTimes.argtypes = [ctypes.c_void_p] + [ctypes.POINTER(ctypes.c_uint64)] * 4
            created, exited, system, user = [ctypes.c_uint64() for unused in range(4)]
            if kernel.GetThreadTimes(kernel.GetCurrentThread(), ctypes.byref(created),
                    ctypes.byref(exited), ctypes.byref(system), ctypes.byref(user)):
                return (system.value + user.value) / 10000000.0
    except Exception:
        pass
    return None


def _record_bridge_ui_timing(timing, callback_name, posted, started, finished,
                             cpu_started, cpu_finished, outcome):
    """Only fixed callback names and numeric durations enter protocol telemetry."""
    try:
        stages = timing["uiTransactions"]
        if len(stages) >= 16:
            return
        completed_at = finished if finished is not None else time.monotonic()
        began_at = started if started is not None else completed_at
        name = str(callback_name or "uiTransaction")
        if re.fullmatch(r"[A-Za-z0-9_]{1,64}", name) is None:
            name = "uiTransaction"
        stages.append({
            "callback": name, "outcome": outcome,
            "uiQueueWallMs": round(max(0.0, began_at - posted) * 1000.0, 3),
            "callbackWallMs": round(max(0.0, completed_at - began_at) * 1000.0, 3),
            "callbackThreadCpuMs": (round(max(0.0, cpu_finished - cpu_started) * 1000.0, 3)
                                    if cpu_started is not None and cpu_finished is not None else None),
        })
    except Exception:
        # Diagnostics cannot alter capture work, cancellation or publication.
        pass


def _record_bridge_replay_timing(timing, callback_name, posted, started, finished,
                                 cpu_started, cpu_finished, outcome):
    """Bounded replay scheduling/run timing; no source, arguments or results."""
    try:
        stages = timing.setdefault("replayTransactions", [])
        if len(stages) >= 16:
            return
        completed_at = finished if finished is not None else time.monotonic()
        began_at = started if started is not None else completed_at
        name = str(callback_name or "replayTransaction")
        if re.fullmatch(r"[A-Za-z0-9_]{1,64}", name) is None:
            name = "replayTransaction"
        stages.append({
            "callback": name, "outcome": outcome,
            "replayQueueAndGILWallMs": round(max(0.0, began_at - posted) * 1000.0, 3),
            "callbackWallMs": round(max(0.0, completed_at - began_at) * 1000.0, 3),
            "callbackThreadCpuMs": (round(max(0.0, cpu_finished - cpu_started) * 1000.0, 3)
                                    if cpu_started is not None and cpu_finished is not None else None),
        })
    except Exception:
        pass  # Telemetry must never affect replay or transaction restoration.


def _bridge_request_timing(item):
    timing = item["stageTiming"]
    claimed = timing["claimFinishedMonotonic"]
    started = timing.get("workerStartedMonotonic", claimed)
    finished = timing.get("workerFinishedMonotonic", started)
    claim_cpu_started = timing.get("claimStartedCpuSeconds")
    claim_cpu_finished = timing.get("claimFinishedCpuSeconds")
    worker_cpu_started = timing.get("workerStartedCpuSeconds")
    worker_cpu_finished = timing.get("workerFinishedCpuSeconds")
    return {
        "schema": "bread-bridge-request-timing/v1", "schemaVersion": 1,
        "mailboxAgeAtClaimMs": timing.get("mailboxAgeAtClaimMs"),
        "pollGapMs": timing.get("pollGapMs"),
        "pendingRequestsAtPoll": timing.get("pendingRequestsAtPoll"),
        "manifestPublishWallMs": timing.get("manifestPublishWallMs"),
        "claimSnapshotWallMs": round(max(0.0, claimed - timing["claimStartedMonotonic"]) * 1000.0, 3),
        "claimSnapshotThreadCpuMs": (round(max(0.0, claim_cpu_finished - claim_cpu_started) * 1000.0, 3)
                                    if claim_cpu_started is not None and claim_cpu_finished is not None else None),
        "workerQueueWallMs": round(max(0.0, started - claimed) * 1000.0, 3),
        "workerWallMs": round(max(0.0, finished - started) * 1000.0, 3),
        "workerThreadCpuMs": (round(max(0.0, worker_cpu_finished - worker_cpu_started) * 1000.0, 3)
                              if worker_cpu_started is not None and worker_cpu_finished is not None else None),
        "uiTransactions": list(timing["uiTransactions"]),
        "replayTransactions": list(timing.get("replayTransactions", [])),
    }


def _invoke_on_ui_sync(callback):
    """Run one short CaptureContext transaction on Qt while its worker waits."""
    dispatch = _request_dispatch_context()
    if dispatch is None:
        return callback()

    completed = threading.Event()
    result = [None]
    error = [None]
    phase_guard = threading.Lock()
    phase = ["pending"]
    request_tracker = _request_event_tracker()
    cancellation_allowed = not bool(
        request_tracker and request_tracker.get("replayAtomicCommitStarted"))
    timing = dispatch.get("stageTiming")
    posted_at = time.monotonic() if timing is not None else None
    callback_started = [None]
    callback_finished = [None]
    callback_cpu_started = [None]
    callback_cpu_finished = [None]

    def _invoke():
        with phase_guard:
            if phase[0] != "pending":
                completed.set()
                return
            if cancellation_allowed and _request_dispatch_cancelled(dispatch):
                phase[0] = "cancelled"
                completed.set()
                return
            phase[0] = "running"
        if timing is not None:
            callback_started[0] = time.monotonic()
            callback_cpu_started[0] = _bridge_thread_cpu_seconds()
        try:
            if _bridge_diagnostics is not None:
                _bridge_diagnostics.ui_event("ui-begin", (request_tracker or {}).get("method", ""),
                                             getattr(callback, "__name__", ""))
            result[0] = callback()
        except BaseException as exc:
            error[0] = exc
        finally:
            if _bridge_diagnostics is not None:
                _bridge_diagnostics.ui_event("ui-end", (request_tracker or {}).get("method", ""),
                                             getattr(callback, "__name__", ""),
                                             "error" if error[0] is not None else "ok")
            if timing is not None:
                callback_cpu_finished[0] = _bridge_thread_cpu_seconds()
                callback_finished[0] = time.monotonic()
            with phase_guard:
                phase[0] = "done"
            completed.set()

    # Keep this on the public Python binding shape used by qrenderdoc. The
    # ExtensionManager itself does not expose InvokeOntoUIThread.
    _ctx.Extensions().GetMiniQtHelper().InvokeOntoUIThread(_invoke)
    while not completed.wait(0.05):
        if cancellation_allowed and _request_dispatch_cancelled(dispatch):
            with phase_guard:
                if phase[0] == "pending":
                    phase[0] = "cancelled"
                    completed.set()
    with phase_guard:
        final_phase = phase[0]
    if timing is not None:
        _record_bridge_ui_timing(timing, getattr(callback, "__name__", "uiTransaction"),
            posted_at, callback_started[0], callback_finished[0],
            callback_cpu_started[0], callback_cpu_finished[0], final_phase)
    if final_phase == "cancelled":
        raise _ReplayLabBackgroundPreempted(
            _request_preemption_message(dispatch,
                "Bread background tool was cancelled before its UI transaction"))
    if error[0] is not None:
        raise error[0]
    return result[0]


def _request_event_tracker():
    return getattr(_request_event_state, "current", None)


def _request_visible_event_id(default=0):
    dispatch = _request_dispatch_context()
    if dispatch is not None:
        snapshot = dispatch.get("captureSnapshot", {})
        return _safe_int(snapshot.get("visibleEventId", default), default)
    try:
        return _safe_int(_ctx.CurEvent(), default)
    except Exception:
        return default


def _request_capture_loaded():
    """Return the UI-captured load state for a worker-dispatched request."""
    dispatch = _request_dispatch_context()
    if dispatch is not None:
        return bool(dispatch.get("captureSnapshot", {}).get("captureLoaded"))
    try:
        return bool(_ctx and _ctx.IsCaptureLoaded())
    except Exception:
        return False


def _request_capture_session_id():
    """Return the capture session frozen when this request was claimed."""
    dispatch = _request_dispatch_context()
    if dispatch is not None:
        return str(
            dispatch.get("captureSnapshot", {}).get("captureSessionId", "") or "")
    return str(_capture_session_id or "")


def _foreground_replay_manager():
    tracker = _request_event_tracker()
    if tracker is not None and tracker.get("replayManager") is not None:
        return tracker["replayManager"]
    dispatch = _request_dispatch_context()
    if dispatch is not None:
        replay = dispatch.get("captureSnapshot", {}).get("replayManager")
        if replay is not None:
            return replay
    return _ctx.Replay() if _ctx else None


def _replay_foreground_pending(replay):
    pending = getattr(replay, "HasPendingForegroundInvoke", None)
    return bool(pending is not None and pending())


def _replay_foreground_generation(replay):
    generation = getattr(replay, "GetForegroundInvokeGeneration", None)
    if generation is None:
        return None
    return int(generation())


def _foreground_replay_pending():
    return _replay_foreground_pending(_foreground_replay_manager())


def _foreground_replay_generation():
    return _replay_foreground_generation(_foreground_replay_manager())


def _background_replay_checkpoint():
    """End read-only AI work promptly when cancellation or user replay work appears."""
    tracker = _request_event_tracker()
    if tracker is None or not tracker.get("backgroundReplayTag"):
        return
    if (tracker.get("replayAtomicTransaction") or
            tracker.get("replayAtomicCommitStarted")):
        # Once a persistent replay mutation starts, finish its commit or its
        # rollback in this same callback. Foreground work is already queued to
        # run immediately afterwards and must not interrupt recovery midway.
        return
    cancel_event = tracker.get("cancelEvent")
    dispatch = tracker.get("dispatchContext") or _request_dispatch_context()
    independent = isinstance(dispatch, dict) and dispatch.get("selectionIndependent") is True
    if (cancel_event is not None and cancel_event.is_set() and
            (not independent or _request_dispatch_cancelled(dispatch))):
        tracker["backgroundAbandoned"] = True
        raise _ReplayLabBackgroundPreempted(
            _request_preemption_message(tracker.get("dispatchContext") or _request_dispatch_context(),
                "Bread background tool was cancelled"))
    if independent:
        # A short fixed-EID observation finishes on the serialized replay
        # callback. The user's queued foreground replay executes afterwards.
        return
    expected_generation = tracker.get("foregroundReplayGeneration")
    current_generation = _foreground_replay_generation()
    if (expected_generation is not None and current_generation is not None and
            current_generation != expected_generation):
        tracker["userPreempted"] = True
        tracker["backgroundAbandoned"] = True
        raise _ReplayLabBackgroundPreempted(
            "Bread background tool yielded after a user replay operation; retry it if still needed")
    if _foreground_replay_pending():
        # Do not restore the request's old visible EID. The queued foreground
        # command is now authoritative and will establish the user's new state.
        tracker["userPreempted"] = True
        tracker["backgroundAbandoned"] = True
        raise _ReplayLabBackgroundPreempted(
            "Bread background tool yielded to a user replay operation; retry it if still needed")


def _require_healthy_replay(ctrl):
    """A native fatal replay switches to DummyDriver; empty reads are not success."""
    getter = getattr(ctrl, "GetFatalErrorStatus", None)
    if callable(getter):
        status = getter()
        if status.code != rd.ResultCode.Succeeded:
            raise RuntimeError(
                "bread-replay-unavailable: native replay is in a fatal state (%s). "
                "Repeated EID selection cannot recover this controller. Preserve cached evidence; "
                "rebuild replay before requesting current bindings or new pixels." % str(status))


def _get_replay_health(params):
    """Read native status without selecting an event or requesting GPU work."""
    def read(ctrl):
        status = ctrl.GetFatalErrorStatus()
        return {"schema": "bread-replay-health/v1", "captureSessionId": _capture_session_id,
                "healthy": status.code == rd.ResultCode.Succeeded,
                "code": str(status.code), "diagnostic": str(status),
                "recovery": "none" if status.code == rd.ResultCode.Succeeded else "recreate-controller"}
    return _replay(read)


def _set_frame_event(ctrl, event_id, force=True, allow_background_preemption=True):
    """Set one replay EID and record the mutation for this synchronous request."""

    if allow_background_preemption:
        _background_replay_checkpoint()
    _require_healthy_replay(ctrl)
    tracker = _request_event_tracker()
    if tracker is not None:
        tracker["mutated"] = True
        tracker["lastEventId"] = _safe_int(event_id, 0)
        tracker["lastSetSucceeded"] = False
        tracker["eventDirty"] = True
    ctrl.SetFrameEvent(event_id, force)
    _require_healthy_replay(ctrl)
    if tracker is not None:
        tracker["lastSetSucceeded"] = True
        tracker["eventDirty"] = (
            tracker["lastEventId"] != tracker["visibleEventId"])


def _restore_visible_replay_event(event_id=None):
    if not _ctx or not _ctx.IsCaptureLoaded():
        return
    if event_id is None:
        event_id = _safe_int(_ctx.CurEvent(), 0)
    _replay(lambda ctrl: _set_frame_event(
        ctrl, event_id, True, allow_background_preemption=False))


_read_pipeline_capability = None


def _select_event_for_read(ctrl, event_id):
    """Use native current-pipeline reuse only when that core advertises it.

    Older cores retain their forced-query behavior, including after analysis
    that restored pixels without fetching pipeline metadata.
    """
    global _read_pipeline_capability
    key = str(_capture_session_id or "")
    if _read_pipeline_capability is None or _read_pipeline_capability[0] != key:
        supported = False
        try:
            status = json.loads(str(ctrl.GetReplayCheckpointStatus()))
            supported = status.get("pipelineStateReuse") is True
        except Exception:
            pass
        _read_pipeline_capability = (key, supported)
    _set_frame_event(ctrl, int(event_id), not _read_pipeline_capability[1])


def _console_request_lifecycle_visible(method):
    return str(method or "") not in CONSOLE_QUIET_REQUEST_METHODS


def _publish_console_event(module, severity, message, phase="", code="",
                           context=None):
    """Best-effort fixed-program publisher; logging can never break replay."""
    try:
        _shader_console_protocol.publish_console_event(
            module, severity, message, phase=phase, code=code,
            context=context, process_role="qrenderdoc")
    except Exception:
        pass


def _publish_current_context_freeze_console_event(job):
    """Publish one bounded non-authoritative terminal diagnostic per job."""
    if job.get("consoleEventPublished"):
        return
    status = str(job.get("status", "") or "")
    if status not in ("completed", "failed", "abandoned"):
        return
    job["consoleEventPublished"] = True
    if status == "completed":
        # The AI panel freezes the current context routinely (every refresh, every
        # task). A completed freeze is not news; forty of them an hour buried the
        # messages that were. Failures and abandonments still publish.
        return
    failure_code = str(job.get("failureCode", "") or "")
    if failure_code not in CURRENT_CONTEXT_FREEZE_FAILURE_CODES:
        failure_code = "unknown"
    context = {
        "operation": "currentContextFreeze",
        "jobId": str(job.get("jobId", "") or "")[:64],
        "captureSessionId": str(job.get("captureSessionId", "") or "")[:64],
        "eventId": _safe_int(job.get("currentEventId", 0), 0),
    }
    if status != "completed":
        context["failureCode"] = failure_code
        diagnostic = str(job.get("error", "") or "")[:1024]
        if diagnostic:
            # Diagnostics are bounded observation text only. They are never a
            # stable code, authority field, tool input, or recovery decision.
            context["diagnostics"] = diagnostic
    code = {
        "completed": "currentContextFreezeCompleted",
        "failed": "currentContextFreezeFailed",
        "abandoned": "currentContextFreezeAbandoned",
    }[status]
    _publish_console_event(
        "bridge", "info" if status == "completed" else "error",
        _current_context_freeze_console_message(status), phase="AI",
        code=code, context=context)
    if status != "completed" and callable(_learning_observation_writer):
        try:
            job_id = context["jobId"]
            _learning_observation_writer(
                source_version=BRIDGE_INTEGRATION_VERSION,
                component="qrenderdoc",
                phase="context-freeze",
                exception_type=failure_code,
                message=context.get("diagnostics") or failure_code,
                source="bridge",
                task_id=(job_id if re.fullmatch(
                    r"[0-9a-f]{32}", job_id) is not None else ""),
                terminal_status="failed",
                capture_session_id=context["captureSessionId"],
                event_id=context["eventId"],
            )
        except Exception:
            # Learning is evidence for a later AgentHost startup. It cannot
            # participate in, authorize, or fail this terminal snapshot path.
            pass

def handle_request(request):
    """Route a request to the appropriate handler function."""
    dispatch = _request_dispatch_context()
    if dispatch is None:
        _synchronise_capture_lifecycle()
    rid = request.get("id", "?")
    method = request.get("method", "")
    params = request.get("params", {})

    if method not in METHODS:
        _publish_console_event(
            "bridge", "error", "未知请求：%s" % str(method),
            phase="请求失败", code="requestRejected",
            context={"operation": str(method or "")})
        return {"id": rid, "error": {"code": -32601, "message": "Unknown method: %s" % method}}

    module = _console_module_for_method(method)
    lifecycle_visible = _console_request_lifecycle_visible(method)
    if lifecycle_visible:
        _publish_console_event(
            module, "info", "正在执行 %s" % method, phase="请求开始",
            code="requestStarted", context={"operation": method})
    previous_tracker = _request_event_tracker()
    if dispatch is not None:
        capture_snapshot = dispatch.get("captureSnapshot", {})
        visible_event_id = _safe_int(
            capture_snapshot.get("visibleEventId", 0), 0)
    else:
        visible_event_id = _safe_int(_ctx.CurEvent(), 0) if (
            _ctx and _ctx.IsCaptureLoaded()) else 0
    tracker = {
        "requestId": rid,
        "method": method,
        "captureSessionId": (
            str(capture_snapshot.get("captureSessionId", "") or "")
            if dispatch is not None else _capture_session_id),
        "visibleEventId": visible_event_id,
        "lastEventId": visible_event_id,
        "lastSetSucceeded": True,
        "mutated": False,
        "backgroundReplayTag": (
            str(dispatch.get("backgroundReplayTag", "") or "")
            if dispatch is not None else ""),
        "cancelEvent": (
            dispatch.get("cancelEvent") if dispatch is not None else None),
        "dispatchContext": dispatch,
        "foregroundReplayGeneration": (
            dispatch.get("foregroundReplayGeneration")
            if dispatch is not None else None),
        "userPreempted": False,
        "backgroundAbandoned": False,
        "eventDirty": False,
        "replayAtomicTransaction": False,
        "replayAtomicCommitStarted": False,
    }
    _request_event_state.current = tracker
    try:
        if (dispatch is not None and
                str(capture_snapshot.get("captureSessionId", "") or "") !=
                str(_capture_session_id or "")):
            raise RuntimeError(
                "The RenderDoc capture changed before the background tool started")
        expected_session = str(
            params.get("__replaylab_expected_capture_session_id", "") or "").lower()
        if expected_session and expected_session != _capture_session_id:
            raise RuntimeError(
                "The frozen capture session changed before the Bread tool started")
        result = METHODS[method](params)
        if tracker["eventDirty"]:
            raise RuntimeError(
                "Bread replay callback returned without restoring the user's event")
        response = {"id": rid, "result": result}
        if (_frame_flow_result(response) is not None and
                len(_ipc_json_bytes(response)) >
                MAX_FRAME_FLOW_SERIALIZED_BYTES):
            raise RuntimeError(
                "Frame-flow IPC response exceeds the 8 MiB hard limit")
        if lifecycle_visible:
            _publish_console_event(
                module, "info", "%s 已完成" % method, phase="请求完成",
                code="requestSucceeded", context={"operation": method})
        return response
    except _ReplayLabBackgroundPreempted as e:
        return {"id": rid, "error": {"code": -32010, "message": str(e)}}
    except Exception as e:
        traceback.print_exc()
        _publish_console_event(
            module, "error", "%s 失败：%s" % (method, str(e)), phase="请求失败",
            code="requestFailed", context={"operation": method})
        return {"id": rid, "error": {"code": -32000, "message": str(e)}}
    finally:
        if previous_tracker is None:
            try:
                del _request_event_state.current
            except AttributeError:
                pass
        else:
            _request_event_state.current = previous_tracker


# ---- Helper: run on replay thread ----
def _begin_replay_atomic_transaction():
    """Finish commit/recovery phases once the first persistent setter is reached."""
    tracker = _request_event_tracker()
    if tracker is not None:
        tracker["replayAtomicTransaction"] = True
        # Shared Shader operations bridge replay and GUI ownership registries.
        # Keep later recovery callbacks non-preemptible until this request has
        # fully committed or restored both sides.
        tracker["replayAtomicCommitStarted"] = True


def _replay(fn):
    """Execute fn(controller) on the replay thread, return result."""
    result = [None]
    error = [None]
    request_tracker = _request_event_tracker()
    dispatch = _request_dispatch_context()
    timing = dispatch.get("stageTiming") if dispatch is not None else None
    posted_at = time.monotonic() if timing is not None else None
    callback_started = [None]
    callback_finished = [None]
    callback_cpu_started = [None]
    callback_cpu_finished = [None]
    invocation_failed = [False]

    def _invoke(ctrl):
        if timing is not None:
            # Entry includes replay-queue scheduling and Python GIL acquisition;
            # this does not claim to measure the native queue in isolation.
            callback_started[0] = time.monotonic()
            callback_cpu_started[0] = _bridge_thread_cpu_seconds()
        previous_tracker = _request_event_tracker()
        had_atomic_state = False
        previous_atomic_state = False
        if request_tracker is not None:
            _request_event_state.current = request_tracker
            had_atomic_state = "replayAtomicTransaction" in request_tracker
            previous_atomic_state = bool(
                request_tracker.get("replayAtomicTransaction"))
            request_tracker["replayAtomicTransaction"] = False
        try:
            _background_replay_checkpoint()
            result[0] = fn(ctrl)
            # Reaching this point is the atomic completion boundary. A callback
            # may have committed a shader/CBuffer mutation, so a foreground
            # enqueue that happened *during* fn must run next without turning
            # the already committed response into a retryable cancellation.
            # Long read-only traversals checkpoint inside their own loops.
        except _ReplayLabBackgroundPreempted as e:
            error[0] = e
        except BaseException as e:
            error[0] = e
        finally:
            if request_tracker is not None and request_tracker.get("eventDirty"):
                restore_event = _safe_int(
                    request_tracker.get("visibleEventId", 0), 0)
                try:
                    # Restore inside this same replay callback. Foreground work
                    # cannot interleave between the AI's temporary EID and this
                    # restore, so the next queued user callback sees its own state.
                    ctrl.SetFrameEvent(restore_event, True)
                    _require_healthy_replay(ctrl)
                    request_tracker["lastEventId"] = restore_event
                    request_tracker["lastSetSucceeded"] = True
                    request_tracker["eventDirty"] = False
                except Exception as restore_error:
                    request_tracker["lastSetSucceeded"] = False
                    original_error = error[0]
                    error[0] = RuntimeError(
                        "Bread could not restore the user's replay event: %s%s" %
                        (str(restore_error),
                         "; original operation: %s" % str(original_error)
                         if original_error is not None else ""))
                    error[0].__cause__ = restore_error
            if request_tracker is not None:
                if had_atomic_state:
                    request_tracker["replayAtomicTransaction"] = (
                        previous_atomic_state)
                else:
                    request_tracker.pop("replayAtomicTransaction", None)
            if previous_tracker is None:
                try:
                    del _request_event_state.current
                except AttributeError:
                    pass
            else:
                _request_event_state.current = previous_tracker
            if timing is not None:
                callback_cpu_finished[0] = _bridge_thread_cpu_seconds()
                callback_finished[0] = time.monotonic()

    replay = _foreground_replay_manager()
    if replay is None:
        raise RuntimeError("RenderDoc replay manager is unavailable")
    had_replay_manager = False
    previous_replay_manager = None
    if request_tracker is not None:
        had_replay_manager = "replayManager" in request_tracker
        previous_replay_manager = request_tracker.get("replayManager")
        request_tracker["replayManager"] = replay
    background_tag = str(
        request_tracker.get("backgroundReplayTag", "") or ""
    ) if request_tracker is not None else ""
    tagged_block = getattr(replay, "BlockInvokeTagged", None)
    try:
        if background_tag:
            if tagged_block is None:
                raise RuntimeError(
                    "This qrenderdoc build does not support background Bread replay requests")
            tagged_block(background_tag, _invoke)
        else:
            replay.BlockInvoke(_invoke)
        # Native calls are not all sliceable from Python. Catch foreground work
        # that arrived during one such read after the callback has restored its
        # temporary EID, before publishing a stale result. A persistent setter
        # marks replayAtomicCommitStarted first, making this checkpoint a no-op
        # so a committed mutation and its recovery keep their exact outcome.
        if error[0] is None:
            _background_replay_checkpoint()
    except BaseException:
        invocation_failed[0] = True
        raise
    finally:
        if timing is not None:
            _record_bridge_replay_timing(timing, getattr(fn, "__name__", "replayTransaction"),
                posted_at, callback_started[0], callback_finished[0],
                callback_cpu_started[0], callback_cpu_finished[0],
                "failed" if invocation_failed[0] or error[0] is not None else "completed")
        if request_tracker is not None:
            if had_replay_manager:
                request_tracker["replayManager"] = previous_replay_manager
            else:
                request_tracker.pop("replayManager", None)
    if error[0]:
        raise error[0]
    return result[0]


def _notify_shader_replay_changed():
    """Wake capture viewers after a committed render-output mutation.

    The historical name is kept for bridge compatibility. Shader, CBuffer, and resource edits all
    invalidate persistent event-texture snapshots, so each successful mutation must send the same
    viewer refresh hint after the replay transaction commits.
    """
    if getattr(_request_dispatch_state, 'defer_shader_notifications', False):
        return
    try:
        _invoke_on_ui_sync(lambda: _ctx.RefreshStatus())
    except BaseException:
        # The replay generation remains authoritative. This hint is best-effort
        # during user preemption or capture/application teardown, and a missed
        # hint must not make an already committed mutation look retryable.
        pass


def _safe_int(value, default=0):
    try:
        return int(value)
    except Exception:
        return default


def _resource_id_int(value):
    """Convert the several ResourceId/descriptor shapes exposed by RenderDoc to int."""
    if value is None:
        return 0
    try:
        return int(value)
    except Exception:
        pass
    for attr in ("resource", "resourceId", "id"):
        try:
            nested = getattr(value, attr)
            return int(nested)
        except Exception:
            pass
    return 0


def _resource_id_lookup(resources, wanted_id):
    """Return RenderDoc's real ResourceId object instead of fabricating one via `.id`."""
    wanted_id = _safe_int(wanted_id, 0)
    if wanted_id <= 0:
        return None
    for resource in resources or []:
        candidate = getattr(resource, "resourceId", resource)
        if _resource_id_int(candidate) == wanted_id:
            return candidate
    return None


def _resolve_resource_id(ctrl, wanted_id, resource_kind=None):
    """Resolve an integer ID to an existing RenderDoc-owned ``ResourceId`` object.

    ``ResourceId.id`` is read-only in the Python bindings. Constructing an empty ID and assigning
    to it may appear to work in mocks while failing in qrenderdoc, so every bridge operation that
    accepts an integer must resolve the object from the replay controller instead.
    """
    wanted_id = _safe_int(wanted_id, 0)
    if wanted_id <= 0:
        label = resource_kind or "resource"
        raise ValueError("Invalid %s resource ID: %s" % (label, str(wanted_id)))

    kind = str(resource_kind or "").strip().lower()
    if kind == "texture":
        getter_names = ("GetTextures",)
    elif kind == "buffer":
        getter_names = ("GetBuffers",)
    elif kind:
        raise ValueError("Unknown resource kind: %s" % resource_kind)
    else:
        getter_names = ("GetResources", "GetTextures", "GetBuffers")

    for getter_name in getter_names:
        getter = getattr(ctrl, getter_name, None)
        if not callable(getter):
            continue
        try:
            resolved = _resource_id_lookup(getter(), wanted_id)
        except Exception:
            resolved = None
        if resolved is not None:
            return resolved

    label = (kind + " ") if kind else ""
    raise ValueError("Unknown %sresource ID: %d" % (label, wanted_id))


def _context_resource_ids():
    if not _ctx or not hasattr(_ctx, "GetResources"):
        return {}
    try:
        return {
            _resource_id_int(getattr(resource, "resourceId", None)):
            getattr(resource, "resourceId", None)
            for resource in _ctx.GetResources()
            if _resource_id_int(getattr(resource, "resourceId", None)) > 0
        }
    except Exception:
        return {}


def _current_capture_token():
    dispatch = _request_dispatch_context()
    if dispatch is not None:
        return dispatch.get("captureSnapshot", {}).get("captureToken")
    if not _ctx:
        return None
    try:
        if not _ctx.IsCaptureLoaded():
            return None
    except Exception:
        return None
    try:
        path = str(_ctx.GetCaptureFilename() or "")
    except Exception:
        path = ""
    if path:
        path = os.path.normcase(os.path.abspath(path))
    return ("loaded", path)


def _forget_event_shader_overrides():
    """Forget capture-local target IDs without touching the current controller.

    This path is used after RenderDoc has switched/closed a capture, where the
    old replay controller and its target ResourceIds are already invalid.
    """
    global _event_shader_overrides, _event_shader_targets
    global _event_shader_override_capture_token
    global _event_shader_rollback_tombstones
    global _event_shader_rollback_tombstone_order
    _event_shader_overrides = {}
    _event_shader_targets = {}
    _event_shader_override_capture_token = None
    _event_shader_rollback_tombstones = {}
    _event_shader_rollback_tombstone_order = []


def _release_event_shader_overrides():
    """Best-effort rollback/free while the owning replay controller is alive."""
    global _event_shader_overrides, _event_shader_targets
    global _event_shader_override_capture_token
    records = list(_event_shader_overrides.values())
    targets = list(_event_shader_targets.values())
    owner_token = _event_shader_override_capture_token
    if not records and not targets:
        _forget_event_shader_overrides()
        return
    if owner_token != _current_capture_token():
        _forget_event_shader_overrides()
        return

    def _do(ctrl):
        if records:
            _begin_replay_atomic_transaction()
        for record in records:
            try:
                ctrl.ClearEventShaderOverride(
                    int(record["eventId"]), record["stageObject"])
            except Exception:
                pass
        # A family target can be referenced by many event-scoped overrides.
        # Free each target exactly once, and never pass a captured/original
        # shader ResourceId to FreeTargetResource.
        for target in targets:
            try:
                ctrl.FreeTargetResource(target["targetResource"])
            except Exception:
                _register_orphan_shader_target(target["targetResource"])

    try:
        _replay(_do)
    except Exception:
        pass
    _forget_event_shader_overrides()


def _advance_shared_shader_mutation_epoch():
    global _shared_shader_mutation_epoch
    _shared_shader_mutation_epoch += 1
    globals().get("_event_texture_raw_cache", {}).clear()
    return _shared_shader_mutation_epoch


def _register_orphan_shader_target(target):
    """Queue a built target the caller could not free for the Host orphan sweep.

    A target that is still bound by a live replacement (for example after a
    failed restore) cannot be freed immediately without risking live replay,
    but it must not leak for the capture's lifetime either. ``release_replay
    _transient_caches`` frees every queued orphan once the binding clears, so
    routing unfreeable targets here keeps qrenderdoc memory bounded across many
    validation calls.

    Build admission enforces the normal hard bound. If a target already
    exists (for example from an in-flight or older caller), preserving its
    cleanup ID takes precedence over truncating the queue.
    """
    global _shared_shader_orphan_targets
    if target is None:
        return False
    if target in _shared_shader_orphan_targets:
        return False
    _shared_shader_orphan_targets.append(target)
    return True


def _require_shader_target_build_capacity(required_targets=1):
    """Fail before native allocation when orphan cleanup has no safe room."""
    required = int(required_targets or 0)
    if required <= 0:
        return
    remaining = max(
        0, int(MAX_SHARED_SHADER_ORPHAN_TARGETS) -
        len(_shared_shader_orphan_targets))
    if required > remaining:
        raise RuntimeError(
            "The active capture reached the %d orphan Shader target limit; "
            "retry transient replay cleanup or close the capture before "
            "building another target" % MAX_SHARED_SHADER_ORPHAN_TARGETS)


def _build_target_shader(ctrl, entry_point, encoding, candidate_bytes,
                         compile_flags, stage):
    """The single admission gate for every bridge-created target Shader."""
    _require_healthy_replay(ctrl)
    _require_shader_target_build_capacity(1)
    result = ctrl.BuildTargetShader(
        entry_point, encoding, candidate_bytes, compile_flags, stage)
    _require_healthy_replay(ctrl)
    return result


def _forget_shared_shader_replacements():
    """Forget resource-scoped target IDs after their replay has disappeared."""
    global _shared_shader_replacements, _shared_shader_orphan_targets
    global _shared_shader_replacement_capture_token
    global _shared_shader_rollback_tombstones
    global _shared_shader_rollback_tombstone_order
    global _shared_shader_operation_outcomes
    global _shared_shader_operation_outcome_order
    global _shared_shader_manual_target_cache
    had_active_replacement = bool(_shared_shader_replacements)
    _shared_shader_replacements = {}
    _shared_shader_orphan_targets = []
    _shared_shader_manual_target_cache = []
    _shared_shader_replacement_capture_token = None
    _shared_shader_rollback_tombstones = {}
    _shared_shader_rollback_tombstone_order = []
    _shared_shader_operation_outcomes = {}
    _shared_shader_operation_outcome_order = []
    if had_active_replacement:
        _advance_shared_shader_mutation_epoch()


def _remember_shared_shader_operation(record, operation_id, created):
    """Publish bounded write-ahead evidence for one shared-resource apply."""
    global _shared_shader_operation_outcomes
    global _shared_shader_operation_outcome_order

    token = _shader_override_hex(operation_id, "operation_id", 32)
    outcome = {
        "operationId": token,
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "captureToken": record["captureToken"],
        "workspaceId": record["workspaceId"],
        "replacementId": record["replacementId"],
        "originalResourceId": record["expectedOriginalResourceId"],
        "candidateRawSha256": record["candidateRawSha256"],
        "createdReplacement": bool(created),
        "state": "committed" if created else "idempotent-noop",
    }
    if token in _shared_shader_operation_outcomes:
        _shared_shader_operation_outcome_order = [
            value for value in _shared_shader_operation_outcome_order
            if value != token]
    _shared_shader_operation_outcomes[token] = outcome
    _shared_shader_operation_outcome_order.append(token)
    while (len(_shared_shader_operation_outcome_order) >
           MAX_SHARED_SHADER_OPERATION_OUTCOMES):
        oldest = _shared_shader_operation_outcome_order.pop(0)
        _shared_shader_operation_outcomes.pop(oldest, None)
    return outcome


def _shared_shader_ui_owner(original_resource):
    """Return the UI replacement target, failing closed on an old API."""
    def _read():
        is_replaced = getattr(_ctx, "IsResourceReplaced", None)
        get_replacement = getattr(_ctx, "GetResourceReplacement", None)
        if not callable(is_replaced) or not callable(get_replacement):
            raise RuntimeError(
                "This qrenderdoc context does not expose replacement ownership queries")
        if not bool(is_replaced(original_resource)):
            return None
        target = get_replacement(original_resource)
        if _resource_id_int(target) <= 0:
            raise RuntimeError("qrenderdoc reported an invalid replacement owner")
        return target

    return _invoke_on_ui_sync(_read)


def _require_shared_shader_ui_owner(original_resource, owned_record):
    """Reject foreign/changed replacements instead of overwriting user state."""
    current = _shared_shader_ui_owner(original_resource)
    if owned_record is None:
        if current is not None:
            raise RuntimeError(
                "The captured Shader already has a foreign RenderDoc replacement")
        return
    if (current is None or
            _resource_id_int(current) != owned_record.get("targetResourceId")):
        raise RuntimeError(
            "The captured Shader replacement is no longer owned by this bridge")


def _set_shared_shader_ui_owner(original_resource, target_resource, replace_direct=False):
    """Set and then prove one CaptureContext replacement owner.

    RegisterReplacement is outside the replay thread and is therefore the only
    non-atomic edge of a shared Shader apply.  Never infer that a Python call
    which returned (or raised) updated both of CaptureContext's forward/reverse
    maps: query the public owner API after the operation and fail closed.
    """
    def _set_and_verify():
        expected_id = (
            _resource_id_int(target_resource)
            if target_resource is not None else 0)
        current = _shared_shader_ui_owner(original_resource)
        if ((current is None and expected_id == 0) or
                (current is not None and
                 _resource_id_int(current) == expected_id)):
            return

        unregister = getattr(_ctx, "UnregisterReplacement", None)
        if not callable(unregister):
            raise RuntimeError(
                "This qrenderdoc context does not expose UnregisterReplacement")
        if current is not None and not (replace_direct and expected_id):
            unregister(original_resource)

        if expected_id:
            register = getattr(_ctx, "RegisterReplacement", None)
            if not callable(register):
                raise RuntimeError(
                    "This qrenderdoc context does not expose RegisterReplacement")
            register(original_resource, target_resource)

        verified = _shared_shader_ui_owner(original_resource)
        if expected_id == 0:
            if verified is not None:
                raise RuntimeError(
                    "qrenderdoc did not clear the Shader replacement owner")
        elif (verified is None or
              _resource_id_int(verified) != expected_id):
            raise RuntimeError(
                "qrenderdoc did not register the expected Shader replacement owner")

    return _invoke_on_ui_sync(_set_and_verify)


def _release_shared_shader_replacements():
    """Best-effort remove/unregister replacements and free generated targets."""
    records = list(_shared_shader_replacements.values())
    orphan_targets = list(_shared_shader_orphan_targets)
    orphan_targets.extend(row["targetResource"] for row in _shared_shader_manual_target_cache)
    owner_token = _shared_shader_replacement_capture_token
    if not records and not orphan_targets:
        _forget_shared_shader_replacements()
        return
    if owner_token != _current_capture_token():
        _forget_shared_shader_replacements()
        return

    def _snapshot_owned_records_on_ui():
        owned = []
        for record in records:
            try:
                _require_shared_shader_ui_owner(
                    record["originalResource"], record)
                owned.append(record)
            except Exception:
                # A stock Shader Editor or another extension now owns this key.
                # Never remove, unregister, or free through a foreign mapping.
                pass
        return owned

    owned_records = list(
        _invoke_on_ui_sync(_snapshot_owned_records_on_ui) or [])

    def _remove(ctrl):
        removed = []
        for record in owned_records:
            try:
                _remove_shared_shader_resource(
                    ctrl, record.get("api", "d3d11"), record["originalResource"])
                removed.append(record)
            except Exception:
                pass
        return removed

    try:
        removed_records = list(_replay(_remove) or [])
    except Exception:
        removed_records = []
    def _unregister_and_verify_on_ui():
        cleared = []
        unregister = getattr(_ctx, "UnregisterReplacement", None)
        if not callable(unregister):
            return cleared
        for record in removed_records:
            try:
                current = _shared_shader_ui_owner(record["originalResource"])
                if current is None:
                    cleared.append(record)
                    continue
                if (_resource_id_int(current) !=
                        record.get("targetResourceId")):
                    continue
                unregister(record["originalResource"])
                if _shared_shader_ui_owner(record["originalResource"]) is None:
                    cleared.append(record)
            except Exception:
                pass
        return cleared

    try:
        cleared_records = list(
            _invoke_on_ui_sync(_unregister_and_verify_on_ui) or [])
    except Exception:
        cleared_records = []

    # Free only bridge-generated target shaders. Captured originals are never
    # inserted into either collection and are therefore never passed here.
    targets = [record["targetResource"] for record in cleared_records]
    targets.extend(orphan_targets)
    unique_targets = {}
    for target in targets:
        unique_targets[_resource_id_int(target)] = target

    def _free(ctrl):
        for target_id, target in unique_targets.items():
            if target_id <= 0:
                continue
            try:
                ctrl.FreeTargetResource(target)
            except Exception:
                _register_orphan_shader_target(target)

    try:
        _replay(_free)
    except Exception:
        pass
    _forget_shared_shader_replacements()


def _forget_event_cbuffer_snapshots():
    """Forget capture-local CBuffer bytes and IDs without touching a controller."""
    global _event_cbuffer_snapshots, _event_cbuffer_snapshot_keys
    global _event_cbuffer_released_snapshots, _event_cbuffer_release_serial
    global _event_cbuffer_capture_token
    _event_cbuffer_snapshots = {}
    _event_cbuffer_snapshot_keys = {}
    _event_cbuffer_released_snapshots = {}
    _event_cbuffer_release_serial = 0
    _event_cbuffer_capture_token = None


def _release_event_cbuffer_snapshots():
    """Best-effort clear every configured CBuffer shadow while replay is alive."""
    # Capture-open may fail before replacing the controller. Keep ownership on
    # a failed shared clear instead of forgetting edits on that still-live frame.
    for shared_record in list(_shared_cbuffer_edits.records.values()):
        snapshot = shared_record["snapshot"]
        _rollback_shared_cbuffer({
            "snapshot_id": snapshot["snapshotId"],
            "override_id": shared_record["overrideId"],
            "expected_capture_id": snapshot["captureId"],
            "expected_capture_session_id": snapshot["captureSessionId"],
        })
    records = list(_event_cbuffer_snapshots.values())
    owner_token = _event_cbuffer_capture_token
    active = [record for record in records if record.get("overrideId")]
    if not active or owner_token != _current_capture_token():
        _forget_event_cbuffer_snapshots()
        return

    def _do(ctrl):
        if active:
            _begin_replay_atomic_transaction()
        for record in active:
            try:
                ctrl.ClearEventCBufferOverride(
                    int(record["eventId"]), record["stageObject"],
                    int(record["slot"]), int(record.get("registerSpace", 0)))
            except Exception:
                pass

    try:
        _replay(_do)
    except Exception:
        pass
    _forget_event_cbuffer_snapshots()


def _new_symbol_alias_overlay():
    return {
        "schema": SYMBOL_ALIAS_SCHEMA,
        "schemaVersion": SYMBOL_ALIAS_VERSION,
        "captureId": "",
        "sourcePath": "",
        "confirmedOnly": True,
        "allAliases": [],
        "aliases": [],
    }


def _symbol_alias_rename_ledger_copy(value):
    """Copy only the bounded primitive fields used to restore captured names."""
    result = {}
    for resource_id, original in value.items():
        item = {
            "hadCustomName": bool(original.get("hadCustomName")),
            "name": str(original.get("name", "") or ""),
        }
        managed_name = original.get("managedName")
        if isinstance(managed_name, str) and managed_name:
            item["managedName"] = managed_name[:512]
        binding_kind = str(original.get("bindingKind", "") or "")
        if binding_kind in ("shader", "textureresource"):
            item["bindingKind"] = binding_kind
        result[int(resource_id)] = item
    return result


def _symbol_alias_binding(capture_id):
    token = _current_capture_token()
    session_id = str(_capture_session_id or "")
    if token is None or not session_id:
        raise RuntimeError("Symbol alias recovery requires an active capture session")
    return {
        "captureId": str(capture_id or ""),
        "captureSessionId": session_id,
        "captureToken": token,
    }


def _require_symbol_alias_recovery_binding(ledger, expected_capture_id):
    expected = str(expected_capture_id or "").strip().lower()
    if (len(expected) != 64 or
            any(character not in "0123456789abcdef" for character in expected)):
        raise ValueError("expected_capture_id must be a lowercase SHA-256")
    dispatch = _request_dispatch_context()
    capture_loaded = (
        bool(dispatch.get("captureSnapshot", {}).get("captureLoaded"))
        if dispatch is not None else bool(_ctx and _ctx.IsCaptureLoaded()))
    if not capture_loaded:
        raise RuntimeError("No capture loaded")
    if str(_symbol_capture_snapshot.get("captureId", "") or "") != expected:
        raise RuntimeError(
            "Symbol alias rollback captureId does not match the active trusted catalog")
    token = _current_capture_token()
    snapshot_path = str(
        _symbol_capture_snapshot.get("capturePath", "") or "")
    snapshot_path = (
        os.path.normcase(os.path.abspath(snapshot_path)) if snapshot_path else "")
    if token is None or not snapshot_path or token[1] != snapshot_path:
        raise RuntimeError(
            "Symbol alias rollback capture token does not match the trusted catalog")
    if ledger is not None:
        if str(ledger.get("captureId", "") or "") != expected:
            raise RuntimeError(
                "Symbol alias recovery ledger belongs to another captureId")
        if (str(ledger.get("captureSessionId", "") or "") !=
                str(_capture_session_id or "")):
            raise RuntimeError(
                "Symbol alias recovery ledger belongs to another capture session")
        if ledger.get("captureToken") != token:
            raise RuntimeError(
                "Symbol alias recovery ledger belongs to another capture token")
    return expected


def _symbol_alias_rollback_receipt(ledger, status, kept_user=None):
    kept_user = list(kept_user or [])
    return {
        "schema": SYMBOL_ALIAS_ROLLBACK_SCHEMA,
        "schemaVersion": SYMBOL_ALIAS_ROLLBACK_VERSION,
        "captureId": str(ledger.get("captureId", "") or ""),
        "captureSessionId": str(ledger.get("captureSessionId", "") or ""),
        "transactionId": str(ledger.get("transactionId", "") or ""),
        "status": str(status),
        "restored": True,
        "alreadyRestored": status == "already-restored",
        "verified": True,
        "strictReceipt": True,
        "captureTokenVerified": True,
        "originalNamesVerified": True,
        "physicalAtomic": False,
        "recoveryRequired": False,
        "overlayRestored": True,
        "renameLedgerRestored": True,
        "resourceCount": len(ledger.get("resources", {})),
        "restoredResourceCount": max(
            0, len(ledger.get("resources", {})) - len(kept_user)),
        "keptUser": kept_user,
        "userTakeoverCount": len(kept_user),
        "failures": [],
    }


def _restore_symbol_alias_recovery_ledger(ledger, expected_capture_id):
    """Restore and verify every original name before publishing old logical state."""
    global _symbol_alias_overlay, _symbol_resource_renames
    global _symbol_rename_capture_token, _symbol_alias_recovery_ledger
    global _symbol_alias_last_rollback_receipt

    _require_symbol_alias_recovery_binding(ledger, expected_capture_id)
    if ledger is not _symbol_alias_recovery_ledger:
        raise RuntimeError("Symbol alias recovery ledger changed before rollback")
    originals = ledger.get("resources")
    if not isinstance(originals, dict) or len(originals) > MAX_SYMBOL_ALIAS_RECOVERY_RESOURCES:
        raise RuntimeError("Symbol alias recovery ledger is invalid or exceeds its limit")

    resources = _context_resource_ids()
    failures = []
    kept_user = []
    takeover_ids = set()
    committed = str(ledger.get("state", "") or "").startswith("committed")
    managed_names = ledger.get("managedNames", {})
    managed_names = managed_names if isinstance(managed_names, dict) else {}
    if committed:
        for resource_id in sorted(originals):
            expected = managed_names.get(resource_id)
            if expected is None:
                expected = managed_names.get(str(resource_id))
            if not isinstance(expected, dict):
                continue
            rid = resources.get(resource_id)
            if rid is None:
                continue
            try:
                current_custom = bool(_ctx.HasResourceCustomName(rid))
                current_name = str(
                    _ctx.GetResourceNameUnsuffixed(rid) or "")
            except Exception as exc:
                failures.append("resource %d ownership check failed: %s" % (
                    resource_id, str(exc)))
                continue
            expected_custom = bool(expected.get("hadCustomName"))
            expected_name = str(expected.get("name", "") or "")
            if (current_custom != expected_custom or
                    (expected_custom and current_name != expected_name)):
                takeover_ids.add(resource_id)
                kept_user.append({
                    "resourceId": resource_id,
                    "displayName": current_name,
                    "managedDisplayName": expected_name,
                    "reason": "current custom name no longer matches Bread's managed value",
                })
    if failures:
        raise RuntimeError(
            "Symbol alias rollback could not verify Bread ownership; "
            "recovery remains required (%s)" % "; ".join(failures[:16]))
    for resource_id in sorted(originals):
        if resource_id in takeover_ids:
            continue
        original = originals[resource_id]
        rid = resources.get(resource_id)
        if rid is None:
            failures.append("resource %d is absent" % resource_id)
            continue
        try:
            _ctx.SetResourceCustomName(
                rid, original["name"] if original["hadCustomName"] else "")
        except Exception as exc:
            failures.append("resource %d restore failed: %s" % (
                resource_id, str(exc)))

    # Verification is a separate complete pass. A SetResourceCustomName call
    # that returned without changing the UI must not clear recovery evidence.
    for resource_id in sorted(originals):
        original = originals[resource_id]
        rid = resources.get(resource_id)
        if rid is None:
            continue
        try:
            actual_custom = bool(_ctx.HasResourceCustomName(rid))
            actual_name = str(_ctx.GetResourceNameUnsuffixed(rid) or "")
            if resource_id in takeover_ids:
                takeover = next(
                    item for item in kept_user
                    if item["resourceId"] == resource_id)
                if (not actual_custom or
                        actual_name != takeover["displayName"]):
                    failures.append(
                        "resource %d user-owned name changed during rollback"
                        % resource_id)
                continue
            if (actual_custom != original["hadCustomName"] or
                    actual_name != original["name"]):
                failures.append(
                    "resource %d did not verify its original custom-name state"
                    % resource_id)
        except Exception as exc:
            failures.append("resource %d verification failed: %s" % (
                resource_id, str(exc)))

    if failures:
        # Keep the exact same ledger for an idempotent retry. Limit diagnostic
        # expansion even if many resources fail together.
        raise RuntimeError(
            "Symbol alias rollback did not restore every original name; "
            "recovery remains required (%s)" % "; ".join(failures[:16]))

    _symbol_alias_overlay = ledger["originalOverlay"]
    restored_renames = _symbol_alias_rename_ledger_copy(
        ledger["originalResourceRenames"])
    for resource_id in takeover_ids:
        restored_renames.pop(resource_id, None)
    _symbol_resource_renames = restored_renames
    _symbol_rename_capture_token = ledger["originalRenameCaptureToken"]
    receipt = _symbol_alias_rollback_receipt(
        ledger, "restored", kept_user=kept_user)
    _symbol_alias_recovery_ledger = None
    _symbol_alias_last_rollback_receipt = receipt
    return dict(receipt)


def _legacy_symbol_alias_recovery_ledger(capture_id):
    """Adopt pre-ledger aliases so explicit rollback can still be strict."""
    if (not _symbol_resource_renames and
            not _symbol_alias_overlay.get("aliases", [])):
        return None
    binding = _symbol_alias_binding(capture_id)
    if (_symbol_resource_renames and
            _symbol_rename_capture_token != binding["captureToken"]):
        raise RuntimeError("Existing symbol aliases belong to another capture token")
    if len(_symbol_resource_renames) > MAX_SYMBOL_ALIAS_RECOVERY_RESOURCES:
        raise RuntimeError("Existing symbol alias rename ledger exceeds its recovery limit")
    if any(
            not original.get("hadCustomName") and
            not str(original.get("name", "") or "")
            for original in _symbol_resource_renames.values()):
        raise RuntimeError(
            "Existing pre-recovery alias state lacks an exact original "
            "unsuffixed name; reload the capture instead of claiming rollback")
    ledger = {
        "schema": "renderdoc-ultra-alias-recovery-ledger/v1",
        "transactionId": uuid.uuid4().hex,
        "captureId": binding["captureId"],
        "captureSessionId": binding["captureSessionId"],
        "captureToken": binding["captureToken"],
        "state": "committed-legacy",
        "originalOverlay": _new_symbol_alias_overlay(),
        "originalResourceRenames": {},
        "originalRenameCaptureToken": None,
        "resources": _symbol_alias_rename_ledger_copy(_symbol_resource_renames),
        "managedNames": {
            resource_id: {
                "hadCustomName": True,
                "name": str(original.get("managedName", "") or ""),
            }
            for resource_id, original in _symbol_resource_renames.items()
            if str(original.get("managedName", "") or "")
        },
    }
    return ledger


def _rollback_symbol_aliases(params):
    """Strictly restore the active capture's pending or committed aliases."""
    expected_capture_id = str(
        params.get("expected_capture_id", params.get("capture_id", "")) or "")
    supplied_session = params.get("expected_capture_session_id")
    expected_session = None
    if supplied_session is not None:
        expected_session = _shader_override_hex(
            supplied_session, "expected_capture_session_id", 32)
        if expected_session != _request_capture_session_id():
            raise RuntimeError(
                "Symbol alias rollback belongs to another capture session")
    requested_transaction_id = str(
        params.get("expected_transaction_id",
                   params.get("transaction_id", "")) or "").strip().lower()
    expected_transaction_id = (
        _shader_override_hex(
            requested_transaction_id, "expected_transaction_id", 32)
        if requested_transaction_id else "")

    def _rollback_on_ui():
        global _symbol_alias_recovery_ledger, _symbol_alias_last_rollback_receipt

        if (expected_session is not None and
                expected_session != str(_capture_session_id or "")):
            raise RuntimeError(
                "Symbol alias rollback belongs to another capture session")
        bound_capture_id = _require_symbol_alias_recovery_binding(
            _symbol_alias_recovery_ledger, expected_capture_id)
        if (_symbol_alias_recovery_ledger is not None and
                expected_transaction_id and
                str(_symbol_alias_recovery_ledger.get(
                    "transactionId", "") or "") != expected_transaction_id):
            raise RuntimeError(
                "Symbol alias recovery ledger belongs to another transaction")
        if _symbol_alias_recovery_ledger is None:
            last = _symbol_alias_last_rollback_receipt
            if (isinstance(last, dict) and
                    str(last.get("captureId", "") or "") == bound_capture_id and
                    str(last.get("captureSessionId", "") or "") ==
                    str(_capture_session_id or "") and
                    (not expected_transaction_id or
                     str(last.get("transactionId", "") or "") ==
                     expected_transaction_id)):
                receipt = dict(last)
                receipt["status"] = "already-restored"
                receipt["alreadyRestored"] = True
                return receipt

            adopted = _legacy_symbol_alias_recovery_ledger(bound_capture_id)
            if adopted is None:
                binding = _symbol_alias_binding(bound_capture_id)
                adopted = {
                    "transactionId": expected_transaction_id or uuid.uuid4().hex,
                    "captureId": binding["captureId"],
                    "captureSessionId": binding["captureSessionId"],
                    "resources": {},
                }
                receipt = _symbol_alias_rollback_receipt(
                    adopted, "already-restored")
                _symbol_alias_last_rollback_receipt = receipt
                return dict(receipt)
            _symbol_alias_recovery_ledger = adopted

        return _restore_symbol_alias_recovery_ledger(
            _symbol_alias_recovery_ledger, bound_capture_id)

    return _invoke_on_ui_sync(_rollback_on_ui)


def _get_symbol_alias_transaction(params):
    """Query exact capture-bound strict alias transaction/recovery state."""
    expected_capture_id = str(
        params.get("expected_capture_id", params.get("capture_id", "")) or "")
    expected_capture_id = _require_symbol_alias_recovery_binding(
        _symbol_alias_recovery_ledger, expected_capture_id)
    expected_session = _shader_override_hex(
        params.get("expected_capture_session_id"),
        "expected_capture_session_id", 32)
    if expected_session != str(_capture_session_id or ""):
        raise RuntimeError(
            "Symbol alias transaction query belongs to another capture session")
    requested_transaction_id = str(
        params.get("transaction_id", params.get("operation_id", "")) or ""
    ).strip().lower()
    transaction_id = (
        _shader_override_hex(
            requested_transaction_id, "transaction_id", 32)
        if requested_transaction_id else "")
    ledger = _symbol_alias_recovery_ledger
    last = _symbol_alias_last_rollback_receipt
    state = "absent"
    mutation_present = False
    committed = False
    manifest_sha256 = ""
    manifest_path = ""
    if (isinstance(ledger, dict) and
            (not transaction_id or
             str(ledger.get("transactionId", "") or "") == transaction_id)):
        transaction_id = str(ledger.get("transactionId", "") or "")
        state = str(ledger.get("state", "pending") or "pending")
        mutation_present = True
        committed = state == "committed"
        manifest_sha256 = str(ledger.get("manifestSha256", "") or "")
        commit_response = ledger.get("commitResponse")
        if committed and isinstance(commit_response, dict):
            candidate_path = str(commit_response.get("path", "") or "")
            if candidate_path and len(candidate_path) <= 32768:
                manifest_path = candidate_path
    elif (isinstance(last, dict) and
          (not transaction_id or
           str(last.get("transactionId", "") or "") == transaction_id) and
          str(last.get("captureId", "") or "") == expected_capture_id and
          str(last.get("captureSessionId", "") or "") == expected_session):
        transaction_id = str(last.get("transactionId", "") or "")
        state = "rolled-back"
    return {
        "schema": SYMBOL_ALIAS_TRANSACTION_STATUS_SCHEMA,
        "schemaVersion": SYMBOL_ALIAS_TRANSACTION_STATUS_VERSION,
        "captureId": expected_capture_id,
        "captureSessionId": expected_session,
        "transactionId": transaction_id,
        "state": state,
        "committed": committed,
        "mutationPresent": mutation_present,
        "recoveryRequired": mutation_present,
        "rollbackAvailable": mutation_present,
        "manifestSha256": manifest_sha256,
        "manifestPath": manifest_path,
        "replayMutation": False,
    }


def _restore_symbol_resource_names_best_effort(resource_renames, capture_token):
    """Restore captured names without allowing UI failures to break state reset."""
    try:
        if not resource_renames or capture_token != _current_capture_token():
            return
        resources = _context_resource_ids()
        rename_items = list(resource_renames.items())
    except Exception:
        return

    for resource_id, original in rename_items:
        try:
            rid = resources.get(resource_id)
            if rid is None:
                continue
            managed_name = str(original.get("managedName", "") or "")
            if managed_name:
                current_custom = bool(_ctx.HasResourceCustomName(rid))
                current_name = str(
                    _ctx.GetResourceNameUnsuffixed(rid) or "")
                if not current_custom or current_name != managed_name:
                    # The user changed or cleared Bread's last value.  Resetting
                    # the overlay must not reclaim ownership of that resource.
                    continue
            name = original.get("name", "") if original.get("hadCustomName") else ""
            _ctx.SetResourceCustomName(rid, name)
        except Exception:
            pass


def _reset_symbol_overlay(restore_names=True):
    """Drop aliases and restore names only when the original capture is still active."""
    global _symbol_alias_overlay, _symbol_resource_renames, _symbol_rename_capture_token
    global _symbol_alias_recovery_ledger, _symbol_alias_last_rollback_receipt

    new_overlay = _new_symbol_alias_overlay()
    recovery = _symbol_alias_recovery_ledger
    if (restore_names and recovery is not None and
            recovery.get("captureToken") == _current_capture_token() and
            str(recovery.get("captureSessionId", "") or "") ==
            str(_capture_session_id or "")):
        # An integration-initiated capture switch is still on the old live
        # capture here. Refuse the switch if strict recovery cannot be proven.
        _restore_symbol_alias_recovery_ledger(
            recovery, recovery.get("captureId", ""))
    if restore_names:
        _restore_symbol_resource_names_best_effort(
            _symbol_resource_renames, _symbol_rename_capture_token)

    _symbol_alias_overlay = new_overlay
    _symbol_resource_renames = {}
    _symbol_rename_capture_token = None
    # Capture lifecycle reset invalidates every ResourceId. A user-visible
    # same-capture rollback never takes this path; it uses the strict verifier
    # above and retains the ledger on any failure.
    _symbol_alias_recovery_ledger = None
    _symbol_alias_last_rollback_receipt = None


def _reset_symbol_state(restore_names=True):
    global _symbol_capture_snapshot, _known_catalog_capture_ids
    global _known_catalog_identity_pairs, _known_catalog_stable_pairs
    global _capture_session_id
    globals().get("_event_texture_raw_cache", {}).clear()
    _reset_symbol_overlay(restore_names=restore_names)
    _forget_event_shader_overrides()
    _forget_shared_shader_replacements()
    _forget_event_cbuffer_snapshots()
    _shared_cbuffer_edits.forget()
    _symbol_capture_snapshot = {
        "captureId": "",
        "capturePath": "",
        "shaderKeys": set(),
        "usesByKey": {},
    }
    _known_catalog_capture_ids = {}
    _known_catalog_identity_pairs = set()
    _known_catalog_stable_pairs = set()
    with _project_shader_index_jobs_guard:
        now = time.monotonic()
        for job in _project_shader_index_jobs.values():
            _request_project_shader_index_cancel(
                job, now, "RenderDoc capture changed during resource indexing")
        terminal_ids = [
            job_id for job_id, job in _project_shader_index_jobs.items()
            if job.get("status") in ("completed", "failed")
        ]
        for job_id in terminal_ids:
            _project_shader_index_jobs.pop(job_id, None)
    with _shader_catalog_export_jobs_guard:
        now = time.monotonic()
        for job in _shader_catalog_export_jobs.values():
            _request_shader_catalog_export_cancel(
                job, now, "RenderDoc capture changed during Shader catalog export")
        terminal_ids = [
            job_id for job_id, job in _shader_catalog_export_jobs.items()
            if job.get("status") in ("completed", "failed", "cancelled")
        ]
        for job_id in terminal_ids:
            _shader_catalog_export_jobs.pop(job_id, None)
    with _current_context_freeze_jobs_guard:
        now = time.monotonic()
        for job in _current_context_freeze_jobs.values():
            if job.get("status") not in ("queued", "running"):
                continue
            job["status"] = "failed"
            job["context"] = None
            job["error"] = "RenderDoc capture changed during current context freeze"
            job["updatedMonotonic"] = now
            job["finishedMonotonic"] = now
            try:
                _write_current_context_freeze_terminal(job)
            except Exception:
                pass
    try:
        loaded = bool(_ctx and _ctx.IsCaptureLoaded())
    except Exception:
        loaded = False
    _capture_session_id = uuid.uuid4().hex if loaded else ""
    try:
        _publish_instance_manifest(activity=True)
    except Exception:
        # Capture lifecycle remains authoritative even when discovery metadata
        # cannot be refreshed during filesystem teardown.
        pass


def _synchronise_capture_lifecycle():
    global _active_capture_token
    if _replay_recovery_path:
        return
    token = _current_capture_token()
    if _active_capture_token is None:
        if token is not None and not _capture_session_id:
            _reset_symbol_state(restore_names=False)
        _active_capture_token = token
        return
    if token != _active_capture_token:
        # A UI-driven capture change can happen outside the MCP open_capture method. Resource IDs
        # from the old capture must be forgotten and must not be applied to the new one.
        _reset_symbol_state(restore_names=True)
        _active_capture_token = token


def _catalog_capture_id(catalog):
    """Compute the capture identity shared with the external deterministic matcher."""
    shaders = []
    for shader in catalog.get("shaders", []):
        if not isinstance(shader, dict):
            continue
        shaders.append({
            "resourceId": _safe_int(
                shader.get("shaderResourceId", shader.get("resourceId", 0)), 0),
            "stage": _normalise_stage_name(shader.get("stage", "")),
            "entryPoint": str(
                shader.get("entryPoint", shader.get("entry", "")) or ""),
            "rawSha256": str(shader.get("rawSha256", "") or "").lower(),
        })
    shaders.sort(key=lambda value: (
        value["resourceId"], value["stage"], value["entryPoint"], value["rawSha256"]))
    identity = {
        "capturePath": str(catalog.get("capturePath", "") or ""),
        "api": str(catalog.get("api", "") or ""),
        "shaders": shaders,
    }
    canonical = json.dumps(
        identity, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _stable_shader_key(shader_key):
    """A Shader key without the capture-local ResourceId.

    RenderDoc hands out a fresh ResourceId every time a capture is opened, so a key
    that contains one identifies a Shader *in this replay session* and nothing more.
    What is stable across sessions, across .rdc files and across re-recordings of the
    same game build is ``stage:entryPoint:rawSha256`` -- the Shader's own bytes.
    """
    parts = str(shader_key or "").split(":", 1)
    return parts[1] if len(parts) == 2 else str(shader_key or "")


def _catalog_stable_capture_id(catalog):
    """The capture identity with the volatile ResourceId removed.

    ``captureId`` answers "which replay session is this"; this answers "which Shaders
    are these", which is the question a stored workspace actually needs to ask when it
    reattaches. Everything else in the hash -- capture path, API, Shader bytes -- is
    the same across sessions.
    """
    shaders = []
    for shader in catalog.get("shaders", []):
        if not isinstance(shader, dict):
            continue
        shaders.append({
            "stage": _normalise_stage_name(shader.get("stage", "")),
            "entryPoint": str(
                shader.get("entryPoint", shader.get("entry", "")) or ""),
            "rawSha256": str(shader.get("rawSha256", "") or "").lower(),
        })
    shaders.sort(key=lambda value: (
        value["stage"], value["entryPoint"], value["rawSha256"]))
    # No capture path: this identity answers "which Shaders are these", and that
    # does not change with the file's spelling, its folder, or a second capture of
    # the same build. The Host computes the same hash from the stored catalog.
    identity = {
        "api": str(catalog.get("api", "") or ""),
        "shaders": shaders,
    }
    canonical = json.dumps(
        identity, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _catalog_stable_identity_evidence(evidence):
    """The same evidence with every ResourceId dropped from its Shader keys."""
    return {
        "selection": evidence["selection"],
        "shaderKeys": sorted(set(
            _stable_shader_key(key) for key in evidence["shaderKeys"])),
        "useTuples": sorted(
            [event_id, _stable_shader_key(shader_key)]
            for event_id, shader_key in evidence["useTuples"]),
    }


def _catalog_capture_id_description(catalog, expected_capture_id):
    """Say which identity input differs, because the hash alone says nothing.

    The captureId is a hash of exactly three things: the capture path, the API name
    and the selected Shader tuples. When a stored workspace stops rebinding, exactly
    one of them has drifted -- a re-recorded .rdc, a path spelled differently, an API
    enum whose text changed, or a selection that now resolves to a different Shader.
    Printing them turns a dead end into a one-line diagnosis.
    """
    shaders = []
    for shader in (catalog.get("shaders", []) or [])[:6]:
        if not isinstance(shader, dict):
            continue
        shaders.append("%s:%s:%s:%s" % (
            _safe_int(shader.get("shaderResourceId", shader.get("resourceId", 0)), 0),
            _normalise_stage_name(shader.get("stage", "")),
            str(shader.get("entryPoint", shader.get("entry", "")) or ""),
            str(shader.get("rawSha256", "") or "").lower()[:16]))
    return ("computed=%s expected=%s capturePath=%r api=%r shaderCount=%d selection=%s "
            "shaders=[%s]" % (
                str(catalog.get("captureId", ""))[:16],
                str(expected_capture_id or "")[:16],
                str(catalog.get("capturePath", "") or ""),
                str(catalog.get("api", "") or ""),
                len(catalog.get("shaders", []) or []),
                json.dumps(catalog.get("selection", {}), ensure_ascii=False,
                           sort_keys=True)[:160],
                ", ".join(shaders)))


def _catalog_identity_evidence(catalog):
    """Canonicalise the exact fixed selection, Shader set and event/use map.

    This deliberately excludes names, reflection display metadata and output
    paths.  It is paired with ``captureId``, which already binds capture
    path/API and the complete physical Shader-key set.  The helper is kept
    Python 3.6 compatible because it executes inside qrenderdoc.
    """
    if (not isinstance(catalog, dict) or
            catalog.get("schema") != SYMBOL_CATALOG_SCHEMA or
            catalog.get("schemaVersion") != SYMBOL_CATALOG_VERSION):
        raise RuntimeError("Shader catalog identity evidence has an invalid schema")

    selection = catalog.get("selection")
    if (not isinstance(selection, dict) or
            set(selection.keys()) != set(("mode", "eventIds", "stages"))):
        raise RuntimeError("Shader catalog identity selection is invalid")
    mode = str(selection.get("mode", "") or "")
    if mode not in ("explicit", "all_draw_dispatch"):
        raise RuntimeError("Shader catalog identity selection mode is invalid")
    raw_event_ids = selection.get("eventIds")
    raw_stages = selection.get("stages")
    if (not isinstance(raw_event_ids, list) or
            len(raw_event_ids) > MAX_CATALOG_IDENTITY_EVENTS or
            not isinstance(raw_stages, list) or not raw_stages or
            len(raw_stages) > MAX_CATALOG_IDENTITY_STAGES):
        raise RuntimeError("Shader catalog identity selection exceeds fixed limits")
    if mode == "explicit" and not raw_event_ids:
        raise RuntimeError("Shader catalog explicit identity selection is empty")

    event_ids = []
    for index, value in enumerate(raw_event_ids):
        if isinstance(value, bool):
            raise RuntimeError(
                "Shader catalog identity eventIds[%d] is invalid" % index)
        try:
            event_id = int(value)
        except Exception:
            raise RuntimeError(
                "Shader catalog identity eventIds[%d] is invalid" % index)
        if event_id < 0 or event_id in event_ids:
            raise RuntimeError(
                "Shader catalog identity eventIds[%d] is invalid" % index)
        event_ids.append(event_id)

    stages = []
    for index, value in enumerate(raw_stages):
        stage = _normalise_stage_name(value)
        if not stage or value != stage or stage in stages:
            raise RuntimeError(
                "Shader catalog identity stages[%d] is invalid" % index)
        stages.append(stage)

    def _shader_identity(value, field):
        if not isinstance(value, dict):
            raise RuntimeError("Shader catalog %s is invalid" % field)
        resource_a = value.get("shaderResourceId")
        resource_b = value.get("resourceId")
        try:
            if (resource_a is not None and resource_b is not None and
                    int(resource_a) != int(resource_b)):
                raise RuntimeError(
                    "Shader catalog %s ResourceId conflicts" % field)
            raw_resource = resource_a if resource_a is not None else resource_b
            if isinstance(raw_resource, bool):
                raise ValueError("boolean ResourceId")
            resource_id = int(raw_resource)
        except Exception:
            raise RuntimeError("Shader catalog %s ResourceId is invalid" % field)
        stage = _normalise_stage_name(value.get("stage"))
        if resource_id <= 0 or not stage:
            raise RuntimeError("Shader catalog %s identity is invalid" % field)
        entry_point = str(
            value.get("entryPoint", value.get("entry", "")) or "")
        raw_sha256 = str(value.get("rawSha256", "") or "").strip().lower()
        if (raw_sha256 and
                (len(raw_sha256) != 64 or
                 any(character not in "0123456789abcdef"
                     for character in raw_sha256))):
            raise RuntimeError("Shader catalog %s rawSha256 is invalid" % field)
        shader_key = "%d:%s:%s:%s" % (
            resource_id, stage, entry_point,
            raw_sha256 or "no-raw-bytes")
        if value.get("shaderKey") != shader_key:
            raise RuntimeError("Shader catalog %s shaderKey is invalid" % field)
        return shader_key, stage

    shaders = catalog.get("shaders")
    uses = catalog.get("uses")
    if (not isinstance(shaders, list) or
            len(shaders) > MAX_CATALOG_IDENTITY_SHADERS or
            not isinstance(uses, list) or
            len(uses) > MAX_CATALOG_IDENTITY_USES):
        raise RuntimeError("Shader catalog identity Shader/use evidence is invalid")
    declared = set()
    for index, shader in enumerate(shaders):
        shader_key, unused_stage = _shader_identity(
            shader, "shaders[%d]" % index)
        if shader_key in declared:
            raise RuntimeError(
                "Shader catalog shaders[%d] is duplicated" % index)
        declared.add(shader_key)

    selected_events = set(event_ids)
    selected_stages = set(stages)
    use_tuples = set()
    used = set()
    for index, use in enumerate(uses):
        shader_key, stage = _shader_identity(use, "uses[%d]" % index)
        if shader_key not in declared:
            raise RuntimeError(
                "Shader catalog uses[%d] references an unknown Shader" % index)
        raw_event_id = use.get("eventId")
        if isinstance(raw_event_id, bool):
            raise RuntimeError(
                "Shader catalog uses[%d].eventId is invalid" % index)
        try:
            event_id = int(raw_event_id)
        except Exception:
            raise RuntimeError(
                "Shader catalog uses[%d].eventId is invalid" % index)
        item = (event_id, shader_key)
        if (event_id not in selected_events or stage not in selected_stages or
                item in use_tuples):
            raise RuntimeError(
                "Shader catalog uses[%d] is outside its exact selection" % index)
        use_tuples.add(item)
        used.add(shader_key)
    if used != declared:
        raise RuntimeError(
            "Shader catalog identity does not bind every Shader to an event")

    return {
        "selection": {
            "mode": mode,
            "eventIds": event_ids,
            "stages": stages,
        },
        "shaderKeys": sorted(declared),
        "useTuples": [
            [event_id, shader_key]
            for event_id, shader_key in sorted(use_tuples)
        ],
    }


def _catalog_identity_evidence_sha256(catalog):
    evidence = _catalog_identity_evidence(catalog)
    encoded = json.dumps(
        evidence, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _catalog_stable_identity_evidence_sha256(catalog):
    """The evidence hash a stored workspace can still reproduce next session."""
    evidence = _catalog_stable_identity_evidence(
        _catalog_identity_evidence(catalog))
    encoded = json.dumps(
        evidence, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _catalog_identity_cache_projection(catalog, identity_evidence_sha256=None):
    """Build bounded exact-identity cache state without publishing any of it."""
    if not isinstance(catalog, dict):
        raise RuntimeError("Shader catalog cache payload is invalid")
    raw_capture_id = catalog.get("captureId")
    capture_id = str(raw_capture_id or "")
    if (not isinstance(raw_capture_id, str) or capture_id != capture_id.strip() or
            len(capture_id) != 64 or
            any(character not in "0123456789abcdef"
                for character in capture_id)):
        raise RuntimeError("Shader catalog captureId must be a lowercase SHA-256")
    raw_capture_path = catalog.get("capturePath")
    if not isinstance(raw_capture_path, str) or not raw_capture_path.strip():
        raise RuntimeError("Shader catalog capturePath is required")
    capture_path = str(raw_capture_path)
    canonical_capture_path = os.path.normcase(os.path.abspath(capture_path))
    computed_evidence_sha256 = _catalog_identity_evidence_sha256(catalog)
    if (identity_evidence_sha256 is not None and
            str(identity_evidence_sha256 or "") != computed_evidence_sha256):
        raise RuntimeError("Shader catalog identity evidence hash is inconsistent")
    identity_evidence_sha256 = computed_evidence_sha256
    identity_evidence_sha256 = str(identity_evidence_sha256 or "")
    if (len(identity_evidence_sha256) != 64 or
            any(character not in "0123456789abcdef"
                for character in identity_evidence_sha256)):
        raise RuntimeError(
            "Shader catalog identity evidence must be a lowercase SHA-256")

    new_known_capture_ids = dict(_known_catalog_capture_ids)
    if (capture_id not in new_known_capture_ids and
            len(new_known_capture_ids) >= MAX_KNOWN_CATALOG_CAPTURE_IDS):
        raise RuntimeError(
            "Too many catalog identities were exported in this capture session")
    new_known_capture_ids[capture_id] = canonical_capture_path
    new_identity_pairs = set(_known_catalog_identity_pairs)
    identity_pair = (capture_id, identity_evidence_sha256)
    if (identity_pair not in new_identity_pairs and
            len(new_identity_pairs) >= MAX_KNOWN_CATALOG_IDENTITY_PAIRS):
        raise RuntimeError(
            "Too many exact catalog selections were exported in this capture session")
    new_identity_pairs.add(identity_pair)
    stable_capture_id = _catalog_stable_capture_id(catalog)
    stable_evidence_sha256 = _catalog_stable_identity_evidence_sha256(catalog)
    new_stable_pairs = set(_known_catalog_stable_pairs)
    stable_pair = (stable_capture_id, stable_evidence_sha256)
    if (stable_pair not in new_stable_pairs and
            len(new_stable_pairs) >= MAX_KNOWN_CATALOG_IDENTITY_PAIRS):
        raise RuntimeError(
            "Too many exact catalog selections were exported in this capture session")
    new_stable_pairs.add(stable_pair)
    return {
        "captureId": capture_id,
        "capturePath": capture_path,
        "knownCaptureIds": new_known_capture_ids,
        "knownIdentityPairs": new_identity_pairs,
        "knownStablePairs": new_stable_pairs,
        "identityEvidenceSha256": identity_evidence_sha256,
        "stableCaptureId": stable_capture_id,
        "stableIdentityEvidenceSha256": stable_evidence_sha256,
    }


def _prepare_catalog_cache_publication(catalog, identity_evidence_sha256=None,
                                       identity_only=False,
                                       recover_aliases_before_switch=False):
    """Build every potentially large catalog cache value off the GUI thread."""
    projected = _catalog_identity_cache_projection(
        catalog, identity_evidence_sha256)
    publication = {
        "identityOnly": bool(identity_only),
        "baseKnownCaptureIds": _known_catalog_capture_ids,
        "baseKnownIdentityPairs": _known_catalog_identity_pairs,
        "baseKnownStablePairs": _known_catalog_stable_pairs,
        "projected": projected,
    }
    if identity_only:
        return publication

    capture_id = projected["captureId"]
    capture_path = projected["capturePath"]

    raw_shaders = catalog.get("shaders")
    raw_uses = catalog.get("uses")
    if not isinstance(raw_shaders, list) or not isinstance(raw_uses, list):
        raise RuntimeError("Shader catalog Shader/use records are invalid")

    shader_keys = set()
    for shader in raw_shaders:
        if not isinstance(shader, dict):
            raise RuntimeError("Shader catalog Shader record is invalid")
        key = (
            _safe_int(shader.get("shaderResourceId", shader.get("resourceId", 0)), 0),
            _normalise_stage_name(shader.get("stage", "")),
            str(shader.get("entryPoint", shader.get("entry", "")) or ""),
            str(shader.get("rawSha256", "") or "").lower(),
        )
        shader_keys.add(key)

    uses_by_key = {}
    for use in raw_uses:
        if not isinstance(use, dict):
            raise RuntimeError("Shader catalog use record is invalid")
        key = (
            _safe_int(use.get("shaderResourceId", use.get("resourceId", 0)), 0),
            _normalise_stage_name(use.get("stage", "")),
            str(use.get("entryPoint", use.get("entry", "")) or ""),
            str(use.get("rawSha256", "") or "").lower(),
        )
        event_id = _safe_int(use.get("eventId", 0), 0)
        if key in shader_keys and event_id > 0:
            uses_by_key.setdefault(key, []).append(event_id)

    new_snapshot = {
        "captureId": capture_id,
        "capturePath": capture_path,
        "shaderKeys": shader_keys,
        "usesByKey": uses_by_key,
    }

    old_capture_id = str(_symbol_capture_snapshot.get("captureId", "") or "")
    reset_overlay = bool(old_capture_id and old_capture_id != capture_id)
    recover_aliases_before_switch = bool(recover_aliases_before_switch)
    if (reset_overlay and _symbol_alias_recovery_ledger is not None and
            not recover_aliases_before_switch):
        raise RuntimeError(
            "Rollback the capture-bound symbol aliases before publishing a "
            "different catalog identity")
    publication.update({
        "baseSymbolSnapshot": _symbol_capture_snapshot,
        "baseAliasOverlay": _symbol_alias_overlay,
        "baseResourceRenames": _symbol_resource_renames,
        "baseResourceRenamesValue": dict(_symbol_resource_renames),
        "baseRenameCaptureToken": _symbol_rename_capture_token,
        "baseAliasRecoveryLedger": _symbol_alias_recovery_ledger,
        "recoverAliasesBeforeSwitch": bool(
            reset_overlay and _symbol_alias_recovery_ledger is not None and
            recover_aliases_before_switch),
        "newSnapshot": new_snapshot,
        "resetOverlay": reset_overlay,
        "newOverlay": _new_symbol_alias_overlay() if reset_overlay else None,
        "resourceRenames": (
            dict(_symbol_resource_renames) if reset_overlay else {}),
        "renameCaptureToken": (
            _symbol_rename_capture_token if reset_overlay else None),
    })
    return publication


def _prepare_inventory_symbol_snapshot_publication(result, capture_path):
    """Prepare a unique-resource symbol snapshot without granting catalog authority.

    Resource inventory has no frame-wide event selection and some shaders may
    legitimately have no representative event.  It therefore cannot be
    projected through ``_catalog_identity_evidence`` (which intentionally
    requires every shader to have a selected use).  This publication keeps the
    existing transactional symbol-state checks while leaving the executable
    catalog identity caches unchanged.
    """

    if (not isinstance(result, dict) or
            result.get("inventoryOnly") is not True or
            result.get("inventoryComplete") is not True):
        raise RuntimeError("Shader resource inventory is incomplete")
    capture_id = str(result.get("stableResourceSetSha256", "") or "")
    if (len(capture_id) != 64 or
            any(character not in "0123456789abcdef"
                for character in capture_id)):
        raise RuntimeError(
            "Shader resource inventory stable set must be a lowercase SHA-256")
    raw_capture_path = str(capture_path or "").strip()
    if not raw_capture_path:
        raise RuntimeError("Shader resource inventory capturePath is required")
    canonical_capture_path = os.path.normcase(
        os.path.abspath(raw_capture_path))

    assets = result.get("assets")
    if (not isinstance(assets, list) or
            len(assets) > MAX_PROJECT_SHADER_INDEX_ENTRIES):
        raise RuntimeError("Shader resource inventory assets are invalid")
    shader_keys = set()
    uses_by_key = {}
    for index, asset in enumerate(assets):
        if not isinstance(asset, dict):
            raise RuntimeError(
                "Shader resource inventory asset %d is invalid" % index)
        raw_resource_id = asset.get("resourceId")
        if isinstance(raw_resource_id, bool):
            raise RuntimeError(
                "Shader resource inventory asset %d ResourceId is invalid" %
                index)
        resource_id = _safe_int(raw_resource_id, 0)
        raw_stage = str(asset.get("stage", "") or "")
        stage = _normalise_stage_name(raw_stage)
        entry_point = str(asset.get("entryPoint", "") or "")
        raw_sha256 = str(asset.get("rawSha256", "") or "").lower()
        if (resource_id <= 0 or not stage or stage != raw_stage or
                (raw_sha256 and
                 (len(raw_sha256) != 64 or
                  any(character not in "0123456789abcdef"
                      for character in raw_sha256)))):
            raise RuntimeError(
                "Shader resource inventory asset %d identity is invalid" %
                index)
        key = (resource_id, stage, entry_point, raw_sha256)
        shader_keys.add(key)

        raw_anchor = asset.get("anchorEventId")
        if raw_anchor is None:
            continue
        if isinstance(raw_anchor, bool):
            raise RuntimeError(
                "Shader resource inventory asset %d anchor is invalid" % index)
        anchor_event_id = _safe_int(raw_anchor, 0)
        if anchor_event_id <= 0:
            raise RuntimeError(
                "Shader resource inventory asset %d anchor is invalid" % index)
        # Exactly one representative EID is retained for this unique Shader
        # key.  Alias revalidation may select it later, but inventory never
        # selects or traverses the event itself.
        existing = uses_by_key.get(key)
        if existing is not None and existing != [anchor_event_id]:
            raise RuntimeError(
                "Shader resource inventory identity has conflicting anchors")
        uses_by_key[key] = [anchor_event_id]

    new_snapshot = {
        "captureId": capture_id,
        "capturePath": raw_capture_path,
        "shaderKeys": shader_keys,
        "usesByKey": uses_by_key,
    }
    old_capture_id = str(_symbol_capture_snapshot.get("captureId", "") or "")
    old_capture_path = str(
        _symbol_capture_snapshot.get("capturePath", "") or "").strip()
    canonical_old_path = (
        os.path.normcase(os.path.abspath(old_capture_path))
        if old_capture_path else "")
    reset_overlay = bool(
        (old_capture_id or canonical_old_path) and
        (old_capture_id != capture_id or
         canonical_old_path != canonical_capture_path))
    if reset_overlay and _symbol_alias_recovery_ledger is not None:
        raise RuntimeError(
            "Rollback the capture-bound symbol aliases before publishing a "
            "different Shader resource inventory")

    # Reuse _commit_catalog_cache_publication's compare-before-publish section,
    # but copy the executable identity caches without adding an authority pair.
    return {
        "identityOnly": False,
        "baseKnownCaptureIds": _known_catalog_capture_ids,
        "baseKnownIdentityPairs": _known_catalog_identity_pairs,
        "baseKnownStablePairs": _known_catalog_stable_pairs,
        "projected": {
            "knownCaptureIds": dict(_known_catalog_capture_ids),
            "knownIdentityPairs": set(_known_catalog_identity_pairs),
            "knownStablePairs": set(_known_catalog_stable_pairs),
        },
        "baseSymbolSnapshot": _symbol_capture_snapshot,
        "baseAliasOverlay": _symbol_alias_overlay,
        "baseResourceRenames": _symbol_resource_renames,
        "baseResourceRenamesValue": dict(_symbol_resource_renames),
        "baseRenameCaptureToken": _symbol_rename_capture_token,
        "baseAliasRecoveryLedger": _symbol_alias_recovery_ledger,
        "newSnapshot": new_snapshot,
        "resetOverlay": reset_overlay,
        "newOverlay": _new_symbol_alias_overlay() if reset_overlay else None,
        "resourceRenames": (
            dict(_symbol_resource_renames) if reset_overlay else {}),
        "renameCaptureToken": (
            _symbol_rename_capture_token if reset_overlay else None),
    }


def _commit_catalog_cache_publication(publication):
    """Commit one prevalidated cache snapshot in a short GUI-thread section."""
    global _symbol_alias_overlay, _symbol_resource_renames
    global _symbol_rename_capture_token, _symbol_capture_snapshot
    global _known_catalog_capture_ids, _known_catalog_identity_pairs
    global _known_catalog_stable_pairs
    global _symbol_alias_recovery_ledger, _symbol_alias_last_rollback_receipt

    if not isinstance(publication, dict):
        raise RuntimeError("Shader catalog cache publication is invalid")
    if (_known_catalog_capture_ids is not publication.get("baseKnownCaptureIds") or
            _known_catalog_identity_pairs is not publication.get(
                "baseKnownIdentityPairs") or
            _known_catalog_stable_pairs is not publication.get(
                "baseKnownStablePairs")):
        raise RuntimeError("Shader catalog cache changed before publication")
    projected = publication.get("projected")
    if not isinstance(projected, dict):
        raise RuntimeError("Shader catalog cache projection is invalid")
    if publication.get("identityOnly") is True:
        # The exact pair is the fast-path authority, so publish it last. A
        # reader can observe a known captureId without the pair (safe slow
        # path), never a newly-authorised pair without its path binding.
        _known_catalog_capture_ids = projected["knownCaptureIds"]
        _known_catalog_stable_pairs = projected["knownStablePairs"]
        _known_catalog_identity_pairs = projected["knownIdentityPairs"]
        return

    if (_symbol_capture_snapshot is not publication.get("baseSymbolSnapshot") or
            _symbol_alias_overlay is not publication.get("baseAliasOverlay") or
            _symbol_resource_renames is not publication.get(
                "baseResourceRenames") or
            _symbol_resource_renames != publication.get(
                "baseResourceRenamesValue") or
            _symbol_rename_capture_token != publication.get(
                "baseRenameCaptureToken") or
            _symbol_alias_recovery_ledger is not publication.get(
                "baseAliasRecoveryLedger")):
        raise RuntimeError("Shader symbol state changed before catalog publication")
    if publication.get("resetOverlay") is True:
        if publication.get("recoverAliasesBeforeSwitch") is True:
            recovery = publication.get("baseAliasRecoveryLedger")
            if not isinstance(recovery, dict):
                raise RuntimeError(
                    "Shader catalog switch lost its alias recovery ledger")
            old_capture_id = str(
                publication["baseSymbolSnapshot"].get("captureId", "") or "")
            # Keep the old catalog active until every Bread-managed name has
            # either been restored or explicitly preserved as a user takeover.
            # A failed restore leaves the old snapshot and exact ledger in
            # place, so the same recovery can be retried without guessing.
            _restore_symbol_alias_recovery_ledger(recovery, old_capture_id)
            if _symbol_alias_recovery_ledger is not None:
                raise RuntimeError(
                    "Shader catalog switch did not complete alias recovery")
        _restore_symbol_resource_names_best_effort(
            _symbol_resource_renames, _symbol_rename_capture_token)
        _symbol_alias_overlay = publication["newOverlay"]
        _symbol_resource_renames = {}
        _symbol_rename_capture_token = None
        _symbol_alias_last_rollback_receipt = None
    _symbol_capture_snapshot = publication["newSnapshot"]
    _known_catalog_capture_ids = projected["knownCaptureIds"]
    _known_catalog_stable_pairs = projected["knownStablePairs"]
    _known_catalog_identity_pairs = projected["knownIdentityPairs"]


def _cache_catalog_identity_pair(catalog, identity_evidence_sha256=None):
    """Publish only exact operation-authorisation facts for a restart rebind."""
    _commit_catalog_cache_publication(_prepare_catalog_cache_publication(
        catalog, identity_evidence_sha256, identity_only=True))


def _cache_symbol_catalog(catalog, identity_evidence_sha256=None):
    """Publish an ordinary full catalog snapshot without partial mutation."""
    _commit_catalog_cache_publication(_prepare_catalog_cache_publication(
        catalog, identity_evidence_sha256, identity_only=False))


def _revalidate_symbol_shader_keys(expected_keys):
    """Hash current replay reflections so a stale catalog cannot authorise an alias."""
    expected_keys = set(expected_keys)
    if not expected_keys:
        return set(), {}

    stage_map = dict(_available_shader_stages())
    uses_by_key = _symbol_capture_snapshot.get("usesByKey", {})
    try:
        original_event = _request_visible_event_id(0)
        restore_original_event = True
    except Exception:
        original_event = 0
        restore_original_event = False

    def _do(ctrl):
        verified = set()
        failures = {}
        try:
            for key in sorted(expected_keys):
                resource_id, stage_name, entry_point, raw_sha256 = key
                stage = stage_map.get(stage_name)
                event_ids = uses_by_key.get(key, [])
                if stage is None:
                    failures[key] = "shader stage is unavailable in this RenderDoc build"
                    continue
                if not event_ids:
                    failures[key] = "catalog has no event proving this shader binding"
                    continue
                try:
                    _set_frame_event(ctrl, int(event_ids[0]), True)
                    ps = ctrl.GetPipelineState()
                    shader_id = ps.GetShader(stage)
                    if _resource_id_int(shader_id) != resource_id:
                        failures[key] = "shader resource changed since catalog export"
                        continue
                    entries = ctrl.GetShaderEntryPoints(shader_id)
                    selected = None
                    for candidate in entries or []:
                        if str(getattr(candidate, "name", "") or "") == entry_point:
                            selected = candidate
                            break
                    if selected is None:
                        failures[key] = "shader entry point changed since catalog export"
                        continue
                    active_reflection = ctrl.GetShader(
                        _get_pipeline_obj(ps, ctrl), shader_id, selected)
                    if not active_reflection:
                        failures[key] = "shader reflection is unavailable"
                        continue
                    # D3D12 resolves GetShader through an active shared
                    # replacement even though GetPipelineState().GetShader()
                    # still returns the captured ResourceId.  Catalog export
                    # deliberately records the retained captured-original
                    # reflection in that case, so live alias revalidation must
                    # prove the bridge-owned target and then compare the same
                    # retained original bytes.  Hashing the active target here
                    # made every valid resource-name publication fail after a
                    # Shader workspace replacement had been applied.
                    reflection = active_reflection
                    owner = _shared_shader_replacements.get(resource_id)
                    if owner is not None:
                        capture_token = _current_capture_token()
                        if (owner.get("captureSessionId") != _capture_session_id or
                                owner.get("captureToken") != capture_token or
                                _shared_shader_replacement_capture_token != capture_token or
                                owner.get("api") != _shader_api_token(ctrl) or
                                _resource_id_int(owner.get("originalResource")) !=
                                resource_id):
                            failures[key] = (
                                "shared Shader replacement owner belongs to another capture")
                            continue
                        reflection = _captured_original_from_shared_owner(
                            active_reflection,
                            {
                                "eventId": int(event_ids[0]),
                                "expectedOriginalResourceId": resource_id,
                                "expectedOriginalSha256": raw_sha256,
                            },
                            stage_name,
                            entry_point,
                            owner,
                            allow_original_active=(owner.get("api") in ("d3d11", "vulkan", "opengl")),
                        )
                    actual_entry = str(getattr(reflection, "entryPoint", "") or
                                       getattr(selected, "name", "") or "")
                    raw = _shader_raw_bytes(reflection)
                    actual_sha256 = hashlib.sha256(raw).hexdigest() if raw else ""
                    actual_key = (
                        resource_id, stage_name, actual_entry, actual_sha256.lower())
                    if actual_key != key:
                        failures[key] = "shader bytes or entry point changed since catalog export"
                        continue
                    verified.add(key)
                except Exception as exc:
                    failures[key] = str(exc)
        finally:
            if restore_original_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass
        return verified, failures

    return _replay(_do)


def _revalidate_symbol_texture_aliases(candidates):
    """Prove each texture alias still names the resource bound at its exact EID.

    The Host seals the asset/content decision, while the bridge owns the live
    capture fact.  Keeping those responsibilities separate prevents a stale
    material receipt from renaming an unrelated resource after the selected
    draw or capture changes.
    """
    candidates = [item for item in candidates if item[3] == "textureresource"]
    if not candidates:
        return set(), {}

    stage_map = dict(_available_shader_stages())
    try:
        original_event = _request_visible_event_id(0)
        restore_original_event = True
    except Exception:
        original_event = 0
        restore_original_event = False

    def _do(ctrl):
        verified = set()
        failures = {}
        try:
            texture_ids = {
                _resource_id_int(getattr(texture, "resourceId", None))
                for texture in (ctrl.GetTextures() or [])
            }
            for index, alias, shader_key, unused_kind in candidates:
                metadata = alias.get("metadata", {})
                event_id = _safe_int(
                    metadata.get("eventId") if isinstance(metadata, dict) else 0, 0)
                target_id = _alias_target_resource_id(alias)
                bind_number = _safe_int(_alias_first(
                    alias, ("bindNumber", "bind", "fixedBindNumber"), -1), -1)
                register_space = _safe_int(_alias_first(
                    alias, ("registerSpace", "space", "fixedBindSetOrSpace"), 0), 0)
                requested_array = _alias_first(
                    alias, ("arrayIndex", "arrayElement"), None)
                requested_array = (
                    _safe_int(requested_array, -1)
                    if requested_array is not None else None)
                shader_id, stage_name, entry_point, unused_raw_sha256 = shader_key
                stage = stage_map.get(stage_name)
                if event_id <= 0 or target_id <= 0 or bind_number < 0:
                    failures[index] = (
                        "texture resource alias requires eventId, resourceId and bindNumber")
                    continue
                if target_id not in texture_ids:
                    failures[index] = "texture resource is absent from the active capture"
                    continue
                if stage is None:
                    failures[index] = "shader stage is unavailable in this RenderDoc build"
                    continue
                try:
                    _set_frame_event(ctrl, event_id, True)
                    pipeline = ctrl.GetPipelineState()
                    live_shader = pipeline.GetShader(stage)
                    if _resource_id_int(live_shader) != shader_id:
                        failures[index] = "the Shader bound at the alias EID changed"
                        continue
                    entries = list(ctrl.GetShaderEntryPoints(live_shader) or [])
                    selected = next((
                        entry for entry in entries
                        if str(getattr(entry, "name", "") or "") == entry_point
                    ), None)
                    if selected is None:
                        failures[index] = "the Shader entry point at the alias EID changed"
                        continue
                    reflection = ctrl.GetShader(
                        _get_pipeline_obj(pipeline, ctrl), live_shader, selected)
                    if reflection is None:
                        failures[index] = "Shader reflection is unavailable at the alias EID"
                        continue
                    try:
                        bindings = pipeline.GetReadOnlyResources(stage)
                    except Exception:
                        bindings = None
                    matches = []
                    for slot_index, resource in enumerate(
                            getattr(reflection, "readOnlyResources", []) or []):
                        if not getattr(resource, "isTexture", False):
                            continue
                        live_bind = _safe_int(
                            getattr(resource, "fixedBindNumber", slot_index), slot_index)
                        live_space = _safe_int(
                            getattr(resource, "fixedBindSetOrSpace", 0), 0)
                        if live_bind != bind_number or live_space != register_space:
                            continue
                        for exact in _exact_readonly_descriptor_resources(
                                bindings, slot_index):
                            if (exact["resourceId"] == target_id and
                                    (requested_array is None or
                                     exact["arrayElement"] == requested_array)):
                                matches.append((
                                    slot_index, exact["arrayElement"],
                                    exact["descriptorStoreId"]))
                    if not matches:
                        failures[index] = (
                            "texture resource is not exactly bound at the authorized register")
                        continue
                    verified.add(index)
                except Exception as exc:
                    failures[index] = str(exc)
        finally:
            if restore_original_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass
        return verified, failures

    return _replay(_do)


def _shader_raw_bytes(refl):
    raw = getattr(refl, "rawBytes", b"")
    if raw is None:
        return b""
    if isinstance(raw, bytes):
        return raw
    try:
        return bytes(raw)
    except Exception:
        try:
            return bytearray(raw)
        except Exception:
            return b""


def _shader_type_name(shader_type):
    if shader_type is None:
        return "unknown"
    base = str(getattr(shader_type, "baseType", getattr(shader_type, "type", "unknown")))
    rows = _safe_int(getattr(shader_type, "rows", 1), 1)
    columns = _safe_int(getattr(shader_type, "columns", 1), 1)
    elements = _safe_int(getattr(shader_type, "elements", 1), 1)
    result = base
    if rows > 1 and columns > 1:
        result += "%dx%d" % (rows, columns)
    elif max(rows, columns) > 1:
        result += "%d" % max(rows, columns)
    if elements > 1:
        result += "[%d]" % elements
    return result


def _shader_type_info(shader_type):
    if shader_type is None:
        return {
            "name": "", "baseType": "unknown", "rows": 0, "columns": 0,
            "elements": 0, "arrayByteStride": 0, "matrixByteStride": 0,
            "rowMajor": False, "flags": 0, "flagsText": "0",
        }

    flags = getattr(shader_type, "flags", 0)
    row_major = False
    try:
        row_major_fn = getattr(shader_type, "RowMajor")
        row_major = bool(row_major_fn() if callable(row_major_fn) else row_major_fn)
    except Exception:
        row_major = "rowmajor" in str(flags).replace("_", "").lower()

    return {
        "name": str(getattr(shader_type, "name", "")),
        "baseType": str(getattr(shader_type, "baseType", getattr(shader_type, "type", "unknown"))),
        "rows": _safe_int(getattr(shader_type, "rows", 1), 1),
        "columns": _safe_int(getattr(shader_type, "columns", 1), 1),
        "elements": _safe_int(getattr(shader_type, "elements", 1), 1),
        "arrayByteStride": _safe_int(getattr(shader_type, "arrayByteStride", 0), 0),
        "matrixByteStride": _safe_int(getattr(shader_type, "matrixByteStride", 0), 0),
        "rowMajor": row_major,
        "flags": _safe_int(flags, 0),
        "flagsText": str(flags),
    }


def _shader_type_is_empty_struct(shader_type):
    """A reflected empty declaration occupies no storage or ABI field."""
    return (shader_type is not None and
            str(getattr(shader_type, "baseType", "")).lower() in ("struct", "vartype.struct") and
            not list(getattr(shader_type, "members", []) or []) and
            _safe_int(getattr(shader_type, "rows", -1), -1) == 0 and
            _safe_int(getattr(shader_type, "columns", -1), -1) == 0 and
            _safe_int(getattr(shader_type, "elements", 0), 0) == 1 and
            _safe_int(getattr(shader_type, "arrayByteStride", -1), -1) == 0 and
            _safe_int(getattr(shader_type, "matrixByteStride", -1), -1) == 0 and
            _safe_int(getattr(shader_type, "pointerTypeID", 0xFFFFFFFF), 0xFFFFFFFF) == 0xFFFFFFFF)


def _shader_type_byte_size(shader_type):
    if shader_type is None:
        return 0
    if _shader_type_is_empty_struct(shader_type):
        return 0
    elements = max(_safe_int(getattr(shader_type, "elements", 1), 1), 1)
    array_stride = _safe_int(getattr(shader_type, "arrayByteStride", 0), 0)
    # RenderDoc uses ~0U for a runtime-sized SPIR-V array. Its capacity comes
    # from the bound buffer, not from reflection. Preserve the sentinel/stride
    # separately and report only the fixed prefix, never stride * ~0U.
    if elements == 0xFFFFFFFF:
        return 0

    members = getattr(shader_type, "members", []) or []
    if members:
        end = 0
        for member in members:
            member_end = (_safe_int(getattr(member, "byteOffset", 0), 0) +
                          _shader_type_byte_size(getattr(member, "type", None)))
            end = max(end, member_end)
        return ((elements - 1) * array_stride + end
                if elements > 1 and array_stride > 0 else end * elements)

    rows = max(_safe_int(getattr(shader_type, "rows", 1), 1), 1)
    columns = max(_safe_int(getattr(shader_type, "columns", 1), 1), 1)
    matrix_stride = _safe_int(getattr(shader_type, "matrixByteStride", 0), 0)
    if rows > 1 and columns > 1 and matrix_stride > 0:
        info = _shader_type_info(shader_type)
        major_count = rows if info["rowMajor"] else columns
        minor_count = columns if info["rowMajor"] else rows
    else:
        major_count = 1
        minor_count = rows * columns

    base = str(getattr(shader_type, "baseType", "")).lower()
    component_size = 4
    if "double" in base or "slong" in base or "ulong" in base:
        component_size = 8
    elif "half" in base or "short" in base:
        component_size = 2
    elif "byte" in base and "byteaddress" not in base:
        component_size = 1
    # The final row/column/array element does not own its trailing alignment
    # padding. HLSL may place the next variable there (for example float2 after
    # a float2x2 with 16-byte row stride). Keep strides separately from extent.
    element_size = (major_count - 1) * matrix_stride + minor_count * component_size
    return ((elements - 1) * array_stride + element_size
            if elements > 1 and array_stride > 0 else element_size * elements)


def _shader_constant_fields(constants, prefix="", parent_offset=0, depth=0):
    """Serialise ShaderConstant trees with paths plus relative and absolute offsets."""
    if depth > 32:
        return []

    fields = []
    for index, constant in enumerate(constants or []):
        name = str(getattr(constant, "name", "")) or "field%d" % index
        path = name if not prefix else "%s.%s" % (prefix, name)
        relative_offset = _safe_int(getattr(constant, "byteOffset", 0), 0)
        absolute_offset = parent_offset + relative_offset
        shader_type = getattr(constant, "type", None)
        if _shader_type_is_empty_struct(shader_type):
            # Native DXIL includes empty declarations at the next member's
            # offset. They carry no bytes and must not fabricate an overlap.
            continue
        type_info = _shader_type_info(shader_type)
        field = {
            "path": path,
            "name": name,
            "offset": relative_offset,
            "byteOffset": relative_offset,
            "absoluteByteOffset": absolute_offset,
            "relativeOffset": relative_offset,
            "type": _shader_type_name(shader_type),
            "baseType": type_info["baseType"],
            "byteSize": _shader_type_byte_size(shader_type),
            "rows": type_info["rows"],
            "columns": type_info["columns"],
            "elements": type_info["elements"],
            "arrayByteStride": type_info["arrayByteStride"],
            "matrixByteStride": type_info["matrixByteStride"],
            "rowMajor": type_info["rowMajor"],
            "flags": type_info["flags"],
            "pointerTypeID": _safe_int(
                getattr(shader_type, "pointerTypeID", 0xFFFFFFFF), 0xFFFFFFFF),
            "typeInfo": type_info,
        }

        bit_offset = _safe_int(getattr(constant, "bitFieldOffset", 0), 0)
        bit_size = _safe_int(getattr(constant, "bitFieldSize", 0), 0)
        if bit_offset or bit_size:
            field["bitFieldOffset"] = bit_offset
            field["bitFieldSize"] = bit_size

        members = getattr(shader_type, "members", []) if shader_type is not None else []
        if members:
            field["members"] = _shader_constant_fields(
                members, prefix=path, parent_offset=absolute_offset, depth=depth + 1)
        fields.append(field)
    return fields


def _constant_field_annotations_are_complete(fields, parent_byte_size, depth=0):
    """Return whether a reflected CBuffer member tree is a physical layout.

    Stripped DXIL commonly exposes an opaque block as one or more ``unknown``
    placeholders.  Those placeholders describe a best-effort storage shape, not
    source member annotations: they may have zero elements, overlap at offset 0,
    or extend beyond ``ConstantBlock.byteSize``.  They must never be promoted to
    ABI fields.
    """
    if depth > 32 or parent_byte_size < 0:
        return False
    if not fields:
        return True

    ranges = []
    for field in fields:
        byte_offset = _safe_int(field.get("byteOffset"), -1)
        byte_size = _safe_int(field.get("byteSize"), -1)
        rows = _safe_int(field.get("rows"), 0)
        columns = _safe_int(field.get("columns"), 0)
        elements = _safe_int(field.get("elements"), 0)
        base_type = _physical_base_type(field.get("baseType"))
        members = list(field.get("members", []) or [])
        aggregate = base_type == "struct" and bool(members)
        if (byte_offset < 0 or byte_size <= 0 or
                (not aggregate and (rows <= 0 or columns <= 0)) or
                rows < 0 or columns < 0 or elements <= 0 or
                base_type in ("", "unknown")):
            return False
        if byte_offset + byte_size > parent_byte_size:
            return False

        # Native SPIR-V struct reflection has rows=columns=0. Its members,
        # offsets and array stride define the layout, not scalar dimensions.
        # Validate children against one array element, never the whole array.
        member_limit = byte_size
        if aggregate and elements > 1:
            stride = _safe_int(field.get("arrayByteStride"), 0)
            if stride <= 0 or stride * (elements - 1) >= byte_size:
                return False
            member_limit = min(stride, byte_size - stride * (elements - 1))
        if members and not _constant_field_annotations_are_complete(
                members, member_limit, depth + 1):
            return False

        bit_offset = _safe_int(field.get("bitFieldOffset"), 0)
        bit_size = _safe_int(field.get("bitFieldSize"), 0)
        if bit_size:
            if bit_offset < 0 or bit_size < 0 or bit_offset + bit_size > byte_size * 8:
                return False
            start = byte_offset * 8 + bit_offset
            end = start + bit_size
        else:
            if bit_offset:
                return False
            start = byte_offset * 8
            end = (byte_offset + byte_size) * 8
        ranges.append((start, end))

    ranges.sort()
    previous_end = -1
    for start, end in ranges:
        if start < previous_end:
            return False
        previous_end = end
    return True


def _constant_block_layout(cb):
    """Preserve every usable CBuffer member without inventing opaque layout.

    An empty result means the block is opaque.  Its register/space/count and
    ``byteSize`` remain authoritative physical ABI facts.  The legacy opaque
    downgrade is deliberately narrow: an all-``unknown``/unnamed-type tree is
    opaque only when it is also structurally invalid (zero elements,
    out-of-range, overlapping, etc.).  A physically complete unnamed tree is
    retained and compared strictly.  In mixed trees, malformed anonymous
    placeholders never erase otherwise known fields.
    """
    fields = _shader_constant_fields(getattr(cb, "variables", []))
    byte_size = _safe_int(getattr(cb, "byteSize", 0), 0)
    if not fields:
        return fields, "opaque"
    if _constant_field_annotations_are_complete(fields, byte_size):
        return fields, "complete"
    retained = []
    for field in fields:
        legacy_unknown = (
            str(field.get("name", "") or "").strip().lower() == "unknown" and
            not str((field.get("typeInfo") or {}).get("name", "") or "").strip()
        )
        if not _constant_field_annotations_are_complete([field], byte_size):
            continue
        retained.append(field)
    retained = _drop_conflicting_legacy_unknown_fields(retained)
    # Any discarded/contradictory annotation means the captured layout was not
    # fully knowable. Keep usable fields for inspection, but mark the whole
    # block apply-ineligible rather than silently treating it as ordinary
    # envelope-only opaque data.
    return retained, "ambiguous"


def _constant_block_fields(cb):
    return _constant_block_layout(cb)[0]


def _constant_field_bit_range(field):
    byte_offset = _safe_int(field.get("byteOffset"), -1)
    byte_size = _safe_int(field.get("byteSize"), -1)
    if byte_offset < 0 or byte_size <= 0:
        return None
    bit_offset = _safe_int(field.get("bitFieldOffset"), 0)
    bit_size = _safe_int(field.get("bitFieldSize"), 0)
    if bit_size:
        return (byte_offset * 8 + bit_offset,
                byte_offset * 8 + bit_offset + bit_size)
    return (byte_offset * 8, (byte_offset + byte_size) * 8)


def _drop_conflicting_legacy_unknown_fields(fields):
    """Keep non-overlapping anonymous ranges; discard only ambiguous ones."""
    legacy = []
    known = []
    for index, field in enumerate(fields):
        is_legacy = (
            str(field.get("name", "") or "").strip().lower() == "unknown" and
            not str((field.get("typeInfo") or {}).get("name", "") or "").strip()
        )
        entry = (index, _constant_field_bit_range(field), field)
        (legacy if is_legacy else known).append(entry)
    dropped = set()
    for legacy_index, legacy_range, unused_field in legacy:
        if legacy_range is None:
            dropped.add(legacy_index)
            continue
        for unused_known_index, known_range, unused_known_field in known:
            if (known_range is not None and legacy_range[0] < known_range[1] and
                    known_range[0] < legacy_range[1]):
                dropped.add(legacy_index)
                break
    for left_position, left in enumerate(legacy):
        left_index, left_range, left_field = left
        if left_range is None:
            continue
        for right_index, right_range, right_field in legacy[left_position + 1:]:
            if (right_range is None or left_range[0] >= right_range[1] or
                    right_range[0] >= left_range[1]):
                continue
            if left_range == right_range and left_field == right_field:
                dropped.add(right_index)
            else:
                dropped.add(left_index)
                dropped.add(right_index)
    return [field for index, field in enumerate(fields) if index not in dropped]


def _shader_constant_type_dict(shader_type):
    """Serialise the physical shape of a ShaderConstantType without trusting its name."""
    info = _shader_type_info(shader_type)
    members = getattr(shader_type, "members", []) if shader_type is not None else []
    # SPIR-V storage-buffer wrappers use Float/0/0 in native reflection even
    # though their member tree is a struct. Canonicalise that aggregate shape.
    if members and info["rows"] == 0 and info["columns"] == 0:
        info["baseType"] = "VarType.Struct"
    return {
        "name": info["name"],
        "baseType": info["baseType"],
        "rows": info["rows"],
        "columns": info["columns"],
        "elements": info["elements"],
        "arrayByteStride": info["arrayByteStride"],
        "matrixByteStride": info["matrixByteStride"],
        "rowMajor": info["rowMajor"],
        "flags": info["flags"],
        "pointerTypeID": _safe_int(getattr(shader_type, "pointerTypeID", 0xFFFFFFFF),
                                   0xFFFFFFFF),
        "byteSize": _shader_type_byte_size(shader_type),
        "members": _shader_constant_fields(members),
    }


def _bound_descriptor_info(bound):
    """Normalise UsedDescriptor, Descriptor, and legacy bound-buffer objects."""
    result = {
        "resourceId": 0,
        "byteOffset": 0,
        "byteSize": 0,
        # Descriptor bindings do not expose a stride. Keep it explicitly
        # unknown instead of manufacturing zero; BoundVBuffer does expose it.
        "byteStride": None,
    }
    if bound is None:
        return result

    descriptor = getattr(bound, "descriptor", None)
    candidates = [descriptor, bound] if descriptor is not None else [bound]
    for candidate in candidates:
        if candidate is None:
            continue
        rid = _resource_id_int(getattr(candidate, "resource", None))
        if not rid:
            rid = _resource_id_int(getattr(candidate, "resourceId", None))
        if rid:
            result["resourceId"] = rid
        if hasattr(candidate, "byteOffset"):
            result["byteOffset"] = _safe_int(getattr(candidate, "byteOffset", 0), 0)
        if hasattr(candidate, "byteSize"):
            result["byteSize"] = _safe_int(getattr(candidate, "byteSize", 0), 0)
        stride = getattr(candidate, "byteStride", None)
        if isinstance(stride, int) and not isinstance(stride, bool) and stride >= 0:
            result["byteStride"] = int(stride)
        if result["resourceId"]:
            break
    return result


def _get_constant_block_binding(ps, stage, block_index):
    """Resolve an exact reflected constant-block index to its current descriptor."""
    if hasattr(ps, "GetConstantBlock"):
        try:
            return _bound_descriptor_info(ps.GetConstantBlock(stage, block_index, 0))
        except Exception:
            pass

    for method_name in ("GetConstantBlocks", "GetConstantBuffers"):
        if not hasattr(ps, method_name):
            continue
        try:
            bindings = getattr(ps, method_name)(stage, False)
            if bindings and block_index < len(bindings):
                return _bound_descriptor_info(bindings[block_index])
        except Exception:
            pass
    return {"resourceId": 0, "byteOffset": 0, "byteSize": 0}


def _constant_block_binding_key(cb, block_index):
    return (
        _safe_int(getattr(cb, "fixedBindSetOrSpace", 0), 0),
        _safe_int(getattr(cb, "fixedBindNumber", block_index), block_index),
    )


def _constant_block_dict(cb, block_index, binding=None, layout_evidence=None,
                         dxbc_declaration=None):
    layout_fields, layout_completeness = _constant_block_layout(cb)
    if layout_evidence is not None:
        # This is a lower-only classification.  The evidence comes from the
        # fixed DXC disassembly and never from display/member names.  Exact
        # original/candidate access tuples are still required by the apply
        # gate before fields may be ignored.
        layout_completeness = "ambiguous"
    block = {
        "index": block_index,
        "name": str(getattr(cb, "name", "")),
        "bind": _safe_int(getattr(cb, "fixedBindNumber", block_index), block_index),
        "space": _safe_int(getattr(cb, "fixedBindSetOrSpace", 0), 0),
        "bindArraySize": _safe_int(getattr(cb, "bindArraySize", 1), 1),
        "byteSize": _safe_int(getattr(cb, "byteSize", 0), 0),
        "bufferBacked": bool(getattr(cb, "bufferBacked", True)),
        "inlineDataBytes": bool(getattr(cb, "inlineDataBytes", False)),
        "compileConstants": bool(getattr(cb, "compileConstants", False)),
        "fields": layout_fields,
        "layoutCompleteness": layout_completeness,
    }
    if dxbc_declaration is not None and layout_evidence is None:
        # Inspect the untouched fallback tree: the strict layout serializer has
        # already dropped native zero-element placeholders. Only exact raw
        # declaration + native fallback agreement permits an opaque envelope.
        original = dict(block)
        original["fields"] = _shader_constant_fields(getattr(cb, "variables", []))
        if _dxbc_cbuffer_layout.matches_synthetic_fields(original, dxbc_declaration):
            block["fields"] = []
            block["layoutCompleteness"] = "opaque"
            block["layoutEvidence"] = dict(dxbc_declaration)
    if layout_evidence is not None:
        block["layoutEvidence"] = dict(layout_evidence)
    if binding is not None:
        block["binding"] = binding
    return block


def _signature_parameter_dict(parameter):
    reg_channel_mask = _safe_int(getattr(parameter, "regChannelMask", 0), 0)
    component_count = _safe_int(getattr(parameter, "compCount", 0), 0)
    if component_count <= 0 and reg_channel_mask:
        component_count = bin(reg_channel_mask & 0xF).count("1")
    return {
        "varName": str(getattr(parameter, "varName", "")),
        "semanticName": str(getattr(parameter, "semanticName", "")),
        "semanticIdxName": str(getattr(parameter, "semanticIdxName", "")),
        "semanticIndex": _safe_int(getattr(parameter, "semanticIndex", 0), 0),
        "regIndex": _safe_int(getattr(parameter, "regIndex", -1), -1),
        "systemValue": str(getattr(parameter, "systemValue", "")),
        "compType": str(getattr(parameter, "varType", getattr(parameter, "compType", ""))),
        "compCount": component_count,
        "stream": _safe_int(getattr(parameter, "stream", 0), 0),
        "regChannelMask": reg_channel_mask,
        "channelUsedMask": _safe_int(getattr(parameter, "channelUsedMask", 0), 0),
        "perPrimitiveRate": bool(getattr(parameter, "perPrimitiveRate", False)),
        "needSemanticIndex": bool(getattr(parameter, "needSemanticIndex", False)),
    }


def _shader_binding_dict(binding, dxbc_declaration=None):
    descriptor_type = str(getattr(binding, "descriptorType", ""))
    result = {
        "name": str(getattr(binding, "name", "")),
        "space": _safe_int(getattr(binding, "fixedBindSetOrSpace", 0), 0),
        "bind": _safe_int(getattr(binding, "fixedBindNumber", -1), -1),
        "arraySize": _safe_int(getattr(binding, "bindArraySize", 1), 1),
        # resourceType is retained as a compatibility alias for older Host snapshots. The
        # authoritative RenderDoc field is descriptorType.
        "resourceType": descriptor_type,
        "descriptorType": descriptor_type,
        "textureType": str(getattr(binding, "textureType", "")),
        "variableType": _shader_constant_type_dict(
            getattr(binding, "variableType", None)),
        "isTexture": bool(getattr(binding, "isTexture", False)),
        "hasSampler": bool(getattr(binding, "hasSampler", False)),
        "isInputAttachment": bool(getattr(binding, "isInputAttachment", False)),
        "isReadOnly": bool(getattr(binding, "isReadOnly", False)),
    }
    variable = result['variableType']
    if (dxbc_declaration is not None and not result['isTexture'] and
            result['arraySize'] == dxbc_declaration['bindArraySize'] and
            _physical_base_type(variable['baseType']) == 'unknown' and
            variable['rows'] == 0 and variable['columns'] == 0 and
            variable['elements'] == 0 and not variable['members']):
        variable.update(elements=1, byteSize=dxbc_declaration['byteSize'],
            arrayByteStride=dxbc_declaration['byteSize'], layoutCompleteness='opaque')
        result['layoutEvidence'] = dict(dxbc_declaration)
    return result


def _shader_sampler_dict(sampler):
    return {
        "name": str(getattr(sampler, "name", "")),
        "space": _safe_int(getattr(sampler, "fixedBindSetOrSpace", 0), 0),
        "bind": _safe_int(getattr(sampler, "fixedBindNumber", -1), -1),
        "arraySize": _safe_int(getattr(sampler, "bindArraySize", 1), 1),
    }


def _thread_group_size(reflection):
    # Only workgroup stages populate this native field. Some producers leave
    # it uninitialized for other stages; do not read those bytes.
    if _known_stage_name(reflection) not in ("compute", "task", "mesh"):
        return []
    value = getattr(reflection, "dispatchThreadsDimension", None)
    if value is None:
        return []
    try:
        values = [_safe_int(value[index], 0) for index in range(3)]
        return values if any(values) else []
    except Exception:
        try:
            values = list(value)
            values = [_safe_int(item, 0) for item in values[:3]]
            return values if any(values) else []
        except Exception:
            return []


def _compiled_shader_interface(reflection, dxil_layout_evidence=None):
    """Serialise only physical compiled-interface facts from ShaderReflection."""
    evidence = dxil_layout_evidence or {}
    dxbc_declarations = _dxbc_cbuffer_layout.declarations(_shader_raw_bytes(reflection))
    constant_blocks = [
        _constant_block_dict(
            value,
            index,
            layout_evidence=evidence.get(
                _constant_block_binding_key(value, index)),
            dxbc_declaration=dxbc_declarations.get(_constant_block_binding_key(value, index)),
        )
        for index, value in enumerate(getattr(reflection, "constantBlocks", []))
    ]
    interface = {
        "interfaceComplete": not any(
            block.get("layoutCompleteness") == "ambiguous"
            for block in constant_blocks),
        "stage": _known_stage_name(reflection),
        "entryPoint": str(getattr(reflection, "entryPoint", "") or ""),
        "encoding": _native_enum_text(getattr(reflection, "encoding", None)),
        "inputSignature": [
            _signature_parameter_dict(value)
            for value in getattr(reflection, "inputSignature", [])
        ],
        "outputSignature": [
            _signature_parameter_dict(value)
            for value in getattr(reflection, "outputSignature", [])
        ],
        "readOnlyResources": [
            _shader_binding_dict(value, dxbc_declarations.get(('srv',) + _constant_block_binding_key(value, -1)))
            for value in getattr(reflection, "readOnlyResources", [])
        ],
        "readWriteResources": [
            _shader_binding_dict(value, dxbc_declarations.get(('uav',) + _constant_block_binding_key(value, -1)))
            for value in getattr(reflection, "readWriteResources", [])
        ],
        "samplers": [
            _shader_sampler_dict(value)
            for value in getattr(reflection, "samplers", [])
        ],
        "constantBlocks": constant_blocks,
        "dynamicLinkageInterfaceCount": len(
            getattr(reflection, "interfaces", []) or []),
        "outputTopology": _native_enum_text(getattr(reflection, "outputTopology", None)),
        "threadGroupSize": _thread_group_size(reflection),
    }
    return interface


def _native_enum_text(value):
    """Native enums may have a valid zero value; only None denotes absence."""
    return "" if value is None else str(value)


def _physical_enum(value):
    return (_native_enum_text(value).strip().lower().rsplit(".", 1)[-1]
            .replace("_", "").replace(" ", ""))


def _shader_encoding_token(value):
    token = _physical_enum(value).replace("-", "")
    return {
        "directxbytecode": "dxbc",
        "directxil": "dxil",
        "dxilcontainer": "dxil",
        "spv": "spirv",
        "spirvshader": "spirv",
        "openglspirv": "opengl-spirv",
    }.get(token, token)


def _physical_base_type(value):
    token = _physical_enum(value)
    return {
        "float32": "float",
        "single": "float",
        "sint": "int",
        "signedint": "int",
        "int32": "int",
        "unsignedint": "uint",
        "uint32": "uint",
        "float16": "half",
        "min16float": "half",
        "float64": "double",
    }.get(token, token)


def _physical_sorted(values):
    return sorted(
        values,
        key=lambda item: json.dumps(
            item, ensure_ascii=False, sort_keys=True,
            separators=(",", ":")),
    )


def _physical_constant_field(field):
    """Remove reflection/debug names while retaining exact CBuffer packing."""
    return {
        "byteOffset": _safe_int(field.get("byteOffset"), 0),
        "byteSize": _safe_int(field.get("byteSize"), 0),
        "baseType": _physical_base_type(field.get("baseType")),
        "rows": _safe_int(field.get("rows"), 0),
        "columns": _safe_int(field.get("columns"), 0),
        "elements": _safe_int(field.get("elements"), 0),
        "arrayByteStride": _safe_int(field.get("arrayByteStride"), 0),
        "matrixByteStride": _safe_int(field.get("matrixByteStride"), 0),
        "rowMajor": bool(field.get("rowMajor", False)),
        "flags": _safe_int(field.get("flags"), 0),
        "pointerTypeID": _safe_int(field.get("pointerTypeID"), 0xFFFFFFFF),
        "bitFieldOffset": _safe_int(field.get("bitFieldOffset"), 0),
        "bitFieldSize": _safe_int(field.get("bitFieldSize"), 0),
        "members": _physical_sorted([
            _physical_constant_field(member)
            for member in list(field.get("members", []) or [])
        ]),
    }


def _physical_variable_type(value):
    value = value if isinstance(value, dict) else {}
    result = {
        "baseType": _physical_base_type(value.get("baseType")),
        "rows": _safe_int(value.get("rows"), 0),
        "columns": _safe_int(value.get("columns"), 0),
        "elements": _safe_int(value.get("elements"), 0),
        "arrayByteStride": _safe_int(value.get("arrayByteStride"), 0),
        "matrixByteStride": _safe_int(value.get("matrixByteStride"), 0),
        "rowMajor": bool(value.get("rowMajor", False)),
        "flags": _safe_int(value.get("flags"), 0),
        "pointerTypeID": _safe_int(value.get("pointerTypeID"), 0xFFFFFFFF),
        "byteSize": _safe_int(value.get("byteSize"), 0),
        "members": _physical_sorted([
            _physical_constant_field(member)
            for member in list(value.get("members", []) or [])
        ]),
    }
    if value.get('layoutCompleteness') == 'opaque':
        result['layoutCompleteness'] = 'opaque'
    return result


def _physical_shader_interface(interface):
    """Canonical compiled ABI used to prove Shader-family compatibility.

    Display/debug identifiers (resource, CBuffer and local variable names) are
    deliberately excluded. Semantic names, registers, descriptor kinds,
    complete CBuffer packing, topology and compute group size remain physical.
    This mirrors the Host ABI gate and lets the Bridge reject a forged ABI
    report before configuring any replay override.
    """
    if not isinstance(interface, dict):
        raise RuntimeError("Shader compiled interface is unavailable")

    def _signature(item):
        return {
            "semanticName": str(item.get("semanticName", "") or "").lower(),
            "semanticIdxName": str(
                item.get("semanticIdxName", "") or "").lower(),
            "semanticIndex": _safe_int(item.get("semanticIndex"), 0),
            "regIndex": _safe_int(item.get("regIndex"), -1),
            "systemValue": _physical_enum(item.get("systemValue")),
            "compType": _physical_base_type(item.get("compType")),
            "compCount": _safe_int(item.get("compCount"), 0),
            "stream": _safe_int(item.get("stream"), 0),
            "regChannelMask": _safe_int(item.get("regChannelMask"), 0),
            # channelUsedMask is compiler data-flow analysis, not part of the
            # declared linkage ABI. Packed DXIL may report aggregate usage for
            # every row while a source recompile reports each row separately.
            # Keep it in raw reflection above for audit, but do not hash or
            # reject a replacement solely because this analysis changed.
            "perPrimitiveRate": bool(item.get("perPrimitiveRate", False)),
            "needSemanticIndex": bool(item.get("needSemanticIndex", False)),
        }

    def _binding(item):
        return {
            "space": _safe_int(item.get("space"), 0),
            "bind": _safe_int(item.get("bind"), -1),
            "arraySize": _safe_int(item.get("arraySize"), 0),
            "descriptorType": _physical_enum(item.get("descriptorType")),
            "textureType": _physical_enum(item.get("textureType")),
            "variableType": _physical_variable_type(item.get("variableType")),
            "isTexture": bool(item.get("isTexture", False)),
            "hasSampler": bool(item.get("hasSampler", False)),
            "isInputAttachment": bool(item.get("isInputAttachment", False)),
            "isReadOnly": bool(item.get("isReadOnly", False)),
        }

    def _sampler(item):
        return {
            "space": _safe_int(item.get("space"), 0),
            "bind": _safe_int(item.get("bind"), -1),
            "arraySize": _safe_int(item.get("arraySize"), 0),
        }

    def _block(item):
        fields = _physical_sorted([
            _physical_constant_field(field)
            for field in list(item.get("fields", []) or [])
        ])
        completeness = str(item.get("layoutCompleteness", "") or "").strip().lower()
        if completeness not in ("complete", "partial", "opaque", "ambiguous"):
            completeness = "complete" if fields else "opaque"
        return {
            "space": _safe_int(item.get("space"), 0),
            "bind": _safe_int(item.get("bind"), -1),
            "bindArraySize": _safe_int(item.get("bindArraySize"), 0),
            "byteSize": _safe_int(item.get("byteSize"), 0),
            "bufferBacked": bool(item.get("bufferBacked", False)),
            "inlineDataBytes": bool(item.get("inlineDataBytes", False)),
            "compileConstants": bool(item.get("compileConstants", False)),
            "fields": fields,
            "layoutCompleteness": completeness,
        }

    return {
        "stage": _normalise_stage_name(interface.get("stage")),
        "entryPoint": str(interface.get("entryPoint", "") or ""),
        "inputSignature": _physical_sorted([
            _signature(item)
            for item in list(interface.get("inputSignature", []) or [])
        ]),
        "outputSignature": _physical_sorted([
            _signature(item)
            for item in list(interface.get("outputSignature", []) or [])
        ]),
        "readOnlyResources": _physical_sorted([
            _binding(item)
            for item in list(interface.get("readOnlyResources", []) or [])
        ]),
        "readWriteResources": _physical_sorted([
            _binding(item)
            for item in list(interface.get("readWriteResources", []) or [])
        ]),
        "samplers": _physical_sorted([
            _sampler(item)
            for item in list(interface.get("samplers", []) or [])
        ]),
        "constantBlocks": _physical_sorted([
            _block(item)
            for item in list(interface.get("constantBlocks", []) or [])
        ]),
        "threadGroupSize": [
            _safe_int(item, 0)
            for item in list(interface.get("threadGroupSize", []) or [])
        ],
        "outputTopology": _physical_enum(interface.get("outputTopology")),
        "dynamicLinkageInterfaceCount": _safe_int(
            interface.get("dynamicLinkageInterfaceCount"), 0),
    }


def _physical_shader_interface_sha256(reflection, dxil_layout_evidence=None):
    return _canonical_json_sha256(
        _physical_shader_interface(_compiled_shader_interface(
            reflection, dxil_layout_evidence)))


def _ambiguous_dxil_access_block_matches(captured, candidate,
                                         baseline_access, candidate_access):
    """Require exact static DXIL loads for one captured ambiguous CBuffer."""
    if baseline_access is None or candidate_access is None:
        return False
    space = _safe_int(captured.get("space"), -1)
    bind = _safe_int(captured.get("bind"), -1)
    baseline_block = baseline_access.block(space, bind)
    candidate_block = candidate_access.block(space, bind)
    if baseline_block is None or candidate_block is None:
        return False
    if (captured.get("space") != candidate.get("space") or
            captured.get("bind") != candidate.get("bind") or
            captured.get("bindArraySize") != 1 or
            candidate.get("bindArraySize") != 1 or
            baseline_block.space != space or
            candidate_block.space != space or
            baseline_block.bind != bind or
            candidate_block.bind != bind or
            baseline_block.bind_array_size != captured.get("bindArraySize") or
            candidate_block.bind_array_size != candidate.get("bindArraySize") or
            baseline_block.byte_size != captured.get("byteSize") or
            candidate_block.byte_size != candidate.get("byteSize") or
            not baseline_block.accesses or not candidate_block.accesses):
        return False
    # Ambiguous captured CBuffer layouts are proven only by the exact static
    # load tuples the shader issues. An intentional source edit may make a
    # previously-live load dead (e.g. a new output overwrites an earlier one,
    # so its input read is eliminated), leaving the candidate with a strict
    # SUBSET of the captured loads. Every candidate load still matches a
    # captured load exactly (same byte offset, width and return type) and stays
    # inside the captured access envelope, so it remains consistent with the
    # same ambiguous layout and the identically-bound, identically-sized block:
    # the replacement is safe. Loads the original never issued cannot be
    # verified against an ambiguous layout, so a superset is still rejected.
    baseline_accesses = set(baseline_block.accesses)
    candidate_accesses = set(candidate_block.accesses)
    if not candidate_accesses.issubset(baseline_accesses):
        return False
    if (candidate_block.envelope_start < baseline_block.envelope_start or
            candidate_block.envelope_end > baseline_block.envelope_end):
        return False
    return True


_INTERFACE_STRUCTURAL_KEYS = (
    "stage", "entryPoint", "threadGroupSize",
    "outputTopology", "dynamicLinkageInterfaceCount",
)
_INTERFACE_USAGE_KEYS = (
    "inputSignature", "outputSignature",
    "readOnlyResources", "readWriteResources", "samplers",
)


def _interface_incompatibilities(baseline, candidate):
    """Real physical incompatibilities of a candidate against the captured ABI.

    Mirrors the Host gate (shader_workspace/abi.py). A replay replacement is
    safe when its interface stays WITHIN the captured pipeline's: identical
    fixed structure (stage/entry/thread-group/topology/linkage) and, for every
    constant buffer it still uses, the same binding space/register and byte
    size. Input/output signatures and resource/sampler bindings need only be a
    SUBSET of what the capture provides. Which CBuffer fields or resources the
    shader reads is an implementation detail -- adding, removing or reworking
    code (including letting the optimiser drop a now-unreferenced resource) is
    allowed while it compiles and stays inside that envelope. Only needing
    something the capture does not provide -- a new input/output slot, a new
    resource/sampler binding, a new constant buffer, or a different constant-
    buffer size -- is a genuine ABI failure.
    """
    differences = []
    for key in _INTERFACE_STRUCTURAL_KEYS:
        # Historical bridges dropped the false-valued Topology.Unknown enum.
        # Interpret its two spellings only for comparison: persisted physical
        # hashes and signed restore evidence must keep their original bytes.
        if (key == "outputTopology" and key in baseline and key in candidate and
                baseline[key] in ("", "unknown") and
                candidate[key] in ("", "unknown")):
            continue
        if baseline.get(key) != candidate.get(key):
            differences.append(key)
            return differences
    for key in _INTERFACE_USAGE_KEYS:
        available = list(baseline.get(key, []) or [])
        requested = [dict(entry) for entry in candidate.get(key, []) or []]
        if key in ('readOnlyResources', 'readWriteResources'):
            _dxbc_cbuffer_layout.project_opaque_resource_types(available, requested)
        for entry in requested:
            if entry not in available:
                differences.append(key)
                return differences
    baseline_blocks = {
        (block.get("space"), block.get("bind")): block
        for block in baseline.get("constantBlocks", []) or []
    }
    for block in candidate.get("constantBlocks", []) or []:
        captured = baseline_blocks.get((block.get("space"), block.get("bind")))
        if captured is None:
            differences.append("constantBlocks")
            return differences
        # Mirror the Host gate: a non-ambiguous captured layout keeps its exact
        # member facts (a code edit never changes the declared CBuffer struct),
        # while an ambiguous block is compared on its binding/byte-size envelope
        # only. Opaque/partial captured layouts are projected the same way the
        # Host projects them before the whole-block comparison.
        cap = dict(captured)
        cand = dict(block)
        completeness = cap.get("layoutCompleteness", "complete")
        if completeness == "ambiguous":
            cap["fields"] = []
            cand["fields"] = []
            cand["layoutCompleteness"] = "ambiguous"
        elif completeness == "opaque":
            cand["fields"] = []
            cand["layoutCompleteness"] = "opaque"
        elif completeness == "partial":
            cap_fields = cap.get("fields", []) or []
            if all(field in (cand.get("fields", []) or []) for field in cap_fields):
                cand["fields"] = list(cap_fields)
                cand["layoutCompleteness"] = "partial"
        if cap != cand:
            differences.append("constantBlocks")
            return differences
    return differences


def _physical_shader_interfaces_compatible(
        baseline_reflection, candidate_reflection,
        baseline_dxil_access=None, candidate_dxil_access=None,
        baseline_dxil_layout_evidence=None,
        candidate_dxil_layout_evidence=None):
    """True when the candidate interface stays within the captured pipeline's.

    Only the fixed structure and each used CBuffer's binding/byte size must
    match; input/output signatures and resource/sampler bindings need only be a
    subset. CBuffer field/access patterns are implementation details and are not
    compared, so an intentional source edit that adds, removes or reworks code
    (or lets the optimiser drop an unreferenced resource) replaces safely as
    long as it compiles and needs nothing the capture does not already provide.
    """
    baseline = _physical_shader_interface(
        _compiled_shader_interface(
            baseline_reflection, baseline_dxil_layout_evidence))
    candidate = _physical_shader_interface(
        _compiled_shader_interface(
            candidate_reflection, candidate_dxil_layout_evidence))
    return not _interface_incompatibilities(baseline, candidate)


_DXIL_ACCESS_DISASSEMBLY_TARGET = "DXC DXIL"


def _dxil_layout_evidence_for_all_blocks(
        reflection, status, source_sha256=None, access_signature_sha256=None):
    result = {}
    for index, block in enumerate(
            list(getattr(reflection, "constantBlocks", []) or [])):
        key = (
            _safe_int(getattr(block, "fixedBindSetOrSpace", 0), 0),
            _safe_int(getattr(block, "fixedBindNumber", index), index),
        )
        marker = {
            "kind": "dxc-dxil-buffer-definition",
            "typeAnnotation": status,
        }
        if source_sha256:
            marker["sourceSha256"] = source_sha256
        if access_signature_sha256:
            marker["accessSignatureSha256"] = access_signature_sha256
        result[key] = marker
    return result


def _dxil_layout_evidence_for_reflection_ambiguity(reflection):
    """Mark only structurally ambiguous reflected blocks without disassembling.

    Host validation already derives the candidate DXIL access signature from
    the immutable, hash-bound fixed-DXC job produced by compilation. Re-running
    RenderDoc's textual DXIL printer here duplicated that proof on every save
    and was substantially slower than target reflection itself. This lower-only
    marker keeps a genuinely incomplete RenderDoc reflection fail-closed while
    allowing complete candidate layouts to remain complete. The mutation path
    still performs its independent live DXIL access comparison immediately
    before replacement.
    """

    evidence = {}
    for index, block in enumerate(
            list(getattr(reflection, "constantBlocks", []) or [])):
        unused_fields, completeness = _constant_block_layout(block)
        if completeness != "ambiguous":
            continue
        key = _constant_block_binding_key(block, index)
        evidence[key] = {
            "kind": "dxc-dxil-buffer-definition",
            "typeAnnotation": "unavailable",
        }
    return evidence


def _dxil_disassembly_source(ctrl, pipeline_id, reflection):
    """Return bytes from the one exact RenderDoc-owned DXC target."""
    targets = list(ctrl.GetDisassemblyTargets(True) or [])
    exact_targets = [
        target for target in targets
        if str(target) == _DXIL_ACCESS_DISASSEMBLY_TARGET
    ]
    if len(exact_targets) != 1:
        raise RuntimeError(
            "The replay does not expose one exact 'DXC DXIL' disassembly target")
    source = ctrl.DisassembleShader(
        pipeline_id, reflection, exact_targets[0])
    if not isinstance(source, str):
        source = str(source or "")
    try:
        return source.encode("utf-8", errors="strict")
    except UnicodeEncodeError:
        raise RuntimeError("DXC DXIL disassembly is not strict UTF-8")


def _dxil_evidence_from_live_disassembly(ctrl, pipeline_id, reflection):
    """Return exact access evidence plus lower-only layout classifications."""
    source_bytes = _dxil_disassembly_source(ctrl, pipeline_id, reflection)
    blocks = [
        {"space": _safe_int(getattr(block, "fixedBindSetOrSpace", 0), 0),
         "bind": _safe_int(getattr(block, "fixedBindNumber", index), index),
         "byteSize": _safe_int(getattr(block, "byteSize", 0), 0)}
        for index, block in enumerate(
            list(getattr(reflection, "constantBlocks", []) or []))
    ]
    return _dxil_evidence_from_snapshot(source_bytes, blocks)


def _dxil_layout_evidence_from_snapshot(blocks, status, source_sha256="",
                                      access_signature_sha256=""):
    """Classify copied block identities without retaining native reflection."""
    result = {}
    for block in blocks:
        marker = {"kind": "dxc-dxil-buffer-definition", "typeAnnotation": status}
        if source_sha256:
            marker["sourceSha256"] = source_sha256
        if access_signature_sha256:
            marker["accessSignatureSha256"] = access_signature_sha256
        result[(block["space"], block["bind"])] = marker
    return result


def _dxil_evidence_from_snapshot(source_bytes, blocks):
    """Parse immutable disassembly bytes and ordinary block dictionaries only."""
    try:
        access, absent = _dxil_access_protocol.extract_dxil_cbuffer_evidence(
            source_bytes)
    except _dxil_access_protocol.DxilAccessSignatureError as error:
        # Access extraction is required only when reconstructing ambiguous
        # layouts. Valid native reflection with matching DXIL type annotations
        # remains authoritative even for instructions outside that parser.
        try:
            annotated = _dxil_access_protocol.extract_dxil_annotated_cbuffer_bindings(
                source_bytes)
        except _dxil_access_protocol.DxilAccessSignatureError:
            annotated = ()
        if not annotated:
            raise RuntimeError(
                "DXC DXIL CBuffer access evidence is incomplete: %s" % str(error))
        evidence = _dxil_layout_evidence_from_snapshot(blocks, "unavailable")
        for space, bind, byte_size in annotated:
            reflected = [block for block in blocks if
                         (block["space"], block["bind"]) == (space, bind)]
            if len(reflected) != 1 or reflected[0]["byteSize"] != byte_size:
                raise RuntimeError("DXC DXIL CBuffer type annotation contradicts reflection")
            evidence.pop((space, bind), None)
        return None, evidence

    if absent is None:
        # Old printers can omit the textual layout section while retaining
        # exact LLVM type annotations. Preserve complete native layouts only
        # for those proven bindings; all others still need exact access proof.
        evidence = _dxil_layout_evidence_from_snapshot(
            blocks,
            "unavailable",
            source_sha256=access.source_sha256,
            access_signature_sha256=access.signature_sha256,
        )
        try:
            annotated = _dxil_access_protocol.extract_dxil_annotated_cbuffer_bindings(
                source_bytes)
        except _dxil_access_protocol.DxilAccessSignatureError:
            annotated = ()
        for space, bind, byte_size in annotated:
            reflected = [block for block in blocks if
                         (block["space"], block["bind"]) == (space, bind)]
            if len(reflected) != 1 or reflected[0]["byteSize"] != byte_size:
                raise RuntimeError("DXC DXIL CBuffer type annotation contradicts reflection")
            evidence.pop((space, bind), None)
        return access, evidence

    evidence = {}
    by_key = _dxil_layout_evidence_from_snapshot(
        blocks,
        "absent",
        source_sha256=access.source_sha256,
        access_signature_sha256=access.signature_sha256,
    )
    reflected_sizes = {}
    for block in blocks:
        reflected_sizes[(block["space"], block["bind"])] = block["byteSize"]
    for space, bind, byte_size in absent:
        key = (space, bind)
        if key not in reflected_sizes or reflected_sizes[key] != byte_size:
            raise RuntimeError(
                "DXC DXIL CBuffer layout evidence contradicts reflection")
        evidence[key] = by_key[key]
    return access, evidence


def _dxil_access_signature_from_live_disassembly(ctrl, pipeline_id, reflection):
    """Recompute one access signature from RenderDoc-owned DXC DXIL text."""
    access, unused_layout_evidence = _dxil_evidence_from_live_disassembly(
        ctrl, pipeline_id, reflection)
    return access


def _dxil_ambiguous_interface_compatible(
        ctrl, baseline_pipeline_id, baseline_reflection, candidate_reflection,
        baseline_access=None, baseline_layout_evidence=None):
    """Interface-envelope gate for DXIL replacements.

    CBuffer member layout is often unreflectable ("ambiguous") for stripped
    DXIL, but the replacement's safety depends only on the interface envelope,
    not on which members the shader loads. The unused ctrl/access/layout
    parameters are retained for call-site compatibility; no per-save DXIL
    disassembly of the candidate is required.
    """
    del ctrl, baseline_pipeline_id, baseline_access
    return _physical_shader_interfaces_compatible(
        baseline_reflection, candidate_reflection,
        baseline_dxil_layout_evidence=baseline_layout_evidence)


