def _ping(params):
    return {
        "status": "ok",
        "server": "replaylab",
        # Keep the legacy field for IPC v2 clients while the built-in integration name propagates.
        "extensionVersion": BRIDGE_INTEGRATION_VERSION,
        "integrationVersion": BRIDGE_INTEGRATION_VERSION,
        "protocolVersion": BRIDGE_PROTOCOL_VERSION,
        "ipc_dir": IPC_DIR,
        "capabilities": [
            "request-mailbox-v2",
            "capture-symbol-catalog-v1",
            "async-shader-catalog-export-v1",
            "unique-shader-resource-inventory-v2",
            "capture-bound-symbol-aliases-v1",
            "shader-search-v1",
            "resource-usage-v1",
            "pixel-object-inspector-v1",
            "d3d11-event-shader-override-v1",
            "d3d11-event-cbuffer-override-v1",
            "d3d11-event-cbuffer-clear-all-v1",
            "current-renderdoc-context-v1",
            "resource-export-capture-v1",
        ],
        "schemas": {
            "captureSymbols": SYMBOL_CATALOG_SCHEMA,
            "shaderCatalogExportJob": "replaylab-shader-catalog-export-job/v1",
            "projectShaderResourceIndex":
                "replaylab-project-shader-resource-index/v2",
            "rdcProjectIndex": REPLAYLAB_RDC_PROJECT_INDEX_SCHEMA,
            "symbolAliases": SYMBOL_ALIAS_SCHEMA,
            "eventCBufferSnapshot": "renderdoc-ultra-event-cbuffer-snapshot/v1",
            "eventCBufferOverride": "renderdoc-ultra-event-cbuffer-override/v1",
            "eventCBufferClearAll": "renderdoc-ultra-event-cbuffer-clear-all/v1",
            "currentContext": _ai_context_protocol.CONTEXT_SCHEMA,
            "resourceExportInspect": _resource_export_protocol.INSPECT_SCHEMA,
            "resourceExportCapture": _resource_export_protocol.CAPTURE_SCHEMA,
            "resourceExportBundle": _resource_export_protocol.BUNDLE_SCHEMA,
        },
    }


def _capture_catalog_identity_status():
    """Copy the identities this Bridge actually admitted in this capture."""
    raw_identity_pairs = sorted(_known_catalog_identity_pairs)
    if len(raw_identity_pairs) > MAX_KNOWN_CATALOG_IDENTITY_PAIRS:
        raise RuntimeError("Bridge catalog identity-pair state exceeds its bound")
    known_identity_pairs = []
    for capture_id, evidence_sha256 in raw_identity_pairs:
        if (len(capture_id) != 64 or len(evidence_sha256) != 64 or
                any(character not in "0123456789abcdef"
                    for character in capture_id + evidence_sha256)):
            raise RuntimeError("Bridge catalog identity-pair state is invalid")
        known_identity_pairs.append({
            "captureId": capture_id,
            "identityEvidenceSha256": evidence_sha256,
        })
    return {
        "restoreValidationPolicySha256": _shader_restore_policy_sha256,
        "restoreValidationCompatiblePolicySha256s": _shader_restore_protocol.compatible_validation_policies(
            _shader_restore_physical_validation_binding),
        "captureId": str(_symbol_capture_snapshot.get("captureId", "") or ""),
        "knownCatalogCaptureIds": sorted(_known_catalog_capture_ids.keys()),
        "knownCatalogIdentityPairs": known_identity_pairs,
        "knownCatalogStablePairs": [
            {"stableCaptureId": stable_id,
             "stableIdentityEvidenceSha256": stable_sha256}
            for stable_id, stable_sha256 in sorted(_known_catalog_stable_pairs)],
    }


def _get_capture_status(params):
    """Check if capture is loaded."""
    if isinstance(params, dict) and params.get("identity_only") is True:
        # Catalog admission needs no draw statistics or replay-thread work.
        # These are real UI-owned capture facts plus the identities admitted
        # by this process; no caller assertion creates an identity here.
        identity = _request_admitted_capture_identity()
        if identity is not None:
            if not identity["loaded"]:
                return {"loaded": False, "identityOnly": True}
            return dict({
                "loaded": True, "identityOnly": True,
                "api": identity["api"], "renderer": identity["renderer"],
                "capturePath": identity["path"], "captureSessionId": identity["captureSessionId"],
            }, **_capture_catalog_identity_status())
        def _read_identity():
            if not _ctx or not _ctx.IsCaptureLoaded():
                return {"loaded": False, "identityOnly": True}
            props = _ctx.APIProps()
            return dict({
                "loaded": True,
                "identityOnly": True,
                "api": str(props.pipelineType),
                "renderer": _native_enum_text(getattr(props, "localRenderer", None)),
                "capturePath": str(_ctx.GetCaptureFilename() or ""),
                "captureSessionId": str(_capture_session_id or ""),
            }, **_capture_catalog_identity_status())
        return _invoke_on_ui_sync(_read_identity)

    dispatch = _request_dispatch_context()
    snapshot = dispatch.get("captureSnapshot", {}) if dispatch is not None else None
    loaded = (bool(snapshot.get("captureLoaded")) if snapshot is not None
              else bool(_ctx.IsCaptureLoaded()))
    if not loaded:
        return {"loaded": False}
    if snapshot is not None:
        capture_token = snapshot.get("captureToken")
        capture_path = capture_token[1] if capture_token else ""
        capture_session_id = str(snapshot.get("captureSessionId", "") or "")
    else:
        try:
            capture_path = str(_ctx.GetCaptureFilename() or "")
        except Exception:
            capture_path = ""
        capture_session_id = _capture_session_id

    def _do(ctrl):
        props = ctrl.GetAPIProperties()
        fi = ctrl.GetFrameInfo()
        result = {
            "loaded": True,
            "api": str(props.pipelineType),
            "renderer": str(props.localRenderer),
            "frameNumber": fi.frameNumber,
            "capturePath": capture_path,
            "captureSessionId": capture_session_id,
        }
        result.update(_capture_catalog_identity_status())
        # Stats structure varies by RenderDoc version
        try:
            result["draws"] = fi.stats.recorded.draws
            result["dispatches"] = fi.stats.recorded.dispatches
            result["calls"] = fi.stats.recorded.calls
        except AttributeError:
            try:
                result["draws"] = fi.stats.draws
                result["dispatches"] = fi.stats.dispatches
                result["calls"] = fi.stats.calls
            except AttributeError:
                result["stats_note"] = "Stats not available in this RenderDoc version"
        return result
    return _replay(_do)


def _current_action_context(event_id, allow_current_fallback=True):
    """Serialize the action and marker ancestry visible in ICaptureContext."""
    action = None
    try:
        action = _ctx.GetAction(int(event_id))
    except Exception:
        action = None
    if action is None and allow_current_fallback:
        try:
            action = _ctx.CurAction()
        except Exception:
            action = None
    if action is None:
        return None

    def _item(value):
        return {
            "eventId": _safe_int(getattr(value, "eventId", 0), 0),
            "actionId": _safe_int(getattr(value, "actionId", 0), 0),
            "name": str(
                getattr(value, "customName", "") or
                getattr(value, "name", "") or
                "Action %d" % _safe_int(getattr(value, "actionId", 0), 0)),
            "flags": str(getattr(value, "flags", "") or ""),
        }

    ancestry = []
    parent = getattr(action, "parent", None)
    guard = 0
    while parent is not None and guard < 128:
        ancestry.append(_item(parent))
        parent = getattr(parent, "parent", None)
        guard += 1
    ancestry.reverse()
    result = _item(action)
    result["markerPath"] = ancestry
    return result


def _current_texture_context(warnings):
    """Read the Texture Viewer's active tab, subresource, and picked texel."""
    try:
        viewer = _ctx.GetTextureViewer()
        resource = viewer.GetCurrentResource()
        resource_id = _resource_id_int(resource)
        if resource_id <= 0:
            return None
        try:
            name = str(_ctx.GetResourceName(resource) or "")
        except Exception:
            name = ""
        subresource = viewer.GetSelectedSubresource()
        selected = {
            "mip": _safe_int(getattr(subresource, "mip", 0), 0),
            "slice": _safe_int(getattr(subresource, "slice", 0), 0),
            "sample": _safe_int(getattr(subresource, "sample", 0), 0),
        }
        location = viewer.GetPickedLocation()
        try:
            x, y = location
        except Exception:
            x = _safe_int(getattr(location, "first", -1), -1)
            y = _safe_int(getattr(location, "second", -1), -1)
        picked = {"x": int(x), "y": int(y)} if int(x) >= 0 and int(y) >= 0 else None
        try:
            flip_y = bool(viewer.Widget().property("textureDisplayFlipY"))
        except (AttributeError, RuntimeError):
            # An unavailable display flag must not discard the captured RT binding.
            flip_y = False
        return {
            "resourceId": resource_id,
            "name": name,
            "subresource": selected,
            "pickedPixel": picked,
            "flipY": flip_y,
        }
    except Exception as exc:
        warnings.append("Texture Viewer context is unavailable: %s" % str(exc))
        return None


def _captured_shader_identity_for_context(ctrl, reflection, resource_id, event_id,
                                          stage_name, entry_point):
    """Keep current replacement bytes and immutable capture identity distinct."""
    owner = _shared_shader_replacements.get(resource_id)
    if owner is None:
        return None
    capture_token = _current_capture_token()
    if (not _capture_session_id or owner.get("captureSessionId") != _capture_session_id or
            owner.get("captureToken") != capture_token or
            _shared_shader_replacement_capture_token != capture_token or
            owner.get("api") != _shader_api_token(ctrl) or
            _resource_id_int(owner.get("originalResource")) != resource_id):
        raise RuntimeError("Shader context replacement owner belongs to another capture")
    original = _captured_original_from_shared_owner(
        reflection, {"eventId": event_id, "expectedOriginalResourceId": resource_id,
                     "expectedOriginalSha256": owner.get("expectedOriginalSha256")},
        stage_name, entry_point, owner, allow_original_active=owner.get("api") in ("d3d11", "vulkan", "opengl"))
    return {"resourceId": resource_id, "stage": stage_name,
            "entryPoint": str(getattr(original, "entryPoint", "") or entry_point),
            "rawSha256": hashlib.sha256(_shader_raw_bytes(original)).hexdigest(),
            "captureSessionId": _capture_session_id}


def _bound_shader_stage_context(ctrl, event_id, stage_name, stage, aliases=None):
    """Inspect one fixed-EID stage and return only primitive Python values."""
    warnings = []
    shader = None
    try:
        pipeline = ctrl.GetPipelineState()
        pipeline_object = _get_pipeline_obj(pipeline, ctrl)
        resource = pipeline.GetShader(stage)
        resource_id = _resource_id_int(resource)
        if resource_id <= 0:
            return None, warnings
        entries = list(ctrl.GetShaderEntryPoints(resource) or [])
        selection = _pipeline_shader_entry_selection(
            pipeline, stage, stage_name, resource, entries)
        selected_entry = selection.get("entry")
        pipeline_entry = str(
            selection["evidence"].get("selectedEntryPoint") or "")

        raw_sha256 = ""
        captured_identity = None
        reflected_entry = pipeline_entry
        if selected_entry is not None:
            reflection = ctrl.GetShader(
                pipeline_object, resource, selected_entry)
            identity_failure = (
                _shader_reflection_identity_failure(
                    reflection, selected_entry, resource,
                    pipeline_object, stage_name, selection)
                if reflection is not None else None)
            if reflection is not None and identity_failure is None:
                reflected_entry = str(
                    getattr(reflection, "entryPoint", "") or pipeline_entry)
                raw = _shader_raw_bytes(reflection)
                if raw:
                    raw_sha256 = hashlib.sha256(raw).hexdigest()
                captured_identity = _captured_shader_identity_for_context(
                    ctrl, reflection, resource_id, event_id, stage_name, reflected_entry)
        else:
            warnings.append(
                "%s shader entry selection is %s" % (
                    stage_name, selection["evidence"]["status"]))
        if not raw_sha256:
            warnings.append(
                "%s shader exact raw bytes are unavailable" % stage_name)

        display_name = ""
        aliases = _matching_shader_aliases(
            resource_id, stage_name, reflected_entry, raw_sha256,
            aliases=aliases)
        if len(aliases) == 1:
            display_name = _alias_display_name(aliases[0])
        shader = {
            "stage": stage_name,
            "resourceId": resource_id,
            "entryPoint": reflected_entry,
            "rawSha256": raw_sha256,
            "displayName": display_name,
            "entryPointSelection": dict(selection["evidence"]),
        }
        if captured_identity is not None:
            shader["capturedOriginalIdentity"] = captured_identity
    except Exception as exc:
        warnings.append(
            "%s shader context is unavailable: %s" % (stage_name, str(exc)))
    return shader, warnings


def _current_bound_shader_context(event_id, action):
    """Return exact identities for every shader bound at the current replay EID."""
    compatible_stages = _ai_context_protocol.compatible_shader_stages(action)

    def _do(ctrl):
        warnings = []
        shaders = []
        if event_id > 0:
            # A context read does not invalidate replay. The controller still materializes a
            # changed/invalid EID, but can reuse the already current, valid pipeline state.
            _set_frame_event(ctrl, int(event_id), False)
        for stage_name, stage in _available_shader_stages(compatible_stages):
            shader, stage_warnings = _bound_shader_stage_context(
                ctrl, event_id, stage_name, stage)
            if shader is not None:
                shaders.append(shader)
            warnings.extend(stage_warnings)
        return shaders, warnings

    return _replay(_do)


def _finish_current_renderdoc_context(facts):
    """Canonicalise one frozen set of facts and assign its observation generation."""
    global _ai_context_generation, _ai_last_observation_id

    # Compare a generation-zero canonical observation. Only genuine context changes
    # increment the process-local generation; repeated reads are byte-identical.
    observed = _ai_context_protocol.build_context(facts)
    observation_id = observed["snapshotId"]
    if observation_id != _ai_last_observation_id:
        _ai_context_generation += 1
        _ai_last_observation_id = observation_id
    facts["contextGeneration"] = _ai_context_generation
    return _ai_context_protocol.build_context(facts)


def _capture_current_renderdoc_context_facts(
        focus_stage="", focus_source="", expected_current_event_id="",
        expected_selected_event_id="",
        expected_capture_session_id=""):
    """Capture GUI-owned context as primitive values before replay work is queued."""
    expected_session = str(expected_capture_session_id or "")
    if expected_session:
        if (len(expected_session) != 32 or
                any(character not in "0123456789abcdef"
                    for character in expected_session)):
            raise ValueError(
                "Expected capture session ID must be 32 lowercase hexadecimal characters")
        if expected_session != str(_capture_session_id or ""):
            raise RuntimeError(
                "RenderDoc capture session changed before current context freeze")
    def _expected_event(value, label, allow_zero=False):
        text = str(value or "")
        if not text:
            return None
        if not text.isdigit():
            raise ValueError(
                "Expected %s event ID must be a decimal uint32" % label)
        parsed = int(text)
        if (str(parsed) != text or parsed > 0xFFFFFFFF or
                (parsed == 0 and not allow_zero)):
            qualifier = "a decimal uint32" if allow_zero else "a positive decimal uint32"
            raise ValueError("Expected %s event ID must be %s" % (label, qualifier))
        return parsed

    expected_event = _expected_event(
        expected_current_event_id, "current")
    expected_selected_event = _expected_event(
        expected_selected_event_id, "selected", allow_zero=True)
    if expected_selected_event is not None and expected_event is None:
        raise ValueError(
            "Expected selected event ID requires an expected current event ID")

    if not _ctx or not _ctx.IsCaptureLoaded():
        if (expected_event is not None or expected_selected_event is not None or
                expected_session):
            raise RuntimeError(
                "No RenderDoc capture is loaded for the expected context")
        facts = {
            "contextGeneration": 0,
            "capture": {"loaded": False},
            "events": {"currentEventId": 0, "selectedEventId": 0},
            "action": None,
            "boundShaders": [],
            "texture": None,
            "warnings": [],
        }
        return facts, (), None, 0
    else:
        visible_event = _safe_int(_ctx.CurEvent(), 0)
        try:
            visible_selected_event = _safe_int(
                _ctx.CurSelectedEvent(), visible_event)
        except Exception:
            visible_selected_event = visible_event
        current_event = expected_event if expected_event is not None else visible_event
        if expected_event is not None:
            selected_event = (
                expected_selected_event if expected_selected_event is not None
                else current_event)
        else:
            selected_event = visible_selected_event
        warnings = []
        current_action = _current_action_context(
            current_event, allow_current_fallback=expected_event is None)
        if (expected_event is not None and
                (current_action is None or
                 _safe_int(current_action.get("eventId"), 0) != current_event)):
            raise ValueError(
                "Expected current event ID does not identify a valid action")
        try:
            props = _ctx.APIProps()
            api_name = _native_enum_text(getattr(props, "pipelineType", None))
        except Exception:
            api_name = ""
        try:
            local = bool(_ctx.IsCaptureLocal())
        except Exception:
            local = False
        try:
            capture_path = str(_ctx.GetCaptureFilename() or "")
        except Exception:
            capture_path = ""
        texture = None
        if (expected_event is None or
                (visible_event == current_event and
                 visible_selected_event == selected_event)):
            texture = _current_texture_context(warnings)
        else:
            warnings.append(
                "Texture Viewer context was omitted because the visible event "
                "changed after task submission")
        facts = {
            "contextGeneration": 0,
            "capture": {
                "loaded": True,
                "captureSessionId": _capture_session_id,
                "captureId": str(_symbol_capture_snapshot.get("captureId", "") or ""),
                "path": capture_path,
                "api": api_name,
                "local": local,
            },
            "events": {
                "currentEventId": current_event,
                "selectedEventId": selected_event,
            },
            "action": current_action,
            "boundShaders": [],
            "focusStage": _normalise_stage_name(focus_stage) if focus_stage else "",
            "focusSource": str(focus_source or ""),
            "texture": texture,
            "warnings": warnings,
        }
        compatible_stages = tuple(
            _ai_context_protocol.compatible_shader_stages(current_action))
        return facts, compatible_stages, _current_capture_token(), visible_event


def _build_current_renderdoc_context(focus_stage="", focus_source=""):
    """Build a current UI/replay snapshot without inferring an unknown UI shader focus."""
    facts, _compatible_stages, _capture_token, _visible_event = (
        _invoke_on_ui_sync(
            lambda: _capture_current_renderdoc_context_facts(
                focus_stage, focus_source)))
    if facts["capture"].get("loaded"):
        try:
            bound_shaders, shader_warnings = _current_bound_shader_context(
                facts["events"]["currentEventId"], facts["action"])
            facts["boundShaders"] = bound_shaders
            facts["warnings"].extend(shader_warnings)
        except Exception as exc:
            facts["warnings"].append(
                "Bound shader context is unavailable: %s" % str(exc))
    return _finish_current_renderdoc_context(facts)


def _current_context_freeze_result_path(job_id):
    """Return a bridge-owned, non-symlink terminal result path for one job."""
    job_id = str(job_id or "").lower()
    if (len(job_id) != 32 or
            any(character not in "0123456789abcdef" for character in job_id)):
        raise ValueError("Current context freeze job ID is invalid")
    result_dir = os.path.join(IPC_DIR, "native-context-jobs")
    for directory in (IPC_DIR, result_dir):
        if not os.path.exists(directory):
            os.makedirs(directory)
        info = os.lstat(directory)
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
            raise RuntimeError(
                "Current context freeze result directory is unsafe")
    result_path = os.path.join(result_dir, job_id + ".json")
    if os.path.lexists(result_path):
        info = os.lstat(result_path)
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
            raise RuntimeError("Current context freeze result path is unsafe")
        os.remove(result_path)
    return result_path


def _current_context_freeze_job_snapshot(job):
    value = {
        "schema": CURRENT_CONTEXT_FREEZE_JOB_SCHEMA,
        "schemaVersion": 1,
        "jobId": job["jobId"],
        "status": job["status"],
        "captureSessionId": job["captureSessionId"],
        "currentEventId": job["currentEventId"],
        "selectedEventId": job["selectedEventId"],
        "resultPath": job["resultPath"],
    }
    if job["status"] == "completed":
        value["context"] = job["context"]
    elif job["status"] in ("failed", "abandoned"):
        value["error"] = str(job.get("error", "") or "")[:4096]
    return value


def _cancel_current_context_freeze_timer(job):
    timer = job.get("timeoutTimer")
    job["timeoutTimer"] = None
    if timer is not None:
        try:
            timer.cancel()
        except Exception:
            pass


def _write_current_context_freeze_terminal(job):
    """Atomically publish a bounded terminal envelope for QFile polling."""
    if job.get("status") not in ("completed", "failed", "abandoned"):
        raise RuntimeError("Current context freeze job is not terminal")
    _cancel_current_context_freeze_timer(job)
    value = _current_context_freeze_job_snapshot(job)
    encoded = json.dumps(
        value, ensure_ascii=True, sort_keys=True,
        separators=(",", ":")).encode("utf-8")
    if len(encoded) > MAX_CURRENT_CONTEXT_FREEZE_RESULT_BYTES:
        job["status"] = "failed"
        job["context"] = None
        job["error"] = "Current context freeze result exceeds the size limit"
        job["failureCode"] = "result-too-large"
        value = _current_context_freeze_job_snapshot(job)
        encoded = json.dumps(
            value, ensure_ascii=True, sort_keys=True,
            separators=(",", ":")).encode("utf-8")
    _atomic_write_bytes(job["resultPath"], encoded)
    _publish_current_context_freeze_console_event(job)


def _timeout_current_context_freeze_job(job_id):
    with _current_context_freeze_jobs_guard:
        job = _current_context_freeze_jobs.get(job_id)
        if job is None or job.get("status") not in ("queued", "running"):
            return
        now = time.monotonic()
        job["status"] = "failed"
        job["context"] = None
        job["error"] = "Current context freeze timed out"
        job["failureCode"] = "timeout"
        job["updatedMonotonic"] = now
        job["finishedMonotonic"] = now
        _write_current_context_freeze_terminal(job)


def _cleanup_current_context_freeze_jobs(now):
    for job in _current_context_freeze_jobs.values():
        if (job.get("status") in ("queued", "running") and
                now - float(job.get("createdMonotonic", now)) >=
                CURRENT_CONTEXT_FREEZE_JOB_TIMEOUT_SECONDS):
            job["status"] = "failed"
            job["context"] = None
            job["error"] = "Current context freeze timed out"
            job["failureCode"] = "timeout"
            job["updatedMonotonic"] = now
            job["finishedMonotonic"] = now
            _write_current_context_freeze_terminal(job)
    expired = [
        job_id for job_id, job in _current_context_freeze_jobs.items()
        if (job.get("status") in ("completed", "failed", "abandoned") and
            now - float(job.get("updatedMonotonic", now)) >=
            CURRENT_CONTEXT_FREEZE_JOB_TTL_SECONDS)
    ]
    for job_id in expired:
        job = _current_context_freeze_jobs.pop(job_id, None)
        result_path = job.get("resultPath", "") if job else ""
        try:
            if result_path and os.path.isfile(result_path) and not os.path.islink(result_path):
                os.remove(result_path)
        except Exception:
            pass


def _run_current_context_freeze_job(job_id, ctrl):
    """Freeze one EID atomically on replay; the GUI observes only the result file."""
    with _current_context_freeze_jobs_guard:
        job = _current_context_freeze_jobs.get(job_id)
        if job is None or job.get("status") != "queued":
            return
        job["status"] = "running"
        job["updatedMonotonic"] = time.monotonic()
        facts = job["facts"]
        compatible_stages = job["compatibleStages"]
        aliases = job["aliases"]
        expected_session = job["captureSessionId"]
        expected_token = job["captureToken"]
        event_id = job["currentEventId"]
        restore_event_id = job["restoreEventId"]
        replay_manager = job.get("replayManager")
    context = None
    failure = None
    failure_code = ""
    event_dirty = False
    restore_needed = (
        restore_event_id > 0 and restore_event_id != event_id)
    try:
        if (expected_session != _capture_session_id or
                expected_token != _active_capture_token):
            failure_code = "capture-changed"
            raise RuntimeError(
                "RenderDoc capture changed before current context freeze")
        shaders = []
        warnings = []
        if event_id > 0:
            # Mark first so a partially successful replay call is also restored.
            # This callback is a ReplayManager foreground ordering barrier, so
            # later user replay operations cannot overtake this mutation.
            event_dirty = True
            # Do not force a full GPU replay merely to observe the current shaders. Native
            # resource replacement already invalidates and refreshes its event, and the
            # controller replays different or non-materialized EIDs even with force=False.
            _set_frame_event(ctrl, int(event_id), False)
        for stage_name, stage in _available_shader_stages(compatible_stages):
            shader, stage_warnings = _bound_shader_stage_context(
                ctrl, event_id, stage_name, stage, aliases=aliases)
            if shader is not None:
                shaders.append(shader)
            warnings.extend(stage_warnings)
        if (expected_session != _capture_session_id or
                expected_token != _active_capture_token):
            failure_code = "capture-changed"
            raise RuntimeError(
                "RenderDoc capture changed during current context freeze")
        facts["boundShaders"] = shaders
        facts["warnings"].extend(warnings)
    except Exception as exc:
        if "bread-replay-unavailable" in str(exc):
            # Keep the AI usable for recovery/static inspection. Identity and
            # action metadata are still valid; empty live bindings are not.
            facts["boundShaders"] = []
            facts["warnings"].append(str(exc))
            event_dirty = False
        else:
            failure = exc
            if not failure_code:
                failure_code = "replay-callback-failed"
    finally:
        if (event_dirty and restore_needed and
                expected_session == _capture_session_id and
                expected_token == _active_capture_token):
            try:
                _set_frame_event(ctrl, int(restore_event_id), True)
            except Exception as restore_exc:
                failure_code = "replay-restore-failed"
                if failure is None:
                    failure = restore_exc
                else:
                    failure = RuntimeError(
                        "%s; replay event restoration failed: %s" %
                        (str(failure), str(restore_exc)))

    if failure is None:
        try:
            context = _finish_current_renderdoc_context(facts)
        except Exception as exc:
            failure = exc
            failure_code = "context-finalization-failed"

    with _current_context_freeze_jobs_guard:
        current = _current_context_freeze_jobs.get(job_id)
        if current is not job or job.get("status") != "running":
            return
        if failure is None:
            job["status"] = "completed"
            job["context"] = context
        else:
            job["status"] = "failed"
            job["context"] = None
            job["error"] = "%s: %s" % (type(failure).__name__, str(failure))
            job["failureCode"] = failure_code or "unknown"
        job["updatedMonotonic"] = time.monotonic()
        job["finishedMonotonic"] = job["updatedMonotonic"]
        _write_current_context_freeze_terminal(job)


def _begin_current_context_freeze(
        focus_stage="", expected_current_event_id="",
        expected_selected_event_id="",
        expected_capture_session_id="", _job_id="", _for_chat=False):
    """Capture GUI facts and queue replay work without waiting for replay."""
    global _project_ai_inspection
    now = time.monotonic()
    with _current_context_freeze_jobs_guard:
        _cleanup_current_context_freeze_jobs(now)
        active = sum(
            1 for job in _current_context_freeze_jobs.values()
            if job.get("status") in ("queued", "running"))
        if active >= MAX_CURRENT_CONTEXT_FREEZE_JOBS:
            raise RuntimeError("The current context freeze queue is full")

    facts, compatible_stages, capture_token, restore_event_id = (
        _capture_current_renderdoc_context_facts(
            focus_stage=focus_stage,
            focus_source="explicit-native-task" if focus_stage else "",
            expected_current_event_id=expected_current_event_id,
            expected_selected_event_id=expected_selected_event_id,
            expected_capture_session_id=expected_capture_session_id))
    job_id = str(_job_id or uuid.uuid4().hex).lower()
    result_path = _current_context_freeze_result_path(job_id)
    session = str(facts.get("capture", {}).get("captureSessionId", "") or "")
    restore_client = None
    if _for_chat and expected_capture_session_id and session and facts.get("capture", {}).get("loaded"):
        # A submitted chat owns its replay evidence. Cancel only this window's
        # passive startup job, and suppress late association callbacks for this
        # capture session. The explicit project launcher uses a separate client.
        if _project_ai_inspection[0] != session:
            _project_ai_inspection = (session, _project_auto_restore_client)
            if _project_auto_restore_client is not None:
                _project_auto_restore_client.cancel_for_inspection()
        restore_client = _project_ai_inspection[1]
    replay_manager = _ctx.Replay() if facts.get("capture", {}).get("loaded") else None
    job = {
        "jobId": job_id,
        "status": "queued",
        "captureSessionId": session,
        "currentEventId": _safe_int(
            facts.get("events", {}).get("currentEventId", 0), 0),
        "selectedEventId": _safe_int(
            facts.get("events", {}).get("selectedEventId", 0), 0),
        "captureToken": capture_token,
        "restoreEventId": _safe_int(restore_event_id, 0),
        "replayManager": replay_manager,
        "facts": facts,
        "compatibleStages": tuple(compatible_stages),
        "aliases": [],
        "resultPath": result_path,
        "context": None,
        "error": "",
        "failureCode": "",
        "consoleEventPublished": False,
        "createdMonotonic": now,
        "updatedMonotonic": now,
        "finishedMonotonic": None,
        "timeoutTimer": None,
    }
    with _current_context_freeze_jobs_guard:
        _current_context_freeze_jobs[job_id] = job

    if not facts.get("capture", {}).get("loaded"):
        with _current_context_freeze_jobs_guard:
            job["status"] = "completed"
            job["context"] = _finish_current_renderdoc_context(facts)
            job["updatedMonotonic"] = time.monotonic()
            job["finishedMonotonic"] = job["updatedMonotonic"]
            _write_current_context_freeze_terminal(job)
        return _current_context_freeze_job_snapshot(job)

    timeout_timer = threading.Timer(
        CURRENT_CONTEXT_FREEZE_JOB_TIMEOUT_SECONDS,
        lambda token=job_id: _timeout_current_context_freeze_job(token))
    timeout_timer.daemon = True
    with _current_context_freeze_jobs_guard:
        job["timeoutTimer"] = timeout_timer
    timeout_timer.start()

    def queue_after_project_restore():
        with _current_context_freeze_jobs_guard:
            if job["status"] != "queued":
                return
        if restore_client is not None and _project_auto_restore_client is restore_client:
            QtCore.QTimer.singleShot(100, queue_after_project_restore)
            return
        try:
            if restore_client is not None and not restore_client.replay_inspection_safe:
                raise RuntimeError("Project restore rollback could not be verified for this capture")
            try:
                job["aliases"] = json.loads(json.dumps(
                    _symbol_alias_overlay.get("aliases", []),
                    ensure_ascii=True, separators=(",", ":")))
            except (TypeError, ValueError):
                job["aliases"] = []
            replay_manager.AsyncInvoke(
                lambda ctrl, token=job_id: _run_current_context_freeze_job(token, ctrl),
                CURRENT_CONTEXT_FREEZE_REPLAY_TAG_PREFIX + job_id)
        except Exception as exc:
            with _current_context_freeze_jobs_guard:
                if job["status"] != "queued":
                    return
                job["status"] = "failed"
                job["error"] = "%s: %s" % (type(exc).__name__, str(exc))
                job["failureCode"] = "enqueue-failed"
                job["updatedMonotonic"] = time.monotonic()
                job["finishedMonotonic"] = job["updatedMonotonic"]
                _write_current_context_freeze_terminal(job)

    queue_after_project_restore()
    return _current_context_freeze_job_snapshot(job)


def _poll_current_context_freeze(job_id):
    with _current_context_freeze_jobs_guard:
        _cleanup_current_context_freeze_jobs(time.monotonic())
        job = _current_context_freeze_jobs.get(str(job_id or "").lower())
        if job is None:
            raise ValueError("Unknown or expired current context freeze job")
        return _current_context_freeze_job_snapshot(job)


def _abandon_current_context_freeze(job_id):
    with _current_context_freeze_jobs_guard:
        _cleanup_current_context_freeze_jobs(time.monotonic())
        job = _current_context_freeze_jobs.get(str(job_id or "").lower())
        if job is None:
            raise ValueError("Unknown or expired current context freeze job")
        if job.get("status") in ("queued", "running"):
            job["status"] = "abandoned"
            job["context"] = None
            job["error"] = "Current context freeze was abandoned"
            job["failureCode"] = "abandoned"
            job["updatedMonotonic"] = time.monotonic()
            job["finishedMonotonic"] = job["updatedMonotonic"]
            _write_current_context_freeze_terminal(job)
        return _current_context_freeze_job_snapshot(job)


def _capture_identity_on_ui():
    """Copy only cached CaptureContext facts while already on the Qt thread."""
    if not _ctx or not _ctx.IsCaptureLoaded():
        return {"loaded": False}
    try:
        props = _ctx.APIProps()
        api_name = _native_enum_text(getattr(props, "pipelineType", None))
        renderer = _native_enum_text(getattr(props, "localRenderer", None))
    except Exception:
        api_name, renderer = "", ""
    try:
        local = bool(_ctx.IsCaptureLocal())
    except Exception:
        local = False
    try:
        capture_path = str(_ctx.GetCaptureFilename() or "")
    except Exception:
        capture_path = ""
    return {
        "loaded": True, "captureSessionId": _capture_session_id,
        "captureId": str(_symbol_capture_snapshot.get("captureId", "") or ""),
        "path": capture_path, "api": api_name, "local": local, "renderer": renderer,
    }


def _request_admitted_capture_identity():
    """Reuse this request's Qt admission, never an instance discovery manifest."""
    dispatch = _request_dispatch_context()
    if not isinstance(dispatch, dict):
        return None
    snapshot = dispatch.get("captureSnapshot")
    if not isinstance(snapshot, dict):
        return None
    identity = snapshot.get("captureIdentity")
    session = snapshot.get("captureSessionId")
    token = snapshot.get("captureToken")
    if (not isinstance(identity, dict) or type(identity.get("loaded")) is not bool
            or identity["loaded"] != snapshot.get("captureLoaded") or not isinstance(session, str)):
        return None
    if identity["loaded"]:
        if (not re.fullmatch(r"[0-9a-f]{32}", session)
                or identity.get("captureSessionId") != session
                or not isinstance(identity.get("path"), str) or not identity["path"]
                or not isinstance(identity.get("api"), str) or not identity["api"]
                or type(identity.get("local")) is not bool
                or not isinstance(identity.get("renderer"), str)
                or not isinstance(token, tuple) or len(token) != 2 or token[0] != "loaded"
                or token[1] != os.path.normcase(os.path.abspath(identity["path"]))):
            return None
    elif session or token is not None:
        return None
    if (_request_dispatch_cancelled(dispatch) or session != str(_capture_session_id or "")
            or token != _active_capture_token):
        raise _ReplayLabBackgroundPreempted(
            "Bread request capture admission changed before its identity read")
    result = dict(identity)
    if result["loaded"]:
        # Catalog admission can advance inside this same capture session. It is
        # not a native capture getter and must remain a current process fact.
        result["captureId"] = str(_symbol_capture_snapshot.get("captureId", "") or "")
    return result


def _capture_identity_context():
    """Which capture is open -- nothing about where the user is looking.

    Host tools re-check the capture identity (session, path, API) before they
    touch it. That check must not freeze the UI's current event: the AI's
    request was frozen once, when it was asked, and the user is free to move
    around the capture while the task runs. So this is a plain read of the
    identity facts, with no event, action or Texture Viewer state.
    """

    capture = _request_admitted_capture_identity()
    if capture is None:
        capture = _invoke_on_ui_sync(_capture_identity_on_ui)
    facts = {
        "contextGeneration": 0,
        "capture": capture,
        "events": {"currentEventId": 0, "selectedEventId": 0},
        "action": None,
        "boundShaders": [],
        "texture": None,
        "warnings": ["identity-only read: events, action and texture context "
                     "were not captured"],
    }
    context = _ai_context_protocol.build_context(facts)
    context["identityOnly"] = True
    # Reuse this existing Host identity read for an early cache-miss hint.
    # It never grants apply authority; the Bridge checks the signed policy again.
    context["restoreValidationPolicySha256"] = _shader_restore_policy_sha256
    context["restoreValidationCompatiblePolicySha256s"] = _shader_restore_protocol.compatible_validation_policies(
        _shader_restore_physical_validation_binding)
    context["snapshotId"] = _canonical_json_sha256({
        key: value for key, value in context.items() if key != "snapshotId"})
    return context


def _get_current_renderdoc_context(params):
    # MCP/IPC callers cannot assert an explicit UI shader selection. Explicit
    # focus exists only in a RenderDoc stage-scoped menu callback.
    if isinstance(params, dict) and params.get("identity_only"):
        return _capture_identity_context()
    if _request_dispatch_context() is None:
        return _build_current_renderdoc_context()
    dispatch = _request_dispatch_context()
    capture_snapshot = dispatch.get("captureSnapshot", {})
    expected_event_id = _safe_int(
        capture_snapshot.get("visibleEventId", 0), 0)
    expected_selected_event_id = _safe_int(
        capture_snapshot.get("selectedEventId", expected_event_id),
        expected_event_id)
    expected_capture_session_id = str(
        capture_snapshot.get("captureSessionId", "") or "")

    # Use the same fixed-EID foreground ordering barrier as the native AI
    # submit path.  A generic background ReplayManager generation includes
    # qrenderdoc's own foreground maintenance invokes, not only user actions,
    # so using that generation for context freezing can permanently mislabel
    # an idle capture as user-preempted.  The poller's activity cancellation
    # and the exact capture/EID preconditions remain authoritative here.
    snapshot = _invoke_on_ui_sync(
        lambda: _begin_current_context_freeze(
            expected_current_event_id=(
                str(expected_event_id) if expected_event_id > 0 else ""),
            expected_selected_event_id=(
                str(expected_selected_event_id)
                if expected_event_id > 0 and expected_selected_event_id >= 0
                else ""),
            expected_capture_session_id=expected_capture_session_id))
    job_id = str(snapshot.get("jobId", "") or "")
    if not job_id:
        raise RuntimeError("Current context freeze did not return a job ID")
    deadline = time.monotonic() + CURRENT_CONTEXT_FREEZE_JOB_TIMEOUT_SECONDS + 1.0
    cancel_event = dispatch.get("cancelEvent")
    while True:
        if _request_dispatch_cancelled(dispatch):
            _abandon_current_context_freeze(job_id)
            raise _ReplayLabBackgroundPreempted(
                "Bread current context freeze was cancelled by user activity")
        snapshot = _poll_current_context_freeze(job_id)
        status = str(snapshot.get("status", "") or "")
        if status == "completed":
            context = snapshot.get("context")
            if not isinstance(context, dict):
                raise RuntimeError(
                    "Current context freeze returned an invalid context object")
            return context
        if status == "failed":
            raise RuntimeError(
                str(snapshot.get("error", "") or
                    "Current context freeze failed"))
        if status == "abandoned":
            raise _ReplayLabBackgroundPreempted(
                str(snapshot.get("error", "") or
                    "Current context freeze was abandoned"))
        if time.monotonic() >= deadline:
            _abandon_current_context_freeze(job_id)
            raise RuntimeError("Current context freeze timed out")
        time.sleep(0.01)


def _action_name(action):
    return str(getattr(action, "customName", "") or
               "Action %d" % _safe_int(getattr(action, "actionId", 0), 0))


_INDIRECT_ARGS_RE = re.compile(r"(Indirect[A-Za-z]*)\(<[^>]*>\)")


def _stable_action_name(name):
    """An action label fit for a content-addressed catalog.

    RenderDoc names indirect actions with the arguments it read back during
    replay ("IndirectDispatch(<2, 2, 123>)"); those numbers change from one
    replay to the next and would turn every re-index of the same capture
    into a new catalog revision. The label keeps the action, not the values.
    """

    return _INDIRECT_ARGS_RE.sub(r"\1(<indirect>)", str(name or ""))


def _action_flags_mask(names, fallback=0):
    action_flags = getattr(rd, "ActionFlags", None)
    mask = 0
    for name in names:
        mask |= _safe_int(getattr(action_flags, name, 0), 0)
    return mask or fallback


def _draw_dispatch_action_mask():
    return _action_flags_mask(
        ("Drawcall", "Dispatch", "MeshDispatch", "DispatchRay"),
        0x0002 | 0x0004 | 0x0008 | 0x4000)


def _marker_action_mask():
    return _action_flags_mask(
        ("PushMarker", "PopMarker", "SetMarker", "CmdList", "MultiAction",
         "PassBoundary", "CommandBufferBoundary"),
        0x0040 | 0x0080 | 0x0020 | 0x0010 | 0x0200 | 0x2000 | 0x1000000)


def _get_draw_calls(params):
    """Get actions with marker-subtree filtering and an optional draw/dispatch-only view."""
    include_children = bool(params.get("include_children", True))
    only_actions = bool(params.get("only_actions", False))
    marker_filter = str(params.get("marker_filter", "") or "").strip().lower()
    event_min = _safe_int(params.get("event_id_min", 0), 0)
    event_max = _safe_int(params.get("event_id_max", 0), 0)
    draw_dispatch_mask = _draw_dispatch_action_mask()
    marker_mask = _marker_action_mask()

    def _flatten(actions, depth=0, marker_path=None, matched_ancestor=False):
        marker_path = marker_path or []
        result = []
        for a in actions:
            flags = _safe_int(getattr(a, "flags", 0), 0)
            name = _action_name(a)
            children = getattr(a, "children", None) or []
            is_marker = bool(children) or bool(flags & marker_mask)
            current_path = marker_path + ([name] if is_marker else [])
            marker_matches = is_marker and marker_filter in name.lower() if marker_filter else False
            in_matching_subtree = matched_ancestor or marker_matches
            entry = {
                "eventId": _safe_int(getattr(a, "eventId", 0), 0),
                "name": name,
                "flags": flags,
                "numIndices": _safe_int(getattr(a, "numIndices", 0), 0),
                "numInstances": _safe_int(getattr(a, "numInstances", 0), 0),
                "depth": depth,
                "markerPath": current_path if is_marker else marker_path,
            }
            outputs = getattr(a, "outputs", None) or []
            if outputs:
                entry["outputs"] = [_resource_id_int(output) for output in outputs
                                    if _resource_id_int(output)]

            passes_marker = not marker_filter or in_matching_subtree
            passes_type = not only_actions or bool(flags & draw_dispatch_mask)
            passes_range = ((event_min <= 0 or entry["eventId"] >= event_min) and
                            (event_max <= 0 or entry["eventId"] <= event_max))
            if passes_marker and passes_type and passes_range:
                result.append(entry)

            if include_children and children:
                result.extend(_flatten(
                    children, depth + 1, current_path, in_matching_subtree))
        return result

    def _do(ctrl):
        filtered = _flatten(ctrl.GetRootActions())
        return {
            "count": len(filtered),
            "includeChildren": include_children,
            "onlyActions": only_actions,
            "markerFilter": marker_filter,
            "actions": filtered,
        }

    return _replay(_do)


def _get_pipeline_obj(ps, ctrl):
    """Get pipeline object ID, compatible with D3D11/D3D12/Vulkan/OpenGL."""
    # Method 1: Universal API (newer RenderDoc versions)
    if hasattr(ps, 'GetShaderPipelineObject'):
        try:
            pid = ps.GetShaderPipelineObject()
            if pid and int(pid) != 0:
                return pid
        except Exception:
            pass

    # Method 2: Vulkan — pipeline from VkGraphicsPipelineState
    try:
        vk = ctrl.GetVulkanPipelineState()
        if vk and hasattr(vk, 'graphics') and hasattr(vk.graphics, 'pipelineResourceId'):
            pid = vk.graphics.pipelineResourceId
            if pid and int(pid) != 0:
                return pid
        if vk and hasattr(vk, 'compute') and hasattr(vk.compute, 'pipelineResourceId'):
            pid = vk.compute.pipelineResourceId
            if pid and int(pid) != 0:
                return pid
    except Exception:
        pass

    # Method 3: D3D12 — pipeline from D3D12PipelineState
    try:
        d3d12 = ctrl.GetD3D12PipelineState()
        if d3d12 and hasattr(d3d12, 'pipelineResourceId'):
            pid = d3d12.pipelineResourceId
            if pid and int(pid) != 0:
                return pid
        # D3D12 graphics/compute pipeline
        if d3d12:
            for attr in ['graphics', 'compute']:
                sub = getattr(d3d12, attr, None)
                if sub and hasattr(sub, 'pipelineResourceId'):
                    pid = sub.pipelineResourceId
                    if pid and int(pid) != 0:
                        return pid
    except Exception:
        pass

    # Method 4: D3D11 — no explicit pipeline object, use null ResourceId
    # D3D11 doesn't have pipeline state objects; RenderDoc handles this internally
    # GetShader/GetShaderEntryPoints still work with a null pipeline ID
    try:
        d3d11 = ctrl.GetD3D11PipelineState()
        if d3d11:
            # D3D11 is valid but has no pipeline object — return null
            return rd.ResourceId()
    except Exception:
        pass

    # Method 5: OpenGL — similar to D3D11, no explicit pipeline object
    try:
        gl = ctrl.GetOpenGLPipelineState()
        if gl:
            return rd.ResourceId()
    except Exception:
        pass

    # Fallback: return a null ResourceId (works for D3D11 and some edge cases)
    return rd.ResourceId()


def _pipeline_shader_entry_selection(pipeline, stage, stage_name, shader_resource,
                                     entries):
    """Select exactly one entry for a pipeline-bound stage/resource pair.

    The pipeline's reported entry name is authoritative when present.  A
    reflected entry may only be used without it when the stage/resource set is
    itself unique.  The returned ``entry`` is an in-process RenderDoc object;
    ``evidence`` is the serialisable protocol projection used by every caller.
    """
    canonical_stage = _normalise_stage_name(stage_name)
    candidates = list(entries or [])
    records = []
    compatible = []
    for candidate in candidates:
        name = str(getattr(candidate, "name", "") or "")
        candidate_stage = _known_stage_name(candidate)
        records.append({
            "name": name,
            "stage": candidate_stage or None,
        })
        if not candidate_stage or candidate_stage == canonical_stage:
            compatible.append(candidate)

    try:
        reported = pipeline.GetShaderEntryPoint(stage)
        pipeline_entry = str(getattr(reported, "name", reported) or "")
    except Exception:
        pipeline_entry = ""

    selected = None
    source = ""
    matches = []
    if pipeline_entry:
        matches = [
            candidate for candidate in compatible
            if str(getattr(candidate, "name", "") or "") == pipeline_entry
        ]
        if len(matches) == 1:
            selected = matches[0]
            source = "pipeline-state-entry"
        elif len(compatible) == 1:
            # Some D3D12 captures report the legacy placeholder ``main`` even
            # though the DXIL metadata contains the real exported entry name.
            # A unique bound resource/stage candidate is still exact; select
            # it here and require reflection identity to agree below.
            candidate = next(iter(compatible))
            candidate_name = str(getattr(candidate, "name", "") or "")
            if candidate_name.lower() == pipeline_entry.lower():
                selected = candidate
                source = "pipeline-state-entry-case-normalized"
            else:
                selected = candidate
                source = "unique-bound-resource-entry"
    elif len(candidates) == 1 and len(compatible) == 1:
        selected = next(iter(compatible))
        source = "unique-reflected-entry"
    else:
        explicit_stage_matches = [
            candidate for candidate in compatible
            if _known_stage_name(candidate) == canonical_stage
        ]
        if len(explicit_stage_matches) == 1 and all(
                _known_stage_name(candidate)
                for candidate in candidates):
            selected = explicit_stage_matches[0]
            source = "unique-reflected-stage-entry"

    selected_name = str(getattr(selected, "name", "") or "") if selected else ""
    if selected is not None:
        status = "selected"
        error_id = ""
        error = ""
    else:
        ambiguous = len(candidates) > 1
        status = "ambiguous" if ambiguous else "unavailable"
        error_id = (
            "shader-entry-point-ambiguous" if ambiguous else
            "shader-entry-point-unavailable")
        error = (
            "The current pipeline stage/resource/entry does not uniquely select "
            "one reflected shader entry point" if ambiguous else
            "The current pipeline stage/resource/entry has no exact reflected "
            "shader entry point")

    return {
        "entry": selected,
        "evidence": {
            "status": status,
            "source": source or None,
            "resourceId": _resource_id_int(shader_resource),
            "stage": canonical_stage,
            "pipelineReportedEntryPoint": pipeline_entry or None,
            "selectedEntryPoint": selected_name or None,
            "candidateCount": len(candidates),
            "stageCompatibleCandidateCount": len(compatible),
            "entryPoints": records,
            "errorId": error_id or None,
            "error": error or None,
        },
    }


def _shader_entry_selection_failure(selection, shader_resource, pipeline_id,
                                    stage_name):
    evidence = dict(selection.get("evidence") or {})
    return {
        "errorId": evidence.get("errorId") or "shader-entry-point-unavailable",
        "error": evidence.get("error") or
        "The exact pipeline shader entry point is unavailable",
        "shaderId": _resource_id_int(shader_resource),
        "pipelineId": _resource_id_int(pipeline_id),
        "stage": _normalise_stage_name(stage_name),
        "entryPoints": list(evidence.get("entryPoints") or []),
        "pipelineReportedEntryPoint": evidence.get(
            "pipelineReportedEntryPoint"),
        "entryPointSelection": evidence,
        "unknowns": [
            "No reflection, disassembly, binding role, or semantic analysis was "
            "attributed to an arbitrary entry point."
        ],
    }


def _shader_reflection_identity_failure(reflection, selected_entry,
                                        shader_resource, pipeline_id, stage_name,
                                        selection):
    selected_name = str(getattr(selected_entry, "name", "") or "")
    reflected_name = str(getattr(reflection, "entryPoint", "") or "")
    reflected_stage = _known_stage_name(reflection)
    canonical_stage = _normalise_stage_name(stage_name)
    if ((reflected_name and reflected_name != selected_name) or
            (reflected_stage and reflected_stage != canonical_stage)):
        return {
            "errorId": "shader-reflection-identity-mismatch",
            "error": (
                "Shader reflection does not match the uniquely selected "
                "pipeline stage/resource/entry"),
            "shaderId": _resource_id_int(shader_resource),
            "pipelineId": _resource_id_int(pipeline_id),
            "stage": canonical_stage,
            "entryPoints": list(
                (selection.get("evidence") or {}).get("entryPoints") or []),
            "selectedEntryPoint": selected_name,
            "reflectedEntryPoint": reflected_name,
            "reflectedStage": reflected_stage,
            "entryPointSelection": dict(selection.get("evidence") or {}),
        }
    return None


def _pipeline_state_on_replay(ctrl):
    """Collect pipeline evidence from the controller's already-selected event."""
    _require_healthy_replay(ctrl)
    ps = ctrl.GetPipelineState()
    pipeline_id = _get_pipeline_obj(ps, ctrl)

    stages = {}
    for name, stage in _available_shader_stages(
            ["vertex", "hull", "domain", "geometry", "fragment",
             "compute", "task", "mesh"]):
        sid = ps.GetShader(stage)
        if sid and int(sid) != 0:
            stages[name] = {"shaderId": int(sid)}
            entries = list(ctrl.GetShaderEntryPoints(sid) or [])
            selection = _pipeline_shader_entry_selection(
                ps, stage, name, sid, entries)
            stages[name]["entryPointSelection"] = dict(selection["evidence"])
            selected_entry = selection.get("entry")
            if selected_entry is None:
                stages[name].update(_shader_entry_selection_failure(
                    selection, sid, pipeline_id, name))
                continue
            refl = ctrl.GetShader(pipeline_id, sid, selected_entry)
            if not refl:
                stages[name].update({
                    "errorId": "shader-reflection-unavailable",
                    "error": "The exact pipeline shader reflection is unavailable",
                })
                continue
            identity_failure = _shader_reflection_identity_failure(
                refl, selected_entry, sid, pipeline_id, name, selection)
            if identity_failure is not None:
                stages[name].update(identity_failure)
                continue
            stages[name]["entryPoint"] = str(
                getattr(selected_entry, "name", "") or "")
            stages[name]["textureCount"] = sum(
                1 for r in refl.readOnlyResources if r.isTexture)
            stages[name]["cbufferCount"] = len(refl.constantBlocks)
            stages[name]["samplerCount"] = len(refl.samplers)

    targets = ps.GetOutputTargets()
    depth = ps.GetDepthTarget()

    return {
        "shaders": stages,
        "renderTargets": [int(t.resource) for t in targets if int(t.resource) != 0],
        "depthTarget": int(depth.resource) if depth and int(depth.resource) != 0 else None,
    }


def _get_pipeline_state(params):
    """Get pipeline state at an event."""
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")

    def _do(ctrl):
        _select_event_for_read(ctrl, event_id)
        return _pipeline_state_on_replay(ctrl)

    return _replay(_do)


def _shader_analysis_targets(targets, mode):
    """Prefer portable instructions to duplicate hardware ISA for explanation."""
    values = list(targets)
    if mode == "all":
        return values
    if mode != "preferred":
        raise ValueError("text_mode must be preferred or all")

    def priority(value):
        name = str(value).lower()
        if any(token in name for token in ("dxbc", "dxil", "spir-v", "spirv", "glsl", "hlsl")):
            return 0
        if name in ("native", "default"):
            return 1
        return 2

    return sorted(values, key=priority)


def _get_shader_info(params):
    """Get detailed shader info + disassembly + bound textures at an event."""
    event_id = params.get("event_id")
    stage_name = _normalise_stage_name(params.get("stage", "fragment"))
    if event_id is None:
        raise ValueError("event_id required")

    stage_map = dict(_available_shader_stages([stage_name]))
    stage = stage_map.get(stage_name)
    if stage is None:
        raise ValueError("unsupported shader stage: %s" % stage_name)

    def _do(ctrl):
        _set_frame_event(ctrl, int(event_id), True)
        ps = ctrl.GetPipelineState()
        sid = ps.GetShader(stage)
        if not sid or int(sid) == 0:
            return {"error": "No shader at stage '%s'" % stage_name}

        pid = _get_pipeline_obj(ps, ctrl)
        entries = list(ctrl.GetShaderEntryPoints(sid) or [])

        selection = _pipeline_shader_entry_selection(
            ps, stage, stage_name, sid, entries)
        selected_entry = selection.get("entry")
        if selected_entry is None:
            return _shader_entry_selection_failure(
                selection, sid, pid, stage_name)

        refl = ctrl.GetShader(pid, sid, selected_entry)
        if not refl:
            failure = _shader_entry_selection_failure(
                selection, sid, pid, stage_name)
            failure.update({
                "errorId": "shader-reflection-unavailable",
                "error": "The exact pipeline shader reflection is unavailable",
            })
            return failure

        selected_entry_name = str(getattr(selected_entry, "name", "") or "")
        reflected_entry_name = str(getattr(refl, "entryPoint", "") or "")
        identity_failure = _shader_reflection_identity_failure(
            refl, selected_entry, sid, pid, stage_name, selection)
        if identity_failure is not None:
            return identity_failure
        entry_point = reflected_entry_name or selected_entry_name
        raw_bytes = _shader_raw_bytes(refl)
        raw_sha256 = hashlib.sha256(raw_bytes).hexdigest() if raw_bytes else None
        compiled_interface = _compiled_shader_interface(refl)
        captured_identity = _captured_shader_identity_for_context(
            ctrl, refl, int(sid), int(event_id), stage_name, entry_point)

        result = {
            "shaderId": int(sid),
            "pipelineId": int(pid),
            "api": _native_enum_text(getattr(ctrl.GetAPIProperties(), "pipelineType", None)),
            "stage": stage_name,
            "entryPoint": entry_point,
            "entryPoints": list(selection["evidence"]["entryPoints"]),
            "entryPointSelection": dict(selection["evidence"]),
            "encoding": _native_enum_text(getattr(refl, "encoding", None)),
            "rawSha256": raw_sha256,
            # This is compiled reflection evidence, not recovered source or a
            # semantic interpretation.  A quick-analysis child can use
            # it without first creating/decompiling a managed workspace.
            "compiledInterface": compiled_interface,
            "diagnostics": [],
            "unknowns": [],
        }
        if captured_identity is not None:
            result["capturedOriginalIdentity"] = captured_identity

        aliases = _matching_shader_aliases(
            int(sid), stage_name, entry_point, raw_sha256)
        if aliases:
            result["alias"] = aliases[0]
            result["displayName"] = _alias_display_name(aliases[0])
            if len(aliases) > 1:
                result["aliasCandidates"] = aliases

        # Explanation-only callers prefer embedded source, otherwise one useful
        # portable IR. Existing inspection/editing callers retain all targets.
        text_mode = params.get("text_mode", "all")
        embedded_files = list(getattr(getattr(refl, "debugInfo", None), "files", []) or [])
        has_source = any(isinstance(getattr(f, "contents", None), str)
                         and f.contents.strip() and "\x00" not in f.contents
                         for f in embedded_files)
        targets = ctrl.GetDisassemblyTargets(True)
        result["disassemblyTargets"] = list(targets)
        disasm = {}
        ordered_targets = _shader_analysis_targets(targets, text_mode)
        attempted_targets = []
        for t in ([] if text_mode == "preferred" and has_source else ordered_targets):
            attempted_targets.append(str(t))
            try:
                value = ctrl.DisassembleShader(pid, refl, t)
                disasm[t] = value
                if (text_mode == "preferred" and isinstance(value, str) and value.strip()
                        and "\x00" not in value and not value.lstrip().lower().startswith("error:")):
                    break
            except Exception as e:
                message = str(e).replace("\x00", "")[:1024]
                disasm[t] = None
                result["diagnostics"].append({
                    "section": "disassembly",
                    "target": str(t),
                    "status": "unavailable",
                    "message": message,
                })
        result["disassembly"] = disasm
        result["textSelection"] = {
            "mode": text_mode, "embeddedSourcePreferred": text_mode == "preferred" and has_source,
            "attemptedTargets": attempted_targets,
        }

        # Embedded source
        if refl.debugInfo and hasattr(refl.debugInfo, "files") and refl.debugInfo.files:
            result["sourceFiles"] = [
                {"filename": f.filename, "contents": f.contents}
                for f in refl.debugInfo.files
            ]
            result["sourceProvenance"] = {
                "kind": "embedded-debug-information",
                "originalSourceProvenanceVerified": False,
                "reason": (
                    "RenderDoc exposed debug source files, but this evidence bundle "
                    "does not independently prove their build provenance."
                ),
            }

        # Input/output — safe attribute access for different RenderDoc versions
        def _sig(s):
            return {
                "name": getattr(s, 'varName', getattr(s, 'semanticName', '')),
                "semantic": getattr(s, 'semanticName', ''),
                "idx": getattr(s, 'semanticIndex', 0),
                "type": str(getattr(s, 'compType', getattr(s, 'varType', ''))),
                "count": getattr(s, 'compCount', 0),
            }

        result["inputs"] = [_sig(s) for s in refl.inputSignature]
        result["outputs"] = [_sig(s) for s in refl.outputSignature]

        # Bound textures
        name_lookup = {}
        for r in ctrl.GetResources():
            name_lookup[int(r.resourceId)] = r.name

        tex_lookup = {}
        for t in ctrl.GetTextures():
            tex_lookup[int(t.resourceId)] = t

        bound_textures = []
        try:
            ro_bindings = ps.GetReadOnlyResources(stage)
        except Exception:
            ro_bindings = None

        for i, ro in enumerate(getattr(refl, 'readOnlyResources', [])):
            if not getattr(ro, 'isTexture', False):
                continue
            ro_name = getattr(ro, 'name', 'tex%d' % i)
            tex_entry = {
                "slot": i, "name": ro_name, "bind": getattr(ro, 'fixedBindNumber', i),
                "resourceId": 0,
            }
            # Resolve bound resource — compatible with D3D11/D3D12/Vulkan/GL
            tex_entry["resourceId"] = _resolve_bound_resource(ro_bindings, i, ctrl)

            rid = tex_entry["resourceId"]
            if rid and rid in tex_lookup:
                t = tex_lookup[rid]
                tex_entry["texName"] = name_lookup.get(rid, "")
                tex_entry["width"] = t.width
                tex_entry["height"] = t.height
                tex_entry["format"] = _fmt_str(t.format)
                inferred_role = _infer_role(
                    ro_name, name_lookup.get(rid, ""), _fmt_str(t.format))
            else:
                inferred_role = _infer_role(ro_name, "", "")
            # Compatibility retains ``role`` while the evidence contract makes
            # its heuristic origin explicit. It is never a reflected fact.
            tex_entry["role"] = inferred_role
            tex_entry["roleInference"] = {
                "value": inferred_role,
                "basis": "reflection/resource names and texture-format heuristic",
                "confidence": "low",
                "observed": False,
            }
            bound_textures.append(tex_entry)
        result["boundTextures"] = bound_textures

        # Constant buffers with values
        cbufs = []
        cb_list = getattr(refl, 'constantBlocks', [])
        for idx, cb in enumerate(cb_list):
            binding = _get_constant_block_binding(ps, stage, idx)
            bind_number = _safe_int(getattr(cb, "fixedBindNumber", idx), idx)
            register_space = _safe_int(getattr(cb, "fixedBindSetOrSpace", 0), 0)
            layout_fields = _constant_block_fields(cb)
            _apply_layout_aliases(
                layout_fields, int(sid), stage_name, entry_point, raw_sha256,
                bind_number, register_space)

            cb_info = {
                "name": getattr(cb, 'name', ''),
                "size": getattr(cb, 'byteSize', 0),
                "byteSize": getattr(cb, 'byteSize', 0),
                "index": idx,
                "bind": bind_number,
                "space": register_space,
                "bufferId": binding["resourceId"],
                "byteOffset": binding["byteOffset"],
                "boundByteSize": binding["byteSize"],
                "layoutFields": layout_fields,
            }
            cb_aliases = _matching_binding_aliases(
                int(sid), stage_name, entry_point, raw_sha256,
                "constantBuffer", bind_number, register_space)
            if cb_aliases:
                cb_info["alias"] = cb_aliases[0]
                cb_info["displayName"] = _alias_display_name(cb_aliases[0])

            try:
                buffer_rid = _resource_id_lookup(
                    ctrl.GetResources(), binding["resourceId"])
                if buffer_rid is None:
                    buffer_rid = rd.ResourceId()
                variables = ctrl.GetCBufferVariableContents(
                    pid, sid, stage, entry_point, idx, buffer_rid,
                    binding["byteOffset"], binding["byteSize"])
                cb_info["variables"] = [_var_dict(v) for v in variables]
                cb_info["variablesStatus"] = "available"
            except Exception as exc:
                cb_info["variables"] = []
                cb_info["variablesStatus"] = "unavailable"
                message = str(exc).replace("\x00", "")[:1024]
                cb_info["variablesDiagnostic"] = message
                result["diagnostics"].append({
                    "section": "constant-buffer-values",
                    "constantBlockIndex": idx,
                    "status": "unavailable",
                    "message": message,
                })
            _copy_layout_aliases_to_values(cb_info["variables"], layout_fields)
            cbufs.append(cb_info)
        result["constantBuffers"] = cbufs

        # Samplers
        samplers = []
        try:
            smp_bound = ps.GetSamplers(stage)
        except Exception:
            smp_bound = None
        for i, s in enumerate(getattr(refl, 'samplers', [])):
            se = {"slot": i, "name": getattr(s, 'name', '')}
            if smp_bound and i < len(smp_bound):
                sb = smp_bound[i]
                for attr in ['addressU', 'addressV', 'addressW', 'filter']:
                    if hasattr(sb, attr):
                        se[attr] = str(getattr(sb, attr))
            samplers.append(se)
        result["samplers"] = samplers

        disassembly_values = list(disasm.values())
        disassembly_available = sum(
            1 for value in disassembly_values
            if isinstance(value, str) and bool(value.strip()))
        cbuffer_value_statuses = [
            value.get("variablesStatus") for value in cbufs
        ]
        result["sectionStatus"] = {
            "identity": "complete" if raw_sha256 else "partial",
            "compiledInterface": (
                "complete" if compiled_interface.get("interfaceComplete") is True
                else "partial"
            ),
            "disassembly": (
                "complete" if disassembly_values and
                disassembly_available == len(disassembly_values)
                else "partial" if disassembly_available
                else "unavailable"
            ),
            "embeddedDebugSource": (
                "available" if result.get("sourceFiles") else "unavailable"
            ),
            "constantBufferValues": (
                "not-applicable" if not cbuffer_value_statuses
                else "complete" if all(
                    value == "available" for value in cbuffer_value_statuses)
                else "partial" if any(
                    value == "available" for value in cbuffer_value_statuses)
                else "unavailable"
            ),
        }

        result["evidenceContract"] = {
            "observed": [
                "api", "encoding", "entryPointSelection", "rawSha256",
                "compiledInterface", "disassembly", "boundTextures",
                "constantBuffers", "samplers",
            ],
            "inferred": ["boundTextures.roleInference"],
            "generatedSource": False,
            "semanticEquivalenceVerified": False,
        }
        if not raw_sha256:
            result["unknowns"].append(
                "RenderDoc did not expose raw shader bytes, so raw identity is unavailable."
            )

        return result

    return _replay(_do)


def _dimension_triplet(value):
    if value is None:
        return None
    result = []
    for index, field in enumerate(("x", "y", "z")):
        component = getattr(value, field, None)
        if component is None:
            try:
                component = value[index]
            except Exception:
                return None
        component = _safe_int(component, -1)
        if component < 0:
            return None
        result.append(component)
    return tuple(result)


def _frame_flow_text(value, maximum=MAX_FRAME_FLOW_TEXT):
    # Zero-valued SWIG enums include Add and Zero blend operations/factors.
    # They are observations, not missing text.
    text = str("" if value is None else value).replace("\x00", "").strip()
    return text[:maximum]


def _frame_flow_json_bytes(value):
    return len(_ipc_json_bytes(value))


def _frame_flow_response_json_bytes(value):
    """Measure a result in the exact JSON envelope written to the mailbox."""
    tracker = _request_event_tracker() or {}
    return len(_ipc_json_bytes({
        "id": tracker.get("requestId", "?"),
        "result": value,
    }))


def _bounded_frame_flow_resource_metadata(ctrl):
    """Build a capture-local lookup under explicit record and byte budgets."""
    metadata = {}
    entry_bytes = {}
    budgeted_bytes = [0]
    source_records = [0]
    omitted_source_records = [0]

    def _retain(resource_id, values):
        resource_id = _resource_id_int(resource_id)
        if not resource_id:
            return
        source_records[0] += 1
        existing = dict(metadata.get(resource_id, {}))
        candidate = dict(existing)
        candidate.update(values)
        if (resource_id not in metadata and
                len(metadata) >= MAX_FRAME_FLOW_RESOURCE_METADATA_RECORDS):
            omitted_source_records[0] += 1
            return
        encoded_size = _frame_flow_json_bytes({
            "resourceId": resource_id,
            "metadata": candidate,
        })
        next_size = (
            budgeted_bytes[0] - entry_bytes.get(resource_id, 0) +
            encoded_size)
        if next_size > MAX_FRAME_FLOW_RESOURCE_METADATA_BYTES:
            omitted_source_records[0] += 1
            return
        metadata[resource_id] = candidate
        entry_bytes[resource_id] = encoded_size
        budgeted_bytes[0] = next_size

    try:
        for resource in ctrl.GetResources() or []:
            _retain(
                getattr(resource, "resourceId", None),
                {"name": _frame_flow_text(getattr(resource, "name", ""))})
    except Exception:
        pass
    try:
        for texture in ctrl.GetTextures() or []:
            values = {
                "format": _fmt_str(getattr(texture, "format", None))[:256],
            }
            samples = getattr(texture, "msSamp", None)
            if (isinstance(samples, int) and not isinstance(samples, bool) and
                    samples > 0):
                values["sampleCount"] = int(samples)
            _retain(getattr(texture, "resourceId", None), values)
    except Exception:
        pass

    receipt = {
        "sourceRecordCount": source_records[0],
        "retainedEntryCount": len(metadata),
        "omittedSourceRecordCount": omitted_source_records[0],
        "recordLimit": MAX_FRAME_FLOW_RESOURCE_METADATA_RECORDS,
        "byteBudget": MAX_FRAME_FLOW_RESOURCE_METADATA_BYTES,
        "budgetedBytes": budgeted_bytes[0],
        "truncated": bool(omitted_source_records[0]),
    }
    return metadata, receipt


def _frame_flow_subresource(value):
    if value is None:
        return None
    result = {}
    for source, target in (
            ("mip", "mip"), ("slice", "slice"),
            ("sample", "sample"), ("plane", "plane")):
        component = _safe_int(getattr(value, source, -1), -1)
        if component >= 0:
            result[target] = component
    return result or None


def _frame_flow_descriptor_fields(fact, value):
    descriptor = getattr(value, "descriptor", value)
    if descriptor is None:
        return fact
    descriptor_format = _fmt_str(getattr(descriptor, "format", None))[:256]
    if descriptor_format:
        fact["format"] = descriptor_format
    for field in (
            "byteOffset", "byteSize", "firstMip", "numMips",
            "firstSlice", "numSlices"):
        number = _safe_int(getattr(descriptor, field, -1), -1)
        if number >= 0:
            fact[field] = number
    access = getattr(value, "access", None)
    if access is not None and isinstance(
            getattr(access, "staticallyUnused", None), bool):
        fact["staticallyUnused"] = bool(access.staticallyUnused)
    return fact


def _action_workload(action):
    flags = _safe_int(getattr(action, "flags", 0), 0)
    result = {
        "indexCount": _safe_int(getattr(action, "numIndices", 0), 0),
        "vertexCount": _safe_int(
            getattr(action, "numVertices", getattr(action, "numIndices", 0)), 0),
        "instanceCount": (
            _safe_int(getattr(action, "numInstances", 0), 0)
            if flags & _action_flags_mask(("Instanced", "Indirect"), 0x0A0000)
            else 1),
    }
    for attribute, field in (
            ("indexOffset", "indexOffset"),
            ("vertexOffset", "vertexOffset"),
            ("instanceOffset", "instanceOffset"),
            ("baseVertex", "baseVertex")):
        raw = getattr(action, attribute, None)
        result[field] = (
            int(raw)
            if isinstance(raw, int) and not isinstance(raw, bool) else None)
    raw_draw_index = getattr(action, "drawIndex", None)
    result["drawIndex"] = (
        int(raw_draw_index)
        if isinstance(raw_draw_index, int) and
        not isinstance(raw_draw_index, bool) and raw_draw_index >= 0
        else None)
    groups = _dimension_triplet(getattr(action, "dispatchDimension", None))
    if groups is not None:
        result.update({
            "groupCountX": groups[0],
            "groupCountY": groups[1],
            "groupCountZ": groups[2],
        })
    threads = _dimension_triplet(
        getattr(action, "dispatchThreadsDimension", None))
    if threads is not None:
        result.update({
            "threadCountX": threads[0],
            "threadCountY": threads[1],
            "threadCountZ": threads[2],
        })
    dispatch_base = _dimension_triplet(getattr(action, "dispatchBase", None))
    result["dispatchBase"] = (
        list(dispatch_base) if dispatch_base is not None else None)
    if flags & _action_flags_mask(("Indirect",), 0x080000):
        result["indirectArgumentsResolved"] = False
    return result


def _finite_pipeline_number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    value = float(value) if isinstance(value, float) else int(value)
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def _optional_pipeline_bool(value, attribute):
    raw = getattr(value, attribute, None)
    return bool(raw) if isinstance(raw, bool) else None


def _optional_pipeline_int(value, attribute, minimum=0):
    raw = getattr(value, attribute, None)
    if isinstance(raw, int) and not isinstance(raw, bool) and raw >= minimum:
        return int(raw)
    return None


def _pass_blend_equation(value):
    result = {}
    for source, target in (
            ("source", "sourceFactor"),
            ("destination", "destinationFactor"),
            ("operation", "operation")):
        raw = getattr(value, source, None) if value is not None else None
        result[target] = (
            _frame_flow_text(raw, 128) if raw is not None else None)
    return result


def _pass_color_blend_state(blend, slot):
    """Return complete, explicitly nullable RenderDoc ColorBlend evidence."""
    write_mask = _optional_pipeline_int(blend, "writeMask")
    logic_operation = getattr(blend, "logicOperation", None)
    return {
        "slot": int(slot),
        "blendEnabled": _optional_pipeline_bool(blend, "enabled"),
        "logicOperationEnabled": _optional_pipeline_bool(
            blend, "logicOperationEnabled"),
        "colorBlend": _pass_blend_equation(
            getattr(blend, "colorBlend", None)),
        "alphaBlend": _pass_blend_equation(
            getattr(blend, "alphaBlend", None)),
        "logicOperation": (
            _frame_flow_text(logic_operation, 128)
            if logic_operation is not None else None),
        "writeMask": write_mask,
        "writeChannels": (
            "".join(
                channel for bit, channel in
                ((1, "R"), (2, "G"), (4, "B"), (8, "A"))
                if write_mask & bit)
            if write_mask is not None else None),
    }


def _pass_blend_enabled(blend_states):
    values = [
        _optional_pipeline_bool(value, "enabled")
        for value in blend_states
    ]
    if any(value is True for value in values):
        return True
    if values and all(value is False for value in values):
        return False
    return None


def _pass_vertex_layout(vertex_inputs):
    result = []
    values = list(vertex_inputs or [])
    for index, value in enumerate(
            values[:MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]):
        name = getattr(value, "name", None)
        raw_format = getattr(value, "format", None)
        result.append({
            "index": index,
            "name": (
                _frame_flow_text(name, 256) if name is not None else None),
            "vertexBuffer": _optional_pipeline_int(
                value, "vertexBuffer"),
            "byteOffset": _optional_pipeline_int(value, "byteOffset"),
            "format": (
                _fmt_str(raw_format)[:256]
                if raw_format is not None else None),
            "perInstance": _optional_pipeline_bool(value, "perInstance"),
            "instanceRate": _optional_pipeline_int(value, "instanceRate"),
            "genericEnabled": _optional_pipeline_bool(
                value, "genericEnabled"),
            "used": _optional_pipeline_bool(value, "used"),
        })
    return result, max(0, len(values) - len(result))


def _pass_attachment_sample_state(targets, depth_target):
    attachments = list(targets or [])
    if depth_target is not None:
        attachments.append(depth_target)
    counts = [
        value.get("sampleCount")
        for value in attachments
        if isinstance(value.get("sampleCount"), int) and
        not isinstance(value.get("sampleCount"), bool) and
        value.get("sampleCount") > 0
    ]
    resolved = bool(attachments) and len(counts) == len(attachments)
    if resolved and len(set(counts)) == 1:
        return {"sampleCount": counts[0], "sampleCountResolved": True}
    return {"sampleCount": None, "sampleCountResolved": False}


def _raster_output_applicability(action_flags, has_action, shaders,
                                  draw_state, fragment_stage_resolved):
    if not has_action:
        return None, "unknown-action"
    draw_mask = _action_flags_mask(("Drawcall",), 0x0002)
    mesh_mask = _action_flags_mask(("MeshDispatch",), 0x0008)
    if not action_flags & (draw_mask | mesh_mask):
        return False, "non-raster-action"
    rasterizer_discard = draw_state.get("rasterizerDiscardEnabled")
    if rasterizer_discard is True:
        return False, "rasterizer-discard"
    if rasterizer_discard is not False:
        return None, "rasterizer-discard-unknown"
    if fragment_stage_resolved and "fragment" not in shaders:
        # A fragment-less raster draw cannot write color, but APIs such as D3D
        # can still perform depth/stencil testing and writes.  Keep the overall
        # raster path applicable and let callers suppress only color/blend I/O.
        return True, "no-fragment-shader"
    return True, None


_COLOR_RASTER_IO_ACCESSES = frozenset((
    "blend-destination",
    "color-target",
    "color-target-possible",
))


_RASTER_IO_ACCESSES = frozenset((
    *_COLOR_RASTER_IO_ACCESSES,
    "depth-test",
    "stencil-test",
    "depth-target",
    "depth-target-possible",
    "stencil-target-possible",
))


def _without_raster_io(values):
    return [
        value for value in values
        if value.get("access") not in _RASTER_IO_ACCESSES
    ]


def _without_color_raster_io(values):
    return [
        value for value in values
        if value.get("access") not in _COLOR_RASTER_IO_ACCESSES
    ]


def _downgrade_raster_writes(values, certainty):
    """Move definite raster writes to bounded possible-output evidence."""
    retained = []
    possible = []
    access_map = {
        "color-target": "color-target-possible",
        "depth-target": "depth-target-possible",
    }
    for value in values:
        possible_access = access_map.get(value.get("access"))
        if possible_access is None:
            retained.append(value)
            continue
        candidate = dict(value)
        candidate["access"] = possible_access
        candidate["certainty"] = certainty
        possible.append(candidate)
    return retained, possible


def _frame_flow_resource_range(value):
    result = {}
    for field in (
            "byteOffset", "byteSize", "firstMip", "numMips",
            "firstSlice", "numSlices"):
        number = _safe_int(value.get(field, -1), -1)
        if number >= 0:
            result[field] = number
    subresource = value.get("subresource")
    if isinstance(subresource, dict):
        result["subresource"] = dict(subresource)
    return result


def _coalesce_utility_output_aliases(values):
    """Merge dedicated and coarse utility destinations, retaining roles."""
    result = []
    for raw in values:
        item = dict(raw)
        access = item.get("access", "")
        roles = [
            str(role) for role in item.get("roles", [])
            if isinstance(role, str) and role
        ]
        if access and access not in roles:
            roles.append(access)
        item_range = _frame_flow_resource_range(item)
        match = next((
            existing for existing in result
            if existing.get("resourceId", 0) == item.get("resourceId", 0)
            and (
                _frame_flow_resource_range(existing) == item_range
                or not _frame_flow_resource_range(existing)
                or not item_range)
        ), None)
        if match is None:
            item["roles"] = roles
            result.append(item)
            continue
        merged_roles = list(match.get("roles", []))
        for role in roles:
            if role not in merged_roles:
                merged_roles.append(role)
        match["roles"] = merged_roles
        if (match.get("access") == "action-output" and
                access == "copy-destination"):
            match["access"] = access
        if not _frame_flow_resource_range(match) and item_range:
            for field, value in item_range.items():
                match[field] = value
        for field in ("name", "format"):
            if not match.get(field) and item.get(field):
                match[field] = item[field]
    return result


def _pass_stream_output_resources(ctrl, resource_fact):
    """Return active-backend stream/transform-feedback output bindings."""
    try:
        pipeline_type = str(ctrl.GetAPIProperties().pipelineType).lower()
    except Exception:
        return [], 0
    bindings = []
    kind = ""
    try:
        if "d3d11" in pipeline_type:
            bindings = list(getattr(
                getattr(ctrl.GetD3D11PipelineState(), "streamOut", None),
                "outputs", []) or [])
            kind = "d3d"
        elif "d3d12" in pipeline_type:
            bindings = list(getattr(
                getattr(ctrl.GetD3D12PipelineState(), "streamOut", None),
                "outputs", []) or [])
            kind = "d3d"
        elif "vulkan" in pipeline_type:
            bindings = [
                value for value in list(getattr(
                    getattr(ctrl.GetVulkanPipelineState(),
                            "transformFeedback", None),
                    "buffers", []) or [])
                if getattr(value, "active", None) is True
            ]
            kind = "vulkan"
        elif "opengl" in pipeline_type or pipeline_type.endswith(".gl"):
            feedback = getattr(
                ctrl.GetOpenGLPipelineState(), "transformFeedback", None)
            if (getattr(feedback, "active", None) is True and
                    getattr(feedback, "paused", None) is not True):
                resource_ids = list(
                    getattr(feedback, "bufferResourceId", []) or [])
                offsets = list(getattr(feedback, "byteOffset", []) or [])
                sizes = list(getattr(feedback, "byteSize", []) or [])
                bindings = [
                    {
                        "resourceId": resource_id,
                        "byteOffset": (offsets[index]
                                       if index < len(offsets) else None),
                        "byteSize": (sizes[index]
                                     if index < len(sizes) else None),
                    }
                    for index, resource_id in enumerate(resource_ids)
                ]
                kind = "gl"
    except Exception:
        return [], 0

    result = []
    omitted = 0

    def _append(resource_id, access, value, offset_name, size_name):
        nonlocal omitted
        resource_id = _resource_id_int(resource_id)
        if not resource_id:
            return
        if len(result) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
            omitted += 1
            return
        fact = resource_fact(resource_id)
        fact["access"] = access
        fact["stage"] = "stream-output"
        if isinstance(value, dict):
            offset = value.get(offset_name)
            size = value.get(size_name)
            offset = (int(offset) if isinstance(offset, int) and
                      not isinstance(offset, bool) and offset >= 0 else None)
            size = (int(size) if isinstance(size, int) and
                    not isinstance(size, bool) and size >= 0 else None)
        else:
            offset = _optional_pipeline_int(value, offset_name)
            size = _optional_pipeline_int(value, size_name)
        if offset is not None:
            fact["byteOffset"] = offset
        if size is not None:
            fact["byteSize"] = size
        result.append(fact)

    for value in bindings:
        if isinstance(value, dict):
            resource_id = value.get("resourceId")
        else:
            resource_id = getattr(
                value, "bufferResourceId",
                getattr(value, "resourceId", None))
        _append(resource_id, "stream-output", value, "byteOffset", "byteSize")
        if kind in ("d3d", "vulkan"):
            counter_id = getattr(
                value, "counterBufferResourceId",
                getattr(value, "writtenCountResourceId", None))
            counter_offset = (
                "counterBufferOffset" if kind == "vulkan"
                else "writtenCountByteOffset")
            _append(
                counter_id, "stream-output-counter", value,
                counter_offset, "__missing_byte_size")
    return result, omitted


def _pass_draw_state(ps):
    result = {
        "stencilStateResolved": False,
        "colorWriteMasksResolved": False,
        "attachmentSubresourcesResolved": False,
        "rasterStateResolved": False,
    }
    try:
        topology = ps.GetPrimitiveTopology()
        if topology is not None:
            text = str(topology)
            if text and len(text) <= 256:
                result["topology"] = text
    except Exception:
        pass
    try:
        rasterized_stream = ps.GetRasterizedStream()
        if (isinstance(rasterized_stream, int) and
                not isinstance(rasterized_stream, bool)):
            result["rasterizedStream"] = int(rasterized_stream)
            result["rasterizerDiscardEnabled"] = rasterized_stream < 0
    except Exception:
        pass
    try:
        viewport = ps.GetViewport(0)
        if viewport:
            values = {}
            for source, target in (
                    ("x", "x"), ("y", "y"),
                    ("width", "width"), ("height", "height"),
                    ("minDepth", "minDepth"), ("maxDepth", "maxDepth")):
                number = _finite_pipeline_number(getattr(viewport, source, None))
                if number is not None:
                    values[target] = number
            if values:
                result["viewport"] = values
    except Exception:
        pass
    try:
        scissor = ps.GetScissor(0)
        if scissor:
            values = {}
            for source in ("x", "y", "width", "height"):
                number = _finite_pipeline_number(getattr(scissor, source, None))
                if number is not None:
                    values[source] = number
            if values:
                result["scissor"] = values
    except Exception:
        pass
    try:
        faces = ps.GetStencilFaces()
        front = faces[0]
        back = faces[1]

        def _stencil_face(value):
            face = {}
            for source, target in (
                    ("function", "function"),
                    ("failOperation", "failOperation"),
                    ("depthFailOperation", "depthFailOperation"),
                    ("passOperation", "passOperation")):
                raw = getattr(value, source, None)
                if raw is not None:
                    text = _frame_flow_text(raw, 128)
                    if text:
                        face[target] = text
            for source in ("reference", "compareMask", "writeMask"):
                raw = getattr(value, source, None)
                if isinstance(raw, int) and not isinstance(raw, bool) and raw >= 0:
                    face[source] = int(raw)
            return face

        front_face = _stencil_face(front)
        back_face = _stencil_face(back)
        if front_face or back_face:
            result["stencilStateResolved"] = True
            result["stencilFront"] = front_face
            result["stencilBack"] = back_face

            def _face_can_write(face):
                if _safe_int(face.get("writeMask", 0), 0) <= 0:
                    return False
                return any(
                    str(face.get(field, "")).lower().rsplit(".", 1)[-1]
                    not in ("", "keep")
                    for field in (
                        "failOperation", "depthFailOperation", "passOperation")
                )

            result["stencilWriteOperationsCanWrite"] = (
                _face_can_write(front_face) or _face_can_write(back_face))
    except Exception:
        pass
    return result


def _pass_depth_state(ctrl):
    """Return active-backend depth, stencil, and raster facts."""
    try:
        pipeline_type = str(ctrl.GetAPIProperties().pipelineType).lower()
    except Exception:
        return {}
    candidate = (None, None, None, None, None)
    try:
        if "d3d11" in pipeline_type:
            value = ctrl.GetD3D11PipelineState()
            output_merger = getattr(value, "outputMerger", None)
            candidate = (
                getattr(output_merger, "depthStencilState", None),
                getattr(output_merger, "depthReadOnly", None),
                getattr(output_merger, "depthStencilState", None),
                getattr(output_merger, "stencilReadOnly", None),
                getattr(getattr(value, "rasterizer", None), "state", None),
            )
    except Exception:
        return {}
    try:
        if "d3d12" in pipeline_type:
            value = ctrl.GetD3D12PipelineState()
            output_merger = getattr(value, "outputMerger", None)
            candidate = (
                getattr(output_merger, "depthStencilState", None),
                getattr(output_merger, "depthReadOnly", None),
                getattr(output_merger, "depthStencilState", None),
                getattr(output_merger, "stencilReadOnly", None),
                getattr(getattr(value, "rasterizer", None), "state", None),
            )
    except Exception:
        return {}
    try:
        if "vulkan" in pipeline_type:
            value = ctrl.GetVulkanPipelineState()
            candidate = (
                getattr(value, "depthStencil", None), False,
                getattr(value, "depthStencil", None), None,
                getattr(value, "rasterizer", None),
            )
    except Exception:
        return {}
    try:
        if "opengl" in pipeline_type or pipeline_type.endswith(".gl"):
            value = ctrl.GetOpenGLPipelineState()
            candidate = (
                getattr(value, "depthState", None), False,
                getattr(value, "stencilState", None), None,
                getattr(getattr(value, "rasterizer", None), "state", None),
            )
    except Exception:
        return {}
    state, read_only, stencil_state, stencil_read_only, raster_state = candidate
    result = {}
    if state is not None:
        result["depthStateResolved"] = True
        enabled = getattr(
            state, "depthEnable", getattr(state, "depthTestEnable", None))
        writes = getattr(
            state, "depthWrites", getattr(state, "depthWriteEnable", None))
        depth_function = getattr(state, "depthFunction", None)
        if isinstance(enabled, bool):
            result["depthTestEnabled"] = enabled
        if isinstance(writes, bool):
            result["depthWriteEnabled"] = writes and read_only is not True
        if isinstance(read_only, bool):
            result["depthReadOnly"] = read_only
        if depth_function is not None:
            result["depthFunction"] = _frame_flow_text(depth_function, 128)
    if stencil_state is not None:
        enabled = getattr(
            stencil_state, "stencilEnable",
            getattr(stencil_state, "stencilTestEnable", None))
        if isinstance(enabled, bool):
            result["stencilTestEnabled"] = enabled
        if isinstance(stencil_read_only, bool):
            result["stencilReadOnly"] = stencil_read_only
    if raster_state is not None:
        result["rasterStateResolved"] = True
        for source, target in (("cullMode", "cullMode"),
                               ("fillMode", "fillMode")):
            raw = getattr(raster_state, source, None)
            if raw is not None:
                result[target] = _frame_flow_text(raw, 128)
        front_ccw = getattr(raster_state, "frontCCW", None)
        if isinstance(front_ccw, bool):
            result["frontCCW"] = front_ccw
        discard = getattr(raster_state, "rasterizerDiscardEnable", None)
        if isinstance(discard, bool):
            result["rasterizerDiscardEnabled"] = discard
    return result


def _pass_sampler_binding(item):
    """Return bounded sampler state without claiming a runtime shader access."""
    access = getattr(item, "access", None)
    sampler = getattr(item, "sampler", item)
    result = {
        "accessEvidence": "unknown",
        "runtimeAccessProven": False,
    }
    if access is not None:
        index = _safe_int(getattr(access, "index", -1), -1)
        result["directAccess"] = index == 0xffff
        if index >= 0 and index != 0xffff:
            result["bindingIndex"] = index
        array_element = _safe_int(getattr(access, "arrayElement", -1), -1)
        if array_element >= 0:
            result["arrayElement"] = array_element
        descriptor_store = _resource_id_int(
            getattr(access, "descriptorStore", None))
        if descriptor_store:
            result["descriptorStoreId"] = descriptor_store
        for source, target in (("byteOffset", "descriptorByteOffset"),
                               ("byteSize", "descriptorByteSize")):
            value = getattr(access, source, None)
            if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
                result[target] = int(value)
        statically_unused = getattr(access, "staticallyUnused", None)
        if isinstance(statically_unused, bool):
            result["staticallyUnused"] = statically_unused
            result["accessEvidence"] = (
                "statically-unused" if statically_unused
                else "not-statically-unused-candidate")
    sampler_id = _resource_id_int(getattr(sampler, "object", None))
    if sampler_id:
        result["samplerResourceId"] = sampler_id
    creation_constant = getattr(sampler, "creationTimeConstant", None)
    if isinstance(creation_constant, bool):
        result["creationTimeConstant"] = creation_constant
    for source in (
            "type", "addressU", "addressV", "addressW", "compareFunction",
            "filter"):
        raw = getattr(sampler, source, None)
        if raw is not None:
            result[source] = _frame_flow_text(raw, 128)
    for source in ("maxAnisotropy", "minLOD", "maxLOD", "mipBias"):
        number = _finite_pipeline_number(getattr(sampler, source, None))
        if number is not None:
            result[source] = number
    return result


def _collect_current_frame_inputs(params, require_capture_id, result_schema):
    """Collect bounded action and pipeline facts in one replay transaction."""
    if require_capture_id:
        expected_capture_id = _require_capture_identity(
            params.get("expected_capture_id"))
    else:
        expected_capture_id = str(
            params.get("expected_capture_id", "") or "").strip().lower()
        if expected_capture_id:
            expected_capture_id = _shader_override_hex(
                expected_capture_id, "expected_capture_id", 64)
    expected_session = _shader_override_hex(
        params.get("expected_capture_session_id"),
        "expected_capture_session_id", 32)
    if not _capture_session_id or expected_session != _capture_session_id:
        raise RuntimeError("Capture session changed before pass classification")
    maximum = _safe_int(params.get("max_actions", 100000), -1)
    if maximum < 1 or maximum > 100000:
        raise ValueError("max_actions must be between 1 and 100000")
    try:
        original_event = _request_visible_event_id(0)
        restore_original_event = True
    except Exception:
        original_event = 0
        restore_original_event = False

    def _do(ctrl):
        resource_metadata, resource_metadata_receipt = (
            _bounded_frame_flow_resource_metadata(ctrl))

        def _resource_fact(resource_id):
            resource_id = _resource_id_int(resource_id)
            metadata = resource_metadata.get(resource_id, {})
            fact = {
                "resourceId": resource_id,
                "name": metadata.get("name", ""),
                "format": metadata.get("format", ""),
            }
            if "sampleCount" in metadata:
                fact["sampleCount"] = metadata["sampleCount"]
            return fact

        actions = []
        truncated = [False]
        omitted_lower_bound = [0]
        truncation_reasons = []
        action_serialized_bytes = [2]

        def _flatten(values, depth=0, marker_path=None,
                     marker_event_path=None, parent_event_id=0):
            marker_path = marker_path or []
            marker_event_path = marker_event_path or []
            for action in values:
                if len(actions) >= maximum:
                    truncated[0] = True
                    omitted_lower_bound[0] += 1
                    return True
                flags = _safe_int(getattr(action, "flags", 0), 0)
                name = _frame_flow_text(_action_name(action))
                children = getattr(action, "children", None) or []
                is_context = bool(children) or bool(flags & _marker_action_mask())
                current_path = marker_path + ([name] if is_context else [])
                event_id = _safe_int(getattr(action, "eventId", 0), 0)
                marker_identity = {"eventId": event_id, "name": name}
                current_event_path = marker_event_path + (
                    [marker_identity] if is_context else [])
                entry = {
                    "eventId": event_id,
                    "name": name,
                    "flags": flags,
                    "numIndices": _safe_int(getattr(action, "numIndices", 0), 0),
                    # RenderDoc uses numIndices as the vertex count for
                    # non-indexed draws. Keep a future adapter's explicit
                    # numVertices value when it is available.
                    "numVertices": _safe_int(
                        getattr(action, "numVertices",
                                getattr(action, "numIndices", 0)), 0),
                    "numInstances": _safe_int(getattr(action, "numInstances", 0), 0),
                    "depth": depth,
                    "markerPath": current_path if is_context else marker_path,
                    "markerEventPath": (
                        current_event_path if is_context else marker_event_path),
                    "parentEventId": _safe_int(parent_event_id, 0),
                    "executionIndex": len(actions),
                    "workload": _action_workload(action),
                }
                outputs = getattr(action, "outputs", None) or []
                if outputs:
                    output_ids = [
                        output for output in outputs
                        if _resource_id_int(output)]
                    entry["outputs"] = [
                        _resource_fact(output)
                        for output in output_ids[
                            :MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]]
                    if (len(output_ids) >
                            MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION):
                        entry["outputOmittedCount"] = (
                            len(output_ids) -
                            MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION)
                copy_source = _resource_id_int(
                    getattr(action, "copySource", None))
                copy_destination = _resource_id_int(
                    getattr(action, "copyDestination", None))
                if copy_source:
                    entry["copySource"] = _resource_fact(copy_source)
                    subresource = _frame_flow_subresource(
                        getattr(action, "copySourceSubresource", None))
                    if subresource:
                        entry["copySource"]["subresource"] = subresource
                if copy_destination:
                    entry["copyDestination"] = _resource_fact(copy_destination)
                    subresource = _frame_flow_subresource(
                        getattr(action, "copyDestinationSubresource", None))
                    if subresource:
                        entry["copyDestination"]["subresource"] = subresource
                depth_output = _resource_id_int(
                    getattr(action, "depthOut", None))
                if depth_output:
                    entry["depthOutput"] = _resource_fact(depth_output)
                encoded_size = _frame_flow_json_bytes(entry) + 1
                if (action_serialized_bytes[0] + encoded_size >
                        MAX_FRAME_FLOW_ACTION_BYTES):
                    truncated[0] = True
                    omitted_lower_bound[0] += 1
                    if "serialized-size-budget" not in truncation_reasons:
                        truncation_reasons.append("serialized-size-budget")
                    return True
                actions.append(entry)
                action_serialized_bytes[0] += encoded_size
                if children:
                    if _flatten(
                            children, depth + 1, current_path,
                            current_event_path, event_id):
                        return True
            return False

        _flatten(ctrl.GetRootActions())
        if truncated[0] and "serialized-size-budget" not in truncation_reasons:
            truncation_reasons.append("action-limit")
        actionable_mask = _draw_dispatch_action_mask()
        pipeline_states = {}

        def _used_resources(ps, method_name, stage, stage_name, access):
            method = getattr(ps, method_name, None)
            if method is None:
                return [], 0
            try:
                used = method(stage, True)
            except TypeError:
                used = method(stage)
            except Exception:
                return [], 0
            result = []
            omitted = 0
            for item in used or []:
                descriptor = getattr(item, "descriptor", item)
                resource_id = _resource_id_int(getattr(descriptor, "resource", None))
                if resource_id:
                    if len(result) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                        omitted += 1
                        continue
                    fact = _resource_fact(resource_id)
                    fact["stage"] = stage_name
                    fact["access"] = access
                    result.append(_frame_flow_descriptor_fields(fact, item))
            return result, omitted

        def _read_write_resources(ps, stage, stage_name):
            method = getattr(ps, "GetReadWriteResources", None)
            if method is None:
                return [], [], 0, 0
            try:
                try:
                    used = method(stage, True)
                except TypeError:
                    used = method(stage)
            except Exception:
                return [], [], 0, 0
            read_values = []
            write_values = []
            read_omitted = 0
            write_omitted = 0
            flags_type = getattr(rd, "DescriptorFlags", None)
            read_only_mask = _safe_int(
                getattr(flags_type, "ReadOnlyAccess", 0x8), 0x8)
            write_only_mask = _safe_int(
                getattr(flags_type, "WriteOnlyAccess", 0x10), 0x10)
            for item in used or []:
                descriptor = getattr(item, "descriptor", item)
                resource_id = _resource_id_int(
                    getattr(descriptor, "resource", None))
                if not resource_id:
                    continue
                flags = _safe_int(getattr(descriptor, "flags", 0), 0)
                read_allowed = not bool(flags & write_only_mask)
                write_allowed = not bool(flags & read_only_mask)
                if read_allowed:
                    fact = _resource_fact(resource_id)
                    fact["stage"] = stage_name
                    fact["access"] = (
                        "read-write" if write_allowed else "shader-read")
                    _frame_flow_descriptor_fields(fact, item)
                    if len(read_values) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                        read_omitted += 1
                    else:
                        read_values.append(fact)
                if write_allowed:
                    fact = _resource_fact(resource_id)
                    fact["stage"] = stage_name
                    fact["access"] = (
                        "read-write" if read_allowed else "shader-write")
                    _frame_flow_descriptor_fields(fact, item)
                    if len(write_values) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                        write_omitted += 1
                    else:
                        write_values.append(fact)
            return read_values, write_values, read_omitted, write_omitted

        action_total = float(max(1, len(actions)))
        pipeline_serialized_bytes = 2
        retained_action_count = len(actions)
        try:
            for action_index, action in enumerate(actions):
                if not (action["flags"] & actionable_mask):
                    continue
                event_id = action["eventId"]
                if event_id <= 0:
                    continue
                _set_frame_event(ctrl, int(event_id), True)
                ps = ctrl.GetPipelineState()
                pipeline_id = _get_pipeline_obj(ps, ctrl)
                stages = {}
                sampler_summary = {}
                reads = []
                writes = []
                input_omitted = 0
                output_omitted = 0
                available_stages = _available_shader_stages(
                    ["vertex", "hull", "domain", "geometry", "fragment",
                     "compute", "task", "mesh"])
                fragment_stage_resolved = any(
                    stage_name == "fragment"
                    for stage_name, unused_stage in available_stages)
                for stage_name, stage in available_stages:
                    _background_replay_checkpoint()
                    shader_id = ps.GetShader(stage)
                    if not shader_id or _resource_id_int(shader_id) == 0:
                        continue
                    shader = {"shaderId": _resource_id_int(shader_id)}
                    reflection = None
                    try:
                        entries = list(ctrl.GetShaderEntryPoints(shader_id) or [])
                        selection = _pipeline_shader_entry_selection(
                            ps, stage, stage_name, shader_id, entries)
                        shader["entryPointSelection"] = dict(selection["evidence"])
                        selected = selection.get("entry")
                        if selected is not None:
                            shader["entryPoint"] = _frame_flow_text(
                                getattr(selected, "name", ""), 256)
                            reflection = ctrl.GetShader(pipeline_id, shader_id, selected)
                            identity_failure = (
                                _shader_reflection_identity_failure(
                                    reflection, selected, shader_id, pipeline_id,
                                    stage_name, selection)
                                if reflection is not None else None)
                            if identity_failure is not None:
                                shader.update(identity_failure)
                                reflection = None
                            if reflection:
                                raw = _shader_raw_bytes(reflection)
                                if raw:
                                    shader["rawSha256"] = hashlib.sha256(raw).hexdigest()
                                constant_blocks = list(
                                    getattr(reflection, "constantBlocks", []) or [])
                                reflected_samplers = list(
                                    getattr(reflection, "samplers", []) or [])
                                shader["constantBufferCount"] = len(constant_blocks)
                                shader["samplerCount"] = len(reflected_samplers)
                    except Exception:
                        pass
                    try:
                        try:
                            bound_samplers = list(ps.GetSamplers(stage, True) or [])
                        except TypeError:
                            bound_samplers = list(ps.GetSamplers(stage) or [])
                        shader["boundSamplerCount"] = len(bound_samplers)
                        sampler_bindings_resolved = True
                    except Exception:
                        bound_samplers = []
                        sampler_bindings_resolved = False
                    if ("samplerCount" in shader or
                            "boundSamplerCount" in shader or
                            sampler_bindings_resolved):
                        sampler_summary[stage_name] = {
                            "bindingsResolved": sampler_bindings_resolved,
                        }
                        if "samplerCount" in shader:
                            sampler_summary[stage_name]["declaredCount"] = (
                                shader["samplerCount"])
                        if "boundSamplerCount" in shader:
                            sampler_summary[stage_name]["boundCount"] = (
                                shader["boundSamplerCount"])
                        if sampler_bindings_resolved:
                            sampler_summary[stage_name]["bindings"] = [
                                _pass_sampler_binding(value)
                                for value in bound_samplers[
                                    :MAX_FRAME_FLOW_SAMPLERS_PER_STAGE]
                            ]
                            if (len(bound_samplers) >
                                    MAX_FRAME_FLOW_SAMPLERS_PER_STAGE):
                                sampler_summary[stage_name][
                                    "bindingOmittedCount"] = (
                                        len(bound_samplers) -
                                        MAX_FRAME_FLOW_SAMPLERS_PER_STAGE)
                    aliases = _matching_shader_aliases(
                        shader["shaderId"], stage_name,
                        shader.get("entryPoint", ""), shader.get("rawSha256"))
                    if aliases:
                        shader["displayName"] = _frame_flow_text(
                            _alias_display_name(aliases[0]))
                    stages[stage_name] = shader
                    stage_reads, omitted = _used_resources(
                        ps, "GetReadOnlyResources", stage, stage_name,
                        "shader-read")
                    reads.extend(stage_reads)
                    input_omitted += omitted
                    constant_reads, omitted = _used_resources(
                        ps, "GetConstantBlocks", stage, stage_name,
                        "constant-buffer")
                    reads.extend(constant_reads)
                    input_omitted += omitted
                    stage_rw_reads, stage_rw_writes, read_omitted, write_omitted = (
                        _read_write_resources(ps, stage, stage_name)
                    )
                    reads.extend(stage_rw_reads)
                    writes.extend(stage_rw_writes)
                    input_omitted += read_omitted
                    output_omitted += write_omitted

                graphics_output_mask = _action_flags_mask(
                    ("Drawcall", "MeshDispatch"), 0x0002 | 0x0008)
                if action["flags"] & graphics_output_mask:
                    stream_outputs, omitted = _pass_stream_output_resources(
                        ctrl, _resource_fact)
                    writes.extend(stream_outputs)
                    output_omitted += omitted

                try:
                    vertex_buffers = list(ps.GetVBuffers() or [])
                    vertex_buffer_bindings_resolved = True
                except Exception:
                    vertex_buffers = []
                    vertex_buffer_bindings_resolved = False
                try:
                    vertex_inputs = list(ps.GetVertexInputs() or [])
                    vertex_input_usage_resolved = True
                    used_vertex_slots = sorted(set(
                        _safe_int(getattr(value, "vertexBuffer", -1), -1)
                        for value in vertex_inputs
                        if getattr(value, "used", False) is True
                        and getattr(value, "genericEnabled", False) is not True
                        and _safe_int(
                            getattr(value, "vertexBuffer", -1), -1) >= 0))
                except Exception:
                    vertex_inputs = []
                    used_vertex_slots = []
                    vertex_input_usage_resolved = False
                vertex_layout, vertex_layout_omitted = _pass_vertex_layout(
                    vertex_inputs)
                bounded_vertex_slots = used_vertex_slots[
                    :MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]
                for slot in bounded_vertex_slots:
                    if slot >= len(vertex_buffers):
                        continue
                    binding = vertex_buffers[slot]
                    info = _bound_descriptor_info(binding)
                    resource_id = _safe_int(info.get("resourceId", 0), 0)
                    if resource_id:
                        fact = _resource_fact(resource_id)
                        fact["stage"] = "vertex"
                        fact["access"] = "vertex-buffer"
                        fact.update({
                            "byteOffset": _safe_int(
                                info.get("byteOffset", 0), 0),
                            "byteSize": _safe_int(
                                info.get("byteSize", 0), 0),
                            "byteStride": info.get("byteStride"),
                        })
                        reads.append(fact)
                if len(used_vertex_slots) > MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                    input_omitted += (
                        len(used_vertex_slots) -
                        MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION)
                try:
                    index_binding = _bound_descriptor_info(ps.GetIBuffer())
                    index_buffer_binding_resolved = True
                except Exception:
                    index_binding = {"resourceId": 0}
                    index_buffer_binding_resolved = False
                index_resource = _safe_int(
                    index_binding.get("resourceId", 0), 0)
                indexed_mask = _action_flags_mask(("Indexed",), 0x010000)
                if index_resource and indexed_mask and action["flags"] & indexed_mask:
                    fact = _resource_fact(index_resource)
                    fact["stage"] = "vertex"
                    fact["access"] = "index-buffer"
                    fact.update({
                        "byteOffset": _safe_int(
                            index_binding.get("byteOffset", 0), 0),
                        "byteSize": _safe_int(
                            index_binding.get("byteSize", 0), 0),
                        "byteStride": index_binding.get("byteStride"),
                    })
                    reads.append(fact)

                blend_states = []
                try:
                    blend_states = list(ps.GetColorBlends() or [])
                except Exception:
                    pass
                targets = []
                color_write_targets = []
                color_target_states = []
                possible_outputs = []
                target_indices = []
                for target_index, descriptor in enumerate(
                        ps.GetOutputTargets() or []):
                    resource_id = _resource_id_int(getattr(descriptor, "resource", None))
                    if resource_id:
                        if len(targets) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                            output_omitted += 1
                            continue
                        fact = _resource_fact(resource_id)
                        fact["access"] = "color-target"
                        fact["slot"] = target_index
                        _frame_flow_descriptor_fields(fact, descriptor)
                        targets.append(fact)
                        target_indices.append(target_index)
                        if target_index < len(blend_states):
                            blend = blend_states[target_index]
                            blend_state = _pass_color_blend_state(
                                blend, target_index)
                            color_target_states.append(blend_state)
                            write_mask = blend_state["writeMask"]
                            if write_mask is not None:
                                if write_mask > 0:
                                    color_write_targets.append(fact)
                                    writes.append(fact)
                            else:
                                possible = dict(fact)
                                possible["access"] = "color-target-possible"
                                possible["certainty"] = "unknown-write-mask"
                                possible_outputs.append(possible)
                        else:
                            possible = dict(fact)
                            possible["access"] = "color-target-possible"
                            possible["certainty"] = "unknown-write-mask"
                            possible_outputs.append(possible)
                depth_fact = None
                depth = ps.GetDepthTarget()
                if depth:
                    depth_id = _resource_id_int(getattr(depth, "resource", None))
                    if depth_id:
                        depth_fact = _resource_fact(depth_id)
                        depth_fact["access"] = "depth-target-bound"
                        _frame_flow_descriptor_fields(depth_fact, depth)

                def _unique(values):
                    result = []
                    seen = set()
                    omitted = 0
                    for value in values:
                        resource_id = value.get("resourceId", 0)
                        key = (
                            resource_id,
                            value.get("access", ""),
                            value.get("stage", ""),
                            *(
                                _safe_int(value.get(field, -1), -1)
                                for field in (
                                    "byteOffset", "byteSize", "firstMip",
                                    "numMips", "firstSlice", "numSlices")
                            ),
                            json.dumps(
                                value.get("subresource", {}),
                                ensure_ascii=True,
                                sort_keys=True,
                                separators=(",", ":"),
                            ),
                        )
                        if resource_id and key not in seen:
                            seen.add(key)
                            if (len(result) >=
                                    MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION):
                                omitted += 1
                            else:
                                result.append(value)
                    return result, omitted

                state = {
                    "shaders": stages,
                    "renderTargets": targets,
                    "colorWriteTargets": color_write_targets,
                    "colorTargetStates": color_target_states,
                    "depthTarget": depth_fact,
                    "readResources": [],
                    "writeResources": [],
                    "lateFrameFraction": float(action_index) / action_total,
                    "vertexBufferBindingsResolved": (
                        vertex_buffer_bindings_resolved),
                    "vertexInputUsageResolved": vertex_input_usage_resolved,
                    "vertexLayout": vertex_layout,
                    "vertexLayoutOmittedCount": vertex_layout_omitted,
                    "indexBufferBindingResolved": (
                        index_buffer_binding_resolved),
                    "indexStride": index_binding.get("byteStride"),
                }
                state["blendEnabled"] = _pass_blend_enabled(blend_states)
                state.update(_pass_attachment_sample_state(
                    targets, depth_fact))
                state.update(_pass_draw_state(ps))
                state.update(_pass_depth_state(ctrl))
                if state.get("stencilWriteOperationsCanWrite") is not None:
                    state["stencilWritePossible"] = bool(
                        state.get("stencilTestEnabled") is True and
                        state.get("stencilReadOnly") is not True and
                        state.get("stencilWriteOperationsCanWrite") is True)
                state["colorWriteMasksResolved"] = bool(
                    len(color_target_states) == len(targets))
                raster_applicable, raster_reason = (
                    _raster_output_applicability(
                        action["flags"], True, stages, state,
                        fragment_stage_resolved))
                no_fragment_shader = bool(
                    fragment_stage_resolved and "fragment" not in stages)
                state["rasterOutputApplicable"] = raster_applicable
                if raster_reason:
                    state["rasterOutputSuppressionReason"] = raster_reason
                if raster_applicable is False:
                    # ActionDescription.outputs/depthOut are documented as
                    # coarse color/depth attachments, not UAV/SO outputs.
                    action.pop("outputs", None)
                    action.pop("depthOutput", None)
                    reads = _without_raster_io(reads)
                    writes = _without_raster_io(writes)
                    possible_outputs = _without_raster_io(possible_outputs)
                    state["renderTargets"] = []
                    state["colorWriteTargets"] = []
                    state["depthTarget"] = None
                    targets = []
                    target_indices = []
                    depth_fact = None
                else:
                    if no_fragment_shader:
                        # Fragment-less draws can still update depth/stencil.
                        # ActionDescription.outputs is the coarse color list;
                        # depthOut remains valid evidence for the depth path.
                        action.pop("outputs", None)
                        reads = _without_color_raster_io(reads)
                        writes = _without_color_raster_io(writes)
                        possible_outputs = _without_color_raster_io(
                            possible_outputs)
                        state["renderTargets"] = []
                        state["colorWriteTargets"] = []
                        targets = []
                        target_indices = []
                    if raster_applicable is None:
                        # An unresolved discard state cannot support a definite
                        # raster write.  Preserve the bindings as candidates.
                        action.pop("outputs", None)
                        action.pop("depthOutput", None)
                        writes, downgraded = _downgrade_raster_writes(
                            writes, "unknown-rasterizer-discard")
                        possible_outputs.extend(downgraded)
                        state["colorWriteTargets"] = []
                blend_read_targets = []
                for target, target_index in zip(targets, target_indices):
                    if target_index >= len(blend_states):
                        continue
                    blend_state = _pass_color_blend_state(
                        blend_states[target_index], target_index)
                    if (blend_state["writeMask"] is None or
                            blend_state["writeMask"] <= 0 or
                            not (
                                blend_state["blendEnabled"] is True or
                                blend_state["logicOperationEnabled"] is True)):
                        continue
                    blend_read_targets.append(target)
                if blend_read_targets:
                    state["blendReadTargets"] = blend_read_targets
                    for target in blend_read_targets:
                        fact = dict(target)
                        fact["access"] = "blend-destination"
                        reads.append(fact)
                if (depth_fact is not None and
                        state.get("depthTestEnabled") is True):
                    fact = dict(depth_fact)
                    fact["access"] = "depth-test"
                    reads.append(fact)
                if (depth_fact is not None and
                        state.get("stencilTestEnabled") is True):
                    fact = dict(depth_fact)
                    fact["access"] = "stencil-test"
                    reads.append(fact)
                if depth_fact is not None:
                    fact = dict(depth_fact)
                    if (raster_applicable is True and
                            state.get("depthTestEnabled") is True and
                            state.get("depthWriteEnabled") is True):
                        fact["access"] = "depth-target"
                        writes.append(fact)
                    elif (state.get("depthTestEnabled") is not False and
                            state.get("depthWriteEnabled") is not False):
                        fact["access"] = "depth-target-possible"
                        fact["certainty"] = (
                            "unknown-rasterizer-discard"
                            if raster_applicable is None else "unknown")
                        possible_outputs.append(fact)
                    if (state.get("stencilTestEnabled") is True and
                            state.get("stencilWritePossible") is True):
                        stencil_fact = dict(depth_fact)
                        stencil_fact["access"] = "stencil-target-possible"
                        stencil_fact["certainty"] = (
                            "unknown-rasterizer-discard"
                            if raster_applicable is None else "state-possible")
                        possible_outputs.append(stencil_fact)
                bounded_reads, locally_omitted = _unique(reads)
                input_omitted += locally_omitted
                bounded_writes, locally_omitted = _unique(writes)
                output_omitted += locally_omitted
                state["readResources"] = bounded_reads
                state["writeResources"] = bounded_writes
                if possible_outputs:
                    state["possibleOutputs"] = possible_outputs
                if sampler_summary:
                    state["samplers"] = sampler_summary
                state["inputOmittedCount"] = input_omitted
                state["outputOmittedCount"] = output_omitted
                encoded_size = _frame_flow_json_bytes(state) + len(
                    str(event_id)) + 4
                if (action_serialized_bytes[0] + pipeline_serialized_bytes +
                        encoded_size >
                        MAX_FRAME_FLOW_SERIALIZED_BYTES - 64 * 1024):
                    truncated[0] = True
                    omitted_lower_bound[0] += len(actions) - action_index
                    retained_action_count = action_index
                    if "serialized-size-budget" not in truncation_reasons:
                        truncation_reasons.append("serialized-size-budget")
                    break
                pipeline_states[str(event_id)] = state
                pipeline_serialized_bytes += encoded_size
        finally:
            if restore_original_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass

        if retained_action_count < len(actions):
            actions[:] = actions[:retained_action_count]

        def _payload():
            input_omitted_total = sum(
                _safe_int(value.get("inputOmittedCount", 0), 0)
                for value in pipeline_states.values())
            output_omitted_total = sum(
                _safe_int(value.get("outputOmittedCount", 0), 0)
                for value in pipeline_states.values())
            return {
                "schema": result_schema,
                "schemaVersion": 1,
                "captureId": expected_capture_id,
                "captureSessionId": expected_session,
                "actions": actions,
                "pipelineStates": pipeline_states,
                "summary": {
                    "actionCount": len(actions),
                    "pipelineStateCount": len(pipeline_states),
                    "singleReplayThreadTransaction": True,
                    "truncated": truncated[0],
                    "requestedMaxActions": maximum,
                    "omittedActionCountLowerBound": omitted_lower_bound[0],
                    "truncationReasons": list(truncation_reasons),
                    "serializedBudgetBytes": MAX_FRAME_FLOW_SERIALIZED_BYTES,
                    "inputResourceOmittedCount": input_omitted_total,
                    "outputResourceOmittedCount": output_omitted_total,
                    "resourceFactsTruncated": bool(
                        input_omitted_total or output_omitted_total or
                        resource_metadata_receipt.get("truncated")),
                    "resourceMetadata": dict(resource_metadata_receipt),
                },
            }

        def _payload_with_receipt():
            payload_value = _payload()
            for unused in range(16):
                serialized_value = _frame_flow_response_json_bytes(
                    payload_value)
                if (payload_value["summary"].get("serializedBytes") ==
                        serialized_value):
                    return payload_value, serialized_value
                payload_value["summary"]["serializedBytes"] = serialized_value
            raise RuntimeError("Frame-flow serialized-byte receipt did not converge")

        payload, serialized_bytes = _payload_with_receipt()
        while serialized_bytes > MAX_FRAME_FLOW_SERIALIZED_BYTES and actions:
            old_count = len(actions)
            keep = max(0, min(
                old_count - 1,
                int(old_count * float(MAX_FRAME_FLOW_SERIALIZED_BYTES - 65536) /
                    float(serialized_bytes))))
            removed = old_count - keep
            actions[:] = actions[:keep]
            kept_events = set(
                str(value.get("eventId", 0)) for value in actions)
            pipeline_states = dict(
                (key, value) for key, value in pipeline_states.items()
                if key in kept_events)
            omitted_lower_bound[0] += removed
            truncated[0] = True
            if "serialized-size-budget" not in truncation_reasons:
                truncation_reasons.append("serialized-size-budget")
            payload, serialized_bytes = _payload_with_receipt()
        if serialized_bytes > MAX_FRAME_FLOW_SERIALIZED_BYTES:
            raise RuntimeError("Frame-flow IPC response exceeds the 8 MiB hard limit")

        if expected_session != _capture_session_id:
            raise RuntimeError("Capture session changed during pass classification")
        return payload

    return _replay(_do)


def _get_pass_classification_inputs(params):
    """Collect fixed-pass inputs bound to the exported capture identity."""
    return _collect_current_frame_inputs(
        params, True, "replaylab-pass-classification-inputs/v1")


def _get_current_frame_flow_inputs(params):
    """Collect read-only frame-flow inputs without project or UI effects."""
    return _collect_current_frame_inputs(
        params, False, "replaylab-current-frame-flow-inputs/v1")


def _collect_frame_render_flow_outline(ctrl, capture, session, checkpoint=lambda: None):
    from .frame_render_flow_outline import collect_actions
    from .frame_stage_evidence import resolved_indirect_workload
    masks = {
        "marker": _marker_action_mask(),
        "draw": _action_flags_mask(("Drawcall", "MeshDispatch"), 0x0002 | 0x0008),
        "mesh": _action_flags_mask(("MeshDispatch",), 0x0008),
        "indirect": _action_flags_mask(("Indirect",), 0x080000),
        "dispatch": _action_flags_mask(("Dispatch", "DispatchRay"), 0x0004 | 0x4000),
        "copy": _action_flags_mask(("Copy",)), "resolve": _action_flags_mask(("Resolve",)),
        "clear": _action_flags_mask(("Clear",)), "present": _action_flags_mask(("Present",)),
    }
    # Structured capture data is immutable while this session is pinned. This
    # reads the native decoded argument chunks, without replaying each action.
    structured = _ctx.GetStructuredFile() if _ctx is not None and hasattr(_ctx, "GetStructuredFile") else None
    rows, count = collect_actions(ctrl.GetRootActions(), _action_name, _resource_id_int,
                                  masks, checkpoint=checkpoint,
                                  indirect_workload=(lambda action: resolved_indirect_workload(action, structured))
                                  if structured is not None else None)
    return {"schema": "bread-frame-render-flow-outline/v1", "captureSessionId": session,
            "captureId": str(capture.get("captureId", "") or ""),
            "capturePath": str(capture.get("path", "") or ""),
            "api": str(capture.get("api", "") or ""),
            "frameNumber": _safe_int(getattr(ctrl.GetFrameInfo(), "frameNumber", 0), 0),
            "actions": rows, "summary": {"complete": len(rows) == count,
                "totalActionCount": count, "storedActionCount": len(rows),
                "omittedActionCount": count - len(rows)}}


def _get_frame_render_flow_outline(params):
    """Page a capture-scoped action tree, with no per-action replay or pipeline reads."""
    global _frame_render_flow_outline_cache
    from .frame_render_flow_outline import outline_page
    expected = str(params.get("expected_capture_session_id", "") or "")
    if (len(expected) != 32 or expected != _request_capture_session_id() or
            expected != _capture_session_id or not _request_capture_loaded()):
        raise RuntimeError("Frame flow capture session changed or no capture is loaded")
    refresh = params.get("refresh", False)
    if not isinstance(refresh, bool):
        raise ValueError("Frame flow refresh must be a boolean")
    offset, limit = params.get("offset", 0), params.get("limit", 4000)
    if (isinstance(offset, bool) or not isinstance(offset, int) or offset < 0 or
            isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 5000):
        raise ValueError("Frame flow offset/limit must be non-negative integers; limit is 1..5000")
    cached = _frame_render_flow_outline_cache
    hit = bool(not refresh and cached and cached.get("captureSessionId") == expected)
    if not hit:
        capture = _capture_identity_context()["capture"]

        def collect(ctrl):
            return _collect_frame_render_flow_outline(ctrl, capture, expected,
                                                       _background_replay_checkpoint)

        cached = _replay(collect)
        if expected != _capture_session_id:
            raise RuntimeError("Capture changed while reading the frame flow outline")
        _frame_render_flow_outline_cache = cached
    page = outline_page(cached, offset, limit, cache_hit=hit)
    if offset == 0 and _frame_render_flow_saved:
        saved = _frame_render_flow_saved.get("document", {})
        if saved.get("captureSessionId") == expected:
            page["restoredDocument"] = saved
    return page


def _show_frame_render_flow(params):
    document = params.get("document")
    if (not isinstance(document, dict) or
            document.get("schema") != "bread-frame-render-flow/v1"):
        raise ValueError("Invalid frame render flow document")
    expected = str(document.get("captureSessionId", "") or "")
    if (not expected or expected != _request_capture_session_id() or
            expected != _capture_session_id or not _request_capture_loaded()):
        raise RuntimeError("Frame flow belongs to a different capture session")

    def publish():
        global _frame_render_flow_generation
        if expected != _capture_session_id or not _ctx.IsCaptureLoaded():
            raise RuntimeError("Capture changed before opening the frame flow")
        _frame_render_flow_generation += 1
        panel = _ensure_frame_render_flow_ui()
        panel.set_document(document)
        panel.show()
        shown = bool(panel.top.isVisible())
        return {"schema": "bread-frame-render-flow-window/v1", "published": shown,
                "shown": shown, "flowId": document.get("flowId"),
                "captureSessionId": expected, "state": panel.get_state()}

    return _invoke_on_ui_sync(publish)


def _frame_flow_artifact_root():
    from pathlib import Path
    configured = os.environ.get("RENDERDOC_ULTRA_EVENT_ARTIFACTS_HOME", "")
    if configured:
        if not os.path.isabs(configured):
            raise ValueError("Configured Event artifact root must be absolute")
        return Path(configured)
    local = os.environ.get("LOCALAPPDATA", "")
    if local:
        return Path(local) / "ReplayLab" / "event-artifacts"
    return Path(os.environ.get("XDG_DATA_HOME", str(Path.home() / ".local" / "share"))) / "ReplayLab" / "event-artifacts"


def _save_frame_render_flow(params):
    """Persist verified Host data without modifying the RDC or replay state."""
    global _frame_render_flow_saved
    from .frame_flow_persistence import canonical_outline, digest, save
    document, outline = params.get("document"), params.get("outline")
    session = _request_capture_session_id()
    capture = _capture_identity_context()["capture"]
    if (not isinstance(document, dict) or not isinstance(outline, dict) or
            not session or session != _capture_session_id or not _request_capture_loaded() or
            document.get("captureSessionId") != session or outline.get("captureSessionId") != session):
        raise ValueError("Frame flow persistence requires the active capture session")
    clean = canonical_outline(outline)
    if document.get("snapshotId") != digest(clean):
        raise ValueError("Frame diagram does not match its action outline")
    result = save(capture["path"], document, clean, _frame_flow_artifact_root())
    if session != _capture_session_id:
        raise RuntimeError("Capture changed while saving the frame flow")
    _frame_render_flow_saved = {"document": document, "outline": clean, "persistence": result}
    return result


def _capture_frame_flow_channels(params):
    """Pre-generate a bounded batch; the Host validates and persists receipts."""
    from .frame_flow_channels import capture_channel_batch, mutation_identity
    session = params.get("expected_capture_session_id")
    if (not isinstance(session, str) or not re.match(r"^[0-9a-f]{32}$", session) or
            session != _request_capture_session_id() or session != _capture_session_id or
            not _request_capture_loaded()):
        raise RuntimeError("Frame channel generation requires the active capture session")
    items = params.get("items")
    if not isinstance(items, list) or not 1 <= len(items) <= 8:
        raise ValueError("Frame channel generation requires one to eight parent previews")
    replay = _foreground_replay_manager()
    original_event = _request_visible_event_id(0)
    snapshot = {"session": session, "originalEvent": original_event, "replay": replay,
                "flowGeneration": _frame_render_flow_generation,
                "foregroundGeneration": _replay_foreground_generation(replay),
                "mutationEpoch": mutation_identity(sys.modules[__name__])}
    tracker = _request_event_tracker() or {}
    cancel_event = tracker.get("cancelEvent")
    cancelled = cancel_event.is_set if cancel_event is not None else lambda: False
    result, keys = [], set()
    for item in items:
        _background_replay_checkpoint()
        if not isinstance(item, dict) or not isinstance(item.get("preview"), dict):
            raise ValueError("Frame channel parent preview is invalid")
        key = item.get("key")
        if not isinstance(key, str) or not key or len(key) > 160 or key in keys:
            raise ValueError("Frame channel parent key must be unique and bounded")
        keys.add(key)
        requests = item.get("requests")
        if not isinstance(requests, list) or len(requests) > 6:
            raise ValueError("Frame channel request directories are invalid")
        by_channel = {}
        for request in requests:
            if not isinstance(request, dict) or request.get("channel") not in ("rgb", "r", "g", "b", "a", "depth"):
                raise ValueError("Frame channel request uses an unsupported channel")
            if request["channel"] in by_channel:
                raise ValueError("Frame channel request contains a duplicate channel")
            by_channel[request["channel"]] = request
        value = capture_channel_batch(sys.modules[__name__], item["preview"], snapshot,
                                      {}, cancelled, requests=by_channel)
        # Files are generated under Host-allocated directories. Only the Host
        # writes authoritative manifests and adds admitted images to the flow.
        result.append({"key": key, "componentCount": value["componentCount"],
                       "channelGroups": value["channelGroups"], "receipts": value["receipts"],
                       "errors": value["errors"], "complete": value["complete"]})
    return {"schema": "bread-frame-flow-channel-capture/v1", "captureSessionId": session,
            "originalEventId": original_event, "replayRevision": snapshot["mutationEpoch"], "items": result}


def _capture_frame_flow_volume(params):
    """Prepare a bounded volume slice set without per-slice event replay."""
    from .frame_flow_channels import mutation_identity
    from .frame_flow_volume import capture_volume
    session = params.get("expected_capture_session_id")
    if (not isinstance(session, str) or not re.match(r"^[0-9a-f]{32}$", session) or
            session != _request_capture_session_id() or session != _capture_session_id or
            not _request_capture_loaded()):
        raise RuntimeError("Frame volume generation requires the active capture session")
    preview = params.get("preview")
    if not isinstance(preview, dict):
        raise ValueError("Frame volume parent preview is invalid")
    replay = _foreground_replay_manager()
    snapshot = {"session": session, "originalEvent": _request_visible_event_id(0), "replay": replay,
                "flowGeneration": _frame_render_flow_generation,
                "foregroundGeneration": _replay_foreground_generation(replay),
                "mutationEpoch": mutation_identity(sys.modules[__name__])}
    tracker = _request_event_tracker() or {}
    cancel_event = tracker.get("cancelEvent")
    cancelled = cancel_event.is_set if cancel_event is not None else lambda: False
    return capture_volume(sys.modules[__name__], preview, params.get("requests"), snapshot, cancelled)


def _get_saved_frame_render_flow(params):
    """Reuse checked restoration data, or load and bind it to the current outline."""
    global _frame_render_flow_saved
    from .frame_flow_persistence import load, rebind
    session = str(params.get("expected_capture_session_id", "") or "")
    if not session or session != _capture_session_id or session != _request_capture_session_id():
        raise RuntimeError("Frame flow restoration requires the active capture session")
    if _frame_render_flow_saved and _frame_render_flow_saved["document"].get("captureSessionId") == session:
        return _frame_render_flow_saved
    capture = _capture_identity_context()["capture"]
    bundle = load(capture["path"], _frame_flow_artifact_root())
    if bundle is None:
        return {"restored": False}
    _get_frame_render_flow_outline({"expected_capture_session_id": session, "limit": 1})
    result = rebind(bundle, _frame_render_flow_outline_cache)
    if session != _capture_session_id:
        raise RuntimeError("Capture changed while restoring the frame flow")
    _frame_render_flow_saved = result
    return result


def _restore_frame_render_flow_revision(params):
    global _frame_render_flow_saved
    from .frame_flow_persistence import restore_revision,rebind
    _require_capture_session_id(params.get('expected_capture_session_id'))
    capture=_capture_identity_context()['capture']
    bundle=restore_revision(capture['path'],_frame_flow_artifact_root(),params.get('revision_sha256'))
    _get_frame_render_flow_outline({'expected_capture_session_id':_capture_session_id,'limit':1})
    result=rebind(bundle,_frame_render_flow_outline_cache)
    _frame_render_flow_saved=result
    return result


def _parse_catalog_event_ids(value):
    if value is None:
        return None
    if isinstance(value, str):
        value = [item.strip() for item in value.split(",") if item.strip()]
    try:
        values = list(value)
    except Exception:
        values = [value]

    result = []
    seen = set()
    for item in values:
        event_id = _safe_int(item, -1)
        if event_id < 0:
            raise ValueError("Invalid event id: %s" % str(item))
        if event_id not in seen:
            seen.add(event_id)
            result.append(event_id)
    return result


def _require_capture_identity(expected_capture_id):
    """Bind a mutating shader operation to the active exported capture."""
    expected = str(expected_capture_id or "").strip().lower()
    if (len(expected) != 64 or
            any(character not in "0123456789abcdef" for character in expected)):
        raise ValueError("expected_capture_id must be a lowercase SHA-256")
    if not _request_capture_loaded():
        raise RuntimeError("No capture loaded")
    known_path = _known_catalog_capture_ids.get(expected)
    if not known_path:
        raise RuntimeError(
            "The active capture has no bridge catalog identity; export the exact "
            "event/stage catalog again before using a capture-bound operation")

    token = _current_capture_token()
    if token is None:
        raise RuntimeError("No capture loaded")
    if token[1] != known_path:
        raise RuntimeError("The active capture path changed since catalog export")
    return expected


def _read_shader_candidate(params):
    """Read one exact bounded candidate and verify its caller-bound digest."""
    candidate_path = str(params.get("candidate_path", "") or "").strip()
    if not candidate_path:
        raise ValueError("candidate_path is required")
    candidate_path = os.path.abspath(os.path.expanduser(candidate_path))
    if not os.path.isfile(candidate_path):
        raise ValueError("Candidate shader file not found: %s" % candidate_path)

    expected_sha256 = str(params.get("expected_sha256", "") or "").strip().lower()
    if (len(expected_sha256) != 64 or
            any(c not in "0123456789abcdef" for c in expected_sha256)):
        raise ValueError("expected_sha256 must be a 64-character lowercase SHA-256")

    is_glsl = str(params.get("encoding", "") or "").strip().lower() == "glsl"
    maximum_size = (4 if is_glsl else 512) * 1024 * 1024
    if os.path.getsize(candidate_path) > maximum_size:
        raise ValueError("Candidate shader exceeds its bounded artifact size limit")
    with open(candidate_path, "rb") as stream:
        candidate_bytes = stream.read(maximum_size + 1)
    if len(candidate_bytes) > maximum_size:
        raise ValueError("Candidate shader exceeds its bounded artifact size limit")
    if not candidate_bytes:
        raise ValueError("Candidate shader is empty")
    actual_sha256 = hashlib.sha256(candidate_bytes).hexdigest()
    if actual_sha256 != expected_sha256:
        raise ValueError("Candidate shader bytes do not match expected_sha256")
    if is_glsl:
        try:
            source = candidate_bytes.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("GLSL candidate must be exact UTF-8 source")
        if "\x00" in source or not source.strip():
            raise ValueError("GLSL candidate must be nonempty source without NUL bytes")
    return candidate_path, candidate_bytes, actual_sha256


def _compile_shader_source_native(params):
    from .native_shader_compile import compile_source
    return compile_source(sys.modules[__name__], params)


def _reflect_shader_candidate(params):
    """Build and reflect one exact candidate blob without replacing any capture resource."""
    if not _request_capture_loaded():
        raise RuntimeError("No capture loaded")

    candidate_path, candidate_bytes, actual_sha256 = _read_shader_candidate(params)
    expected_capture_id = str(params.get("expected_capture_id", "") or "").strip()
    if expected_capture_id:
        expected_capture_id = _require_capture_identity(expected_capture_id)

    encoding_name = str(params.get("encoding", "dxbc") or "dxbc").strip().lower()
    encoding_attribute = {
        "dxbc": "DXBC",
        "dxil": "DXIL",
        "spirv": "SPIRV",
        "opengl-spirv": "OpenGLSPIRV",
        "glsl": "GLSL",
    }.get(encoding_name)
    if encoding_attribute is None:
        raise ValueError(
            "Candidate reflection accepts DXBC, DXIL, Vulkan SPIR-V, OpenGL SPIR-V or GLSL")
    encoding = getattr(rd.ShaderEncoding, encoding_attribute, None)
    if encoding is None:
        raise RuntimeError(
            "This RenderDoc build does not expose ShaderEncoding.%s" %
            encoding_attribute)

    requested_stage = _normalise_stage_name(params.get("stage", ""))
    stage_map = dict(_available_shader_stages([requested_stage]))
    stage = stage_map.get(requested_stage)
    if stage is None:
        raise ValueError("Unsupported shader stage: %s" % requested_stage)
    entry_point = str(params.get("entry_point", "") or "").strip()
    if not entry_point:
        raise ValueError("entry_point is required")
    if encoding_name == "glsl" and (entry_point != "main" or requested_stage in ("task", "mesh")):
        raise ValueError("OpenGL GLSL requires main and a legacy pipeline stage")

    def _do(ctrl):
        result = {
            "schema": "renderdoc-ultra-shader-reflection/v1",
            "schemaVersion": 1,
            "rawSha256": actual_sha256,
            "byteSize": len(candidate_bytes),
            "stage": requested_stage,
            "entryPoint": entry_point,
            "encoding": encoding_name,
            "buildTargetShaderSucceeded": False,
            "reflectionSucceeded": False,
            "freeTargetResourceSucceeded": False,
            "buildMessages": "",
            "compiledInterface": None,
        }
        if expected_capture_id:
            result["captureId"] = expected_capture_id
            result["captureSessionId"] = _capture_session_id
        target_id = None
        try:
            get_api = getattr(ctrl, "GetAPIProperties", None)
            api_name = str(
                getattr(get_api(), "pipelineType", "") if callable(get_api) else "")
            api_token = api_name.lower().replace("graphicsapi.", "")
            if api_token == "direct3d11":
                api_token = "d3d11"
            elif api_token == "direct3d12":
                api_token = "d3d12"
            api_token = {
                "direct3d11": "d3d11",
                "direct3d12": "d3d12",
                "vk": "vulkan",
                "gl": "opengl",
            }.get(api_token, api_token)
            valid_pair = (
                (api_token == "d3d11" and encoding_name == "dxbc") or
                (api_token == "d3d12" and encoding_name in ("dxbc", "dxil")) or
                (api_token == "vulkan" and encoding_name == "spirv") or
                (api_token == "opengl" and encoding_name in ("opengl-spirv", "glsl")))
            if not valid_pair:
                result["buildMessages"] = (
                    "Candidate encoding does not match the active replay API")
                return result
            supported = list(ctrl.GetTargetShaderEncodings())
            if encoding not in supported:
                result["buildMessages"] = "%s target shaders are unsupported by this replay" % (
                    encoding_name.upper())
                return result

            compile_flags = rd.ShaderCompileFlags()
            target_id, messages = _build_target_shader(
                ctrl,
                entry_point, encoding, candidate_bytes, compile_flags, stage)
            result["buildMessages"] = str(messages or "")
            if not _resource_id_int(target_id):
                return result
            result["buildTargetShaderSucceeded"] = True

            entries = list(ctrl.GetShaderEntryPoints(target_id) or [])
            selected_entry = _exact_shader_entry(
                entries, entry_point, requested_stage)
            if selected_entry is None:
                result["buildMessages"] = (
                    result["buildMessages"]
                    + "\nCandidate entry point/stage was not reflected exactly once"
                ).strip()
                return result

            reflection = ctrl.GetShader(rd.ResourceId(), target_id, selected_entry)
            if not reflection:
                result["buildMessages"] = (
                    result["buildMessages"] + "\nCandidate ShaderReflection is unavailable"
                ).strip()
                return result

            reflected_raw = _shader_raw_bytes(reflection)
            if encoding_name == "glsl" and (
                    _shader_encoding_token(getattr(reflection, "encoding", "")) != "glsl"
                    or reflected_raw != candidate_bytes):
                result["buildMessages"] = (
                    result["buildMessages"] + "\nGLSL reflection does not preserve exact source identity").strip()
                return result
            result["reflectedRawSha256"] = (
                hashlib.sha256(reflected_raw).hexdigest() if reflected_raw else "")
            result["reflectedEntryPoint"] = str(
                getattr(reflection, "entryPoint", "") or
                getattr(selected_entry, "name", "") or "")
            dxil_layout_evidence = {}
            if encoding_name == "dxil":
                # Do not invoke the expensive replay-side textual DXIL printer
                # during reflection. The Host separately validates the exact
                # immutable fixed-DXC access artifact for this candidate, and
                # shared apply still repeats a live access comparison adjacent
                # to mutation. Only structural ambiguity visible in reflection
                # itself needs an explicit lower-only marker here.
                dxil_layout_evidence = (
                    _dxil_layout_evidence_for_reflection_ambiguity(reflection))
            result["compiledInterface"] = _compiled_shader_interface(
                reflection, dxil_layout_evidence)
            result["reflectionSucceeded"] = True
            return result
        finally:
            if target_id is not None and _resource_id_int(target_id):
                try:
                    ctrl.FreeTargetResource(target_id)
                    result["freeTargetResourceSucceeded"] = True
                except Exception as exc:
                    result["freeTargetResourceError"] = str(exc)
                    _register_orphan_shader_target(target_id)

    return _replay(_do)


def _d3d11_stage_state(ctrl, stage_name):
    state = ctrl.GetD3D11PipelineState()
    attribute = {
        "vertex": "vertexShader",
        "hull": "hullShader",
        "domain": "domainShader",
        "geometry": "geometryShader",
        "fragment": "pixelShader",
        "compute": "computeShader",
    }.get(stage_name)
    if state is None or attribute is None:
        return None
    return getattr(state, attribute, None)


def _shader_api_token(ctrl):
    api_name = _native_enum_text(getattr(ctrl.GetAPIProperties(), "pipelineType", None))
    token = api_name.lower().replace("graphicsapi.", "")
    if token == "direct3d11":
        token = "d3d11"
    elif token == "direct3d12":
        token = "d3d12"
    elif token == "vk":
        token = "vulkan"
    elif token == "gl":
        token = "opengl"
    return token


def _replace_shared_shader_resource(ctrl, api_token, original, target):
    """Use a checked derived-pipeline transaction whenever the API needs one."""
    if api_token in ("d3d12", "vulkan", "opengl"):
        api_label = {
            "d3d12": "D3D12", "vulkan": "Vulkan", "opengl": "OpenGL"
        }[api_token]
        checked = getattr(ctrl, "ReplaceTargetShaderChecked", None)
        if not callable(checked):
            raise RuntimeError(
                "This RenderDoc build lacks checked %s Shader replacement" %
                api_label)
        _begin_replay_atomic_transaction()
        error = str(checked(original, target) or "")
        if error:
            raise RuntimeError(
                "Checked %s Shader replacement failed: %s" %
                (api_label, error))
        return
    if api_token != "d3d11":
        raise RuntimeError(
            "Shared Shader replacement supports D3D11/D3D12/Vulkan/OpenGL only")
    _begin_replay_atomic_transaction()
    ctrl.ReplaceResource(original, target)


def _remove_shared_shader_resource(ctrl, api_token, original):
    if api_token in ("d3d12", "vulkan", "opengl"):
        api_label = {
            "d3d12": "D3D12", "vulkan": "Vulkan", "opengl": "OpenGL"
        }[api_token]
        checked = getattr(ctrl, "RemoveTargetShaderReplacementChecked", None)
        if not callable(checked):
            raise RuntimeError(
                "This RenderDoc build lacks checked %s Shader rollback" %
                api_label)
        _begin_replay_atomic_transaction()
        error = str(checked(original) or "")
        if error:
            raise RuntimeError(
                "Checked %s Shader rollback failed: %s" %
                (api_label, error))
        return
    if api_token != "d3d11":
        raise RuntimeError(
            "Shared Shader rollback supports D3D11/D3D12/Vulkan/OpenGL only")
    _begin_replay_atomic_transaction()
    ctrl.RemoveReplacement(original)


def _shader_override_hex(value, field_name, length):
    text = str(value or "").strip().lower()
    if len(text) != length or any(c not in "0123456789abcdef" for c in text):
        raise ValueError("%s must be %d lowercase hexadecimal characters" %
                         (field_name, length))
    return text


def _shader_rollback_capture_session(params):
    """Bind a rollback (including a tombstone retry) to this capture session."""
    current = str(_capture_session_id or "").strip().lower()
    if (len(current) != 32 or
            any(character not in "0123456789abcdef" for character in current)):
        raise RuntimeError("No valid capture session is active for Shader rollback")
    supplied = params.get("expected_capture_session_id")
    if supplied is not None:
        expected = _shader_override_hex(
            supplied, "expected_capture_session_id", 32)
        if expected != current:
            raise RuntimeError("Capture session changed before Shader rollback")
    return current


def _event_shader_rollback_receipt(receipt, already_restored):
    result = dict(receipt)
    result["alreadyRestored"] = bool(already_restored)
    result["idempotentRollback"] = bool(already_restored)
    return result


def _remember_event_shader_rollback_receipt(receipt, capture_token):
    global _event_shader_rollback_tombstones
    global _event_shader_rollback_tombstone_order

    override_id = str(receipt.get("overrideId", "") or "")
    if override_id in _event_shader_rollback_tombstones:
        _event_shader_rollback_tombstone_order = [
            value for value in _event_shader_rollback_tombstone_order
            if value != override_id
        ]
    _event_shader_rollback_tombstones[override_id] = {
        "captureId": receipt.get("captureId"),
        "captureSessionId": receipt.get("captureSessionId"),
        "captureToken": capture_token,
        "receipt": dict(receipt),
    }
    _event_shader_rollback_tombstone_order.append(override_id)
    limit = max(0, int(MAX_EVENT_SHADER_ROLLBACK_TOMBSTONES))
    while len(_event_shader_rollback_tombstone_order) > limit:
        expired = _event_shader_rollback_tombstone_order.pop(0)
        _event_shader_rollback_tombstones.pop(expired, None)


def _shared_shader_rollback_receipt(receipt, already_restored):
    result = dict(receipt)
    result["alreadyRestored"] = bool(already_restored)
    result["idempotentRollback"] = bool(already_restored)
    return result


def _remember_shared_shader_rollback_receipt(receipt, capture_token):
    global _shared_shader_rollback_tombstones
    global _shared_shader_rollback_tombstone_order

    replacement_id = str(receipt.get("replacementId", "") or "")
    if replacement_id in _shared_shader_rollback_tombstones:
        _shared_shader_rollback_tombstone_order = [
            value for value in _shared_shader_rollback_tombstone_order
            if value != replacement_id
        ]
    _shared_shader_rollback_tombstones[replacement_id] = {
        "captureId": receipt.get("captureId"),
        "captureSessionId": receipt.get("captureSessionId"),
        "captureToken": capture_token,
        "workspaceId": receipt.get("workspaceId"),
        "receipt": dict(receipt),
    }
    _shared_shader_rollback_tombstone_order.append(replacement_id)
    limit = max(0, int(MAX_SHARED_SHADER_ROLLBACK_TOMBSTONES))
    while len(_shared_shader_rollback_tombstone_order) > limit:
        expired = _shared_shader_rollback_tombstone_order.pop(0)
        _shared_shader_rollback_tombstones.pop(expired, None)


def _event_shader_override_for_slot(event_id, stage_name):
    for override_id, record in list(_event_shader_overrides.items()):
        if (record.get("eventId") == event_id and
                record.get("stageName") == stage_name):
            return override_id, record
    return None, None


def _shader_family_id(capture_session_id, stage_name, entry_point,
                      original_resource_id, original_sha256,
                      candidate_sha256, abi_sha256):
    return _canonical_json_sha256({
        "captureSessionId": capture_session_id,
        "stage": stage_name,
        "entryPoint": entry_point,
        "originalResourceId": original_resource_id,
        "originalRawSha256": original_sha256,
        "candidateRawSha256": candidate_sha256,
        "physicalAbiSha256": abi_sha256,
    })


def _shader_override_events(params):
    raw_events = params.get("events")
    if raw_events is None:
        raw_events = [{
            "event_id": params.get("event_id"),
            "expected_original_resource_id": params.get(
                "expected_original_resource_id"),
            "expected_original_sha256": params.get("expected_original_sha256"),
        }]
    if not isinstance(raw_events, list) or not raw_events:
        raise ValueError("events must be a non-empty array")
    if len(raw_events) > MAX_EVENT_SHADER_OVERRIDES:
        raise ValueError("events exceeds the event shader override limit")

    result = []
    seen = set()
    common_sha256 = params.get("expected_original_sha256")
    for index, value in enumerate(raw_events):
        if not isinstance(value, dict):
            raise ValueError("events[%d] must be an object" % index)
        event_id = _safe_int(value.get("event_id", value.get("eventId")), 0)
        if event_id <= 0:
            raise ValueError("events[%d].event_id must be positive" % index)
        if event_id in seen:
            raise ValueError("events contains duplicate event_id %d" % event_id)
        seen.add(event_id)
        resource_id = _safe_int(value.get(
            "expected_original_resource_id",
            value.get("expectedOriginalResourceId")), 0)
        if resource_id <= 0:
            raise ValueError(
                "events[%d].expected_original_resource_id must be positive" % index)
        digest = value.get(
            "expected_original_sha256",
            value.get("expectedOriginalSha256", common_sha256))
        digest = _shader_override_hex(
            digest, "events[%d].expected_original_sha256" % index, 64)
        result.append({
            "eventId": event_id,
            "expectedOriginalResourceId": resource_id,
            "expectedOriginalSha256": digest,
        })
    if len(set(item["expectedOriginalSha256"] for item in result)) != 1:
        raise ValueError(
            "all Shader-family events must have the same original raw SHA-256")
    if len(set(item["expectedOriginalResourceId"] for item in result)) != 1:
        raise ValueError(
            "all Shader-family events must preserve one captured shader ResourceId")
    return result


def _captured_original_from_shared_owner(active_reflection, event, stage_name,
                                         entry_point, owner, allow_original_active=False):
    """Validate retained original identity under a separately verified owner."""
    if any((owner.get("expectedOriginalResourceId") != event["expectedOriginalResourceId"],
            owner.get("expectedOriginalSha256") != event["expectedOriginalSha256"],
            owner.get("stageName") != stage_name, owner.get("entryPoint") != entry_point)):
        raise RuntimeError("The shared Shader owner is bound to a different captured original identity")
    active_entry = str(getattr(active_reflection, "entryPoint", "") or entry_point)
    active_bytes = _shader_raw_bytes(active_reflection)
    active_sha256 = hashlib.sha256(active_bytes).hexdigest() if active_bytes else ""
    allowed = {owner.get("candidateRawSha256")}
    # Reflection is not a universal query for the active executable. Vulkan
    # and OpenGL look up the requested captured shader's creation record;
    # D3D11 may also expose captured reflection while replacement is active.
    # Ownership and checked replacement are proved separately by the caller.
    if allow_original_active:
        allowed.add(event["expectedOriginalSha256"])
    if active_entry != entry_point or active_sha256 not in allowed:
        raise RuntimeError("Event %d active shared Shader target changed outside Bread" % event["eventId"])
    reflection = owner.get("capturedOriginalReflection")
    if reflection is None:
        raise RuntimeError("The captured-original Shader reflection is no longer available")
    raw_bytes = _shader_raw_bytes(reflection)
    if (str(getattr(reflection, "entryPoint", "") or entry_point) != entry_point or
            not raw_bytes or hashlib.sha256(raw_bytes).hexdigest() != event["expectedOriginalSha256"]):
        raise RuntimeError("The retained captured-original Shader identity changed")
    return reflection


def _validate_live_shader_event(ctrl, event, stage, stage_name, entry_point,
                                require_d3d11_state=True,
                                owned_shared_replacement=None,
                                verified_physical_abi_sha256="",
                                event_already_selected=False):
    """Return immutable live facts for one exact captured event/stage."""
    if not event_already_selected:
        _set_frame_event(ctrl, event["eventId"], True)
    else:
        _require_healthy_replay(ctrl)
    pipeline = ctrl.GetPipelineState()
    original_id = pipeline.GetShader(stage)
    if (_resource_id_int(original_id) !=
            event["expectedOriginalResourceId"]):
        raise RuntimeError(
            "Event %d bound a different shader resource" % event["eventId"])

    entries = list(ctrl.GetShaderEntryPoints(original_id) or [])
    selected_entry = _exact_shader_entry(entries, entry_point, stage_name)
    if selected_entry is None:
        raise RuntimeError(
            "Event %d shader entry point/stage changed or became ambiguous" %
            event["eventId"])
    try:
        pipeline_entry = str(pipeline.GetShaderEntryPoint(stage) or "")
    except Exception:
        pipeline_entry = entry_point
    if pipeline_entry and pipeline_entry != entry_point:
        entry_names = [
            str(getattr(candidate, "name", "") or "")
            for candidate in entries
        ]
        # Some native D3D12 pipeline snapshots expose the generic source-level
        # placeholder ``main`` even though the DXIL container has one renamed
        # physical entry (for example ``MainPS``).  The placeholder is not an
        # executable identity.  Accept it only when it resolves to no container
        # entry and the container has exactly one entry, already matched above.
        # A real alternative/multi-entry pipeline name remains a hard failure.
        if (pipeline_entry.lower() != "main" or
                pipeline_entry in entry_names or len(entries) != 1):
            raise RuntimeError(
                "Event %d pipeline entry point changed" % event["eventId"])

    pipeline_id = _get_pipeline_obj(pipeline, ctrl)
    active_reflection = ctrl.GetShader(
        pipeline_id, original_id, selected_entry)
    if not active_reflection:
        raise RuntimeError(
            "Event %d shader reflection is unavailable" %
            event["eventId"])
    # Resource replacement is intentionally transparent to the pipeline state:
    # GetShader(stage) still returns the canonical captured ResourceId.  On
    # D3D12, however, GetShader(pipeline, that_id, entry) resolves through the
    # active mapping and returns the *target* reflection.  A later live-edit
    # revision must therefore prove two separate identities:
    #
    # * the live pipeline is still using the bridge-owned last-good target; and
    # * ABI validation still uses the immutable captured-original reflection.
    #
    # Treating the active target bytes as the original caused every rev1 -> rev2
    # supersede to fail before ReplaceTargetShaderChecked could run.
    reflection = active_reflection
    if owned_shared_replacement is not None:
        reflection = _captured_original_from_shared_owner(
            active_reflection, event, stage_name, entry_point, owned_shared_replacement,
            allow_original_active=(_shader_api_token(ctrl) in ("d3d11", "vulkan", "opengl")))

    reflected_entry = str(getattr(reflection, "entryPoint", "") or entry_point)
    original_bytes = _shader_raw_bytes(reflection)
    original_sha256 = (
        hashlib.sha256(original_bytes).hexdigest() if original_bytes else "")
    if (reflected_entry != entry_point or
            original_sha256 != event["expectedOriginalSha256"]):
        raise RuntimeError(
            "Event %d original shader bytes or entry point changed" %
            event["eventId"])
    if require_d3d11_state and list(getattr(reflection, "interfaces", []) or []):
        raise RuntimeError(
            "D3D11 dynamic linkage interfaces are not supported by the ABI gate")

    if require_d3d11_state:
        d3d11_stage = _d3d11_stage_state(ctrl, stage_name)
        if d3d11_stage is None:
            raise RuntimeError("D3D11 stage state is unavailable")
        if (_resource_id_int(getattr(d3d11_stage, "resourceId", None)) !=
                event["expectedOriginalResourceId"]):
            raise RuntimeError(
                "Event %d D3D11 stage state changed" % event["eventId"])
        if list(getattr(d3d11_stage, "classInstances", []) or []):
            raise RuntimeError(
                "D3D11 dynamic shader linkage is not supported by the ABI gate")

    dxil_access = (
        owned_shared_replacement.get("capturedDxilAccessSignature")
        if owned_shared_replacement is not None else None)
    dxil_layout_evidence = (
        owned_shared_replacement.get("capturedDxilLayoutEvidence")
        if owned_shared_replacement is not None else None)
    physical_abi_sha256 = (verified_physical_abi_sha256 or
                           _physical_shader_interface_sha256(reflection))
    if (not verified_physical_abi_sha256 and
            _shader_encoding_token(getattr(reflection, "encoding", "")) == "dxil"):
        # The catalog and Host ABI bind stripped DXIL using the same fixed DXC
        # layout/access evidence. Hashing raw RenderDoc placeholder members here
        # would produce a different identity even though the subsequent strict
        # access comparison accepts the interface. Compute this live identity
        # from the exact evidence once and reuse it for the candidate gate.
        if dxil_access is None or dxil_layout_evidence is None:
            dxil_access, dxil_layout_evidence = (
                _dxil_evidence_from_live_disassembly(
                    ctrl, pipeline_id, reflection))
        physical_abi_sha256 = _physical_shader_interface_sha256(
            reflection, dxil_layout_evidence)
    if (owned_shared_replacement is not None and
            physical_abi_sha256 !=
            owned_shared_replacement.get("physicalAbiSha256") and
            not (owned_shared_replacement.get("abiValidationMode") == "manual-fast" and
                 not owned_shared_replacement.get("physicalAbiSha256"))):
        raise RuntimeError(
            "The captured-original Shader ABI identity changed")

    return {
        "event": event,
        "originalResource": original_id,
        "pipelineResource": pipeline_id,
        "reflection": reflection,
        "activeReflection": active_reflection,
        "physicalAbiSha256": physical_abi_sha256,
        "dxilAccessSignature": dxil_access,
        "dxilLayoutEvidence": dxil_layout_evidence,
    }


def _manual_shared_shader_original(ctrl, original_resource, event, stage_name,
                                   entry_point, owner):
    """Read captured identity without stepping/replaying an anchor or comparing ABI.

    Shader resources are immutable for a capture lifetime. Once retained by an
    owned replacement, these facts do not depend on the currently selected EID.
    UI ownership, capture/session and the original raw hash are checked by this
    path; none of these checks asserts candidate interface compatibility.
    """
    if owner is not None:
        if any((owner.get("expectedOriginalResourceId") != event["expectedOriginalResourceId"],
                owner.get("expectedOriginalSha256") != event["expectedOriginalSha256"],
                owner.get("stageName") != stage_name, owner.get("entryPoint") != entry_point,
                owner.get("captureSessionId") != _capture_session_id,
                owner.get("captureToken") != _current_capture_token())):
            raise RuntimeError("The manual Shader edit belongs to a different captured original")
        reflection = owner.get("capturedOriginalReflection")
        pipeline_resource = owner.get("capturedOriginalPipelineResource", rd.ResourceId())
    else:
        entries = list(ctrl.GetShaderEntryPoints(original_resource) or [])
        entry = _exact_shader_entry(entries, entry_point, stage_name)
        if entry is None:
            raise RuntimeError("The captured Shader entry point/stage changed or became ambiguous")
        pipeline_resource = rd.ResourceId()
        reflection = ctrl.GetShader(pipeline_resource, original_resource, entry)
    raw = _shader_raw_bytes(reflection) if reflection else b""
    if (not raw or hashlib.sha256(raw).hexdigest() != event["expectedOriginalSha256"] or
            str(getattr(reflection, "entryPoint", "") or entry_point) != entry_point):
        raise RuntimeError("The captured Shader bytes or entry point changed before manual edit")
    return {
        "event": event, "originalResource": original_resource,
        "pipelineResource": pipeline_resource, "reflection": reflection,
        # This is an optional identity of the captured original, never a proof
        # that the unvalidated manual candidate has the same interface.
        "physicalAbiSha256": owner.get("physicalAbiSha256", "") if owner else "",
        "dxilAccessSignature": owner.get("capturedDxilAccessSignature") if owner else None,
        "dxilLayoutEvidence": owner.get("capturedDxilLayoutEvidence") if owner else None,
    }


def _manual_shader_target_key(record):
    return tuple(record.get(key) for key in (
        "captureToken", "api", "encoding", "expectedOriginalResourceId",
        "expectedOriginalSha256", "stageName", "entryPoint", "candidateRawSha256"))


def _verified_restore_original(ctrl, resource, event, stage_name, entry_point, payload, owner=None):
    """Read immutable native bytes without replaying a historical anchor.

    Only an authenticated exact-RDC/native-byte pair enters this path. Resource
    replacement affects all uses, so re-rendering one old EID adds no identity
    evidence. Unknown IDs, unavailable resource-only reflection and an existing
    owner retain the ordinary anchor path. Never cache a GPU object on disk.
    """
    if (payload is None or owner is not None or resource is None
            or _shader_api_token(ctrl) not in ("d3d11", "d3d12", "vulkan", "opengl")):
        return None
    _require_healthy_replay(ctrl)
    try:
        live = _manual_shared_shader_original(ctrl, resource, event, stage_name, entry_point, None)
    except (RuntimeError, ValueError, AttributeError, TypeError):
        return None
    if list(getattr(live["reflection"], "interfaces", []) or []):
        return None
    live["physicalAbiSha256"] = payload["physicalAbiSha256"]
    return live


def _take_manual_shader_target(key):
    for index, record in enumerate(_shared_shader_manual_target_cache):
        if _manual_shader_target_key(record) == key:
            return _shared_shader_manual_target_cache.pop(index)["targetResource"]
    return None


def _retain_manual_shader_target(ctrl, record):
    """Keep a small LRU of inactive native targets for edit/undo/A-B toggles."""
    target = record.get("targetResource")
    target_id = _resource_id_int(target)
    if not target_id or any(row.get("targetResourceId") == target_id
                            for row in _shared_shader_replacements.values()):
        return False
    if any(_resource_id_int(row.get("targetResource")) == target_id
           for row in _shared_shader_manual_target_cache):
        return True
    _shared_shader_manual_target_cache.append(dict(record))
    while len(_shared_shader_manual_target_cache) > 8:
        expired = _shared_shader_manual_target_cache.pop(0)
        try:
            ctrl.FreeTargetResource(expired["targetResource"])
        except Exception:
            _register_orphan_shader_target(expired["targetResource"])
    return True


def _shader_override_response(record, superseded_id=None,
                              superseded_target_freed=True,
                              target_reused=False, idempotent=False):
    target = _event_shader_targets.get(record["familyId"])
    reference_count = len(target.get("overrideIds", set())) if target else 0
    return {
        "schema": "renderdoc-ultra-event-shader-override/v1",
        "schemaVersion": 1,
        "overrideId": record["overrideId"],
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "workspaceId": record["workspaceId"],
        "revision": record["revision"],
        "eventId": record["eventId"],
        "stage": record["stageName"],
        "entryPoint": record["entryPoint"],
        "api": "d3d11",
        "encoding": "dxbc",
        "originalResourceId": record["expectedOriginalResourceId"],
        "originalRawSha256": record["expectedOriginalSha256"],
        "candidateRawSha256": record["candidateRawSha256"],
        "physicalAbiSha256": record["physicalAbiSha256"],
        "shaderFamilyId": record["familyId"],
        "targetResourceId": record["targetResourceId"],
        "targetReferenceCount": reference_count,
        "targetShared": reference_count > 1,
        "targetReused": bool(target_reused),
        "idempotent": bool(idempotent),
        "abiRequestId": record["abiRequestId"],
        "abiReportSha256": record["abiReportSha256"],
        "eventScoped": True,
        "configured": True,
        "appliedToCurrentEvent": True,
        "originalShaderPreserved": True,
        "supersededOverrideId": superseded_id,
        "supersededTargetFreed": bool(superseded_target_freed),
    }


def _apply_shader_candidate_overrides(params):
    """Transactionally apply one physical Shader family to many events."""
    global _event_shader_overrides, _event_shader_targets
    global _event_shader_override_capture_token

    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_token = _current_capture_token()
    if (_event_shader_override_capture_token is not None and
            _event_shader_override_capture_token != capture_token):
        _forget_event_shader_overrides()

    candidate_path, candidate_bytes, candidate_sha256 = _read_shader_candidate(params)
    if str(params.get("encoding", "dxbc") or "dxbc").strip().lower() != "dxbc":
        raise ValueError("Only native DXBC event shader overrides are supported")
    requested_stage = _normalise_stage_name(params.get("stage", ""))
    stage_map = dict(_available_shader_stages([requested_stage]))
    stage = stage_map.get(requested_stage)
    if stage is None or requested_stage not in (
            "vertex", "hull", "domain", "geometry", "fragment", "compute"):
        raise ValueError("Unsupported D3D11 shader stage: %s" % requested_stage)
    entry_point = str(params.get("entry_point", "") or "").strip()
    if not entry_point:
        raise ValueError("entry_point is required")
    workspace_id = _shader_override_hex(params.get("workspace_id"), "workspace_id", 32)
    revision = _safe_int(params.get("revision"), 0)
    if revision <= 0:
        raise ValueError("revision must be a positive integer")
    request_id = _shader_override_hex(params.get("abi_request_id"), "abi_request_id", 64)
    report_sha256 = _shader_override_hex(
        params.get("abi_report_sha256"), "abi_report_sha256", 64)
    events = _shader_override_events(params)
    original_resource_id = events[0]["expectedOriginalResourceId"]
    if original_resource_id in _shared_shader_replacements:
        raise RuntimeError(
            "The captured Shader already has a resource-scoped replacement; "
            "roll it back before applying event-scoped overrides")

    new_slots = 0
    for event in events:
        existing_id, existing = _event_shader_override_for_slot(
            event["eventId"], requested_stage)
        if existing is None:
            new_slots += 1
    if len(_event_shader_overrides) + new_slots > MAX_EVENT_SHADER_OVERRIDES:
        raise RuntimeError(
            "The active capture reached the %d event shader override limit" %
            MAX_EVENT_SHADER_OVERRIDES)

    encoding = getattr(rd.ShaderEncoding, "DXBC", None)
    if encoding is None:
        raise RuntimeError("This RenderDoc build does not expose ShaderEncoding.DXBC")
    try:
        original_event = _request_visible_event_id(0)
    except Exception:
        original_event = 0

    def _do(ctrl):
        api_name = _native_enum_text(getattr(ctrl.GetAPIProperties(), "pipelineType", None))
        if api_name.lower().replace("graphicsapi.", "") not in (
                "d3d11", "direct3d11"):
            raise RuntimeError("Event shader overrides currently require a D3D11 capture")
        if encoding not in list(ctrl.GetTargetShaderEncodings()):
            raise RuntimeError("DXBC target shaders are unsupported by this replay")

        live = []
        for event in events:
            live.append(_validate_live_shader_event(
                ctrl, event, stage, requested_stage, entry_point))
        abi_hashes = set(item["physicalAbiSha256"] for item in live)
        if len(abi_hashes) != 1:
            raise RuntimeError(
                "Selected events do not share one physical Shader ABI")
        abi_sha256 = next(iter(abi_hashes))
        original_sha256 = events[0]["expectedOriginalSha256"]
        family_id = _shader_family_id(
            _capture_session_id, requested_stage, entry_point,
            events[0]["expectedOriginalResourceId"], original_sha256,
            candidate_sha256, abi_sha256)

        prepared = []
        for item in live:
            event = item["event"]
            existing_id, existing = _event_shader_override_for_slot(
                event["eventId"], requested_stage)
            exact_idempotent = bool(
                existing is not None and
                existing.get("familyId") == family_id and
                existing.get("workspaceId") == workspace_id and
                existing.get("revision") == revision and
                existing.get("abiRequestId") == request_id and
                existing.get("abiReportSha256") == report_sha256 and
                existing.get("expectedOriginalResourceId") ==
                event["expectedOriginalResourceId"])
            prepared.append({
                "live": item,
                "existingId": existing_id,
                "existing": existing,
                "idempotent": exact_idempotent,
                "metadataOnly": bool(
                    existing is not None and
                    existing.get("familyId") == family_id and
                    not exact_idempotent),
            })

        target = _event_shader_targets.get(family_id)
        target_id = target.get("targetResource") if target else None
        built_target = False
        if target is None and any(not item["idempotent"] for item in prepared):
            target_id, messages = _build_target_shader(
                ctrl,
                entry_point, encoding, candidate_bytes,
                rd.ShaderCompileFlags(), stage)
            if not _resource_id_int(target_id):
                raise RuntimeError(
                    "BuildTargetShader failed: %s" % str(messages or ""))
            built_target = True

            target_entries = list(ctrl.GetShaderEntryPoints(target_id) or [])
            target_entry = _exact_shader_entry(
                target_entries, entry_point, requested_stage)
            if target_entry is None:
                try:
                    ctrl.FreeTargetResource(target_id)
                except Exception:
                    _register_orphan_shader_target(target_id)
                raise RuntimeError(
                    "The target shader has no unique requested entry point/stage")
            target_reflection = ctrl.GetShader(
                rd.ResourceId(), target_id, target_entry)
            target_raw = (
                _shader_raw_bytes(target_reflection) if target_reflection else b"")
            try:
                if (not target_reflection or
                        hashlib.sha256(target_raw).hexdigest() != candidate_sha256):
                    raise RuntimeError(
                        "The built target shader does not match candidate bytes")
                if not _physical_shader_interfaces_compatible(
                        live[0]["reflection"], target_reflection):
                    raise RuntimeError(
                        "The candidate physical ABI differs from the original Shader family")
            except Exception:
                try:
                    ctrl.FreeTargetResource(target_id)
                except Exception:
                    _register_orphan_shader_target(target_id)
                raise
            target = {
                "familyId": family_id,
                "targetResource": target_id,
                "targetResourceId": _resource_id_int(target_id),
                "candidateRawSha256": candidate_sha256,
                "physicalAbiSha256": abi_sha256,
                "overrideIds": set(),
            }
        elif target is None:
            raise RuntimeError("Shader family target bookkeeping is unavailable")

        configured = []
        failed_item = None
        try:
            for item in prepared:
                if item["idempotent"] or item["metadataOnly"]:
                    continue
                # ReplayController requires eventId to equal its current
                # effective event. Revalidate the exact binding immediately
                # before the setter so validation and mutation are adjacent.
                prior_live = item["live"]
                live_item = _validate_live_shader_event(
                    ctrl, prior_live["event"], stage,
                    requested_stage, entry_point)
                if (live_item["physicalAbiSha256"] != abi_sha256 or
                        _resource_id_int(live_item["originalResource"]) !=
                        _resource_id_int(prior_live["originalResource"])):
                    raise RuntimeError(
                        "Event %d Shader binding changed during family apply" %
                        prior_live["event"]["eventId"])
                item["live"] = live_item
                failed_item = item
                _begin_replay_atomic_transaction()
                error = ctrl.SetEventShaderOverride(
                    live_item["event"]["eventId"], stage,
                    live_item["originalResource"], target_id)
                if str(error or ""):
                    raise RuntimeError(
                        "SetEventShaderOverride failed at event %d: %s" %
                        (live_item["event"]["eventId"], str(error or "")))
                configured.append(item)
                failed_item = None
            # Validation and SetEventShaderOverride temporarily select every
            # family event. Restore the user's prior replay selection before
            # committing bookkeeping; a restore failure therefore enters the
            # same transactional rollback path below.
            if original_event > 0:
                _set_frame_event(ctrl, original_event, True)
        except BaseException:
            # A setter may fail after removing the previous config. Restore the
            # failed slot as well as every earlier slot, in reverse order.
            restore = list(configured)
            if failed_item is not None:
                restore.append(failed_item)
            restore_failures = []
            for item in reversed(restore):
                event_id = item["live"]["event"]["eventId"]
                try:
                    ctrl.ClearEventShaderOverride(event_id, stage)
                except Exception:
                    pass
                previous = item.get("existing")
                if previous is not None:
                    try:
                        _set_frame_event(ctrl, event_id, True)
                        restore_error = ctrl.SetEventShaderOverride(
                            event_id, stage,
                            item["live"]["originalResource"],
                            previous["targetResource"])
                        if str(restore_error or ""):
                            raise RuntimeError(str(restore_error))
                    except Exception:
                        restore_failures.append(item)
            for item in restore_failures:
                old_id = item.get("existingId")
                old = _event_shader_overrides.pop(old_id, None)
                if old is not None:
                    old_target = _event_shader_targets.get(old.get("familyId"))
                    if old_target is not None:
                        old_target["overrideIds"].discard(old_id)
            if built_target:
                try:
                    ctrl.FreeTargetResource(target_id)
                except Exception:
                    _register_orphan_shader_target(target_id)
            if original_event > 0:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass
            raise

        if built_target:
            _event_shader_targets[family_id] = target

        committed = []
        old_families = set()
        for item in prepared:
            if item["idempotent"]:
                committed.append({
                    "record": item["existing"],
                    "supersededId": None,
                    "idempotent": True,
                    "oldFamily": None,
                })
                continue
            event = item["live"]["event"]
            override_id = uuid.uuid4().hex
            existing_id = item.get("existingId")
            existing = item.get("existing")
            if existing is not None:
                _event_shader_overrides.pop(existing_id, None)
                old_family = existing.get("familyId")
                old_target = _event_shader_targets.get(old_family)
                if old_target is not None:
                    old_target["overrideIds"].discard(existing_id)
                    old_families.add(old_family)
            else:
                old_family = None
            record = {
                "overrideId": override_id,
                "captureId": capture_id,
                "captureSessionId": _capture_session_id,
                "captureToken": capture_token,
                "eventId": event["eventId"],
                "stageName": requested_stage,
                "stageObject": stage,
                "entryPoint": entry_point,
                "expectedOriginalResourceId": event[
                    "expectedOriginalResourceId"],
                "originalResource": item["live"]["originalResource"],
                "expectedOriginalSha256": original_sha256,
                "candidateRawSha256": candidate_sha256,
                "candidatePath": candidate_path,
                "targetResource": target_id,
                "targetResourceId": _resource_id_int(target_id),
                "familyId": family_id,
                "physicalAbiSha256": abi_sha256,
                "workspaceId": workspace_id,
                "revision": revision,
                "abiRequestId": request_id,
                "abiReportSha256": report_sha256,
            }
            _event_shader_overrides[override_id] = record
            target["overrideIds"].add(override_id)
            committed.append({
                "record": record,
                "supersededId": existing_id,
                "idempotent": False,
                "oldFamily": old_family,
            })

        freed_families = set()
        for old_family in old_families:
            old_target = _event_shader_targets.get(old_family)
            if old_target is None or old_target["overrideIds"]:
                continue
            try:
                ctrl.FreeTargetResource(old_target["targetResource"])
                _event_shader_targets.pop(old_family, None)
                freed_families.add(old_family)
            except Exception:
                # Retain an unreferenced target for lifecycle cleanup rather
                # than accidentally freeing a captured/original shader.
                _register_orphan_shader_target(old_target["targetResource"])
                _event_shader_targets.pop(old_family, None)

        responses = []
        for item in committed:
            old_family = item["oldFamily"]
            responses.append(_shader_override_response(
                item["record"],
                superseded_id=item["supersededId"],
                superseded_target_freed=(
                    old_family is None or old_family == family_id or
                    old_family in freed_families),
                target_reused=not built_target,
                idempotent=item["idempotent"],
            ))
        return {
            "schema": "renderdoc-ultra-event-shader-override-batch/v1",
            "schemaVersion": 1,
            "captureId": capture_id,
            "captureSessionId": _capture_session_id,
            "shaderFamilyId": family_id,
            "physicalAbiSha256": abi_sha256,
            "candidateRawSha256": candidate_sha256,
            "targetResourceId": target["targetResourceId"],
            "targetReferenceCount": len(target["overrideIds"]),
            "targetBuiltOnce": built_target,
            "targetReused": not built_target,
            "transactional": True,
            "originalShadersPreserved": True,
            "overrides": responses,
        }

    def _do_with_event_restore(ctrl):
        try:
            return _do(ctrl)
        except Exception:
            # Validation/build failures happen before the inner setter
            # transaction. They must still restore the user's selected event.
            if original_event > 0:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass
            raise

    result = _replay(_do_with_event_restore)
    _event_shader_override_capture_token = capture_token
    _notify_shader_replay_changed()
    return result


def _apply_shader_candidate_override(params):
    """Compatibility wrapper for one event, backed by the family transaction."""
    batch = _apply_shader_candidate_overrides(params)
    if len(batch.get("overrides", [])) != 1:
        raise RuntimeError("Single Shader override returned an invalid batch result")
    return batch["overrides"][0]


def _rollback_shader_candidate_overrides(params):
    """Transactionally clear overrides; free only unreferenced family targets."""
    global _event_shader_overrides, _event_shader_targets
    global _event_shader_override_capture_token

    raw_ids = params.get("override_ids")
    if raw_ids is None:
        raw_ids = [params.get("override_id")]
    if not isinstance(raw_ids, list) or not raw_ids:
        raise ValueError("override_ids must be a non-empty array")
    if len(raw_ids) > MAX_EVENT_SHADER_OVERRIDES:
        raise ValueError("override_ids exceeds the event shader override limit")
    override_ids = []
    for index, value in enumerate(raw_ids):
        override_id = _shader_override_hex(
            value, "override_ids[%d]" % index, 32)
        if override_id in override_ids:
            raise ValueError("override_ids contains a duplicate token")
        override_ids.append(override_id)

    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_session_id = _shader_rollback_capture_session(params)
    current_token = _current_capture_token()
    records = []
    tombstones = []
    for override_id in override_ids:
        record = _event_shader_overrides.get(override_id)
        tombstone = _event_shader_rollback_tombstones.get(override_id)
        if record is not None and tombstone is not None:
            raise RuntimeError(
                "Shader rollback bookkeeping contains an active/tombstone collision")
        if record is not None:
            records.append(record)
        elif tombstone is not None:
            tombstones.append(tombstone)
        else:
            raise ValueError("Unknown or expired event shader override ID")

    if records and tombstones:
        raise RuntimeError(
            "Shader family rollback mixes active and already-restored override IDs")
    if tombstones:
        for tombstone in tombstones:
            if tombstone.get("captureId") != capture_id:
                raise RuntimeError(
                    "The rollback receipt belongs to a different capture identity")
            if (tombstone.get("captureSessionId") != capture_session_id or
                    tombstone.get("captureToken") != current_token):
                _forget_event_shader_overrides()
                raise RuntimeError(
                    "The rollback receipt belongs to a different capture lifecycle")
        results = [
            _event_shader_rollback_receipt(tombstone["receipt"], True)
            for tombstone in tombstones
        ]
        return {
            "schema": "renderdoc-ultra-event-shader-rollback-batch/v1",
            "schemaVersion": 1,
            "captureId": capture_id,
            "captureSessionId": capture_session_id,
            "transactional": True,
            "originalShadersPreserved": True,
            "alreadyRestored": True,
            "idempotentRollback": True,
            "overrides": results,
        }

    for record in records:
        if record.get("captureId") != capture_id:
            raise RuntimeError(
                "The override belongs to a different capture identity")
        if (record.get("captureSessionId") != capture_session_id or
                record.get("captureToken") != current_token or
                _event_shader_override_capture_token != current_token):
            _forget_event_shader_overrides()
            raise RuntimeError(
                "The override belongs to a different capture lifecycle")
        if record.get("familyId") not in _event_shader_targets:
            raise RuntimeError("Shader family target bookkeeping is unavailable")
    try:
        original_event = _request_visible_event_id(0)
    except Exception:
        original_event = 0

    def _do(ctrl):
        cleared = []
        failed = None
        try:
            for record in records:
                failed = record
                _begin_replay_atomic_transaction()
                ctrl.ClearEventShaderOverride(
                    record["eventId"], record["stageObject"])
                cleared.append(record)
                failed = None
        except Exception:
            restore = list(cleared)
            if failed is not None:
                restore.append(failed)
            restore_failures = []
            for record in reversed(restore):
                try:
                    _set_frame_event(ctrl, record["eventId"], True)
                    restore_error = ctrl.SetEventShaderOverride(
                        record["eventId"], record["stageObject"],
                        record["originalResource"],
                        record["targetResource"])
                    if str(restore_error or ""):
                        raise RuntimeError(str(restore_error))
                except Exception:
                    restore_failures.append(record)
            for record in restore_failures:
                override_id = record["overrideId"]
                _event_shader_overrides.pop(override_id, None)
                target = _event_shader_targets.get(record["familyId"])
                if target is not None:
                    target["overrideIds"].discard(override_id)
            if original_event > 0:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass
            raise

        affected_families = set()
        for record in records:
            override_id = record["overrideId"]
            _event_shader_overrides.pop(override_id, None)
            target = _event_shader_targets[record["familyId"]]
            target["overrideIds"].discard(override_id)
            affected_families.add(record["familyId"])

        freed = set()
        free_warnings = {}
        for family_id in affected_families:
            target = _event_shader_targets.get(family_id)
            if target is None or target["overrideIds"]:
                continue
            try:
                ctrl.FreeTargetResource(target["targetResource"])
                _event_shader_targets.pop(family_id, None)
                freed.add(family_id)
            except Exception as exc:
                free_warnings[family_id] = str(exc)
                _register_orphan_shader_target(target["targetResource"])
                _event_shader_targets.pop(family_id, None)

        selection_warning = ""
        if original_event > 0:
            try:
                _set_frame_event(ctrl, original_event, True)
            except Exception as exc:
                selection_warning = str(exc)

        results = []
        for record in records:
            target = _event_shader_targets.get(record["familyId"])
            reference_count = len(target["overrideIds"]) if target else 0
            results.append({
                "schema": "renderdoc-ultra-event-shader-override/v1",
                "schemaVersion": 1,
                "overrideId": record["overrideId"],
                "captureId": capture_id,
                "captureSessionId": _capture_session_id,
                "eventId": record["eventId"],
                "stage": record["stageName"],
                "entryPoint": record["entryPoint"],
                "api": "d3d11",
                "encoding": "dxbc",
                "originalResourceId": record["expectedOriginalResourceId"],
                "originalRawSha256": record["expectedOriginalSha256"],
                "candidateRawSha256": record["candidateRawSha256"],
                "physicalAbiSha256": record["physicalAbiSha256"],
                "shaderFamilyId": record["familyId"],
                "targetResourceId": record["targetResourceId"],
                "resourceScoped": False,
                "eventScoped": True,
                "cleared": True,
                "targetFreed": record["familyId"] in freed,
                "targetReferenceCount": reference_count,
                "originalShaderPreserved": True,
                "clearWarning": free_warnings.get(record["familyId"], ""),
                "selectionWarning": selection_warning,
            })
        return {
            "schema": "renderdoc-ultra-event-shader-rollback-batch/v1",
            "schemaVersion": 1,
            "captureId": capture_id,
            "captureSessionId": _capture_session_id,
            "transactional": True,
            "originalShadersPreserved": True,
            "overrides": results,
        }

    result = _replay(_do)
    _notify_shader_replay_changed()
    result["alreadyRestored"] = False
    result["idempotentRollback"] = False
    for receipt in result.get("overrides", []):
        receipt["alreadyRestored"] = False
        receipt["idempotentRollback"] = False
        _remember_event_shader_rollback_receipt(receipt, current_token)
    if not _event_shader_overrides and not _event_shader_targets:
        _event_shader_override_capture_token = None
    return result


def _rollback_shader_candidate_override(params):
    """Compatibility wrapper for one family-aware transactional rollback."""
    batch = _rollback_shader_candidate_overrides(params)
    if len(batch.get("overrides", [])) != 1:
        raise RuntimeError("Single Shader rollback returned an invalid batch result")
    return batch["overrides"][0]


def _shared_shader_replacement_response(record, idempotent=False,
                                        metadata_only=False,
                                        operation_id=None,
                                        operation_created_replacement=False,
                                        superseded_id=None,
                                        superseded_target_freed=True,
                                        verified_restore_receipt=None,
                                        verified_restore_mode="verified-rdc-restore"):
    if record.get("postApplyValidationFailed") is True:
        raise RuntimeError(
            "Shader replacement %s requires recovery after failed post-apply validation; "
            "its live target is retained, not a completed apply"
            % record["replacementId"])
    result = {
        "schema": "renderdoc-ultra-shared-shader-replacement/v1",
        "schemaVersion": 1,
        "replacementId": record["replacementId"],
        "operationId": str(operation_id or record.get("operationId", "") or ""),
        "operationCreatedReplacement": bool(operation_created_replacement),
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "workspaceId": record["workspaceId"],
        "revision": record["revision"],
        "anchorEventId": record["anchorEventId"],
        "stage": record["stageName"],
        "entryPoint": record["entryPoint"],
        "api": record["api"],
        "encoding": record["encoding"],
        "originalResourceId": record["expectedOriginalResourceId"],
        "originalRawSha256": record["expectedOriginalSha256"],
        "candidateRawSha256": record["candidateRawSha256"],
        "physicalAbiSha256": record["physicalAbiSha256"],
        "shaderFamilyId": record["familyId"],
        "targetResourceId": record["targetResourceId"],
        "abiRequestId": record["abiRequestId"],
        "abiReportSha256": record["abiReportSha256"],
        "resourceScoped": True,
        "eventScoped": False,
        "allOriginalResourceUsesAffected": True,
        "configured": True,
        "originalShaderPreserved": True,
        "singleOwner": True,
        "checkedDerivedPipelineRebuild": record["api"] in (
            "d3d12", "vulkan", "opengl"),
        "capturedRootSignaturesReused": record["api"] == "d3d12",
        "postApplyAnchorVerified": bool(
            record.get("postApplyAnchorVerified", False)),
        "postApplyMappingVerified": record.get("postApplyMappingVerified") is True,
        "idempotent": bool(idempotent),
        "metadataOnly": bool(metadata_only),
        "targetBuiltOnce": not (idempotent or metadata_only),
        "targetReused": bool(idempotent or metadata_only),
        "supersededReplacementId": superseded_id,
        "supersededTargetFreed": bool(superseded_target_freed),
    }
    if record.get("restoreValidationReceipt") is not None:
        result["restoreValidationReceipt"] = record["restoreValidationReceipt"]
    if record.get("restoreValidationReceiptError"):
        result["restoreValidationReceiptError"] = record["restoreValidationReceiptError"]
    if record.get("restoreValidationReceiptUpgrade"):
        result["restoreValidationReceiptUpgrade"] = record["restoreValidationReceiptUpgrade"]
    if record.get("restoredOriginalResourceId") is not None:
        result["restoredOriginalResourceId"] = record["restoredOriginalResourceId"]
    validation_mode = str(record.get("abiValidationMode", "") or "")
    if validation_mode == "manual-fast":
        result.update({
            "validationScope": "manual-edit-unvalidated",
            "manualEdit": True,
            "replayAbiValidated": False,
            "freshPhysicalValidationPerformed": False,
            "sourceSha256": record.get("sourceSha256", ""),
            "targetProfile": record.get("targetProfile"),
            "targetCacheHit": bool(record.get("targetCacheHit", False)),
            "supersededTargetCached": bool(record.get("supersededTargetCached", False)),
            "targetBuiltOnce": not (idempotent or metadata_only or record.get("targetCacheHit")),
            "targetReused": bool(idempotent or metadata_only or record.get("targetCacheHit")),
        })
    if record.get("timingsMs") is not None:
        result["timingsMs"] = dict(record["timingsMs"])
    if validation_mode:
        result.update({
            "abiValidationMode": validation_mode,
            "preliminaryReflectionSkipped": bool(
                record.get("preliminaryReflectionSkipped", False)),
            "freshPhysicalAbiValidationPerformed": bool(
                record.get("freshPhysicalAbiValidationPerformed", False)),
            "abiLeaseRequestId": record.get("abiLeaseRequestId"),
            "abiLeaseReportSha256": record.get("abiLeaseReportSha256"),
            "abiLeaseCandidateRawSha256": record.get(
                "abiLeaseCandidateRawSha256"),
            "abiLeaseRevision": record.get("abiLeaseRevision"),
        })
    if verified_restore_receipt is not None:
        # A successfully authenticated restore can reuse a target whose owner
        # was established by a full apply. Describe this request's validation
        # in its response; retain the owner's original validation/lease history.
        result.update({
            "abiValidationMode": verified_restore_mode,
            "preliminaryReflectionSkipped": True,
            "freshPhysicalAbiValidationPerformed": False,
            "restoreValidationReceipt": verified_restore_receipt,
        })
    return result


def _shader_restore_binding(params):
    binding = params.get("workspace_catalog_binding")
    if not isinstance(binding, dict) or set(binding) != {"projection", "scope"}:
        raise ValueError("Shader restore catalog binding is required")
    projection, scope = binding["projection"], binding["scope"]
    if (not isinstance(projection, dict) or not isinstance(scope, dict) or
            not isinstance(scope.get("identityEvidence"), dict) or
            not isinstance(scope.get("stableIdentityEvidence"), dict)):
        raise ValueError("Shader restore catalog identity evidence is incomplete")
    return {
        "captureId": _shader_override_hex(params.get("expected_capture_id"), "expected_capture_id", 64),
        "workspaceId": _shader_override_hex(params.get("workspace_id"), "workspace_id", 32),
        "revision": _safe_int(params.get("revision"), 0),
        "sourceSha256": _shader_override_hex(params.get("expected_source_sha256"), "expected_source_sha256", 64),
        "candidateRawSha256": _shader_override_hex(params.get("expected_sha256"), "expected_sha256", 64),
        "originalRawSha256": _shader_override_hex(params.get("expected_original_sha256"), "expected_original_sha256", 64),
        "stage": _normalise_stage_name(params.get("stage")),
        "entryPoint": str(params.get("entry_point", "") or ""),
        "encoding": str(params.get("encoding", "dxbc") or "dxbc").lower(),
        "abiRequestId": _shader_override_hex(params.get("abi_request_id"), "abi_request_id", 64),
        "abiReportSha256": _shader_override_hex(params.get("abi_report_sha256"), "abi_report_sha256", 64),
        "catalogBindingSha256": _canonical_json_sha256(binding),
    }


def _shader_restore_catalog_pairs(params):
    binding = params["workspace_catalog_binding"]
    scope = binding["scope"]
    return (
        (params["expected_capture_id"], _canonical_json_sha256(scope["identityEvidence"])),
        (_shader_override_hex(scope.get("stableCaptureId"), "stableCaptureId", 64),
         _canonical_json_sha256(scope["stableIdentityEvidence"])))


def _verified_shader_restore_request(params):
    """Authenticate old proof, then bind its complete RDC bytes to this session."""
    global _known_catalog_capture_ids, _known_catalog_identity_pairs, _known_catalog_stable_pairs
    payload = _shader_restore_receipt_store.verify(params.get("restore_validation_receipt"))
    pair_mode = params.get("abi_validation_mode") == "verified-shader-pair"
    physical_binding = payload.get("physicalValidationBinding")
    if _shader_restore_physical_validation_binding is None:
        if payload.get("validationPolicySha256") != _shader_restore_policy_sha256:
            raise RuntimeError("Shader restore conservative validation policy or replay binary changed")
    elif physical_binding is None:
        raise RuntimeError("Shader restore proof predates physical validation binding; fresh validation is required once")
    elif (_shader_restore_protocol.physical_validation_binding_sha256(
                _shader_restore_physical_validation_binding) != _shader_restore_policy_sha256
            or payload.get("validationPolicySha256") !=
            _shader_restore_protocol.physical_validation_binding_sha256(physical_binding)
            or (physical_binding != _shader_restore_physical_validation_binding
                and not _shader_restore_protocol.compatible_validation_binding(
                    physical_binding, _shader_restore_physical_validation_binding))):
        raise RuntimeError("Shader restore validation policy or replay binary changed")
    expected = _shader_restore_binding(params)
    # Native bytes determine the Shader profile and interface. A successfully
    # checked pair remains that same pair after an unrelated package update or
    # source/workspace/catalog allocation change. Those fields remain signed
    # origin provenance; current source-to-candidate binding belongs to Host.
    pair_fields = ("candidateRawSha256", "originalRawSha256", "stage", "entryPoint", "encoding")
    compared_fields = pair_fields if pair_mode else tuple(expected)
    if any(payload.get(key) != expected[key] for key in compared_fields):
        raise RuntimeError("Shader restore proof no longer matches source/candidate/catalog/report")
    if pair_mode:
        pair_policy = payload.get("pairValidationPolicyVersion", 1)
        if type(pair_policy) is not int or pair_policy != 1:
            raise RuntimeError("Shader pair validation policy is incompatible")
        if params.get("expected_physical_abi_sha256") != payload.get("physicalAbiSha256"):
            raise RuntimeError("Shader pair proof no longer matches its physical ABI")
        if "targetProfile" in payload and params.get("expected_profile") != payload["targetProfile"]:
            raise RuntimeError("Shader pair proof no longer matches its native profile")
    expected_session = _shader_override_hex(
        params.get("expected_capture_session_id"), "expected_capture_session_id", 32)
    token = _current_capture_token()
    if (not _request_capture_loaded() or token is None or
            expected_session != _capture_session_id):
        raise RuntimeError("Shader restore capture session changed")
    capture_path = token[1]
    requested_path = str(params.get("expected_capture_path", "") or "")
    if requested_path and os.path.normcase(os.path.abspath(requested_path)) != capture_path:
        raise RuntimeError("Shader restore capture path changed")
    replay_sha = payload.get("captureReplaySha256")
    if replay_sha is not None:
        if payload.get("captureReplayIdentitySchema") != "bread-rdc-replay-content/v1":
            raise RuntimeError("Shader restore replay-content identity is unsupported")
        _shader_override_hex(replay_sha, "captureReplaySha256", 64)
        current_replay_sha = _shader_restore_capture_digests.replay_digest(capture_path, _capture_session_id)
        if current_replay_sha != replay_sha:
            raise RuntimeError("Shader restore RDC replay contents changed")
        if params.get("expected_capture_sha256", payload["captureSha256"]) != payload["captureSha256"]:
            raise RuntimeError("Shader restore origin capture binding changed")
    else:
        capture_sha256 = _shader_restore_capture_digests.digest(capture_path, _capture_session_id)
        if (capture_sha256 != payload.get("captureSha256") or
                params.get("expected_capture_sha256", capture_sha256) != capture_sha256):
            raise RuntimeError("Shader restore RDC content SHA-256 changed")
    _shader_override_hex(payload.get("physicalAbiSha256"), "physicalAbiSha256", 64)
    exact_pair, stable_pair = _shader_restore_catalog_pairs(params)
    if (len(_known_catalog_capture_ids) >= MAX_KNOWN_CATALOG_CAPTURE_IDS and
            expected["captureId"] not in _known_catalog_capture_ids):
        raise RuntimeError("Too many cached capture identities are active")
    catalog_matches = payload.get("catalogBindingSha256") == expected["catalogBindingSha256"]
    for pair, known in ((exact_pair, _known_catalog_identity_pairs),
                        (stable_pair, _known_catalog_stable_pairs)) if catalog_matches else ():
        if len(known) >= MAX_KNOWN_CATALOG_IDENTITY_PAIRS and pair not in known:
            raise RuntimeError("Too many cached catalog identities are active")
    # Only signed catalog evidence for the exact same RDC enters these caches.
    known_ids = dict(_known_catalog_capture_ids)
    known_ids[expected["captureId"]] = capture_path
    _known_catalog_capture_ids = known_ids
    if catalog_matches:
        _known_catalog_identity_pairs = set(_known_catalog_identity_pairs) | {exact_pair}
        _known_catalog_stable_pairs = set(_known_catalog_stable_pairs) | {stable_pair}
    return payload


def _attach_shader_restore_receipt(record, params, verified=None):
    if record.get("abiValidationMode") == "manual-fast":
        # Manual edits deliberately did not establish a candidate ABI proof.
        # Never turn their persistence metadata into a strict restore receipt.
        record.pop("restoreValidationReceipt", None)
        record.pop("restoreValidationReceiptError", None)
        return
    if verified is not None:
        if params.get("abi_validation_mode") == "verified-shader-pair":
            rebound = _shader_restore_binding(params)
            rebound.update({
                "schema": _shader_restore_protocol.SCHEMA,
                "validationPolicySha256": _shader_restore_policy_sha256,
                "physicalValidationBinding": _shader_restore_physical_validation_binding,
                "packageProvenanceSha256": _shader_restore_package_provenance_sha256,
                "pairValidationPolicyVersion": 1,
                "captureSha256": verified["captureSha256"],
                "physicalAbiSha256": record["physicalAbiSha256"],
                "api": record["api"],
            })
            if "capturedDxilEvidence" in verified:
                rebound["capturedDxilEvidence"] = verified["capturedDxilEvidence"]
            if params.get("expected_profile") is not None:
                rebound["targetProfile"] = params["expected_profile"]
            try:
                if verified.get("captureReplaySha256") is not None:
                    rebound["captureReplaySha256"] = verified["captureReplaySha256"]
                    rebound["captureReplayIdentitySchema"] = verified["captureReplayIdentitySchema"]
                record["restoreValidationReceipt"] = _shader_restore_receipt_store.seal(rebound)
            except Exception as exc:
                # Receipt persistence is a future optimization. Preserve the
                # authenticated pair proof and the successful replay effect.
                record["restoreValidationReceipt"] = params["restore_validation_receipt"]
                record["restoreValidationReceiptError"] = str(exc)[:512]
        else:
            record["restoreValidationReceipt"] = params["restore_validation_receipt"]
        if verified.get("captureReplaySha256") is None:
            try:
                token = _current_capture_token()
                upgraded = dict(record["restoreValidationReceipt"]["payload"])
                upgraded["captureReplaySha256"] = _shader_restore_capture_digests.replay_digest(token[1], _capture_session_id)
                upgraded["captureReplayIdentitySchema"] = "bread-rdc-replay-content/v1"
                # Preserve the receipt used by this operation. Publish a new
                # optional proof rather than rewriting its immutable history.
                record["restoreValidationReceiptUpgrade"] = _shader_restore_receipt_store.seal(upgraded)
            except (ValueError, OSError, AttributeError, TypeError):
                pass  # Unknown/legacy containers retain whole-file validation.
        return
    # Legacy callers do not yet supply a source/catalog binding. Their full
    # apply remains valid but cannot authorize a later restore fast path.
    if not params.get("expected_source_sha256") or not params.get("workspace_catalog_binding"):
        return
    try:
        payload = _shader_restore_binding(params)
        exact_pair, stable_pair = _shader_restore_catalog_pairs(params)
        if (exact_pair not in _known_catalog_identity_pairs and
                stable_pair not in _known_catalog_stable_pairs):
            raise RuntimeError("Shader restore catalog evidence was not validated in this capture")
        token = _current_capture_token()
        if token is None or record["captureSessionId"] != _capture_session_id:
            raise RuntimeError("Capture changed before Shader restore proof publication")
        payload.update({
            "schema": _shader_restore_protocol.SCHEMA,
            "pairValidationPolicyVersion": 1,
            "validationPolicySha256": _shader_restore_policy_sha256,
            "physicalValidationBinding": _shader_restore_physical_validation_binding,
            "packageProvenanceSha256": _shader_restore_package_provenance_sha256,
            "captureSha256": _shader_restore_capture_digests.digest(token[1], _capture_session_id),
            "physicalAbiSha256": record["physicalAbiSha256"],
            "api": record["api"],
        })
        try:
            payload["captureReplaySha256"] = _shader_restore_capture_digests.replay_digest(token[1], _capture_session_id)
            payload["captureReplayIdentitySchema"] = "bread-rdc-replay-content/v1"
        except (ValueError, OSError, AttributeError, TypeError):
            pass
        if params.get("expected_profile") is not None:
            profile = params["expected_profile"]
            if not isinstance(profile, str) or not profile or len(profile) > 128:
                raise ValueError("expected_profile must be a bounded profile token")
            payload["targetProfile"] = profile
        if payload["encoding"] == "dxil":
            payload["capturedDxilEvidence"] = _shader_restore_protocol.capture_dxil_evidence(
                record.get("capturedDxilAccessSignature"),
                record.get("capturedDxilLayoutEvidence"), _dxil_access_protocol)
        record["restoreValidationReceipt"] = _shader_restore_receipt_store.seal(payload)
    except Exception as exc:
        # The already completed GPU/UI transaction must not become a reported
        # failure merely because its optional future-reuse proof cannot persist.
        record["restoreValidationReceiptError"] = str(exc)[:512]


def _verify_restored_shader_mapping(ctrl, original, target):
    query = getattr(ctrl, "GetTargetShaderReplacement", None)
    if not callable(query):
        return False
    if _resource_id_int(query(original)) != _resource_id_int(target):
        raise RuntimeError("Checked Shader replacement mapping differs from the built target")
    return True


def _apply_shader_candidate_shared_resource_batch(params):
    """One bounded owner transaction; retain independent errors per resource."""
    items = params.get('items')
    if not isinstance(items, list) or not 1 <= len(items) <= 16:
        raise ValueError('Shader restore batch must contain 1..16 items')
    session = str(_capture_session_id or '')
    operations = set()
    for item in items:
        if (not isinstance(item, dict) or item.get('abi_validation_mode') != 'verified-rdc-restore'
                or item.get('expected_capture_session_id') != session):
            raise ValueError('Shader restore batch requires the current signed capture binding')
        operation = _shader_override_hex(item.get('operation_id'), 'operation_id', 32)
        if operation in operations:
            raise ValueError('Duplicate Shader restore batch operation')
        operations.add(operation)
    owner = [0]
    previous = getattr(_request_dispatch_state, 'defer_shader_notifications', False)
    results = []
    def begin(ctrl):
        begin_batch = getattr(ctrl, 'BeginShaderReplacementBatch', None)
        if callable(begin_batch):
            _begin_replay_atomic_transaction()
            owner[0] = int(begin_batch())
    try:
        _replay(begin)
        _request_dispatch_state.defer_shader_notifications = bool(owner[0])
        for item in items:
            try:
                if _capture_session_id != session:
                    raise RuntimeError('Capture changed during Shader restore batch')
                result = _apply_shader_candidate_shared_resource(item)
                results.append({'ok': True, 'result': result})
            except Exception as error:
                results.append({'ok': False, 'error': str(error)[:2048],
                                'operationId': item['operation_id']})
    finally:
        _request_dispatch_state.defer_shader_notifications = previous
        if owner[0] and _capture_session_id == session:
            ended = _replay(lambda ctrl: ctrl.EndShaderReplacementBatch(owner[0]))
            if not ended:
                raise RuntimeError('Shader restore batch ownership changed before final replay')
        if owner[0]:
            _notify_shader_replay_changed()
    return {'items': results, 'captureSessionId': session, 'replayCoalesced': bool(owner[0])}


def _apply_shader_candidate_shared_resource(params):
    """Replace one captured Shader ResourceId for every use in the capture.

    This is the sharing-preserving counterpart to event-scoped overrides.  It
    owns exactly one generated target per original captured ResourceId and
    keeps the captured/original Shader alive for the whole capture lifecycle.
    """
    global _shared_shader_replacements, _shared_shader_orphan_targets
    global _shared_shader_replacement_capture_token

    apply_started = time.monotonic()
    timings = {}
    abi_validation_mode = str(params.get("abi_validation_mode", "") or "").strip().lower()
    manual_fast = abi_validation_mode == "manual-fast"
    expected_session = ""
    if manual_fast or "expected_capture_session_id" in params:
        expected_session = _shader_override_hex(
            params.get("expected_capture_session_id"), "expected_capture_session_id", 32)
        if expected_session != _capture_session_id or not _request_capture_loaded():
            raise RuntimeError("Shader apply capture session changed")
    manual_source_sha256 = (_shader_override_hex(
        params.get("expected_source_sha256"), "expected_source_sha256", 64)
        if manual_fast and params.get("expected_source_sha256") else "")
    restore_payload = None
    restored_dxil_evidence = None
    if params.get("abi_validation_mode") in ("verified-rdc-restore", "verified-shader-pair"):
        restore_payload = _verified_shader_restore_request(params)
        if restore_payload["encoding"] == "dxil":
            restored_dxil_evidence = _shader_restore_protocol.restore_dxil_evidence(
                restore_payload.get("capturedDxilEvidence"), _dxil_access_protocol)
    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    requested_operation_id = str(
        params.get("operation_id", params.get("operationId", "")) or ""
    ).strip().lower()
    operation_id = (
        _shader_override_hex(requested_operation_id, "operation_id", 32)
        if requested_operation_id else uuid.uuid4().hex
    )
    capture_token = _current_capture_token()
    if (_shared_shader_replacement_capture_token is not None and
            _shared_shader_replacement_capture_token != capture_token):
        _forget_shared_shader_replacements()

    candidate_path, candidate_bytes, candidate_sha256 = _read_shader_candidate(params)
    encoding_name = str(params.get("encoding", "dxbc") or "dxbc").strip().lower()
    encoding_attribute = {
        "dxbc": "DXBC",
        "dxil": "DXIL",
        "spirv": "SPIRV",
        "opengl-spirv": "OpenGLSPIRV",
        "glsl": "GLSL",
    }.get(encoding_name)
    if encoding_attribute is None:
        raise ValueError(
            "Shared Shader replacement accepts DXBC, DXIL, Vulkan SPIR-V, OpenGL SPIR-V or GLSL")
    requested_stage = _normalise_stage_name(params.get("stage", ""))
    stage_map = dict(_available_shader_stages([requested_stage]))
    stage = stage_map.get(requested_stage)
    if stage is None or requested_stage not in (
            "vertex", "hull", "domain", "geometry", "fragment", "compute",
            "task", "mesh"):
        raise ValueError("Unsupported replay pipeline shader stage: %s" % requested_stage)
    entry_point = str(params.get("entry_point", "") or "").strip()
    if not entry_point:
        raise ValueError("entry_point is required")
    workspace_id = _shader_override_hex(params.get("workspace_id"), "workspace_id", 32)
    revision = _safe_int(params.get("revision"), 0)
    if revision <= 0:
        raise ValueError("revision must be a positive integer")
    request_id = ("" if manual_fast else _shader_override_hex(
        params.get("abi_request_id"), "abi_request_id", 64))
    report_sha256 = ("" if manual_fast else _shader_override_hex(
        params.get("abi_report_sha256"), "abi_report_sha256", 64))
    lease_request_id = request_id
    lease_report_sha256 = report_sha256
    lease_candidate_sha256 = candidate_sha256
    lease_revision = revision
    if manual_fast:
        lease_request_id = lease_report_sha256 = lease_candidate_sha256 = None
        lease_revision = None
    expected_physical_abi_sha256 = ""
    if abi_validation_mode and restore_payload is None and not manual_fast:
        if abi_validation_mode != "inline-physical-with-initial-lease":
            raise ValueError("Unsupported shared Shader ABI validation mode")
        lease_request_id = _shader_override_hex(
            params.get("abi_lease_request_id"), "abi_lease_request_id", 64)
        lease_report_sha256 = report_sha256
        lease_candidate_sha256 = _shader_override_hex(
            params.get("abi_lease_candidate_sha256"),
            "abi_lease_candidate_sha256", 64)
        lease_revision = _safe_int(params.get("abi_lease_revision"), 0)
        if lease_revision <= 0 or lease_revision >= revision:
            raise ValueError(
                "abi_lease_revision must precede the current revision")
        expected_physical_abi_sha256 = _shader_override_hex(
            params.get("expected_physical_abi_sha256"),
            "expected_physical_abi_sha256", 64)
    events = _shader_override_events(params)
    if len(events) != 1:
        raise ValueError("A shared Shader replacement requires one live anchor event")
    event = events[0]
    restored_original_resource_id = None
    if restore_payload is not None and not (
            abi_validation_mode == "verified-shader-pair" and
            params.get("use_current_anchor_resource") is True):
        # Historical restore IDs need one rebound query. A current inventory
        # anchor can skip that replay; the final mutation callback still checks
        # its actual pipeline binding and captured-original bytes before build.
        restored_original_resource_id = event["expectedOriginalResourceId"]
        resource_hint = _invoke_on_ui_sync(
            lambda: _context_resource_ids().get(restored_original_resource_id))
        def _current_original(ctrl):
            immutable = _verified_restore_original(
                ctrl, resource_hint, event, requested_stage, entry_point, restore_payload)
            if immutable is not None:
                return _resource_id_int(immutable["originalResource"])
            _set_frame_event(ctrl, event["eventId"], True)
            return _resource_id_int(ctrl.GetPipelineState().GetShader(stage))
        current_resource_id = _replay(_current_original)
        if not current_resource_id:
            raise RuntimeError("Shader restore anchor has no current Shader resource")
        event["expectedOriginalResourceId"] = current_resource_id
    original_resource_id = event["expectedOriginalResourceId"]
    if any(
            record.get("expectedOriginalResourceId") == original_resource_id
            for record in _event_shader_overrides.values()):
        raise RuntimeError(
            "The captured Shader has event-scoped overrides; roll them back "
            "before applying a resource-scoped replacement")

    encoding = getattr(rd.ShaderEncoding, encoding_attribute, None)
    if encoding is None:
        raise RuntimeError(
            "This RenderDoc build does not expose ShaderEncoding.%s" %
            encoding_attribute)
    existing = _shared_shader_replacements.get(original_resource_id)
    if existing is not None and existing.get("postApplyValidationFailed") is True:
        # Failed validation is an explicit recovery owner, never an idempotent
        # success or a source of a newly signed persistent ABI receipt.
        _shared_shader_replacement_response(existing)
    previous_operation = _shared_shader_operation_outcomes.get(operation_id)
    if previous_operation is not None:
        if any((
                previous_operation.get("captureId") != capture_id,
                previous_operation.get("captureSessionId") != _capture_session_id,
                previous_operation.get("captureToken") != capture_token,
                previous_operation.get("workspaceId") != workspace_id,
                previous_operation.get("originalResourceId") != original_resource_id,
                previous_operation.get("candidateRawSha256") != candidate_sha256)):
            raise RuntimeError(
                "Shared Shader operation token was reused for another binding")
        prior_replacement = None
        for candidate in _shared_shader_replacements.values():
            if (candidate.get("replacementId") ==
                    previous_operation.get("replacementId")):
                prior_replacement = candidate
                break
        if prior_replacement is not None:
            return _shared_shader_replacement_response(
                prior_replacement,
                idempotent=True,
                operation_id=operation_id,
                operation_created_replacement=False,
                verified_restore_receipt=(prior_replacement.get("restoreValidationReceipt")
                                          if restore_payload is not None else None),
                verified_restore_mode=abi_validation_mode)
        raise RuntimeError(
            "Shared Shader operation token already completed without its exact active replacement")
    if (existing is None and
            len(_shared_shader_replacements) >= MAX_SHARED_SHADER_REPLACEMENTS):
        raise RuntimeError(
            "The active capture reached the %d shared Shader replacement limit" %
            MAX_SHARED_SHADER_REPLACEMENTS)
    if any(
            record.get("workspaceId") == workspace_id and
            record.get("expectedOriginalResourceId") != original_resource_id
            for record in _shared_shader_replacements.values()):
        raise RuntimeError(
            "The workspace already owns a different captured Shader ResourceId")
    handoff = params.get("expected_owner")
    if handoff is not None:
        fields = {"replacementId", "workspaceId", "captureId", "captureSessionId",
                  "candidateRawSha256", "revision"}
        if not isinstance(handoff, dict) or set(handoff) != fields:
            raise ValueError("expected_owner must bind the exact previous Shader replacement")
        if (existing is None or any(existing.get(key) != handoff[key] for key in fields)
                or handoff["workspaceId"] == workspace_id
                or handoff["captureSessionId"] != _capture_session_id
                or existing.get("captureToken") != capture_token):
            raise RuntimeError("Shared Shader handoff owner changed before replacement")
        _require_capture_identity(handoff["captureId"])
        if abi_validation_mode and restore_payload is None and not manual_fast:
            raise RuntimeError("Shared Shader handoff requires a full candidate ABI proof")
    if (existing is not None and
            existing.get("workspaceId") != workspace_id and handoff is None):
        raise RuntimeError(
            "The captured Shader is owned by a different workspace; explicit "
            "replacement handoff is not supported")
    if abi_validation_mode and restore_payload is None and not manual_fast:
        if existing is None:
            raise RuntimeError(
                "An inline ABI lease requires an active fully validated replacement")
        if any((
                existing.get("abiLeaseRequestId") != lease_request_id,
                existing.get("abiLeaseReportSha256") != lease_report_sha256,
                existing.get("abiLeaseCandidateRawSha256") !=
                lease_candidate_sha256,
                existing.get("abiLeaseRevision") != lease_revision,
                existing.get("physicalAbiSha256") !=
                expected_physical_abi_sha256)):
            raise RuntimeError(
                "The inline ABI lease does not match the active replacement")
    original_resource = (
        existing.get("originalResource") if existing is not None else
        _invoke_on_ui_sync(
            lambda: _context_resource_ids().get(original_resource_id)))
    if original_resource is None:
        raise RuntimeError(
            "The captured Shader ResourceId is unavailable in qrenderdoc")
    _require_shared_shader_ui_owner(original_resource, existing)
    try:
        original_event = _request_visible_event_id(0)
    except Exception:
        original_event = 0

    def _do(ctrl):
        new_target = None
        replacement_attempted = False
        replacement_committed = False
        target_cache_hit = False
        anchor_replayed = not manual_fast
        try:
            if expected_session and (_capture_session_id != expected_session or
                    _current_capture_token() != capture_token):
                raise RuntimeError("Shader apply capture session changed before replay mutation")
            if manual_fast and (_capture_session_id != expected_session or
                    _current_capture_token() != capture_token or
                    _shared_shader_replacements.get(original_resource_id) is not existing):
                raise RuntimeError("Manual Shader edit owner or capture changed before replay mutation")
            if handoff is not None and (
                    _shared_shader_replacements.get(original_resource_id) is not existing or
                    any(existing.get(key) != value for key, value in handoff.items()) or
                    _shared_shader_replacement_capture_token != capture_token):
                raise RuntimeError("Shared Shader handoff owner changed before replay mutation")
            api_token = _shader_api_token(ctrl)
            if restore_payload is not None and api_token != restore_payload.get("api"):
                raise RuntimeError("Shader restore replay API changed")
            if api_token == "d3d11":
                if encoding_name != "dxbc" or requested_stage in ("task", "mesh"):
                    raise RuntimeError(
                        "D3D11 shared replacement requires DXBC and a D3D11 shader stage")
            elif api_token == "d3d12":
                if encoding_name not in ("dxbc", "dxil"):
                    raise RuntimeError(
                        "D3D12 shared replacement requires native DXBC or DXIL")
                # D3D12 accepts native DXBC and DXIL. The checked mutation below is mandatory:
                # it prebuilds every captured PSO with its original root signature.
                if not callable(getattr(ctrl, "ReplaceTargetShaderChecked", None)):
                    raise RuntimeError(
                        "This RenderDoc build lacks checked D3D12 Shader replacement")
            elif api_token == "vulkan":
                if encoding_name != "spirv":
                    raise RuntimeError(
                        "Vulkan shared replacement requires native Vulkan SPIR-V")
                if not callable(getattr(ctrl, "ReplaceTargetShaderChecked", None)):
                    raise RuntimeError(
                        "This RenderDoc build lacks checked Vulkan Shader replacement")
            elif api_token == "opengl":
                if (encoding_name not in ("opengl-spirv", "glsl") or
                        requested_stage in ("task", "mesh") or
                        (encoding_name == "glsl" and entry_point != "main")):
                    raise RuntimeError(
                        "OpenGL shared replacement requires GLSL main or OpenGL SPIR-V and a legacy pipeline stage")
                if not callable(getattr(ctrl, "ReplaceTargetShaderChecked", None)):
                    raise RuntimeError(
                        "This RenderDoc build lacks checked OpenGL Shader replacement")
            else:
                raise RuntimeError(
                    "Shared Shader replacements support D3D11/D3D12/Vulkan/OpenGL only")
            if encoding not in list(ctrl.GetTargetShaderEncodings()):
                raise RuntimeError(
                    "%s target shaders are unsupported by this replay" %
                    encoding_name.upper())

            identity_started = time.monotonic()
            if manual_fast:
                live = _manual_shared_shader_original(
                    ctrl, original_resource, event, requested_stage, entry_point, existing)
            else:
                live = _verified_restore_original(
                    ctrl, original_resource, event, requested_stage, entry_point, restore_payload, existing)
                if live is not None:
                    anchor_replayed = False
                else:
                    live = _validate_live_shader_event(
                        ctrl, event, stage, requested_stage, entry_point,
                        require_d3d11_state=(api_token == "d3d11"),
                        owned_shared_replacement=existing,
                        verified_physical_abi_sha256=(restore_payload["physicalAbiSha256"]
                                                     if restore_payload is not None else ""))
            timings["originalIdentity"] = (time.monotonic() - identity_started) * 1000
            if restored_dxil_evidence is not None:
                live["dxilAccessSignature"], live["dxilLayoutEvidence"] = restored_dxil_evidence
            abi_sha256 = live["physicalAbiSha256"]
            if (abi_validation_mode and restore_payload is None and not manual_fast and
                    abi_sha256 != expected_physical_abi_sha256):
                raise RuntimeError(
                    "The live captured Shader ABI no longer matches the initial lease")
            family_id = _shader_family_id(
                _capture_session_id, requested_stage, entry_point,
                original_resource_id, event["expectedOriginalSha256"],
                candidate_sha256, abi_sha256)
            exact = bool(
                existing is not None and
                (manual_fast or existing.get("abiValidationMode") != "manual-fast") and
                existing.get("familyId") == family_id and
                existing.get("workspaceId") == workspace_id and
                existing.get("revision") == revision and
                existing.get("abiRequestId") == request_id and
                existing.get("abiReportSha256") == report_sha256)
            metadata_only = bool(
                existing is not None and
                (manual_fast or existing.get("abiValidationMode") != "manual-fast") and
                existing.get("familyId") == family_id and not exact and handoff is None)
            if exact or metadata_only:
                return {
                    "mode": "idempotent" if exact else "metadata",
                    "live": live,
                    "familyId": family_id,
                    "physicalAbiSha256": abi_sha256,
                    "api": api_token,
                }

            build_started = time.monotonic()
            if manual_fast:
                cache_key = (capture_token, api_token, encoding_name, original_resource_id,
                             event["expectedOriginalSha256"], requested_stage,
                             entry_point, candidate_sha256)
                new_target = _take_manual_shader_target(cache_key)
                target_cache_hit = new_target is not None
            if new_target is None:
                new_target, messages = _build_target_shader(
                    ctrl,
                    entry_point, encoding, candidate_bytes,
                    rd.ShaderCompileFlags(), stage)
            else:
                messages = ""
            timings["buildTarget"] = (time.monotonic() - build_started) * 1000
            if not _resource_id_int(new_target):
                raise RuntimeError(
                    "BuildTargetShader failed: %s" % str(messages or ""))
            # GLSL receipts seal source, not machine code. A new driver build
            # must still reflect that exact source and validate the resulting
            # interface, even when a prior source/ABI pair was authenticated.
            reflect_target = not manual_fast and (restore_payload is None or encoding_name == "glsl")
            target_entries = list(ctrl.GetShaderEntryPoints(new_target) or []) if reflect_target else []
            target_entry = _exact_shader_entry(
                target_entries, entry_point, requested_stage)
            if target_entry is None and reflect_target:
                raise RuntimeError(
                    "The target shader has no unique requested entry point/stage")
            target_reflection = (ctrl.GetShader(rd.ResourceId(), new_target, target_entry)
                                 if reflect_target else None)
            target_raw = (
                _shader_raw_bytes(target_reflection) if target_reflection else b"")
            if reflect_target and (not target_reflection or
                    hashlib.sha256(target_raw).hexdigest() != candidate_sha256 or
                    (encoding_name == "glsl" and _shader_encoding_token(
                        getattr(target_reflection, "encoding", "")) != "glsl")):
                raise RuntimeError(
                    "The built target shader does not match candidate bytes")
            if manual_fast:
                # The user chose direct editing. Driver compilation/pipeline
                # creation is required, but candidate ABI validation is not.
                interface_compatible = True
            elif restore_payload is not None and encoding_name != "glsl":
                interface_compatible = True  # Exact native bytes were fully validated before sealing.
            elif encoding_name == "dxil":
                interface_compatible = _dxil_ambiguous_interface_compatible(
                    ctrl, live["pipelineResource"],
                    live["reflection"], target_reflection,
                    baseline_access=live.get("dxilAccessSignature"),
                    baseline_layout_evidence=live.get("dxilLayoutEvidence"))
            else:
                interface_compatible = _physical_shader_interfaces_compatible(
                    live["reflection"], target_reflection)
            if not interface_compatible:
                raise RuntimeError(
                    "The candidate physical ABI differs from the original Shader")

            # Validation and mutation are adjacent on the replay thread. The
            # replacement key is always the captured original ResourceId.
            replacement_attempted = True
            replace_started = time.monotonic()
            _replace_shared_shader_resource(
                ctrl, api_token, live["originalResource"], new_target)
            timings["replaceResource"] = (time.monotonic() - replace_started) * 1000
            replacement_committed = True
            post_apply_anchor_verified = False
            post_apply_mapping_verified = False
            if (restore_payload is not None and abi_validation_mode == "verified-rdc-restore"
                    and params.get("verify_replacement_mapping") is True
                    and api_token in ("vulkan", "opengl")):
                # The signed same-RDC proof authenticates the original/candidate
                # interface. Checked driver creation has just rebuilt affected
                # pipelines. Confirm the actual controller mapping here instead
                # of replaying the entire frame once per restored stage.
                post_apply_mapping_verified = _verify_restored_shader_mapping(
                    ctrl, live["originalResource"], new_target)
            if not manual_fast and api_token in ("vulkan", "opengl") and not post_apply_mapping_verified:
                pending_owner = {
                    "expectedOriginalResourceId": original_resource_id,
                    "expectedOriginalSha256": event["expectedOriginalSha256"],
                    "stageName": requested_stage,
                    "entryPoint": entry_point,
                    "candidateRawSha256": candidate_sha256,
                    "physicalAbiSha256": abi_sha256,
                    "capturedOriginalReflection": live["reflection"],
                    "capturedDxilAccessSignature": live.get(
                        "dxilAccessSignature"),
                    "capturedDxilLayoutEvidence": live.get(
                        "dxilLayoutEvidence"),
                }
                _validate_live_shader_event(
                    ctrl, event, stage, requested_stage, entry_point,
                    require_d3d11_state=False,
                    owned_shared_replacement=pending_owner,
                    verified_physical_abi_sha256=(restore_payload["physicalAbiSha256"]
                                                 if restore_payload is not None else ""),
                    # Same atomic replay callback: the checked replacement
                    # already refreshed this selected anchor. Inspect its new
                    # binding without rendering that event a second time.
                    event_already_selected=anchor_replayed)
                post_apply_anchor_verified = True
            return {
                "mode": "replaced",
                "live": live,
                "newTarget": new_target,
                "familyId": family_id,
                "physicalAbiSha256": abi_sha256,
                "api": api_token,
                "postApplyAnchorVerified": post_apply_anchor_verified,
                "postApplyMappingVerified": post_apply_mapping_verified,
                "targetCacheHit": target_cache_hit,
            }
        except BaseException as mutation_error:
            # Checked mutations fail atomically. If their call failed, the old
            # owner is already intact and must not be replaced a second time.
            if replacement_attempted and (replacement_committed or api_token == "d3d11"):
                try:
                    if existing is not None:
                        _replace_shared_shader_resource(
                            ctrl, existing.get("api", "d3d11"),
                            existing["originalResource"], existing["targetResource"])
                    else:
                        _remove_shared_shader_resource(
                            ctrl, api_token, live["originalResource"])
                except Exception as restore_error:
                    if replacement_committed:
                        # The checked rollback kept the new owner. Publish it
                        # through the existing UI/bookkeeping recovery path,
                        # without a success receipt. Neither immediate cleanup
                        # nor the orphan sweep may free this still-bound target.
                        return {
                            "mode": "replaced", "live": live, "newTarget": new_target,
                            "familyId": family_id, "physicalAbiSha256": abi_sha256,
                            "api": api_token, "postApplyAnchorVerified": False,
                            "postApplyValidationFailed": True,
                            "recoveryWarning": "Post-apply validation failed: %s; checked replay rollback failed: %s"
                                               % (mutation_error, restore_error),
                        }
            if new_target is not None and _resource_id_int(new_target):
                try:
                    ctrl.FreeTargetResource(new_target)
                except Exception:
                    _register_orphan_shader_target(new_target)
            raise
        finally:
            if original_event > 0 and anchor_replayed:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass

    outcome = _replay(_do)
    mode = outcome["mode"]
    live = outcome["live"]
    if mode in ("idempotent", "metadata"):
        if existing is None:
            raise RuntimeError("Shared Shader replacement bookkeeping is unavailable")
        # Even a no-op/metadata refresh proves that the GUI still points at
        # this bridge-owned target; otherwise it could falsely claim success
        # over a stock Shader Editor replacement.
        _require_shared_shader_ui_owner(
            existing["originalResource"], existing)
        if mode == "metadata":
            existing.update({
                "captureId": capture_id,
                "workspaceId": workspace_id,
                "revision": revision,
                "anchorEventId": event["eventId"],
                "abiRequestId": request_id,
                "abiReportSha256": report_sha256,
                "candidatePath": candidate_path,
                "abiValidationMode": (
                    abi_validation_mode or
                    "full-replay-report-and-inline-physical"),
                "preliminaryReflectionSkipped": bool(abi_validation_mode),
                "freshPhysicalAbiValidationPerformed": not manual_fast and restore_payload is None,
                # A new full report may renew the lease while reusing exactly
                # the same target bytes (e.g. the singleton Host's first save).
                # Inline metadata refreshes retain the already checked lease.
                # Keep this receipt and the Host's next-save binding identical.
                "abiLeaseRequestId": lease_request_id,
                "abiLeaseReportSha256": lease_report_sha256,
                "abiLeaseCandidateRawSha256": lease_candidate_sha256,
                "abiLeaseRevision": lease_revision,
            })
            if manual_fast:
                existing["postApplyAnchorVerified"] = False
                existing["targetCacheHit"] = False
                existing["sourceSha256"] = manual_source_sha256
                existing["targetProfile"] = params.get("expected_profile")
            _advance_shared_shader_mutation_epoch()
        _shared_shader_replacement_capture_token = capture_token
        _attach_shader_restore_receipt(existing, params, restore_payload)
        if restored_original_resource_id is not None:
            existing["restoredOriginalResourceId"] = restored_original_resource_id
        _remember_shared_shader_operation(existing, operation_id, False)
        timings["total"] = (time.monotonic() - apply_started) * 1000
        existing["timingsMs"] = timings
        return _shared_shader_replacement_response(
            existing, idempotent=(mode == "idempotent"),
            metadata_only=(mode == "metadata"),
            operation_id=operation_id,
            operation_created_replacement=False,
            verified_restore_receipt=(existing.get("restoreValidationReceipt")
                                      if restore_payload is not None else None),
            verified_restore_mode=abi_validation_mode)

    new_target = outcome["newTarget"]
    original_resource = live["originalResource"]
    replacement_id = uuid.uuid4().hex
    record = {
        "replacementId": replacement_id,
        "operationId": operation_id,
        "captureId": capture_id,
        "captureSessionId": _capture_session_id,
        "captureToken": capture_token,
        "workspaceId": workspace_id,
        "revision": revision,
        "anchorEventId": event["eventId"],
        "stageName": requested_stage,
        "stageObject": stage,
        "entryPoint": entry_point,
        "api": outcome["api"],
        "encoding": encoding_name,
        "expectedOriginalResourceId": original_resource_id,
        "originalResource": original_resource,
        "capturedOriginalReflection": live["reflection"],
        "capturedOriginalPipelineResource": live["pipelineResource"],
        "capturedDxilAccessSignature": live.get("dxilAccessSignature"),
        "capturedDxilLayoutEvidence": live.get("dxilLayoutEvidence"),
        "expectedOriginalSha256": event["expectedOriginalSha256"],
        "candidateRawSha256": candidate_sha256,
        "candidatePath": candidate_path,
        "targetResource": new_target,
        "targetResourceId": _resource_id_int(new_target),
        "familyId": outcome["familyId"],
        "physicalAbiSha256": outcome["physicalAbiSha256"],
        "abiRequestId": request_id,
        "abiReportSha256": report_sha256,
        "abiValidationMode": (
            abi_validation_mode or "full-replay-report-and-inline-physical"),
        "preliminaryReflectionSkipped": bool(abi_validation_mode),
        "freshPhysicalAbiValidationPerformed": not manual_fast and (restore_payload is None or encoding_name == "glsl"),
        "postApplyAnchorVerified": bool(
            outcome.get("postApplyAnchorVerified", False)),
        "postApplyMappingVerified": outcome.get("postApplyMappingVerified") is True,
        "abiLeaseRequestId": lease_request_id,
        "abiLeaseReportSha256": lease_report_sha256,
        "abiLeaseCandidateRawSha256": lease_candidate_sha256,
        "abiLeaseRevision": lease_revision,
        "uiSynchronized": True,
        "targetCacheHit": bool(outcome.get("targetCacheHit", False)),
    }
    if manual_fast:
        record["sourceSha256"] = manual_source_sha256
        record["targetProfile"] = params.get("expected_profile")
    if outcome.get("postApplyValidationFailed") is True:
        record["postApplyValidationFailed"] = True
        record["recoveryWarning"] = outcome["recoveryWarning"]

    ui_started = time.monotonic()
    try:
        if manual_fast:
            # Native RegisterReplacement retires the previous reverse edge.
            # Avoid an intermediate unregister/cache refresh during live edits.
            _set_shared_shader_ui_owner(original_resource, new_target, replace_direct=True)
        else:
            _set_shared_shader_ui_owner(original_resource, new_target)
    except Exception as register_exc:
        # Keep replay and GUI replacement registries in lock-step. Restore the
        # exact previous replay owner first, and do not free the new target
        # until both replay and GUI have been *verified* at that old state.
        def _restore(ctrl):
            if existing is not None:
                _replace_shared_shader_resource(
                    ctrl, existing.get("api", "d3d11"),
                    existing["originalResource"], existing["targetResource"])
            else:
                _remove_shared_shader_resource(ctrl, outcome["api"], original_resource)

        restore_error = None
        try:
            _replay(_restore)
        except Exception as exc:
            restore_error = exc

        if restore_error is None:
            expected_ui_target = (
                existing["targetResource"] if existing is not None else None)
            try:
                _set_shared_shader_ui_owner(
                    original_resource, expected_ui_target)
            except Exception as ui_restore_exc:
                # The replay is back at the old state, but the UI could not be
                # proven there. Try to converge on the known live new target;
                # checked D3D12 replacement either succeeds wholly or keeps the
                # previous replay owner unchanged.
                replay_reapply_error = None
                try:
                    _replay(lambda ctrl: _replace_shared_shader_resource(
                        ctrl, outcome["api"], original_resource, new_target))
                except Exception as exc:
                    replay_reapply_error = exc

                if replay_reapply_error is None:
                    ui_reapply_error = None
                    try:
                        _set_shared_shader_ui_owner(
                            original_resource, new_target)
                    except Exception as exc:
                        ui_reapply_error = exc
                    record["uiSynchronized"] = ui_reapply_error is None
                    record["recoveryWarning"] = (
                        "qrenderdoc registration failed: %s; restoring the old UI owner "
                        "failed: %s%s" % (
                            str(register_exc), str(ui_restore_exc),
                            ("; re-registering the active target failed: %s" %
                             str(ui_reapply_error)) if ui_reapply_error else ""))
                    _shared_shader_replacements[original_resource_id] = record
                    _shared_shader_replacement_capture_token = capture_token
                    _advance_shared_shader_mutation_epoch()
                    _remember_shared_shader_operation(
                        record, operation_id, True)
                    if existing is not None and record["uiSynchronized"]:
                        try:
                            _replay(lambda ctrl: ctrl.FreeTargetResource(
                                existing["targetResource"]))
                        except Exception:
                            _register_orphan_shader_target(
                                existing["targetResource"])
                    raise RuntimeError(
                        "%s. The new replay replacement remains active and tracked as %s; "
                        "it was not freed. Retry shared-resource rollback with that ID."
                        % (record["recoveryWarning"], replacement_id))

                # Replay is still at the verified prior owner. The new target
                # may nevertheless be referenced by a damaged UI registry, so
                # retain it for lifecycle cleanup instead of freeing it.
                _register_orphan_shader_target(new_target)
                raise RuntimeError(
                    "qrenderdoc registration failed: %s. Replay was restored, but the UI "
                    "owner could not be restored (%s) and re-applying the new target failed "
                    "(%s); the new target was retained, not freed."
                    % (str(register_exc), str(ui_restore_exc),
                       str(replay_reapply_error)))

            free_error = None
            try:
                _replay(lambda ctrl: ctrl.FreeTargetResource(new_target))
            except Exception as exc:
                free_error = exc
                _register_orphan_shader_target(new_target)
            suffix = (
                " The unused target could not be freed and was retained: %s" %
                str(free_error)) if free_error else ""
            raise RuntimeError(
                "qrenderdoc registration failed: %s. Replay and UI were restored to their "
                "previous owner.%s" % (str(register_exc), suffix))

        # Checked restore failed, so its fail-closed contract means the new
        # target remains the replay owner. Align the UI with that owner, retain
        # explicit bookkeeping, and never free the live target.
        ui_recovery_error = None
        try:
            _set_shared_shader_ui_owner(original_resource, new_target)
        except Exception as exc:
            ui_recovery_error = exc
        record["uiSynchronized"] = ui_recovery_error is None
        record["recoveryWarning"] = (
            "qrenderdoc registration failed: %s; checked replay rollback failed: %s%s"
            % (str(register_exc), str(restore_error),
               ("; UI recovery failed: %s" % str(ui_recovery_error))
               if ui_recovery_error else ""))
        _shared_shader_replacements[original_resource_id] = record
        _shared_shader_replacement_capture_token = capture_token
        _advance_shared_shader_mutation_epoch()
        _remember_shared_shader_operation(record, operation_id, True)
        if existing is not None and record["uiSynchronized"]:
            try:
                _replay(lambda ctrl: ctrl.FreeTargetResource(
                    existing["targetResource"]))
            except Exception:
                _register_orphan_shader_target(existing["targetResource"])
        raise RuntimeError(
            "%s. The new replay replacement remains active and tracked as %s; "
            "it was not freed. Retry shared-resource rollback with that ID."
            % (record["recoveryWarning"], replacement_id))

    _shared_shader_replacements[original_resource_id] = record
    timings["uiRegistration"] = (time.monotonic() - ui_started) * 1000
    _shared_shader_replacement_capture_token = capture_token
    if record.get("postApplyValidationFailed") is not True:
        _attach_shader_restore_receipt(record, params, restore_payload)
    if restored_original_resource_id is not None:
        record["restoredOriginalResourceId"] = restored_original_resource_id
    _advance_shared_shader_mutation_epoch()
    _remember_shared_shader_operation(record, operation_id, True)

    superseded_freed = True
    superseded_id = existing.get("replacementId") if existing else None
    if existing is not None:
        try:
            if manual_fast:
                retained = _replay(lambda ctrl: _retain_manual_shader_target(ctrl, existing))
                if retained:
                    superseded_freed = False
                    record["supersededTargetCached"] = True
                else:
                    _replay(lambda ctrl: ctrl.FreeTargetResource(existing["targetResource"]))
            else:
                _replay(lambda ctrl: ctrl.FreeTargetResource(existing["targetResource"]))
        except Exception:
            superseded_freed = False
            _register_orphan_shader_target(existing["targetResource"])
    if record.get("postApplyValidationFailed") is True:
        raise RuntimeError(
            "%s. The new replay replacement remains active and tracked as %s; "
            "it was not freed. Retry shared-resource rollback with that ID."
            % (record["recoveryWarning"], replacement_id))
    timings["total"] = (time.monotonic() - apply_started) * 1000
    record["timingsMs"] = timings
    return _shared_shader_replacement_response(
        record, operation_id=operation_id,
        operation_created_replacement=True,
        superseded_id=superseded_id,
        superseded_target_freed=superseded_freed)


def _rollback_shader_candidate_shared_resource(params):
    """Remove one owned ResourceId replacement and free only its target."""
    global _shared_shader_replacements, _shared_shader_orphan_targets
    global _shared_shader_replacement_capture_token

    replacement_id = _shader_override_hex(
        params.get("replacement_id"), "replacement_id", 32)
    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_session_id = _shader_rollback_capture_session(params)
    workspace_id = _shader_override_hex(
        params.get("workspace_id"), "workspace_id", 32)
    capture_token = _current_capture_token()
    record = None
    for candidate in _shared_shader_replacements.values():
        if candidate.get("replacementId") == replacement_id:
            record = candidate
            break
    tombstone = _shared_shader_rollback_tombstones.get(replacement_id)
    if record is not None and tombstone is not None:
        raise RuntimeError(
            "Shared Shader rollback bookkeeping contains an active/tombstone collision")
    if record is None and tombstone is not None:
        if (tombstone.get("captureId") != capture_id or
                tombstone.get("workspaceId") != workspace_id):
            raise RuntimeError(
                "The shared Shader rollback receipt belongs to a different workspace")
        if (tombstone.get("captureSessionId") != capture_session_id or
                tombstone.get("captureToken") != capture_token):
            _forget_shared_shader_replacements()
            raise RuntimeError(
                "The shared Shader rollback receipt belongs to a different lifecycle")
        return _shared_shader_rollback_receipt(tombstone["receipt"], True)
    if record is None:
        raise ValueError("Unknown or expired shared Shader replacement ID")
    if any((
            record.get("captureId") != capture_id,
            record.get("captureSessionId") != capture_session_id,
            record.get("workspaceId") != workspace_id,
            record.get("captureToken") != capture_token,
            _shared_shader_replacement_capture_token != capture_token)):
        if record.get("captureToken") != capture_token:
            _forget_shared_shader_replacements()
        raise RuntimeError(
            "The shared Shader replacement belongs to a different lifecycle or workspace")

    original_resource = record["originalResource"]
    target_resource = record["targetResource"]
    _require_shared_shader_ui_owner(original_resource, record)
    try:
        _replay(lambda ctrl: _remove_shared_shader_resource(
            ctrl, record.get("api", "d3d11"), original_resource))
    except Exception:
        try:
            _replay(lambda ctrl: _replace_shared_shader_resource(
                ctrl, record.get("api", "d3d11"), original_resource, target_resource))
        except Exception:
            pass
        raise
    try:
        _set_shared_shader_ui_owner(original_resource, None)
    except Exception:
        # Restore both registries so the caller can retry with the same token.
        try:
            _replay(lambda ctrl: _replace_shared_shader_resource(
                ctrl, record.get("api", "d3d11"), original_resource, target_resource))
        except Exception:
            pass
        try:
            _set_shared_shader_ui_owner(original_resource, target_resource)
        except Exception:
            pass
        raise

    target_freed = True
    free_warning = ""
    try:
        _replay(lambda ctrl: ctrl.FreeTargetResource(target_resource))
    except Exception as exc:
        target_freed = False
        free_warning = str(exc)
        _register_orphan_shader_target(target_resource)
    _shared_shader_replacements.pop(record["expectedOriginalResourceId"], None)
    _advance_shared_shader_mutation_epoch()
    if (not _shared_shader_replacements and not _shared_shader_orphan_targets and
            not _shared_shader_manual_target_cache):
        _shared_shader_replacement_capture_token = None
    result = {
        "schema": "renderdoc-ultra-shared-shader-replacement/v1",
        "schemaVersion": 1,
        "replacementId": replacement_id,
        "operationId": str(record.get("operationId", "") or ""),
        "captureId": capture_id,
        "captureSessionId": _capture_session_id,
        "workspaceId": workspace_id,
        "api": record.get("api", "d3d11"),
        "encoding": record.get("encoding", "dxbc"),
        "stage": record["stageName"],
        "entryPoint": record["entryPoint"],
        "originalResourceId": record["expectedOriginalResourceId"],
        "originalRawSha256": record["expectedOriginalSha256"],
        "candidateRawSha256": record["candidateRawSha256"],
        "physicalAbiSha256": record["physicalAbiSha256"],
        "shaderFamilyId": record["familyId"],
        "targetResourceId": record["targetResourceId"],
        "resourceScoped": True,
        "eventScoped": False,
        "cleared": True,
        "targetFreed": target_freed,
        "originalShaderPreserved": True,
        "freeWarning": free_warning,
        "alreadyRestored": False,
        "idempotentRollback": False,
    }
    if record.get("abiValidationMode") == "manual-fast":
        result.update({
            "abiValidationMode": "manual-fast", "manualEdit": True,
            "validationScope": "manual-edit-unvalidated", "replayAbiValidated": False,
        })
    _remember_shared_shader_rollback_receipt(result, capture_token)
    return result


def _recover_shader_candidate_shared_resource_operation(params):
    """Resolve one uncertain apply by caller operation token, never by guess."""
    operation_id = _shader_override_hex(
        params.get("operation_id", params.get("operationId")),
        "operation_id", 32)
    capture_id = _shader_override_hex(params.get("expected_capture_id"), "expected_capture_id", 64)
    capture_session_id = _shader_rollback_capture_session(params)
    workspace_id = _shader_override_hex(
        params.get("workspace_id"), "workspace_id", 32)
    capture_token = _current_capture_token()
    outcome = _shared_shader_operation_outcomes.get(operation_id)
    if outcome is not None or capture_id in _known_catalog_capture_ids:
        _require_capture_identity(capture_id)
    elif (not _request_capture_loaded() or capture_token is None or
          params.get("expected_capture_session_id") != capture_session_id):
        raise RuntimeError("Unknown Shader restore operation needs the exact active capture session")
    base = {
        "schema": "renderdoc-ultra-shared-shader-operation-recovery/v1",
        "schemaVersion": 1,
        "operationId": operation_id,
        "captureId": capture_id,
        "captureSessionId": capture_session_id,
        "workspaceId": workspace_id,
        "originalShaderPreserved": True,
        "strictReceipt": True,
    }
    if outcome is None:
        base.update({
            "status": "absent",
            "operationKnown": False,
            "operationCreatedReplacement": False,
            "replacementId": "",
            "mutationPresent": False,
            "recovered": True,
            "rollback": None,
        })
        return base
    if any((
            outcome.get("captureId") != capture_id,
            outcome.get("captureSessionId") != capture_session_id,
            outcome.get("captureToken") != capture_token,
            outcome.get("workspaceId") != workspace_id)):
        raise RuntimeError(
            "Shared Shader operation recovery belongs to another lifecycle or workspace")
    replacement_id = str(outcome.get("replacementId", "") or "")
    created = outcome.get("createdReplacement") is True
    if not created:
        outcome["state"] = "idempotent-noop"
        base.update({
            "status": "idempotent-noop",
            "operationKnown": True,
            "operationCreatedReplacement": False,
            "replacementId": replacement_id,
            "mutationPresent": False,
            "recovered": True,
            "rollback": None,
        })
        return base
    active = None
    for candidate in _shared_shader_replacements.values():
        if candidate.get("replacementId") == replacement_id:
            active = candidate
            break
    if active is None:
        outcome["state"] = "already-recovered"
        base.update({
            "status": "already-recovered",
            "operationKnown": True,
            "operationCreatedReplacement": True,
            "replacementId": replacement_id,
            "mutationPresent": False,
            "recovered": True,
            "rollback": None,
        })
        return base
    rolled_back = _rollback_shader_candidate_shared_resource({
        "replacement_id": replacement_id,
        "expected_capture_id": capture_id,
        "expected_capture_session_id": capture_session_id,
        "workspace_id": workspace_id,
    })
    if (not isinstance(rolled_back, dict) or
            rolled_back.get("replacementId") != replacement_id or
            rolled_back.get("cleared") is not True or
            rolled_back.get("originalShaderPreserved") is not True):
        raise RuntimeError(
            "Shared Shader operation recovery returned invalid rollback evidence")
    outcome["state"] = "recovered"
    base.update({
        "status": "recovered",
        "operationKnown": True,
        "operationCreatedReplacement": True,
        "replacementId": replacement_id,
        "mutationPresent": False,
        "recovered": True,
        "rollback": rolled_back,
    })
    return base


def _get_shared_shader_replacements(params):
    """Return bounded bridge-owned replacement metadata for this lifecycle.

    Candidate paths and pyrenderdoc resource objects are intentionally omitted.
    A newly connected MCP process can therefore restore the current Shader
    without trusting stale host memory or guessing a replacement token.
    """
    include_validation = params.get("include_validation_receipts", False)
    if not isinstance(include_validation, bool):
        raise ValueError("include_validation_receipts must be a boolean")
    lease_only = params.get("lease_metadata_only", False)
    if not isinstance(lease_only, bool):
        raise ValueError("lease_metadata_only must be a boolean")
    query_workspace = (_shader_override_hex(params["workspace_id"], "workspace_id", 32)
                       if "workspace_id" in params else None)
    query_replacement = (_shader_override_hex(params["replacement_id"], "replacement_id", 32)
                         if "replacement_id" in params else None)
    if lease_only and (not query_workspace or not query_replacement or include_validation):
        raise ValueError("Lease metadata requires one exact workspace/replacement and no full receipts")
    include_all_catalogs = params.get("include_all_capture_catalogs", False)
    if not isinstance(include_all_catalogs, bool):
        raise ValueError("include_all_capture_catalogs must be a boolean")
    current_snapshot = not any(key in params for key in (
        "expected_capture_id", "expected_capture_session_id"))
    if current_snapshot:
        # A read-only inventory can describe this exact live instance without
        # first creating a catalog. It grants no identity or apply authority.
        capture_id = ""
        expected_session = str(_capture_session_id or "")
        include_all_catalogs = True
    else:
        capture_id = _shader_override_hex(
            params.get("expected_capture_id"), "expected_capture_id", 64)
        expected_session = _shader_override_hex(
            params.get("expected_capture_session_id"),
            "expected_capture_session_id", 32)
    if not _capture_session_id or expected_session != _capture_session_id:
        raise RuntimeError("Capture session changed before replacement query")
    capture_token = _current_capture_token()
    if not _request_capture_loaded() or capture_token is None:
        raise RuntimeError("No capture loaded")
    catalog_ready = bool(_known_catalog_capture_ids.get(capture_id))
    if include_all_catalogs and not catalog_ready and not current_snapshot:
        raise RuntimeError("All-catalog replacement inventory requires a current catalog identity")
    if catalog_ready:
        _require_capture_identity(capture_id)
    elif any(record.get("captureId") == capture_id
             for record in _shared_shader_replacements.values()):
        raise RuntimeError("Shared Shader replacement lost its catalog identity")
    # An editor may reconnect before project restore has registered its catalog.
    # This read-only absence result grants neither catalog nor apply authority.
    # All mutations still require _require_capture_identity, and an existing
    # mapping can never be concealed by an unregistered catalog.
    if (_shared_shader_replacement_capture_token is not None and
            _shared_shader_replacement_capture_token != capture_token):
        _forget_shared_shader_replacements()

    records = []
    for record in _shared_shader_replacements.values():
        if any((
                query_workspace is not None and record.get("workspaceId") != query_workspace,
                query_replacement is not None and record.get("replacementId") != query_replacement,
                not include_all_catalogs and record.get("captureId") != capture_id,
                record.get("captureSessionId") != expected_session,
                record.get("captureToken") != capture_token)):
            continue
        records.append({
            "replacementId": record["replacementId"],
            "operationId": str(record.get("operationId", "") or ""),
            "workspaceId": record["workspaceId"],
            "revision": record["revision"],
            "anchorEventId": record["anchorEventId"],
            "stage": record["stageName"],
            "entryPoint": record["entryPoint"],
            "api": record["api"],
            "encoding": record["encoding"],
            "originalResourceId": record["expectedOriginalResourceId"],
            "originalRawSha256": record["expectedOriginalSha256"],
            "candidateRawSha256": record["candidateRawSha256"],
            "physicalAbiSha256": record["physicalAbiSha256"],
            "shaderFamilyId": record["familyId"],
            "targetResourceId": record["targetResourceId"],
            "resourceScoped": True,
            "eventScoped": False,
            "allOriginalResourceUsesAffected": True,
            "originalShaderPreserved": True,
            "postApplyValidationFailed": record.get("postApplyValidationFailed") is True,
        })
        if include_all_catalogs:
            # Resource ownership spans catalog projections of this one live
            # capture. Preserve the owner's catalog for an exact rollback;
            # never relabel its receipt as belonging to the querying catalog.
            _require_capture_identity(record["captureId"])
            records[-1]["captureId"] = record["captureId"]
            records[-1]["captureSessionId"] = record["captureSessionId"]
        if record.get("abiValidationMode") == "manual-fast":
            records[-1].update({
                "abiValidationMode": "manual-fast", "manualEdit": True,
                "validationScope": "manual-edit-unvalidated",
                "replayAbiValidated": False, "freshPhysicalValidationPerformed": False,
                "sourceSha256": record.get("sourceSha256", ""),
                "targetProfile": record.get("targetProfile"),
            })
        if include_validation or lease_only:
            # Optional readback of the already performed transaction, never a
            # new ABI check or replacement. Keep physical revisions and signed
            # envelopes intact for final publication by a newly connected Host.
            records[-1].update({
                "schema": "renderdoc-ultra-shared-shader-replacement/v1",
                "schemaVersion": 1,
                "captureId": record["captureId"],
                "captureSessionId": record["captureSessionId"],
            })
            for key in (
                    "abiRequestId", "abiReportSha256", "restoreValidationReceipt",
                    "restoredOriginalResourceId",
                    "restoreValidationReceiptError", "abiValidationMode",
                    "postApplyMappingVerified",
                    "postApplyValidationFailed", "recoveryWarning",
                    "preliminaryReflectionSkipped", "freshPhysicalAbiValidationPerformed",
                    "abiLeaseRequestId", "abiLeaseReportSha256",
                    "abiLeaseCandidateRawSha256", "abiLeaseRevision"):
                if lease_only and key not in (
                        "postApplyValidationFailed", "abiLeaseRequestId", "abiLeaseReportSha256",
                        "abiLeaseCandidateRawSha256", "abiLeaseRevision"):
                    continue
                if key in record:
                    records[-1][key] = json.loads(json.dumps(record[key]))
    records.sort(key=lambda item: (
        item["originalResourceId"], item["stage"], item["replacementId"]))
    return {
        "schema": "renderdoc-ultra-shared-shader-replacement-list/v1",
        "schemaVersion": 1,
        "captureId": capture_id,
        "captureSessionId": expected_session,
        "catalogReady": catalog_ready,
        "replacements": records,
        "count": len(records),
        "mutationEpoch": _shared_shader_mutation_epoch,
        "originalShadersPreserved": True,
        "replayMutation": False,
        "leaseMetadataOnly": lease_only,
        "queryWorkspaceId": query_workspace,
        "queryReplacementId": query_replacement,
    }


def _restore_shader_candidate_shared_resource_exact(params):
    """Linearize exact shared-Shader absence or rollback in one Bridge call.

    The host may have inspected the public replacement inventory while it
    validated a deterministic project workspace.  This method is the final
    bridge-owned compare-and-restore point: if the target ResourceId acquired
    a different owner after that inspection, it fails closed; if the exact
    owner is still active, it rolls that owner back; and if no owner exists it
    publishes an exact absence receipt.  No fuzzy bytecode or host-memory
    lookup participates in the decision.
    """

    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_session_id = _shader_rollback_capture_session(params)
    workspace_id = _shader_override_hex(
        params.get("workspace_id"), "workspace_id", 32)
    capture_token = _current_capture_token()
    if (_shared_shader_replacement_capture_token is not None and
            _shared_shader_replacement_capture_token != capture_token):
        _forget_shared_shader_replacements()

    stage_name = _normalise_stage_name(params.get("stage", ""))
    expected_event_id = _safe_int(params.get("expected_event_id"), 0)
    if expected_event_id <= 0:
        raise ValueError("expected_event_id must be positive")
    entry_point = str(params.get("entry_point", "") or "")
    if not entry_point or len(entry_point) > 512:
        raise ValueError("entry_point must contain 1 to 512 characters")
    original_resource_id = _safe_int(
        params.get("expected_original_resource_id"), 0)
    if original_resource_id <= 0:
        raise ValueError("expected_original_resource_id must be positive")
    original_sha256 = _shader_override_hex(
        params.get("expected_original_sha256"),
        "expected_original_sha256", 64)

    replacement_id_text = str(
        params.get("expected_replacement_id", "") or "").strip().lower()
    replacement_id = (
        _shader_override_hex(
            replacement_id_text, "expected_replacement_id", 32)
        if replacement_id_text else ""
    )
    operation_id_text = str(
        params.get("expected_operation_id", "") or "").strip().lower()
    operation_id = (
        _shader_override_hex(
            operation_id_text, "expected_operation_id", 32)
        if operation_id_text else ""
    )
    expected_revision = _safe_int(params.get("expected_revision"), 0)
    expected_anchor_event_id = _safe_int(
        params.get("expected_anchor_event_id"), 0)
    api_name = str(params.get("expected_api", "") or "").strip().lower()
    encoding_name = str(
        params.get("expected_encoding", "") or "").strip().lower()
    candidate_text = str(
        params.get("expected_candidate_sha256", "") or "").strip().lower()
    physical_abi_text = str(
        params.get("expected_physical_abi_sha256", "") or "").strip().lower()
    family_text = str(
        params.get("expected_shader_family_id", "") or "").strip().lower()
    target_resource_id = _safe_int(
        params.get("expected_target_resource_id"), 0)

    if replacement_id:
        if expected_revision <= 0 or expected_anchor_event_id <= 0:
            raise ValueError(
                "expected_revision and expected_anchor_event_id must be positive")
        if not (
                (api_name == "d3d11" and encoding_name == "dxbc") or
                (api_name == "d3d12" and encoding_name in ("dxbc", "dxil")) or
                (api_name == "vulkan" and encoding_name == "spirv") or
                (api_name == "opengl" and
                 encoding_name in ("opengl-spirv", "glsl"))):
            raise ValueError("expected_api/expected_encoding is unsupported")
        candidate_sha256 = _shader_override_hex(
            candidate_text, "expected_candidate_sha256", 64)
        current_owner = _shared_shader_replacements.get(original_resource_id)
        if (not physical_abi_text and current_owner is not None and
                current_owner.get("replacementId") == replacement_id and
                current_owner.get("abiValidationMode") == "manual-fast" and
                not current_owner.get("physicalAbiSha256")):
            physical_abi_sha256 = ""
        else:
            physical_abi_sha256 = _shader_override_hex(
                physical_abi_text, "expected_physical_abi_sha256", 64)
        family_id = _shader_override_hex(
            family_text, "expected_shader_family_id", 64)
        if target_resource_id <= 0:
            raise ValueError("expected_target_resource_id must be positive")
        if not operation_id:
            raise ValueError(
                "expected_operation_id is required for an active replacement")
    else:
        if any((
                operation_id,
                expected_revision,
                expected_anchor_event_id,
                api_name,
                encoding_name,
                candidate_text,
                physical_abi_text,
                family_text,
                target_resource_id)):
            raise ValueError(
                "active replacement identity fields require expected_replacement_id")
        candidate_sha256 = ""
        physical_abi_sha256 = ""
        family_id = ""

    expected_physical = (
        {
            "replacementId": replacement_id,
            "operationId": operation_id,
            "captureId": capture_id,
            "captureSessionId": capture_session_id,
            "workspaceId": workspace_id,
            "stage": stage_name,
            "entryPoint": entry_point,
            "api": api_name,
            "encoding": encoding_name,
            "originalResourceId": original_resource_id,
            "originalRawSha256": original_sha256,
            "candidateRawSha256": candidate_sha256,
            "physicalAbiSha256": physical_abi_sha256,
            "shaderFamilyId": family_id,
            "targetResourceId": target_resource_id,
        }
        if replacement_id else None
    )

    def _require_exact_rollback_receipt(rollback):
        if not isinstance(rollback, dict):
            raise RuntimeError(
                "Exact shared Shader rollback returned invalid evidence")
        mismatched = [
            name for name, value in expected_physical.items()
            if rollback.get(name) != value
        ]
        if any((
                mismatched,
                rollback.get("resourceScoped") is not True,
                rollback.get("eventScoped") is not False,
                rollback.get("cleared") is not True,
                rollback.get("originalShaderPreserved") is not True)):
            suffix = (
                ": %s" % ", ".join(sorted(mismatched))
                if mismatched else "")
            raise RuntimeError(
                "Exact shared Shader rollback physical evidence mismatch%s" %
                suffix)

    all_records = list(_shared_shader_replacements.values())
    same_resource = [
        record for record in all_records
        if record.get("expectedOriginalResourceId") == original_resource_id
    ]
    if len(same_resource) > 1:
        raise RuntimeError(
            "More than one shared Shader replacement owns the target ResourceId")
    if any(
            record.get("eventId") == expected_event_id and
            record.get("stageName") == stage_name
            for record in _event_shader_overrides.values()):
        raise RuntimeError(
            "An event-scoped Shader override owns the exact current event/stage")

    if not _ctx or _request_visible_event_id(0) != expected_event_id:
        raise RuntimeError(
            "The qrenderdoc current event changed before exact Shader restore")
    stage_map = dict(_available_shader_stages([stage_name]))
    stage_object = stage_map.get(stage_name)
    if stage_object is None:
        raise ValueError("Unsupported Shader stage: %s" % stage_name)
    owned_record = same_resource[0] if same_resource else None

    def _validate_exact_live_binding(ctrl):
        live_api = _shader_api_token(ctrl)
        if live_api not in ("d3d11", "d3d12", "vulkan", "opengl"):
            raise RuntimeError(
                "Exact shared Shader restore supports D3D11/D3D12/Vulkan/OpenGL only")
        restore_event = {
            "eventId": expected_event_id,
            "expectedOriginalResourceId": original_resource_id,
            "expectedOriginalSha256": original_sha256,
        }
        if owned_record is not None and owned_record.get("abiValidationMode") == "manual-fast":
            if _resource_id_int(ctrl.GetPipelineState().GetShader(stage_object)) != original_resource_id:
                raise RuntimeError("The current event bound a different Shader before manual restore")
            live = _manual_shared_shader_original(
                ctrl, owned_record["originalResource"], restore_event,
                stage_name, entry_point, owned_record)
        else:
            live = _validate_live_shader_event(
                ctrl, restore_event, stage_object, stage_name, entry_point,
                require_d3d11_state=(live_api == "d3d11"),
                owned_shared_replacement=owned_record)
        live_encoding = _shader_encoding_token(
            getattr(live.get("reflection"), "encoding", ""))
        if not (
                (live_api == "d3d11" and live_encoding == "dxbc") or
                (live_api == "d3d12" and live_encoding in ("dxbc", "dxil")) or
                (live_api == "vulkan" and live_encoding == "spirv") or
                (live_api == "opengl" and
                 live_encoding in ("opengl-spirv", "glsl"))):
            raise RuntimeError(
                "The exact live Shader API/encoding identity is unsupported")
        return {
            "api": live_api,
            "encoding": live_encoding,
            "physicalAbiSha256": live["physicalAbiSha256"],
            "originalResource": live["originalResource"],
        }

    live_binding = _replay(_validate_exact_live_binding)
    _require_shared_shader_ui_owner(
        live_binding["originalResource"], owned_record)

    base = {
        "schema": "renderdoc-ultra-exact-shared-shader-restore/v1",
        "schemaVersion": 1,
        "captureId": capture_id,
        "captureSessionId": capture_session_id,
        "workspaceId": workspace_id,
        "eventId": expected_event_id,
        "stage": stage_name,
        "entryPoint": entry_point,
        "originalResourceId": original_resource_id,
        "originalRawSha256": original_sha256,
        "api": live_binding["api"],
        "encoding": live_binding["encoding"],
        "physicalAbiSha256": live_binding["physicalAbiSha256"],
        "linearized": True,
        "stateAtLinearizationVerified": True,
        "originalShaderPreserved": True,
    }

    if not same_resource:
        # A tombstone proves that this exact replacement was already restored.
        # Calling the ordinary rollback route validates the same lifecycle and
        # workspace before returning that immutable physical receipt.
        tombstone = (
            _shared_shader_rollback_tombstones.get(replacement_id)
            if replacement_id else None
        )
        if tombstone is not None:
            rollback = _rollback_shader_candidate_shared_resource({
                "replacement_id": replacement_id,
                "expected_capture_id": capture_id,
                "expected_capture_session_id": capture_session_id,
                "workspace_id": workspace_id,
            })
            _require_exact_rollback_receipt(rollback)
            base.update({
                "state": "already-restored",
                "restored": True,
                "alreadyRestored": True,
                "activeReplacementCountForResource": 0,
                "mutationEpoch": _shared_shader_mutation_epoch,
                "rollback": rollback,
            })
            return base
        # Reject a replacement ID that is still active on another resource;
        # accepting it as target absence would hide an identity collision.
        if replacement_id and any(
                record.get("replacementId") == replacement_id
                for record in all_records):
            raise RuntimeError(
                "The expected replacement ID owns another Shader ResourceId")
        if replacement_id:
            raise RuntimeError(
                "The expected shared Shader replacement has no exact active "
                "owner or rollback tombstone")
        base.update({
            "state": "absent",
            "restored": True,
            "alreadyRestored": True,
            "activeReplacementCountForResource": 0,
            "mutationEpoch": _shared_shader_mutation_epoch,
            "rollback": None,
        })
        return base

    record = same_resource[0]
    if not replacement_id:
        raise RuntimeError(
            "A shared Shader replacement appeared for the exact target ResourceId")
    if (
        live_binding["api"] != api_name
        or live_binding["encoding"] != encoding_name
        or live_binding["physicalAbiSha256"] != physical_abi_sha256
    ):
        raise RuntimeError(
            "The exact live Shader physical identity changed before restore")
    expected_record = {
        "replacementId": replacement_id,
        "operationId": operation_id,
        "captureId": capture_id,
        "captureSessionId": capture_session_id,
        "captureToken": capture_token,
        "workspaceId": workspace_id,
        "revision": expected_revision,
        "anchorEventId": expected_anchor_event_id,
        "stageName": stage_name,
        "entryPoint": entry_point,
        "api": api_name,
        "encoding": encoding_name,
        "expectedOriginalResourceId": original_resource_id,
        "expectedOriginalSha256": original_sha256,
        "candidateRawSha256": candidate_sha256,
        "physicalAbiSha256": physical_abi_sha256,
        "familyId": family_id,
        "targetResourceId": target_resource_id,
    }
    mismatches = [
        name for name, value in expected_record.items()
        if record.get(name) != value
    ]
    if mismatches:
        raise RuntimeError(
            "Shared Shader replacement changed before exact restore: %s" %
            ", ".join(sorted(mismatches)))

    rollback = _rollback_shader_candidate_shared_resource({
        "replacement_id": replacement_id,
        "expected_capture_id": capture_id,
        "expected_capture_session_id": capture_session_id,
        "workspace_id": workspace_id,
    })
    _require_exact_rollback_receipt(rollback)
    base.update({
        "state": (
            "already-restored" if rollback.get("alreadyRestored") is True
            else "rolled-back"),
        "restored": True,
        "alreadyRestored": rollback.get("alreadyRestored") is True,
        "activeReplacementCountForResource": 0,
        "mutationEpoch": _shared_shader_mutation_epoch,
        "rollback": rollback,
    })
    return base


def _event_cbuffer_snapshot_id(value):
    return _shader_override_hex(value, "snapshot_id", 32)


def _require_capture_session_id(value):
    expected = _shader_override_hex(
        value, "expected_capture_session_id", 32)
    if not _capture_session_id or expected != _capture_session_id:
        raise RuntimeError("The capture session changed; take a new CBuffer snapshot")
    return expected


def _strict_base64_bytes(value, field_name, maximum_size):
    if not isinstance(value, str):
        raise ValueError("%s must be a base64 string" % field_name)
    try:
        encoded = value.encode("ascii")
    except Exception:
        raise ValueError("%s must contain ASCII base64 only" % field_name)
    # A bounded encoded length prevents a large allocation before decoding.
    if len(encoded) > ((maximum_size + 2) // 3) * 4:
        raise ValueError("%s exceeds the maximum decoded size" % field_name)
    try:
        decoded = base64.b64decode(encoded, validate=True)
    except Exception:
        raise ValueError("%s is not canonical base64" % field_name)
    if len(decoded) > maximum_size:
        raise ValueError("%s exceeds the maximum decoded size" % field_name)
    if base64.b64encode(decoded) != encoded:
        raise ValueError("%s is not canonical base64" % field_name)
    return decoded


def _canonical_json_sha256(value):
    encoded = json.dumps(
        value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _normalise_cbuffer_leaf_type(value):
    # VarType.Float is zero in the native enum and must retain its symbolic name.
    token = ("" if value is None else str(value)).strip().replace("_", "").replace(" ", "")
    token = token.split(".")[-1].lower()
    return {
        "float": "Float",
        "sint": "SInt",
        "uint": "UInt",
    }.get(token)


def _event_cbuffer_editable_leaves(constants, valid_byte_size, block_byte_size, shared=False):
    """Build the deterministic allow-list for 32-bit scalar/vector leaf edits."""
    leaves = []

    def _visit(values, prefix, parent_offset, depth):
        if depth > 32:
            raise RuntimeError("CBuffer reflection nesting exceeds 32 levels")
        for index, constant in enumerate(values or []):
            if shared and (not hasattr(constant, "byteOffset") or
                           _safe_int(getattr(constant, "byteOffset", -1), -1) < 0):
                continue
            name = str(getattr(constant, "name", "") or "").strip()
            if not name:
                name = "field%d" % index
            path = name if not prefix else "%s.%s" % (prefix, name)
            byte_offset = parent_offset + _safe_int(
                getattr(constant, "byteOffset", 0), 0)
            shader_type = getattr(constant, "type", None)
            if shader_type is None:
                continue

            members = list(getattr(shader_type, "members", []) or [])
            elements = _safe_int(getattr(shader_type, "elements", 1), 1)
            if elements <= 0:
                continue
            try:
                flags = int(getattr(shader_type, "flags", 0))
            except Exception:
                continue
            # Only row-major/hex/binary/RGB display metadata is harmless for this
            # scalar/vector editor. Packed, normalised, truncated, enum and
            # SingleElementArray interpretations are deliberately excluded.
            if flags & ~0x000F:
                continue
            pointer_type_id = _safe_int(
                getattr(shader_type, "pointerTypeID", 0xFFFFFFFF), -2)
            if pointer_type_id != 0xFFFFFFFF:
                continue
            if members:
                # Arrays of structures need per-member/per-element offset expansion,
                # which is deliberately outside this first fail-closed editor.
                if elements == 1:
                    _visit(members, path, byte_offset, depth + 1)
                continue

            if (_safe_int(getattr(constant, "bitFieldOffset", 0), 0) or
                    _safe_int(getattr(constant, "bitFieldSize", 0), 0)):
                continue
            base_type = _normalise_cbuffer_leaf_type(
                getattr(shader_type, "baseType", None))
            if base_type is None:
                continue

            rows = _safe_int(getattr(shader_type, "rows", 1), 1)
            columns = _safe_int(getattr(shader_type, "columns", 1), 1)
            if rows != 1 or columns < 1 or columns > 4:
                continue
            components = columns

            stride = _safe_int(getattr(shader_type, "arrayByteStride", 0), 0)
            element_size = components * 4
            is_array = elements > 1
            if is_array:
                # D3D11 CBuffer arrays advance by whole 16-byte registers.
                if stride < element_size or (not shared and stride % 16 != 0):
                    continue
            # DXBC reflection commonly reports 16 for arrayByteStride and
            # matrixByteStride even on non-array scalar/vector variables. With
            # rows == 1 these are register-layout metadata, not extra leaf bytes.
            if not is_array and _shader_type_byte_size(shader_type) != element_size:
                continue
            reported_size = _safe_int(getattr(shader_type, "byteSize", 0), 0)
            physical_span = ((elements - 1) * stride + element_size
                             if is_array else element_size)
            if reported_size > 0 and reported_size < physical_span:
                continue
            physical_end = byte_offset + physical_span
            if (byte_offset < 0 or physical_end > valid_byte_size or
                    (block_byte_size > 0 and physical_end > block_byte_size)):
                continue
            for array_index in range(elements):
                leaf_path = ("%s[%d]" % (path, array_index)
                             if is_array else path)
                leaf_offset = byte_offset + (array_index * stride if is_array else 0)
                leaf_end = leaf_offset + element_size
                if (leaf_offset < 0 or leaf_end > valid_byte_size or
                        (block_byte_size > 0 and leaf_end > block_byte_size)):
                    continue
                identity = {
                    "arrayIndex": array_index if elements > 1 else 0,
                    "baseType": base_type,
                    "byteOffset": leaf_offset,
                    "byteSize": element_size,
                    "components": components,
                    "path": leaf_path,
                }
                leaf = dict(identity)
                leaf["leafId"] = hashlib.sha256(json.dumps(
                    identity, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":")).encode("utf-8")).hexdigest()[:32]
                leaf["displayName"] = leaf_path
                leaf["editable"] = True
                leaf["reason"] = ""
                leaves.append(leaf)

    _visit(constants, "", 0, 0)
    leaves.sort(key=lambda leaf: (
        leaf["byteOffset"], leaf["byteSize"], leaf["path"], leaf["arrayIndex"]))

    seen_ids = set()
    previous_end = -1
    for leaf in leaves:
        if leaf["leafId"] in seen_ids:
            raise RuntimeError("CBuffer reflection produced a duplicate editable leaf ID")
        seen_ids.add(leaf["leafId"])
        if leaf["byteOffset"] < previous_end:
            raise RuntimeError("CBuffer reflection contains overlapping editable leaves")
        previous_end = leaf["byteOffset"] + leaf["byteSize"]
    if len(leaves) > 16384:
        raise RuntimeError("CBuffer reflection contains too many editable leaves")
    return leaves


def _event_cbuffer_layout(block, block_index, stage_name):
    return {
        "schema": "renderdoc-ultra-event-cbuffer-layout/v1",
        "stage": stage_name,
        "block": _constant_block_dict(block, block_index),
    }


def _event_cbuffer_live_state(ctrl, event_id, stage_name, stage, block_index, shared=False,
                             array_index=0):
    """Validate a reflected window; shared mode resolves its original byte-range identity."""
    props = ctrl.GetAPIProperties()
    # GraphicsAPI.D3D11 has numeric value zero in the native binding. It is valid, not missing.
    api_value = getattr(props, "pipelineType", None)
    api_name = "" if api_value is None else str(api_value)
    api_token = api_name.lower().replace("graphicsapi.", "").replace("direct3d", "d3d")
    supported = ("d3d11", "d3d12", "opengl", "vulkan") if shared else ("d3d11", "d3d12")
    if api_token not in supported:
        if shared:
            raise RuntimeError("The capture API does not support shared CBuffer editing")
        raise RuntimeError("Event CBuffer snapshots require a D3D11 or D3D12 capture")
    if not shared and bool(getattr(props, "remoteReplay", False)):
        raise RuntimeError("Event CBuffer snapshots require local replay")

    # Native selection snapshots are already tied to the published EID. The shared
    # editor never changes event during updates; only its initial snapshot may replay.
    _set_frame_event(ctrl, event_id, not shared)

    def _find_action(actions):
        for action in list(actions or []):
            if _safe_int(getattr(action, "eventId", 0), 0) == event_id:
                return action
            found = _find_action(getattr(action, "children", None))
            if found is not None:
                return found
        return None

    action = None
    flags = 0
    get_root_actions = getattr(ctrl, "GetRootActions", None)
    if callable(get_root_actions):
        action = _find_action(get_root_actions())
        flags = _safe_int(getattr(action, "flags", 0), 0) if action is not None else 0
        replayable_mask = _action_flags_mask(
            ("Drawcall", "Dispatch", "MeshDispatch"), 0x0002 | 0x0004 | 0x0008)
        if action is None or not (flags & replayable_mask):
            raise RuntimeError(
                "Select an actual Draw, Dispatch, or MeshDispatch EID before editing a CBuffer")
    # Older replay-controller bindings did not expose GetRootActions. In that case the bridge
    # still binds the snapshot to the exact current EID and the native SetEventCBufferOverride
    # performs the authoritative Draw/Dispatch validation before any mutation.

    pipeline = ctrl.GetPipelineState()
    shader_resource = pipeline.GetShader(stage)
    shader_resource_id = _resource_id_int(shader_resource)
    if shader_resource_id <= 0:
        raise RuntimeError("The requested event/stage has no bound shader")

    if api_token == "d3d11":
        d3d11_stage = _d3d11_stage_state(ctrl, stage_name)
        if d3d11_stage is None:
            raise RuntimeError("D3D11 stage state is unavailable")
        if _resource_id_int(getattr(d3d11_stage, "resourceId", None)) != shader_resource_id:
            raise RuntimeError("D3D11 stage state does not match the pipeline shader")
        if list(getattr(d3d11_stage, "classInstances", []) or []):
            raise RuntimeError("Dynamic shader linkage is not supported by CBuffer snapshots")

    entries = list(ctrl.GetShaderEntryPoints(shader_resource) or [])
    selection = _pipeline_shader_entry_selection(
        pipeline, stage, stage_name, shader_resource, entries)
    selected_entry = selection.get("entry")
    pipeline_entry = str(
        selection["evidence"].get("selectedEntryPoint") or "")
    if selected_entry is None:
        raise RuntimeError(
            "The event's exact shader entry point is unavailable: %s (%s)" % (
                selection["evidence"]["status"],
                selection["evidence"].get("errorId") or
                "shader-entry-point-unavailable"))

    reflection = ctrl.GetShader(
        _get_pipeline_obj(pipeline, ctrl), shader_resource, selected_entry)
    if not reflection:
        raise RuntimeError("The event's shader reflection is unavailable")
    identity_failure = _shader_reflection_identity_failure(
        reflection, selected_entry, shader_resource,
        _get_pipeline_obj(pipeline, ctrl), stage_name, selection)
    if identity_failure is not None:
        raise RuntimeError(identity_failure["error"])
    if list(getattr(reflection, "interfaces", []) or []):
        raise RuntimeError("Dynamic linkage interfaces are not supported by CBuffer snapshots")
    reflected_entry = str(
        getattr(reflection, "entryPoint", "") or pipeline_entry)
    if reflected_entry != pipeline_entry:
        raise RuntimeError("The reflected shader entry point does not match the pipeline")
    shader_raw = _shader_raw_bytes(reflection)
    if not shader_raw:
        raise RuntimeError("The captured shader's exact raw bytes are unavailable")
    shader_raw_sha256 = hashlib.sha256(shader_raw).hexdigest()

    blocks = list(getattr(reflection, "constantBlocks", []) or [])
    if block_index < 0 or block_index >= len(blocks):
        raise ValueError("block_index is outside the reflected constant-block array")
    block = blocks[block_index]
    if not bool(getattr(block, "bufferBacked", True)):
        raise RuntimeError("The reflected constant block is not buffer-backed")
    if bool(getattr(block, "inlineDataBytes", False)):
        raise RuntimeError("Inline constant data is not supported by the CBuffer editor")
    if bool(getattr(block, "compileConstants", False)):
        raise RuntimeError("Compile-time constants are not supported by the CBuffer editor")
    register_space = _safe_int(getattr(block, "fixedBindSetOrSpace", 0), 0)
    bind_array_size = _safe_int(getattr(block, "bindArraySize", 1), 1)
    slot = _safe_int(getattr(block, "fixedBindNumber", -1), -1)
    if ((not shared and bind_array_size != 1) or bind_array_size <= array_index or
            array_index < 0 or slot < 0 or slot > 0xFFFFFFFF):
        raise RuntimeError("The reflected block is not one fixed CBuffer binding")
    if api_token == "d3d11" and (register_space != 0 or slot >= 14):
        raise RuntimeError("The reflected block is not one fixed D3D11 b0-b13 binding")

    # GetConstantBlock takes the reflection array index.  The setter below takes
    # the independently reflected physical bN slot; these must never be confused.
    if shared:
        # Generic GetConstantBlock includes the API's binding/dynamic offset. Do
        # not infer a physical binding from a reflection-array index fallback.
        bound = pipeline.GetConstantBlock(stage, block_index, array_index)
        descriptor = getattr(bound, "descriptor", bound)
        if (not hasattr(descriptor, "byteOffset") or not hasattr(descriptor, "byteSize") or
                _safe_int(getattr(descriptor, "byteOffset", -1), -1) < 0):
            raise RuntimeError("The exact CBuffer binding byte range is unavailable")
        binding = _bound_descriptor_info(bound)
    else:
        binding = _get_constant_block_binding(pipeline, stage, block_index)
    buffer_resource_id = _safe_int(binding.get("resourceId"), 0)
    if buffer_resource_id <= 0:
        raise RuntimeError("The reflected constant block is unbound at this event")
    byte_offset = _safe_int(binding.get("byteOffset"), -1)
    byte_size = _safe_int(binding.get("byteSize"), -1)
    if api_token == "d3d12":
        try:
            d3d12_state = ctrl.GetD3D12PipelineState()
            root_params = list(
                getattr(getattr(d3d12_state, "rootSignature", None),
                        "parameters", []) or [])
        except Exception:
            root_params = []
        stage_index = _safe_int(stage, -1)
        stage_mask = (1 << stage_index) if 0 <= stage_index < 16 else 0
        root_cbv = False
        for root_param in root_params:
            descriptor = getattr(root_param, "descriptor", None)
            descriptor_type = str(getattr(descriptor, "type", "") or "").lower()
            visibility = _safe_int(getattr(root_param, "visibility", 0), 0)
            if (stage_mask and visibility & stage_mask and
                    _safe_int(getattr(root_param, "reg", -1), -1) == slot and
                    _safe_int(getattr(root_param, "space", -1), -1) == register_space and
                    "constantbuffer" in descriptor_type.replace("_", "") and
                    _resource_id_int(getattr(descriptor, "resource", None)) ==
                    buffer_resource_id and
                    _safe_int(getattr(descriptor, "byteOffset", -1), -1) == byte_offset):
                root_cbv = True
                break
        if root_cbv:
            indirect_mask = _action_flags_mask(("Indirect",), 0x080000)
            if not shared and flags & indirect_mask:
                raise RuntimeError(
                    "D3D12 ExecuteIndirect root-CBV editing is excluded because the command "
                    "signature may overwrite the root descriptor during replay")
            reflected_size = _safe_int(getattr(block, "byteSize", 0), 0)
            reflected_size = (reflected_size + 15) & ~15
            if reflected_size <= 0 or reflected_size > byte_size:
                raise RuntimeError(
                    "The reflected D3D12 root-CBV window is empty or outside its buffer")
            byte_size = reflected_size
    window_limit = _shared_cbuffer_protocol.MAX_SHARED_CBUFFER_BYTES if shared else 64 * 1024
    if (byte_offset < 0 or byte_size <= 0 or byte_size > window_limit or
            (not shared and (byte_offset % 16 != 0 or byte_size % 16 != 0))):
        raise RuntimeError("The live CBuffer window is invalid or unsupported")
    if api_token == "d3d12" and byte_offset % 256:
        raise RuntimeError("The live D3D12 CBV offset is not 256-byte aligned")

    buffer_resource = None
    buffer_length = -1
    for description in list(ctrl.GetBuffers() or []):
        candidate = getattr(description, "resourceId", description)
        if _resource_id_int(candidate) == buffer_resource_id:
            buffer_resource = candidate
            buffer_length = _safe_int(getattr(description, "length", -1), -1)
            break
    if buffer_resource is None or buffer_length < 0:
        raise RuntimeError("The bound CBuffer is absent from GetBuffers")
    if byte_offset >= buffer_length:
        raise RuntimeError("The bound CBuffer window starts outside the buffer")
    valid_byte_size = min(byte_size, buffer_length - byte_offset)
    if (valid_byte_size <= 0 or valid_byte_size > window_limit or
            (not shared and valid_byte_size % 16 != 0)):
        raise RuntimeError("The complete valid CBuffer window is not 16-byte aligned")

    if shared:
        _shared_cbuffer_edits.check_snapshot_capacity(valid_byte_size)
    raw_value = ctrl.GetBufferData(buffer_resource, byte_offset, valid_byte_size)
    try:
        raw_bytes = bytes(raw_value)
    except Exception:
        raw_bytes = bytearray(raw_value)
    raw_bytes = bytes(raw_bytes)
    if len(raw_bytes) != valid_byte_size:
        raise RuntimeError("GetBufferData did not return the complete valid CBuffer window")

    block_byte_size = _safe_int(getattr(block, "byteSize", 0), 0)
    layout = _event_cbuffer_layout(block, block_index, stage_name)
    leaves = _event_cbuffer_editable_leaves(
        getattr(block, "variables", []), valid_byte_size, block_byte_size, shared=shared)
    block_path = str(getattr(block, "name", "") or "cbuffer%d" % block_index)
    block_display_name = _unique_validated_alias_display(
        _matching_binding_aliases(
            shader_resource_id, stage_name, reflected_entry, shader_raw_sha256,
            "constantBuffer", slot, register_space)) or block_path
    for leaf in leaves:
        display_name = _unique_validated_alias_display(
            _matching_binding_aliases(
                shader_resource_id, stage_name, reflected_entry, shader_raw_sha256,
                "constantField", slot, register_space, leaf["byteOffset"]))
        if display_name:
            # Display-only symbol overlays must never affect path, leafId, byte
            # range, layout digest, or the patch allow-list.
            leaf["displayName"] = display_name
    return {
        "eventId": event_id,
        "stageName": stage_name,
        "stageObject": stage,
        "blockIndex": block_index,
        "constantBlockPath": block_path,
        "constantBlockName": block_path,
        "constantBlockDisplayName": block_display_name,
        "slot": slot,
        "registerSpace": register_space,
        "api": api_token,
        "shaderResource": shader_resource,
        "shaderResourceId": shader_resource_id,
        "shaderRawSha256": shader_raw_sha256,
        "entryPoint": reflected_entry,
        "bufferResource": buffer_resource,
        "bufferResourceId": buffer_resource_id,
        "bufferLength": buffer_length,
        "byteOffset": byte_offset,
        "byteSize": byte_size,
        "validByteSize": valid_byte_size,
        "rawBytes": raw_bytes,
        "rawSha256": hashlib.sha256(raw_bytes).hexdigest(),
        "layoutSha256": _canonical_json_sha256(layout),
        "fields": leaves,
    }


def _event_cbuffer_snapshot_response(record):
    return {
        "schema": "renderdoc-ultra-event-cbuffer-snapshot/v1",
        "schemaVersion": 1,
        "snapshotId": record["snapshotId"],
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "api": record["api"],
        "eventId": record["eventId"],
        "stage": record["stageName"],
        "blockIndex": record["blockIndex"],
        "constantBlockPath": record["constantBlockPath"],
        "constantBlockName": record["constantBlockName"],
        "constantBlockDisplayName": record["constantBlockDisplayName"],
        "slot": record["slot"],
        "registerSpace": record["registerSpace"],
        "shaderResourceId": record["shaderResourceId"],
        "bufferResourceId": record["bufferResourceId"],
        "byteOffset": record["byteOffset"],
        "byteSize": record["byteSize"],
        "validByteSize": record["validByteSize"],
        "rawBase64": base64.b64encode(record["baselineBytes"]).decode("ascii"),
        "rawSha256": record["baselineRawSha256"],
        "layoutSha256": record["layoutSha256"],
        "fields": list(record["fields"]),
    }


_shared_cbuffer_edits = _shared_cbuffer_protocol.SharedCBufferEdits(_resource_id_int)


def _snapshot_shared_cbuffer(params):
    """Issue a reflected field capability without creating an event override."""
    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    event_id = _safe_int(params.get("event_id"), 0)
    block_index = _safe_int(params.get("block_index"), -1)
    array_index = _safe_int(params.get("array_index"), 0)
    if event_id <= 0 or block_index < 0:
        raise ValueError("A valid event and reflected block index are required")
    if event_id != _request_visible_event_id(0):
        raise RuntimeError("The native CBuffer selection is no longer the published event")
    stage_name = _normalise_stage_name(params.get("stage", ""))
    stage = dict(_available_shader_stages([stage_name])).get(stage_name)
    if stage is None:
        raise ValueError("The selected shader stage is unavailable")

    def _do(ctrl):
        state = _event_cbuffer_live_state(
            ctrl, event_id, stage_name, stage, block_index, shared=True, array_index=array_index)
        record = dict(state)
        record.update({"snapshotId": uuid.uuid4().hex, "captureId": capture_id,
                       "captureSessionId": _capture_session_id,
                       "baselineBytes": state["rawBytes"],
                       "baselineRawSha256": state["rawSha256"]})
        snapshot = _event_cbuffer_snapshot_response(record)
        snapshot["bufferLength"] = state["bufferLength"]
        snapshot["arrayIndex"] = array_index
        return _shared_cbuffer_edits.register(snapshot, ctrl)

    return _replay(_do)


def _vertex_geometry_scope(ctrl, event, observation, stage):
    from .vertex_effect_scope import inspect
    return inspect(sys.modules[__name__], ctrl, event, observation, stage)


def _inspect_vertex_effect_scope(params):
    event = int(params.get('event_id', 0))
    observation = int(params.get('observation_event_id', 0))
    if not 0 < event <= observation <= 0xffffffff:
        raise ValueError('A source draw and same-or-later output event are required')
    visible = _request_visible_event_id(0)
    session = _capture_session_id

    def run(ctrl):
        try:
            result = _vertex_geometry_scope(ctrl, event, observation, rd.ShaderStage.Vertex)
            if session != _capture_session_id:
                raise RuntimeError('Capture changed during geometry inspection')
            return dict(result, captureSessionId=session, sourceEventId=event, observationEventId=observation)
        finally:
            _set_frame_event(ctrl, visible, True, allow_background_preemption=False)

    return _replay(run)


def _get_cbuffer_navigation_target(params):
    """Read reflected coordinates without registering any editing capability."""
    event_id=int(params.get('event_id',0));block=int(params.get('block_index',-1))
    stage_name=_normalise_stage_name(params.get('stage','fragment'))
    stage=dict(_available_shader_stages([stage_name])).get(stage_name)
    path=str(params.get('variable_path',''))
    if event_id<=0 or block<0 or stage is None or not path or len(path)>2048:
        raise ValueError('An event, block, stage and reflected variable path are required')
    component=-1
    if len(path)>2 and path[-2]=='.' and path[-1] in 'xyzw':
        component='xyzw'.index(path[-1]);path=path[:-2]
    visible=_request_visible_event_id(0)
    session=_capture_session_id
    def run(ctrl):
        try:
            state=_event_cbuffer_live_state(ctrl,event_id,stage_name,stage,block,shared=True,
                                             array_index=int(params.get('array_index',0)))
            matches=[f for f in state['fields'] if path in (f['path'],f.get('displayName'))]
            if len(matches)!=1 or (component>=0 and component>=matches[0]['components']):
                return {'resolved':False,'reason':'No unique reflected leaf matches this path',
                        'fields':[dict(path=f['path'],displayName=f.get('displayName'),components=f['components']) for f in state['fields'][:128]]}
            leaf=matches[0]
            if session!=_capture_session_id:raise RuntimeError('Capture changed during CBuffer navigation lookup')
            return {'resolved':True,'target':dict(eventId=event_id,stage=stage_name,blockIndex=block,
                arrayIndex=int(params.get('array_index',0)),path=leaf['path'],component=component,
                byteOffset=leaf['byteOffset'],components=leaf['components'],baseType=leaf['baseType'],
                shaderResourceId=str(state['shaderResourceId']),shaderRawSha256=state['shaderRawSha256'],
                bufferResourceId=str(state['bufferResourceId']))}
        finally:_set_frame_event(ctrl,visible,True)
    return _replay(run)


def _get_mesh_uv_navigation_target(params):
    event_id = int(params.get('event_id', 0))
    mesh_stage = params.get('stage', 'vs-in')
    channel = str(params.get('channel', ''))
    pair = int(params.get('pair', 0))
    texture = int(params.get('texture_resource_id', 0))
    selection_mode = params.get('selection_mode', 'point')
    select_components = params.get('selected_vertices') is not None
    selected = params.get('selected_vertices') or []
    if (selection_mode not in ('point', 'edge', 'face') or not isinstance(selected, list) or
            len(selected) > 4096 or any(isinstance(v, bool) or not isinstance(v, int) or
                                      not 0 <= v <= 0xffffffff for v in selected)):
        raise ValueError('Selection requires up to 4096 original vertex indices and point/edge/face mode')
    if not 0 < event_id <= 0xffffffff or mesh_stage not in ('vs-in', 'vs-out', 'gs-out') or pair not in (0, 1):
        raise ValueError('A draw EID, mesh stage and UV component pair are required')
    visible = _request_visible_event_id(0)

    def run(ctrl):
        try:
            action = _find_action_by_event(ctrl.GetRootActions(), event_id)
            if action is None or not (action.flags & (rd.ActionFlags.Drawcall | rd.ActionFlags.MeshDispatch)):
                raise ValueError('UV links require an actual graphics draw')
            _select_event_for_read(ctrl, event_id)
            pipeline = ctrl.GetPipelineState()
            if mesh_stage == 'vs-in':
                inputs = [attr for attr in pipeline.GetVertexInputs() if attr.used and not attr.perInstance]
                channels = {str(attr.name): int(attr.format.compCount) for attr in inputs}
            else:
                stage = rd.ShaderStage.Vertex if mesh_stage == 'vs-out' else rd.ShaderStage.Geometry
                if mesh_stage == 'vs-out' and pipeline.GetShaderReflection(rd.ShaderStage.Mesh):
                    stage = rd.ShaderStage.Mesh
                if mesh_stage == 'gs-out' and not pipeline.GetShaderReflection(stage):
                    stage = rd.ShaderStage.Domain
                reflection = pipeline.GetShaderReflection(stage)
                channels = {str(sig.varName or sig.semanticIdxName): int(sig.compCount)
                            for sig in reflection.outputSignature if not sig.perPrimitiveRate} if reflection else {}
            choices = [name for name, count in channels.items() if count >= (pair + 1) * 2]
            textures = {int(t.resourceId): t for t in ctrl.GetTextures() if t.dimension == 2 and t.msSamp == 1}
            bound = set()
            for _, stage in _available_shader_stages(['vertex', 'fragment', 'geometry', 'hull', 'domain', 'mesh']):
                for item in pipeline.GetReadOnlyResources(stage, True):
                    rid = _resource_id_int(item.descriptor.resource)
                    if rid in textures:
                        bound.add(rid)
            if not choices or (channel and channel not in choices) or (texture and texture not in bound):
                return dict(resolved=False, channelChoices=choices, textureResourceIds=sorted(bound))
            target = dict(kind='uv', eventId=event_id, stage=mesh_stage,
                          channel=channel, pair=pair, textureResourceId=str(texture))
            if select_components:
                target.update(selectionMode=selection_mode, selectedVertices=sorted(set(selected)))
            return dict(resolved=True, target=target, channelChoices=choices,
                        textureResourceIds=sorted(bound))
        finally:
            _set_frame_event(ctrl, visible, True, allow_background_preemption=False)

    return _replay(run)


def _capture_mesh_uv_evidence(params):
    session = _require_capture_session_id(params.get('expected_capture_session_id'))
    request = params.get('request')
    def ui():
        if session != _capture_session_id:
            raise RuntimeError('Capture changed during mesh evidence collection')
        if request:
            event = int(request['eventId'])
            if int(_ctx.CurEvent()) != event or int(_ctx.CurSelectedEvent()) != event:
                _ctx.SetEventID([], event, event, True)
            _ctx.ShowMeshPreview()
        widget = _ctx.GetMeshPreview().Widget()
        if widget.metaObject().indexOfProperty('meshEvidence') < 0:
            raise RuntimeError('This application does not support native mesh/UV evidence snapshots')
        if request:
            # JSON preserves nested lists across PySide's QVariant boundary.
            widget.setProperty('meshEvidenceRequest', json.dumps(request, ensure_ascii=False))
        result = dict(widget.property('meshEvidence') or {})
        if result.get('requestId') != params.get('request_id'):
            raise RuntimeError('The mesh evidence request was superseded')
        result['captureSessionId'] = session
        return result
    return _invoke_on_ui_sync(ui)


def _shared_cbuffer_transaction(params, rollback=False):
    _require_capture_identity(params.get("expected_capture_id"))
    _require_capture_session_id(params.get("expected_capture_session_id"))

    def _do(ctrl):
        _begin_replay_atomic_transaction()
        return _execute_shared_cbuffer_operation(ctrl, params, rollback)

    envelope = _replay(_do)
    # The synchronous helper returns native configuration acceptance. GUI
    # publication is asynchronous and must not force/retry the committed edit.
    response = envelope["response"]
    if response is not None:
        response["previewPublished"] = False
        response["previewPublicationPending"] = True
    _invoke_on_ui_sync(lambda: _publish_shared_cbuffer_operation(
        envelope, lambda unused_response, unused_error: None))
    if envelope["error"] is not None:
        raise envelope["error"]
    return response


def _execute_shared_cbuffer_operation(ctrl, params, rollback):
    envelope = {"response": None, "error": None,
                "eventId": None, "generation": None,
                "captureSessionId": params["expected_capture_session_id"]}
    try:
        operation = _shared_cbuffer_edits.rollback if rollback else _shared_cbuffer_edits.apply
        envelope["response"] = operation(params, ctrl)
    except BaseException as exc:
        envelope["error"] = exc
    try:
        # These facts come from the actual completed replay operation, never
        # from a potentially newer GUI selection.
        envelope["eventId"] = int(ctrl.GetCurrentEventID())
        envelope["generation"] = int(ctrl.GetSharedBufferPatchGeneration())
    except Exception as exc:
        envelope["publicationError"] = str(exc)
    return envelope


def _publish_shared_cbuffer_operation(envelope, complete):
    """GUI-only acknowledgement after owned pipeline publication and viewer drain."""
    completed = [False]

    def finish(published):
        if completed[0]:
            return
        completed[0] = True
        response = envelope["response"]
        if response is not None:
            response["replayedEventId"] = envelope["eventId"]
            response["previewPublished"] = bool(published)
            response["previewPublicationPending"] = False
            if envelope.get("publicationError"):
                response["previewDiagnostic"] = envelope["publicationError"]
        # false means publication was superseded, not that the native mutation
        # failed. Keep accepted bytes/revision and never retry them automatically.
        complete(response, envelope["error"])

    if (envelope["captureSessionId"] != _capture_session_id or
            envelope["eventId"] is None or envelope["generation"] is None):
        finish(False)
        return
    try:
        _ctx.RefreshReplayStatus(envelope["eventId"], envelope["generation"], finish)
    except Exception as exc:
        envelope["publicationError"] = str(exc)
        finish(False)


def _apply_shared_cbuffer(params):
    return _shared_cbuffer_transaction(params)


def _rollback_shared_cbuffer(params):
    return _shared_cbuffer_transaction(params, rollback=True)


def _material_current_context():
    """GUI-only material identity, with no bound-shader query or replay wait."""
    loaded = bool(_ctx and _ctx.IsCaptureLoaded())
    return {"capture": {"loaded": loaded, "captureSessionId": _capture_session_id,
                        "captureId": str(_symbol_capture_snapshot.get("captureId", "") or ""),
                        "api": str(_ctx.APIProps().pipelineType) if loaded else ""},
            "events": {"currentEventId": int(_ctx.CurEvent()) if loaded else 0}}


def _begin_shared_cbuffer_transaction(params, rollback, cancel, complete):
    """Capture GUI ownership, enqueue native replay, then publish on the GUI thread."""
    _require_capture_identity(params.get("expected_capture_id"))
    session_id = _require_capture_session_id(params.get("expected_capture_session_id"))
    replay_manager = _ctx.Replay()
    miniqt = _ctx.Extensions().GetMiniQtHelper()

    def replay_work(ctrl):
        if cancel.is_set() or _capture_session_id != session_id:
            envelope = {"response": None,
                        "error": RuntimeError("The queued material edit was cancelled before replay"),
                        "eventId": None, "generation": None, "captureSessionId": session_id}
        else:
            envelope = _execute_shared_cbuffer_operation(ctrl, params, rollback)
        miniqt.InvokeOntoUIThread(lambda: _publish_shared_cbuffer_operation(envelope, complete))

    # The queue owns coalescing. An empty/untagged native request must execute
    # exactly once, including a completed version followed by a newer input.
    replay_manager.AsyncInvoke(replay_work)


def _snapshot_event_cbuffer(params):
    """Capture one immutable, reflected D3D11/D3D12 CBuffer binding window."""
    global _event_cbuffer_capture_token

    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_token = _current_capture_token()
    if (_event_cbuffer_capture_token is not None and
            _event_cbuffer_capture_token != capture_token):
        _forget_event_cbuffer_snapshots()

    event_id = _safe_int(params.get("event_id"), 0)
    block_index = _safe_int(params.get("block_index"), -1)
    if event_id <= 0:
        raise ValueError("event_id must be a positive integer")
    if block_index < 0:
        raise ValueError("block_index must be a non-negative reflection array index")
    stage_name = _normalise_stage_name(params.get("stage", ""))
    stage_map = dict(_available_shader_stages([stage_name]))
    stage = stage_map.get(stage_name)
    if stage is None or stage_name not in (
            "vertex", "hull", "domain", "geometry", "fragment", "compute",
            "task", "mesh"):
        raise ValueError("Unsupported D3D11/D3D12 shader stage: %s" % stage_name)

    try:
        original_event = _request_visible_event_id(0)
    except Exception:
        original_event = 0

    def _do(ctrl):
        try:
            return _event_cbuffer_live_state(
                ctrl, event_id, stage_name, stage, block_index)
        finally:
            if original_event > 0 and original_event != event_id:
                _set_frame_event(ctrl, original_event, True)

    state = _replay(_do)
    key = (event_id, stage_name, state["slot"], state["registerSpace"])
    old_snapshot_id = _event_cbuffer_snapshot_keys.get(key)
    if old_snapshot_id:
        old_record = _event_cbuffer_snapshots.get(old_snapshot_id)
        if old_record:
            raise RuntimeError(
                "This event/stage/slot/register-space already has a bridge-owned CBuffer snapshot; "
                "rollback it before taking another snapshot")
        _event_cbuffer_snapshot_keys.pop(key, None)
    if len(_event_cbuffer_snapshots) >= MAX_EVENT_CBUFFER_SNAPSHOTS:
        raise RuntimeError(
            "The active capture reached the %d CBuffer snapshot limit" %
            MAX_EVENT_CBUFFER_SNAPSHOTS)

    snapshot_id = uuid.uuid4().hex
    record = {
        "snapshotId": snapshot_id,
        "captureId": capture_id,
        "captureSessionId": _capture_session_id,
        "captureToken": capture_token,
        "api": state["api"],
        "eventId": event_id,
        "stageName": stage_name,
        "stageObject": stage,
        "blockIndex": block_index,
        "constantBlockPath": state["constantBlockPath"],
        "constantBlockName": state["constantBlockName"],
        "constantBlockDisplayName": state["constantBlockDisplayName"],
        "slot": state["slot"],
        "registerSpace": state["registerSpace"],
        "shaderResourceId": state["shaderResourceId"],
        "shaderRawSha256": state["shaderRawSha256"],
        "entryPoint": state["entryPoint"],
        "bufferResourceId": state["bufferResourceId"],
        "bufferLength": state["bufferLength"],
        "byteOffset": state["byteOffset"],
        "byteSize": state["byteSize"],
        "validByteSize": state["validByteSize"],
        "baselineBytes": state["rawBytes"],
        "baselineRawSha256": state["rawSha256"],
        "layoutSha256": state["layoutSha256"],
        "fields": state["fields"],
        "fieldsById": dict((leaf["leafId"], leaf) for leaf in state["fields"]),
        "overrideId": None,
        "revision": 0,
        "currentBytes": state["rawBytes"],
        "currentRawSha256": state["rawSha256"],
    }
    _event_cbuffer_snapshots[snapshot_id] = record
    _event_cbuffer_snapshot_keys[key] = snapshot_id
    _event_cbuffer_capture_token = capture_token
    return _event_cbuffer_snapshot_response(record)


def _require_event_cbuffer_record(params):
    snapshot_id = _event_cbuffer_snapshot_id(params.get("snapshot_id"))
    record = _event_cbuffer_snapshots.get(snapshot_id)
    if record is None:
        raise ValueError("Unknown or expired event CBuffer snapshot ID")
    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_session_id = _require_capture_session_id(
        params.get("expected_capture_session_id"))
    if record.get("captureId") != capture_id:
        raise RuntimeError("The CBuffer snapshot belongs to a different catalog identity")
    if (record.get("captureSessionId") != capture_session_id or
            record.get("captureToken") != _current_capture_token()):
        _forget_event_cbuffer_snapshots()
        raise RuntimeError("The CBuffer snapshot belongs to a different capture lifecycle")
    return snapshot_id, record


def _validate_event_cbuffer_patches(record, patches):
    if not isinstance(patches, list):
        raise ValueError("patches must be a cumulative array")
    if len(patches) > len(record["fieldsById"]):
        raise ValueError("patches contains more entries than editable reflected leaves")

    rebuilt = bytearray(record["baselineBytes"])
    seen = set()
    for index, patch in enumerate(patches):
        if not isinstance(patch, dict):
            raise ValueError("patches[%d] must be an object" % index)
        unknown = set(patch.keys()) - set(("leafId", "packedBase64"))
        if unknown:
            raise ValueError("patches[%d] contains unsupported keys" % index)
        leaf_id = _shader_override_hex(
            patch.get("leafId"), "patches[%d].leafId" % index, 32)
        if leaf_id in seen:
            raise ValueError("patches contains a duplicate leafId")
        seen.add(leaf_id)
        leaf = record["fieldsById"].get(leaf_id)
        if leaf is None:
            raise ValueError("patches references a leaf not issued by this snapshot")
        packed = _strict_base64_bytes(
            patch.get("packedBase64"), "patches[%d].packedBase64" % index,
            leaf["byteSize"])
        if len(packed) != leaf["byteSize"]:
            raise ValueError("A packed leaf does not match its reflected byte size")
        if leaf["baseType"] == "Float":
            values = struct.unpack("<%df" % leaf["components"], packed)
            if any(not math.isfinite(value) for value in values):
                raise ValueError("Float CBuffer patches must contain only finite values")
        start = leaf["byteOffset"]
        rebuilt[start:start + leaf["byteSize"]] = packed
    return bytes(rebuilt)


def _expire_event_cbuffer_record(snapshot_id, record):
    key = (record["eventId"], record["stageName"], record["slot"],
           record["registerSpace"])
    _event_cbuffer_snapshots.pop(snapshot_id, None)
    if _event_cbuffer_snapshot_keys.get(key) == snapshot_id:
        _event_cbuffer_snapshot_keys.pop(key, None)


def _record_event_cbuffer_release(record):
    """Keep a bounded capture-local tombstone for idempotent rollback/status."""
    global _event_cbuffer_release_serial
    _event_cbuffer_release_serial += 1
    snapshot_id = record["snapshotId"]
    _event_cbuffer_released_snapshots[snapshot_id] = {
        "snapshotId": snapshot_id,
        "overrideId": record.get("overrideId"),
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "captureToken": record["captureToken"],
        "api": record["api"],
        "eventId": record["eventId"],
        "stageName": record["stageName"],
        "blockIndex": record["blockIndex"],
        "slot": record["slot"],
        "registerSpace": record["registerSpace"],
        "revision": record["revision"],
        "baselineRawSha256": record["baselineRawSha256"],
        "currentRawSha256": record["currentRawSha256"],
        "layoutSha256": record["layoutSha256"],
        "releaseSerial": _event_cbuffer_release_serial,
    }
    while len(_event_cbuffer_released_snapshots) > MAX_EVENT_CBUFFER_RELEASED_SNAPSHOTS:
        oldest_id = min(
            _event_cbuffer_released_snapshots,
            key=lambda value: _event_cbuffer_released_snapshots[value]["releaseSerial"])
        _event_cbuffer_released_snapshots.pop(oldest_id, None)


def _apply_event_cbuffer_override(params):
    """Apply a cumulative allow-listed patch set to one immutable snapshot."""
    snapshot_id, record = _require_event_cbuffer_record(params)
    expected_raw_sha256 = _shader_override_hex(
        params.get("expected_raw_sha256"), "expected_raw_sha256", 64)
    expected_layout_sha256 = _shader_override_hex(
        params.get("expected_layout_sha256"), "expected_layout_sha256", 64)
    if expected_raw_sha256 != record["currentRawSha256"]:
        raise RuntimeError("The CBuffer editor revision is stale")
    if expected_layout_sha256 != record["layoutSha256"]:
        raise RuntimeError("The reflected CBuffer layout digest changed")

    expected_revision = _safe_int(params.get("expected_revision"), -1)
    new_revision = _safe_int(params.get("new_revision"), -1)
    if expected_revision != record["revision"]:
        raise RuntimeError("The CBuffer editor revision is stale")
    if new_revision != expected_revision + 1:
        raise ValueError("new_revision must equal expected_revision + 1")

    expected_override_id = str(params.get("expected_override_id", "") or "").strip().lower()
    current_override_id = str(record.get("overrideId") or "")
    if expected_override_id:
        expected_override_id = _shader_override_hex(
            expected_override_id, "expected_override_id", 32)
    if expected_override_id != current_override_id:
        raise RuntimeError("The active CBuffer override ID changed")

    data = _strict_base64_bytes(
        params.get("data_base64"), "data_base64", 64 * 1024)
    if len(data) != record["validByteSize"]:
        raise ValueError("data_base64 must contain the complete valid bound window")
    data_sha256 = _shader_override_hex(
        params.get("data_sha256"), "data_sha256", 64)
    if hashlib.sha256(data).hexdigest() != data_sha256:
        raise ValueError("data_base64 does not match data_sha256")
    rebuilt = _validate_event_cbuffer_patches(record, params.get("patches"))
    if rebuilt != data:
        raise ValueError(
            "data_base64 is not exactly the immutable baseline plus the cumulative patches")

    old_override_id = record.get("overrideId")
    old_data = record["currentBytes"]
    override_id = old_override_id or uuid.uuid4().hex
    restoration_failed = [False]

    def _do(ctrl):
        setter_called = False
        state = _event_cbuffer_live_state(
            ctrl, record["eventId"], record["stageName"],
            record["stageObject"], record["blockIndex"])
        comparisons = (
            ("slot", state["slot"], record["slot"]),
            ("register space", state["registerSpace"], record["registerSpace"]),
            ("shader resource", state["shaderResourceId"], record["shaderResourceId"]),
            ("shader bytes", state["shaderRawSha256"], record["shaderRawSha256"]),
            ("entry point", state["entryPoint"], record["entryPoint"]),
            ("buffer resource", state["bufferResourceId"], record["bufferResourceId"]),
            ("buffer length", state["bufferLength"], record["bufferLength"]),
            ("byte offset", state["byteOffset"], record["byteOffset"]),
            ("byte size", state["byteSize"], record["byteSize"]),
            ("valid byte size", state["validByteSize"], record["validByteSize"]),
            ("layout", state["layoutSha256"], record["layoutSha256"]),
            ("captured raw bytes", state["rawSha256"], record["baselineRawSha256"]),
        )
        for label, current, expected in comparisons:
            if current != expected:
                raise RuntimeError("The live CBuffer %s changed since snapshot" % label)
        if [leaf["leafId"] for leaf in state["fields"]] != [
                leaf["leafId"] for leaf in record["fields"]]:
            raise RuntimeError("The editable CBuffer leaf allow-list changed since snapshot")

        try:
            setter_called = True
            _begin_replay_atomic_transaction()
            error = ctrl.SetEventCBufferOverride(
                record["eventId"], record["stageObject"], record["slot"],
                state["shaderResource"], state["bufferResource"],
                record["byteOffset"], record["byteSize"], data,
                record["registerSpace"])
            if str(error or ""):
                raise RuntimeError("SetEventCBufferOverride failed: %s" % str(error))
        except Exception as apply_error:
            if setter_called:
                restored = False
                try:
                    if old_override_id:
                        restore_error = ctrl.SetEventCBufferOverride(
                            record["eventId"], record["stageObject"], record["slot"],
                            state["shaderResource"], state["bufferResource"],
                            record["byteOffset"], record["byteSize"], old_data,
                            record["registerSpace"])
                        restored = not str(restore_error or "")
                    else:
                        ctrl.ClearEventCBufferOverride(
                            record["eventId"], record["stageObject"], record["slot"],
                            record["registerSpace"])
                        restored = True
                except Exception:
                    restored = False
                if not restored:
                    restoration_failed[0] = True
                    raise RuntimeError(
                        "%s; restoring the previous CBuffer configuration failed and "
                        "the snapshot was expired" % str(apply_error))
            raise
        return True

    try:
        _replay(_do)
    except Exception:
        if restoration_failed[0]:
            _expire_event_cbuffer_record(snapshot_id, record)
        raise

    record["overrideId"] = override_id
    record["revision"] = new_revision
    record["currentBytes"] = data
    record["currentRawSha256"] = data_sha256
    _notify_shader_replay_changed()
    return {
        "schema": "renderdoc-ultra-event-cbuffer-override/v1",
        "schemaVersion": 1,
        "snapshotId": snapshot_id,
        "overrideId": override_id,
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "api": record["api"],
        "eventId": record["eventId"],
        "stage": record["stageName"],
        "blockIndex": record["blockIndex"],
        "slot": record["slot"],
        "registerSpace": record["registerSpace"],
        "revision": new_revision,
        "currentRawSha256": data_sha256,
        "layoutSha256": record["layoutSha256"],
        "configured": True,
        "appliedToCurrentEvent": True,
    }


def _rollback_event_cbuffer_override(params):
    """Clear one exact override and release its immutable snapshot."""
    global _event_cbuffer_capture_token
    snapshot_id = _event_cbuffer_snapshot_id(params.get("snapshot_id"))
    requested_override_id = str(params.get("override_id", "") or "").strip().lower()
    if requested_override_id:
        requested_override_id = _shader_override_hex(
            requested_override_id, "override_id", 32)

    record = _event_cbuffer_snapshots.get(snapshot_id)
    if record is None:
        released = _event_cbuffer_released_snapshots.get(snapshot_id)
        if released is None:
            raise ValueError("Unknown or expired event CBuffer snapshot ID")
        capture_id = _require_capture_identity(params.get("expected_capture_id"))
        capture_session_id = _require_capture_session_id(
            params.get("expected_capture_session_id"))
        if released.get("captureId") != capture_id:
            raise RuntimeError("The CBuffer snapshot belongs to a different catalog identity")
        if (released.get("captureSessionId") != capture_session_id or
                released.get("captureToken") != _current_capture_token()):
            _forget_event_cbuffer_snapshots()
            raise RuntimeError("The CBuffer snapshot belongs to a different capture lifecycle")
        released_override_id = str(released.get("overrideId") or "")
        if requested_override_id and requested_override_id != released_override_id:
            raise RuntimeError("The requested CBuffer override ID was never owned by this snapshot")
        return {
            "schema": "renderdoc-ultra-event-cbuffer-override/v1",
            "schemaVersion": 1,
            "snapshotId": snapshot_id,
            "overrideId": released.get("overrideId"),
            "captureId": released["captureId"],
            "captureSessionId": released["captureSessionId"],
            "api": released["api"],
            "eventId": released["eventId"],
            "stage": released["stageName"],
            "blockIndex": released["blockIndex"],
            "slot": released["slot"],
            "registerSpace": released["registerSpace"],
            "revision": released["revision"],
            "currentRawSha256": released["currentRawSha256"],
            "cleared": False,
            "alreadyReleased": True,
            "snapshotReleased": True,
            "configured": False,
        }

    # Validate the active record only after handling the bounded idempotency tombstone.
    snapshot_id, record = _require_event_cbuffer_record(params)
    active_override_id = str(record.get("overrideId") or "")
    if requested_override_id and requested_override_id != active_override_id:
        raise RuntimeError("The requested CBuffer override ID is not active")

    if active_override_id:
        def _do(ctrl):
            _begin_replay_atomic_transaction()
            ctrl.ClearEventCBufferOverride(
                record["eventId"], record["stageObject"], record["slot"],
                record["registerSpace"])
        _replay(_do)
        _notify_shader_replay_changed()
    _record_event_cbuffer_release(record)
    _expire_event_cbuffer_record(snapshot_id, record)
    if not _event_cbuffer_snapshots:
        _event_cbuffer_capture_token = None
    return {
        "schema": "renderdoc-ultra-event-cbuffer-override/v1",
        "schemaVersion": 1,
        "snapshotId": snapshot_id,
        "overrideId": record.get("overrideId"),
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "api": record["api"],
        "eventId": record["eventId"],
        "stage": record["stageName"],
        "blockIndex": record["blockIndex"],
        "slot": record["slot"],
        "registerSpace": record["registerSpace"],
        "revision": record["revision"],
        "currentRawSha256": record["currentRawSha256"],
        "cleared": bool(active_override_id),
        "alreadyReleased": False,
        "snapshotReleased": True,
        "configured": False,
    }


def _get_event_cbuffer_override_status(params):
    snapshot_id, record = _require_event_cbuffer_record(params)
    return {
        "schema": "renderdoc-ultra-event-cbuffer-override/v1",
        "schemaVersion": 1,
        "snapshotId": snapshot_id,
        "overrideId": record.get("overrideId"),
        "captureId": record["captureId"],
        "captureSessionId": record["captureSessionId"],
        "api": record["api"],
        "eventId": record["eventId"],
        "stage": record["stageName"],
        "blockIndex": record["blockIndex"],
        "slot": record["slot"],
        "registerSpace": record["registerSpace"],
        "revision": record["revision"],
        "baselineRawSha256": record["baselineRawSha256"],
        "currentRawSha256": record["currentRawSha256"],
        "layoutSha256": record["layoutSha256"],
        "configured": bool(record.get("overrideId")),
    }


def _clear_all_event_cbuffer_snapshots(params):
    """Explicit recovery: clear every bridge-owned CBuffer shadow/snapshot."""
    capture_id = _require_capture_identity(params.get("expected_capture_id"))
    capture_session_id = _require_capture_session_id(
        params.get("expected_capture_session_id"))
    capture_token = _current_capture_token()
    if (_event_cbuffer_capture_token is not None and
            _event_cbuffer_capture_token != capture_token):
        _forget_event_cbuffer_snapshots()
        raise RuntimeError("The CBuffer snapshots belong to a different capture lifecycle")

    snapshot_count = len(_event_cbuffer_snapshots)
    override_count = sum(
        1 for record in _event_cbuffer_snapshots.values()
        if record.get("overrideId"))

    def _do(ctrl):
        props = ctrl.GetAPIProperties()
        api_name = _native_enum_text(getattr(props, "pipelineType", None))
        api_token = api_name.lower().replace("graphicsapi.", "").replace(
            "direct3d", "d3d")
        if api_token not in ("d3d11", "d3d12"):
            raise RuntimeError(
                "Clearing event CBuffers requires a D3D11 or D3D12 capture")
        if bool(getattr(props, "remoteReplay", False)):
            raise RuntimeError("Clearing event CBuffers requires local replay")
        _begin_replay_atomic_transaction()
        ctrl.ClearEventCBufferOverrides()

    _replay(_do)
    _forget_event_cbuffer_snapshots()
    if override_count:
        _notify_shader_replay_changed()
    return {
        "schema": "renderdoc-ultra-event-cbuffer-clear-all/v1",
        "schemaVersion": 1,
        "captureId": capture_id,
        "captureSessionId": capture_session_id,
        "clearedOverrideCount": override_count,
        "releasedSnapshotCount": snapshot_count,
        "cleared": True,
    }


class _ShaderCatalogExportCancelled(RuntimeError):
    pass


def _check_shader_catalog_export_cancel(cancel_event):
    if cancel_event is None:
        return
    expected_generation = getattr(
        cancel_event, "replaylabForegroundGeneration", None)
    replay_manager = getattr(cancel_event, "replaylabReplayManager", None)
    current_generation = (
        _replay_foreground_generation(replay_manager)
        if replay_manager is not None else _foreground_replay_generation())
    if (cancel_event is not None and expected_generation is not None and
            current_generation is not None and
            current_generation != expected_generation):
        cancel_event.set()
        raise _ShaderCatalogExportCancelled(
            "Shader catalog export yielded after a user replay operation")
    pending_foreground = (
        _replay_foreground_pending(replay_manager)
        if replay_manager is not None else _foreground_replay_pending())
    if cancel_event is not None and pending_foreground:
        cancel_event.set()
        raise _ShaderCatalogExportCancelled(
            "Shader catalog export yielded to a user replay operation")
    if cancel_event is not None and cancel_event.is_set():
        raise _ShaderCatalogExportCancelled("Shader catalog export cancelled")


def _shader_catalog_export_capture_snapshot():
    """Capture the small ICaptureContext state only on qrenderdoc's UI thread."""
    if not _ctx or not _ctx.IsCaptureLoaded():
        raise RuntimeError("No capture loaded")
    try:
        original_event = _request_visible_event_id(0)
        restore_original_event = True
    except Exception:
        original_event = 0
        restore_original_event = False
    try:
        capture_path = str(_ctx.GetCaptureFilename())
    except Exception:
        capture_path = ""
    return {
        "capturePath": capture_path,
        "captureSessionId": str(_capture_session_id or ""),
        "captureToken": _active_capture_token,
        "originalEvent": original_event,
        "restoreOriginalEvent": restore_original_event,
    }


def _export_shader_catalog(params, replay_controller=None,
                           capture_snapshot=None, cancel_event=None,
                           progress_job_id="", defer_publication=False,
                           defer_finalization=False):
    """Export an exact, versioned shader/reflection/binding snapshot for asset matching.

    Request fields:
      output_dir: required destination directory.
      event_ids: optional list or comma-separated string. If omitted/empty, all draw/dispatch
                 actions are visited.
      stages: optional shader-stage list. Defaults to every stage available in this RenderDoc.
    """
    if capture_snapshot is None:
        capture_snapshot = _invoke_on_ui_sync(
            _shader_catalog_export_capture_snapshot)
    elif (capture_snapshot.get("captureSessionId") != _capture_session_id or
          capture_snapshot.get("captureToken") != _active_capture_token):
        raise RuntimeError("Capture changed before Shader catalog export")
    _check_shader_catalog_export_cancel(cancel_event)

    expected_capture_id = str(
        params.get("expected_capture_id", "") or "").strip()
    expected_identity_sha256 = str(
        params.get("expected_identity_evidence_sha256", "") or "").strip()
    # The capture-independent pair. When it is supplied it is what the export is
    # judged against, because a stored workspace can reproduce it next session and
    # cannot reproduce a ResourceId.
    expected_stable_capture_id = str(
        params.get("expected_stable_capture_id", "") or "").strip().lower()
    expected_stable_identity_sha256 = str(
        params.get("expected_stable_identity_evidence_sha256", "") or "").strip().lower()
    activate_catalog_if_valid = params.get("activate_catalog_if_valid", False)
    if type(activate_catalog_if_valid) is not bool:
        raise ValueError("activate_catalog_if_valid must be a boolean")
    if bool(expected_stable_capture_id) != bool(expected_stable_identity_sha256):
        raise ValueError(
            "expected_stable_capture_id and "
            "expected_stable_identity_evidence_sha256 must be supplied together")
    for value, label in ((expected_stable_capture_id, "expected_stable_capture_id"),
                         (expected_stable_identity_sha256,
                          "expected_stable_identity_evidence_sha256")):
        if value and (len(value) != 64 or any(
                character not in "0123456789abcdef" for character in value)):
            raise ValueError("%s must be a lowercase SHA-256" % label)
    if bool(expected_capture_id) != bool(expected_identity_sha256):
        raise ValueError(
            "expected_capture_id and expected_identity_evidence_sha256 must "
            "be supplied together")
    if expected_capture_id:
        if (len(expected_capture_id) != 64 or
                any(character not in "0123456789abcdef"
                    for character in expected_capture_id)):
            raise ValueError("expected_capture_id must be a lowercase SHA-256")
        if (len(expected_identity_sha256) != 64 or
                any(character not in "0123456789abcdef"
                    for character in expected_identity_sha256)):
            raise ValueError(
                "expected_identity_evidence_sha256 must be a lowercase SHA-256")
    if activate_catalog_if_valid and not (
            expected_capture_id or expected_stable_capture_id):
        raise ValueError(
            "activate_catalog_if_valid requires an expected catalog identity")

    output_dir = str(params.get("output_dir", "") or "").strip()
    if not output_dir:
        raise ValueError("output_dir required")
    output_dir = os.path.abspath(os.path.expanduser(output_dir))
    blob_dir = os.path.join(output_dir, "blobs")

    requested_event_ids = _parse_catalog_event_ids(
        params.get("event_ids", params.get("eventIds")))
    if requested_event_ids == []:
        requested_event_ids = None
    stages = _available_shader_stages(params.get("stages"))
    if not stages:
        raise ValueError("No valid shader stages requested")
    progress_binding = _shader_catalog_progress_binding(params)
    if progress_job_id:
        if progress_binding is None:
            progress_binding = {}
        progress_binding["jobId"] = str(progress_job_id)

    original_event = _safe_int(capture_snapshot.get("originalEvent"), 0)
    restore_original_event = bool(capture_snapshot.get("restoreOriginalEvent"))
    capture_path = str(capture_snapshot.get("capturePath", "") or "")
    if capture_path:
        # Qt/CLI can spell the same Windows RDC with '/' or '\\'. Catalog
        # identity includes this text, so canonicalize at the export boundary
        # while retaining the historical native path spelling and case. Do
        # not change the capture-ID algorithm or rewrite existing catalogs.
        capture_path = os.path.abspath(os.path.normpath(capture_path))

    def _do(ctrl):
        action_info = {}
        if requested_event_ids is not None:
            # A target-bound workspace supplies one frozen representative EID.
            # Do not enumerate the frame's action tree merely to decorate that
            # explicit event with an action label: SetFrameEvent below is the
            # only replay-state lookup needed for its real PSO/ABI snapshot.
            event_ids = requested_event_ids
            selection = "explicit"
        else:
            action_count = [0]

            def _collect_actions(actions):
                for action in actions:
                    _check_shader_catalog_export_cancel(cancel_event)
                    action_count[0] += 1
                    if progress_job_id and action_count[0] % 32 == 0:
                        # A large marker/action tree is traversed before the first
                        # EID snapshot exists. Yield periodically so the GUI can
                        # continue polling the still-running job during this phase.
                        time.sleep(SHADER_CATALOG_EXPORT_UI_YIELD_SECONDS)
                    event_id = _safe_int(getattr(action, "eventId", 0), 0)
                    action_info[event_id] = {
                        "name": str(getattr(action, "customName", "") or
                                    "Action %d" % _safe_int(
                                        getattr(action, "actionId", 0), 0)),
                        "flags": _safe_int(getattr(action, "flags", 0), 0),
                    }
                    children = getattr(action, "children", None)
                    if children:
                        _collect_actions(children)

            _collect_actions(ctrl.GetRootActions())
            action_mask = 0
            for flag_name in ("Drawcall", "Dispatch", "MeshDispatch", "DispatchRay"):
                action_mask |= _safe_int(getattr(rd.ActionFlags, flag_name, 0), 0)
            # Stable values from ActionFlags are a fallback for older Python bindings.
            if not action_mask:
                action_mask = 0x0002 | 0x0004 | 0x0008 | 0x4000
            event_ids = [eid for eid, info in sorted(action_info.items())
                         if info["flags"] & action_mask]
            selection = "all_draw_dispatch"

        catalog = {
            "schema": SYMBOL_CATALOG_SCHEMA,
            "schemaVersion": SYMBOL_CATALOG_VERSION,
            "capturePath": capture_path,
            "capture": {
                "path": capture_path,
            },
            "selection": {
                "mode": selection,
                "eventIds": event_ids,
                "stages": [name for name, unused_stage in stages],
            },
            "shaders": [],
            "uses": [],
            "errors": [],
        }

        try:
            props = ctrl.GetAPIProperties()
            api_name = str(getattr(props, "pipelineType", ""))
            catalog["api"] = api_name
            catalog["capture"]["api"] = api_name
            catalog["capture"]["renderer"] = str(getattr(props, "localRenderer", ""))
        except Exception as exc:
            catalog["errors"].append({"scope": "capture", "message": str(exc)})
        try:
            frame_info = ctrl.GetFrameInfo()
            catalog["capture"]["frameNumber"] = _safe_int(
                getattr(frame_info, "frameNumber", 0), 0)
        except Exception:
            pass

        blobs = {}
        unique_shaders = {}
        dxil_requests = []
        dxil_snapshot_bytes = 0
        # These caches deliberately live only for this one replay-thread export.  RenderDoc
        # reflection/entry-point objects must never survive a capture or replay session.  The
        # reflection cache key includes every live input to GetShader so a pipeline, stage, or
        # selected-entry change cannot reuse incompatible ABI/layout evidence.
        shader_entry_points_cache = {}
        shader_details_cache = {}
        try:
            for progress_current, event_id in enumerate(event_ids, 1):
                _check_shader_catalog_export_cancel(cancel_event)
                try:
                    _set_frame_event(ctrl, int(event_id), True)
                    ps = ctrl.GetPipelineState()
                    pipeline_id = _get_pipeline_obj(ps, ctrl)
                    pipeline_resource_id = _resource_id_int(pipeline_id)
                except Exception as exc:
                    catalog["errors"].append({
                        "eventId": event_id, "scope": "pipeline", "message": str(exc)})
                    _publish_shader_catalog_progress(
                        progress_binding, event_id, progress_current, len(event_ids))
                    continue

                action = action_info.get(event_id, {})
                for stage_name, stage in stages:
                    _check_shader_catalog_export_cancel(cancel_event)
                    try:
                        shader_id = ps.GetShader(stage)
                        shader_resource_id = _resource_id_int(shader_id)
                        if not shader_resource_id:
                            continue

                        if shader_resource_id not in shader_entry_points_cache:
                            shader_entry_points_cache[shader_resource_id] = tuple(
                                ctrl.GetShaderEntryPoints(shader_id) or [])
                        entries = shader_entry_points_cache[shader_resource_id]
                        if not entries:
                            catalog["errors"].append({
                                "eventId": event_id, "stage": stage_name,
                                "scope": "entry", "message": "No shader entry points"})
                            continue

                        selection = _pipeline_shader_entry_selection(
                            ps, stage, stage_name, shader_id, entries)
                        selected_entry = selection.get("entry")
                        if selected_entry is None:
                            evidence = selection["evidence"]
                            catalog["errors"].append({
                                "eventId": event_id,
                                "stage": stage_name,
                                "shaderResourceId": shader_resource_id,
                                "scope": "entry",
                                "errorId": evidence.get("errorId"),
                                "message": evidence.get("error"),
                                "entryPointSelection": dict(evidence),
                            })
                            continue

                        selected_entry_name = str(
                            getattr(selected_entry, "name", "") or "")
                        details_key = (
                            pipeline_resource_id,
                            shader_resource_id,
                            stage_name,
                            selected_entry_name,
                        )
                        shader_details = shader_details_cache.get(details_key)
                        if shader_details is None:
                            reflection = ctrl.GetShader(
                                pipeline_id, shader_id, selected_entry)
                            if not reflection:
                                catalog["errors"].append({
                                    "eventId": event_id, "stage": stage_name,
                                    "scope": "reflection",
                                    "message": "No shader reflection"})
                                continue
                            owner = _shared_shader_replacements.get(shader_resource_id)
                            if owner is not None:
                                # Catalogs identify captured resources. D3D12 resolves
                                # GetShader through active replacements, so use only
                                # the current owner's proven original reflection.
                                if (owner.get("captureSessionId") != capture_snapshot["captureSessionId"] or
                                        owner.get("captureSessionId") != _capture_session_id or
                                        owner.get("captureToken") != capture_snapshot["captureToken"] or
                                        _shared_shader_replacement_capture_token != capture_snapshot["captureToken"] or
                                        owner.get("api") != _shader_api_token(ctrl) or
                                        _resource_id_int(owner.get("originalResource")) != shader_resource_id):
                                    raise RuntimeError("Shader catalog replacement owner belongs to another capture")
                                reflection = _captured_original_from_shared_owner(
                                    reflection, {"eventId": event_id,
                                        "expectedOriginalResourceId": shader_resource_id,
                                        "expectedOriginalSha256": owner.get("expectedOriginalSha256")},
                                    stage_name, selected_entry_name, owner,
                                    allow_original_active=owner.get("api") in ("d3d11", "vulkan", "opengl"))
                            identity_failure = _shader_reflection_identity_failure(
                                reflection, selected_entry, shader_id,
                                pipeline_id, stage_name, selection)
                            if identity_failure is not None:
                                identity_failure.update({
                                    "eventId": event_id,
                                    "scope": "reflection",
                                })
                                catalog["errors"].append(identity_failure)
                                continue

                            entry_point = str(
                                getattr(reflection, "entryPoint", "") or
                                selected_entry_name)
                            raw_bytes = _shader_raw_bytes(reflection)
                            raw_sha256 = (
                                hashlib.sha256(raw_bytes).hexdigest()
                                if raw_bytes else None)
                            blob_path = (
                                "blobs/%s.bin" % raw_sha256
                                if raw_sha256 else None)
                            if raw_sha256 and raw_sha256 not in blobs:
                                blobs[raw_sha256] = raw_bytes

                            shader_key = "%d:%s:%s:%s" % (
                                shader_resource_id, stage_name, entry_point,
                                raw_sha256 or "no-raw-bytes")

                            constant_blocks = list(getattr(reflection, "constantBlocks", []) or [])
                            dxil_request = None
                            if constant_blocks and _shader_encoding_token(
                                    getattr(reflection, "encoding", "")) == "dxil":
                                dxil_request = {
                                    "sourceBytes": None, "sourceSha256": "", "sourceError": "",
                                    "eventId": event_id, "stage": stage_name,
                                    "shaderKey": shader_key, "rawSha256": raw_sha256,
                                    "boundBlocks": [],
                                }
                                try:
                                    if owner is not None:
                                        # D3D12 DisassembleShader also follows the
                                        # replacement map, even with original reflection.
                                        retained = owner.get("capturedDxilLayoutEvidence")
                                        if not isinstance(retained, dict):
                                            raise RuntimeError(
                                                "Captured-original DXIL layout evidence is unavailable while its Shader is replaced")
                                        dxil_request["retainedLayoutEvidence"] = {
                                            key: dict(marker) for key, marker in retained.items()}
                                    else:
                                        dxil_request["sourceBytes"] = _dxil_disassembly_source(
                                            ctrl, pipeline_id, reflection)
                                        source_size = len(dxil_request["sourceBytes"])
                                        if (source_size > _dxil_access_protocol.MAX_IR_BYTES or
                                                dxil_snapshot_bytes + source_size >
                                                MAX_SHADER_CATALOG_DXIL_SNAPSHOT_BYTES):
                                            raise RuntimeError("DXIL catalog evidence snapshot exceeds its byte budget")
                                        dxil_snapshot_bytes += source_size
                                        dxil_request["sourceSha256"] = hashlib.sha256(
                                            dxil_request["sourceBytes"]).hexdigest()
                                except RuntimeError as exc:
                                    dxil_request["sourceBytes"] = None
                                    dxil_request["sourceError"] = str(exc)

                            reflected_blocks = []
                            dxbc_declarations = _dxbc_cbuffer_layout.declarations(raw_bytes)
                            for block_index, cb in enumerate(constant_blocks):
                                reflected_blocks.append(_constant_block_dict(cb, block_index,
                                    dxbc_declaration=dxbc_declarations.get(
                                        _constant_block_binding_key(cb, block_index))))
                            if dxil_request is not None:
                                dxil_request["blocks"] = reflected_blocks
                                dxil_requests.append(dxil_request)

                            shader_details = {
                                "entryPoint": entry_point,
                                "rawBytes": raw_bytes,
                                "rawSha256": raw_sha256,
                                "blobPath": blob_path,
                                "shaderKey": shader_key,
                                "encoding": str(getattr(
                                    reflection, "encoding", "")),
                                "reflectedBlocks": reflected_blocks,
                                "dxilRequest": dxil_request,
                                "inputSignature": [
                                    _signature_parameter_dict(value)
                                    for value in getattr(
                                        reflection, "inputSignature", [])
                                ],
                                "outputSignature": [
                                    _signature_parameter_dict(value)
                                    for value in getattr(
                                        reflection, "outputSignature", [])
                                ],
                                "readOnlyResources": [
                                    _shader_binding_dict(value, dxbc_declarations.get(('srv',) + _constant_block_binding_key(value, -1)))
                                    for value in getattr(
                                        reflection, "readOnlyResources", [])
                                ],
                                "readWriteResources": [
                                    _shader_binding_dict(value, dxbc_declarations.get(('uav',) + _constant_block_binding_key(value, -1)))
                                    for value in getattr(
                                        reflection, "readWriteResources", [])
                                ],
                                "samplers": [
                                    _shader_sampler_dict(value)
                                    for value in getattr(reflection, "samplers", [])
                                ],
                                "dynamicLinkageInterfaceCount": len(
                                    getattr(reflection, "interfaces", []) or []),
                                "outputTopology": _native_enum_text(
                                    getattr(reflection, "outputTopology", None)),
                                "threadGroupSize": _thread_group_size(reflection),
                            }
                            shader_details_cache[details_key] = shader_details

                        entry_point = shader_details["entryPoint"]
                        raw_bytes = shader_details["rawBytes"]
                        raw_sha256 = shader_details["rawSha256"]
                        blob_path = shader_details["blobPath"]
                        shader_key = shader_details["shaderKey"]
                        reflected_blocks = shader_details["reflectedBlocks"]

                        # Binding identity is event state, so it is intentionally never cached.
                        # Reuse only the already-serialised reflection layout and attach the
                        # exact resource/range returned for this event.
                        bound_blocks = []
                        for block_index, reflected_block in enumerate(reflected_blocks):
                            binding = _get_constant_block_binding(
                                ps, stage, block_index)
                            bound_block = dict(reflected_block)
                            bound_block["binding"] = binding
                            bound_blocks.append(bound_block)
                        if shader_details["dxilRequest"] is not None:
                            shader_details["dxilRequest"]["boundBlocks"].append(bound_blocks)

                        if shader_key not in unique_shaders:
                            shader_record = {
                                "shaderKey": shader_key,
                                "resourceId": shader_resource_id,
                                "shaderResourceId": shader_resource_id,
                                "stage": stage_name,
                                "entry": entry_point,
                                "entryPoint": entry_point,
                                "encoding": shader_details["encoding"],
                                "rawSha256": raw_sha256,
                                "rawSize": len(raw_bytes),
                                "blob": blob_path,
                                "rawPath": blob_path,
                                "constantBlocks": reflected_blocks,
                                # Reflection is the authoritative compiled interface. Names are
                                # retained for display but the external interface hash excludes
                                # non-ABI resource/variable names.
                                "interfaceComplete": not any(
                                    block.get("layoutCompleteness") == "ambiguous"
                                    for block in reflected_blocks),
                                "inputSignature": [
                                    value for value in shader_details["inputSignature"]
                                ],
                                "outputSignature": [
                                    value for value in shader_details["outputSignature"]
                                ],
                                "readOnlyResources": [
                                    value for value in shader_details["readOnlyResources"]
                                ],
                                "readWriteResources": [
                                    value for value in shader_details["readWriteResources"]
                                ],
                                "samplers": [
                                    value for value in shader_details["samplers"]
                                ],
                                "dynamicLinkageInterfaceCount": shader_details[
                                    "dynamicLinkageInterfaceCount"],
                                "outputTopology": shader_details["outputTopology"],
                                "threadGroupSize": shader_details["threadGroupSize"],
                            }
                            aliases = _matching_shader_aliases(
                                shader_resource_id, stage_name, entry_point, raw_sha256)
                            if aliases:
                                shader_record["alias"] = aliases[0]
                                shader_record["displayName"] = _alias_display_name(aliases[0])
                            unique_shaders[shader_key] = shader_record

                        use_record = {
                            "eventId": event_id,
                            "actionName": _stable_action_name(action.get("name", "")),
                            "actionFlags": action.get("flags", 0),
                            "stage": stage_name,
                            "entry": entry_point,
                            "entryPoint": entry_point,
                            "resourceId": shader_resource_id,
                            "rawSha256": raw_sha256,
                            "shaderKey": shader_key,
                            "constantBlocks": bound_blocks,
                        }
                        catalog["uses"].append(use_record)
                    except Exception as exc:
                        catalog["errors"].append({
                            "eventId": event_id, "stage": stage_name,
                            "scope": "shader", "message": str(exc)})
                _publish_shader_catalog_progress(
                    progress_binding, event_id, progress_current, len(event_ids))
        finally:
            if restore_original_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception as exc:
                    catalog["errors"].append({
                        "eventId": original_event, "scope": "restore_event",
                        "message": str(exc)})

        catalog["shaders"] = sorted(
            unique_shaders.values(),
            key=lambda item: (item["resourceId"], item["stage"], item["entry"]))
        catalog["counts"] = {
            "events": len(event_ids),
            "shaderUses": len(catalog["uses"]),
            "uniqueShaders": len(catalog["shaders"]),
            "uniqueBlobs": len(blobs),
            "errors": len(catalog["errors"]),
        }
        # Only plain dictionaries and owned bytes leave this callback. The
        # entries/PSO/reflection caches above die with the replay stack frame.
        catalog["_dxilEvidenceRequests"] = dxil_requests
        return catalog, blobs

    # Legacy callers synchronously enter the replay thread. The project restore
    # path supplies the controller from ReplayManager.AsyncInvoke instead, so
    # qrenderdoc's GUI thread never waits for the full-frame traversal.
    if replay_controller is None:
        catalog, blobs = _replay(_do)
    else:
        catalog, blobs = _do(replay_controller)
    _check_shader_catalog_export_cancel(cancel_event)
    collected = {
        "catalog": catalog, "blobs": blobs, "captureSnapshot": dict(capture_snapshot),
        "outputDir": output_dir, "blobDirectory": blob_dir,
        "expectedCaptureId": expected_capture_id,
        "expectedIdentitySha256": expected_identity_sha256,
        "expectedStableCaptureId": expected_stable_capture_id,
        "expectedStableIdentitySha256": expected_stable_identity_sha256,
        "activateCatalogIfValid": activate_catalog_if_valid,
    }
    if defer_finalization:
        return collected
    if replay_controller is not None:
        raise RuntimeError("Replay-thread catalog collection requires deferred finalization")
    return _finalize_shader_catalog_export(
        collected, cancel_event=cancel_event, defer_publication=defer_publication)


def _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot):
    # No ReplayManager/ICaptureContext/SWIG access on the CPU worker. Native
    # foreground preemption is checked at collection and at UI publication.
    dispatch = _request_dispatch_context()
    dispatch_cancel = dispatch.get("cancelEvent") if dispatch is not None else None
    if (_shader_catalog_finalize_stopping or
            (cancel_event is not None and cancel_event.is_set()) or
            (dispatch_cancel is not None and dispatch_cancel.is_set())):
        raise _ShaderCatalogExportCancelled("Shader catalog export cancelled")
    if (capture_snapshot.get("captureSessionId") != _capture_session_id or
            capture_snapshot.get("captureToken") != _active_capture_token):
        raise RuntimeError("Capture changed during Shader catalog export")


def _finalize_shader_catalog_export(collected, cancel_event=None, defer_publication=False):
    """Finish copied native evidence off the replay queue, before any publication."""
    catalog, blobs = collected["catalog"], collected["blobs"]
    capture_snapshot = collected["captureSnapshot"]
    output_dir, blob_dir = collected["outputDir"], collected["blobDirectory"]
    expected_capture_id = collected["expectedCaptureId"]
    expected_identity_sha256 = collected["expectedIdentitySha256"]
    expected_stable_capture_id = collected.get("expectedStableCaptureId", "")
    expected_stable_identity_sha256 = collected.get("expectedStableIdentitySha256", "")
    activate_catalog_if_valid = bool(collected.get("activateCatalogIfValid", False))
    _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
    for raw_sha256, raw_bytes in blobs.items():
        if not isinstance(raw_bytes, bytes) or hashlib.sha256(raw_bytes).hexdigest() != raw_sha256:
            raise RuntimeError("Shader catalog captured bytecode identity changed")
    for request in catalog.pop("_dxilEvidenceRequests", []):
        _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
        blocks = request["blocks"]
        if request["rawSha256"] and request["rawSha256"] not in blobs:
            raise RuntimeError("Shader catalog DXIL evidence lost its captured bytecode")
        retained_evidence = request.get("retainedLayoutEvidence")
        if retained_evidence is None and not request["sourceError"] and (
                not isinstance(request["sourceBytes"], bytes) or
                hashlib.sha256(request["sourceBytes"]).hexdigest() != request["sourceSha256"]):
            raise RuntimeError("Shader catalog captured disassembly identity changed")
        try:
            if retained_evidence is not None:
                evidence = retained_evidence
            elif request["sourceError"]:
                raise RuntimeError(request["sourceError"])
            else:
                unused_access, evidence = _dxil_evidence_from_snapshot(request["sourceBytes"], blocks)
        except RuntimeError as exc:
            evidence = _dxil_layout_evidence_from_snapshot(blocks, "unavailable")
            catalog["errors"].append({
                "eventId": request["eventId"], "stage": request["stage"],
                "scope": "dxil-cbuffer-layout-evidence", "message": str(exc),
            })
        finally:
            # No later phase needs the printer text. In particular neither the
            # completed job nor its publication receipt retains native IR.
            request["sourceBytes"] = None
        _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
        for block_set in [blocks] + request["boundBlocks"]:
            for block in block_set:
                marker = evidence.get((block["space"], block["bind"]))
                if marker is not None:
                    block["layoutCompleteness"] = "ambiguous"
                    block["layoutEvidence"] = dict(marker)
    for shader in catalog["shaders"]:
        if "constantBlocks" in shader:
            shader["interfaceComplete"] = not any(
                block.get("layoutCompleteness") == "ambiguous"
                for block in shader["constantBlocks"])
    catalog["counts"]["errors"] = len(catalog["errors"])
    _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
    catalog["captureId"] = _catalog_capture_id(catalog)
    catalog["stableCaptureId"] = _catalog_stable_capture_id(catalog)
    identity_evidence_sha256 = _catalog_identity_evidence_sha256(catalog)
    stable_identity_evidence_sha256 = _catalog_stable_identity_evidence_sha256(catalog)
    # A restart rebind is an atomic compare-before-publish transaction. Never let a
    # failed expected export enter _known_catalog_capture_ids or replace
    # _symbol_capture_snapshot: another Host request may use those process-local
    # facts as its capture-identity fast path.
    if expected_stable_capture_id:
        # The capture-independent gate. ResourceIds are reassigned on every open, so
        # comparing them here would refuse a workspace whose Shader has not changed
        # by one byte. The volatile captureId is still reported, never enforced.
        if catalog["stableCaptureId"] != expected_stable_capture_id:
            raise RuntimeError(
                "Live Shader catalog did not match expected_stable_capture_id (%s)"
                % _catalog_capture_id_description(catalog, expected_stable_capture_id))
        if stable_identity_evidence_sha256 != expected_stable_identity_sha256:
            raise RuntimeError(
                "Live Shader catalog selection/Shader/use evidence changed "
                "(selection=%s, uses=%d, shaders=%d)"
                % (json.dumps(catalog.get("selection", {}), ensure_ascii=False,
                              sort_keys=True)[:200],
                   len(catalog.get("uses", []) or []),
                   len(catalog.get("shaders", []) or [])))
    elif expected_capture_id:
        if catalog["captureId"] != expected_capture_id:
            raise RuntimeError(
                "Live Shader catalog did not match expected_capture_id (%s)"
                % _catalog_capture_id_description(catalog, expected_capture_id))
        if identity_evidence_sha256 != expected_identity_sha256:
            raise RuntimeError(
                "Live Shader catalog selection/Shader/use evidence changed "
                "(selection=%s, uses=%d, shaders=%d)"
                % (json.dumps(catalog.get("selection", {}), ensure_ascii=False,
                              sort_keys=True)[:200],
                   len(catalog.get("uses", []) or []),
                   len(catalog.get("shaders", []) or [])))

    native_blob_dir = _native_filesystem_path(blob_dir)
    if not os.path.exists(native_blob_dir):
        os.makedirs(native_blob_dir)
    for raw_sha256, raw_bytes in blobs.items():
        _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
        blob_path = os.path.join(blob_dir, "%s.bin" % raw_sha256)
        native_blob_path = _native_filesystem_path(blob_path)
        must_write = True
        if os.path.isfile(native_blob_path):
            try:
                with open(native_blob_path, "rb") as existing:
                    existing_hash = hashlib.sha256(existing.read()).hexdigest()
                must_write = existing_hash != raw_sha256
            except Exception:
                must_write = True
        if must_write:
            _atomic_write_bytes(blob_path, raw_bytes)

    _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
    catalog_path = os.path.join(output_dir, "shader_catalog.v1.json")
    _atomic_write_json(catalog_path, catalog)
    _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
    if (capture_snapshot.get("captureSessionId") != _capture_session_id or
            capture_snapshot.get("captureToken") != _active_capture_token):
        raise RuntimeError("Capture changed before Shader catalog publication")
    result = {
        "schema": SYMBOL_CATALOG_SCHEMA,
        "schemaVersion": SYMBOL_CATALOG_VERSION,
        "captureId": catalog["captureId"],
        "captureSessionId": capture_snapshot["captureSessionId"],
        "catalogPath": catalog_path,
        "blobDirectory": blob_dir,
        "counts": catalog["counts"],
    }
    result["identityEvidenceSha256"] = identity_evidence_sha256
    result["stableCaptureId"] = catalog["stableCaptureId"]
    result["stableIdentityEvidenceSha256"] = stable_identity_evidence_sha256
    if expected_capture_id or expected_stable_capture_id:
        result["expectedIdentityValidatedBeforeCache"] = True
    if activate_catalog_if_valid:
        result["activeCatalogPublished"] = True
    # Hashing, validation, and Shader/use indexing can be proportional to the
    # entire frame, so prepare the publication on the CPU/request worker.
    # Only its short checked state/name commit may touch CaptureContext on Qt.
    publication = _prepare_catalog_cache_publication(
        catalog, identity_evidence_sha256,
        identity_only=bool(
            (expected_capture_id or expected_stable_capture_id)
            and not activate_catalog_if_valid
        ),
        # An explicit expected-identity activation is the one safe place to
        # switch bounded symbol catalogs automatically.  The expected catalog
        # was validated above; the UI commit will first recover any old strict
        # alias transaction while its original catalog is still active.
        recover_aliases_before_switch=activate_catalog_if_valid,
    )
    if defer_publication:
        result["_deferredPublication"] = publication
    else:
        def _commit_on_ui():
            _check_shader_catalog_export_cancel(cancel_event)
            _check_shader_catalog_finalize_cancel(cancel_event, capture_snapshot)
            if (capture_snapshot.get("captureSessionId") != _capture_session_id or
                    capture_snapshot.get("captureToken") != _active_capture_token):
                raise RuntimeError(
                    "Capture changed before Shader catalog cache publication")
            _commit_catalog_cache_publication(publication)

        _invoke_on_ui_sync(_commit_on_ui)
    return result


def _shader_catalog_export_job_id(value):
    text = str(value or "")
    if (len(text) != 32 or
            any(character not in "0123456789abcdef" for character in text)):
        raise ValueError("job_id must be 32 lowercase hexadecimal characters")
    return text


def _shader_catalog_export_job_snapshot(job):
    value = {
        "schema": "replaylab-shader-catalog-export-job/v1",
        "schemaVersion": 1,
        "jobId": job["jobId"],
        "status": job["status"],
        "captureSessionId": job["captureSessionId"],
        "cancellationRequested": job.get("cancelRequested") is True,
        "current": _safe_int(job.get("current"), 0),
        "total": _safe_int(job.get("total"), 0),
        "eventId": _safe_int(job.get("eventId"), 0),
    }
    if job["status"] in ("failed", "cancelled"):
        value["error"] = str(job.get("error", "") or "")[:4096]
    return value


def _request_shader_catalog_export_cancel(job, now, reason):
    if job.get("status") not in ("queued", "running"):
        return False
    cancel_event = job.get("cancelEvent")
    if cancel_event is not None:
        cancel_event.set()
    if job.get("cancelRequested") is not True:
        job["cancelRequested"] = True
        job["cancelRequestedMonotonic"] = now
        job["error"] = str(reason or "Shader catalog export cancelled")
        job["updatedMonotonic"] = now
    if job.get("status") == "queued":
        job["status"] = "cancelled"
        job["finishedMonotonic"] = now
    return True


def _cleanup_shader_catalog_export_jobs(now):
    for job in _shader_catalog_export_jobs.values():
        if (job.get("status") in ("queued", "running") and
                job.get("cancelRequested") is not True and
                now - float(job.get("createdMonotonic", now)) >=
                SHADER_CATALOG_EXPORT_JOB_TIMEOUT_SECONDS):
            _request_shader_catalog_export_cancel(
                job, now, "Shader catalog export timed out")
    expired = [
        job_id for job_id, job in _shader_catalog_export_jobs.items()
        if (job.get("status") in ("completed", "failed", "cancelled") and
            now - float(job.get("updatedMonotonic", now)) >=
            SHADER_CATALOG_EXPORT_JOB_TTL_SECONDS)
    ]
    for job_id in expired:
        _shader_catalog_export_jobs.pop(job_id, None)


def _update_shader_catalog_export_progress(job_id, event_id, current, total):
    """Publish replay-thread progress into a lock-protected lightweight snapshot."""
    with _shader_catalog_export_jobs_guard:
        job = _shader_catalog_export_jobs.get(str(job_id or ""))
        if job is None or job.get("status") != "running":
            return False
        current_value = _safe_int(current, 0)
        total_value = _safe_int(total, 0)
        if (current_value < job.get("current", 0) or total_value < 1 or
                current_value < 1 or current_value > total_value):
            return False
        job["current"] = current_value
        job["total"] = total_value
        job["eventId"] = _safe_int(event_id, 0)
        job["updatedMonotonic"] = time.monotonic()
    # The replay callback runs Python on RenderDoc's replay thread. Some replay
    # API calls retain the embedded interpreter long enough that the GUI-side
    # JSON poller would otherwise wait several seconds to acquire it. Yield at
    # the EID boundary, after publishing a consistent snapshot, so Qt can paint
    # and answer the next lightweight poll without moving replay work onto the
    # GUI thread. A bounded 1 ms handoff avoids Windows ``Sleep(0)`` immediately
    # rescheduling this replay callback before the waiting GUI thread runs.
    time.sleep(SHADER_CATALOG_EXPORT_UI_YIELD_SECONDS)
    return True


def _run_shader_catalog_export_job(job_id, ctrl):
    with _shader_catalog_export_jobs_guard:
        job = _shader_catalog_export_jobs.get(job_id)
        if job is None or job.get("status") != "queued":
            return
        job["status"] = "running"
        job["updatedMonotonic"] = time.monotonic()
        params = job["params"]
        capture_snapshot = job["captureSnapshot"]
        cancel_event = job["cancelEvent"]
    try:
        _check_shader_catalog_export_cancel(cancel_event)
        if capture_snapshot.get("captureSessionId") != _capture_session_id:
            raise RuntimeError("Capture changed before Shader catalog export")
        collected = _export_shader_catalog(
            params, replay_controller=ctrl,
            capture_snapshot=capture_snapshot,
            cancel_event=cancel_event, progress_job_id=job_id,
            defer_publication=True, defer_finalization=True)
        _check_shader_catalog_export_cancel(cancel_event)
        with _shader_catalog_export_jobs_guard:
            if (_shader_catalog_finalize_stopping or
                    _shader_catalog_export_jobs.get(job_id) is not job or
                    job.get("status") != "running" or cancel_event.is_set()):
                raise _ShaderCatalogExportCancelled("Shader catalog export cancelled")
            worker = threading.Thread(
                target=_finish_shader_catalog_export_job,
                args=(job_id, collected),
                name="ReplayLabCatalogCPU-" + job_id[:8])
            worker.daemon = True
            _shader_catalog_finalize_workers.add(worker)
            try:
                worker.start()
            except Exception:
                _shader_catalog_finalize_workers.discard(worker)
                raise
        # Never wait for parsing on the replay queue. No closure passed to the
        # worker captures this controller or any native reflection object.
    except Exception as exc:
        _fail_shader_catalog_export_job(job_id, job, exc)


def _fail_shader_catalog_export_job(job_id, job, exc):
    with _shader_catalog_export_jobs_guard:
        if (_shader_catalog_export_jobs.get(job_id) is not job or
                job.get("status") != "running"):
            return
        cancelled = (isinstance(exc, _ShaderCatalogExportCancelled) or
                     job["cancelEvent"].is_set())
        if not job.get("error"):
            job["error"] = "%s: %s" % (type(exc).__name__, exc)
        job["status"] = "cancelled" if cancelled else "failed"
        job["updatedMonotonic"] = time.monotonic()
        job["finishedMonotonic"] = job["updatedMonotonic"]


def _finish_shader_catalog_export_job(job_id, collected):
    """CPU-only worker; completion is still inert until consume on Qt."""
    job = None
    try:
        with _shader_catalog_export_jobs_guard:
            job = _shader_catalog_export_jobs.get(job_id)
            if job is None or job.get("status") != "running":
                return
            cancel_event = job["cancelEvent"]
        result = _finalize_shader_catalog_export(
            collected, cancel_event=cancel_event, defer_publication=True)
        publication = result.pop("_deferredPublication", None)
        if not isinstance(publication, dict):
            raise RuntimeError("Shader catalog export publication is incomplete")
        _check_shader_catalog_finalize_cancel(cancel_event, collected["captureSnapshot"])
        with _shader_catalog_export_jobs_guard:
            current = _shader_catalog_export_jobs.get(job_id)
            if current is not job or job.get("status") != "running":
                return
            _check_shader_catalog_finalize_cancel(cancel_event, collected["captureSnapshot"])
            job["result"] = result
            job["publication"] = publication
            job["status"] = "completed"
            job["updatedMonotonic"] = time.monotonic()
            job["finishedMonotonic"] = job["updatedMonotonic"]
    except Exception as exc:
        if job is not None:
            _fail_shader_catalog_export_job(job_id, job, exc)
    finally:
        with _shader_catalog_export_jobs_guard:
            _shader_catalog_finalize_workers.discard(threading.current_thread())


def _stop_shader_catalog_finalize_workers():
    """Hard shutdown gate: no catalog writer survives Python finalization."""
    global _shader_catalog_finalize_stopping
    with _shader_catalog_export_jobs_guard:
        _shader_catalog_finalize_stopping = True
        now = time.monotonic()
        for job in _shader_catalog_export_jobs.values():
            _request_shader_catalog_export_cancel(job, now, "Shader catalog export stopped")
        workers = tuple(_shader_catalog_finalize_workers)
    deadline = time.monotonic() + IPC_WORKER_STOP_TIMEOUT_SECONDS
    for worker in workers:
        worker.join(max(0.0, deadline - time.monotonic()))
    if any(worker.is_alive() for worker in workers):
        raise RuntimeError("Shader catalog CPU worker is still stopping")


def _begin_export_shader_catalog(params):
    """Queue a full catalog traversal without blocking qrenderdoc's GUI timer."""
    if not isinstance(params, dict):
        raise ValueError("Shader catalog export parameters must be an object")
    capture_snapshot = _shader_catalog_export_capture_snapshot()
    # Reject malformed cheap fields before consuming the bounded replay queue.
    output_dir = str(params.get("output_dir", "") or "").strip()
    if not output_dir:
        raise ValueError("output_dir required")
    _parse_catalog_event_ids(params.get("event_ids", params.get("eventIds")))
    if not _available_shader_stages(params.get("stages")):
        raise ValueError("No valid shader stages requested")
    replay_manager = _ctx.Replay()
    now = time.monotonic()
    with _shader_catalog_export_jobs_guard:
        if _shader_catalog_finalize_stopping:
            raise RuntimeError("Shader catalog export is stopping")
        _cleanup_shader_catalog_export_jobs(now)
        if len(_shader_catalog_export_jobs) >= MAX_SHADER_CATALOG_EXPORT_JOBS:
            raise RuntimeError("The Shader catalog export queue is full")
        job_id = uuid.uuid4().hex
        cancel_event = threading.Event()
        cancel_event.replaylabForegroundGeneration = (
            _replay_foreground_generation(replay_manager))
        cancel_event.replaylabReplayManager = replay_manager
        job = {
            "jobId": job_id,
            "status": "queued",
            "captureSessionId": capture_snapshot["captureSessionId"],
            "params": dict(params),
            "captureSnapshot": capture_snapshot,
            "createdMonotonic": now,
            "updatedMonotonic": now,
            "finishedMonotonic": None,
            "result": None,
            "publication": None,
            "error": "",
            "cancelEvent": cancel_event,
            "replayManager": replay_manager,
            "cancelRequested": False,
            "current": 0,
            "total": 0,
            "eventId": 0,
        }
        _shader_catalog_export_jobs[job_id] = job
    try:
        callback = (lambda ctrl, token=job_id:
                    _run_shader_catalog_export_job(token, ctrl))
        # This begin-handler is GUI-thread-only, so obtaining the manager here
        # is safe. Deliberately require the tagged overload: silently falling
        # back to the legacy lane would let a long catalog job monopolise user
        # replay work on builds that lack background scheduling support.
        _ctx.Replay().AsyncInvoke(
            callback, SHADER_CATALOG_REPLAY_TAG_PREFIX + job_id)
    except Exception:
        with _shader_catalog_export_jobs_guard:
            _shader_catalog_export_jobs.pop(job_id, None)
        raise
    return _shader_catalog_export_job_snapshot(job)


def _poll_export_shader_catalog(params):
    job_id = _shader_catalog_export_job_id(params.get("job_id"))
    with _shader_catalog_export_jobs_guard:
        _cleanup_shader_catalog_export_jobs(time.monotonic())
        job = _shader_catalog_export_jobs.get(job_id)
        if job is None or job.get("captureSessionId") != _capture_session_id:
            raise ValueError("Unknown or expired Shader catalog export job")
        return _shader_catalog_export_job_snapshot(job)


def _cancel_export_shader_catalog(params):
    job_id = _shader_catalog_export_job_id(params.get("job_id"))
    with _shader_catalog_export_jobs_guard:
        now = time.monotonic()
        _cleanup_shader_catalog_export_jobs(now)
        job = _shader_catalog_export_jobs.get(job_id)
        if job is None or job.get("captureSessionId") != _capture_session_id:
            raise ValueError("Unknown or expired Shader catalog export job")
        _request_shader_catalog_export_cancel(
            job, now, "Shader catalog export cancellation requested")
        return _shader_catalog_export_job_snapshot(job)


def _consume_export_shader_catalog(params):
    job_id = _shader_catalog_export_job_id(params.get("job_id"))
    with _shader_catalog_export_jobs_guard:
        _cleanup_shader_catalog_export_jobs(time.monotonic())
        job = _shader_catalog_export_jobs.get(job_id)
        if job is None or job.get("captureSessionId") != _capture_session_id:
            raise ValueError("Unknown or expired Shader catalog export job")
        if (job.get("status") != "completed" or
                not isinstance(job.get("result"), dict) or
                not isinstance(job.get("publication"), dict)):
            raise RuntimeError("Shader catalog export job is not completed")
        capture_snapshot = job.get("captureSnapshot", {})
        _check_shader_catalog_export_cancel(job["cancelEvent"])
        _check_shader_catalog_finalize_cancel(job["cancelEvent"], capture_snapshot)
        if (capture_snapshot.get("captureSessionId") != _capture_session_id or
                capture_snapshot.get("captureToken") != _active_capture_token):
            raise RuntimeError("Capture changed before Shader catalog publication")
        _commit_catalog_cache_publication(job["publication"])
        value = _shader_catalog_export_job_snapshot(job)
        value["result"] = job["result"]
        _shader_catalog_export_jobs.pop(job_id, None)
        return value


def _normalise_alias_records(data):
    raw_aliases = data.get("aliases", [])
    if not raw_aliases and isinstance(data.get("shaderAliases"), list):
        raw_aliases = data.get("shaderAliases")

    if isinstance(raw_aliases, list):
        return [alias for alias in raw_aliases if isinstance(alias, dict)]

    if isinstance(raw_aliases, dict):
        result = []
        for key, value in raw_aliases.items():
            if isinstance(value, dict):
                alias = dict(value)
            else:
                alias = {"displayName": str(value)}
            if ("resourceId" not in alias and "shaderResourceId" not in alias and
                    "rawSha256" not in alias):
                if str(key).isdigit():
                    alias["shaderResourceId"] = int(key)
                elif len(str(key)) == 64:
                    alias["rawSha256"] = str(key)
            result.append(alias)
        return result
    raise ValueError("aliases must be a list or object")


def _commit_symbol_aliases_on_ui(plan):
    """Apply one prepared alias plan as a single GUI-thread transaction."""
    global _symbol_alias_overlay, _symbol_resource_renames
    global _symbol_rename_capture_token, _symbol_alias_recovery_ledger
    global _symbol_alias_last_rollback_receipt

    if not _ctx or not _ctx.IsCaptureLoaded():
        raise RuntimeError("No capture loaded")
    if str(_capture_session_id or "") != plan["captureSessionId"]:
        raise RuntimeError("Capture changed before symbol alias commit")
    if _current_capture_token() != plan["captureToken"]:
        raise RuntimeError("Capture changed before symbol alias commit")
    if _symbol_capture_snapshot is not plan["captureSnapshot"]:
        raise RuntimeError("Shader catalog changed before symbol alias commit")
    if (_symbol_alias_overlay is not plan["originalOverlay"] or
            _symbol_resource_renames is not plan["originalResourceRenames"] or
            _symbol_rename_capture_token != plan["originalRenameCaptureToken"] or
            _symbol_alias_recovery_ledger is not plan["originalRecoveryLedger"]):
        raise RuntimeError("Symbol alias state changed before commit")

    strict_atomic = plan["strictAtomic"]
    snapshot_capture_id = plan["snapshotCaptureId"]
    skipped = plan["skipped"]
    conflicts = plan["conflicts"]
    resources = _context_resource_ids()
    rename_plan = []
    kept_user = []
    for resource_id in sorted(plan["renameCandidates"].keys()):
        names = sorted(plan["renameCandidates"][resource_id])
        kinds = sorted(plan.get("renameCandidateKinds", {}).get(resource_id, ()))
        if len(names) != 1:
            conflicts.append({
                "target": ["shader-resource", resource_id], "displayNames": names})
            continue
        if len(kinds) != 1:
            conflicts.append({
                "target": ["capture-resource", resource_id],
                "bindingKinds": kinds,
                "displayNames": names,
            })
            continue
        rid = resources.get(resource_id)
        if rid is None:
            skipped.append({
                "resourceId": resource_id,
                "displayName": names[0],
                "reason": "resource ID is not present in the current capture",
            })
            continue
        kind = kinds[0]
        if kind in ("shader", "textureresource"):
            try:
                current_custom = bool(_ctx.HasResourceCustomName(rid))
                current_name = str(
                    _ctx.GetResourceNameUnsuffixed(rid) or "")
                managed = _symbol_resource_renames.get(resource_id)
                managed = managed if isinstance(managed, dict) else {}
                managed_name = str(managed.get("managedName", "") or "")
                legacy_shader_ownership = bool(
                    kind == "shader" and managed and not managed_name)
                bread_still_owns = bool(
                    legacy_shader_ownership or (
                        managed.get("bindingKind") == kind
                        and managed_name
                        and current_custom
                        and current_name == managed_name))
                user_took_over = bool(
                    managed_name and not bread_still_owns)
                if ((current_custom and not bread_still_owns) or
                        user_took_over):
                    kept_user.append({
                        "resourceId": resource_id,
                        "displayName": current_name,
                        "hadCustomName": current_custom,
                        "requestedDisplayName": names[0],
                        "bindingKind": kind,
                    })
                    continue
            except Exception as exc:
                skipped.append({
                    "resourceId": resource_id,
                    "displayName": names[0],
                    "reason": "could not inspect existing custom name: %s" % str(exc),
                })
                continue
        rename_plan.append((resource_id, rid, names[0], kind))

    transaction_resource_ids = set(_symbol_resource_renames)
    transaction_resource_ids.update(item[0] for item in rename_plan)
    if len(transaction_resource_ids) > MAX_SYMBOL_ALIAS_UI_RENAME_RESOURCES:
        raise RuntimeError(
            "Symbol alias UI rename transaction exceeds the %d-resource limit"
            % MAX_SYMBOL_ALIAS_UI_RENAME_RESOURCES)

    kept_targets = set(
        (item["bindingKind"], item["resourceId"]) for item in kept_user)
    if kept_targets:
        effective_overlay = dict(plan["newOverlay"])
        effective_overlay["aliases"] = [
            alias for alias in plan["newOverlay"].get("aliases", [])
            if (_alias_kind(alias), _alias_target_resource_id(alias))
            not in kept_targets
        ]
        plan["newOverlay"] = effective_overlay

    logical_mutation = (
        plan["newOverlay"].get("aliases", []) !=
        _symbol_alias_overlay.get("aliases", []))
    if strict_atomic and (skipped or conflicts):
        details = []
        for item in list(skipped)[:3]:
            reason = str(item.get("reason", "") or "").strip()
            if reason and reason not in details:
                details.append(reason)
        suffix = ("; first reasons: " + " | ".join(details)) if details else ""
        raise ValueError(
            "Strict atomic alias load rejected %d skipped aliases and %d conflicts%s"
            % (len(skipped), len(conflicts), suffix))
    if strict_atomic and not transaction_resource_ids and not logical_mutation:
        # The only requested physical names were user-owned and the active
        # logical overlay is unchanged.  Report the preserved names without
        # manufacturing an empty recovery transaction.
        return {
            "schema": SYMBOL_ALIAS_SCHEMA,
            "schemaVersion": plan["version"],
            "captureId": snapshot_capture_id,
            "captureSessionId": str(_capture_session_id or ""),
            "path": plan["path"],
            "confirmedOnly": plan["confirmedOnly"],
            "strictAtomic": True,
            "atomicity": "no-mutation",
            "physicalAtomic": False,
            "recoveryRequired": False,
            "rollbackAvailable": False,
            "recoveryLedgerPublished": False,
            "transactionId": "",
            "operationId": plan["operationId"],
            "idempotent": False,
            "committed": True,
            "mutationPresent": False,
            "counts": {
                "manifestAliases": len(plan["allAliases"]),
                "deterministicAliases": len(plan["candidates"]),
                "liveBoundAliases": len(plan["liveCandidates"]),
                "activeValidatedAliases": len(plan["activeAliases"]),
                "renamedShaders": 0,
                "renamedTextures": 0,
                "renamedResources": 0,
                "keptUser": len(kept_user),
                "skipped": len(skipped),
                "conflicts": len(conflicts),
            },
            "applied": [],
            "written": [],
            "replacedManaged": [],
            "keptUser": kept_user,
            "skipped": skipped,
            "conflicts": conflicts,
        }

    applied = []
    written = []
    replaced_managed = []
    if strict_atomic:
        # Strict means complete-or-recovery-required, not physical atomicity:
        # validate everything first, publish a capture-bound recovery ledger,
        # then perform and verify the ordered qrenderdoc name updates.
        if skipped or conflicts:
            details = []
            for item in list(skipped)[:3]:
                reason = str(item.get("reason", "") or "").strip()
                if reason and reason not in details:
                    details.append(reason)
            suffix = ("; first reasons: " + " | ".join(details)) if details else ""
            raise ValueError(
                "Strict atomic alias load rejected %d skipped aliases and %d conflicts%s"
                % (len(skipped), len(conflicts), suffix))

        previous_renames = _symbol_resource_renames
        binding = _symbol_alias_binding(snapshot_capture_id)
        transaction_capture_token = binding["captureToken"]
        if (previous_renames and _symbol_rename_capture_token !=
                transaction_capture_token):
            raise RuntimeError(
                "Strict atomic alias load cannot restore names from another capture")
        previous_names = {}
        transaction_resources = set(transaction_resource_ids)
        if len(transaction_resources) > MAX_SYMBOL_ALIAS_RECOVERY_RESOURCES:
            raise RuntimeError(
                "Strict alias transaction exceeds the bounded recovery ledger")
        for resource_id in sorted(transaction_resources):
            rid = resources.get(resource_id)
            if rid is None:
                raise RuntimeError(
                    "Strict atomic alias load cannot restore resource %d"
                    % resource_id)
            try:
                had_custom_name = bool(_ctx.HasResourceCustomName(rid))
                current_name = str(
                    _ctx.GetResourceNameUnsuffixed(rid) or "")
            except Exception as exc:
                raise RuntimeError(
                    "Strict atomic alias load could not snapshot resource %d: %s"
                    % (resource_id, str(exc)))
            previous_names[resource_id] = {
                "rid": rid,
                "hadCustomName": had_custom_name,
                "name": current_name,
            }

        desired_names = {}
        for resource_id, original in previous_renames.items():
            desired_names[resource_id] = {
                "hadCustomName": bool(original.get("hadCustomName")),
                "name": str(original.get("name", "") or ""),
            }
        new_names = {item[0]: item[2] for item in rename_plan}
        for resource_id, display_name in new_names.items():
            desired_names[resource_id] = {
                "hadCustomName": True,
                "name": display_name,
            }

        recovery_ledger = {
            "schema": "renderdoc-ultra-alias-recovery-ledger/v1",
            "transactionId": plan["operationId"],
            "captureId": binding["captureId"],
            "captureSessionId": binding["captureSessionId"],
            "captureToken": binding["captureToken"],
            "state": "pending",
            "manifestSha256": plan["expectedSha256"],
            "originalOverlay": _symbol_alias_overlay,
            "originalResourceRenames": _symbol_alias_rename_ledger_copy(
                previous_renames),
            "originalRenameCaptureToken": _symbol_rename_capture_token,
            "resources": previous_names,
            "managedNames": {
                resource_id: dict(desired)
                for resource_id, desired in desired_names.items()
            },
        }
        # This assignment is the transaction's write-ahead publication point.
        # Nothing below may call SetResourceCustomName without this exact ledger.
        _symbol_alias_recovery_ledger = recovery_ledger
        _symbol_alias_last_rollback_receipt = None
        try:
            for resource_id in sorted(transaction_resources):
                desired = desired_names[resource_id]
                _ctx.SetResourceCustomName(
                    previous_names[resource_id]["rid"],
                    desired["name"] if desired["hadCustomName"] else "")
            for resource_id in sorted(transaction_resources):
                desired = desired_names[resource_id]
                rid = previous_names[resource_id]["rid"]
                actual_custom = bool(_ctx.HasResourceCustomName(rid))
                actual_name = str(_ctx.GetResourceNameUnsuffixed(rid) or "")
                if (actual_custom != desired["hadCustomName"] or
                        (desired["hadCustomName"] and
                         actual_name != desired["name"])):
                    raise RuntimeError(
                        "resource %d did not verify its requested custom name"
                        % resource_id)
        except Exception as exc:
            try:
                _restore_symbol_alias_recovery_ledger(
                    recovery_ledger, snapshot_capture_id)
            except Exception as rollback_exc:
                raise RuntimeError(
                    "Strict alias rename failed (%s); immediate rollback was "
                    "incomplete and recovery remains required for transaction %s: %s"
                    % (str(exc), recovery_ledger["transactionId"],
                       str(rollback_exc)))
            raise RuntimeError(
                "Strict alias rename failed and verified immediate rollback restored "
                "the previous overlay: %s"
                % str(exc))

        new_renames = {}
        for resource_id, unused_rid, display_name, binding_kind in rename_plan:
            baseline = previous_renames.get(
                resource_id, previous_names[resource_id])
            new_renames[resource_id] = {
                "hadCustomName": bool(baseline.get("hadCustomName")),
                "name": str(baseline.get("name", "") or ""),
                "managedName": display_name,
                "bindingKind": binding_kind,
            }
            receipt = {
                "resourceId": resource_id,
                "displayName": display_name,
            }
            typed_receipt = {
                **receipt,
                "bindingKind": binding_kind,
            }
            applied.append(receipt)
            if resource_id in previous_renames:
                replaced_managed.append(typed_receipt)
            else:
                written.append(typed_receipt)

        # Every fallible replay/UI operation completed. Publish the complete
        # capture-bound state only now.
        _symbol_alias_overlay = plan["newOverlay"]
        _symbol_resource_renames = new_renames
        _symbol_rename_capture_token = (
            transaction_capture_token if applied else None)
        recovery_ledger["state"] = "committed"
    else:
        # Historical callers retain their best-effort behaviour.
        previous_renames = dict(_symbol_resource_renames)
        _reset_symbol_overlay(restore_names=True)
        _symbol_alias_overlay = plan["newOverlay"]
        for resource_id, rid, display_name, binding_kind in rename_plan:
            try:
                had_custom_name = bool(_ctx.HasResourceCustomName(rid))
                original_name = str(
                    _ctx.GetResourceNameUnsuffixed(rid) or "")
                _symbol_resource_renames[resource_id] = {
                    "hadCustomName": had_custom_name,
                    "name": original_name,
                    "managedName": display_name,
                    "bindingKind": binding_kind,
                }
                _ctx.SetResourceCustomName(rid, display_name)
                receipt = {
                    "resourceId": resource_id,
                    "displayName": display_name,
                }
                typed_receipt = {
                    **receipt,
                    "bindingKind": binding_kind,
                }
                applied.append(receipt)
                if resource_id in previous_renames:
                    replaced_managed.append(typed_receipt)
                else:
                    written.append(typed_receipt)
            except Exception as exc:
                skipped.append({
                    "resourceId": resource_id,
                    "displayName": display_name,
                    "reason": str(exc),
                })
        if applied:
            _symbol_rename_capture_token = _current_capture_token()

    result = {
        "schema": SYMBOL_ALIAS_SCHEMA,
        "schemaVersion": plan["version"],
        "captureId": snapshot_capture_id,
        "captureSessionId": str(_capture_session_id or ""),
        "path": plan["path"],
        "confirmedOnly": plan["confirmedOnly"],
        "strictAtomic": strict_atomic,
        "atomicity": (
            "complete-or-recovery-required" if strict_atomic else "best-effort"),
        "physicalAtomic": False,
        "recoveryRequired": False,
        "rollbackAvailable": bool(strict_atomic),
        "recoveryLedgerPublished": bool(strict_atomic),
        "transactionId": (
            _symbol_alias_recovery_ledger.get("transactionId", "")
            if strict_atomic and _symbol_alias_recovery_ledger is not None else ""),
        "recoveryResourceCount": (
            len(_symbol_alias_recovery_ledger.get("resources", {}))
            if strict_atomic and _symbol_alias_recovery_ledger is not None else 0),
        "operationId": plan["operationId"],
        "idempotent": False,
        "committed": True,
        "mutationPresent": bool(transaction_resource_ids or logical_mutation),
        "counts": {
            "manifestAliases": len(plan["allAliases"]),
            "deterministicAliases": len(plan["candidates"]),
            "liveBoundAliases": len(plan["liveCandidates"]),
            "activeValidatedAliases": len(plan["activeAliases"]),
            "renamedShaders": sum(
                item.get("bindingKind") == "shader"
                for item in written + replaced_managed),
            "renamedTextures": sum(
                item.get("bindingKind") == "textureresource"
                for item in written + replaced_managed),
            "renamedResources": len(applied),
            "keptUser": len(kept_user),
            "skipped": len(skipped),
            "conflicts": len(conflicts),
        },
        "applied": applied,
        "written": written,
        "replacedManaged": replaced_managed,
        "keptUser": kept_user,
        "skipped": skipped,
        "conflicts": conflicts,
    }
    if strict_atomic and _symbol_alias_recovery_ledger is not None:
        _symbol_alias_recovery_ledger["commitResponse"] = dict(result)
    return result


def _load_symbol_aliases(params):
    """Load deterministic aliases bound to the exact currently exported capture/shaders."""
    if not _request_capture_loaded():
        raise RuntimeError("No capture loaded")
    request_capture_token = _current_capture_token()
    request_capture_session_id = _request_capture_session_id()
    request_capture_snapshot = _symbol_capture_snapshot
    request_alias_overlay = _symbol_alias_overlay
    request_resource_renames = _symbol_resource_renames
    request_rename_capture_token = _symbol_rename_capture_token
    request_recovery_ledger = _symbol_alias_recovery_ledger

    path = str(params.get("path", "") or "").strip()
    if not path:
        raise ValueError("path required")
    path = os.path.abspath(os.path.expanduser(path))
    if not os.path.isfile(path):
        raise ValueError("Alias file not found: %s" % path)

    requested_confirmed_only = params.get(
        "confirmed_only", params.get("confirmedOnly", True))
    if isinstance(requested_confirmed_only, str):
        requested_confirmed_only = requested_confirmed_only.strip().lower() not in (
            "0", "false", "no", "off")
    else:
        requested_confirmed_only = bool(requested_confirmed_only)
    if not requested_confirmed_only:
        raise ValueError(
            "confirmed_only=false is not supported; the bridge only loads deterministic aliases")
    confirmed_only = True
    requested_strict_atomic = params.get(
        "strict_atomic", params.get("strictAtomic", False))
    if isinstance(requested_strict_atomic, str):
        strict_atomic = requested_strict_atomic.strip().lower() not in (
            "0", "false", "no", "off")
    else:
        strict_atomic = bool(requested_strict_atomic)
    requested_operation_id = str(
        params.get("operation_id", params.get("operationId", "")) or ""
    ).strip().lower()
    operation_id = (
        _shader_override_hex(requested_operation_id, "operation_id", 32)
        if requested_operation_id else uuid.uuid4().hex
    )

    if os.path.getsize(path) > 32 * 1024 * 1024:
        raise ValueError("Alias manifest is larger than the 32 MiB safety limit")

    expected_sha256 = str(params.get("expected_sha256", "") or "").strip().lower()
    if (len(expected_sha256) != 64 or
            any(c not in "0123456789abcdef" for c in expected_sha256)):
        raise ValueError(
            "expected_sha256 is required; aliases must come from the host's "
            "verified export/apply flow")
    with open(path, "rb") as f:
        raw_manifest = f.read(32 * 1024 * 1024 + 1)
    if len(raw_manifest) > 32 * 1024 * 1024:
        raise ValueError("Alias manifest is larger than the 32 MiB safety limit")
    actual_sha256 = hashlib.sha256(raw_manifest).hexdigest()
    if actual_sha256 != expected_sha256:
        raise ValueError("Alias manifest bytes do not match the host-authorized SHA-256")
    try:
        data = json.loads(raw_manifest.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError("Alias manifest is not valid UTF-8 JSON: %s" % str(exc))
    if not isinstance(data, dict):
        raise ValueError("Alias manifest root must be an object")

    schema = str(data.get("schema", "") or "")
    if schema != SYMBOL_ALIAS_SCHEMA:
        raise ValueError(
            "Unsupported alias schema %r (required: %s)" % (schema, SYMBOL_ALIAS_SCHEMA))
    version = data.get("schemaVersion")
    try:
        version = int(version)
    except Exception:
        raise ValueError("Invalid alias schemaVersion: %s" % str(version))
    if version != SYMBOL_ALIAS_VERSION:
        raise ValueError("Unsupported alias schemaVersion %d (supported: %d)" % (
            version, SYMBOL_ALIAS_VERSION))

    snapshot_capture_id = str(request_capture_snapshot.get("captureId", "") or "")
    if not snapshot_capture_id:
        raise RuntimeError(
            "No trusted shader catalog is active; call export_shader_catalog for this capture first")
    manifest_capture_id = str(data.get("captureId", "") or "")
    if not manifest_capture_id or manifest_capture_id != snapshot_capture_id:
        raise ValueError(
            "Alias captureId does not match the catalog exported by this RenderDoc instance")
    if request_recovery_ledger is not None:
        existing_transaction_id = str(
            request_recovery_ledger.get("transactionId", "") or "")
        if (strict_atomic and existing_transaction_id == operation_id and
                request_recovery_ledger.get("state") == "committed" and
                request_recovery_ledger.get("manifestSha256") ==
                expected_sha256 and
                isinstance(
                    request_recovery_ledger.get("commitResponse"), dict)):
            def _read_idempotent_response_on_ui():
                if (not _ctx or not _ctx.IsCaptureLoaded() or
                        str(_capture_session_id or "") !=
                        request_capture_session_id or
                        _current_capture_token() != request_capture_token or
                        _symbol_capture_snapshot is not request_capture_snapshot or
                        _symbol_alias_recovery_ledger is not request_recovery_ledger):
                    raise RuntimeError(
                        "Capture or symbol alias state changed before idempotent response")
                response = dict(request_recovery_ledger["commitResponse"])
                response["idempotent"] = True
                return response

            return _invoke_on_ui_sync(_read_idempotent_response_on_ui)
        raise RuntimeError(
            "A symbol alias transaction is already applied or requires recovery; "
            "call rollback_symbol_aliases for this capture before another load")

    all_aliases = _normalise_alias_records(data)
    skipped = []
    candidates = []
    expected_keys = set()
    snapshot_keys = request_capture_snapshot.get("shaderKeys", set())
    allowed_kinds = (
        "shader", "constantbuffer", "constantfield", "textureresource")
    for index, alias in enumerate(all_aliases):
        if not _alias_validated(alias):
            skipped.append({
                "index": index,
                "reason": "alias lacks deterministic program verification",
            })
            continue
        if str(alias.get("captureId", "") or "") != snapshot_capture_id:
            skipped.append({"index": index, "reason": "alias captureId mismatch"})
            continue
        shader_key = _alias_shader_key(alias)
        if shader_key is None:
            skipped.append({
                "index": index,
                "reason": "alias requires resourceId, stage, entryPoint, and rawSha256",
            })
            continue
        if shader_key not in snapshot_keys:
            skipped.append({
                "index": index,
                "resourceId": shader_key[0],
                "reason": "alias shader binding is absent from the active catalog",
            })
            continue
        kind = _alias_kind(alias)
        if kind not in allowed_kinds:
            skipped.append({"index": index, "reason": "unsupported alias binding kind"})
            continue
        if kind == "textureresource":
            target_resource_id = _alias_target_resource_id(alias)
            bind_number = _safe_int(_alias_first(
                alias, ("bindNumber", "bind", "fixedBindNumber"), -1), -1)
            array_value = _alias_first(
                alias, ("arrayIndex", "arrayElement"), None)
            metadata = alias.get("metadata", {})
            if (target_resource_id <= 0 or bind_number < 0 or
                    (array_value is not None and
                     _safe_int(array_value, -1) < 0) or
                    not isinstance(metadata, dict) or
                    _safe_int(metadata.get("eventId"), 0) <= 0):
                skipped.append({
                    "index": index,
                    "reason": (
                        "texture resource alias requires resourceId, bindNumber "
                        "and metadata.eventId"),
                })
                continue
        if not _alias_display_name(alias):
            skipped.append({"index": index, "reason": "empty alias display name"})
            continue
        candidates.append((index, alias, shader_key, kind))
        expected_keys.add(shader_key)

    live_keys, live_failures = _revalidate_symbol_shader_keys(expected_keys)
    live_candidates = []
    for index, alias, shader_key, kind in candidates:
        if shader_key not in live_keys:
            skipped.append({
                "index": index,
                "resourceId": shader_key[0],
                "reason": live_failures.get(
                    shader_key, "shader binding failed live revalidation"),
            })
            continue
        live_candidates.append((index, alias, shader_key, kind))

    texture_candidates = [
        item for item in live_candidates if item[3] == "textureresource"]
    live_texture_indexes, texture_failures = (
        _revalidate_symbol_texture_aliases(texture_candidates))
    if texture_candidates:
        checked_candidates = []
        for index, alias, shader_key, kind in live_candidates:
            if kind != "textureresource" or index in live_texture_indexes:
                checked_candidates.append((index, alias, shader_key, kind))
                continue
            skipped.append({
                "index": index,
                "resourceId": _alias_target_resource_id(alias),
                "reason": texture_failures.get(
                    index, "texture binding failed live revalidation"),
            })
        live_candidates = checked_candidates

    # Never choose a first alias when one physical target has conflicting names.
    target_groups = {}
    for index, alias, shader_key, kind in live_candidates:
        target_key = [kind] + list(shader_key)
        if kind in ("constantbuffer", "constantfield", "textureresource"):
            target_key.extend([
                _safe_int(_alias_first(
                    alias, ("registerSpace", "space", "fixedBindSetOrSpace"), 0), 0),
                _safe_int(_alias_first(
                    alias, ("bindNumber", "bind", "fixedBindNumber"), -1), -1),
            ])
        if kind == "textureresource":
            target_key.extend([
                _alias_target_resource_id(alias),
                _safe_int((alias.get("metadata") or {}).get("eventId"), 0),
                _safe_int(_alias_first(
                    alias, ("arrayIndex", "arrayElement"), 0), 0),
            ])
        if kind == "constantfield":
            target_key.append(_safe_int(
                _alias_first(alias, ("byteOffset", "offset"), -1), -1))
        target_groups.setdefault(tuple(target_key), []).append((index, alias))

    conflicts = []
    active_aliases = []
    for target_key, group in target_groups.items():
        names = sorted(set(_alias_display_name(item[1]) for item in group))
        if len(names) != 1:
            conflicts.append({
                "target": list(target_key),
                "displayNames": names,
                "indexes": [item[0] for item in group],
            })
            continue
        active_aliases.extend(item[1] for item in group)

    new_overlay = {
        "schema": SYMBOL_ALIAS_SCHEMA,
        "schemaVersion": version,
        "captureId": snapshot_capture_id,
        "sourcePath": path,
        "confirmedOnly": confirmed_only,
        "allAliases": all_aliases,
        "aliases": active_aliases,
    }

    rename_candidates = {}
    rename_candidate_kinds = {}
    for alias in active_aliases:
        alias_kind = _alias_kind(alias)
        if alias_kind not in ("shader", "textureresource"):
            continue
        resource_id = _alias_target_resource_id(alias)
        display_name = _alias_display_name(alias)
        rename_candidates.setdefault(resource_id, set()).add(display_name)
        rename_candidate_kinds.setdefault(resource_id, set()).add(alias_kind)

    plan = {
        "captureToken": request_capture_token,
        "captureSessionId": request_capture_session_id,
        "captureSnapshot": request_capture_snapshot,
        "originalOverlay": request_alias_overlay,
        "originalResourceRenames": request_resource_renames,
        "originalRenameCaptureToken": request_rename_capture_token,
        "originalRecoveryLedger": request_recovery_ledger,
        "strictAtomic": strict_atomic,
        "snapshotCaptureId": snapshot_capture_id,
        "skipped": skipped,
        "conflicts": conflicts,
        "renameCandidates": rename_candidates,
        "renameCandidateKinds": rename_candidate_kinds,
        "operationId": operation_id,
        "expectedSha256": expected_sha256,
        "newOverlay": new_overlay,
        "version": version,
        "path": path,
        "confirmedOnly": confirmed_only,
        "allAliases": all_aliases,
        "candidates": candidates,
        "liveCandidates": live_candidates,
        "activeAliases": active_aliases,
    }
    return _invoke_on_ui_sync(
        lambda: _commit_symbol_aliases_on_ui(plan))


def _fmt_str(fmt):
    """Safely convert ResourceFormat to string."""
    name = getattr(fmt, "Name", None)
    if callable(name):
        return str(name())
    if hasattr(fmt, 'name'):
        return fmt.name
    return str(fmt)


def _get_textures(params):
    """List all textures."""
    def _do(ctrl):
        # Build name lookup from resources
        name_lookup = {}
        for r in ctrl.GetResources():
            name_lookup[int(r.resourceId)] = r.name

        result = []
        for t in ctrl.GetTextures():
            rid = int(t.resourceId)
            entry = {
                "id": rid,
                "name": name_lookup.get(rid, ""),
                "w": t.width, "h": t.height,
                "fmt": _fmt_str(t.format),
                "mips": t.mips,
                "array": t.arraysize,
                "size": t.byteSize,
            }
            result.append(entry)
        return result
    return _replay(_do)


def _get_buffers(params):
    """List all buffers."""
    def _do(ctrl):
        name_lookup = {}
        for r in ctrl.GetResources():
            name_lookup[int(r.resourceId)] = r.name

        return [
            {"id": int(b.resourceId), "name": name_lookup.get(int(b.resourceId), ""), "length": b.length}
            for b in ctrl.GetBuffers()
        ]
    return _replay(_do)


def _get_resources(params):
    """List all resources."""
    def _do(ctrl):
        return [
            {"id": int(r.resourceId), "name": r.name, "type": str(r.type)}
            for r in ctrl.GetResources()
        ]
    return _replay(_do)


def _find_by_texture(params):
    """Find draw calls using a texture name (partial match)."""
    tex_name = params.get("texture_name", "")
    if not tex_name:
        raise ValueError("texture_name required")

    def _do(ctrl):
        # Find matching texture IDs
        matching_ids = set()
        for t in ctrl.GetTextures():
            if tex_name.lower() in t.name.lower():
                matching_ids.add(int(t.resourceId))

        if not matching_ids:
            return {"matches": [], "note": "No textures matching '%s'" % tex_name}

        # Scan actions for usage
        results = []
        def scan(actions):
            for a in actions:
                if a.outputs:
                    for o in a.outputs:
                        if int(o) in matching_ids:
                            results.append({"eventId": a.eventId, "name": a.customName or "Action"})
                # Also check by moving to event and checking bindings (expensive, skip for now)
                if a.children:
                    scan(a.children)
        scan(ctrl.GetRootActions())

        return {
            "textureIds": list(matching_ids),
            "draws": results,
            "note": "Found %d textures, %d draw calls" % (len(matching_ids), len(results)),
        }

    return _replay(_do)


def _ui_resource_name(resource_id, fallback=""):
    fallback = str(fallback or "")

    def _read():
        if not _ctx or not hasattr(_ctx, "GetResourceName"):
            return fallback
        try:
            rid = _context_resource_ids().get(_safe_int(resource_id, 0))
            if rid is None:
                return fallback
            return str(_ctx.GetResourceName(rid) or fallback)
        except Exception:
            return str(fallback or "")

    return _invoke_on_ui_sync(_read)


def _find_by_shader(params):
    """Find draw/dispatch actions by shader ID, display name, capture name, or alias."""
    shader_name = str(params.get("shader_name", "") or "").strip()
    if not shader_name:
        raise ValueError("shader_name required")

    requested_stage = str(params.get("stage", "") or "").strip()
    stages = _available_shader_stages([requested_stage] if requested_stage else None)
    if requested_stage and not stages:
        raise ValueError("Unknown shader stage: %s" % requested_stage)

    try:
        original_event = _request_visible_event_id(0)
        restore_original_event = True
    except Exception:
        original_event = 0
        restore_original_event = False

    draw_dispatch_mask = _draw_dispatch_action_mask()

    def _do(ctrl):
        action_records = []

        def _collect(actions, marker_path=None):
            marker_path = marker_path or []
            for action in actions:
                flags = _safe_int(getattr(action, "flags", 0), 0)
                name = _action_name(action)
                children = getattr(action, "children", None) or []
                current_path = marker_path + ([name] if children else [])
                if flags & draw_dispatch_mask:
                    action_records.append({
                        "eventId": _safe_int(getattr(action, "eventId", 0), 0),
                        "actionName": name,
                        "actionFlags": flags,
                        "markerPath": marker_path,
                    })
                if children:
                    _collect(children, current_path)

        _collect(ctrl.GetRootActions())

        resource_names = {}
        try:
            for resource in ctrl.GetResources():
                resource_names[_resource_id_int(getattr(resource, "resourceId", None))] = str(
                    getattr(resource, "name", ""))
        except Exception:
            pass

        candidates = []
        errors = []
        reflection_cache = {}
        try:
            for action in action_records:
                event_id = action["eventId"]
                try:
                    _set_frame_event(ctrl, event_id, True)
                    ps = ctrl.GetPipelineState()
                    pipeline_id = _get_pipeline_obj(ps, ctrl)
                except Exception as exc:
                    errors.append({
                        "eventId": event_id, "scope": "pipeline", "message": str(exc)})
                    continue

                for stage_name, stage in stages:
                    try:
                        shader_id = ps.GetShader(stage)
                        shader_resource_id = _resource_id_int(shader_id)
                    except Exception as exc:
                        errors.append({
                            "eventId": event_id, "stage": stage_name,
                            "scope": "shader_binding", "message": str(exc)})
                        continue
                    if not shader_resource_id:
                        continue

                    entry_point = ""
                    try:
                        entry_point = str(ps.GetShaderEntryPoint(stage) or "")
                    except Exception:
                        pass
                    cache_key = (
                        _resource_id_int(pipeline_id), shader_resource_id,
                        stage_name, entry_point)
                    details = reflection_cache.get(cache_key)
                    if details is None:
                        raw_sha256 = None
                        try:
                            entries = list(ctrl.GetShaderEntryPoints(shader_id) or [])
                            selection = _pipeline_shader_entry_selection(
                                ps, stage, stage_name, shader_id, entries)
                            selected_entry = selection.get("entry")
                            if selected_entry is None:
                                failure = _shader_entry_selection_failure(
                                    selection, shader_id, pipeline_id, stage_name)
                                failure.update({
                                    "eventId": event_id,
                                    "shaderResourceId": shader_resource_id,
                                    "scope": "entry",
                                })
                                errors.append(failure)
                                continue
                            entry_point = str(
                                getattr(selected_entry, "name", "") or "")
                            cache_key = (
                                _resource_id_int(pipeline_id), shader_resource_id,
                                stage_name, entry_point)
                            reflection = ctrl.GetShader(
                                pipeline_id, shader_id, selected_entry)
                            if reflection:
                                identity_failure = _shader_reflection_identity_failure(
                                    reflection, selected_entry, shader_id,
                                    pipeline_id, stage_name, selection)
                                if identity_failure is not None:
                                    identity_failure.update({
                                        "eventId": event_id,
                                        "shaderResourceId": shader_resource_id,
                                        "scope": "reflection",
                                    })
                                    errors.append(identity_failure)
                                    continue
                                raw_bytes = _shader_raw_bytes(reflection)
                                if raw_bytes:
                                    raw_sha256 = hashlib.sha256(raw_bytes).hexdigest()
                        except Exception as exc:
                            errors.append({
                                "eventId": event_id, "stage": stage_name,
                                "shaderResourceId": shader_resource_id,
                                "scope": "reflection", "message": str(exc)})

                        aliases = _matching_shader_aliases(
                            shader_resource_id, stage_name, entry_point, raw_sha256)
                        details = {
                            "entryPoint": entry_point,
                            "rawSha256": raw_sha256,
                            "captureResourceName": resource_names.get(shader_resource_id, ""),
                            "aliasNames": [_alias_display_name(alias) for alias in aliases
                                           if _alias_display_name(alias)],
                            "aliases": aliases,
                        }
                        reflection_cache[cache_key] = details

                    record = dict(action)
                    record.update({
                        "stage": stage_name,
                        "shaderResourceId": shader_resource_id,
                        "resourceId": shader_resource_id,
                        "entryPoint": details["entryPoint"],
                        "rawSha256": details["rawSha256"],
                        "captureResourceName": details["captureResourceName"],
                        "aliasNames": details["aliasNames"],
                    })
                    if details["aliases"]:
                        record["alias"] = details["aliases"][0]
                    candidates.append(record)
        finally:
            if restore_original_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception as exc:
                    errors.append({
                        "eventId": original_event, "scope": "restore_event",
                        "message": str(exc)})

        return {
            "actionsScanned": len(action_records),
            "bindingsScanned": len(candidates),
            "candidates": candidates,
            "errors": errors,
        }

    scan = _replay(_do)
    query = shader_name.lower()
    numeric_query = int(shader_name) if shader_name.isdigit() else None
    display_name_cache = {}
    matches = []
    for candidate in scan["candidates"]:
        resource_id = candidate["shaderResourceId"]
        if resource_id not in display_name_cache:
            display_name_cache[resource_id] = _ui_resource_name(
                resource_id, candidate.get("captureResourceName", ""))
        candidate["resourceDisplayName"] = display_name_cache[resource_id]

        evidence = []
        if numeric_query is not None:
            if numeric_query == resource_id:
                evidence.append({
                    "field": "shaderResourceId", "value": resource_id,
                    "match": "exact"})
        else:
            resource_tokens = [str(resource_id), "ResourceId::%d" % resource_id,
                               "ResourceId(%d)" % resource_id]
            if any(query in token.lower() for token in resource_tokens):
                evidence.append({
                    "field": "shaderResourceId", "value": resource_id,
                    "match": "case-insensitive substring"})

        for field, value in (
                ("captureResourceName", candidate.get("captureResourceName", "")),
                ("resourceDisplayName", candidate.get("resourceDisplayName", ""))):
            if value and query in str(value).lower():
                evidence.append({
                    "field": field, "value": value,
                    "match": "case-insensitive substring"})
        for alias_name in candidate.get("aliasNames", []):
            if query in alias_name.lower():
                evidence.append({
                    "field": "alias", "value": alias_name,
                    "match": "case-insensitive substring"})

        if evidence:
            candidate["matchEvidence"] = evidence
            matches.append(candidate)

    return {
        "schema": "renderdoc-shader-search/v1",
        "query": shader_name,
        "stage": _normalise_stage_name(requested_stage) if requested_stage else "",
        "count": len(matches),
        "actionsScanned": scan["actionsScanned"],
        "bindingsScanned": scan["bindingsScanned"],
        "matches": matches,
        "errors": scan["errors"],
    }


def _find_by_resource(params):
    """Return coarse event candidates from ReplayController.GetUsage(ResourceId)."""
    resource_id = _safe_int(params.get("resource_id"), 0)
    if resource_id <= 0:
        raise ValueError("resource_id required")

    draw_dispatch_mask = _draw_dispatch_action_mask()

    def _do(ctrl):
        action_map = {}

        def _collect(actions, marker_path=None):
            marker_path = marker_path or []
            for action in actions:
                event_id = _safe_int(getattr(action, "eventId", 0), 0)
                flags = _safe_int(getattr(action, "flags", 0), 0)
                name = _action_name(action)
                children = getattr(action, "children", None) or []
                action_map[event_id] = {
                    "actionName": name,
                    "actionFlags": flags,
                    "markerPath": marker_path,
                    "isDrawDispatch": bool(flags & draw_dispatch_mask),
                }
                if children:
                    _collect(children, marker_path + [name])

        _collect(ctrl.GetRootActions())

        capture_name = ""
        rid = None
        try:
            for resource in ctrl.GetResources():
                if _resource_id_int(getattr(resource, "resourceId", None)) == resource_id:
                    capture_name = str(getattr(resource, "name", ""))
                    rid = getattr(resource, "resourceId", None)
                    break
        except Exception:
            pass

        if rid is None:
            raise ValueError("resource_id is not present in the current capture")
        if not hasattr(ctrl, "GetUsage"):
            raise RuntimeError("ReplayController.GetUsage is unavailable")
        usages = ctrl.GetUsage(rid)
        candidates = []
        for usage in usages or []:
            event_id = _safe_int(
                getattr(usage, "eventId", getattr(usage, "eventID", 0)), 0)
            usage_value = getattr(usage, "usage", "")
            candidate = {
                "eventId": event_id,
                "usage": str(usage_value),
                "usageValue": _safe_int(usage_value, 0),
            }
            candidate.update(action_map.get(event_id, {
                "actionName": "",
                "actionFlags": 0,
                "markerPath": [],
                "isDrawDispatch": False,
            }))
            candidates.append(candidate)
        return {"captureResourceName": capture_name, "candidates": candidates}

    result = _replay(_do)
    display_name = _ui_resource_name(resource_id, result["captureResourceName"])
    return {
        "schema": "renderdoc-resource-usage/v1",
        "resourceId": resource_id,
        "captureResourceName": result["captureResourceName"],
        "resourceDisplayName": display_name,
        "count": len(result["candidates"]),
        "coarseCandidates": True,
        "limitations": [
            "ReplayController.GetUsage reports resource-level event usage only.",
            "It does not identify descriptor slot, shader stage, byte offset, or byte range.",
        ],
        "candidates": result["candidates"],
    }


def _save_texture(params):
    """Save a texture to disk. Auto-detects CubeMap (arraysize=6) and handles appropriately.

    For CubeMap textures:
    - DDS/HDR/EXR: saves all 6 faces in a single file (native cubemap support)
    - PNG/JPG/BMP/TGA: saves 6 individual face files ({name}_face0_posX.png, etc.)
      OR a single cross-layout image if slice=-1

    For regular 2D textures: saves normally.

    Args:
        resource_id: Texture resource ID
        output_path: Output file path
        mip: Mip level (default 0)
        slice: For CubeMap: specific face (0-5), -1 for all faces. Ignored for 2D.
    """
    resource_id = params.get("resource_id")
    output_path = params.get("output_path")
    if not resource_id or not output_path:
        raise ValueError("resource_id and output_path required")

    req_slice = params.get("slice", -1)  # -1 = auto (all faces for cubemap)
    raw_crop = params.get("crop")
    crop = None
    if raw_crop is not None:
        if not isinstance(raw_crop, dict):
            raise ValueError("crop must be an object with x, y, width and height")
        crop = {}
        for name, minimum in (("x", 0), ("y", 0), ("width", 1), ("height", 1)):
            value = raw_crop.get(name)
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("crop.%s must be a whole number of pixels" % name)
            if int(value) < minimum:
                raise ValueError("crop.%s must be at least %d" % (name, minimum))
            crop[name] = int(value)
    max_dimension = params.get("max_dimension")
    if max_dimension is not None:
        if isinstance(max_dimension, bool) or not isinstance(max_dimension, int):
            raise ValueError("max_dimension must be an integer")
        if not 16 <= max_dimension <= 8192:
            raise ValueError("max_dimension must be between 16 and 8192")

    def _do(ctrl):
        # Find the actual texture info
        target_tex = None
        for t in ctrl.GetTextures():
            if int(t.resourceId) == int(resource_id):
                target_tex = t
                break

        if target_tex is None:
            return {"error": "Texture %d not found" % int(resource_id)}

        target_rid = target_tex.resourceId
        is_cubemap = target_tex.arraysize == 6
        mip_level = params.get("mip", 0)

        ext = os.path.splitext(output_path)[1].lower()
        fmt_map = {
            ".png": rd.FileType.PNG, ".jpg": rd.FileType.JPG,
            ".bmp": rd.FileType.BMP, ".tga": rd.FileType.TGA,
            ".hdr": rd.FileType.HDR, ".exr": rd.FileType.EXR,
            ".dds": rd.FileType.DDS,
        }
        dest_type = fmt_map.get(ext, rd.FileType.PNG)

        # Non-CubeMap: save normally
        if not is_cubemap:
            save = rd.TextureSave()
            save.resourceId = target_rid
            save.mip = mip_level
            save.destType = dest_type
            ret = ctrl.SaveTexture(save, output_path)
            if ret.code == rd.ResultCode.Succeeded:
                # Cropping and scaling here is what keeps a 4K input texture usable as
                # evidence: a model reading it has a finite context.
                reduction = None
                if crop or max_dimension:
                    reduction = _reduce_saved_image(output_path, crop, max_dimension)
                return {"saved": output_path, "type": "2D", "reduction": reduction,
                        "sourceFormat": _fmt_str(target_tex.format),
                        "sourceColorSpace": "srgb" if target_tex.format.SRGBCorrected() else "linear"}
            return {"error": "Save failed: %s" % str(ret)}

        # CubeMap handling
        face_names = ["posX", "negX", "posY", "negY", "posZ", "negZ"]
        face_labels = ["+X (Right)", "-X (Left)", "+Y (Up)", "-Y (Down)", "+Z (Front)", "-Z (Back)"]

        # DDS can store full cubemap natively
        if dest_type == rd.FileType.DDS:
            save = rd.TextureSave()
            save.resourceId = target_rid
            save.mip = mip_level
            save.destType = rd.FileType.DDS
            ret = ctrl.SaveTexture(save, output_path)
            if ret.code == rd.ResultCode.Succeeded:
                return {
                    "saved": output_path,
                    "type": "cubemap",
                    "format": "DDS (all 6 faces)",
                    "faces": 6,
                    "size": "%dx%d" % (target_tex.width, target_tex.height),
                }
            return {"error": "Save failed: %s" % str(ret)}

        # Specific face requested
        if req_slice >= 0 and req_slice < 6:
            save = rd.TextureSave()
            save.resourceId = target_rid
            save.mip = mip_level
            save.destType = dest_type
            # Set slice for the specific face
            if hasattr(save, 'slice'):
                if hasattr(save.slice, 'sliceIndex'):
                    save.slice.sliceIndex = req_slice
                elif hasattr(save.slice, 'cubeCruciform'):
                    pass  # Will handle differently
            # Try setting via sample attribute
            if hasattr(save, 'sample'):
                pass
            # Direct slice setting for Vulkan/newer RenderDoc
            if hasattr(save, 'resourceId'):
                save.slice = rd.Subresource(mip_level, req_slice, 0)

            ret = ctrl.SaveTexture(save, output_path)
            if ret.code == rd.ResultCode.Succeeded:
                return {
                    "saved": output_path,
                    "type": "cubemap_face",
                    "face": req_slice,
                    "faceName": face_names[req_slice],
                    "faceLabel": face_labels[req_slice],
                }
            return {"error": "Save face %d failed: %s" % (req_slice, str(ret))}

        # Default: export all 6 faces as individual files
        base, base_ext = os.path.splitext(output_path)
        saved_faces = []
        errors = []

        for face_idx in range(6):
            face_path = "%s_face%d_%s%s" % (base, face_idx, face_names[face_idx], base_ext)
            save = rd.TextureSave()
            save.resourceId = target_rid
            save.mip = mip_level
            save.destType = dest_type
            # Set the slice/face
            try:
                save.slice = rd.Subresource(mip_level, face_idx, 0)
            except Exception:
                # Fallback: try setting sliceIndex directly
                if hasattr(save, 'slice') and hasattr(save.slice, 'sliceIndex'):
                    save.slice.sliceIndex = face_idx

            ret = ctrl.SaveTexture(save, face_path)
            if hasattr(ret, 'code') and ret.code == rd.ResultCode.Succeeded:
                saved_faces.append({
                    "path": face_path,
                    "face": face_idx,
                    "name": face_names[face_idx],
                    "label": face_labels[face_idx],
                })
            else:
                errors.append("Face %d (%s): %s" % (face_idx, face_names[face_idx], str(ret)[:80]))

        result = {
            "type": "cubemap",
            "faces": len(saved_faces),
            "size": "%dx%d" % (target_tex.width, target_tex.height),
            "savedFaces": saved_faces,
        }
        if errors:
            result["errors"] = errors
        if saved_faces:
            result["saved"] = saved_faces[0]["path"]  # First face as primary
        else:
            result["error"] = "No faces saved successfully"

        return result

    return _replay(_do)


# ---- Helpers ----

def _strict_float_vector(values, maximum):
    """Return JSON-safe floats plus explicit positions for non-finite values.

    Captured buffer bytes can legitimately decode to IEEE NaN or infinity.
    JSON cannot represent those numbers.  Preserve their observed class in a
    sibling diagnostic while using ``null`` at that vector position so every
    bridge response remains strict, hashable JSON.
    """
    result = []
    non_finite = []
    for index, value in enumerate(list(values[:maximum])):
        number = float(value)
        if math.isfinite(number):
            result.append(number)
            continue
        result.append(None)
        if math.isnan(number):
            label = "nan"
        elif number > 0:
            label = "+inf"
        else:
            label = "-inf"
        non_finite.append({"index": index, "value": label})
    return result, non_finite

def _var_dict(v):
    d = {"name": v.name}
    if hasattr(v, "value"):
        val = v.value
        if hasattr(val, "f32v"):
            floats, non_finite = _strict_float_vector(val.f32v, 16)
            # Trim trailing zeros for readability
            while floats and floats[-1] == 0.0:
                floats.pop()
            if floats:
                d["float"] = floats
            if non_finite:
                d["floatNonFinite"] = non_finite
        if hasattr(val, "u32v"):
            uints = list(val.u32v[:4])
            if any(u != 0 for u in uints):
                d["uint"] = uints
        if hasattr(val, "s32v"):
            sints = list(val.s32v[:4])
            if any(s != 0 for s in sints):
                d["int"] = sints
    # Try direct float/int attributes (some RenderDoc versions)
    for attr in ['fvalue', 'uvalue', 'ivalue']:
        val = getattr(v, attr, None)
        if val is not None:
            try:
                if attr == 'fvalue':
                    values, non_finite = _strict_float_vector(val, 4)
                    d[attr] = values
                    if non_finite:
                        d["fvalueNonFinite"] = non_finite
                else:
                    d[attr] = list(val[:4])
            except Exception:
                pass
    # Include type and byte offset if available
    if hasattr(v, 'type'):
        try:
            d["type"] = str(v.type)
        except Exception:
            pass
    if hasattr(v, 'byteOffset'):
        d["offset"] = v.byteOffset
    if hasattr(v, 'rows') and hasattr(v, 'columns'):
        d["rows"] = v.rows
        d["columns"] = v.columns
    if hasattr(v, "members") and v.members:
        d["members"] = [_var_dict(m) for m in v.members]
    return d


def _resolve_bound_resource(bindings, index, ctrl):
    """Resolve the actual bound resource ID from pipeline bindings.

    Handles all API-specific binding structures:
    - Vulkan: UsedDescriptor → .descriptor.resource (ResourceId)
    - D3D11: BoundResourceArray → .resources[] → .resourceId
    - D3D12: Similar to D3D11 but may use descriptor tables
    - OpenGL: BoundResource → .resourceId

    Args:
        bindings: Result of ps.GetReadOnlyResources(stage)
        index: The slot index to look up
        ctrl: The ReplayController (for fallback descriptor access)
    Returns:
        int: The bound resource ID, or 0 if not found
    """
    if not bindings or index >= len(bindings):
        return 0

    binding = bindings[index]

    try:
        # --- Strategy 1: Vulkan UsedDescriptor → descriptor.resource ---
        # This is the primary path for Vulkan/ANGLE captures
        if hasattr(binding, 'descriptor'):
            desc = binding.descriptor
            if hasattr(desc, 'resource'):
                rid = int(desc.resource)
                if rid != 0:
                    return rid
            # Fallback: descriptor.view
            if hasattr(desc, 'view'):
                rid = int(desc.view)
                if rid != 0:
                    return rid

        # --- Strategy 2: Direct .resourceId attribute (D3D11/GL style) ---
        if hasattr(binding, 'resourceId'):
            rid = int(binding.resourceId)
            if rid != 0:
                return rid

        # --- Strategy 3: .resources list (BoundResourceArray — D3D11/D3D12) ---
        if hasattr(binding, 'resources'):
            for d in binding.resources:
                if hasattr(d, 'resourceId'):
                    rid = int(d.resourceId)
                    if rid != 0:
                        return rid
                elif hasattr(d, 'resource'):
                    rid = int(d.resource)
                    if rid != 0:
                        return rid

        # --- Strategy 4: Direct .resource on binding (some RenderDoc versions) ---
        # Note: for Vulkan UsedDescriptor, int(binding.resource) returns a pointer, not ResourceId
        # Only try this if it looks like a real ResourceId (< 10M)
        if hasattr(binding, 'resource'):
            try:
                rid = int(binding.resource)
                if 0 < rid < 10000000:  # Reasonable ResourceId range
                    return rid
            except (TypeError, ValueError):
                pass

        # --- Strategy 5: D3D12 root signature / descriptor table ---
        if hasattr(binding, 'tableIndex') or hasattr(binding, 'rootElement'):
            if hasattr(binding, 'resource'):
                rid = int(binding.resource)
                if rid != 0:
                    return rid

    except Exception:
        pass

    return 0


def _exact_readonly_descriptor_resources(bindings, reflection_index):
    """Return only resources exactly mapped to one reflection binding index.

    Modern RenderDoc returns ``UsedDescriptor`` rows whose ``access.index`` is
    the index into ``ShaderReflection.readOnlyResources`` and whose
    ``access.arrayElement`` identifies a descriptor-array element.  That is
    current-EID evidence.  Older APIs return one row per reflection index; the
    positional fallback is accepted only when *none* of the rows exposes an
    access record.  This helper deliberately never consults resource usage or
    another EID.
    """
    values = list(bindings or [])
    has_access_records = any(
        getattr(value, "access", None) is not None for value in values)
    result = []
    if has_access_records:
        for value in values:
            access = getattr(value, "access", None)
            if access is None or _safe_int(
                    getattr(access, "index", -1), -1) != reflection_index:
                continue
            descriptor = getattr(value, "descriptor", None)
            resource_id = _resource_id_int(
                getattr(descriptor, "resource", None))
            if resource_id <= 0:
                resource_id = _resource_id_int(
                    getattr(descriptor, "view", None))
            if resource_id <= 0:
                continue
            result.append({
                "resourceId": resource_id,
                "arrayElement": _safe_int(
                    getattr(access, "arrayElement", 0), 0),
                "descriptorStoreId": _resource_id_int(
                    getattr(access, "descriptorStore", None)),
                "evidence": "used-descriptor-access",
            })
        return result

    resource_id = _resolve_bound_resource(values, reflection_index, None)
    if resource_id > 0:
        result.append({
            "resourceId": resource_id,
            "arrayElement": 0,
            "descriptorStoreId": 0,
            "evidence": "positional-pipeline-binding",
        })
    return result


_ROLE_PATTERNS = [
    (["albedo", "diffuse", "basecolor", "base_color", "color", "maintex", "_col"], "albedo"),
    (["normal", "nrm", "bump", "normalmap", "_n_", "_norm"], "normal"),
    (["metallic", "metalness", "_met", "metal"], "metallic"),
    (["rough", "roughness", "_rgh", "smoothness"], "roughness"),
    (["ao", "occlusion", "_occ"], "ao"),
    (["emissive", "emission", "glow"], "emissive"),
    (["specular", "spec"], "specular"),
    (["height", "displacement", "parallax"], "height"),
    (["opacity", "alpha", "mask"], "opacity"),
    (["shadow"], "shadow"),
    (["env", "cubemap", "skybox", "reflection", "ibl"], "environment"),
    (["lightmap", "lm_"], "lightmap"),
    (["depth", "zbuffer"], "depth"),
]


def _infer_role(var_name, tex_name, tex_format):
    combined = (var_name + " " + tex_name).lower()
    for keywords, role in _ROLE_PATTERNS:
        for kw in keywords:
            if kw in combined:
                return role
    fmt = tex_format.lower()
    if "bc5" in fmt:
        return "normal"
    if "bc6" in fmt:
        return "environment"
    return "unknown"


def _get_frame_summary(params):
    """Get frame summary stats."""
    return _get_capture_status(params)


def _find_action_by_event(actions, event_id):
    remaining = [MAX_CATALOG_IDENTITY_EVENTS]

    def _walk(values):
        for action in values or []:
            remaining[0] -= 1
            if remaining[0] < 0:
                return None
            if _safe_int(getattr(action, "eventId", 0), 0) == event_id:
                return action
            found = _walk(getattr(action, "children", None) or [])
            if found is not None:
                return found
        return None

    return _walk(actions)


def _draw_call_details_on_replay(ctrl, event_id):
    """Collect compact single-EID draw/workload/I/O evidence."""
    _require_healthy_replay(ctrl)
    ps = ctrl.GetPipelineState()
    event_id = int(event_id)
    try:
        action = _find_action_by_event(ctrl.GetRootActions(), event_id)
    except Exception:
        action = None
    action_flags = _safe_int(
        getattr(action, "flags", 0), 0) if action else 0

    resource_metadata, resource_metadata_receipt = (
        _bounded_frame_flow_resource_metadata(ctrl))

    def _fact(resource_id, access, stage=""):
        resource_id = _resource_id_int(resource_id)
        metadata = resource_metadata.get(resource_id, {})
        value = {
            "resourceId": resource_id,
            "name": metadata.get("name", ""),
            "format": metadata.get("format", ""),
            "access": access,
        }
        if stage:
            value["stage"] = stage
        if "sampleCount" in metadata:
            value["sampleCount"] = metadata["sampleCount"]
        return value

    def _bound_resources(method_name, stage, stage_name, access):
        method = getattr(ps, method_name, None)
        if method is None:
            return [], 0
        try:
            try:
                values = method(stage, True)
            except TypeError:
                values = method(stage)
        except Exception:
            return [], 0
        result = []
        omitted = 0
        for value in values or []:
            descriptor = getattr(value, "descriptor", value)
            resource_id = _resource_id_int(
                getattr(descriptor, "resource", None))
            if not resource_id:
                continue
            if len(result) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                omitted += 1
            else:
                fact = _fact(resource_id, access, stage_name)
                _frame_flow_descriptor_fields(fact, value)
                if access == "read-write":
                    fact["descriptorFlags"] = _safe_int(
                        getattr(descriptor, "flags", 0), 0)
                result.append(fact)
        return result, omitted

    def _unique(values):
        result = []
        seen = set()
        omitted = 0
        for value in values:
            key = (
                value.get("resourceId", 0), value.get("access", ""),
                value.get("stage", ""),
                *(
                    _safe_int(value.get(field, -1), -1)
                    for field in (
                        "byteOffset", "byteSize", "firstMip", "numMips",
                        "firstSlice", "numSlices")
                ),
                json.dumps(
                    value.get("subresource", {}),
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
            if not key[0] or key in seen:
                continue
            seen.add(key)
            if len(result) >= MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
                omitted += 1
            else:
                result.append(value)
        return result, omitted

    inputs = []
    outputs = []
    possible_outputs = []
    input_omitted = 0
    output_omitted = 0
    shaders = {}
    sampler_summary = {}
    pipeline_id = _get_pipeline_obj(ps, ctrl)
    action_compatibility = None
    if action is not None:
        action_compatibility = {
            "eventId": _safe_int(getattr(action, "eventId", 0), 0),
            "flags": str(getattr(action, "flags", "") or ""),
            "matchesCurrentEvent": bool(
                _safe_int(getattr(action, "eventId", 0), 0) == event_id),
        }
    compatible_stages = _ai_context_protocol.compatible_shader_stages(
        action_compatibility)
    available_stages = _available_shader_stages(compatible_stages)
    fragment_stage_resolved = any(
        stage_name == "fragment"
        for stage_name, unused_stage in available_stages)
    for stage_name, stage in available_stages:
        try:
            shader_id = ps.GetShader(stage)
        except Exception:
            continue
        if not shader_id or not _resource_id_int(shader_id):
            continue
        shader = {"shaderId": _resource_id_int(shader_id)}
        reflection = None
        try:
            entries = list(ctrl.GetShaderEntryPoints(shader_id) or [])
            selection = _pipeline_shader_entry_selection(
                ps, stage, stage_name, shader_id, entries)
            shader["entryPointSelection"] = dict(selection["evidence"])
            selected = selection.get("entry")
            if selected is not None:
                shader["entryPoint"] = _frame_flow_text(
                    getattr(selected, "name", ""), 256)
                reflection = ctrl.GetShader(
                    pipeline_id, shader_id, selected)
                identity_failure = (
                    _shader_reflection_identity_failure(
                        reflection, selected, shader_id, pipeline_id,
                        stage_name, selection)
                    if reflection is not None else None)
                if identity_failure is not None:
                    shader.update(identity_failure)
                    reflection = None
        except Exception:
            pass
        if reflection is not None:
            blocks = list(getattr(reflection, "constantBlocks", []) or [])
            samplers = list(getattr(reflection, "samplers", []) or [])
            shader["constantBufferCount"] = len(blocks)
            shader["samplerCount"] = len(samplers)
        try:
            try:
                bound_samplers = list(ps.GetSamplers(stage, True) or [])
            except TypeError:
                bound_samplers = list(ps.GetSamplers(stage) or [])
            shader["boundSamplerCount"] = len(bound_samplers)
            sampler_bindings_resolved = True
        except Exception:
            bound_samplers = []
            sampler_bindings_resolved = False
        sampler_counts = {"bindingsResolved": sampler_bindings_resolved}
        if "samplerCount" in shader:
            sampler_counts["declaredCount"] = shader["samplerCount"]
        if "boundSamplerCount" in shader:
            sampler_counts["boundCount"] = shader["boundSamplerCount"]
        if sampler_bindings_resolved:
            sampler_counts["bindings"] = [
                _pass_sampler_binding(value)
                for value in bound_samplers[:MAX_FRAME_FLOW_SAMPLERS_PER_STAGE]
            ]
            if len(bound_samplers) > MAX_FRAME_FLOW_SAMPLERS_PER_STAGE:
                sampler_counts["bindingOmittedCount"] = (
                    len(bound_samplers) - MAX_FRAME_FLOW_SAMPLERS_PER_STAGE)
        if len(sampler_counts) > 1 or sampler_bindings_resolved:
            sampler_summary[stage_name] = sampler_counts
        shaders[stage_name] = shader
        reads, omitted = _bound_resources(
            "GetReadOnlyResources", stage, stage_name, "shader-read")
        inputs.extend(reads)
        input_omitted += omitted
        constants, omitted = _bound_resources(
            "GetConstantBlocks", stage, stage_name, "constant-buffer")
        inputs.extend(constants)
        input_omitted += omitted
        read_writes, omitted = _bound_resources(
            "GetReadWriteResources", stage, stage_name, "read-write")
        flags_type = getattr(rd, "DescriptorFlags", None)
        read_only_mask = _safe_int(
            getattr(flags_type, "ReadOnlyAccess", 0x8), 0x8)
        write_only_mask = _safe_int(
            getattr(flags_type, "WriteOnlyAccess", 0x10), 0x10)
        for value in read_writes:
            descriptor_flags = _safe_int(value.pop("descriptorFlags", 0), 0)
            read_allowed = not bool(descriptor_flags & write_only_mask)
            write_allowed = not bool(descriptor_flags & read_only_mask)
            if read_allowed:
                read_value = dict(value)
                read_value["access"] = (
                    "read-write" if write_allowed else "shader-read")
                inputs.append(read_value)
            if write_allowed:
                write_value = dict(value)
                write_value["access"] = (
                    "read-write" if read_allowed else "shader-write")
                outputs.append(write_value)
        # A single descriptor can count against both directions; the bounded
        # final de-duplication below reports any additional omission exactly.
        input_omitted += omitted
        output_omitted += omitted

    graphics_output_mask = _action_flags_mask(
        ("Drawcall", "MeshDispatch"), 0x0002 | 0x0008)
    if action_flags & graphics_output_mask:
        stream_outputs, omitted = _pass_stream_output_resources(
            ctrl, lambda resource_id: _fact(
                resource_id, "stream-output", "stream-output"))
        outputs.extend(stream_outputs)
        output_omitted += omitted

    try:
        vertex_buffers = list(ps.GetVBuffers() or [])
        vertex_buffer_bindings_resolved = True
    except Exception:
        vertex_buffers = []
        vertex_buffer_bindings_resolved = False
    try:
        vertex_inputs = list(ps.GetVertexInputs() or [])
        vertex_input_usage_resolved = True
        used_vertex_slots = sorted(set(
            _safe_int(getattr(value, "vertexBuffer", -1), -1)
            for value in vertex_inputs
            if getattr(value, "used", False) is True
            and getattr(value, "genericEnabled", False) is not True
            and _safe_int(getattr(value, "vertexBuffer", -1), -1) >= 0))
    except Exception:
        vertex_inputs = []
        used_vertex_slots = []
        vertex_input_usage_resolved = False
    vertex_layout, vertex_layout_omitted = _pass_vertex_layout(vertex_inputs)
    for slot in used_vertex_slots[:MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]:
        if slot >= len(vertex_buffers):
            continue
        binding = vertex_buffers[slot]
        info = _bound_descriptor_info(binding)
        if info.get("resourceId"):
            fact = _fact(info["resourceId"], "vertex-buffer", "vertex")
            fact["byteOffset"] = _safe_int(info.get("byteOffset", 0), 0)
            fact["byteSize"] = _safe_int(info.get("byteSize", 0), 0)
            fact["byteStride"] = info.get("byteStride")
            inputs.append(fact)
    input_omitted += max(
        0, len(used_vertex_slots) - MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION)
    try:
        index = _bound_descriptor_info(ps.GetIBuffer())
        index_buffer_binding_resolved = True
    except Exception:
        index = {"resourceId": 0}
        index_buffer_binding_resolved = False
    indexed_mask = _action_flags_mask(("Indexed",), 0x010000)
    if index.get("resourceId") and indexed_mask and action_flags & indexed_mask:
        fact = _fact(index["resourceId"], "index-buffer", "vertex")
        fact["byteOffset"] = _safe_int(index.get("byteOffset", 0), 0)
        fact["byteSize"] = _safe_int(index.get("byteSize", 0), 0)
        fact["byteStride"] = index.get("byteStride")
        inputs.append(fact)

    targets = []
    blends = []
    try:
        blends = list(ps.GetColorBlends() or [])
    except Exception:
        pass
    try:
        raw_targets = list(ps.GetOutputTargets() or [])
    except Exception:
        raw_targets = []
    target_indices = []
    color_target_states = []
    for target_index, target in enumerate(
            raw_targets[:MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]):
        resource_id = _resource_id_int(getattr(target, "resource", None))
        if resource_id:
            fact = _fact(resource_id, "color-target")
            fact["slot"] = target_index
            _frame_flow_descriptor_fields(fact, target)
            targets.append(fact)
            target_indices.append(target_index)
            if target_index < len(blends):
                blend = blends[target_index]
                blend_state = _pass_color_blend_state(blend, target_index)
                color_target_states.append(blend_state)
                write_mask = blend_state["writeMask"]
                if write_mask is not None and write_mask > 0:
                    outputs.append(fact)
                elif write_mask is None:
                    possible = dict(fact)
                    possible["access"] = "color-target-possible"
                    possible["certainty"] = "unknown-write-mask"
                    possible_outputs.append(possible)
            else:
                possible = dict(fact)
                possible["access"] = "color-target-possible"
                possible["certainty"] = "unknown-write-mask"
                possible_outputs.append(possible)
    output_omitted += max(
        0, len(raw_targets) - MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION)
    try:
        depth_binding = ps.GetDepthTarget()
    except Exception:
        depth_binding = None
    depth_id = _resource_id_int(
        getattr(depth_binding, "resource", None)) if depth_binding else 0
    depth_fact = _fact(depth_id, "depth-target-bound") if depth_id else None
    if depth_fact is not None:
        _frame_flow_descriptor_fields(depth_fact, depth_binding)

    draw_state = _pass_draw_state(ps)
    draw_state.update(_pass_depth_state(ctrl))
    draw_state["colorTargetStates"] = color_target_states
    draw_state["colorWriteMasksResolved"] = bool(
        len(color_target_states) == len(targets))
    if draw_state.get("stencilWriteOperationsCanWrite") is not None:
        draw_state["stencilWritePossible"] = bool(
            draw_state.get("stencilTestEnabled") is True and
            draw_state.get("stencilReadOnly") is not True and
            draw_state.get("stencilWriteOperationsCanWrite") is True)
    draw_state["vertexBufferBindingsResolved"] = (
        vertex_buffer_bindings_resolved)
    draw_state["vertexInputUsageResolved"] = vertex_input_usage_resolved
    draw_state["vertexLayout"] = vertex_layout
    draw_state["vertexLayoutOmittedCount"] = vertex_layout_omitted
    draw_state["indexBufferBindingResolved"] = (
        index_buffer_binding_resolved)
    draw_state["indexStride"] = index.get("byteStride")
    draw_state["blendEnabled"] = _pass_blend_enabled(blends)
    draw_state.update(_pass_attachment_sample_state(targets, depth_fact))
    if sampler_summary:
        draw_state["samplers"] = sampler_summary
    raster_applicable, raster_reason = _raster_output_applicability(
        action_flags, action is not None, shaders, draw_state,
        fragment_stage_resolved)
    no_fragment_shader = bool(
        fragment_stage_resolved and "fragment" not in shaders)
    draw_state["rasterOutputApplicable"] = raster_applicable
    if raster_reason:
        draw_state["rasterOutputSuppressionReason"] = raster_reason
    if raster_applicable is False:
        inputs = _without_raster_io(inputs)
        outputs = _without_raster_io(outputs)
        possible_outputs = _without_raster_io(possible_outputs)
        targets = []
        target_indices = []
        depth_id = 0
        depth_fact = None
    else:
        if no_fragment_shader:
            inputs = _without_color_raster_io(inputs)
            outputs = _without_color_raster_io(outputs)
            possible_outputs = _without_color_raster_io(possible_outputs)
            targets = []
            target_indices = []
        if raster_applicable is None:
            outputs, downgraded = _downgrade_raster_writes(
                outputs, "unknown-rasterizer-discard")
            possible_outputs.extend(downgraded)
    blend_read_targets = []
    for target, target_index in zip(targets, target_indices):
        if target_index >= len(blends):
            continue
        blend_state = _pass_color_blend_state(
            blends[target_index], target_index)
        if (blend_state["writeMask"] is None or
                blend_state["writeMask"] <= 0 or
                not (
                    blend_state["blendEnabled"] is True or
                    blend_state["logicOperationEnabled"] is True)):
            continue
        blend_read_targets.append(target)
    if blend_read_targets:
        draw_state["blendReadTargets"] = [
            value["resourceId"] for value in blend_read_targets]
        for target in blend_read_targets:
            inputs.append(_fact(
                target["resourceId"], "blend-destination"))
    if depth_id and draw_state.get("depthTestEnabled") is True:
        inputs.append(_fact(depth_id, "depth-test"))
    if depth_id and draw_state.get("stencilTestEnabled") is True:
        inputs.append(_fact(depth_id, "stencil-test"))
    if (depth_id and raster_applicable is True and
            draw_state.get("depthTestEnabled") is True and
            draw_state.get("depthWriteEnabled") is True):
        outputs.append(_fact(depth_id, "depth-target"))
    elif (depth_id and draw_state.get("depthTestEnabled") is not False and
            draw_state.get("depthWriteEnabled") is not False):
        possible = _fact(depth_id, "depth-target-possible")
        possible["certainty"] = (
            "unknown-rasterizer-discard"
            if raster_applicable is None else "unknown")
        possible_outputs.append(possible)
    if (depth_id and draw_state.get("stencilTestEnabled") is True and
            draw_state.get("stencilWritePossible") is True):
        possible = _fact(depth_id, "stencil-target-possible")
        possible["certainty"] = (
            "unknown-rasterizer-discard"
            if raster_applicable is None else "state-possible")
        possible_outputs.append(possible)

    flags = _safe_int(getattr(action, "flags", 0), 0) if action else 0
    workload = _action_workload(action) if action is not None else {}
    indirect = bool(flags & _action_flags_mask(("Indirect",), 0x080000))
    draw_mask = _action_flags_mask(("Drawcall",), 0x0002)
    mesh_mask = _action_flags_mask(("MeshDispatch",), 0x0008)
    dispatch_mask = _action_flags_mask(
        ("Dispatch", "DispatchRay"), 0x0004 | 0x4000)
    clear_mask = _action_flags_mask(("Clear",), 0x0001)
    copy_mask = _action_flags_mask(("Copy",), 0x0400)
    resolve_mask = _action_flags_mask(("Resolve",), 0x0800)
    gen_mips_mask = _action_flags_mask(("GenMips",), 0x1000)
    present_mask = _action_flags_mask(("Present",), 0x0100)
    build_as_mask = _action_flags_mask(
        ("BuildAccelerationStructure",), 0x8000)
    utility_mask = (
        clear_mask | copy_mask | resolve_mask | gen_mips_mask |
        present_mask | build_as_mask)

    if action is not None:
        if flags & utility_mask:
            # Pipeline bindings around utility actions can be stale state from
            # the preceding draw. Rebuild utility I/O only from the action's
            # own declared source/destination facts.
            inputs = []
            outputs = []
            possible_outputs = []
            input_omitted = 0
            output_omitted = 0
            shaders = {}
            targets = []
            depth_id = 0
            draw_state = {"pipelineStateApplicable": False}
        copy_source = _resource_id_int(getattr(action, "copySource", None))
        copy_destination = _resource_id_int(
            getattr(action, "copyDestination", None))
        if copy_source:
            fact = _fact(copy_source, "copy-source")
            subresource = _frame_flow_subresource(
                getattr(action, "copySourceSubresource", None))
            if subresource:
                fact["subresource"] = subresource
            inputs.append(fact)
        if copy_destination and not (flags & present_mask):
            fact = _fact(copy_destination, "copy-destination")
            subresource = _frame_flow_subresource(
                getattr(action, "copyDestinationSubresource", None))
            if subresource:
                fact["subresource"] = subresource
            outputs.append(fact)
        declared_outputs = [
            _resource_id_int(value)
            for value in (getattr(action, "outputs", None) or [])
            if _resource_id_int(value)
        ]
        if flags & utility_mask and copy_destination and not (flags & present_mask):
            # Utility actions inherit the preceding pipeline's bound RTs. The
            # native destination identifies the actual clear/discard/transfer;
            # retain an identical alias, never unrelated inherited targets.
            declared_outputs = [value for value in declared_outputs if value == copy_destination]
        for resource_id in declared_outputs[
                :MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION]:
            if flags & present_mask:
                inputs.append(_fact(resource_id, "present-source"))
            elif flags & (
                    clear_mask | copy_mask | resolve_mask | gen_mips_mask):
                outputs.append(_fact(resource_id, "action-output"))
            elif flags & utility_mask:
                possible = _fact(resource_id, "action-output-possible")
                possible["certainty"] = "unknown-utility-write"
                possible_outputs.append(possible)
        if len(declared_outputs) > MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION:
            omitted = (
                len(declared_outputs) - MAX_FRAME_FLOW_RESOURCES_PER_DIRECTION)
            if flags & present_mask:
                input_omitted += omitted
            else:
                output_omitted += omitted
        depth_output = _resource_id_int(getattr(action, "depthOut", None))
        if (depth_output and not (flags & present_mask) and
                (not (flags & utility_mask) or not copy_destination or depth_output == copy_destination)):
            if flags & clear_mask:
                outputs.append(_fact(depth_output, "action-depth-output"))
            elif flags & utility_mask:
                possible = _fact(depth_output, "action-depth-output-possible")
                possible["certainty"] = "unknown-utility-write"
                possible_outputs.append(possible)
            elif (flags & draw_mask and raster_applicable is not False):
                if (raster_applicable is True and
                        draw_state.get("depthTestEnabled") is True and
                        draw_state.get("depthWriteEnabled") is True):
                    outputs.append(_fact(depth_output, "depth-target"))
                elif (draw_state.get("depthTestEnabled") is not False and
                        draw_state.get("depthWriteEnabled") is not False):
                    possible = _fact(
                        depth_output, "depth-target-possible")
                    possible["certainty"] = (
                        "unknown-rasterizer-discard"
                        if raster_applicable is None else "unknown")
                    possible_outputs.append(possible)

    if flags & (copy_mask | resolve_mask):
        outputs = _coalesce_utility_output_aliases(outputs)

    inputs, locally_omitted = _unique(inputs)
    input_omitted += locally_omitted
    outputs, locally_omitted = _unique(outputs)
    output_omitted += locally_omitted
    possible_outputs, locally_omitted = _unique(possible_outputs)
    output_omitted += locally_omitted

    issued_action = bool(
        flags & (draw_mask | mesh_mask | dispatch_mask | utility_mask))
    non_zero = None
    if indirect:
        non_zero = None
    elif flags & (mesh_mask | dispatch_mask):
        if all(key in workload for key in (
                "groupCountX", "groupCountY", "groupCountZ")):
            non_zero = all(
                workload[key] > 0 for key in
                ("groupCountX", "groupCountY", "groupCountZ"))
    elif flags & draw_mask:
        non_zero = (
            max(workload.get("indexCount", 0),
                workload.get("vertexCount", 0)) > 0 and
            workload.get("instanceCount", 0) > 0)
    elif flags & utility_mask:
        non_zero = True
    output_candidate = non_zero is not False and bool(
        outputs or possible_outputs)
    if flags & (draw_mask | mesh_mask):
        action_kind = "graphics"
    elif flags & dispatch_mask:
        action_kind = "compute"
    elif flags & utility_mask:
        action_kind = "utility"
    else:
        action_kind = "unknown"

    result = {
        "eventId": event_id,
        "actionKind": action_kind,
        "shaders": shaders,
        "renderTargets": [value["resourceId"] for value in targets],
        "depthTarget": depth_id or None,
        "inputs": inputs,
        "outputs": outputs,
        "possibleOutputs": possible_outputs,
        "inputOmittedCount": input_omitted,
        "outputOmittedCount": output_omitted,
        "resourceMetadata": resource_metadata_receipt,
        "drawState": draw_state,
        "workload": workload,
        "actualWorkState": (
            "output-affecting-candidate"
            if output_candidate else "not-established"),
        "participation": {
            "issuedAction": issued_action,
            "nonZeroWorkload": non_zero,
            "outputAffectingCandidate": output_candidate,
            "observedContributor": False,
            "contributorObservation": (
                "not-tested; no pixel history, resource diff, or contribution counter was run"),
            "indirectArgumentsResolved": False if indirect else None,
        },
    }
    if "viewport" in draw_state:
        viewport = draw_state["viewport"]
        result["viewport"] = {
            "x": viewport.get("x", 0), "y": viewport.get("y", 0),
            "w": viewport.get("width", 0),
            "h": viewport.get("height", 0),
        }
    if "vertex" in shaders:
        result["vertexShader"] = shaders["vertex"]["shaderId"]
    if "fragment" in shaders:
        result["fragmentShader"] = shaders["fragment"]["shaderId"]
    return result


def _get_draw_call_details(params):
    """Get details of a specific draw call."""
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")

    def _do(ctrl):
        _select_event_for_read(ctrl, event_id)
        return _draw_call_details_on_replay(ctrl, event_id)

    return _replay(_do)


def _inspect_event(params):
    """Collect draw and pipeline evidence in one replay-thread transaction."""
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")
    event_id = int(event_id)

    def _do(ctrl):
        _select_event_for_read(ctrl, event_id)
        return {
            "schema": "renderdoc-internal-inspect-event/v1",
            "eventId": event_id,
            "drawCall": _draw_call_details_on_replay(ctrl, event_id),
            "pipeline": _pipeline_state_on_replay(ctrl),
        }

    return _replay(_do)


def _inspect_event_api_parameters(params):
    """Read exact captured API arguments without changing the selected EID."""
    from .frame_stage_evidence import event_api_evidence
    expected = params.get("expected_capture_session_id")
    if not expected or expected != _capture_session_id or not _request_capture_loaded():
        raise RuntimeError("API evidence belongs to a different capture session")

    def read():
        if expected != _capture_session_id:
            raise RuntimeError("Capture changed while reading API evidence")
        result = event_api_evidence(_ctx, params.get("event_id"), _resource_id_int,
                                    params.get("max_depth", 6), params.get("max_nodes", 512))
        result["captureSessionId"] = expected
        return result

    result = _invoke_on_ui_sync(read)
    call = result.get("indirect", {}).get("call", {})
    command = call.get("command")
    formats = {"vkCmdDrawIndexedIndirect": ("<IIIiI", ("indexCount", "instanceCount", "firstIndex", "vertexOffset", "firstInstance")),
               "vkCmdDrawIndirect": ("<IIII", ("vertexCount", "instanceCount", "firstVertex", "firstInstance")),
               "vkCmdDispatchIndirect": ("<III", ("groupCountX", "groupCountY", "groupCountZ"))}
    if command in formats and call.get("drawCount") == 1:
        import base64
        import struct
        fmt, fields = formats[command]
        receipt = _get_buffer_data({"resource_id": call["argumentBufferId"], "offset": call["argumentOffset"],
            "length": struct.calcsize(fmt), "event_id": params["event_id"], "before_action": True,
            "expected_capture_session_id": expected})
        raw = base64.b64decode(receipt["base64"])
        if len(raw) == struct.calcsize(fmt):
            values = dict(zip(fields, struct.unpack(fmt, raw)))
            work = {key: value for key, value in values.items() if key in ("indexCount", "vertexCount", "instanceCount", "groupCountX", "groupCountY", "groupCountZ")}
            result["indirect"].update(status="resolved", decoded={"status": "resolved", "eventId": params["event_id"],
                "source": "event-bound-indirect-arguments", "workload": work,
                "nonZeroWorkload": all(value > 0 for value in work.values()), "arguments": values, "bufferEvidence": receipt})
    return result


def _inspect_frame_render_stage(params):
    from .frame_stage_evidence import inventory, resolved_indirect_workload
    event_id = _event_texture_evidence_int(params.get("event_id"), "event_id", 1, 0xFFFFFFFF)
    expected = params.get("expected_capture_session_id")
    if not expected or expected != _capture_session_id:
        raise RuntimeError("Frame stage belongs to a different capture session")
    original = _request_visible_event_id(0)

    def collect(ctrl):
        try:
            action = _find_action_by_event(ctrl.GetRootActions(), event_id)
            if action is None:
                raise ValueError("The requested EID is not an exact captured action")
            _set_frame_event(ctrl, event_id, True)
            details = _draw_call_details_on_replay(ctrl, event_id)
            if _ctx is not None and hasattr(_ctx, "GetStructuredFile"):
                decoded = resolved_indirect_workload(action, _ctx.GetStructuredFile())
                if decoded is not None:
                    details["indirectWorkload"] = decoded
                    if decoded.get("status") == "resolved":
                        details["workload"].update(decoded["workload"])
                        details["workload"]["indirectArgumentsResolved"] = True
                        details["participation"].update(indirectArgumentsResolved=True,
                                                        nonZeroWorkload=decoded["nonZeroWorkload"])
                        if decoded["nonZeroWorkload"] is False:
                            details["participation"]["outputAffectingCandidate"] = False
                            details["actualWorkState"] = "not-established"
            resources = inventory(ctrl, ctrl.GetPipelineState(), details,
                                  _available_shader_stages(list(details.get("shaders", {}))),
                                  _resource_id_int, _fmt_str, action=action)
            return dict(resources, schema="bread-frame-stage-evidence/v1", eventId=event_id,
                        captureSessionId=expected, details=details)
        finally:
            _set_frame_event(ctrl, original, True)

    result = _replay(collect)
    indirect = result.get("details", {}).get("indirectWorkload") or {}
    if indirect.get("status") == "unresolved":
        decoded = _inspect_event_api_parameters({"event_id": event_id,
            "expected_capture_session_id": expected}).get("indirect", {}).get("decoded")
        if decoded and decoded.get("status") == "resolved":
            result["details"]["indirectWorkload"] = decoded
            result["indirectWorkload"] = decoded
            result["details"]["workload"].update(decoded["workload"], indirectArgumentsResolved=True)
            result["details"]["participation"].update(indirectArgumentsResolved=True,
                nonZeroWorkload=decoded["nonZeroWorkload"])
            if decoded["nonZeroWorkload"] is False:
                result["details"]["participation"]["outputAffectingCandidate"] = False
                result["details"]["actualWorkState"] = "observed-no-work"
    if expected != _capture_session_id:
        raise RuntimeError("Capture changed while inspecting the frame stage")
    return result


def _texture_info_on_replay(ctrl, resource_id):
    """Collect texture metadata without entering the replay thread again."""
    name_lookup = {}
    for r in ctrl.GetResources():
        name_lookup[int(r.resourceId)] = r.name
    for t in ctrl.GetTextures():
        if int(t.resourceId) == int(resource_id):
            return {
                "id": int(t.resourceId), "name": name_lookup.get(int(t.resourceId), ""),
                "w": t.width, "h": t.height, "d": t.depth,
                "fmt": _fmt_str(t.format), "mips": t.mips,
                "array": t.arraysize, "size": t.byteSize,
            }
    return {"error": "Texture not found"}


def _get_effect_resource_info(params):
    expected = params.get("expected_capture_session_id")
    if not expected or expected != _capture_session_id:
        raise RuntimeError("Resource dependency belongs to another capture session")
    usage = _find_by_resource(params)
    texture = _get_texture_info(params)
    if expected != _capture_session_id:
        raise RuntimeError("Capture changed while inspecting resource dependencies")
    return {"usage": usage, "texture": texture, "captureSessionId": expected}


def _get_texture_info(params):
    """Get single texture info."""
    resource_id = params.get("resource_id")
    if resource_id is None:
        raise ValueError("resource_id required")

    return _replay(lambda ctrl: _texture_info_on_replay(ctrl, resource_id))


_event_texture_raw_cache = {}


def _get_event_texture_bytes(params):
    import base64
    import hashlib
    from .frame_flow_channels import mutation_identity
    expected = params.get("expected_capture_session_id")
    if expected != _capture_session_id or not _request_capture_loaded():
        raise RuntimeError("Texture read belongs to another capture session")
    event = _event_texture_evidence_int(params.get("event_id"), "event_id", 1, 0xFFFFFFFF)
    rid = int(params["resource_id"]); mip = int(params.get("mip", 0)); offset = int(params.get("offset", 0))
    slice_index = int(params.get("slice", 0)); sample_index = int(params.get("sample", 0))
    length = max(1, min(1024 * 1024, int(params.get("length", 1024 * 1024))))
    if offset < 0 or mip < 0 or slice_index < 0 or sample_index < 0:
        raise ValueError("Texture offset/mip must be non-negative")
    original = _request_visible_event_id(0)
    mutation = hashlib.sha256(json.dumps(mutation_identity(sys.modules[__name__])).encode("utf-8")).hexdigest()
    key = (expected, mutation, event, rid, mip, slice_index, sample_index)
    def read(ctrl):
        if key in _event_texture_raw_cache:
            return _event_texture_raw_cache[key]
        try:
            if _find_action_by_event(ctrl.GetRootActions(), event) is None:
                raise ValueError("Texture reads require an exact captured EID")
            _set_frame_event(ctrl, event, True)
            texture = next((row for row in ctrl.GetTextures() if int(row.resourceId) == rid), None)
            if texture is None or mip >= int(texture.mips):
                raise ValueError("Texture or requested mip is unavailable")
            if slice_index >= max(1,int(getattr(texture,"arraysize",1))) or sample_index >= max(1,int(getattr(texture,"msSamp",1))):
                raise ValueError("Texture slice/sample is unavailable")
            if int(texture.byteSize) > 256 * 1024 * 1024:
                raise ValueError("Texture exceeds bounded readback size")
            _event_texture_raw_cache.clear()
            data = bytes(ctrl.GetTextureData(texture.resourceId, rd.Subresource(mip, slice_index, sample_index)))
            if len(data) > 256 * 1024 * 1024:
                raise ValueError("Texture mip exceeds bounded readback size")
            metadata = {"width": max(1,int(texture.width)>>mip), "height": max(1,int(texture.height)>>mip),
                "depth": max(1,int(texture.depth)>>mip), "mips": int(texture.mips),
                "format": _fmt_str(texture.format), "dimension": str(texture.type),
                "arraySize": int(getattr(texture,"arraysize",1)), "samples": int(getattr(texture,"msSamp",1)),
                "sha256": hashlib.sha256(data).hexdigest()}
            result = (data, metadata)
            # Cache one bounded mip across all IPC chunks, including HDR 4K.
            _event_texture_raw_cache[key] = result
            return result
        finally:
            _set_frame_event(ctrl, original, True)
    data, metadata = _replay(read)
    if expected != _capture_session_id:
        raise RuntimeError("Capture changed while reading texture")
    if mutation != hashlib.sha256(json.dumps(mutation_identity(sys.modules[__name__])).encode("utf-8")).hexdigest():
        raise RuntimeError("Texture inputs changed during readback")
    part = data[offset:offset+length]
    return dict(metadata, eventId=event, resourceId=str(rid), mip=mip, offset=offset,
        sliceIndex=slice_index, sampleIndex=sample_index,
        length=len(data), returnedBytes=len(part), base64=base64.b64encode(part).decode("ascii"),
        captureSessionId=expected, mutationEpoch=key[1], restoredEventId=original)


def _get_texture_data(params):
    """Get texture pixel data as base64."""
    import base64
    resource_id = params.get("resource_id")
    if resource_id is None:
        raise ValueError("resource_id required")
    mip = params.get("mip", 0)
    slc = params.get("slice", 0)

    def _do(ctrl):
        tid = _resolve_resource_id(ctrl, resource_id, "texture")
        sub = rd.Subresource(mip, slc, 0)
        data = ctrl.GetTextureData(tid, sub)
        # Preserve the legacy 10,000-character response ceiling, but truncate on a complete raw
        # byte boundary so the base64 payload always decodes. 7,500 is divisible by three and
        # therefore encodes to exactly 10,000 characters without padding.
        returned = data[:7500]
        return {
            "resourceId": int(resource_id),
            "length": len(data),
            "returnedBytes": len(returned),
            "truncated": len(returned) < len(data),
            "encoding": "base64",
            "base64": base64.b64encode(returned).decode("ascii"),
        }

    return _replay(_do)


def _get_buffer_data(params):
    """Get buffer contents."""
    import base64
    import hashlib
    resource_id = params.get("resource_id")
    if resource_id is None:
        raise ValueError("resource_id required")
    offset = _safe_int(params.get("offset", 0), -1)
    requested_length = _safe_int(params.get("length", 256), 0)
    if offset < 0:
        raise ValueError("offset must be non-negative")
    if requested_length <= 0:
        raise ValueError("length must be positive")
    read_length = min(requested_length, MAX_BUFFER_DATA_BYTES)
    event_id = params.get("event_id")
    expected = params.get("expected_capture_session_id")
    original = _request_visible_event_id(0) if event_id is not None else None
    if event_id is not None:
        event_id = _event_texture_evidence_int(event_id, "event_id", 1, 0xFFFFFFFF)
        if expected != _capture_session_id:
            raise RuntimeError("Event buffer read belongs to another capture session")

    def _do(ctrl):
        bid = _resolve_resource_id(ctrl, resource_id, "buffer")
        try:
            if event_id is not None:
                if _find_action_by_event(ctrl.GetRootActions(), event_id) is None:
                    raise ValueError("Event buffer reads require an exact captured action")
                _set_frame_event(ctrl, event_id - 1 if params.get("before_action", True) else event_id, True)
            raw_data = ctrl.GetBufferData(bid, offset, read_length)
        finally:
            if event_id is not None:
                _set_frame_event(ctrl, original, True)
        data = raw_data[:read_length]
        base64_bytes = data
        hex_bytes = data[:512]
        return {
            "resourceId": int(resource_id),
            "offset": offset,
            "length": len(data),
            "returnedBytes": len(base64_bytes),
            "truncated": (requested_length > len(data) or
                          len(raw_data) > len(data)),
            "encoding": "base64",
            "base64": base64.b64encode(base64_bytes).decode("ascii"),
            "hex": hex_bytes.hex(),
            "hexReturnedBytes": len(hex_bytes),
            "hexTruncated": len(hex_bytes) < len(data),
            "eventId": event_id, "captureSessionId": _capture_session_id,
            "capturePhase": ("before-action" if params.get("before_action", True) else "after-action") if event_id is not None else "current-replay-state",
            "replayEventId": (event_id - 1 if params.get("before_action", True) else event_id) if event_id is not None else original,
            "restoredEventId": original,
            "sha256": hashlib.sha256(data).hexdigest(),
        }

    return _replay(_do)


def _pick_pixel(params):
    """Pick a pixel value from a texture."""
    resource_id = params.get("resource_id")
    x = params.get("x", 0)
    y = params.get("y", 0)
    if resource_id is None:
        raise ValueError("resource_id required")

    def _do(ctrl):
        tid = _resolve_resource_id(ctrl, resource_id, "texture")
        sub = rd.Subresource(0, 0, 0)
        val = ctrl.PickPixel(tid, x, y, sub, rd.CompType.Typeless)
        return {"x": x, "y": y, "r": val.floatValue[0], "g": val.floatValue[1],
                "b": val.floatValue[2], "a": val.floatValue[3]}

    return _replay(_do)


def _event_texture_evidence_int(value, name, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s must be an integer" % name)
    if value < minimum or value > maximum:
        raise ValueError(
            "%s must be between %d and %d" % (name, minimum, maximum))
    return int(value)


def _event_texture_evidence_float(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s must be a finite number" % name)
    result = float(value)
    if not math.isfinite(result) or abs(result) > 1.0e30:
        raise ValueError("%s must be a finite bounded number" % name)
    return result


def _event_texture_evidence_is_redirected(path):
    """Reject symlinks and Windows reparse points at an evidence boundary."""

    try:
        info = os.lstat(path)
    except OSError:
        return True
    if stat.S_ISLNK(info.st_mode):
        return True
    attributes = getattr(info, "st_file_attributes", 0)
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
    return bool(attributes & reparse_flag)


def _event_texture_evidence_hash(path, maximum_bytes):
    before = os.lstat(path)
    if (not stat.S_ISREG(before.st_mode) or
            _event_texture_evidence_is_redirected(path) or
            before.st_size <= 0 or before.st_size > maximum_bytes):
        raise RuntimeError("event texture evidence is not a bounded regular file")
    digest = hashlib.sha256()
    total = 0
    with open(path, "rb") as stream:
        while True:
            data = stream.read(min(1024 * 1024, maximum_bytes + 1 - total))
            if not data:
                break
            total += len(data)
            if total > maximum_bytes:
                raise RuntimeError("event texture evidence exceeded its byte budget")
            digest.update(data)
    after = os.lstat(path)
    if (total != before.st_size or after.st_size != before.st_size or
            getattr(after, "st_mtime_ns", None) !=
            getattr(before, "st_mtime_ns", None)):
        raise RuntimeError("event texture evidence changed while it was hashed")
    return total, digest.hexdigest()


def _reduce_saved_image(path, crop, max_dimension, opaque_rgb=False, flip_y=False,
                        preserve_channels=False):
    """Crop and shrink a saved image, using Qt's own image code.

    A model reading this has a finite context, and a 4K render target spends it on
    pixels that say nothing. Cropping to where the draw actually landed and scaling the
    result down keeps what the picture is *for* — what was drawn, and where — at a
    fraction of the size. Done before publication so the hash, the byte budget and the
    atomic link all apply to the file that is actually kept.

    Returns what was applied, or None when nothing was.
    """

    if not crop and not max_dimension and not opaque_rgb and not flip_y:
        return None
    try:
        from PySide2 import QtGui
    except Exception as exc:  # pragma: no cover - depends on the host runtime
        raise RuntimeError("PySide2 is unavailable for image reduction: %s" % exc)
    image = QtGui.QImage(path)
    if image.isNull():
        raise RuntimeError("the evidence PNG could not be read back for reduction")
    original = {"width": int(image.width()), "height": int(image.height())}
    applied = {"original": original, "crop": None, "scaledTo": None}
    if opaque_rgb:
        # RenderDoc's AlphaMapping.Discard does not affect PNG exports. Remove
        # alpha before Qt's smooth scaler premultiplies it: scene RGB may be
        # valid with alpha zero, and clearing alpha after scaling loses it.
        image = image.convertToFormat(QtGui.QImage.Format_RGB32)
        if image.isNull():
            raise RuntimeError("the evidence PNG could not be converted to opaque RGB")
        applied["opaqueRgbProcessed"] = True
    if crop:
        left = max(0, min(int(crop.get("x", 0)), original["width"] - 1))
        top = max(0, min(int(crop.get("y", 0)), original["height"] - 1))
        width = max(1, min(int(crop.get("width", 0)), original["width"] - left))
        height = max(1, min(int(crop.get("height", 0)), original["height"] - top))
        image = image.copy(left, top, width, height)
        if image.isNull():
            raise RuntimeError("the requested crop rectangle produced no image")
        applied["crop"] = {"x": left, "y": top, "width": width, "height": height}
    if flip_y:
        # Presentation transform only. Crop coordinates continue to address the
        # native subresource; hash the transformed file actually sent to the AI.
        image = image.mirrored(False, True)
        applied["flipYProcessed"] = True
    if max_dimension:
        longest = max(int(image.width()), int(image.height()))
        if longest > int(max_dimension):
            image = image.scaled(
                int(max_dimension), int(max_dimension),
                QtCore.Qt.KeepAspectRatio,
                QtCore.Qt.FastTransformation if preserve_channels else QtCore.Qt.SmoothTransformation)
            if image.isNull():
                raise RuntimeError("scaling the evidence PNG produced no image")
    applied["scaledTo"] = {"width": int(image.width()), "height": int(image.height())}
    if not image.save(path, "PNG"):
        raise RuntimeError("the reduced evidence PNG could not be written")
    return applied


def _save_decoded_grayscale_evidence(path, gray, width, height):
    from PySide2 import QtGui
    # Own the bytes until saving finishes; the external-buffer QImage overload does not copy them.
    pixels = bytes(gray)
    image = QtGui.QImage(pixels, width, height, width, QtGui.QImage.Format_Grayscale8)
    if image.isNull() or not image.save(path, "PNG"):
        raise RuntimeError("decoded scalar evidence could not be written as a PNG")


def _capture_event_texture_evidence(params, _controller=None, _original_event=None,
                                    _expected_resource_id=None):
    """Save one exact EID-bound RTV/DSV view into a Host-owned directory.

    This composite deliberately does not call the legacy ``_save_texture``
    handler: that API accepts arbitrary paths and is not capture/EID bound.
    """

    flip_y = params.get("flip_y", False)
    preserve_alpha = params.get("preserve_alpha", False)
    if type(flip_y) is not bool:
        raise ValueError("flip_y must be a boolean")
    if type(preserve_alpha) is not bool:
        raise ValueError("preserve_alpha must be a boolean")
    event_id = _event_texture_evidence_int(
        params.get("event_id"), "event_id", 1, 0xFFFFFFFF)
    attachment_kind = params.get("attachment_kind")
    if (not isinstance(attachment_kind, str) or
            attachment_kind not in ("rtv", "dsv", "uav", "srv", "present")):
        raise ValueError("attachment_kind must be rtv, dsv, uav, srv or present")
    attachment_index = _event_texture_evidence_int(
        params.get("attachment_index", 0), "attachment_index", 0,
        7 if attachment_kind in ("rtv", "dsv") else 4095)
    stage_name = params.get("stage", "fragment")
    stages = dict(_available_shader_stages([stage_name])) if attachment_kind in ("uav", "srv") else {}
    if attachment_kind in ("uav", "srv") and stage_name not in stages:
        raise ValueError("A supported Shader stage is required")
    if attachment_kind in ("dsv", "present") and attachment_index != 0:
        raise ValueError("a DSV or Present attachment_index must be 0")
    mip = _event_texture_evidence_int(params.get("mip"), "mip", 0, 0x7FFFFFFF)
    array_slice = _event_texture_evidence_int(
        params.get("slice"), "slice", 0, 0x7FFFFFFF)
    sample = _event_texture_evidence_int(
        params.get("sample"), "sample", 0, 0x7FFFFFFF)
    if attachment_kind == "present" and (mip or array_slice or sample):
        raise ValueError("Present evidence requires mip, slice and sample 0")

    raw_crop = params.get("crop")
    crop = None
    if raw_crop is not None:
        if not isinstance(raw_crop, dict):
            raise ValueError("crop must be an object with x, y, width and height")
        crop = {name: _event_texture_evidence_int(raw_crop.get(name), "crop.%s" % name,
                                                  0, 0x7FFFFFFF)
                for name in ("x", "y")}
        crop.update({name: _event_texture_evidence_int(raw_crop.get(name), "crop.%s" % name,
                                                       1, 0x7FFFFFFF)
                     for name in ("width", "height")})
    max_dimension = params.get("max_dimension")
    if max_dimension is not None:
        max_dimension = _event_texture_evidence_int(
            max_dimension, "max_dimension", 16, 8192)

    channel = params.get("channel")
    if (not isinstance(channel, str) or
            channel not in ("rgba", "r", "g", "b", "a", "depth")):
        raise ValueError("channel must be rgba, r, g, b, a, or depth")
    if attachment_kind == "dsv" and channel != "depth":
        raise ValueError("DSV evidence only supports the raw depth channel")
    if attachment_kind != "dsv" and channel == "depth":
        raise ValueError("the depth channel requires a DSV attachment")
    value_decode = params.get("value_decode", "native")
    if value_decode not in ("native", "float32-bits"):
        raise ValueError("value_decode must be native or float32-bits")
    if value_decode != "native" and channel not in ("r", "rgba"):
        raise ValueError("float32-bits evidence requires the r or rgba channel")

    range_mode = params.get("range_mode", "visible-distribution")
    if (not isinstance(range_mode, str) or
            range_mode not in ("native", "explicit", "subresource-minmax", "visible-distribution")):
        raise ValueError(
            "range_mode must be native, explicit, subresource-minmax, or visible-distribution")
    supplied_black = params.get("black_point")
    supplied_white = params.get("white_point")
    if range_mode == "explicit":
        black_point = _event_texture_evidence_float(
            supplied_black, "black_point")
        white_point = _event_texture_evidence_float(
            supplied_white, "white_point")
        if black_point >= white_point:
            raise ValueError("black_point must be less than white_point")
        if (channel == "depth" and
                (black_point < 0.0 or white_point > 1.0)):
            raise ValueError("raw depth display range must remain within [0, 1]")
    else:
        if supplied_black is not None or supplied_white is not None:
            raise ValueError(
                "black_point and white_point are only valid for explicit range")
        black_point = 0.0 if range_mode == "native" else None
        white_point = 1.0 if range_mode == "native" else None

    expected_session = params.get("expected_capture_session_id")
    if (not _capture_session_id or expected_session != _capture_session_id or
            not isinstance(expected_session, str) or
            len(expected_session) != 32 or
            not re.match(r"^[0-9a-f]{32}$", expected_session)):
        raise ValueError(
            "active capture session changed before texture evidence capture")
    request_id = params.get("request_id")
    if (not isinstance(request_id, str) or
            len(request_id) != 32 or
            not re.match(r"^[0-9a-f]{32}$", request_id)):
        raise ValueError("request_id must be 32 lowercase hexadecimal characters")

    raw_artifact_dir = params.get("artifact_dir")
    if (not isinstance(raw_artifact_dir, str) or not raw_artifact_dir or
            "\x00" in raw_artifact_dir or not os.path.isabs(raw_artifact_dir)):
        raise ValueError("artifact_dir must be an absolute Host-owned directory")
    artifact_dir = os.path.abspath(os.path.normpath(raw_artifact_dir))
    expected_dir_name = "eid-%d-%s" % (event_id, request_id)
    if os.path.basename(artifact_dir) != expected_dir_name:
        raise ValueError("artifact_dir is not bound to this EID and request")
    if (not os.path.isdir(artifact_dir) or
            _event_texture_evidence_is_redirected(artifact_dir) or
            os.path.normcase(os.path.realpath(artifact_dir)) !=
            os.path.normcase(artifact_dir)):
        raise ValueError("artifact_dir is unavailable or redirected")
    if os.listdir(artifact_dir):
        raise ValueError("artifact_dir must be a new empty directory")

    try:
        original_event = (_request_visible_event_id(0) if _controller is None
                          else _original_event)
    except Exception:
        raise RuntimeError("the original visible EID is unavailable")
    if original_event < 0 or original_event > 0xFFFFFFFF:
        raise RuntimeError("the original visible EID is invalid")

    channel_extract = {
        "rgba": -1,
        "r": 0,
        "g": 1,
        "b": 2,
        "a": 3,
        "depth": 0,
    }[channel]
    budgets = {
        "maxTextureByteSize": MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES,
        "maxSubresourcePixels": MAX_EVENT_TEXTURE_EVIDENCE_PIXELS,
        "maxPngByteSize": MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES,
    }

    def _do(ctrl):
        def _capture_at_event():
            if expected_session != _capture_session_id:
                raise RuntimeError(
                    "capture session changed while selecting texture evidence EID")
            try:
                action = _find_action_by_event(ctrl.GetRootActions(), event_id)
            except Exception:
                action = None
            if action is None:
                raise RuntimeError("event_id is not an exact captured action EID")

            from .frame_stage_evidence import bindings, present_output_binding
            pipeline = ctrl.GetPipelineState() if attachment_kind != "present" else None
            if attachment_kind in ("uav", "srv"):
                compatible = _ai_context_protocol.compatible_shader_stages({
                    "eventId": event_id, "flags": str(action.flags), "matchesCurrentEvent": True})
                if stage_name not in compatible:
                    raise ValueError("Shader stage does not execute at this event")
            targets = ([present_output_binding(action, ctrl, _resource_id_int)]
                       if attachment_kind == "present" else
                       bindings(pipeline, attachment_kind, stages.get(stage_name)))
            if attachment_index >= len(targets):
                raise RuntimeError("The requested texture binding index is unavailable at this EID")
            binding = targets[attachment_index]
            descriptor = getattr(binding, "descriptor", binding)
            resource_id = _resource_id_int(
                getattr(descriptor, "resource", None))
            if not resource_id:
                resource_id = _resource_id_int(
                    getattr(binding, "resource", None))
            if not resource_id:
                raise RuntimeError(
                    "the requested %s is not bound at this EID" %
                    attachment_kind.upper())
            if _expected_resource_id is not None and resource_id != _expected_resource_id:
                raise RuntimeError("texture binding no longer matches the requested resource")

            texture = None
            resolved_resource = None
            for candidate in ctrl.GetTextures() or []:
                candidate_id = _resource_id_int(
                    getattr(candidate, "resourceId", None))
                if candidate_id == resource_id:
                    texture = candidate
                    resolved_resource = getattr(candidate, "resourceId", None)
                    break
            if texture is None or resolved_resource is None:
                raise RuntimeError("the bound output texture description is unavailable")

            def _descriptor_uint(name):
                raw = getattr(descriptor, name, None)
                if isinstance(raw, bool):
                    raise RuntimeError(
                        "the output binding has an invalid %s" % name)
                try:
                    result = int(raw)
                except Exception:
                    raise RuntimeError(
                        "the output binding does not expose exact %s" % name)
                if result < 0 or result > 0xFFFFFFFF:
                    raise RuntimeError(
                        "the output binding has an invalid %s" % name)
                return result

            first_mip = _descriptor_uint("firstMip")
            num_mips = _descriptor_uint("numMips")
            first_slice = _descriptor_uint("firstSlice")
            num_slices = _descriptor_uint("numSlices")
            texture_mips = max(0, _safe_int(getattr(texture, "mips", 0), 0))
            texture_width = max(0, _safe_int(getattr(texture, "width", 0), 0))
            texture_height = max(0, _safe_int(getattr(texture, "height", 0), 0))
            texture_depth = max(0, _safe_int(getattr(texture, "depth", 0), 0))
            texture_array = max(
                0, _safe_int(getattr(texture, "arraysize", 0), 0))
            sample_count = max(0, _safe_int(getattr(texture, "msSamp", 0), 0))
            texture_byte_size = max(
                0, _safe_int(getattr(texture, "byteSize", 0), 0))
            if (texture_mips <= 0 or texture_width <= 0 or texture_height <= 0 or
                    texture_array <= 0 or sample_count <= 0):
                raise RuntimeError("the bound texture dimensions are unavailable")
            if num_mips <= 0 or first_mip >= texture_mips:
                raise RuntimeError("the output binding mip range is invalid")
            bound_mip_end = min(texture_mips, first_mip + num_mips)
            if mip < first_mip or mip >= bound_mip_end:
                raise RuntimeError(
                    "the requested mip is not part of the bound output view")
            from .frame_stage_evidence import texture_slice_view
            native_descriptor = {
                "firstMip": first_mip, "numMips": num_mips,
                "firstSlice": first_slice, "numSlices": num_slices,
            }
            slice_view = texture_slice_view(texture, descriptor, attachment_kind, mip)
            first_slice = slice_view["viewSliceFirst"]
            num_slices = slice_view["viewSliceCount"]
            bound_slice_end = first_slice + num_slices
            if array_slice < first_slice or array_slice >= bound_slice_end:
                raise RuntimeError(
                    "the requested slice is not part of the bound output view")
            if sample >= sample_count:
                raise RuntimeError(
                    "the requested sample is not present in the bound texture")

            mip_width = max(1, texture_width >> mip)
            mip_height = max(1, texture_height >> mip)
            pixel_count = mip_width * mip_height
            texture_format = getattr(texture, "format", None)
            component_type = getattr(texture_format, "compType", rd.CompType.Typeless)
            type_cast = rd.CompType.Typeless
            if component_type == rd.CompType.Typeless:
                view_type = getattr(getattr(descriptor, "format", None), "compType", rd.CompType.Typeless)
                if view_type != rd.CompType.Typeless:
                    component_type = type_cast = view_type
            component_count = max(
                0, _safe_int(getattr(texture_format, "compCount", 0), 0))
            if component_count <= 0 or component_count > 4:
                raise RuntimeError("the output texture component count is unavailable")
            if channel_extract >= component_count and channel_extract >= 0:
                raise RuntimeError(
                    "the requested channel is absent from the output texture")
            if value_decode == "float32-bits" and (
                    component_count != 1 or
                    getattr(texture_format, "compByteWidth", None) != 4 or
                    component_type != getattr(rd.CompType, "UInt", None) or
                    getattr(texture_format, "Special", lambda: True)() or
                    getattr(texture, "dimension", None) != 2 or texture_depth != 1 or
                    sample_count != 1):
                raise ValueError("float32-bits requires a regular R32_UINT 2D non-MS texture")

            attachment = {
                "kind": attachment_kind,
                "index": attachment_index,
                "stage": stage_name,
                "resourceId": resource_id,
                "mip": mip,
                "slice": array_slice,
                "sample": sample,
                "viewWidth": mip_width,
                "viewHeight": mip_height,
                "format": _fmt_str(texture_format)[:256],
                "componentCount": component_count,
                "textureByteSize": texture_byte_size,
                "sampleCount": sample_count,
                "presentedBackbuffer": attachment_kind == "present",
                "descriptor": {
                    "firstMip": first_mip,
                    "numMips": num_mips,
                    "firstSlice": first_slice,
                    "numSlices": num_slices,
                },
                "nativeDescriptor": native_descriptor,
            }
            attachment.update(slice_view)
            if slice_view["textureDimension"] == 3:
                attachment["depthSlice"] = array_slice
            display = {
                "channel": channel,
                "flipY": flip_y,
                "channelExtract": channel_extract,
                "rangeMode": range_mode,
                "blackPoint": black_point,
                "whitePoint": white_point,
                "subresourceMin": None,
                "subresourceMax": None,
                "valueDecode": value_decode,
                "depthInterpretation": (
                    "raw-resource-component-0" if channel == "depth" else None),
            }

            def _skipped(reason):
                return {
                    "status": "skipped",
                    "skipReason": reason,
                    "attachment": attachment,
                    "display": display,
                    "output": None,
                }

            if texture_byte_size <= 0:
                return _skipped("source-size-unavailable")
            if texture_byte_size > MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES:
                return _skipped("source-size-budget-exceeded")
            # Large atlas UAVs (e.g. 16384 x 2048 page tables) still need a
            # readable overview. Allow a bounded 32 Mpix source only when the
            # caller explicitly requests a small presentation preview.
            pixel_budget = MAX_EVENT_TEXTURE_EVIDENCE_PIXELS
            if max_dimension and max_dimension <= 2048:
                pixel_budget = max(pixel_budget, 32 * 1024 * 1024)
            if pixel_count > pixel_budget:
                return _skipped("subresource-pixel-budget-exceeded")

            decoded_gray = None
            if value_decode == "float32-bits":
                from .texture_value_decode import decode_r32_uint_grayscale
                # Read complete bytes directly inside this exact-event transaction. The legacy
                # get_texture_data endpoint truncates its transport and cannot decode an atlas.
                raw = ctrl.GetTextureData(resolved_resource, rd.Subresource(mip, array_slice, sample))
                decoded_gray, decoded_display = decode_r32_uint_grayscale(
                    raw, mip_width, mip_height, value_decode=value_decode,
                    range_mode=range_mode, black_point=supplied_black, white_point=supplied_white)
                display.update(decoded_display)
                del raw
                if decoded_gray is None:
                    if not decoded_display["decoding"]["finiteCount"]:
                        raise ValueError("No finite decoded texels; use visible-distribution or explicit range")
                    return _skipped("subresource-range-flat")
            elif range_mode in ("subresource-minmax", "visible-distribution"):
                subresource = rd.Subresource(mip, array_slice, sample)
                minimum, maximum = ctrl.GetMinMax(
                    resolved_resource, subresource, type_cast)
                # PixelValue is a union. Integer UAV/SRV ranges must not be
                # interpreted as the float bit-patterns of those values.
                value_field = "floatValue"
                if component_type == getattr(rd.CompType, "UInt", None):
                    value_field = "uintValue"
                elif component_type == getattr(rd.CompType, "SInt", None):
                    value_field = "intValue"
                minimum_components = getattr(minimum, value_field)
                maximum_components = getattr(maximum, value_field)
                minimum_values = []
                maximum_values = []
                for index in range(component_count):
                    if range_mode == "visible-distribution":
                        # An HDR target can contain NaN/Inf in unused cells.
                        # Keep their absence explicit in evidence; the finite
                        # GPU histogram still measures the occupied content.
                        low_value = float(minimum_components[index])
                        high_value = float(maximum_components[index])
                        minimum_values.append(low_value if math.isfinite(low_value) and abs(low_value) <= 1.0e30 else None)
                        maximum_values.append(high_value if math.isfinite(high_value) and abs(high_value) <= 1.0e30 else None)
                    else:
                        minimum_values.append(_event_texture_evidence_float(
                            minimum_components[index], "subresource minimum"))
                        maximum_values.append(_event_texture_evidence_float(
                            maximum_components[index], "subresource maximum"))
                    if (minimum_values[index] is not None and maximum_values[index] is not None and
                            minimum_values[index] > maximum_values[index]):
                        raise RuntimeError(
                            "subresource min/max returned an inverted component range")
                display["subresourceMin"] = minimum_values
                display["subresourceMax"] = maximum_values
                selected_indices = (
                    range(min(component_count, 3))
                    if channel == "rgba" else [channel_extract])
                if range_mode == "visible-distribution":
                    from .texture_preview_range import visible_distribution_range
                    mask = [index in selected_indices for index in range(4)]
                    normalized = component_type in (
                        getattr(rd.CompType, "UNorm", "__unorm_missing__"),
                        getattr(rd.CompType, "SNorm", "__snorm_missing__"))
                    def histogram(lower, upper, enabled):
                        return ctrl.GetHistogram(resolved_resource, subresource,
                                                 type_cast, lower, upper, enabled)
                    (display["blackPoint"], display["whitePoint"],
                     display["distribution"]) = visible_distribution_range(
                        histogram, minimum_values, maximum_values, mask,
                        depth=channel == "depth", normalized=normalized)
                else:
                    display["blackPoint"] = min(
                        minimum_values[index] for index in selected_indices)
                    display["whitePoint"] = max(
                        maximum_values[index] for index in selected_indices)
                if channel == "depth" and (
                        display["blackPoint"] < 0.0 or
                        display["whitePoint"] > 1.0):
                    raise RuntimeError(
                        "raw depth subresource range is outside [0, 1]")
                if display["blackPoint"] >= display["whitePoint"]:
                    return _skipped("subresource-range-flat")

            if expected_session != _capture_session_id:
                raise RuntimeError(
                    "capture session changed before texture evidence export")
            filename = (
                "eid-%d-%s%d-m%d-s%d-sample%d-%s.png" % (
                    event_id, attachment_kind, attachment_index, mip,
                    array_slice, sample, channel))
            final_path = os.path.join(artifact_dir, filename)
            temporary_path = os.path.join(
                artifact_dir, ".tmp-%s.png" % request_id)
            if os.path.lexists(final_path) or os.path.lexists(temporary_path):
                raise RuntimeError("event texture evidence path already exists")

            save = rd.TextureSave()
            save.resourceId = resolved_resource
            save.typeCast = type_cast
            save.destType = rd.FileType.PNG
            save.mip = mip
            save.slice.sliceIndex = array_slice
            save.sample.mapToArray = False
            save.sample.sampleIndex = sample
            save.channelExtract = channel_extract
            if hasattr(rd, "AlphaMapping"):
                save.alpha = rd.AlphaMapping.Preserve if preserve_alpha else rd.AlphaMapping.Discard
            display["alphaMode"] = "preserved" if preserve_alpha else "opaque-rgb"
            save.comp.blackPoint = display["blackPoint"]
            save.comp.whitePoint = display["whitePoint"]
            try:
                if decoded_gray is not None:
                    _save_decoded_grayscale_evidence(
                        temporary_path, decoded_gray, mip_width, mip_height)
                    del decoded_gray
                else:
                    result = ctrl.SaveTexture(save, temporary_path)
                    if result.code != rd.ResultCode.Succeeded:
                        raise RuntimeError("RenderDoc SaveTexture failed: %s" % str(result))
                if expected_session != _capture_session_id:
                    raise RuntimeError(
                        "capture session changed during texture evidence export")
                temporary_info = os.lstat(temporary_path)
                if (not stat.S_ISREG(temporary_info.st_mode) or
                        _event_texture_evidence_is_redirected(temporary_path)):
                    raise RuntimeError(
                        "RenderDoc texture evidence output was redirected")
                temporary_size = temporary_info.st_size
                # A target too large even to open safely is refused before Qt sees it.
                if temporary_size > MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES * 8:
                    return _skipped("png-byte-budget-exceeded")
                with open(temporary_path, "rb") as stream:
                    if stream.read(8) != b"\x89PNG\r\n\x1a\n":
                        raise RuntimeError(
                            "RenderDoc did not produce a valid PNG evidence file")
                reduction = _reduce_saved_image(
                    temporary_path, crop, max_dimension, opaque_rgb=not preserve_alpha,
                    flip_y=flip_y, **({"preserve_channels": True} if preserve_alpha else {}))
                if reduction is not None:
                    temporary_size = os.lstat(temporary_path).st_size
                if temporary_size > MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES:
                    return _skipped("png-byte-budget-exceeded")
                png_size, png_sha256 = _event_texture_evidence_hash(
                    temporary_path, MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES)
                # A hard-link publication is atomic and fails if the final
                # name already exists; unlike replace/rename it cannot
                # silently overwrite another artifact.
                os.link(temporary_path, final_path)
                os.unlink(temporary_path)
                final_size, final_sha256 = _event_texture_evidence_hash(
                    final_path, MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES)
                if final_size != png_size or final_sha256 != png_sha256:
                    raise RuntimeError(
                        "event texture evidence changed while it was published")
            finally:
                try:
                    if os.path.lexists(temporary_path):
                        os.unlink(temporary_path)
                except Exception:
                    pass

            return {
                "status": "saved",
                "skipReason": None,
                "attachment": attachment,
                "display": display,
                "output": {
                    "path": final_path,
                    "mimeType": "image/png",
                    "byteSize": final_size,
                    "sha256": final_sha256,
                    "noOverwrite": True,
                    "reduction": reduction,
                },
            }

        artifact = None
        try:
            if _controller is None:
                _set_frame_event(ctrl, event_id, True)
            artifact = _capture_at_event()
        finally:
            # Restoration failure is deliberately not swallowed. Returning an
            # evidence receipt without proving restoration would be unsafe.
            if _controller is None:
                _set_frame_event(ctrl, original_event, True)
        if expected_session != _capture_session_id:
            raise RuntimeError(
                "capture session changed before texture evidence receipt")
        return {
            "schema": EVENT_TEXTURE_EVIDENCE_SCHEMA,
            "schemaVersion": EVENT_TEXTURE_EVIDENCE_VERSION,
            "requestId": request_id,
            "captureSessionId": expected_session,
            "eventId": event_id,
            "restoration": {
                "originalEventId": original_event,
                "restored": _controller is None,
            },
            "exactEventBinding": True,
            "replayMutation": False,
            "budgets": budgets,
            "artifact": artifact,
        }

    # The private batch path already owns the replay callback and restores once
    # after all channels. It never consults Qt objects from a worker thread.
    return _do(_controller) if _controller is not None else _replay(_do)


