def _fingerprint_event_outputs(params):
    """Hash and deterministically sample every MRT/depth output at one event.

    This is read-only observational evidence.  It intentionally reports both
    a whole-subresource byte hash and a bounded pixel grid so the Host can
    distinguish exact replay equality from tolerance-limited observations.
    """
    event_id = _safe_int(params.get("event_id"), 0)
    grid_size = _safe_int(params.get("grid_size", 12), 12)
    expected_session = str(
        params.get("expected_capture_session_id", "") or "").strip().lower()
    if event_id <= 0:
        raise ValueError("event_id must be a positive integer")
    if grid_size < 2 or grid_size > 32:
        raise ValueError("grid_size must be between 2 and 32")
    if (not _capture_session_id or expected_session != _capture_session_id or
            not re.match(r"^[0-9a-f]{32}$", expected_session)):
        raise ValueError("active capture session changed before output fingerprinting")
    try:
        original_event = _request_visible_event_id(0)
        restore_event = True
    except Exception:
        original_event = 0
        restore_event = False

    def _component(value):
        number = float(value)
        if math.isnan(number):
            return "nan"
        if math.isinf(number):
            return "+inf" if number > 0 else "-inf"
        return number

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, event_id, True)
            if expected_session != _capture_session_id:
                raise RuntimeError("capture session changed during output fingerprinting")
            pipeline = ctrl.GetPipelineState()
            texture_by_id = {}
            for texture in ctrl.GetTextures() or []:
                texture_by_id[_resource_id_int(texture.resourceId)] = texture

            descriptors = []
            for index, descriptor in enumerate(pipeline.GetOutputTargets() or []):
                resource_id = _resource_id_int(getattr(descriptor, "resource", None))
                if resource_id:
                    descriptors.append(("color", index, descriptor, resource_id))
            depth = pipeline.GetDepthTarget()
            depth_id = _resource_id_int(getattr(depth, "resource", None))
            if depth_id:
                descriptors.append(("depth", 0, depth, depth_id))

            # ``GetTextureData`` materialises a complete subresource in the
            # qrenderdoc process. Several large HDR MRTs can otherwise exhaust
            # the UI process even though the caller only retains a digest.
            # Keep exact hashing for bounded outputs and fall back to the fixed
            # pixel grid for larger/unknown allocations.
            full_hash_byte_limit = 32 * 1024 * 1024
            outputs = []
            for kind, index, descriptor, resource_id in descriptors:
                texture = texture_by_id.get(resource_id)
                if texture is None:
                    raise RuntimeError("output texture description is unavailable")
                mip = max(0, _safe_int(getattr(descriptor, "firstMip", 0), 0))
                array_slice = max(
                    0, _safe_int(getattr(descriptor, "firstSlice", 0), 0))
                width = max(1, _safe_int(getattr(texture, "width", 1), 1) >> mip)
                height = max(1, _safe_int(getattr(texture, "height", 1), 1) >> mip)
                subresource = rd.Subresource(mip, array_slice, 0)
                resource = getattr(descriptor, "resource", None)
                texture_byte_size = max(
                    0, _safe_int(getattr(texture, "byteSize", 0), 0))
                raw_byte_size = None
                raw_sha256 = None
                if 0 < texture_byte_size <= full_hash_byte_limit:
                    raw = ctrl.GetTextureData(resource, subresource)
                    raw_byte_size = len(raw)
                    raw_sha256 = hashlib.sha256(raw).hexdigest()
                    del raw
                    raw_hash_status = "hashed"
                elif texture_byte_size > full_hash_byte_limit:
                    raw_hash_status = "skipped-texture-too-large"
                else:
                    raw_hash_status = "skipped-size-unavailable"
                coordinates = []
                seen = set()
                for gy in range(grid_size):
                    y = min(height - 1, int((gy + 0.5) * height / grid_size))
                    for gx in range(grid_size):
                        x = min(width - 1, int((gx + 0.5) * width / grid_size))
                        if (x, y) not in seen:
                            seen.add((x, y))
                            coordinates.append((x, y))
                samples = []
                for x, y in coordinates:
                    value = ctrl.PickPixel(
                        resource, x, y, subresource, rd.CompType.Typeless)
                    samples.append({
                        "x": x,
                        "y": y,
                        "value": [_component(value.floatValue[channel])
                                  for channel in range(4)],
                    })
                outputs.append({
                    "kind": kind,
                    "index": index,
                    "resourceId": resource_id,
                    "mip": mip,
                    "slice": array_slice,
                    "width": width,
                    "height": height,
                    "format": _fmt_str(getattr(texture, "format", None)),
                    "textureByteSize": texture_byte_size,
                    "fullHashByteLimit": full_hash_byte_limit,
                    "rawHashStatus": raw_hash_status,
                    "rawByteSize": raw_byte_size,
                    "rawSha256": raw_sha256,
                    "samples": samples,
                })
            if expected_session != _capture_session_id:
                raise RuntimeError("capture session changed during output fingerprinting")
            return {
                "schema": "replaylab-event-output-fingerprint/v1",
                "schemaVersion": 1,
                "captureSessionId": expected_session,
                "eventId": event_id,
                "gridSize": grid_size,
                "outputs": outputs,
                "observationalOnly": True,
                "semanticEquivalenceVerified": False,
            }
        finally:
            if restore_event:
                try:
                    _set_frame_event(ctrl, original_event, True)
                except Exception:
                    pass

    return _replay(_do)


def _texture_minmax_on_replay(ctrl, resource_id):
    """Collect base-subresource min/max values without a nested replay call."""
    tid = _resolve_resource_id(ctrl, resource_id, "texture")
    sub = rd.Subresource(0, 0, 0)
    mn, mx = ctrl.GetMinMax(tid, sub, rd.CompType.Typeless)
    return {
        "min": {
            "r": mn.floatValue[0], "g": mn.floatValue[1],
            "b": mn.floatValue[2], "a": mn.floatValue[3],
        },
        "max": {
            "r": mx.floatValue[0], "g": mx.floatValue[1],
            "b": mx.floatValue[2], "a": mx.floatValue[3],
        },
    }


def _get_texture_minmax(params):
    """Get min/max pixel values of a texture."""
    resource_id = params.get("resource_id")
    if resource_id is None:
        raise ValueError("resource_id required")

    return _replay(lambda ctrl: _texture_minmax_on_replay(ctrl, resource_id))


def _pixel_history(params):
    """Get pixel modification history."""
    resource_id = params.get("resource_id")
    x = params.get("x", 0)
    y = params.get("y", 0)
    event_id = _safe_int(params.get("event_id"), 0)
    if resource_id is None:
        raise ValueError("resource_id required")
    if event_id <= 0:
        raise ValueError("event_id must be a positive integer")
    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, event_id, True)
            tid = _resolve_resource_id(ctrl, resource_id, "texture")
            sub = rd.Subresource(0, 0, 0)
            mods = ctrl.PixelHistory(tid, x, y, sub, rd.CompType.Typeless)
            result = []
            for m in mods:
                entry = {"eventId": m.eventId}
                try:
                    if m.preMod:
                        entry["pre"] = {"r": m.preMod.col.floatValue[0], "g": m.preMod.col.floatValue[1],
                                        "b": m.preMod.col.floatValue[2], "a": m.preMod.col.floatValue[3]}
                    if m.postMod:
                        entry["post"] = {"r": m.postMod.col.floatValue[0], "g": m.postMod.col.floatValue[1],
                                         "b": m.postMod.col.floatValue[2], "a": m.postMod.col.floatValue[3]}
                except Exception:
                    pass
                result.append(entry)
            return result
        finally:
            _set_frame_event(ctrl, original_event, True)

    return _replay(_do)


PIXEL_OBJECT_INSPECTOR_SCHEMA = "renderdoc-ultra-pixel-object-inspector/v1"
PIXEL_OBJECT_INSPECTOR_VERSION = 1


def _pixel_optional_bool(value, name):
    try:
        return bool(getattr(value, name))
    except Exception:
        return None


def _pixel_optional_int(value, name):
    try:
        return int(getattr(value, name))
    except Exception:
        return None


def _pixel_channel_array(colour, name, convert):
    try:
        values = getattr(colour, name)
        return [convert(values[index]) for index in range(4)]
    except Exception:
        return None


def _pixel_modification_value(value):
    """Losslessly expose the representations available on ``ModificationValue``."""
    if value is None:
        return {
            "available": False, "valid": None, "floatValue": None,
            "intValue": None, "uintValue": None, "depth": None, "stencil": None,
        }

    valid = None
    is_valid = getattr(value, "IsValid", None)
    if callable(is_valid):
        try:
            valid = bool(is_valid())
        except Exception:
            pass

    colour = getattr(value, "col", None)
    try:
        depth = float(getattr(value, "depth"))
    except Exception:
        depth = None
    try:
        stencil = int(getattr(value, "stencil"))
    except Exception:
        stencil = None

    return {
        "available": True,
        "valid": valid,
        "floatValue": _pixel_channel_array(colour, "floatValue", float),
        "intValue": _pixel_channel_array(colour, "intValue", int),
        "uintValue": _pixel_channel_array(colour, "uintValue", int),
        "depth": depth,
        "stencil": stencil,
    }


def _pixel_action_flag(name, fallback):
    try:
        return _safe_int(getattr(rd.ActionFlags, name), fallback)
    except Exception:
        return fallback


def _pixel_action_types(flags):
    known = (
        ("Clear", 0x0001),
        ("Drawcall", 0x0002),
        ("Dispatch", 0x0004),
        ("MeshDispatch", 0x0008),
        ("Present", 0x0100),
        ("Copy", 0x0400),
        ("Resolve", 0x0800),
        ("GenerateMips", 0x1000),
        ("DispatchRay", 0x4000),
        ("BuildAccelerationStructure", 0x8000),
    )
    result = []
    for name, fallback in known:
        api_name = {
            "GenerateMips": "GenMips",
            "BuildAccelerationStructure": "BuildAccStruct",
        }.get(name, name)
        if flags & _pixel_action_flag(api_name, fallback):
            result.append(name)
    return result or ["Unknown"]


def _pixel_action_map(ctrl):
    actions_by_event = {}
    draw_mask = _pixel_action_flag("Drawcall", 0x0002)
    mesh_mask = _pixel_action_flag("MeshDispatch", 0x0008)
    compute_mask = (_pixel_action_flag("Dispatch", 0x0004) |
                    _pixel_action_flag("DispatchRay", 0x4000))

    def _collect(actions, marker_path=None):
        marker_path = marker_path or []
        for action in actions or []:
            flags = _safe_int(getattr(action, "flags", 0), 0)
            children = getattr(action, "children", None) or []
            name = _action_name(action)
            actions_by_event[_safe_int(getattr(action, "eventId", 0), 0)] = {
                "found": True,
                "eventId": _safe_int(getattr(action, "eventId", 0), 0),
                "actionId": _safe_int(getattr(action, "actionId", 0), 0),
                "name": name,
                "flags": flags,
                "types": _pixel_action_types(flags),
                "markerPath": list(marker_path),
                "isRasterGeometry": bool(flags & (draw_mask | mesh_mask)),
                "isComputeOrRay": bool(flags & compute_mask),
            }
            current_path = marker_path + ([name] if children else [])
            if children:
                _collect(children, current_path)

    _collect(ctrl.GetRootActions())
    return actions_by_event


def _pixel_modification_record(modification, index, action):
    flag_names = (
        "directShaderWrite", "unboundPS", "sampleMasked", "backfaceCulled",
        "depthClipped", "depthBoundsFailed", "viewClipped", "scissorClipped",
        "shaderDiscarded", "depthTestFailed", "stencilTestFailed",
        "predicationSkipped",
    )
    flags = dict((name, _pixel_optional_bool(modification, name)) for name in flag_names)

    passed = None
    passed_fn = getattr(modification, "Passed", None)
    if callable(passed_fn):
        try:
            passed = bool(passed_fn())
        except Exception:
            pass
    if passed is None:
        failure_names = flag_names[2:]
        if all(flags[name] is not None for name in failure_names):
            passed = not any(flags[name] for name in failure_names)

    failure_reasons = [name for name in flag_names[2:] if flags[name] is True]
    direct_write = flags["directShaderWrite"]
    is_raster_geometry = bool(
        passed is True and action.get("isRasterGeometry") and direct_write is not True)

    if direct_write is True:
        write_classification = "potential-direct-shader-write"
    elif passed is True:
        write_classification = "passed-non-direct-write"
    elif passed is False:
        write_classification = "failed-write-attempt"
    else:
        write_classification = "unknown-write-attempt"

    return {
        "index": index,
        "eventId": _pixel_optional_int(modification, "eventId"),
        "fragIndex": _pixel_optional_int(modification, "fragIndex"),
        "primitiveId": _pixel_optional_int(modification, "primitiveID"),
        "pre": _pixel_modification_value(getattr(modification, "preMod", None)),
        "shaderOut": _pixel_modification_value(
            getattr(modification, "shaderOut", None)),
        "post": _pixel_modification_value(getattr(modification, "postMod", None)),
        "flags": flags,
        "passed": passed,
        "failureReasons": failure_reasons,
        # Passed() means the API write attempt survived the tests RenderDoc can
        # instrument. It does not prove that this entry materially contributed
        # to the final pixel (for example a later opaque write can replace it),
        # and direct shader writes are only potential writes in PixelHistory.
        "writeClassification": write_classification,
        "contributionConfirmed": False,
        "isPassedRasterGeometry": is_raster_geometry,
        "action": action,
    }


def _pixel_contributor_reference(record):
    return {
        "modificationIndex": record["index"],
        "eventId": record["eventId"],
        "fragIndex": record["fragIndex"],
        "primitiveId": record["primitiveId"],
        "passed": record["passed"],
        "directShaderWrite": record["flags"]["directShaderWrite"],
        "writeClassification": record["writeClassification"],
        "contributionConfirmed": record["contributionConfirmed"],
        "action": record["action"],
    }


def _inspect_pixel_object_on_replay(ctrl, texture_id, x, y, mip, array_slice, sample,
                                    prefer_geometry, cutoff_event_id):
    """Build the inspector result on the replay thread without inventing object identity."""
    tid = _resolve_resource_id(ctrl, texture_id, "texture")
    texture = None
    for candidate in ctrl.GetTextures():
        if _resource_id_int(getattr(candidate, "resourceId", None)) == texture_id:
            texture = candidate
            break

    if texture is None:
        # _resolve_resource_id normally catches this; keep the failure explicit if an unusual
        # binding returns different lists between calls.
        raise ValueError("Unknown texture resource ID: %d" % texture_id)

    mip_count = max(_safe_int(getattr(texture, "mips", 1), 1), 1)
    if mip >= mip_count:
        raise ValueError("Mip %d is outside texture mip count %d" % (mip, mip_count))
    mip_width = max(1, _safe_int(getattr(texture, "width", 1), 1) >> mip)
    mip_height = max(1, _safe_int(getattr(texture, "height", 1), 1) >> mip)
    if x >= mip_width or y >= mip_height:
        raise ValueError(
            "Pixel (%d, %d) is outside mip %d dimensions %dx%d" %
            (x, y, mip, mip_width, mip_height))

    dimension = getattr(texture, "dimension", None)
    arraysize = getattr(texture, "arraysize", None)
    depth = getattr(texture, "depth", None)
    if dimension is not None and _safe_int(dimension, 0) == 3 and depth is not None:
        slice_count = max(1, _safe_int(depth, 1) >> mip)
    elif arraysize is not None:
        slice_count = max(1, _safe_int(arraysize, 1))
    else:
        slice_count = None
    if slice_count is not None and array_slice >= slice_count:
        raise ValueError(
            "Slice %d is outside mip %d slice count %d" %
            (array_slice, mip, slice_count))

    sample_count_value = getattr(
        texture, "msSamp", getattr(texture, "sampleCount", None))
    sample_count = (max(1, _safe_int(sample_count_value, 1))
                    if sample_count_value is not None else None)
    if sample_count is not None and sample >= sample_count:
        raise ValueError(
            "Sample %d is outside texture sample count %d" % (sample, sample_count))

    subresource = rd.Subresource(mip, array_slice, sample)
    started = time.time()
    modifications = ctrl.PixelHistory(
        tid, x, y, subresource, rd.CompType.Typeless)
    elapsed_ms = int((time.time() - started) * 1000.0)

    action_map = _pixel_action_map(ctrl)
    records = []
    for index, modification in enumerate(modifications or []):
        event_id = _pixel_optional_int(modification, "eventId")
        action = action_map.get(event_id, {
            "found": False,
            "eventId": event_id,
            "actionId": None,
            "name": "",
            "flags": None,
            "types": ["Unknown"],
            "markerPath": [],
            "isRasterGeometry": False,
            "isComputeOrRay": False,
        })
        records.append(_pixel_modification_record(modification, index, action))

    passed_records = [record for record in records if record["passed"] is True]
    confirmed_non_direct = [
        record for record in passed_records
        if record["flags"]["directShaderWrite"] is not True
    ]
    potential_direct = [
        record for record in records
        if record["flags"]["directShaderWrite"] is True
    ]
    raster_records = [record for record in confirmed_non_direct
                      if record["isPassedRasterGeometry"]]
    last_recorded = records[-1] if records else None
    last_passed_candidate = passed_records[-1] if passed_records else None
    last_confirmed_non_direct = confirmed_non_direct[-1] if confirmed_non_direct else None
    last_geometry = raster_records[-1] if raster_records else None

    last_recorded_ref = (_pixel_contributor_reference(last_recorded)
                         if last_recorded is not None else None)
    last_passed_ref = (_pixel_contributor_reference(last_passed_candidate)
                       if last_passed_candidate is not None else None)
    last_confirmed_ref = (_pixel_contributor_reference(last_confirmed_non_direct)
                          if last_confirmed_non_direct is not None else None)
    last_geometry_ref = (_pixel_contributor_reference(last_geometry)
                          if last_geometry is not None else None)
    passed_candidates = [_pixel_contributor_reference(record) for record in passed_records]
    direct_candidates = [_pixel_contributor_reference(record) for record in potential_direct]
    preferred = (
        last_geometry_ref if prefer_geometry and last_geometry_ref
        else (last_confirmed_ref or last_passed_ref)
    )
    preferred_kind = None
    if preferred is not None:
        if prefer_geometry and last_geometry_ref:
            preferred_kind = "LastPassedRasterGeometry"
        elif last_confirmed_ref:
            preferred_kind = "LastConfirmedNonDirectWrite"
        else:
            preferred_kind = "LastPassedWriteCandidate"

    passed_candidate_confidence = (
        "low" if last_passed_candidate is not None and
        last_passed_candidate["flags"]["directShaderWrite"] is True
        else ("high" if last_passed_candidate is not None else "none")
    )
    confirmed_writer_confidence = "high" if last_confirmed_ref else "none"
    geometry_confidence = "high" if last_geometry_ref else "none"
    object_confidence = "none"
    overall_confidence = "low" if preferred_kind == "LastPassedRasterGeometry" else (
        "low" if preferred is not None else "none")

    last_action_event = max(action_map) if action_map else None
    covers_last_action = None
    if cutoff_event_id > 0 and last_action_event is not None:
        covers_last_action = cutoff_event_id >= last_action_event

    evidence = [
        "PixelHistory returned %d modification attempt(s)." % len(records),
        "%d modification(s) report Passed() == true; these are write candidates, not proof "
        "of final material contribution." % len(passed_records),
        "%d direct shader write(s) are potential writes only." % len(potential_direct),
        "%d passed modification(s) have Drawcall/MeshDispatch action flags." %
        len(raster_records),
    ]
    if last_passed_ref:
        evidence.append(
            "The final Passed() entry is retained as a write candidate, not asserted as a "
            "confirmed final-frame writer.")
    if last_geometry_ref:
        evidence.append(
            "The final passed raster action is associated with the reported primitive ID only; "
            "PixelHistory does not expose an instance ID or asset identity.")

    return {
        "schema": PIXEL_OBJECT_INSPECTOR_SCHEMA,
        "schemaVersion": PIXEL_OBJECT_INSPECTOR_VERSION,
        "query": {
            "textureId": texture_id,
            "x": x,
            "y": y,
            "mip": mip,
            "slice": array_slice,
            "sample": sample,
            "preferGeometry": bool(prefer_geometry),
        },
        "historyScope": {
            "kind": "up-to-selected-event",
            "cutoffEventId": cutoff_event_id,
            "lastListedActionEventId": last_action_event,
            "coversThroughLastListedAction": covers_last_action,
            "isGuaranteedWholeFrame": covers_last_action is True,
        },
        "texture": {
            "resourceId": texture_id,
            "width": _safe_int(getattr(texture, "width", 0), 0),
            "height": _safe_int(getattr(texture, "height", 0), 0),
            "mips": mip_count,
            "sliceCountAtMip": slice_count,
            "sampleCount": sample_count,
        },
        "categories": {
            "lastRecordedModification": last_recorded_ref,
            "lastPassedWriteCandidate": last_passed_ref,
            "lastConfirmedNonDirectWrite": last_confirmed_ref,
            "lastPassedRasterGeometry": last_geometry_ref,
            "allPassedWriteCandidates": passed_candidates,
            "potentialDirectShaderWrites": direct_candidates,
        },
        "preferredSelection": {
            "kind": preferred_kind,
            "candidate": preferred,
            "objectIdentity": None,
        },
        "modifications": records,
        "confidence": {
            "overallObjectSelection": overall_confidence,
            "lastPassedWriteCandidate": passed_candidate_confidence,
            "lastConfirmedNonDirectWrite": confirmed_writer_confidence,
            "lastPassedRasterGeometry": geometry_confidence,
            "objectIdentity": object_confidence,
        },
        "evidence": evidence,
        "limitations": [
            "This identifies events/fragments, not a unique engine object or asset.",
            "PixelHistory is evaluated only through the selected cutoff event; it is not "
            "automatically the final frame history.",
            "PixelHistory does not expose a trustworthy instance ID; none is inferred.",
            "Fullscreen and post-process draws use ordinary raster action flags and cannot be "
            "distinguished reliably here.",
            "Compute, ray, copy, clear, and direct shader writes have no raster object identity; "
            "direct shader entries are potential writes rather than confirmed writes.",
            "Passed() does not prove lasting final-pixel contribution. Transparency, blending, "
            "overdraw, and later opaque writes prevent treating all passed entries as contributors.",
        ],
        "invocationPolicy": {
            "interaction": "click-only",
            "hoverSupported": False,
            "continuousPollingSupported": False,
            "runAsynchronouslyInUI": True,
            "expensiveReplayOperation": True,
            "elapsedMilliseconds": elapsed_ms,
        },
    }


def _inspect_pixel_object(params):
    """Inspect a clicked pixel and classify evidence without guessing an engine object."""
    if not _request_capture_loaded():
        raise RuntimeError("No capture loaded")

    texture_id = _safe_int(params.get("texture_id"), 0)
    if texture_id <= 0:
        raise ValueError("texture_id required")
    x = _safe_int(params.get("x"), -1)
    y = _safe_int(params.get("y"), -1)
    mip = _safe_int(params.get("mip", 0), -1)
    array_slice = _safe_int(params.get("slice", 0), -1)
    sample = _safe_int(params.get("sample", 0), -1)
    event_id = _safe_int(params.get("event_id"), 0)
    prefer_geometry = bool(params.get("prefer_geometry", True))
    if min(x, y, mip, array_slice, sample) < 0:
        raise ValueError("x, y, mip, slice, and sample must be non-negative integers")
    if event_id <= 0:
        raise ValueError("event_id must be a positive integer")

    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, event_id, True)
            result = _inspect_pixel_object_on_replay(
                ctrl, texture_id, x, y, mip, array_slice, sample, prefer_geometry,
                event_id)
        finally:
            # PixelHistory performs internal replay. Always put the user's event selection back,
            # including event 0, and surface any restore failure instead of silently drifting.
            _set_frame_event(ctrl, original_event, True)
        result["eventRestore"] = {
            "originalEventId": original_event,
            "frozenEventId": event_id,
            "restored": True,
        }
        return result

    return _replay(_do)


def _analyze_pixel(params):
    """Collect texture, min/max, and pixel-history evidence in one replay call."""
    if not _request_capture_loaded():
        raise RuntimeError("No capture loaded")

    texture_id = _safe_int(params.get("texture_id"), 0)
    if texture_id <= 0:
        raise ValueError("texture_id required")
    x = _safe_int(params.get("x"), -1)
    y = _safe_int(params.get("y"), -1)
    mip = _safe_int(params.get("mip", 0), -1)
    array_slice = _safe_int(params.get("slice", 0), -1)
    sample = _safe_int(params.get("sample", 0), -1)
    event_id = _safe_int(params.get("event_id"), 0)
    prefer_geometry = bool(params.get("prefer_geometry", True))
    if min(x, y, mip, array_slice, sample) < 0:
        raise ValueError("x, y, mip, slice, and sample must be non-negative integers")
    if event_id <= 0:
        raise ValueError("event_id must be a positive integer")

    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, event_id, True)
            texture = _texture_info_on_replay(ctrl, texture_id)
            minmax = _texture_minmax_on_replay(ctrl, texture_id)
            inspection = _inspect_pixel_object_on_replay(
                ctrl, texture_id, x, y, mip, array_slice, sample,
                prefer_geometry, event_id)
        finally:
            # PixelHistory can change replay state internally. Restore the UI's
            # visible event before this single replay-thread transaction ends.
            _set_frame_event(ctrl, original_event, True)
        inspection["eventRestore"] = {
            "originalEventId": original_event,
            "frozenEventId": event_id,
            "restored": True,
        }
        return {
            "schema": "renderdoc-internal-analyze-pixel/v1",
            "texture": texture,
            "minMax": minmax,
            "inspection": inspection,
        }

    return _replay(_do)


def _debug_variable_snapshot(variable, depth=0, budget=None, member_limit=16, max_depth=4):
    """Serialize actual debug values, never source-variable mapping metadata."""
    if budget is None:
        budget = [64]
    budget[0] -= 1
    type_value = getattr(variable, "type", None)
    type_name = str(type_value).rsplit(".", 1)[-1]
    storage = {"Float": "f32v", "Double": "f64v", "Half": "u16v",
               "SInt": "s32v", "UInt": "u32v", "SShort": "s16v",
               "UShort": "u16v", "SLong": "s64v", "ULong": "u64v",
               "SByte": "s8v", "UByte": "u8v", "Bool": "u32v"}
    enum_type = getattr(rd, "VarType", None)
    for name in storage:
        if enum_type is not None and type_value == getattr(enum_type, name, object()):
            type_name = name
            break
    rows = max(0, _safe_int(getattr(variable, "rows", 0), 0))
    columns = max(0, _safe_int(getattr(variable, "columns", 0), 0))
    result = {"name": str(getattr(variable, "name", "")), "type": type_name,
              "rows": rows, "columns": columns, "valueAvailable": False}
    members = getattr(variable, "members", ())
    if members:
        result["membersTruncated"] = depth >= max_depth or len(members) > member_limit
        if depth < max_depth:
            result["members"] = [_debug_variable_snapshot(
                member, depth + 1, budget, member_limit, max_depth)
                for member in members[:member_limit] if budget[0] > 0]
            result["membersTruncated"] = len(result["members"]) < len(members)
        return result
    values = getattr(getattr(variable, "value", None), storage.get(type_name, ""), None)
    if values is None or not rows or not columns:
        return result
    count = min(rows * columns, 16)
    if type_name == "Half":
        values = [struct.unpack("<e", struct.pack("<H", int(value)))[0]
                  for value in values[:count]]
    if type_name in ("Float", "Double", "Half"):
        values, non_finite = _strict_float_vector(values, count)
        if non_finite:
            result["nonFinite"] = non_finite
    else:
        values = [int(value) for value in values[:count]]
    result.update({"valueAvailable": True, "value": list(values)})
    return result


_SHADER_DEBUG_TRACE_MAX_BYTES = 32 * 1024 * 1024
_SHADER_DEBUG_TRACE_MAX_STEPS = 50000
_SHADER_DEBUG_TRACE_LIFETIME = 24 * 60 * 60
_SHADER_DEBUG_TRACE_RETAINED = 16


def _shader_debug_trace_root():
    """Per-user diagnostic artifacts, independent of the short-lived IPC response mailbox."""
    root = os.path.join(_replaylab_local_root, "ReplayLab", "shader-debug-traces")
    candidate = os.path.abspath(root)
    while candidate:
        if os.path.lexists(candidate):
            info = os.lstat(candidate)
            if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & 0x400:
                raise RuntimeError("Shader debug evidence directory is redirected")
        parent = os.path.dirname(candidate)
        if parent == candidate:
            break
        candidate = parent
    os.makedirs(root, mode=0o700, exist_ok=True)
    entries = []
    now = time.time()
    for name in os.listdir(root):
        if not re.match(r"^[0-9]+-[a-f0-9]{32}-[a-f0-9]{32}\.jsonl$", name):
            continue
        path = os.path.join(root, name)
        try:
            info = os.lstat(path)
            if not stat.S_ISREG(info.st_mode) or getattr(info, "st_file_attributes", 0) & 0x400:
                continue
            entries.append((info.st_mtime, path))
        except OSError:
            continue
    entries.sort(reverse=True)
    for index, (modified, path) in enumerate(entries):
        if index >= _SHADER_DEBUG_TRACE_RETAINED - 1 or now - modified > _SHADER_DEBUG_TRACE_LIFETIME:
            try:
                os.unlink(path)
            except OSError:
                pass
    return root


def _debug_snapshot_truncated(value):
    if isinstance(value, dict):
        return bool(value.get("membersTruncated") or value.get("changesTruncated") or
                    value.get("callstackTruncated") or
                    any(_debug_snapshot_truncated(child) for child in value.values()))
    if isinstance(value, list):
        return any(_debug_snapshot_truncated(child) for child in value)
    return False


def _collect_shader_debug_states(ctrl, trace, invocation=None):
    """Persist late debug values once; the inline preview remains deliberately small."""
    root = _shader_debug_trace_root()
    path = os.path.join(root, "%s-%s.jsonl" % (INSTANCE_ID, uuid.uuid4().hex))
    partial = path + ".part"
    states, index = [], []
    count, byte_count, summary_offset, last_step_offset = 0, 0, 0, 0
    truncation_reasons = set()
    stopped = False
    digest = hashlib.sha256()
    fd = os.open(partial, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    try:
        with os.fdopen(fd, "wb") as stream:
            def write(record):
                nonlocal byte_count
                encoded = (json.dumps(record, ensure_ascii=False, separators=(",", ":"),
                                      allow_nan=False) + "\n").encode("utf-8")
                # Keep room for the compact final completion record.
                if byte_count + len(encoded) > _SHADER_DEBUG_TRACE_MAX_BYTES - 4096:
                    return False
                stream.write(encoded)
                digest.update(encoded)
                byte_count += len(encoded)
                return True

            header = {"record": "header", "schema": "bread-shader-debug-trace/v1",
                      "createdUnixMs": int(time.time() * 1000),
                      "captureSessionId": str(_capture_session_id or ""),
                      "invocation": dict(invocation or {}),
                      "variableRepresentation": "debug-variable-changes"}
            write(header)
            batch = ctrl.ContinueDebug(trace.debugger)
            while batch and not stopped:
                _background_replay_checkpoint()
                for state in batch:
                    if count and count % 128 == 0:
                        _background_replay_checkpoint()
                    if count >= _SHADER_DEBUG_TRACE_MAX_STEPS:
                        truncation_reasons.add("step-limit")
                        stopped = True
                        break
                    changes = getattr(state, "changes", ())
                    entries, budget = [], [4096]
                    for change in changes[:1024]:
                        if budget[0] < 2:
                            break
                        entries.append({
                            "before": _debug_variable_snapshot(change.before, budget=budget,
                                                               member_limit=256, max_depth=8),
                            "after": _debug_variable_snapshot(change.after, budget=budget,
                                                              member_limit=256, max_depth=8)})
                    callstack = getattr(state, "callstack", ())
                    record = {"record": "step", "ordinal": count,
                              "step": state.stepIndex, "nextInstruction": state.nextInstruction,
                              "flags": str(getattr(state, "flags", "")),
                              "callstack": [str(name) for name in callstack[:256]],
                              "callstackTruncated": len(callstack) > 256,
                              "changes": entries, "changesTruncated": len(changes) > len(entries)}
                    offset = byte_count
                    if not write(record):
                        truncation_reasons.add("byte-limit")
                        stopped = True
                        break
                    last_step_offset = offset
                    if count % 128 == 0:
                        index.append({"ordinal": count, "step": state.stepIndex, "offset": offset})
                    count += 1
                    if _debug_snapshot_truncated(record):
                        truncation_reasons.add("variable-detail-limit")
                    if len(states) < 50:
                        preview_entries = [
                            {"before": _debug_variable_snapshot(change.before),
                             "after": _debug_variable_snapshot(change.after)}
                            for change in changes[:10]]
                        preview = dict(record)
                        preview.update(changes=preview_entries, changesTruncated=len(changes) > 10,
                                       callstack=record["callstack"][:16],
                                       vars=[entry["after"] for entry in preview_entries])
                        states.append(preview)
                if not stopped:
                    batch = ctrl.ContinueDebug(trace.debugger)
            summary_offset = byte_count
            summary = {"record": "summary", "steps": count, "executionComplete": not stopped,
                       "complete": not truncation_reasons,
                       "truncationReasons": sorted(truncation_reasons)}
            # The reserved footer fits even if a state reached the byte ceiling.
            encoded = (json.dumps(summary, separators=(",", ":")) + "\n").encode("utf-8")
            stream.write(encoded)
            digest.update(encoded)
            byte_count += len(encoded)
        os.replace(partial, path)
    finally:
        if os.path.exists(partial):
            try:
                os.unlink(partial)
            except OSError:
                pass
    artifact = {
        "schema": "bread-shader-debug-trace/v1", "path": path,
        "format": "jsonl", "byteSize": byte_count, "sha256": digest.hexdigest(),
        "steps": count, "complete": not truncation_reasons, "executionComplete": not stopped,
        "truncationReasons": sorted(truncation_reasons),
        "stepIndex": index, "lastStepOffset": last_step_offset, "summaryOffset": summary_offset,
        "maxBytes": _SHADER_DEBUG_TRACE_MAX_BYTES, "maxSteps": _SHADER_DEBUG_TRACE_MAX_STEPS,
        "retentionSeconds": _SHADER_DEBUG_TRACE_LIFETIME,
        "readTool": "read_evidence_file",
        "readHint": "Use stepIndex.offset to read a later JSONL page without rerunning debug.",
    }
    return {"steps": count, "trace": states, "traceTruncated": count > len(states) or stopped,
            "executionComplete": not stopped, "traceArtifact": artifact,
            "variableRepresentation": "debug-variable-changes"}


def _debug_pixel(params):
    """Debug pixel shader execution."""
    x = params.get("x", 0)
    y = params.get("y", 0)
    event_id = _safe_int(params.get("event_id", 0), 0)
    sample = _safe_int(params.get("sample", 0), 0)
    primitive_id = _safe_int(params.get("primitive_id", -1), -1)
    view = _safe_int(params.get("view", 0), 0)
    if min(_safe_int(x, -1), _safe_int(y, -1), sample, view) < 0:
        raise ValueError("x, y, sample, and view must be non-negative integers")
    if event_id < 0:
        raise ValueError("event_id must be 0 (current event) or a positive event ID")

    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        changed_event = event_id > 0
        trace = None
        try:
            if changed_event:
                _set_frame_event(ctrl, event_id, True)
            inputs = rd.DebugPixelInputs()
            inputs.sample = sample
            inputs.primitive = primitive_id if primitive_id >= 0 else 0xFFFFFFFF
            inputs.view = view
            trace = ctrl.DebugPixel(x, y, inputs)
            if not trace or not trace.debugger:
                return {
                    "error": "No debug trace for this pixel",
                    "eventId": event_id if event_id > 0 else original_event,
                    "x": x, "y": y, "sample": sample,
                    "primitiveId": primitive_id, "view": view,
                }
            result = {
                "eventId": event_id if event_id > 0 else original_event,
                "x": x, "y": y, "sample": sample,
                "primitiveId": primitive_id, "view": view,
            }
            result.update(_collect_shader_debug_states(ctrl, trace, dict(result, kind="pixel")))
            return result
        finally:
            if trace:
                try:
                    ctrl.FreeTrace(trace)
                except Exception:
                    pass
            _set_frame_event(ctrl, original_event, True)

    return _replay(_do)


def _debug_vertex(params):
    """Debug vertex shader execution."""
    vertex_id = params.get("vertex_id", 0)
    instance_id = params.get("instance_id", 0)
    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        trace = None
        try:
            trace = ctrl.DebugVertex(vertex_id, instance_id, 0, 0)
            if not trace or not trace.debugger:
                return {"error": "No debug trace for this vertex"}
            result = {"vertexId": vertex_id, "instanceId": instance_id, "eventId": original_event}
            result.update(_collect_shader_debug_states(ctrl, trace, dict(result, kind="vertex")))
            return result
        finally:
            try:
                if trace:
                    ctrl.FreeTrace(trace)
            finally:
                _set_frame_event(ctrl, original_event, True)

    return _replay(_do)


def _enumerate_counters(params):
    """List available GPU counters."""
    def _do(ctrl):
        counters = ctrl.EnumerateCounters()
        result = []
        for c in counters:
            desc = ctrl.DescribeCounter(c)
            result.append({"id": int(c), "name": desc.name, "desc": desc.description, "unit": str(desc.unit)})
        return result
    return _replay(_do)


def _fetch_counters(params):
    """Fetch GPU counter values."""
    ids = params.get("counter_ids", [])
    if not ids:
        raise ValueError("counter_ids required")

    def _do(ctrl):
        counters = [rd.GPUCounter(c) for c in ids]
        results = ctrl.FetchCounters(counters)
        return [{"eventId": r.eventId, "counter": int(r.counter), "value": r.value.d if hasattr(r.value, "d") else 0} for r in results]
    return _replay(_do)


def _counter_result_value(result, description):
    result_type = str(getattr(description, "resultType", "")).lower()
    byte_width = _safe_int(getattr(description, "resultByteWidth", 8), 8)
    value = getattr(result, "value", None)
    try:
        if "float" in result_type:
            return float(value.f if byte_width <= 4 else value.d)
        if "uint" in result_type:
            return int(value.u32 if byte_width <= 4 else value.u64)
        if "sint" in result_type:
            # CounterValue only exposes unsigned integer storage. Preserve its numeric bits rather
            # than fabricating a signed interpretation without a documented width conversion.
            return int(value.u32 if byte_width <= 4 else value.u64)
    except Exception:
        pass
    return None


def _get_action_timings(params):
    """Fetch the real GPU event-duration counter or report that it is unsupported."""
    requested_ids = set()
    for value in params.get("event_ids", []) or []:
        event_id = _safe_int(value, -1)
        if event_id < 0:
            raise ValueError("event_ids must contain non-negative integers")
        requested_ids.add(event_id)
    marker_filter = str(params.get("marker_filter", "") or "").strip().lower()

    try:
        original_event = _request_visible_event_id(0)
        restore_event = True
    except Exception:
        original_event = 0
        restore_event = False

    def _do(ctrl):
        try:
            available = list(ctrl.EnumerateCounters() or [])
            duration_id = None
            try:
                standard_duration = _safe_int(rd.GPUCounter.EventGPUDuration, 1)
            except Exception:
                standard_duration = 1
            descriptions = {}
            for counter in available:
                counter_id = _safe_int(counter, -1)
                try:
                    description = ctrl.DescribeCounter(counter)
                    descriptions[counter_id] = description
                except Exception:
                    continue
                if counter_id == standard_duration:
                    duration_id = counter
                    break

            if duration_id is None:
                for counter in available:
                    counter_id = _safe_int(counter, -1)
                    description = descriptions.get(counter_id)
                    if description is None:
                        try:
                            description = ctrl.DescribeCounter(counter)
                            descriptions[counter_id] = description
                        except Exception:
                            continue
                    text = (str(getattr(description, "name", "")) + " " +
                            str(getattr(description, "description", ""))).lower()
                    if "duration" in text and "gpu" in text:
                        duration_id = counter
                        break

            if duration_id is None:
                return {
                    "schema": "renderdoc-ultra-action-timings/v1",
                    "schemaVersion": 1,
                    "supported": False,
                    "reason": "GPU event-duration counter is not available on this replay device.",
                    "availableCounterIds": [_safe_int(counter, -1) for counter in available],
                    "timings": [],
                }

            duration_key = _safe_int(duration_id, -1)
            description = descriptions.get(duration_key)
            if description is None:
                description = ctrl.DescribeCounter(duration_id)
            action_map = _pixel_action_map(ctrl)
            try:
                fetched = ctrl.FetchCounters([duration_id])
            except Exception as exc:
                return {
                    "schema": "renderdoc-ultra-action-timings/v1",
                    "schemaVersion": 1,
                    "supported": False,
                    "reason": "GPU duration counter fetch failed: %s" % str(exc),
                    "counterId": duration_key,
                    "timings": [],
                }

            timings = []
            for counter_result in fetched or []:
                event_id = _safe_int(getattr(counter_result, "eventId", 0), 0)
                if requested_ids and event_id not in requested_ids:
                    continue
                action = action_map.get(event_id)
                if marker_filter:
                    if action is None:
                        continue
                    searchable = " / ".join(
                        list(action.get("markerPath", [])) + [action.get("name", "")]
                    ).lower()
                    if marker_filter not in searchable:
                        continue
                value = _counter_result_value(counter_result, description)
                record = {
                    "eventId": event_id,
                    "seconds": value,
                    "milliseconds": value * 1000.0 if value is not None else None,
                }
                if action is not None:
                    record["action"] = action
                timings.append(record)

            timings.sort(key=lambda item: item["eventId"])
            return {
                "schema": "renderdoc-ultra-action-timings/v1",
                "schemaVersion": 1,
                "supported": True,
                "counter": {
                    "id": duration_key,
                    "name": str(getattr(description, "name", "")),
                    "description": str(getattr(description, "description", "")),
                    "unit": str(getattr(description, "unit", "")),
                },
                "filters": {
                    "eventIds": sorted(requested_ids),
                    "markerFilter": marker_filter,
                },
                "count": len(timings),
                "timings": timings,
            }
        finally:
            if restore_event:
                _set_frame_event(ctrl, original_event, True)

    return _replay(_do)


def _get_post_vs_data(params):
    """Read bounded post-transform positions at one exact EID and restore replay."""
    from .mesh_evidence import bounded_integer, read_mesh

    original_event = _request_visible_event_id()
    event_id = params.get("event_id", 0)
    bounded_integer(event_id, "event_id", 0, 0xffffffff)
    event_id = event_id or original_event
    bounded_integer(event_id, "event_id", 1, 0xffffffff)
    instance = bounded_integer(params.get("instance", 0), "instance", 0, 0xffffffff)
    view = bounded_integer(params.get("view", 0), "view", 0, 2047)
    max_vertices = bounded_integer(params.get("max_vertices", 4096), "max_vertices", 1, 16384)
    max_indices = bounded_integer(params.get("max_indices", 12288), "max_indices", 1, 49152)
    stage_name = params.get("stage", "vs-out")
    if stage_name not in ("vs-out", "gs-out"):
        raise ValueError("stage must be vs-out or gs-out")

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, event_id, True)
            action = _find_action_by_event(ctrl.GetRootActions(), event_id)
            if action is None or not int(action.flags) & (0x0002 | 0x0008):
                raise ValueError("The event is not a captured geometry draw")
            instances = _action_workload(action)["instanceCount"]
            if int(action.flags) & 0x0002 and (instances <= 0 or instance >= instances):
                raise ValueError("The requested draw instance is unavailable or unresolved")
            if int(action.flags) & 0x0008 and instance:
                raise ValueError("Mesh dispatch geometry does not select a draw instance")
            pipeline = ctrl.GetPipelineState()
            try:
                view_count = max(1, int(pipeline.MultiviewBroadcastCount()))
            except Exception:
                view_count = 1
            if view >= view_count:
                raise ValueError("The requested geometry view is not available in this pipeline")
            mesh = ctrl.GetPostVSData(instance, view, rd.MeshDataStage.VSOut if stage_name == "vs-out"
                                      else rd.MeshDataStage.GSOut)
            _require_healthy_replay(ctrl)
            result = read_mesh(ctrl, mesh, max_vertices, max_indices)
            _require_healthy_replay(ctrl)
            final_positions = stage_name == "gs-out"
            if stage_name == "vs-out":
                try:
                    final_positions = not any(int(pipeline.GetShader(getattr(rd.ShaderStage, name)))
                                              for name in ("Hull", "Domain", "Geometry", "Mesh")
                                              if hasattr(rd.ShaderStage, name))
                except Exception:
                    final_positions = False
            result.update({"schema": "bread-mesh-evidence/v1", "eventId": event_id,
                           "captureSessionId": _request_capture_session_id(),
                           "instance": instance, "view": view, "stage": stage_name,
                           "viewCount": view_count,
                           "instanceCount": instances,
                           "allInstances": instances == 1,
                           "finalPositionStage": final_positions,
                           "rasterCoverageVerified": False})
            if instances > 1:
                result["limitations"].append("selected-instance-only")
            try:
                viewport = pipeline.GetViewport(0)
                result["viewport"] = {name: _finite_pipeline_number(getattr(viewport, name, None))
                                      for name in ("x", "y", "width", "height")}
            except Exception:
                result["viewport"] = None
            return result
        finally:
            if original_event != event_id:
                _set_frame_event(ctrl, original_event, True, allow_background_preemption=False)
    return _replay(_do)


def _get_debug_messages(params):
    """Get debug/validation messages."""
    def _do(ctrl):
        msgs = ctrl.GetDebugMessages()
        return [{"eventId": m.eventId, "severity": str(m.severity), "msg": m.description} for m in msgs]
    return _replay(_do)


def _list_captures(params):
    """List .rdc files in a directory."""
    directory = params.get("directory", "")
    if not directory:
        raise ValueError("directory required")
    result = []
    for f in os.listdir(directory):
        if f.lower().endswith(".rdc"):
            fp = os.path.join(directory, f)
            result.append({"name": f, "path": fp, "size": os.path.getsize(fp)})
    return result


def _reject_duplicate_json_object(pairs):
    """Reject duplicate keys in cache metadata read from an untrusted RDC."""

    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Bread RDC project index contains a duplicate JSON key")
        result[key] = value
    return result


def _canonical_project_index_bytes(document):
    return json.dumps(
        document, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False).encode("utf-8")


def _reject_project_index_json_constant(value):
    raise ValueError(
        "Bread RDC project index contains a non-finite number: %s" % value)


def _validated_project_index_document(value):
    """Validate the small sealed envelope; the Host validates every record."""

    if not isinstance(value, dict):
        raise ValueError("Bread RDC project index must be a JSON object")
    version = value.get("schemaVersion")
    if (not isinstance(version, int) or isinstance(version, bool) or
            version not in REPLAYLAB_RDC_PROJECT_INDEX_SCHEMAS):
        raise ValueError("Bread RDC project index has an unsupported version")
    if value.get("schema") != REPLAYLAB_RDC_PROJECT_INDEX_SCHEMAS[version]:
        raise ValueError("Bread RDC project index has an unsupported schema")
    bindings = value.get("bindings")
    if not isinstance(bindings, list) or len(bindings) > 4096:
        raise ValueError("Bread RDC project index bindings are invalid")
    seal = str(value.get("sealSha256", "") or "").lower()
    if (len(seal) != 64 or
            any(character not in "0123456789abcdef" for character in seal)):
        raise ValueError("Bread RDC project index seal is invalid")
    unsigned = dict(value)
    unsigned.pop("sealSha256", None)
    expected = hashlib.sha256(_canonical_project_index_bytes(unsigned)).hexdigest()
    if seal != expected:
        raise ValueError("Bread RDC project index seal does not match its content")
    return value


def _require_project_index_capture(params):
    if not _ctx or not _ctx.IsCaptureLoaded():
        raise RuntimeError("No capture is loaded in RenderDoc")
    expected_session = str(params.get("expected_capture_session_id", "") or "")
    if expected_session and expected_session != _capture_session_id:
        raise RuntimeError("RenderDoc capture session changed before RDC index access")
    current_path = os.path.abspath(str(_ctx.GetCaptureFilename() or ""))
    expected_path = str(params.get("expected_capture_path", "") or "").strip()
    if (expected_path and
            os.path.normcase(os.path.abspath(expected_path)) !=
            os.path.normcase(current_path)):
        raise RuntimeError("RenderDoc capture path changed before RDC index access")
    if not current_path or not current_path.lower().endswith(".rdc"):
        raise RuntimeError("The loaded capture is not a local RDC file")
    return current_path


def _project_index_section(access):
    count = int(access.GetSectionCount())
    if count < 0 or count > MAX_CAPTURE_SECTION_COUNT:
        raise RuntimeError("The RDC section table exceeds Bread's safety bound")
    matches = []
    for index in range(count):
        props = access.GetSectionProperties(index)
        if str(getattr(props, "name", "") or "") == REPLAYLAB_RDC_PROJECT_INDEX_SECTION:
            matches.append((index, props))
    if len(matches) > 1:
        raise RuntimeError("The RDC contains duplicate Bread project-index sections")
    return matches[0] if matches else (None, None)


def _read_project_index_from_access(access):
    index, props = _project_index_section(access)
    if index is None:
        return {
            "schema": "replaylab-rdc-project-index-transport/v1",
            "schemaVersion": 1,
            "sectionName": REPLAYLAB_RDC_PROJECT_INDEX_SECTION,
            "present": False,
            "document": None,
        }
    section_version = int(getattr(props, "version", 0))
    if section_version not in REPLAYLAB_RDC_PROJECT_INDEX_SCHEMAS:
        raise RuntimeError("The RDC Bread project-index section version is unsupported")
    declared_size = int(getattr(props, "uncompressedSize", 0))
    if declared_size < 0 or declared_size > MAX_REPLAYLAB_RDC_PROJECT_INDEX_BYTES:
        raise RuntimeError("The RDC Bread project index exceeds the size limit")
    contents = bytes(access.GetSectionContents(index))
    if not contents or len(contents) > MAX_REPLAYLAB_RDC_PROJECT_INDEX_BYTES:
        raise RuntimeError("The RDC Bread project index has an invalid size")
    if declared_size and declared_size != len(contents):
        raise RuntimeError("The RDC Bread project-index size metadata is inconsistent")
    try:
        document = json.loads(
            contents.decode("utf-8"),
            object_pairs_hook=_reject_duplicate_json_object,
            parse_constant=_reject_project_index_json_constant)
    except (UnicodeDecodeError, ValueError, TypeError) as exc:
        raise RuntimeError("The RDC Bread project index is not strict UTF-8 JSON: %s" % exc)
    _validated_project_index_document(document)
    if document.get("schemaVersion") != section_version:
        raise RuntimeError(
            "The RDC Bread project-index section and document versions differ")
    return {
        "schema": "replaylab-rdc-project-index-transport/v1",
        "schemaVersion": 1,
        "sectionName": REPLAYLAB_RDC_PROJECT_INDEX_SECTION,
        "sectionVersion": int(getattr(props, "version", 0)),
        "present": True,
        "encodedSize": len(contents),
        "encodedSha256": hashlib.sha256(contents).hexdigest(),
        "document": document,
    }


def _read_rdc_project_index(params):
    """Read the bounded ReplayLab association cache without replay traversal."""

    def _snapshot_on_ui():
        path = _require_project_index_capture(params)
        return path, _ctx.Replay().GetCaptureAccess(), str(_capture_session_id or "")

    path, access, capture_session_id = _invoke_on_ui_sync(_snapshot_on_ui)
    if access is None:
        raise RuntimeError("The loaded capture does not expose section access")
    result = _read_project_index_from_access(access)
    result.update({
        "capturePath": path,
        "captureSessionId": capture_session_id,
    })
    return result


def _write_rdc_project_index(params):
    """Append/replace only ReplayLab's named custom section, then read it back."""

    document = _validated_project_index_document(params.get("document"))
    if (document.get("schemaVersion") != REPLAYLAB_RDC_PROJECT_INDEX_VERSION or
            document.get("schema") != REPLAYLAB_RDC_PROJECT_INDEX_SCHEMA):
        raise ValueError(
            "Bread only writes the current RDC project-index schema")
    encoded = _canonical_project_index_bytes(document)
    if not encoded or len(encoded) > MAX_REPLAYLAB_RDC_PROJECT_INDEX_BYTES:
        raise ValueError("Bread RDC project index exceeds the size limit")
    def _snapshot_on_ui():
        path = _require_project_index_capture(params)
        return path, _ctx.Replay().GetCaptureFile(), str(_capture_session_id or "")

    path, capture_file, capture_session_id = _invoke_on_ui_sync(_snapshot_on_ui)
    if capture_file is None:
        raise RuntimeError("Bread can only write an index to a local capture file")
    # Unknown + a unique name is RenderDoc's public custom-section contract.
    props = rd.SectionProperties()
    props.name = REPLAYLAB_RDC_PROJECT_INDEX_SECTION
    props.type = rd.SectionType.Unknown
    props.version = int(document["schemaVersion"])
    props.flags = rd.SectionFlags.ZstdCompressed
    written = capture_file.WriteSection(props, encoded)
    ok = getattr(written, "OK", None)
    if callable(ok) and not ok():
        message = str(getattr(written, "message", "") or "")
        raise RuntimeError(message or "RenderDoc could not write the Bread RDC index")
    # Treat the section as committed only after an exact read-back through the
    # same capture handle. It remains a cache, never physical apply authority.
    verified = _read_project_index_from_access(capture_file)
    if (not verified.get("present") or
            verified.get("encodedSha256") != hashlib.sha256(encoded).hexdigest() or
            verified.get("document") != document):
        raise RuntimeError("Bread RDC project index failed post-write verification")
    verified.update({
        "capturePath": path,
        "captureSessionId": capture_session_id,
        "written": True,
        "physicalApplyAuthority": False,
    })
    return verified


def _project_shader_index_hex(value, length, label):
    text = str(value or "").strip().lower()
    if (len(text) != length or
            any(character not in "0123456789abcdef" for character in text)):
        raise ValueError("%s must be %d lowercase hexadecimal characters" %
                         (label, length))
    return text


def _project_shader_index_api(value):
    token = _physical_enum(value)
    aliases = {
        "direct3d11": "d3d11",
        "direct3d12": "d3d12",
        "gl": "opengl",
        "openglcore": "opengl",
    }
    return aliases.get(token, token)


def _project_shader_index_encoding(value):
    token = _physical_enum(value).replace("-", "")
    aliases = {
        "directxbytecode": "dxbc",
        "directxil": "dxil",
        "dxilcontainer": "dxil",
        "spv": "spirv",
        "spirvshader": "spirv",
        "openglspirv": "opengl-spirv",
        "glslshader": "glsl",
        "openglglsl": "glsl",
    }
    return aliases.get(token, token)


def _project_shader_index_format_supported(api, encoding):
    return encoding in {
        "d3d11": {"dxbc"},
        "d3d12": {"dxbc", "dxil"},
        "opengl": {"glsl", "spirv", "opengl-spirv"},
        "vulkan": {"spirv"},
    }.get(api, set())


def _project_shader_stable_identity(api, encoding, raw_sha256, stage,
                                    entry_point, abi_hash, layout_hash,
                                    physical_abi_authoritative):
    """Return the capture-independent exact Shader identity material.

    ResourceId and EID are deliberately absent.  The digest remains useful as
    a project-knowledge lookup key when all material is present, while
    ``stableKeyComplete`` separately records whether the ABI came from an
    authoritative physical reflection for executable reuse.
    """

    material = {
        "api": _project_shader_index_api(api),
        "encoding": _project_shader_index_encoding(encoding),
        "rawSha256": str(raw_sha256 or "").lower(),
        "stage": _normalise_stage_name(stage),
        "entryPoint": str(entry_point or ""),
        "abiHash": str(abi_hash or "").lower(),
        "layoutHash": str(layout_hash or "").lower(),
    }
    # RenderDoc permits an empty entry-point token for some binary families;
    # it is still an explicit component of the canonical key.  The digest is
    # always present, including for evidence-only/incomplete identities, so a
    # v1 migration or knowledge-only association can be checked without being
    # mistaken for executable authority.
    material_present = all(
        material[name] for name in (
            "api", "encoding", "rawSha256", "stage", "abiHash",
            "layoutHash"))
    return {
        "stableKeyMaterial": material,
        "stableKeySha256": hashlib.sha256(
            _canonical_project_index_bytes(material)).hexdigest(),
        "stableKeyComplete": bool(
            material_present and physical_abi_authoritative),
    }


def _validated_project_shader_index_request(params, capture_path):
    capture_id = _project_shader_index_hex(
        params.get("expected_capture_id"), 64, "expected_capture_id")
    evidence_sha256 = _project_shader_index_hex(
        params.get("expected_identity_evidence_sha256"), 64,
        "expected_identity_evidence_sha256")
    inventory_all = params.get("inventory_all_shaders", False)
    discover_anchors = params.get("discover_anchor_eids", inventory_all)
    if not isinstance(inventory_all, bool):
        raise ValueError("inventory_all_shaders must be a boolean")
    if not isinstance(discover_anchors, bool):
        raise ValueError("discover_anchor_eids must be a boolean")
    target_raw_hashes = []
    if "target_raw_sha256s" in params:
        raw_targets = params["target_raw_sha256s"]
        if (not inventory_all or not isinstance(raw_targets, list) or
                not 1 <= len(raw_targets) <= MAX_PROJECT_SHADER_INDEX_TARGET_RAW_HASHES):
            raise ValueError(
                "target_raw_sha256s requires all-Shader inventory and 1..%d hashes" %
                MAX_PROJECT_SHADER_INDEX_TARGET_RAW_HASHES)
        for value in raw_targets:
            digest = _project_shader_index_hex(value, 64, "target_raw_sha256s item")
            if not isinstance(value, str) or value != digest:
                raise ValueError("target_raw_sha256s items must be exact lowercase hashes")
            target_raw_hashes.append(digest)
        target_raw_hashes = sorted(set(target_raw_hashes))
    api = _project_shader_index_api(params.get("expected_api"))
    if ((not api and not inventory_all) or len(api) > 32 or
            any(character not in "abcdefghijklmnopqrstuvwxyz0123456789-"
                for character in api)):
        raise ValueError("expected_api is invalid")
    values = params.get("expected_shaders")
    if values is None and inventory_all:
        values = []
    if (not isinstance(values, list) or
            (not values and not inventory_all) or
            len(values) > MAX_PROJECT_SHADER_INDEX_EXPECTED):
        raise ValueError(
            "expected_shaders must contain between %d and %d records" %
            (0 if inventory_all else 1,
            MAX_PROJECT_SHADER_INDEX_EXPECTED)
        )
    if target_raw_hashes and values:
        raise ValueError("target raw lookup cannot include expected Shader ResourceIds")
    shaders = []
    keys = set()
    anchors_by_resource = {}
    total_blocks = 0
    for index, value in enumerate(values):
        required_fields = {
            "resourceId", "stage", "entryPoint", "encoding", "rawSha256",
            "interfaceHash", "layoutHash", "interfaceComplete",
            "constantBlocks",
        }
        allowed_fields = required_fields | {
            "anchorEventId", "api", "abiHash", "stableKeyComplete",
            "stableKeySha256",
        }
        if (not isinstance(value, dict) or
                not required_fields.issubset(value) or
                not set(value).issubset(allowed_fields)):
            raise ValueError("expected_shaders[%d] fields are invalid" % index)
        resource_id = _safe_int(value.get("resourceId"), -1)
        stage = _normalise_stage_name(value.get("stage"))
        entry_point = str(value.get("entryPoint", "") or "")
        encoding = _project_shader_index_encoding(value.get("encoding"))
        raw_sha256 = _project_shader_index_hex(
            value.get("rawSha256"), 64,
            "expected_shaders[%d].rawSha256" % index)
        interface_hash = str(value.get("interfaceHash", "") or "").lower()
        layout_hash = str(value.get("layoutHash", "") or "").lower()
        for digest, label in (
                (interface_hash, "interfaceHash"),
                (layout_hash, "layoutHash")):
            if digest:
                _project_shader_index_hex(
                    digest, 64, "expected_shaders[%d].%s" % (index, label))
        interface_complete = value.get("interfaceComplete")
        anchor_event_id = _safe_int(value.get("anchorEventId"), 0)
        if (resource_id <= 0 or not stage or len(stage) > 32 or
                len(entry_point.encode("utf-8")) > 512 or
                not encoding or len(encoding) > 32 or
                any(character not in "abcdefghijklmnopqrstuvwxyz0123456789-"
                    for character in encoding) or
                not isinstance(interface_complete, bool) or
                anchor_event_id < 0 or anchor_event_id > 0xFFFFFFFF):
            raise ValueError("expected_shaders[%d] identity is invalid" % index)
        existing_anchor = anchors_by_resource.get(resource_id)
        if (existing_anchor is not None and existing_anchor != anchor_event_id and
                existing_anchor > 0 and anchor_event_id > 0):
            raise ValueError(
                "expected_shaders assigns more than one representative EID "
                "to one Shader resource")
        if anchor_event_id > 0:
            anchors_by_resource[resource_id] = anchor_event_id
        elif existing_anchor is None:
            anchors_by_resource[resource_id] = 0
        key = (resource_id, stage, entry_point, raw_sha256)
        if key in keys:
            raise ValueError("expected_shaders contains a duplicate Shader identity")
        keys.add(key)
        raw_blocks = value.get("constantBlocks")
        if not isinstance(raw_blocks, list):
            raise ValueError("expected_shaders[%d].constantBlocks is invalid" % index)
        total_blocks += len(raw_blocks)
        if total_blocks > MAX_PROJECT_SHADER_INDEX_BLOCKS:
            raise ValueError("expected Shader constant-block identities are oversized")
        blocks = []
        block_keys = set()
        for block_index, block in enumerate(raw_blocks):
            if not isinstance(block, dict) or set(block) != {
                    "index", "path", "space", "bind", "byteSize",
                    "layoutSha256", "abiSha256"}:
                raise ValueError(
                    "expected_shaders[%d].constantBlocks[%d] fields are invalid" %
                    (index, block_index))
            reflected_index = _safe_int(block.get("index"), -1)
            path = str(block.get("path", "") or "")
            space = _safe_int(block.get("space"), -1)
            bind = _safe_int(block.get("bind"), -1)
            byte_size = _safe_int(block.get("byteSize"), -1)
            layout_sha256 = _project_shader_index_hex(
                block.get("layoutSha256"), 64,
                "expected constant-block layoutSha256")
            abi_sha256 = _project_shader_index_hex(
                block.get("abiSha256"), 64,
                "expected constant-block abiSha256")
            block_key = (space, bind, reflected_index, path)
            if (reflected_index < 0 or reflected_index > 65535 or
                    space < 0 or space > 65535 or bind < 0 or bind > 65535 or
                    byte_size <= 0 or byte_size > (1 << 32) - 1 or not path or
                    len(path.encode("utf-8")) > 2048 or block_key in block_keys):
                raise ValueError("expected constant-block identity is invalid")
            block_keys.add(block_key)
            blocks.append({
                "index": reflected_index,
                "path": path,
                "space": space,
                "bind": bind,
                "byteSize": byte_size,
                "layoutSha256": layout_sha256,
                "abiSha256": abi_sha256,
            })
        expected_abi_hash = str(value.get("abiHash", "") or "").lower()
        if expected_abi_hash:
            _project_shader_index_hex(
                expected_abi_hash, 64,
                "expected_shaders[%d].abiHash" % index)
        expected_api = _project_shader_index_api(value.get("api", api))
        if expected_api and api and expected_api != api:
            raise ValueError("expected_shaders[%d].api does not match expected_api" % index)
        expected_key_sha256 = str(
            value.get("stableKeySha256", "") or "").lower()
        if expected_key_sha256:
            _project_shader_index_hex(
                expected_key_sha256, 64,
                "expected_shaders[%d].stableKeySha256" % index)
        expected_key_complete = value.get("stableKeyComplete", False)
        if not isinstance(expected_key_complete, bool):
            raise ValueError(
                "expected_shaders[%d].stableKeyComplete is invalid" % index)
        stable_layout_hash = layout_hash or (
            _canonical_json_sha256([]) if not blocks else "")
        if (expected_key_complete and
                (not (expected_api or api) or not expected_abi_hash or
                 not stable_layout_hash)):
            raise ValueError(
                "expected_shaders[%d] marks an incomplete stable key complete" %
                index)
        if expected_key_sha256:
            recomputed_key = _project_shader_stable_identity(
                expected_api or api, encoding, raw_sha256, stage,
                entry_point, expected_abi_hash, stable_layout_hash,
                expected_key_complete)["stableKeySha256"]
            if recomputed_key != expected_key_sha256:
                raise ValueError(
                    "expected_shaders[%d].stableKeySha256 does not match "
                    "its stable-key fields" % index)
        shaders.append({
            "resourceId": resource_id,
            "stage": stage,
            "entryPoint": entry_point,
            "api": expected_api or api,
            "encoding": encoding,
            "rawSha256": raw_sha256,
            "abiHash": expected_abi_hash,
            "interfaceHash": interface_hash,
            "layoutHash": layout_hash,
            "interfaceComplete": interface_complete,
            "stableKeyComplete": expected_key_complete,
            "stableKeySha256": expected_key_sha256,
            "constantBlocks": sorted(
                blocks, key=lambda item: (
                    item["space"], item["bind"], item["index"], item["path"])),
            "anchorEventId": anchor_event_id,
        })
    shaders.sort(key=lambda item: (
        item["resourceId"], item["stage"], item["entryPoint"],
        item["rawSha256"]))
    request = {
        "capturePath": os.path.normcase(os.path.abspath(capture_path)),
        "captureSessionId": _capture_session_id,
        "captureId": capture_id,
        "identityEvidenceSha256": evidence_sha256,
        "api": api,
        "shaders": shaders,
        "inventoryAllShaders": inventory_all,
        "discoverAnchorEids": discover_anchors,
    }
    if target_raw_hashes:
        request["targetRawSha256s"] = target_raw_hashes
    request["requestSha256"] = hashlib.sha256(
        _canonical_project_index_bytes(request)).hexdigest()
    if len(_canonical_project_index_bytes(request)) > MAX_PROJECT_SHADER_INDEX_BYTES:
        raise ValueError("expected Shader resource-index request exceeds the size limit")
    return request


def _project_shader_index_capability(api, supported, reason_id=""):
    return {
        "supported": bool(supported),
        "api": api,
        "mode": "unique-shader-resource-reflection",
        "reasonId": str(reason_id or ""),
        "fallback": "knowledge-only-without-exact-abi-anchor",
        "eventTraversalSupported": False,
        "fullFrameTraversalSupported": False,
        "physicalAbiFromNullPipeline": bool(
            supported and api in ("d3d11", "d3d12", "opengl")),
        "anchorPreflightRequired": True,
    }


def _project_shader_index_job_snapshot(job, idempotent=False):
    value = {
        "schema": "replaylab-project-shader-resource-index-job/v1",
        "schemaVersion": 1,
        "jobId": job["jobId"],
        "status": job["status"],
        "captureSessionId": job["captureSessionId"],
        "requestSha256": job["requestSha256"],
        "idempotent": bool(idempotent),
        "committed": job.get("committed") is True,
        "cancellationRequested": job.get("cancelRequested") is True,
        "progress": dict(job.get("progress") or {}),
    }
    if job["status"] == "completed":
        value["result"] = job["result"]
    elif job["status"] == "failed" or job.get("cancelRequested") is True:
        value["error"] = str(job.get("error", "") or "")[:4096]
    return value


def _update_project_shader_index_job_progress(job_id, progress):
    with _project_shader_index_jobs_guard:
        job = _project_shader_index_jobs.get(job_id)
        if (job is None or job.get("status") not in ("queued", "running") or
                job.get("cancelRequested") is True):
            return
        job["progress"] = dict(progress or {})
        job["updatedMonotonic"] = time.monotonic()


def _request_project_shader_index_cancel(job, now, reason):
    if job.get("status") not in ("queued", "running"):
        return False
    cancel_event = job.get("cancelEvent")
    if cancel_event is not None:
        cancel_event.set()
    if job.get("cancelRequested") is not True:
        job["cancelRequested"] = True
        job["cancelRequestedMonotonic"] = now
        job["error"] = str(reason or "Project Shader resource indexing cancelled")
        job["updatedMonotonic"] = now
    return True


def _cleanup_project_shader_index_jobs(now):
    for job in _project_shader_index_jobs.values():
        if (job.get("status") in ("queued", "running") and
                job.get("cancelRequested") is not True and
                now - float(job.get("createdMonotonic", now)) >=
                PROJECT_SHADER_INDEX_JOB_TIMEOUT_SECONDS):
            was_queued = job.get("status") == "queued"
            _request_project_shader_index_cancel(
                job, now, "Project Shader resource indexing timed out")
            # A request that never entered ReplayManager has no worker left to
            # acknowledge cancellation.  Make that state terminal immediately;
            # otherwise it remains queued forever and permanently consumes the
            # bounded job capacity.  Running work retains its cancellation flag
            # until its replay callback observes it and records the terminal
            # result, so a blocked replay cannot be mistaken for released work.
            if was_queued:
                job["status"] = "failed"
                job["finishedMonotonic"] = now
    expired = [
        job_id for job_id, job in _project_shader_index_jobs.items()
        if (job.get("status") in ("completed", "failed") and
            now - float(job.get("updatedMonotonic", now)) >=
            PROJECT_SHADER_INDEX_JOB_TTL_SECONDS)
    ]
    for job_id in expired:
        _project_shader_index_jobs.pop(job_id, None)


def _project_shader_resource_type(value):
    resource_type = getattr(value, "type", None)
    shader_type = getattr(getattr(rd, "ResourceType", None), "Shader", None)
    if shader_type is not None and resource_type == shader_type:
        return True
    return _physical_enum(resource_type) == "shader"


class _ProjectShaderIndexLimit(RuntimeError):
    def __init__(self, reason_id, message):
        RuntimeError.__init__(self, message)
        self.reason_id = reason_id


class _ProjectShaderIndexCancelled(RuntimeError):
    pass


def _check_project_shader_index_cancel(cancel_event):
    expected_generation = getattr(
        cancel_event, "replaylabForegroundGeneration", None)
    replay_manager = getattr(cancel_event, "replaylabReplayManager", None)
    current_generation = (
        _replay_foreground_generation(replay_manager)
        if replay_manager is not None else _foreground_replay_generation())
    if (cancel_event is not None and expected_generation is not None and
            current_generation is not None and
            current_generation != expected_generation):
        cancel_event.set()
        raise _ProjectShaderIndexCancelled(
            "Project Shader resource indexing yielded after a user replay operation")
    if cancel_event is not None and cancel_event.is_set():
        raise _ProjectShaderIndexCancelled(
            "Project Shader resource indexing cancelled")


def _new_project_shader_reflection_budget():
    return {
        "fields": 0,
        "signatures": 0,
        "bindings": 0,
        "samplers": 0,
        "stringBytes": 0,
    }


def _project_shader_index_charge(budget, key, maximum, reason_id, label):
    budget[key] = _safe_int(budget.get(key), 0) + 1
    if budget[key] > maximum:
        raise _ProjectShaderIndexLimit(
            reason_id, "Shader reflection exceeds the %s limit" % label)


def _project_shader_index_text(value, budget):
    text = str(value or "")
    try:
        size = len(text.encode("utf-8"))
    except UnicodeError:
        raise _ProjectShaderIndexLimit(
            "shader-resource-index-reflection-string-limit",
            "Shader reflection contains invalid Unicode text")
    if size > MAX_PROJECT_SHADER_INDEX_REFLECTION_STRING_BYTES:
        raise _ProjectShaderIndexLimit(
            "shader-resource-index-reflection-string-limit",
            "Shader reflection contains an oversized string")
    budget["stringBytes"] = _safe_int(budget.get("stringBytes"), 0) + size
    if (budget["stringBytes"] >
            MAX_PROJECT_SHADER_INDEX_REFLECTION_TOTAL_STRING_BYTES):
        raise _ProjectShaderIndexLimit(
            "shader-resource-index-reflection-string-limit",
            "Shader reflection text exceeds the aggregate size limit")
    return text


def _project_shader_index_sequence(values, maximum, reason_id, label):
    result = []
    for value in values or []:
        if len(result) >= maximum:
            raise _ProjectShaderIndexLimit(
                reason_id, "Shader resource index exceeds the %s limit" % label)
        result.append(value)
    return result


def _project_shader_reflection_stage_name(reflection, entry):
    """Read one canonical Stage without eagerly touching a bad fallback enum."""

    # ``getattr(reflection, "stage", getattr(entry, "stage", ""))`` evaluates
    # the entry fallback first. Some captures expose a driver/internal entry
    # with an enum newer than the embedded Python bindings even though the
    # reflection itself has a valid Stage. Probe the authoritative reflection
    # first, and only touch the entry if it cannot provide a known Stage.
    for value in (reflection, entry):
        try:
            stage = _normalise_stage_name(getattr(value, "stage", ""))
        except Exception:
            continue
        if stage in _SHADER_STAGE_NAMES:
            return stage
    return ""


def _project_shader_index_constants(values, budget, depth=0,
                                    allow_runtime_arrays=False):
    if depth > MAX_PROJECT_SHADER_INDEX_REFLECTION_DEPTH:
        raise _ProjectShaderIndexLimit(
            "shader-resource-index-reflection-depth-limit",
            "Shader reflection nesting exceeds the depth limit")
    for constant in values or []:
        _project_shader_index_charge(
            budget, "fields", MAX_PROJECT_SHADER_INDEX_REFLECTION_FIELDS,
            "shader-resource-index-reflection-field-limit", "field-count")
        _project_shader_index_text(getattr(constant, "name", ""), budget)
        shader_type = getattr(constant, "type", None)
        if shader_type is None:
            continue
        for attribute in ("name", "baseType"):
            _project_shader_index_text(
                getattr(shader_type, attribute, ""), budget)
        elements = _safe_int(getattr(shader_type, "elements", 1), 1)
        # SPIR-V OpTypeRuntimeArray is reflected as UINT32_MAX, not billions
        # of materialized fields. Preserve that type identity for storage
        # resources while continuing to bound the actual reflected nodes.
        runtime_array = allow_runtime_arrays and elements == 0xFFFFFFFF
        if elements < 0 or (elements > (1 << 20) and not runtime_array):
            raise _ProjectShaderIndexLimit(
                "shader-resource-index-reflection-field-limit",
                "Shader reflection contains an invalid array element count")
        members = getattr(shader_type, "members", []) or []
        if members:
            _project_shader_index_constants(
                members, budget, depth + 1, allow_runtime_arrays)


def _validate_project_shader_reflection_budget(reflection, budget):
    """Bound reflection before any recursive serialisation or JSON hashing."""

    for attribute in ("stage", "entryPoint", "encoding", "outputTopology"):
        _project_shader_index_text(getattr(reflection, attribute, ""), budget)

    blocks = []
    for block in getattr(reflection, "constantBlocks", []) or []:
        if len(blocks) >= MAX_PROJECT_SHADER_INDEX_BLOCKS:
            raise _ProjectShaderIndexLimit(
                "shader-resource-index-block-limit",
                "Shader reflection exceeds the constant-block limit")
        blocks.append(block)
        _project_shader_index_text(getattr(block, "name", ""), budget)
        _project_shader_index_constants(
            getattr(block, "variables", []) or [], budget)

    for attribute in ("inputSignature", "outputSignature"):
        for value in getattr(reflection, attribute, []) or []:
            _project_shader_index_charge(
                budget, "signatures", MAX_PROJECT_SHADER_INDEX_SIGNATURES,
                "shader-resource-index-reflection-signature-limit",
                "signature-count")
            for name in (
                    "varName", "semanticName", "semanticIdxName",
                    "systemValue", "varType", "compType"):
                _project_shader_index_text(getattr(value, name, ""), budget)

    for attribute in ("readOnlyResources", "readWriteResources"):
        for value in getattr(reflection, attribute, []) or []:
            _project_shader_index_charge(
                budget, "bindings", MAX_PROJECT_SHADER_INDEX_BINDINGS,
                "shader-resource-index-reflection-binding-limit",
                "resource-binding-count")
            for name in ("name", "descriptorType", "textureType"):
                _project_shader_index_text(getattr(value, name, ""), budget)
            variable_type = getattr(value, "variableType", None)
            if variable_type is not None:
                for name in ("name", "baseType"):
                    _project_shader_index_text(
                        getattr(variable_type, name, ""), budget)
                _project_shader_index_constants(
                    getattr(variable_type, "members", []) or [], budget,
                    allow_runtime_arrays=True)

    for value in getattr(reflection, "samplers", []) or []:
        _project_shader_index_charge(
            budget, "samplers", MAX_PROJECT_SHADER_INDEX_SAMPLERS,
            "shader-resource-index-reflection-sampler-limit",
            "sampler-count")
        _project_shader_index_text(getattr(value, "name", ""), budget)

    for value in getattr(reflection, "interfaces", []) or []:
        _project_shader_index_charge(
            budget, "bindings", MAX_PROJECT_SHADER_INDEX_BINDINGS,
            "shader-resource-index-reflection-binding-limit",
            "interface-count")
        _project_shader_index_text(getattr(value, "name", ""), budget)
    return blocks


def _project_symbol_enum_token(value):
    return (str(value or "").strip().lower().rsplit(".", 1)[-1]
            .replace("_", ""))


def _project_symbol_base_type(value):
    if isinstance(value, dict):
        if value.get("members") or value.get("fields"):
            return "struct"
        value = value.get("baseType", value.get("type", ""))
    token = str(value or "").strip().lower().rsplit(".", 1)[-1]
    token = token.replace("_", "").replace(" ", "")
    token = re.sub(r"\d+(x\d+)?$", "", token)
    return {
        "float32": "float",
        "single": "float",
        "sint": "int",
        "signedint": "int",
        "int32": "int",
        "unsignedint": "uint",
        "uint32": "uint",
        "float16": "half",
        "min16float": "half",
        "float64": "double",
    }.get(token, token)


def _project_symbol_fields(values, budget=None, depth=0):
    if budget is None:
        budget = _new_project_shader_reflection_budget()
    if depth > MAX_PROJECT_SHADER_INDEX_REFLECTION_DEPTH:
        raise _ProjectShaderIndexLimit(
            "shader-resource-index-reflection-depth-limit",
            "Shader interface nesting exceeds the depth limit")
    result = []
    for field in values or []:
        if not isinstance(field, dict):
            continue
        _project_shader_index_charge(
            budget, "fields", MAX_PROJECT_SHADER_INDEX_REFLECTION_FIELDS,
            "shader-resource-index-reflection-field-limit", "field-count")
        for value in (
                field.get("name", ""), field.get("path", ""),
                field.get("type", ""), field.get("baseType", "")):
            _project_shader_index_text(value, budget)
        result.append({
            "offset": _safe_int(
                field.get("byteOffset", field.get("offset", -1)), -1),
            "byteSize": _safe_int(field.get("byteSize", 0), 0),
            "type": _project_symbol_base_type(field),
            "rows": _safe_int(field.get("rows", 1), 1),
            "columns": _safe_int(
                field.get("columns", field.get("cols", 1)), 1),
            "elements": _safe_int(field.get("elements", 1), 1),
            "arrayStride": _safe_int(
                field.get("arrayStride", field.get("arrayByteStride", 0)), 0),
            "matrixStride": _safe_int(
                field.get("matrixStride", field.get("matrixByteStride", 0)), 0),
            "rowMajor": bool(field.get("rowMajor", False)),
            "flags": _safe_int(field.get("flags", 0), 0),
            "pointerTypeID": _safe_int(
                field.get("pointerTypeID", 0xFFFFFFFF), 0xFFFFFFFF),
            "bitFieldOffset": _safe_int(field.get("bitFieldOffset", 0), 0),
            "bitFieldSize": _safe_int(field.get("bitFieldSize", 0), 0),
            "members": _project_symbol_fields(
                field.get("members", field.get("fields", [])),
                budget, depth + 1),
        })
    return _physical_sorted(result)


def _project_symbol_layout_material(shader, budget=None):
    if budget is None:
        budget = _new_project_shader_reflection_budget()
    raw_blocks = shader.get(
        "constantBuffers",
        shader.get("constantBlocks", shader.get("constant_blocks", []))) or []
    if not isinstance(raw_blocks, list):
        return []
    result = []
    for block in raw_blocks:
        if not isinstance(block, dict):
            continue
        _project_shader_index_text(block.get("name", ""), budget)
        result.append({
            "space": _safe_int(
                block.get("space", block.get("registerSpace", 0)), 0),
            "bind": _safe_int(
                block.get("bind", block.get("bindNumber", -1)), -1),
            "arraySize": _safe_int(
                block.get("arraySize", block.get("bindArraySize", 1)), 1),
            "size": _safe_int(block.get("byteSize", block.get("size", 0)), 0),
            "bufferBacked": bool(block.get("bufferBacked", True)),
            "inlineDataBytes": bool(block.get("inlineDataBytes", False)),
            "compileConstants": bool(block.get("compileConstants", False)),
            "fields": _project_symbol_fields(
                block.get("fields", block.get("variables", [])), budget),
        })
    return _physical_sorted(result)


def _project_symbol_signature(values, budget):
    result = []
    for value in values or []:
        if not isinstance(value, dict):
            continue
        _project_shader_index_charge(
            budget, "signatures", MAX_PROJECT_SHADER_INDEX_SIGNATURES,
            "shader-resource-index-reflection-signature-limit",
            "signature-count")
        for text in (
                value.get("semanticName", value.get("semantic", "")),
                value.get("semanticIdxName", ""), value.get("systemValue", ""),
                value.get("compType", value.get("componentType", ""))):
            _project_shader_index_text(text, budget)
        result.append({
            "location": _safe_int(
                value.get("regIndex", value.get("location", -1)), -1),
            "semantic": str(
                value.get("semanticName", value.get("semantic", "")) or "").lower(),
            "semanticIndexName": str(
                value.get("semanticIdxName", "") or "").lower(),
            "semanticIndex": _safe_int(
                value.get("semanticIndex", value.get("index", 0)), 0),
            "systemValue": _project_symbol_enum_token(value.get("systemValue", "")),
            "componentType": _project_symbol_base_type(
                value.get("compType", value.get("componentType", ""))),
            "componentCount": _safe_int(
                value.get("compCount", value.get("componentCount", 0)), 0),
            "stream": _safe_int(value.get("stream", 0), 0),
            "registerMask": _safe_int(
                value.get("regChannelMask", value.get("registerMask", 0)), 0),
            "usedMask": _safe_int(
                value.get("channelUsedMask", value.get("usedMask", 0)), 0),
            "perPrimitiveRate": bool(value.get("perPrimitiveRate", False)),
            "needSemanticIndex": bool(value.get("needSemanticIndex", False)),
        })
    return _physical_sorted(result)


def _project_symbol_variable_type(value, budget):
    if not isinstance(value, dict):
        _project_shader_index_text(value, budget)
        return {"legacyToken": _project_symbol_enum_token(value)}
    for text in (value.get("name", ""), value.get("baseType", "")):
        _project_shader_index_text(text, budget)
    return {
        "baseType": _project_symbol_base_type(value),
        "rows": _safe_int(value.get("rows", 0), 0),
        "columns": _safe_int(
            value.get("columns", value.get("cols", 0)), 0),
        "elements": _safe_int(value.get("elements", 0), 0),
        "arrayStride": _safe_int(
            value.get("arrayByteStride", value.get("arrayStride", 0)), 0),
        "matrixStride": _safe_int(
            value.get("matrixByteStride", value.get("matrixStride", 0)), 0),
        "rowMajor": bool(value.get("rowMajor", False)),
        "flags": _safe_int(value.get("flags", 0), 0),
        "pointerTypeID": _safe_int(
            value.get("pointerTypeID", 0xFFFFFFFF), 0xFFFFFFFF),
        "byteSize": _safe_int(value.get("byteSize", 0), 0),
        "members": _project_symbol_fields(
            value.get("members", value.get("fields", [])), budget),
    }


def _project_symbol_bindings(values, budget):
    result = []
    for value in values or []:
        if not isinstance(value, dict):
            continue
        _project_shader_index_charge(
            budget, "bindings", MAX_PROJECT_SHADER_INDEX_BINDINGS,
            "shader-resource-index-reflection-binding-limit",
            "resource-binding-count")
        for text in (
                value.get("name", ""), value.get("descriptorType", ""),
                value.get("resourceType", value.get("resType", "")),
                value.get("textureType", value.get("dimension", ""))):
            _project_shader_index_text(text, budget)
        result.append({
            "space": _safe_int(
                value.get("space", value.get("fixedBindSetOrSpace", 0)), 0),
            "bind": _safe_int(
                value.get("bind", value.get("fixedBindNumber", -1)), -1),
            "arraySize": _safe_int(
                value.get("arraySize", value.get("bindArraySize", 1)), 1),
            "descriptorType": _project_symbol_enum_token(
                value.get("descriptorType", value.get(
                    "resourceType", value.get("resType", "")))),
            "textureType": _project_symbol_enum_token(
                value.get("textureType", value.get("dimension", ""))),
            "variableType": _project_symbol_variable_type(
                value.get("variableType", ""), budget),
            "isTexture": bool(value.get("isTexture", False)),
            "hasSampler": bool(value.get("hasSampler", False)),
            "isInputAttachment": bool(value.get("isInputAttachment", False)),
            "isReadOnly": bool(value.get("isReadOnly", False)),
        })
    return _physical_sorted(result)


def _project_symbol_samplers(values, budget):
    result = []
    for value in values or []:
        if not isinstance(value, dict):
            continue
        _project_shader_index_charge(
            budget, "samplers", MAX_PROJECT_SHADER_INDEX_SAMPLERS,
            "shader-resource-index-reflection-sampler-limit",
            "sampler-count")
        _project_shader_index_text(value.get("name", ""), budget)
        result.append({
            "space": _safe_int(
                value.get("space", value.get("fixedBindSetOrSpace", 0)), 0),
            "bind": _safe_int(
                value.get("bind", value.get("fixedBindNumber", -1)), -1),
            "arraySize": _safe_int(
                value.get("arraySize", value.get("bindArraySize", 1)), 1),
        })
    return _physical_sorted(result)


def _project_symbol_hashes(shader):
    budget = _new_project_shader_reflection_budget()
    blocks = _project_symbol_layout_material(shader, budget)
    # An empty constant-buffer layout is still an exact, hashable layout.  Do
    # not turn it into an unknown value, otherwise valid CBuffer-free shaders
    # can never receive a complete stable key.
    layout_sha256 = _canonical_json_sha256(blocks)
    dimensions = shader.get("threadGroupSize", []) or []
    if not isinstance(dimensions, list):
        dimensions = []
    interface = {
        "inputs": _project_symbol_signature(
            shader.get("inputSignature", shader.get("inputs", [])), budget),
        "outputs": _project_symbol_signature(
            shader.get("outputSignature", shader.get("outputs", [])), budget),
        "readOnly": _project_symbol_bindings(
            shader.get("readOnlyResources", shader.get("resources", [])), budget),
        "readWrite": _project_symbol_bindings(
            shader.get("readWriteResources", []), budget),
        "samplers": _project_symbol_samplers(shader.get("samplers", []), budget),
        "constantBuffers": blocks,
        "threadGroupSize": [_safe_int(value, 0) for value in dimensions],
        "outputTopology": _project_symbol_enum_token(
            shader.get("outputTopology", "")),
        "dynamicLinkageInterfaceCount": _safe_int(
            shader.get("dynamicLinkageInterfaceCount", -1), -1),
    }
    return _canonical_json_sha256(interface), layout_sha256


def _project_shader_index_leaf_base_type(value):
    token = _physical_enum(value)
    return {
        "float": "Float",
        "float32": "Float",
        "single": "Float",
        "sint": "SInt",
        "int": "SInt",
        "int32": "SInt",
        "signedint": "SInt",
        "uint": "UInt",
        "uint32": "UInt",
        "unsignedint": "UInt",
        "double": "Double",
        "float64": "Double",
        "half": "Half",
        "float16": "Half",
        "min16float": "Half",
        "bool": "Bool",
        "boolean": "Bool",
        "slong": "SLong",
        "long": "SLong",
        "int64": "SLong",
        "sint64": "SLong",
        "ulong": "ULong",
        "uint64": "ULong",
        "byte": "Byte",
        "ubyte": "UByte",
        "short": "Short",
        "ushort": "UShort",
    }.get(token, token)


def _project_shader_index_block_fields(reflection_block, projection_budget):
    """Flatten reflected CBuffer leaves without resolving offset ambiguity."""

    leaves = []

    def _nonnegative(value, default, label):
        result = _safe_int(value, default)
        if result < 0:
            raise _ProjectShaderIndexLimit(
                "shader-resource-index-reflection-field-invalid",
                "Shader reflection contains a negative %s" % label)
        return result

    def _visit(values, prefix, parent_offset, depth):
        if depth > MAX_PROJECT_SHADER_INDEX_REFLECTION_DEPTH:
            raise _ProjectShaderIndexLimit(
                "shader-resource-index-reflection-depth-limit",
                "Shader reflection nesting exceeds the depth limit")
        for index, constant in enumerate(values or []):
            projection_budget["fields"] = (
                _safe_int(projection_budget.get("fields"), 0) + 1)
            if (projection_budget["fields"] >
                    MAX_PROJECT_SHADER_INDEX_REFLECTION_FIELDS):
                raise _ProjectShaderIndexLimit(
                    "shader-resource-index-reflection-field-limit",
                    "Shader reflection exceeds the field-count limit")
            name = str(getattr(constant, "name", "") or "field%d" % index)
            canonical_path = name if not prefix else "%s.%s" % (prefix, name)
            if (len(name.encode("utf-8")) >
                    MAX_PROJECT_SHADER_INDEX_REFLECTION_STRING_BYTES or
                    len(canonical_path.encode("utf-8")) > 2048):
                raise _ProjectShaderIndexLimit(
                    "shader-resource-index-reflection-string-limit",
                    "Shader reflection contains an oversized field path")
            local_offset = _nonnegative(
                getattr(constant, "byteOffset", 0), 0, "field byte offset")
            absolute_offset = parent_offset + local_offset
            shader_type = getattr(constant, "type", None)
            if _shader_type_is_empty_struct(shader_type):
                # DXIL can retain empty declarations beside the next field.
                # Match ordinary CBuffer serialization: they own no ABI bytes.
                continue
            members = list(
                getattr(shader_type, "members", []) or []) \
                if shader_type is not None else []
            if members:
                _visit(members, canonical_path, absolute_offset, depth + 1)
                continue
            type_info = _shader_type_info(shader_type)
            byte_size = _nonnegative(
                _shader_type_byte_size(shader_type), 0, "field byte size")
            if byte_size == 0:
                raise _ProjectShaderIndexLimit(
                    "shader-resource-index-reflection-field-invalid",
                    "Shader reflection contains a zero-byte leaf field")
            base_type = _project_shader_index_leaf_base_type(
                type_info.get("baseType", ""))
            if not base_type:
                base_type = "unknown"
            leaves.append({
                "canonicalPath": canonical_path,
                "name": name,
                "absoluteByteOffset": absolute_offset,
                "byteSize": byte_size,
                "baseType": base_type,
                "rows": _nonnegative(type_info.get("rows", 0), 0, "row count"),
                "columns": _nonnegative(
                    type_info.get("columns", 0), 0, "column count"),
                "elements": _nonnegative(
                    type_info.get("elements", 0), 0, "element count"),
                "arrayByteStride": _nonnegative(
                    type_info.get("arrayByteStride", 0), 0,
                    "array byte stride"),
                "matrixByteStride": _nonnegative(
                    type_info.get("matrixByteStride", 0), 0,
                    "matrix byte stride"),
                "rowMajor": bool(type_info.get("rowMajor", False)),
                "flags": _nonnegative(type_info.get("flags", 0), 0, "flags"),
                "pointerTypeID": _nonnegative(
                    getattr(shader_type, "pointerTypeID", 0xFFFFFFFF),
                    0xFFFFFFFF, "pointer type ID"),
                "bitFieldOffset": _nonnegative(
                    getattr(constant, "bitFieldOffset", 0), 0,
                    "bit-field offset"),
                "bitFieldSize": _nonnegative(
                    getattr(constant, "bitFieldSize", 0), 0,
                    "bit-field size"),
            })

    _visit(getattr(reflection_block, "variables", []) or [], "", 0, 0)
    leaves.sort(key=lambda item: (
        item["absoluteByteOffset"], item["canonicalPath"], item["name"],
        item["byteSize"], item["baseType"], item["rows"], item["columns"],
        item["elements"], item["arrayByteStride"], item["matrixByteStride"],
        item["rowMajor"], item["flags"], item["pointerTypeID"],
        item["bitFieldOffset"], item["bitFieldSize"]))
    path_counts = {}
    for leaf in leaves:
        path = leaf["canonicalPath"]
        path_counts[path] = path_counts.get(path, 0) + 1
    ambiguous_paths = set(
        path for path, count in path_counts.items() if count > 1)
    if ambiguous_paths:
        # A canonical path is the field-alias identity. Never invent an ordinal
        # for degraded reflection such as several unrelated leaves all named
        # ``unknown``: that would make aliases appear deterministic while they
        # could bind to a different physical field in another RDC. Keep the
        # Shader/ABI inventory, but remove every member of each ambiguous path
        # so only demonstrably unique fields remain eligible for alias reuse.
        projection_budget["ambiguousFieldPaths"] = (
            _safe_int(projection_budget.get("ambiguousFieldPaths"), 0) +
            len(ambiguous_paths))
        leaves = [
            leaf for leaf in leaves
            if leaf["canonicalPath"] not in ambiguous_paths]
    return leaves


def _project_shader_index_block(reflection_block, block_index, stage_name,
                                include_fields=False,
                                field_projection_budget=None):
    block = _constant_block_dict(reflection_block, block_index)
    name = str(block.get("name", "") or "").strip()
    path = name or "cbuffer%d" % block_index
    layout = _event_cbuffer_layout(reflection_block, block_index, stage_name)
    physical_interface = _physical_shader_interface({
        "stage": stage_name,
        "entryPoint": "",
        "inputSignature": [],
        "outputSignature": [],
        "readOnlyResources": [],
        "readWriteResources": [],
        "samplers": [],
        "constantBlocks": [block],
        "dynamicLinkageInterfaceCount": 0,
        "outputTopology": "",
        "threadGroupSize": [],
    })
    physical_blocks = physical_interface.get("constantBlocks", [])
    result = {
        "index": block_index,
        "path": path,
        "space": _safe_int(block.get("space"), 0),
        "bind": _safe_int(block.get("bind"), block_index),
        "byteSize": _safe_int(block.get("byteSize"), 0),
        "layoutSha256": _canonical_json_sha256(layout),
        "abiSha256": _canonical_json_sha256(
            physical_blocks[0] if physical_blocks else {}),
    }
    if include_fields:
        if (result["space"] < 0 or result["bind"] < 0 or
                result["byteSize"] <= 0):
            raise _ProjectShaderIndexLimit(
                "shader-resource-index-reflection-block-invalid",
                "Shader reflection contains an invalid CBuffer binding or size")
        if field_projection_budget is None:
            field_projection_budget = {"fields": 0}
        result["name"] = name or path
        result["fields"] = _project_shader_index_block_fields(
            reflection_block, field_projection_budget)
    return result


def _project_shader_anchor_from_usage(ctrl, resource, cancel_event=None,
                                      maximum_records=None):
    """Return the first usable resource-use anchor without replaying any EID."""

    if maximum_records is None:
        maximum_records = MAX_PROJECT_SHADER_INDEX_ANCHOR_USAGE_RECORDS
    maximum_records = max(0, _safe_int(maximum_records, 0))
    if maximum_records == 0:
        return {
            "queried": False,
            "anchorEventId": None,
            "anchorSource": None,
            "usageRecordCount": 0,
            "reasonId": "shader-resource-usage-limit",
        }
    get_usage = getattr(ctrl, "GetUsage", None)
    if not callable(get_usage):
        return {
            "queried": False,
            "anchorEventId": None,
            "anchorSource": None,
            "usageRecordCount": 0,
            "reasonId": "shader-resource-usage-index-unavailable",
        }
    _check_project_shader_index_cancel(cancel_event)
    try:
        usages = get_usage(resource)
    except Exception:
        return {
            "queried": True,
            "anchorEventId": None,
            "anchorSource": None,
            "usageRecordCount": 0,
            "reasonId": "shader-resource-usage-query-failed",
        }
    # GetUsage is called once per unique Shader ResourceId by the inventory
    # caller.  Its result can contain a very large frame-wide use list, but a
    # representative EID only needs the first valid record.  Bound malformed
    # prefixes independently from the aggregate inventory budget so a corrupt
    # or surprising use index cannot turn project restore into an EID scan.
    scan_limit = min(
        maximum_records,
        MAX_PROJECT_SHADER_INDEX_ANCHOR_PREFIX_SCAN_RECORDS,
    )
    count = 0
    for usage in usages or []:
        count += 1
        event_id = _safe_int(
            getattr(usage, "eventId", getattr(usage, "eventID", 0)), 0)
        if 0 < event_id <= 0xFFFFFFFF:
            _check_project_shader_index_cancel(cancel_event)
            return {
                "queried": True,
                "anchorEventId": event_id,
                "anchorSource": "resource-usage-index",
                "usageRecordCount": count,
                "reasonId": "",
            }
        if count >= scan_limit:
            _check_project_shader_index_cancel(cancel_event)
            return {
                "queried": True,
                "anchorEventId": None,
                "anchorSource": None,
                "usageRecordCount": count,
                "reasonId": "shader-resource-usage-limit",
            }
    _check_project_shader_index_cancel(cancel_event)
    return {
        "queried": True,
        "anchorEventId": None,
        "anchorSource": None,
        "usageRecordCount": count,
        "reasonId": "shader-resource-anchor-unavailable",
    }


def _publish_project_shader_index_progress(progress_callback, current, total,
                                           resource_id, entry_count):
    if progress_callback is None:
        return
    progress_callback({
        "phase": "index-unique-shader-resources",
        "processedResourceCount": int(current),
        "totalResourceCount": int(total),
        "resourceId": int(resource_id) if resource_id else None,
        "inspectedEntryPointCount": int(entry_count),
        "eventTraversalCount": 0,
    })


def _project_shader_index_captured_reflection(reflection, entry, resource_id, request, api):
    """Inventory captured bytes, proving any transparent live replacement first."""
    owner = _shared_shader_replacements.get(resource_id)
    if owner is None:
        return reflection, None
    capture_token = _current_capture_token()
    if (capture_token is None or
            owner.get("captureSessionId") != request["captureSessionId"] or
            owner.get("captureSessionId") != _capture_session_id or
            owner.get("captureToken") != capture_token or
            _shared_shader_replacement_capture_token != capture_token or
            owner.get("api") != api or
            _resource_id_int(owner.get("originalResource")) != resource_id):
        raise RuntimeError("Shader inventory replacement owner belongs to another capture")
    stage_name = _project_shader_reflection_stage_name(reflection, entry)
    original = _captured_original_from_shared_owner(
        reflection, {"eventId": 0, "expectedOriginalResourceId": resource_id,
                     "expectedOriginalSha256": owner.get("expectedOriginalSha256")},
        stage_name, str(getattr(entry, "name", "") or ""), owner,
        allow_original_active=api in ("d3d11", "vulkan", "opengl"))
    if _project_shader_reflection_stage_name(original, entry) != stage_name:
        raise RuntimeError("The retained captured-original Shader stage changed")
    return original, owner


def _project_shader_index_dxil_layout(ctrl, reflection, owner):
    # DisassembleShader also resolves replacements, including when handed the
    # original reflection. A verified owner retains its original layout evidence.
    if owner is not None:
        retained = owner.get("capturedDxilLayoutEvidence")
        if not isinstance(retained, dict):
            raise RuntimeError("Captured-original DXIL layout evidence is unavailable")
        return {key: dict(marker) for key, marker in retained.items()}
    unused_access, evidence = _dxil_evidence_from_live_disassembly(
        ctrl, rd.ResourceId(), reflection)
    return evidence


def _iter_expected_project_shader_resource_index(ctrl, request,
                                                 cancel_event=None,
                                                 progress_callback=None):
    _check_project_shader_index_cancel(cancel_event)
    api = ""
    try:
        api = _project_shader_index_api(
            getattr(ctrl.GetAPIProperties(), "pipelineType", ""))
    except Exception:
        api = ""
    _check_project_shader_index_cancel(cancel_event)
    capability = _project_shader_index_capability(api, True)
    if api not in ("d3d11", "d3d12", "opengl", "vulkan"):
        capability = _project_shader_index_capability(
            api, False, "shader-resource-index-api-unsupported")
    elif api != request["api"]:
        capability = _project_shader_index_capability(
            api, False, "shader-resource-index-api-mismatch")
    elif any(not _project_shader_index_format_supported(api, item["encoding"])
             for item in request["shaders"]):
        capability = _project_shader_index_capability(
            api, False, "shader-resource-index-format-unsupported")
    base = {
        "schema": "replaylab-project-shader-resource-index/v2",
        "schemaVersion": 2,
        "capturePath": request["capturePath"],
        "captureSessionId": request["captureSessionId"],
        "captureId": request["captureId"],
        "identityEvidenceSha256": request["identityEvidenceSha256"],
        "requestSha256": request["requestSha256"],
        "capability": capability,
        "matched": False,
        "inventoryOnly": False,
        "inventoryComplete": False,
        "leaseEligible": True,
        "reasonId": capability["reasonId"],
        "expectedShaderCount": len(request["shaders"]),
        "matchedShaderCount": 0,
        "scannedResourceCount": 0,
        "shaderResourceCount": 0,
        "uniqueShaderResourceCount": 0,
        "processedShaderResourceCount": 0,
        "indexedShaderResourceCount": 0,
        "unindexedShaderResourceCount": 0,
        "unindexedShaderResourceIds": [],
        "inspectedEntryPointCount": 0,
        "anchorQueryCount": 0,
        "anchorUsageRecordCount": 0,
        "assets": [],
        "rawBytecodeBlobs": [],
        "diagnostics": [],
        "eventTraversalCount": 0,
        "fullFrameTraversal": False,
        "gpuReplayMutation": False,
        "physicalApplyAuthority": False,
        "resourceOwnershipScope": "target-capture-session",
        "crossCaptureResourceIdReuse": False,
    }
    if not capability["supported"]:
        return base

    try:
        _check_project_shader_index_cancel(cancel_event)
        resources = _project_shader_index_sequence(
            ctrl.GetResources(), MAX_PROJECT_SHADER_INDEX_RESOURCES,
            "shader-resource-index-resource-limit", "resource-count")
        _check_project_shader_index_cancel(cancel_event)
    except _ProjectShaderIndexLimit as exc:
        base["reasonId"] = exc.reason_id
        return base
    base["scannedResourceCount"] = len(resources)
    by_id = {}
    shader_count = 0
    duplicate_ids = set()
    wanted_ids = set(item["resourceId"] for item in request["shaders"])
    for description in resources:
        _check_project_shader_index_cancel(cancel_event)
        if not _project_shader_resource_type(description):
            continue
        shader_count += 1
        resource = getattr(description, "resourceId", description)
        resource_id = _resource_id_int(resource)
        if resource_id not in wanted_ids:
            continue
        if resource_id in by_id:
            duplicate_ids.add(resource_id)
        # Persist only the numeric identity across replay callbacks. The
        # ReplayController and every SWIG value returned from it are scoped to
        # the current InvokeCallback and must never be cached by the job.
        by_id[resource_id] = resource_id
    base["shaderResourceCount"] = shader_count
    base["uniqueShaderResourceCount"] = len(by_id)
    if duplicate_ids:
        base["reasonId"] = "shader-resource-index-ambiguous"
        base["diagnostics"].append({
            "code": "duplicate-shader-resource-id",
            "resourceIds": sorted(duplicate_ids),
        })
        return base

    expected_by_owner = {}
    for expected in request["shaders"]:
        expected_by_owner.setdefault(expected["resourceId"], []).append(expected)

    resources = None
    description = None
    resource = None

    inspected_entries = 0
    total_blocks = 0
    reflection_budget = _new_project_shader_reflection_budget()
    owner_content_index = {}
    owner_module_index = {}
    expected_owners = sorted(expected_by_owner.items())
    _publish_project_shader_index_progress(
        progress_callback, 0, len(expected_owners), 0, 0)
    for owner_position, (resource_id, expected_values) in enumerate(
            expected_owners, 1):
        _check_project_shader_index_cancel(cancel_event)
        if resource_id not in by_id:
            for expected in expected_values:
                base["diagnostics"].append({
                    "code": "shader-resource-absent",
                    "resourceId": resource_id,
                    "stage": expected["stage"],
                })
            base["processedShaderResourceCount"] = owner_position
            _publish_project_shader_index_progress(
                progress_callback, owner_position, len(expected_owners),
                resource_id, inspected_entries)
            ctrl = None
            ctrl = yield None
            continue
        resource = _resolve_resource_id(ctrl, resource_id)
        entries = None
        entry = None
        reflection = None
        reflected_blocks = None
        reflected_block = None
        try:
            _check_project_shader_index_cancel(cancel_event)
            entries = _project_shader_index_sequence(
                ctrl.GetShaderEntryPoints(resource),
                MAX_PROJECT_SHADER_INDEX_ENTRIES - inspected_entries,
                "shader-resource-index-entry-limit", "entry-point-count")
            _check_project_shader_index_cancel(cancel_event)
        except _ProjectShaderIndexLimit as exc:
            base["reasonId"] = exc.reason_id
            base["inspectedEntryPointCount"] = inspected_entries
            return base
        except Exception:
            # A capture can contain driver/internal Shader resources whose
            # entry-point metadata cannot be represented by this RenderDoc
            # build (for example an unknown future ShaderStage enum).  This
            # resource has no complete stable key and therefore can never be
            # selected for executable reuse, but it must not abort discovery
            # of every other physical Shader in the capture.
            base["diagnostics"].append({
                "code": "shader-entry-points-unavailable",
                "resourceId": resource_id,
            })
            base["processedShaderResourceCount"] = owner_position
            _publish_project_shader_index_progress(
                progress_callback, owner_position, len(expected_owners),
                resource_id, inspected_entries)
            resource = None
            entries = None
            ctrl = None
            ctrl = yield None
            continue
        inspected_entries += len(entries)
        wanted_modules = set(
            (item["stage"], item["entryPoint"], item["encoding"], item["rawSha256"])
            for item in expected_values)
        for entry in entries:
            _check_project_shader_index_cancel(cancel_event)
            entry_name = str(getattr(entry, "name", "") or "")
            if not any(item["entryPoint"] == entry_name for item in expected_values):
                continue
            _check_project_shader_index_cancel(cancel_event)
            reflection = ctrl.GetShader(rd.ResourceId(), resource, entry)
            _check_project_shader_index_cancel(cancel_event)
            if reflection is None:
                continue
            try:
                reflection, replacement_owner = _project_shader_index_captured_reflection(
                    reflection, entry, resource_id, request, api)
            except RuntimeError as exc:
                base["diagnostics"].append({
                    "code": "shader-replacement-original-unavailable",
                    "resourceId": resource_id, "entryPoint": entry_name,
                    "message": str(exc),
                })
                continue
            stage_name = _project_shader_reflection_stage_name(reflection, entry)
            if not stage_name:
                base["diagnostics"].append({
                    "code": "shader-stage-unavailable",
                    "resourceId": resource_id,
                    "entryPoint": entry_name,
                })
                continue
            reflected_entry = str(
                getattr(reflection, "entryPoint", "") or entry_name)
            encoding = _project_shader_index_encoding(
                getattr(reflection, "encoding", ""))
            raw_bytes = _shader_raw_bytes(reflection)
            raw_sha256 = hashlib.sha256(raw_bytes).hexdigest() if raw_bytes else ""
            module_key = (stage_name, reflected_entry, encoding, raw_sha256)
            if module_key not in wanted_modules:
                continue
            try:
                reflected_blocks = _validate_project_shader_reflection_budget(
                    reflection, reflection_budget)
                total_blocks += len(reflected_blocks)
                if total_blocks > MAX_PROJECT_SHADER_INDEX_BLOCKS:
                    raise _ProjectShaderIndexLimit(
                        "shader-resource-index-block-limit",
                        "Shader reflection exceeds the constant-block limit")
                dxil_layout_evidence = None
                if encoding == "dxil":
                    _check_project_shader_index_cancel(cancel_event)
                    try:
                        dxil_layout_evidence = _project_shader_index_dxil_layout(
                            ctrl, reflection, replacement_owner)
                    except Exception:
                        dxil_layout_evidence = _dxil_layout_evidence_for_all_blocks(
                            reflection, "unavailable")
                    _check_project_shader_index_cancel(cancel_event)
                compiled = _compiled_shader_interface(
                    reflection, dxil_layout_evidence)
                _check_project_shader_index_cancel(cancel_event)
                compiled["stage"] = stage_name
                compiled["entryPoint"] = reflected_entry
                compiled["encoding"] = encoding
                interface_sha256, layout_sha256 = _project_symbol_hashes(compiled)
                interface_complete = bool(
                    compiled.get("interfaceComplete", False))
                blocks = []
                for block_index, reflected_block in enumerate(reflected_blocks):
                    _check_project_shader_index_cancel(cancel_event)
                    blocks.append(_project_shader_index_block(
                        reflected_block, block_index, stage_name))
            except _ProjectShaderIndexLimit as exc:
                base["reasonId"] = exc.reason_id
                base["inspectedEntryPointCount"] = inspected_entries
                base["diagnostics"].append({
                    "code": exc.reason_id,
                    "resourceId": resource_id,
                    "stage": stage_name,
                })
                return base
            blocks.sort(key=lambda item: (
                item["space"], item["bind"], item["index"], item["path"]))
            physical_abi_sha256 = (
                "" if api == "vulkan" else
                _physical_shader_interface_sha256(
                    reflection, dxil_layout_evidence))
            abi_hash = physical_abi_sha256 or interface_sha256
            stable_identity = _project_shader_stable_identity(
                api, encoding, raw_sha256, stage_name, reflected_entry,
                abi_hash, layout_sha256,
                api != "vulkan" and interface_complete and
                bool(physical_abi_sha256))
            candidate = {
                "resourceId": resource_id,
                "ownerResourceId": resource_id,
                "ownerCaptureSessionId": request["captureSessionId"],
                "resourceOwnershipScope": "target-capture-session",
                "crossCaptureResourceIdReuse": False,
                "stage": stage_name,
                "entryPoint": reflected_entry,
                "api": api,
                "encoding": encoding,
                "rawSha256": raw_sha256,
                "rawSize": len(raw_bytes),
                "abiHash": abi_hash,
                "interfaceHash": interface_sha256,
                "layoutHash": layout_sha256,
                "interfaceComplete": interface_complete,
                "interfaceEvidence": (
                    "module-only-null-pipeline" if api == "vulkan" else
                    "null-pipeline-reflection"),
                "physicalAbiSha256": physical_abi_sha256,
                "physicalAbiValidated": api != "vulkan",
                "constantBlocks": blocks,
                "requiresAnchorPreflight": True,
            }
            candidate.update(stable_identity)
            content_key = (
                api, encoding, stage_name, reflected_entry, raw_sha256,
                interface_sha256, layout_sha256, interface_complete)
            owner_content_index.setdefault(
                (resource_id, content_key), []).append(candidate)
            owner_module_index.setdefault(
                (resource_id, module_key), []).append(candidate)
        base["processedShaderResourceCount"] = owner_position
        _publish_project_shader_index_progress(
            progress_callback, owner_position, len(expected_owners),
            resource_id, inspected_entries)
        resource = None
        entries = None
        entry = None
        reflection = None
        reflected_blocks = None
        reflected_block = None
        ctrl = None
        ctrl = yield None

    assets = []
    for expected in request["shaders"]:
        _check_project_shader_index_cancel(cancel_event)
        expected_layout_hash = expected["layoutHash"]
        if not expected_layout_hash and not expected["constantBlocks"]:
            expected_layout_hash = _canonical_json_sha256([])
        content_key = (
            api, expected["encoding"], expected["stage"],
            expected["entryPoint"], expected["rawSha256"],
            expected["interfaceHash"], expected_layout_hash,
            expected["interfaceComplete"])
        module_key = (
            expected["stage"], expected["entryPoint"],
            expected["encoding"], expected["rawSha256"])
        matching = list((owner_module_index if api == "vulkan" else
                         owner_content_index).get(
            (expected["resourceId"],
             module_key if api == "vulkan" else content_key), []))
        exact = []
        for candidate in matching:
            _check_project_shader_index_cancel(cancel_event)
            block_match = candidate["constantBlocks"] == expected["constantBlocks"]
            interface_match = (
                candidate["interfaceHash"] == expected["interfaceHash"] and
                candidate["layoutHash"] == expected_layout_hash and
                candidate["interfaceComplete"] == expected["interfaceComplete"])
            if api != "vulkan" and (not block_match or not interface_match):
                continue
            if (expected.get("abiHash") and
                    candidate["abiHash"] != expected["abiHash"]):
                continue
            if (expected.get("stableKeySha256") and
                    candidate["stableKeySha256"] !=
                    expected["stableKeySha256"]):
                continue
            selected = dict(candidate)
            selected["anchorEventId"] = expected["anchorEventId"] or None
            selected["anchorSource"] = (
                "rdc-project-association"
                if expected["anchorEventId"] > 0 else None)
            selected["constantBlocksMatched"] = block_match
            selected["interfaceMatched"] = interface_match
            selected["exactExecutableMatchEligible"] = bool(
                selected["stableKeyComplete"] and
                selected["anchorEventId"] is not None)
            selected["contentMatchMode"] = (
                "module-sha256-owner-rid-anchor-preflight" if api == "vulkan" else
                "stable-key-owner-rid")
            exact.append(selected)
        if len(exact) != 1:
            base["diagnostics"].append({
                "code": (
                    "shader-identity-ambiguous" if len(exact) > 1 else
                    "shader-identity-mismatch"),
                "resourceId": expected["resourceId"],
                "stage": expected["stage"],
                "entryPoint": expected["entryPoint"],
            })
            continue
        assets.append(exact[0])

    base["inspectedEntryPointCount"] = inspected_entries
    base["assets"] = sorted(assets, key=lambda item: (
        item["resourceId"], item["stage"], item["entryPoint"],
        item["rawSha256"]))
    indexed_resource_ids = set(item["resourceId"] for item in base["assets"])
    base["indexedShaderResourceCount"] = len(indexed_resource_ids)
    base["unindexedShaderResourceIds"] = sorted(
        set(by_id.keys()) - indexed_resource_ids)
    base["unindexedShaderResourceCount"] = len(
        base["unindexedShaderResourceIds"])
    base["matchedShaderCount"] = len(base["assets"])
    if len(base["assets"]) != len(request["shaders"]):
        if not base["reasonId"]:
            base["reasonId"] = "shader-resource-index-mismatch"
        return base

    _check_project_shader_index_cancel(cancel_event)
    evidence = {
        "api": api,
        "shaders": [
            {
                "resourceId": item["resourceId"],
                "stage": item["stage"],
                "entryPoint": item["entryPoint"],
                "encoding": item["encoding"],
                "rawSha256": item["rawSha256"],
                "abiHash": item["abiHash"],
                "interfaceHash": item["interfaceHash"],
                "layoutHash": item["layoutHash"],
                "stableKeySha256": item["stableKeySha256"],
                "stableKeyComplete": item["stableKeyComplete"],
                "interfaceComplete": item["interfaceComplete"],
                "physicalAbiSha256": item["physicalAbiSha256"],
                "physicalAbiValidated": item["physicalAbiValidated"],
                "requiresAnchorPreflight": item["requiresAnchorPreflight"],
                "constantBlocks": [
                    {
                        "space": block["space"],
                        "bind": block["bind"],
                        "index": block["index"],
                        "path": block["path"],
                        "byteSize": block["byteSize"],
                        "layoutSha256": block["layoutSha256"],
                        "abiSha256": block["abiSha256"],
                    }
                    for block in item["constantBlocks"]
                ],
            }
            for item in base["assets"]
        ],
    }
    resource_inventory = {
        "api": api,
        "shaders": [
            {
                "resourceId": item["resourceId"],
                "stableKeySha256": item["stableKeySha256"],
                "anchorEventId": item["anchorEventId"],
                "constantBlocks": item["constantBlocks"],
            }
            for item in base["assets"]
        ],
    }
    base["resourceInventorySha256"] = hashlib.sha256(
        _canonical_project_index_bytes(resource_inventory)).hexdigest()
    stable_resource_keys = sorted(set(
        item["stableKeySha256"] for item in base["assets"]))
    base["stableResourceSetSha256"] = hashlib.sha256(
        _canonical_project_index_bytes(stable_resource_keys)).hexdigest()
    base["liveIdentitySha256"] = hashlib.sha256(
        _canonical_project_index_bytes(evidence)).hexdigest()
    _check_project_shader_index_cancel(cancel_event)
    base["matched"] = True
    base["reasonId"] = ""
    encoded = _canonical_project_index_bytes(base)
    if len(encoded) > MAX_PROJECT_SHADER_INDEX_BYTES:
        base["matched"] = False
        base["reasonId"] = "shader-resource-index-response-limit"
        base["assets"] = []
        base["matchedShaderCount"] = 0
        base.pop("liveIdentitySha256", None)
    return base


def _consume_project_shader_resource_index_steps(steps, ctrl):
    """Run a sliced builder synchronously and return its final inventory."""

    started = False
    while True:
        try:
            if started:
                steps.send(ctrl)
            else:
                next(steps)
                started = True
        except StopIteration as stopped:
            return stopped.value


def _build_expected_project_shader_resource_index(ctrl, request,
                                                  cancel_event=None,
                                                  progress_callback=None):
    """Compatibility wrapper for callers that need a synchronous result."""

    return _consume_project_shader_resource_index_steps(
        _iter_expected_project_shader_resource_index(
            ctrl, request, cancel_event=cancel_event,
            progress_callback=progress_callback), ctrl)


def _iter_all_project_shader_resource_index(ctrl, request, cancel_event=None,
                                            progress_callback=None):
    """Inventory each physical Shader ResourceId once, without EID replay."""

    _check_project_shader_index_cancel(cancel_event)
    try:
        api = _project_shader_index_api(
            getattr(ctrl.GetAPIProperties(), "pipelineType", ""))
    except Exception:
        api = ""
    supported_api = api in ("d3d11", "d3d12", "opengl", "vulkan")
    capability = _project_shader_index_capability(
        api, supported_api,
        "" if supported_api else "shader-resource-index-api-unsupported")
    if supported_api and request.get("api") and api != request["api"]:
        capability = _project_shader_index_capability(
            api, False, "shader-resource-index-api-mismatch")
    base = {
        "schema": "replaylab-project-shader-resource-index/v2",
        "schemaVersion": 2,
        "capturePath": request["capturePath"],
        "captureSessionId": request["captureSessionId"],
        "captureId": request["captureId"],
        "identityEvidenceSha256": request["identityEvidenceSha256"],
        "requestSha256": request["requestSha256"],
        "capability": capability,
        "matched": False,
        "inventoryOnly": True,
        "inventoryComplete": False,
        "leaseEligible": False,
        "reasonId": capability["reasonId"],
        "expectedShaderCount": len(request["shaders"]),
        "matchedShaderCount": 0,
        "scannedResourceCount": 0,
        "shaderResourceCount": 0,
        "uniqueShaderResourceCount": 0,
        "processedShaderResourceCount": 0,
        "indexedShaderResourceCount": 0,
        "unindexedShaderResourceCount": 0,
        "unindexedShaderResourceIds": [],
        "inspectedEntryPointCount": 0,
        "anchorQueryCount": 0,
        "anchorUsageRecordCount": 0,
        "representativeEidCount": 0,
        "anchorPerShaderMaximum": 1,
        "rawBytecodeIncludedBytes": 0,
        "rawBytecodeOmittedCount": 0,
        "rawBytecodeBlobs": [],
        "assets": [],
        "diagnostics": [],
        "eventTraversalCount": 0,
        "fullFrameTraversal": False,
        "gpuReplayMutation": False,
        "physicalApplyAuthority": False,
        "resourceOwnershipScope": "target-capture-session",
        "crossCaptureResourceIdReuse": False,
    }
    target_raw_hashes = set(request.get("targetRawSha256s", []))
    filtered_resource_ids = set()
    raw_unavailable_resource_ids = set()
    target_matched_resource_ids = set()
    observed_target_hashes = set()
    if target_raw_hashes:
        base.update({
            "inventoryScope": "target-raw-sha256",
            "rawHashPurpose": "captured-executable-identity",
            "semanticEquivalenceVerified": False,
            "targetRawSha256s": sorted(target_raw_hashes),
            "scanComplete": False,
            "targetInventoryComplete": False,
            "rawIdentitySearchComplete": False,
            "rawIdentityUnavailableShaderResourceIds": [],
            "filteredOutShaderResourceCount": 0,
            "filteredOutShaderResourceIds": [],
            "targetMatchedShaderResourceIds": [],
            "observedTargetRawSha256s": [],
            "unobservedTargetRawSha256s": sorted(target_raw_hashes),
        })
    if not capability["supported"]:
        return base

    try:
        resources = _project_shader_index_sequence(
            ctrl.GetResources(), MAX_PROJECT_SHADER_INDEX_RESOURCES,
            "shader-resource-index-resource-limit", "resource-count")
    except _ProjectShaderIndexLimit as exc:
        base["reasonId"] = exc.reason_id
        return base
    base["scannedResourceCount"] = len(resources)
    by_id = {}
    duplicate_ids = set()
    invalid_resource_ids = 0
    for description in resources:
        _check_project_shader_index_cancel(cancel_event)
        if not _project_shader_resource_type(description):
            continue
        resource = getattr(description, "resourceId", description)
        resource_id = _resource_id_int(resource)
        if resource_id <= 0:
            invalid_resource_ids += 1
            continue
        if resource_id in by_id:
            duplicate_ids.add(resource_id)
        else:
            by_id[resource_id] = resource_id
    base["shaderResourceCount"] = len(by_id) + len(duplicate_ids)
    base["uniqueShaderResourceCount"] = len(by_id)
    if invalid_resource_ids:
        base["diagnostics"].append({
            "code": "invalid-shader-resource-id",
            "count": invalid_resource_ids,
        })
        if target_raw_hashes:
            base["reasonId"] = "shader-resource-index-invalid-resource-id"
            return base
    if duplicate_ids:
        base["reasonId"] = "shader-resource-index-ambiguous"
        base["diagnostics"].append({
            "code": "duplicate-shader-resource-id",
            "resourceIds": sorted(duplicate_ids),
        })
        return base

    resources = None
    description = None
    resource = None

    supplied_anchors = {}
    for expected in request["shaders"]:
        if expected["anchorEventId"] > 0:
            supplied_anchors[expected["resourceId"]] = expected["anchorEventId"]

    reflection_budget = _new_project_shader_reflection_budget()
    field_projection_budget = {"fields": 0}
    total_blocks = 0
    inspected_entries = 0
    raw_blob_bytes = 0
    raw_blobs = {}
    omitted_raw_hashes = set()
    assets = []
    representative_eids = set()
    ordered_resources = sorted(by_id)
    _publish_project_shader_index_progress(
        progress_callback, 0, len(ordered_resources), 0, 0)
    for resource_position, resource_id in enumerate(
            ordered_resources, 1):
        _check_project_shader_index_cancel(cancel_event)
        resource = _resolve_resource_id(ctrl, resource_id)
        entries = None
        entry = None
        reflection = None
        reflected_blocks = None
        reflected_block = None
        anchor_event_id = supplied_anchors.get(resource_id)
        anchor_source = (
            "rdc-project-association" if anchor_event_id is not None else None)

        try:
            entries = _project_shader_index_sequence(
                ctrl.GetShaderEntryPoints(resource),
                MAX_PROJECT_SHADER_INDEX_ENTRIES - inspected_entries,
                "shader-resource-index-entry-limit", "entry-point-count")
        except _ProjectShaderIndexLimit as exc:
            base["reasonId"] = exc.reason_id
            base["inspectedEntryPointCount"] = inspected_entries
            return base
        except Exception:
            # Fail closed for this resource only. With no trustworthy Stage or
            # EntryPoint it cannot form the exact seven-field project key, but
            # the remaining unique Shader resources are still safe to index.
            base["diagnostics"].append({
                "code": "shader-entry-points-unavailable",
                "resourceId": resource_id,
            })
            if target_raw_hashes:
                raw_unavailable_resource_ids.add(resource_id)
            base["processedShaderResourceCount"] = resource_position
            _publish_project_shader_index_progress(
                progress_callback, resource_position, len(ordered_resources),
                resource_id, inspected_entries)
            resource = None
            entries = None
            ctrl = None
            ctrl = yield None
            continue
        inspected_entries += len(entries)
        resource_raw_complete = bool(entries)
        if not entries:
            base["diagnostics"].append({
                "code": "shader-entry-points-unavailable",
                "resourceId": resource_id,
            })
        resource_assets = []
        identity_positions = {}
        for entry in entries:
            _check_project_shader_index_cancel(cancel_event)
            entry_name = str(getattr(entry, "name", "") or "")
            try:
                reflection = ctrl.GetShader(rd.ResourceId(), resource, entry)
            except Exception:
                reflection = None
            _check_project_shader_index_cancel(cancel_event)
            if reflection is None:
                resource_raw_complete = False
                base["diagnostics"].append({
                    "code": "shader-reflection-unavailable",
                    "resourceId": resource_id,
                    "entryPoint": entry_name,
                })
                continue
            try:
                reflection, replacement_owner = _project_shader_index_captured_reflection(
                    reflection, entry, resource_id, request, api)
            except RuntimeError as exc:
                resource_raw_complete = False
                base["diagnostics"].append({
                    "code": "shader-replacement-original-unavailable",
                    "resourceId": resource_id, "entryPoint": entry_name,
                    "message": str(exc),
                })
                continue
            # The requested bytes are read from this current capture's real
            # reflection. Do not disassemble/compute ABI/GetUsage for another
            # Shader merely to decide that its raw SHA is not a target.
            if target_raw_hashes:
                raw_bytes = _shader_raw_bytes(reflection)
                raw_sha256 = hashlib.sha256(raw_bytes).hexdigest() if raw_bytes else ""
                if not raw_sha256:
                    resource_raw_complete = False
                    base["diagnostics"].append({
                        "code": "shader-raw-bytes-unavailable",
                        "resourceId": resource_id,
                        "entryPoint": entry_name,
                    })
                    continue
                if raw_sha256 not in target_raw_hashes:
                    continue
                observed_target_hashes.add(raw_sha256)
                target_matched_resource_ids.add(resource_id)
            stage_name = _project_shader_reflection_stage_name(reflection, entry)
            if not stage_name:
                base["diagnostics"].append({
                    "code": "shader-stage-unavailable",
                    "resourceId": resource_id,
                    "entryPoint": entry_name,
                })
                continue
            reflected_entry = str(
                getattr(reflection, "entryPoint", "") or entry_name)
            if entry_name and reflected_entry != entry_name:
                base["diagnostics"].append({
                    "code": "shader-reflection-entry-mismatch",
                    "resourceId": resource_id,
                    "entryPoint": entry_name,
                    "reflectedEntryPoint": reflected_entry,
                })
                continue
            encoding = _project_shader_index_encoding(
                getattr(reflection, "encoding", ""))
            format_supported = _project_shader_index_format_supported(
                api, encoding)
            raw_bytes = _shader_raw_bytes(reflection)
            raw_sha256 = (
                hashlib.sha256(raw_bytes).hexdigest() if raw_bytes else "")
            try:
                reflected_blocks = _validate_project_shader_reflection_budget(
                    reflection, reflection_budget)
                total_blocks += len(reflected_blocks)
                if total_blocks > MAX_PROJECT_SHADER_INDEX_BLOCKS:
                    raise _ProjectShaderIndexLimit(
                        "shader-resource-index-block-limit",
                        "Shader reflection exceeds the constant-block limit")
                dxil_layout_evidence = None
                if encoding == "dxil":
                    try:
                        dxil_layout_evidence = _project_shader_index_dxil_layout(
                            ctrl, reflection, replacement_owner)
                    except Exception:
                        dxil_layout_evidence = _dxil_layout_evidence_for_all_blocks(
                            reflection, "unavailable")
                    _check_project_shader_index_cancel(cancel_event)
                compiled = _compiled_shader_interface(
                    reflection, dxil_layout_evidence)
                compiled["stage"] = stage_name
                compiled["entryPoint"] = reflected_entry
                compiled["encoding"] = encoding
                interface_sha256, layout_sha256 = _project_symbol_hashes(compiled)
                interface_complete = bool(
                    compiled.get("interfaceComplete", False))
                ambiguous_field_paths_before = _safe_int(
                    field_projection_budget.get("ambiguousFieldPaths"), 0)
                blocks = [
                    _project_shader_index_block(
                        reflected_block, block_index, stage_name,
                        include_fields=True,
                        field_projection_budget=field_projection_budget)
                    for block_index, reflected_block in enumerate(reflected_blocks)
                ]
                ambiguous_field_path_count = (
                    _safe_int(
                        field_projection_budget.get("ambiguousFieldPaths"), 0) -
                    ambiguous_field_paths_before)
            except _ProjectShaderIndexLimit as exc:
                base["reasonId"] = exc.reason_id
                base["inspectedEntryPointCount"] = inspected_entries
                base["diagnostics"].append({
                    "code": exc.reason_id,
                    "resourceId": resource_id,
                    "stage": stage_name,
                    "entryPoint": reflected_entry,
                })
                return base
            blocks.sort(key=lambda item: (
                item["space"], item["bind"], item["index"], item["path"]))
            if ambiguous_field_path_count:
                base["diagnostics"].append({
                    "code": "shader-cbuffer-field-path-ambiguous",
                    "resourceId": resource_id,
                    "stage": stage_name,
                    "entryPoint": reflected_entry,
                    "count": ambiguous_field_path_count,
                })
            physical_abi_sha256 = (
                "" if api == "vulkan" else
                _physical_shader_interface_sha256(
                    reflection, dxil_layout_evidence))
            abi_hash = physical_abi_sha256 or interface_sha256
            stable_identity = _project_shader_stable_identity(
                api, encoding, raw_sha256, stage_name, reflected_entry,
                abi_hash, layout_sha256,
                format_supported and api != "vulkan" and
                interface_complete and bool(physical_abi_sha256))
            raw_included = False
            if raw_sha256 in raw_blobs:
                raw_included = True
            elif (raw_bytes and
                    len(raw_bytes) <= MAX_PROJECT_SHADER_INDEX_RAW_BYTES_PER_ASSET and
                    raw_blob_bytes + len(raw_bytes) <=
                    MAX_PROJECT_SHADER_INDEX_RAW_BYTES):
                raw_blobs[raw_sha256] = {
                    "sha256": raw_sha256,
                    "size": len(raw_bytes),
                    "encoding": "base64",
                    "data": base64.b64encode(raw_bytes).decode("ascii"),
                }
                raw_blob_bytes += len(raw_bytes)
                raw_included = True
            elif raw_sha256 and raw_sha256 not in omitted_raw_hashes:
                omitted_raw_hashes.add(raw_sha256)
                base["diagnostics"].append({
                    "code": "shader-raw-bytecode-response-budget",
                    "resourceId": resource_id,
                    "rawSha256": raw_sha256,
                    "rawSize": len(raw_bytes),
                })
            candidate = {
                "resourceId": resource_id,
                "ownerResourceId": resource_id,
                "ownerCaptureSessionId": request["captureSessionId"],
                "resourceOwnershipScope": "target-capture-session",
                "crossCaptureResourceIdReuse": False,
                "stage": stage_name,
                "entryPoint": reflected_entry,
                "api": api,
                "encoding": encoding,
                "rawSha256": raw_sha256,
                "rawSize": len(raw_bytes),
                "rawBytecodeIncluded": raw_included,
                "abiHash": abi_hash,
                "interfaceHash": interface_sha256,
                "layoutHash": layout_sha256,
                "interfaceComplete": interface_complete,
                "interfaceEvidence": (
                    "module-only-null-pipeline" if api == "vulkan" else
                    "null-pipeline-reflection"),
                "physicalAbiSha256": physical_abi_sha256,
                "physicalAbiValidated": api != "vulkan",
                "constantBlocks": blocks,
                "anchorEventId": anchor_event_id,
                "anchorSource": anchor_source,
                "requiresAnchorPreflight": True,
                "identityAmbiguous": False,
                "formatSupported": format_supported,
            }
            candidate.update(stable_identity)
            candidate["exactExecutableMatchEligible"] = bool(
                candidate["stableKeyComplete"] and
                candidate["anchorEventId"] is not None)
            identity_key = (
                stage_name, reflected_entry, encoding, raw_sha256)
            if identity_key in identity_positions:
                candidate["identityAmbiguous"] = True
                candidate["exactExecutableMatchEligible"] = False
                resource_assets[identity_positions[identity_key]][
                    "identityAmbiguous"] = True
                resource_assets[identity_positions[identity_key]][
                    "exactExecutableMatchEligible"] = False
                base["diagnostics"].append({
                    "code": "shader-entry-identity-ambiguous",
                    "resourceId": resource_id,
                    "stage": stage_name,
                    "entryPoint": reflected_entry,
                })
            else:
                identity_positions[identity_key] = len(resource_assets)
            resource_assets.append(candidate)
        # A representative EID exists only to validate a Shader identity that
        # is already eligible for project matching.  Driver/internal resources
        # with no representable Stage/EntryPoint never trigger GetUsage and
        # therefore cannot inflate the representative-EID proof.
        if (resource_assets and anchor_event_id is None and
                request["discoverAnchorEids"]):
            anchor = _project_shader_anchor_from_usage(
                ctrl, resource, cancel_event=cancel_event,
                maximum_records=(
                    MAX_PROJECT_SHADER_INDEX_ANCHOR_USAGE_RECORDS -
                    base["anchorUsageRecordCount"]))
            if anchor["queried"]:
                base["anchorQueryCount"] += 1
            base["anchorUsageRecordCount"] += anchor["usageRecordCount"]
            anchor_event_id = anchor["anchorEventId"]
            anchor_source = anchor["anchorSource"]
            if anchor["reasonId"] and anchor["reasonId"] != \
                    "shader-resource-anchor-unavailable":
                base["diagnostics"].append({
                    "code": anchor["reasonId"],
                    "resourceId": resource_id,
                })
        if resource_assets:
            if anchor_event_id is not None:
                representative_eids.add((resource_id, anchor_event_id))
            for candidate in resource_assets:
                candidate["anchorEventId"] = anchor_event_id
                candidate["anchorSource"] = anchor_source
                candidate["exactExecutableMatchEligible"] = bool(
                    candidate["stableKeyComplete"] and
                    candidate["anchorEventId"] is not None and
                    not candidate["identityAmbiguous"])
        assets.extend(resource_assets)
        if target_raw_hashes:
            if not resource_raw_complete:
                raw_unavailable_resource_ids.add(resource_id)
            elif resource_id not in target_matched_resource_ids:
                filtered_resource_ids.add(resource_id)
        base["processedShaderResourceCount"] = resource_position
        _publish_project_shader_index_progress(
            progress_callback, resource_position, len(ordered_resources),
            resource_id, inspected_entries)
        resource = None
        entries = None
        entry = None
        reflection = None
        reflected_blocks = None
        reflected_block = None
        ctrl = None
        ctrl = yield None

    base["inspectedEntryPointCount"] = inspected_entries
    base["representativeEidCount"] = len(representative_eids)
    base["rawBytecodeIncludedBytes"] = raw_blob_bytes
    base["rawBytecodeOmittedCount"] = len(omitted_raw_hashes)
    base["rawBytecodeBlobs"] = sorted(
        raw_blobs.values(), key=lambda item: item["sha256"])
    base["assets"] = sorted(assets, key=lambda item: (
        item["resourceId"], item["stage"], item["entryPoint"],
        item["rawSha256"]))
    indexed_resource_ids = set(item["resourceId"] for item in base["assets"])
    base["indexedShaderResourceCount"] = len(indexed_resource_ids)
    base["unindexedShaderResourceIds"] = sorted(
        set(by_id.keys()) - indexed_resource_ids - filtered_resource_ids)
    base["unindexedShaderResourceCount"] = len(
        base["unindexedShaderResourceIds"])
    # This is a discovery count, not a project-match grant. ``matched`` stays
    # false and inventory-only jobs can never be committed as route leases.
    base["matchedShaderCount"] = len(base["assets"])
    evidence = {
        "api": api,
        "shaders": [
            {
                "resourceId": item["resourceId"],
                "stableKeySha256": item["stableKeySha256"],
                "stableKeyComplete": item["stableKeyComplete"],
                "anchorEventId": item["anchorEventId"],
            }
            for item in base["assets"]
        ],
    }
    resource_inventory = {
        "api": api,
        "shaders": [
            {
                "resourceId": item["resourceId"],
                "stableKeySha256": item["stableKeySha256"],
                "anchorEventId": item["anchorEventId"],
                "constantBlocks": item["constantBlocks"],
            }
            for item in base["assets"]
        ],
    }
    base["resourceInventorySha256"] = hashlib.sha256(
        _canonical_project_index_bytes(resource_inventory)).hexdigest()
    base["stableResourceSetSha256"] = hashlib.sha256(
        _canonical_project_index_bytes(sorted(set(
            item["stableKeySha256"] for item in base["assets"])))).hexdigest()
    base["liveIdentitySha256"] = hashlib.sha256(
        _canonical_project_index_bytes(evidence)).hexdigest()
    snapshot_shader_keys = set(
        (item["resourceId"], item["stage"], item["entryPoint"],
         item["rawSha256"])
        for item in base["assets"])
    snapshot_use_keys = set(
        (item["resourceId"], item["stage"], item["entryPoint"],
         item["rawSha256"])
        for item in base["assets"]
        if item["anchorEventId"] is not None)
    base["symbolSnapshotPublished"] = False
    base["symbolSnapshotShaderCount"] = len(snapshot_shader_keys)
    base["symbolSnapshotUseCount"] = len(snapshot_use_keys)
    base["symbolSnapshotCaptureId"] = base["stableResourceSetSha256"]
    base["inventoryComplete"] = True
    base["originalShaderIdentityPolicy"] = "captured-original-owner-v1"
    base["reasonId"] = ""
    if target_raw_hashes:
        # A completed filtered search is not a complete Shader inventory and
        # must never replace the UI's full symbol snapshot or enter its cache.
        base.update({
            "inventoryComplete": False,
            "scanComplete": True,
            "targetInventoryComplete": not bool(
                raw_unavailable_resource_ids or base["unindexedShaderResourceIds"]),
            "rawIdentitySearchComplete": not bool(raw_unavailable_resource_ids),
            "rawIdentityUnavailableShaderResourceIds": sorted(raw_unavailable_resource_ids),
            "filteredOutShaderResourceCount": len(filtered_resource_ids),
            "filteredOutShaderResourceIds": sorted(filtered_resource_ids),
            "targetMatchedShaderResourceIds": sorted(target_matched_resource_ids),
            "observedTargetRawSha256s": sorted(observed_target_hashes),
            # 'Unobserved' does not assert absence when any raw identity could
            # not be read. Consumers retain that uncertainty explicitly.
            "unobservedTargetRawSha256s": sorted(target_raw_hashes - observed_target_hashes),
            "symbolSnapshotShaderCount": 0,
            "symbolSnapshotUseCount": 0,
            "symbolSnapshotCaptureId": "",
        })
    encoded = _canonical_project_index_bytes(base)
    if len(encoded) > MAX_PROJECT_SHADER_INDEX_BYTES:
        # Preserve the complete identity inventory before raw convenience
        # blobs. The Host can request an exact resource separately if needed.
        base["rawBytecodeBlobs"] = []
        base["rawBytecodeIncludedBytes"] = 0
        for asset in base["assets"]:
            asset["rawBytecodeIncluded"] = False
        base["rawBytecodeOmittedCount"] = len(set(
            item["rawSha256"] for item in base["assets"]
            if item["rawSha256"]))
        base["diagnostics"].append({
            "code": "shader-raw-bytecode-response-budget",
            "resourceId": None,
        })
        encoded = _canonical_project_index_bytes(base)
    if len(encoded) > MAX_PROJECT_SHADER_INDEX_BYTES:
        base["inventoryComplete"] = False
        if target_raw_hashes:
            base["scanComplete"] = False
            base["targetInventoryComplete"] = False
        base["reasonId"] = "shader-resource-index-response-limit"
        base["assets"] = []
        base.pop("liveIdentitySha256", None)
    return base


def _build_all_project_shader_resource_index(ctrl, request, cancel_event=None,
                                             progress_callback=None):
    """Compatibility wrapper for callers that need a synchronous result."""

    return _consume_project_shader_resource_index_steps(
        _iter_all_project_shader_resource_index(
            ctrl, request, cancel_event=cancel_event,
            progress_callback=progress_callback), ctrl)


def _build_project_shader_resource_index(ctrl, request, cancel_event=None,
                                         progress_callback=None):
    if request.get("inventoryAllShaders") is True:
        return _build_all_project_shader_resource_index(
            ctrl, request, cancel_event=cancel_event,
            progress_callback=progress_callback)
    return _build_expected_project_shader_resource_index(
        ctrl, request, cancel_event=cancel_event,
        progress_callback=progress_callback)


def _project_shader_resource_index_steps(ctrl, request, cancel_event=None,
                                         progress_callback=None):
    if request.get("inventoryAllShaders") is True:
        return _iter_all_project_shader_resource_index(
            ctrl, request, cancel_event=cancel_event,
            progress_callback=progress_callback)
    return _iter_expected_project_shader_resource_index(
        ctrl, request, cancel_event=cancel_event,
        progress_callback=progress_callback)


def _queue_project_shader_resource_index_slice(job_id):
    # A non-empty, job-specific tag lets qrenderdoc identify this as background
    # replay work without coalescing slices belonging to different jobs.
    with _project_shader_index_jobs_guard:
        job = _project_shader_index_jobs.get(job_id)
        replay_manager = job.get("replayManager") if job is not None else None
    if replay_manager is None:
        raise RuntimeError("Project Shader resource-index replay manager is unavailable")
    replay_manager.AsyncInvoke(
        lambda ctrl, token=job_id: _run_project_shader_resource_index_job(token, ctrl),
        PROJECT_SHADER_INDEX_REPLAY_TAG_PREFIX + str(job_id))


def _run_project_shader_resource_index_job(job_id, ctrl):
    with _project_shader_index_jobs_guard:
        job = _project_shader_index_jobs.get(job_id)
        if job is None or job.get("status") not in ("queued", "running"):
            return
        if job.get("status") == "queued":
            job["status"] = "running"
            job["updatedMonotonic"] = time.monotonic()
            job["progress"] = {
                "phase": "index-unique-shader-resources",
                "processedResourceCount": 0,
                "totalResourceCount": 0,
                "resourceId": None,
                "inspectedEntryPointCount": 0,
                "eventTraversalCount": 0,
            }
        request = job["request"]
        cancel_event = job["cancelEvent"]
        steps = job.get("steps")
        steps_started = job.get("stepsStarted") is True
        if steps is None:
            steps = _project_shader_resource_index_steps(
                ctrl, request, cancel_event=cancel_event,
                progress_callback=lambda progress:
                _update_project_shader_index_job_progress(job_id, progress))
            job["steps"] = steps
            job["stepsStarted"] = False
            steps_started = False
    try:
        _check_project_shader_index_cancel(cancel_event)
        if request["captureSessionId"] != _capture_session_id:
            raise RuntimeError("RenderDoc capture changed before resource indexing")
        try:
            if steps_started:
                # Each suspended coroutine has explicitly cleared its previous
                # ReplayController/SWIG values. Inject only the controller from
                # this InvokeCallback, whose lifetime ends with this call.
                steps.send(ctrl)
            else:
                next(steps)
        except StopIteration as stopped:
            result = stopped.value
        else:
            # The generator yields only after releasing every callback-scoped
            # ReplayController/SWIG value and processes at most one physical
            # Shader owner between progress updates.
            # Queue the continuation so replaySetEvent work already waiting in
            # ReplayManager stays ahead of the next background micro-slice.
            _check_project_shader_index_cancel(cancel_event)
            if request["captureSessionId"] != _capture_session_id:
                raise RuntimeError(
                    "RenderDoc capture changed during resource indexing")
            with _project_shader_index_jobs_guard:
                current = _project_shader_index_jobs.get(job_id)
                if current is not job or job.get("status") != "running":
                    return
                job["stepsStarted"] = True
            # AsyncInvoke alone yields the replay queue, but an immediately
            # requeued Python callback can repeatedly reacquire the GIL before
            # GUI-side Python (including the IPC poller) gets a turn.
            time.sleep(PROJECT_SHADER_INDEX_UI_YIELD_SECONDS)
            _queue_project_shader_resource_index_slice(job_id)
            return
        publication = None
        if (request.get("inventoryAllShaders") is True and
                result.get("inventoryComplete") is True):
            # Build the bounded snapshot off the GUI thread.  The checked,
            # constant-time state swap is deferred to begin/poll below.
            publication = _prepare_inventory_symbol_snapshot_publication(
                result, request["capturePath"])
        _check_project_shader_index_cancel(cancel_event)
        if request["captureSessionId"] != _capture_session_id:
            raise RuntimeError("RenderDoc capture changed during resource indexing")
        with _project_shader_index_jobs_guard:
            current = _project_shader_index_jobs.get(job_id)
            if current is not job or job.get("status") != "running":
                return
            _check_project_shader_index_cancel(cancel_event)
            job["result"] = result
            job["symbolPublication"] = publication
            job["steps"] = None
            job["stepsStarted"] = False
            job["status"] = "completed"
            job["updatedMonotonic"] = time.monotonic()
            job["finishedMonotonic"] = job["updatedMonotonic"]
    except Exception as exc:
        try:
            steps.close()
        except Exception:
            pass
        with _project_shader_index_jobs_guard:
            current = _project_shader_index_jobs.get(job_id)
            if (current is not job or
                    job.get("status") not in ("queued", "running")):
                return
            if not job.get("error"):
                job["error"] = "%s: %s" % (type(exc).__name__, exc)
            job["steps"] = None
            job["stepsStarted"] = False
            job["status"] = "failed"
            job["updatedMonotonic"] = time.monotonic()
            job["finishedMonotonic"] = job["updatedMonotonic"]


def _finalize_project_shader_inventory_publication(job):
    """Commit a completed inventory snapshot on the request/GUI thread."""

    with _project_shader_index_jobs_guard:
        if (not isinstance(job, dict) or job.get("status") != "completed" or
                job.get("symbolPublicationCommitted") is True or
                job.get("symbolPublicationFailed") is True or
                job.get("symbolPublicationRunning") is True):
            return
        publication = job.get("symbolPublication")
        if not isinstance(publication, dict):
            return
        job["symbolPublicationRunning"] = True

    try:
        if job.get("captureSessionId") != _capture_session_id:
            raise RuntimeError(
                "RenderDoc capture changed before symbol snapshot publication")
        token = _current_capture_token()
        capture_path = str(
            publication.get("newSnapshot", {}).get("capturePath", "") or "")
        if (token is None or token[1] !=
                os.path.normcase(os.path.abspath(capture_path))):
            raise RuntimeError(
                "RenderDoc capture path changed before symbol snapshot publication")
        _commit_catalog_cache_publication(publication)
    except Exception as exc:
        with _project_shader_index_jobs_guard:
            if job.get("symbolPublicationRunning") is True:
                job["symbolPublicationRunning"] = False
                job["symbolPublicationFailed"] = True
                job["status"] = "failed"
                job["error"] = "%s: %s" % (type(exc).__name__, exc)
                job["updatedMonotonic"] = time.monotonic()
                job["finishedMonotonic"] = job["updatedMonotonic"]
        return

    with _project_shader_index_jobs_guard:
        if job.get("symbolPublicationRunning") is not True:
            return
        result = job.get("result")
        if isinstance(result, dict):
            result["symbolSnapshotPublished"] = True
        job["symbolPublicationRunning"] = False
        job["symbolPublicationCommitted"] = True
        job["symbolPublication"] = None
        job["updatedMonotonic"] = time.monotonic()


def _begin_rdc_project_shader_resource_index(params):
    """Queue bounded exact matching or all-Shader inventory without EID replay."""

    capture_path = _require_project_index_capture(params)
    request = _validated_project_shader_index_request(params, capture_path)
    replay_manager = _ctx.Replay()
    now = time.monotonic()
    existing_job = None
    with _project_shader_index_jobs_guard:
        _cleanup_project_shader_index_jobs(now)
        for existing in _project_shader_index_jobs.values():
            if (existing.get("captureSessionId") == request["captureSessionId"] and
                    existing.get("requestSha256") == request["requestSha256"]):
                existing_job = existing
                break
        if existing_job is None:
            active = sum(
                item.get("status") in ("queued", "running")
                for item in _project_shader_index_jobs.values())
            if active >= MAX_PROJECT_SHADER_INDEX_JOBS:
                raise RuntimeError("The project Shader resource-index queue is full")
            job_id = uuid.uuid4().hex
            cancel_event = threading.Event()
            cancel_event.replaylabForegroundGeneration = (
                _replay_foreground_generation(replay_manager))
            cancel_event.replaylabReplayManager = replay_manager
            job = {
                "jobId": job_id,
                "status": "queued",
                "captureSessionId": request["captureSessionId"],
                "requestSha256": request["requestSha256"],
                "request": request,
                "createdMonotonic": now,
                "updatedMonotonic": now,
                "result": None,
                "steps": None,
                "stepsStarted": False,
                "error": "",
                "committed": False,
                "cancelEvent": cancel_event,
                "replayManager": replay_manager,
                "cancelRequested": False,
                "symbolPublication": None,
                "symbolPublicationRunning": False,
                "symbolPublicationCommitted": False,
                "symbolPublicationFailed": False,
                "progress": {
                    "phase": "queued",
                    "processedResourceCount": 0,
                    "totalResourceCount": 0,
                    "resourceId": None,
                    "inspectedEntryPointCount": 0,
                    "eventTraversalCount": 0,
                },
            }
            _project_shader_index_jobs[job_id] = job
    if existing_job is not None:
        _finalize_project_shader_inventory_publication(existing_job)
        return _project_shader_index_job_snapshot(
            existing_job, idempotent=True)
    try:
        _queue_project_shader_resource_index_slice(job_id)
    except Exception:
        with _project_shader_index_jobs_guard:
            _project_shader_index_jobs.pop(job_id, None)
        raise
    _finalize_project_shader_inventory_publication(job)
    return _project_shader_index_job_snapshot(job)


def _poll_rdc_project_shader_resource_index(params):
    _require_project_index_capture(params)
    job_id = _project_shader_index_hex(params.get("job_id"), 32, "job_id")
    with _project_shader_index_jobs_guard:
        _cleanup_project_shader_index_jobs(time.monotonic())
        job = _project_shader_index_jobs.get(job_id)
        if job is None or job.get("captureSessionId") != _capture_session_id:
            raise ValueError("Unknown or expired project Shader resource-index job")
    _finalize_project_shader_inventory_publication(job)
    return _project_shader_index_job_snapshot(job)


def _commit_rdc_project_shader_resource_index(params):
    """Publish a Host-validated resource identity as a session-local route lease."""

    global _known_catalog_capture_ids, _known_catalog_identity_pairs
    capture_path = _require_project_index_capture(params)
    job_id = _project_shader_index_hex(params.get("job_id"), 32, "job_id")
    capture_id = _project_shader_index_hex(
        params.get("expected_capture_id"), 64, "expected_capture_id")
    evidence_sha256 = _project_shader_index_hex(
        params.get("expected_identity_evidence_sha256"), 64,
        "expected_identity_evidence_sha256")
    live_sha256 = _project_shader_index_hex(
        params.get("live_identity_sha256"), 64, "live_identity_sha256")
    with _project_shader_index_jobs_guard:
        _cleanup_project_shader_index_jobs(time.monotonic())
        job = _project_shader_index_jobs.get(job_id)
        result = job.get("result") if isinstance(job, dict) else None
        request = job.get("request") if isinstance(job, dict) else None
        if (not isinstance(job, dict) or job.get("status") != "completed" or
                not isinstance(result, dict) or result.get("matched") is not True or
                result.get("leaseEligible") is not True or
                not isinstance(request, dict) or
                request.get("inventoryAllShaders") is True or
                job.get("captureSessionId") != _capture_session_id or
                request.get("captureId") != capture_id or
                request.get("identityEvidenceSha256") != evidence_sha256 or
                result.get("liveIdentitySha256") != live_sha256):
            raise RuntimeError(
                "Project Shader resource-index lease is incomplete or changed")
        already_committed = job.get("committed") is True
        token = _current_capture_token()
        canonical_path = os.path.normcase(os.path.abspath(capture_path))
        if token is None or token[1] != canonical_path:
            raise RuntimeError("RenderDoc capture changed before resource-index commit")
        new_ids = dict(_known_catalog_capture_ids)
        if capture_id not in new_ids and len(new_ids) >= MAX_KNOWN_CATALOG_CAPTURE_IDS:
            raise RuntimeError("Too many cached capture identities are active")
        new_ids[capture_id] = canonical_path
        new_pairs = set(_known_catalog_identity_pairs)
        pair = (capture_id, evidence_sha256)
        if pair not in new_pairs and len(new_pairs) >= MAX_KNOWN_CATALOG_IDENTITY_PAIRS:
            raise RuntimeError("Too many cached catalog identities are active")
        new_pairs.add(pair)
        _known_catalog_capture_ids = new_ids
        _known_catalog_identity_pairs = new_pairs
        job["committed"] = True
        job["updatedMonotonic"] = time.monotonic()
    return {
        "schema": "replaylab-project-shader-resource-index-lease/v1",
        "schemaVersion": 1,
        "jobId": job_id,
        "captureId": capture_id,
        "captureSessionId": _capture_session_id,
        "identityEvidenceSha256": evidence_sha256,
        "liveIdentitySha256": live_sha256,
        "committed": True,
        "idempotent": already_committed,
        "eventTraversalCount": 0,
        "gpuReplayMutation": False,
        "physicalApplyAuthority": False,
        "resourceOwnershipScope": "target-capture-session",
        "crossCaptureResourceIdReuse": False,
    }


_PROJECT_PRESELECTED_OPEN_TOKEN = object()


def _capture_path_key(path):
    text = str(path or "").strip()
    if not text:
        return ""
    return os.path.normcase(os.path.abspath(text))


def _consume_preselected_project_capture(path):
    """Consume the one-shot path armed by the project launcher's activation."""

    global _project_preselected_capture_path
    expected = _project_preselected_capture_path
    if not expected:
        return False
    _project_preselected_capture_path = ""
    return expected == _capture_path_key(path)


def _recover_replay(params):
    """Rebuild only a fatal same-file controller; retain drafts and saved media."""
    from .replay_recovery import ReplayRecoveryCoordinator
    global _replay_recovery_coordinator
    if _replay_recovery_coordinator is None:
        _replay_recovery_coordinator = ReplayRecoveryCoordinator()

    class Hooks(object):
        def snapshot(self):
            return {"loaded": bool(_ctx and _ctx.IsCaptureLoaded()),
                    "local": bool(_ctx and _ctx.IsCaptureLocal()),
                    "temporary": bool(_ctx and _ctx.IsCaptureTemporary()),
                    "capturePath": str(_ctx.GetCaptureFilename() or ""),
                    "captureSessionId": _capture_session_id,
                    "eventId": int(_ctx.CurEvent()), "selectedEventId": int(_ctx.CurSelectedEvent())}

        def health(self):
            return _get_replay_health({})

        def preserve(self, snapshot):
            # Source editors and project/diagram files are not closed or rewritten.
            # The old native driver has already destroyed every applied override.
            panel = _shader_workspace_ui
            documents = getattr(panel, "_documents", {})
            models = getattr(panel, "_workspaces", {})
            before = []
            for workspace_id, document in documents.items():
                model = models.get(workspace_id, {})
                live = model.get("liveEdit", {}) if isinstance(model, dict) else {}
                last = live.get("lastApply", {}) if isinstance(live, dict) else {}
                replacement = last.get("replacement", {}) if isinstance(last, dict) else {}
                applied = document.get("appliedReplacementId") or (
                    replacement.get("replacementId") if isinstance(replacement, dict) else "")
                before.append({"workspaceId": str(workspace_id),
                               "sourcePath": str(document.get("sourcePath", "") or ""),
                               "dirty": bool(document.get("dirty")),
                               "wasApplied": bool(applied)})
            return {"preserved": True, "sharedShaders": list(_shared_shader_replacements.values()),
                    "eventShaders": list(_event_shader_overrides.values()),
                    "beforeSavedApplied": before, "documents": documents,
                    "savedDiagram": _frame_render_flow_saved,
                    "flowDocument": getattr(_frame_render_flow_ui, "document", None)}

        def begin(self, snapshot, preserved):
            global _replay_recovery_path
            _replay_recovery_path = _capture_path_key(snapshot["capturePath"])
            window = _ctx.GetMainWindow().Widget()
            window.setProperty("breadReplayRecoveryCapturePath", snapshot["capturePath"])
            _cancel_project_auto_activation()
            _abandon_project_launcher_restore()
            if _project_async_executor is not None:
                _project_async_executor.cancel_owner("frame-flow-restore")
            return window

        def invalidate(self, snapshot, preserved):
            global _frame_render_flow_generation
            # Do not rollback through DummyDriver. Invalidate live IDs only.
            _forget_event_shader_overrides()
            _forget_shared_shader_replacements()
            _forget_event_cbuffer_snapshots()
            _shared_cbuffer_edits.forget()
            panel = _shader_workspace_ui
            for document in getattr(panel, "_documents", {}).values():
                document.pop("appliedReplacementId", None)
            # Workspace models live in the panel's _workspaces registry, not in
            # an editor document. Clear only the live receipt, never saved source.
            for model in getattr(panel, "_workspaces", {}).values():
                if isinstance(model, dict) and isinstance(model.get("liveEdit"), dict):
                    model["liveEdit"].pop("lastApply", None)
            _frame_render_flow_generation += 1
            flow = _frame_render_flow_ui
            loader = getattr(flow, "_channel_preview_loader", None)
            if loader is not None:
                loader.close()
                flow._channel_preview_loader = None
            view = getattr(flow, "view", None)
            cache = getattr(view, "_channel_cache", None)
            if isinstance(cache, dict):
                cache.clear()

        def reopen(self, snapshot):
            global _active_capture_token, _frame_render_flow_outline_cache
            status = _ctx.LoadCaptureForReplayRecovery(
                snapshot["capturePath"], _ctx.Config().DefaultReplayOptions, snapshot["capturePath"])
            self.reopen_status = {"code": str(status.code), "diagnostic": str(status)}
            if status.code != rd.ResultCode.Succeeded:
                raise RuntimeError("bread-replay-reopen-failed: %s" % str(status))
            _reset_symbol_state(restore_names=False)
            _active_capture_token = _current_capture_token()
            _frame_render_flow_outline_cache = None
            self.reopened_session = _capture_session_id
            # Saved media retains its old session. Keeping the immutable record
            # does not authorize navigation or claim the old pixels are current.

        def restore_event(self, snapshot):
            if (not _ctx.IsCaptureLoaded() or
                    _capture_path_key(_ctx.GetCaptureFilename()) != _replay_recovery_path or
                    _capture_session_id != getattr(self, "reopened_session", None)):
                raise RuntimeError("The capture changed before replay recovery could restore the selected event")
            _ctx.SetEventID([], snapshot["selectedEventId"], snapshot["eventId"], True)

        def cancelled(self):
            poller = globals().get("_poller")
            item = getattr(poller, "_active_item", None)
            return bool(item and item.get("cancelEvent") and item["cancelEvent"].is_set())

        def finish(self, snapshot, preserved, result, token):
            global _replay_recovery_path
            try:
                if hasattr(self, "reopen_status"):
                    result["reopenStatus"] = self.reopen_status
                # Preserve dirty text, but invalidate its former replay authority.
                binding = _shader_workspace_capture_binding()
                for panel in (_shader_workspace_ui, _shader_console_ui):
                    changed = getattr(panel, "capture_changed", None)
                    if callable(changed):
                        changed(binding)
                result["beforeSavedApplied"] = preserved.get("beforeSavedApplied", [])
                result["retainedShaderDraftCount"] = sum(1 for row in result["beforeSavedApplied"] if row["dirty"])
                result["invalidatedShaderReplacementCount"] = len(preserved.get("sharedShaders", [])) + len(preserved.get("eventShaders", []))
                result["savedDiagramRetained"] = bool(
                    preserved.get("savedDiagram") or preserved.get("flowDocument"))
                result["nextAction"] = ("Prepare the frame flow for the new capture session; inspect original capture evidence. "
                                        "Saved diagrams remain historical; Shader replacements and live CBuffer edits require separate validation.")
                _publish_instance_manifest(activity=True)
            finally:
                try:
                    window = token or _ctx.GetMainWindow().Widget()
                    window.setProperty("breadReplayRecoveryCapturePath", None)
                finally:
                    _replay_recovery_path = ""

    return _replay_recovery_coordinator.recover(Hooks(), str(params.get("expected_capture_session_id", "") or ""))


def _open_capture(params, _project_open_token=None):
    """Open a capture, preserving an already open file unless reload is explicit."""
    path = params.get("capture_path", "")
    if not path:
        raise ValueError("capture_path required")
    force_reload = params.get("force_reload", False)
    if type(force_reload) is not bool:
        raise ValueError("force_reload must be a boolean")
    if not _ctx:
        return {"error": "No context"}
    global _active_capture_token, _project_preselected_capture_path
    global _project_preselected_open_depth
    project_preselected = _project_open_token is _PROJECT_PRESELECTED_OPEN_TOKEN
    if not force_reload and not project_preselected:
        try:
            loaded_path = str(_ctx.GetCaptureFilename() or "")
            already_open = (bool(_ctx.IsCaptureLoaded()) and bool(loaded_path)
                            and _capture_path_key(loaded_path) == _capture_path_key(path))
        except Exception:
            already_open = False
        if already_open:
            # LoadCapture emits capture lifecycle callbacks which interrupt
            # capture-bound AI tasks. An Agent ensuring this same RDC is open
            # must not clear live replacements or terminate its own turn.
            return {
                "opened": os.path.abspath(loaded_path),
                "captureSessionId": _capture_session_id,
                "alreadyOpen": True,
            }
    _release_event_shader_overrides()
    _release_shared_shader_replacements()
    _release_event_cbuffer_snapshots()
    _reset_symbol_state(restore_names=True)
    # Match the bundled qrenderdoc ICaptureContext contract exactly. Reusing
    # the configured defaults preserves the user's replay/GPU validation
    # choices, while origFilename identifies the same local RDC.
    preselected_path = _capture_path_key(path) if project_preselected else ""
    if project_preselected:
        # project_launcher activates and fully validates the selected project
        # before calling us. Arm the lifecycle callback so it does not launch a
        # second registry-wide path association after this capture has loaded.
        _project_preselected_capture_path = preselected_path
        _project_preselected_open_depth += 1
    try:
        _ctx.LoadCapture(
            path, _ctx.Config().DefaultReplayOptions, path, False, True)
    except Exception:
        if (_project_preselected_capture_path == preselected_path and
                project_preselected):
            _project_preselected_capture_path = ""
        raise
    finally:
        if project_preselected:
            _project_preselected_open_depth = max(
                0, _project_preselected_open_depth - 1)
    # LoadCapture reports replay failures through qrenderdoc's native dialog in
    # some builds instead of raising back into Python.  Do not start project
    # restoration unless the requested local capture is now the live context.
    try:
        loaded = bool(_ctx.IsCaptureLoaded())
        loaded_path = os.path.abspath(str(_ctx.GetCaptureFilename() or ""))
    except Exception:
        loaded = False
        loaded_path = ""
    if (not loaded or
            os.path.normcase(loaded_path) !=
            os.path.normcase(os.path.abspath(path))):
        if (_project_preselected_capture_path == preselected_path and
                project_preselected):
            _project_preselected_capture_path = ""
        return {
            "errorId": "renderdoc-open-incomplete",
            # i18n-ignore: legacy MCP protocol diagnostic retained for clients
            # that still detect failures through the historical error field.
            "error": "RenderDoc did not finish opening the selected RDC",
            "requested": os.path.abspath(path),
        }
    # Some qrenderdoc versions do not synchronously deliver CaptureViewer
    # callbacks for integration-initiated loads. Establish a fresh physical
    # session explicitly before any catalog identity can be cached -- but only when
    # they really did not run. On a build that delivers them synchronously,
    # OnCaptureLoaded has already minted a session and scheduled the project
    # auto-restore against it; minting a second one here made that restore run and
    # then discard its own result at the session check, leaving the status line
    # stuck on "matching this RDC" with nothing restored and nothing logged.
    token = _current_capture_token()
    if _active_capture_token != token:
        _reset_symbol_state(restore_names=False)
        token = _current_capture_token()
    _active_capture_token = token
    return {
        "opened": loaded_path,
        "captureSessionId": _capture_session_id,
    }


def _open_capture_for_preselected_project(path):
    """Open an RDC whose owning project was explicitly activated by the UI."""

    return _open_capture(
        {"capture_path": str(path)}, _PROJECT_PRESELECTED_OPEN_TOKEN)


def _get_bound_textures(params):
    """Get textures bound to a shader stage with role inference."""
    event_id = params.get("event_id")
    stage_name = _normalise_stage_name(params.get("stage", "fragment"))
    if event_id is None:
        raise ValueError("event_id required")

    stage_map = dict(_available_shader_stages([stage_name]))
    stage = stage_map.get(stage_name)
    if stage is None:
        raise ValueError("unsupported shader stage: %s" % stage_name)

    def _do(ctrl):
        _set_frame_event(ctrl, int(event_id), True)
        ps = ctrl.GetPipelineState()
        sid = ps.GetShader(stage)
        if not sid or int(sid) == 0:
            return []
        pid = _get_pipeline_obj(ps, ctrl)
        entries = list(ctrl.GetShaderEntryPoints(sid) or [])
        selection = _pipeline_shader_entry_selection(
            ps, stage, stage_name, sid, entries)
        selected_entry = selection.get("entry")
        if selected_entry is None:
            return _shader_entry_selection_failure(
                selection, sid, pid, stage_name)
        refl = ctrl.GetShader(pid, sid, selected_entry)
        if not refl:
            failure = _shader_entry_selection_failure(
                selection, sid, pid, stage_name)
            failure.update({
                "errorId": "shader-reflection-unavailable",
                "error": "The exact pipeline shader reflection is unavailable",
            })
            return failure
        identity_failure = _shader_reflection_identity_failure(
            refl, selected_entry, sid, pid, stage_name, selection)
        if identity_failure is not None:
            return identity_failure

        name_lookup = {}
        for r in ctrl.GetResources():
            name_lookup[int(r.resourceId)] = r.name
        tex_lookup = {}
        for t in ctrl.GetTextures():
            tex_lookup[int(t.resourceId)] = t

        try:
            ro_bindings = ps.GetReadOnlyResources(stage)
        except Exception:
            ro_bindings = None

        result = []
        for i, ro in enumerate(getattr(refl, 'readOnlyResources', [])):
            if not getattr(ro, 'isTexture', False):
                continue
            ro_name = getattr(ro, 'name', 'tex%d' % i)
            bind_num = getattr(ro, 'fixedBindNumber', i)
            exact_bindings = _exact_readonly_descriptor_resources(
                ro_bindings, i)
            if not exact_bindings:
                exact_bindings = [{
                    "resourceId": 0, "arrayElement": 0,
                    "descriptorStoreId": 0, "evidence": "unbound",
                }]
            for exact in exact_bindings:
                entry = {
                    "slot": i,
                    "name": ro_name,
                    "bind": bind_num,
                    "space": _safe_int(
                        getattr(ro, 'fixedBindSetOrSpace', 0), 0),
                    "arrayIndex": exact["arrayElement"],
                    "resourceId": exact["resourceId"],
                    "bindingEvidence": exact["evidence"],
                }
                if exact["descriptorStoreId"] > 0:
                    entry["descriptorStoreId"] = exact["descriptorStoreId"]
                rid = entry["resourceId"]
                if rid and rid in tex_lookup:
                    t = tex_lookup[rid]
                    entry["texName"] = name_lookup.get(rid, "")
                    entry["width"] = t.width
                    entry["height"] = t.height
                    entry["format"] = _fmt_str(t.format)
                    inferred_role = _infer_role(
                        ro_name, name_lookup.get(rid, ""), _fmt_str(t.format))
                else:
                    inferred_role = _infer_role(ro_name, "", "")
                entry["role"] = inferred_role
                entry["roleInference"] = {
                    "value": inferred_role,
                    "basis": "reflection/resource names and texture-format heuristic",
                    "confidence": "low",
                    "observed": False,
                }
                result.append(entry)
        return result

    return _replay(_do)


MAX_CONSTANT_BUFFER_VALUE_BYTES = 64 * 1024


def _get_constant_buffer_values(params):
    """Return the raw bytes of every bound constant buffer as float/uint lanes.

    Layout-independent evidence for asset matching: a distinctive value such
    as 12.354754 appearing in a cbuffer lane and in an unpacked material's
    parameter data ties the draw to that asset. Each block reports its
    register/space/size, the bound buffer identity and the lanes; missing
    bindings are reported per block instead of failing the whole call.
    """
    event_id = params.get("event_id")
    stage_name = _normalise_stage_name(params.get("stage", "fragment"))
    if event_id is None:
        raise ValueError("event_id required")
    stage_map = dict(_available_shader_stages([stage_name]))
    stage = stage_map.get(stage_name)
    if stage is None:
        raise ValueError("unsupported shader stage: %s" % stage_name)

    def _do(ctrl):
        import struct as _struct
        _set_frame_event(ctrl, int(event_id), True)
        ps = ctrl.GetPipelineState()
        sid = ps.GetShader(stage)
        if not sid or int(sid) == 0:
            return {"eventId": int(event_id), "stage": stage_name, "constantBuffers": [],
                    "status": "no-shader-bound"}
        pid = _get_pipeline_obj(ps, ctrl)
        entries = list(ctrl.GetShaderEntryPoints(sid) or [])
        selection = _pipeline_shader_entry_selection(ps, stage, stage_name, sid, entries)
        selected_entry = selection.get("entry")
        if selected_entry is None:
            return _shader_entry_selection_failure(selection, sid, pid, stage_name)
        refl = ctrl.GetShader(pid, sid, selected_entry)
        if not refl:
            return {"eventId": int(event_id), "stage": stage_name, "constantBuffers": [],
                    "status": "reflection-unavailable"}
        name_lookup = {}
        for r in ctrl.GetResources():
            name_lookup[int(r.resourceId)] = r.name
        blocks = []
        for idx, cb in enumerate(getattr(refl, "constantBlocks", [])):
            binding = _get_constant_block_binding(ps, stage, idx)
            entry = {
                "index": idx,
                "name": getattr(cb, "name", ""),
                "bind": _safe_int(getattr(cb, "fixedBindNumber", idx), idx),
                "space": _safe_int(getattr(cb, "fixedBindSetOrSpace", 0), 0),
                "byteSize": _safe_int(getattr(cb, "byteSize", 0), 0),
                "bufferId": binding["resourceId"],
                "bufferName": name_lookup.get(_resource_id_int(binding["resourceId"]), ""),
                "byteOffset": binding["byteOffset"],
                "boundByteSize": binding["byteSize"],
                "status": "unavailable",
                "floats": [],
                "uints": [],
            }
            try:
                buffer_rid = _resource_id_lookup(ctrl.GetResources(), binding["resourceId"])
                size = entry["boundByteSize"] or entry["byteSize"]
                if buffer_rid is None or size <= 0:
                    entry["reason"] = "constant block has no bound buffer (inline/root constants or unbound)"
                else:
                    size = min(int(size), MAX_CONSTANT_BUFFER_VALUE_BYTES)
                    # A D3D12 root CBV can expose the remainder of a shared
                    # upload buffer. That is not this block's parameter extent;
                    # reading it mixes neighbouring draws/materials into the
                    # matching evidence. Keep the reflected extent when known.
                    if entry["byteSize"] > 0:
                        size = min(size, entry["byteSize"])
                    data = bytes(ctrl.GetBufferData(buffer_rid, int(binding["byteOffset"]), size))
                    lanes = len(data) // 4
                    entry["floats"], non_finite = _strict_float_vector(
                        _struct.unpack_from("<%df" % lanes, data, 0), lanes)
                    if non_finite:
                        entry["floatNonFinite"] = non_finite
                    entry["uints"] = list(_struct.unpack_from("<%dI" % lanes, data, 0))
                    entry["readBytes"] = len(data)
                    entry["status"] = "available"
            except Exception as exc:
                entry["reason"] = str(exc).replace("\x00", "")[:512]
            blocks.append(entry)
        return {"eventId": int(event_id), "stage": stage_name, "entryPoint": str(selected_entry),
                "constantBuffers": blocks, "status": "ok"}

    return _replay(_do)


MAX_TEXTURE_FINGERPRINT_PNG_BYTES = 256 * 1024
TEXTURE_FINGERPRINT_MAX_DIM = 64
# One SaveTexture pass per (capture, event, resource) identity; cleared after
# Host asset authorization so matching no longer retains PNG blobs in-process.
_TEXTURE_FINGERPRINT_CACHE = {}
_TEXTURE_FINGERPRINT_CACHE_ORDER = []
_TEXTURE_FINGERPRINT_CACHE_MAX = 64


def _texture_fingerprint_cache_key(event_id, resource_ids):
    capture = ""
    try:
        if _ctx is not None:
            capture = str(getattr(_ctx, "GetCaptureFilename", lambda: "")() or "")
    except Exception:
        capture = ""
    ids = []
    for raw in list(resource_ids or [])[:32]:
        try:
            ids.append(int(_resource_id_int(raw)))
        except Exception:
            ids.append(str(raw))
    return (capture, int(event_id) if event_id is not None else None, tuple(ids))


def _cache_texture_fingerprints(key, payload):
    global _TEXTURE_FINGERPRINT_CACHE, _TEXTURE_FINGERPRINT_CACHE_ORDER
    if key in _TEXTURE_FINGERPRINT_CACHE:
        try:
            _TEXTURE_FINGERPRINT_CACHE_ORDER.remove(key)
        except ValueError:
            pass
    _TEXTURE_FINGERPRINT_CACHE[key] = payload
    _TEXTURE_FINGERPRINT_CACHE_ORDER.append(key)
    while len(_TEXTURE_FINGERPRINT_CACHE_ORDER) > _TEXTURE_FINGERPRINT_CACHE_MAX:
        old = _TEXTURE_FINGERPRINT_CACHE_ORDER.pop(0)
        _TEXTURE_FINGERPRINT_CACHE.pop(old, None)


def _release_texture_fingerprint_cache(params=None):
    """Drop cached SaveTexture fingerprints after asset matching is done."""

    global _TEXTURE_FINGERPRINT_CACHE, _TEXTURE_FINGERPRINT_CACHE_ORDER
    released = len(_TEXTURE_FINGERPRINT_CACHE)
    _TEXTURE_FINGERPRINT_CACHE = {}
    _TEXTURE_FINGERPRINT_CACHE_ORDER = []
    # Best-effort: also clear project thumbnail cache if present.
    try:
        if _project_thumbnail_cache is not None:
            _project_thumbnail_cache.clear()
    except Exception:
        pass
    return {
        "schema": "replaylab-texture-fingerprint-release/v1",
        "releasedEntries": released,
        "applied": True,
    }


def _release_replay_transient_caches(params=None):
    """Drop rebuildable replay/bridge transients without unloading the capture.

    Opening an RDC already materialises the capture's shaders/resources once.
    Tool calls that force SetFrameEvent, BuildTargetShader, or GetTextureData
    can grow Private on top of that session. This release clears:

    - SaveTexture fingerprint / thumbnail Python caches
    - ReplayController.ClearReplayCache (driver-side replay scratch)
    - orphaned FreeTargetResource entries not owned by a live shared replace

    It does **not** CloseCapture, rollback applied shared shader replacements,
    or drop event overrides the user/Agent still owns.
    """

    global _shared_shader_orphan_targets

    options = params if isinstance(params, dict) else {}
    clear_replay = options.get("clear_replay_cache", True)
    release_orphans = options.get("release_orphaned_targets", True)

    fingerprint = _release_texture_fingerprint_cache({})
    replay_cleared = False
    replay_error = ""
    if clear_replay is not False:
        try:
            def _clear(ctrl):
                clearer = getattr(ctrl, "ClearReplayCache", None)
                if not callable(clearer):
                    raise RuntimeError("ReplayController.ClearReplayCache is unavailable")
                clearer()
                return True

            replay_cleared = bool(_replay(_clear))
        except Exception as exc:
            replay_error = str(exc)[:400]

    orphans_freed = 0
    orphan_error = ""
    if release_orphans is not False:
        pending = list(_shared_shader_orphan_targets)
        if pending:
            kept = []
            try:
                def _free_orphans(ctrl):
                    freed = 0
                    remaining = []
                    for target in pending:
                        try:
                            ctrl.FreeTargetResource(target)
                            freed += 1
                        except Exception:
                            remaining.append(target)
                    return freed, remaining

                orphans_freed, kept = _replay(_free_orphans)
            except Exception as exc:
                orphan_error = str(exc)[:400]
                kept = pending
            _shared_shader_orphan_targets = list(kept)

    return {
        "schema": "replaylab-replay-transient-release/v1",
        "applied": True,
        "fingerprint": fingerprint,
        "releasedEntries": int(fingerprint.get("releasedEntries") or 0),
        "replayCacheCleared": bool(replay_cleared),
        "replayCacheError": replay_error,
        "orphanedTargetsFreed": int(orphans_freed),
        "orphanedTargetsRemaining": len(_shared_shader_orphan_targets),
        "orphanError": orphan_error,
        "captureUnloaded": False,
        "sharedReplacementsPreserved": True,
    }


def _get_texture_fingerprints(params):
    """Small-mip PNG snapshots of textures for content-identity matching.

    For each resource id the mip whose larger dimension is closest to 32 px
    (never above 64) is saved as PNG through RenderDoc's own converter — so
    every GPU format, BC7 and float included, arrives as plain RGBA — and
    returned base64-encoded for the Host to hash. Failures are per texture
    with a reason; nothing here mutates replay state. Identical requests reuse
    one in-process cache until ``release_texture_fingerprint_cache``.
    """
    import base64 as _base64
    import tempfile as _tempfile
    raw_ids = params.get("resource_ids") or []
    if not isinstance(raw_ids, list) or len(raw_ids) > 32:
        raise ValueError("resource_ids must be a list of at most 32 ids")
    event_id = params.get("event_id")
    cache_key = _texture_fingerprint_cache_key(event_id, raw_ids)
    cached = _TEXTURE_FINGERPRINT_CACHE.get(cache_key)
    if isinstance(cached, dict) and cached.get("textures") is not None:
        reused = dict(cached)
        reused["cacheHit"] = True
        return reused

    def _do(ctrl):
        if event_id is not None:
            # Prefer a non-force set when the controller is already at this EID.
            # Force=True materialises more replay resources and was observed to
            # leave large unreclaimed allocations in the qrenderdoc process.
            current_event = 0
            try:
                if _ctx is not None:
                    current_event = _safe_int(_ctx.CurEvent(), 0)
            except Exception:
                current_event = 0
            _set_frame_event(ctrl, int(event_id), force=(current_event != int(event_id)))
        tex_lookup = {int(t.resourceId): t for t in ctrl.GetTextures()}
        name_lookup = {int(r.resourceId): r.name for r in ctrl.GetResources()}
        results = []
        temp_dir = _tempfile.mkdtemp(prefix="replaylab-texfp-")
        try:
            for raw in raw_ids:
                rid_int = _resource_id_int(raw)
                entry = {"resourceId": rid_int, "name": name_lookup.get(rid_int, ""), "available": False}
                texture = tex_lookup.get(rid_int)
                if texture is None:
                    entry["reason"] = "resource is not a texture in this capture"
                    results.append(entry)
                    continue
                width, height = int(texture.width), int(texture.height)
                mips = max(1, int(getattr(texture, "mips", 1)))
                entry.update({"width": width, "height": height, "mips": mips,
                              "format": _fmt_str(texture.format),
                              "arraySize": int(getattr(texture, "arraysize", 1)),
                              "cubemap": bool(getattr(texture, "cubemap", False))})
                largest = max(width, height)
                mip = 0
                while mip + 1 < mips and (largest >> mip) > TEXTURE_FINGERPRINT_MAX_DIM:
                    mip += 1
                if (largest >> mip) > 4 * TEXTURE_FINGERPRINT_MAX_DIM:
                    entry["reason"] = "texture has no mip small enough to snapshot cheaply"
                    results.append(entry)
                    continue
                buffer_rid = _resource_id_lookup(ctrl.GetResources(), rid_int)
                if buffer_rid is None:
                    entry["reason"] = "resource id could not be resolved"
                    results.append(entry)
                    continue
                save = rd.TextureSave()
                save.resourceId = buffer_rid
                save.typeCast = rd.CompType.Typeless
                save.destType = rd.FileType.PNG
                save.mip = mip
                save.slice.sliceIndex = 0
                save.sample.mapToArray = False
                save.sample.sampleIndex = 0
                save.channelExtract = -1
                save.alpha = rd.AlphaMapping.Discard
                path = os.path.join(temp_dir, "fp-%d.png" % rid_int)
                try:
                    result = ctrl.SaveTexture(save, path)
                    if result.code != rd.ResultCode.Succeeded:
                        entry["reason"] = "SaveTexture failed: %s" % str(result)
                        results.append(entry)
                        continue
                    size = os.path.getsize(path)
                    if size > MAX_TEXTURE_FINGERPRINT_PNG_BYTES:
                        entry["reason"] = "snapshot PNG exceeds %d bytes" % MAX_TEXTURE_FINGERPRINT_PNG_BYTES
                        results.append(entry)
                        continue
                    with open(path, "rb") as stream:
                        data = stream.read()
                    entry.update({"available": True, "mip": mip, "pngBase64": _base64.b64encode(data).decode("ascii"),
                                  "pngBytes": len(data)})
                except Exception as exc:
                    entry["reason"] = str(exc).replace("\x00", "")[:400]
                finally:
                    try:
                        if os.path.exists(path):
                            os.unlink(path)
                    except OSError:
                        pass
                results.append(entry)
        finally:
            try:
                os.rmdir(temp_dir)
            except OSError:
                pass
        return {"eventId": event_id, "textures": results, "cacheHit": False}

    payload = _replay(_do)
    _cache_texture_fingerprints(cache_key, payload)
    return payload


def _get_draw_geometry(params):
    """Geometry facts of one draw for mesh-level asset matching.

    Index/vertex/instance counts, topology, the used vertex inputs (semantic,
    format, slot, stride) and the vertex/index buffer identities with their
    debug names (often empty in shipped games — counts and layout are what
    survive). Read-only.
    """
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")

    def _do(ctrl):
        _set_frame_event(ctrl, int(event_id), True)
        action = _find_action_by_event(ctrl.GetRootActions(), int(event_id))
        ps = ctrl.GetPipelineState()
        name_lookup = {int(r.resourceId): r.name for r in ctrl.GetResources()}
        result = {"eventId": int(event_id), "available": action is not None}
        if action is not None:
            result.update(_action_workload(action))
            result["flags"] = _safe_int(getattr(action, "flags", 0), 0)
        try:
            result["topology"] = str(ps.GetPrimitiveTopology())
        except Exception:
            result["topology"] = ""
        inputs = []
        try:
            for value in list(ps.GetVertexInputs() or [])[:32]:
                if getattr(value, "used", False) is not True:
                    continue
                inputs.append({
                    "semantic": "%s%d" % (getattr(value, "name", ""), _safe_int(getattr(value, "semanticIndex", 0), 0))
                    if getattr(value, "name", "") else "",
                    "format": _fmt_str(getattr(value, "format", None)),
                    "vertexBuffer": _safe_int(getattr(value, "vertexBuffer", -1), -1),
                    "byteOffset": _safe_int(getattr(value, "byteOffset", 0), 0),
                    "perInstance": bool(getattr(value, "perInstance", False)),
                })
        except Exception as exc:
            result["vertexInputsError"] = str(exc)[:200]
        result["vertexInputs"] = inputs
        buffers = []
        try:
            for slot, binding in enumerate(list(ps.GetVBuffers() or [])[:16]):
                info = _bound_descriptor_info(binding)
                rid = _resource_id_int(info.get("resourceId"))
                if rid:
                    buffers.append({"slot": slot, "resourceId": rid, "name": name_lookup.get(rid, ""),
                                    "byteStride": info.get("byteStride"), "byteSize": _safe_int(info.get("byteSize", 0), 0)})
        except Exception as exc:
            result["vertexBuffersError"] = str(exc)[:200]
        result["vertexBuffers"] = buffers
        try:
            index = _bound_descriptor_info(ps.GetIBuffer())
            rid = _resource_id_int(index.get("resourceId"))
            result["indexBuffer"] = {"resourceId": rid, "name": name_lookup.get(rid, ""),
                                     "byteStride": index.get("byteStride")} if rid else None
        except Exception:
            result["indexBuffer"] = None
        semantics = [item["semantic"].upper() for item in inputs if item.get("semantic")]
        result["meshHint"] = (
            "skeletal" if any(s.startswith(("BLENDINDICES", "BLENDWEIGHT")) for s in semantics)
            else "instanced" if any(item.get("perInstance") for item in inputs)
            else "static" if semantics else "unknown")
        return result

    return _replay(_do)


def _reverse_shader(params):
    """Full shader reverse-engineering."""
    event_id = params.get("event_id")
    stage_name = params.get("stage", "fragment")
    if event_id is None:
        raise ValueError("event_id required")

    # Reuse get_shader_info which already does full reverse
    return _get_shader_info({"event_id": event_id, "stage": stage_name,
                             "text_mode": params.get("text_mode", "all")})


def _inspect_shader(params):
    """Return one shader reconstruction without repeating disassembly work."""
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")
    event_id = int(event_id)
    stage_name = _normalise_stage_name(params.get("stage", "fragment"))
    shader = _get_shader_info({"event_id": event_id, "stage": stage_name})
    return {
        "schema": "renderdoc-internal-inspect-shader/v2",
        "eventId": event_id,
        "stage": stage_name,
        "shader": shader,
    }


def _lighting_cbuffer_window(binding):
    """Return the bounded byte window represented by one CBuffer binding."""
    offset = max(0, _safe_int(getattr(binding, "byteOffset", 0), 0))
    byte_size = _safe_int(getattr(binding, "byteSize", 0), 0)
    if byte_size <= 0:
        return offset, 0
    return offset, min(byte_size, MAX_LIGHTING_CBUFFER_BYTES)


def _read_lighting_cbuffer_data(ctrl, resource_id, binding):
    """Read only the bound CBuffer range used by the lighting heuristic."""
    offset, byte_size = _lighting_cbuffer_window(binding)
    if _resource_id_int(resource_id) <= 0 or byte_size <= 0:
        return None, offset, byte_size
    data = ctrl.GetBufferData(resource_id, offset, byte_size)
    return data[:byte_size], offset, byte_size


def _analyze_lighting(params):
    """Analyze lighting setup from a draw call's shader and constant buffers."""
    event_id = params.get("event_id")
    if event_id is None:
        raise ValueError("event_id required")

    def _do(ctrl):
        try:
            _set_frame_event(ctrl, int(event_id), True)
            ps = ctrl.GetPipelineState()
            pid = _get_pipeline_obj(ps, ctrl)
            result = {"eventId": int(event_id)}
        except Exception as e:
            return {"error": "init: " + str(e)}

        # 1. Get shader reflection
        for stage_name, stage_enum in [("fragment", rd.ShaderStage.Fragment), ("vertex", rd.ShaderStage.Vertex)]:
            try:
                sid = ps.GetShader(stage_enum)
                if not sid or int(sid) == 0:
                    continue

                entries = ctrl.GetShaderEntryPoints(sid)
                if not entries:
                    continue
                selection = _pipeline_shader_entry_selection(
                    ps, stage_enum, stage_name, sid, entries)
                selected_entry = selection.get("entry")
                if selected_entry is None:
                    result["shaderSelection_%s" % stage_name] = (
                        _shader_entry_selection_failure(
                            selection, sid, pid, stage_name))
                    continue
                selected_entry_name = str(
                    getattr(selected_entry, "name", "") or "")
                refl = ctrl.GetShader(pid, sid, selected_entry)
                if not refl:
                    continue
                identity_failure = _shader_reflection_identity_failure(
                    refl, selected_entry, sid, pid, stage_name, selection)
                if identity_failure is not None:
                    result["shaderSelection_%s" % stage_name] = identity_failure
                    continue
            except Exception as e:
                result["shaderError_%s" % stage_name] = str(e)[:200]
                continue

            # 2. Extract cbuffer variable values
            cbuffers_info = []

            # Get cbuffer bindings
            cbufs_bound = None
            try:
                cbufs_bound = ps.GetConstantBuffers(stage_enum, False)
            except Exception:
                pass  # Vulkan: no GetConstantBuffers, use null resource fallback

            for cb_idx, cb in enumerate(getattr(refl, 'constantBlocks', [])):
                cb_name = getattr(cb, 'name', 'cbuffer%d' % cb_idx)
                cb_info = {"name": cb_name, "index": cb_idx, "stage": stage_name}

                try:
                    buf_vars = None
                    # Try with bound resource (8-arg version)
                    if cbufs_bound and cb_idx < len(cbufs_bound):
                        b = cbufs_bound[cb_idx]
                        binding_offset, binding_size = _lighting_cbuffer_window(b)
                        b_rid = rd.ResourceId()
                        if hasattr(b, 'descriptor') and hasattr(b.descriptor, 'resource'):
                            b_rid = b.descriptor.resource
                        elif hasattr(b, 'resource'):
                            b_rid = b.resource
                        if binding_size > 0:
                            try:
                                buf_vars = ctrl.GetCBufferVariableContents(
                                    pid, sid, stage_enum, selected_entry_name,
                                    cb_idx, b_rid, binding_offset, binding_size)
                            except Exception:
                                pass

                    # Fallback with null resource
                    if not buf_vars:
                        try:
                            null_rid = rd.ResourceId()
                            buf_vars = ctrl.GetCBufferVariableContents(
                                pid, sid, stage_enum, selected_entry_name,
                                cb_idx, null_rid, 0, 0)
                        except Exception:
                            pass

                    if buf_vars:
                        import struct as _struct_cb

                        # Try to read raw buffer data for value extraction
                        raw_data = None
                        buf_debug = {}
                        if cbufs_bound and cb_idx < len(cbufs_bound):
                            b = cbufs_bound[cb_idx]
                            b_rid = None
                            if hasattr(b, 'descriptor') and hasattr(b.descriptor, 'resource'):
                                b_rid = b.descriptor.resource
                            elif hasattr(b, 'resource'):
                                try:
                                    if 0 < int(b.resource) < 10000000:
                                        b_rid = b.resource
                                except Exception:
                                    pass
                            if b_rid and int(b_rid) != 0:
                                try:
                                    raw_data, raw_offset, raw_size = \
                                        _read_lighting_cbuffer_data(ctrl, b_rid, b)
                                    buf_debug["rid"] = int(b_rid)
                                    buf_debug["byteOffset"] = raw_offset
                                    buf_debug["requestedBytes"] = raw_size
                                    buf_debug["rawBytes"] = len(raw_data) if raw_data else 0
                                except Exception:
                                    pass

                        # If raw buffer data available, dump all float4 values
                        if raw_data and len(raw_data) >= 16:
                            float4s = []
                            for off in range(0, min(len(raw_data), 2048) - 15, 16):
                                try:
                                    x, y, z, w = _struct_cb.unpack_from("<ffff", raw_data, off)
                                    float4s.append([round(x, 6), round(y, 6), round(z, 6), round(w, 6)])
                                except Exception:
                                    break
                            cb_info["rawFloat4s"] = float4s
                            cb_info["rawFloat4Count"] = len(float4s)

                        cb_info["bufferDebug"] = buf_debug

                        light_vars = []
                        shadow_vars = []
                        ambient_vars = []
                        all_vars = []

                        for v in buf_vars:
                            vd = _var_dict(v)
                            vname = vd.get("name", "").lower()

                            # Extract values from raw buffer if _var_dict didn't get them
                            if "float" not in vd and raw_data and hasattr(v, 'byteOffset'):
                                off = v.byteOffset
                                cols = getattr(v, 'columns', 0)
                                rows = getattr(v, 'rows', 0)
                                count = max(cols, 1) * max(rows, 1)
                                if count > 0 and off + count * 4 <= len(raw_data):
                                    try:
                                        vals = list(_struct_cb.unpack_from("<%df" % count, raw_data, off))
                                        # Trim trailing zeros
                                        while vals and vals[-1] == 0.0:
                                            vals.pop()
                                        if vals:
                                            vd["float"] = [round(x, 6) for x in vals]
                                    except Exception:
                                        pass

                            # Also extract member values from raw buffer
                            if "members" in vd and raw_data:
                                for mi, m in enumerate(vd["members"]):
                                    if "float" not in m:
                                        mv = v.members[mi] if hasattr(v, 'members') and mi < len(v.members) else None
                                        if mv and hasattr(mv, 'byteOffset'):
                                            moff = mv.byteOffset
                                            mcols = getattr(mv, 'columns', 4)
                                            mrows = getattr(mv, 'rows', 1)
                                            mcount = max(mcols, 1) * max(mrows, 1)
                                            if mcount > 0 and moff + mcount * 4 <= len(raw_data):
                                                try:
                                                    mvals = list(_struct_cb.unpack_from("<%df" % mcount, raw_data, moff))
                                                    while mvals and mvals[-1] == 0.0:
                                                        mvals.pop()
                                                    if mvals:
                                                        m["float"] = [round(x, 6) for x in mvals]
                                                except Exception:
                                                    pass

                            vals = vd.get("float", [])

                            # Auto-classify by variable name
                            category = None
                            if any(k in vname for k in ['light', 'sun', 'direction', 'dir']):
                                category = "light"
                            elif any(k in vname for k in ['shadow', 'cascade', 'bias']):
                                category = "shadow"
                            elif any(k in vname for k in ['ambient', 'env', 'sh', 'ibl', 'probe', 'gi']):
                                category = "ambient"
                            elif any(k in vname for k in ['color', 'colour', 'intensity',
                                                           'atten', 'range', 'radius', 'falloff']):
                                category = "light_param"

                            # Heuristic for anonymous ANGLE variables (_childN)
                            if category is None and vname.startswith('_child'):
                                has_members = "members" in vd
                                member_count = len(vd.get("members", []))

                                # float4[4] = likely SH coefficients or shadow matrix
                                if member_count == 4:
                                    category = "ambient_or_matrix"
                                # float4[6] = likely light array (pos/color/dir/atten per light)
                                elif member_count == 6:
                                    category = "light_array"
                                # float4[8] = likely shadow cascade matrix
                                elif member_count == 8:
                                    category = "shadow_matrix"
                                # float4[2] = likely shadow atlas UV
                                elif member_count == 2:
                                    category = "shadow_param"
                                # Scalar/vector by value heuristic
                                elif not has_members and vals:
                                    if len(vals) >= 3:
                                        mag = sum(v2*v2 for v2 in vals[:3]) ** 0.5
                                        if 0.95 < mag < 1.05:
                                            category = "light_direction"
                                        elif all(0 <= v2 <= 2.0 for v2 in vals[:3]) and sum(vals[:3]) > 0.01:
                                            category = "color_or_light"

                            if category:
                                vd["_category"] = category
                                if "light" in category:
                                    light_vars.append(vd)
                                elif "shadow" in category:
                                    shadow_vars.append(vd)
                                elif "ambient" in category:
                                    ambient_vars.append(vd)

                            all_vars.append(vd)

                        cb_info["varCount"] = len(all_vars)
                        cb_info["variables"] = all_vars[:60]
                        if light_vars:
                            cb_info["lightVars"] = light_vars
                        if shadow_vars:
                            cb_info["shadowVars"] = shadow_vars
                        if ambient_vars:
                            cb_info["ambientVars"] = ambient_vars
                    else:
                        cb_info["note"] = "no variables returned"
                except Exception as e:
                    cb_info["error"] = str(e)[:200]

                cbuffers_info.append(cb_info)

            if cbuffers_info:
                result.setdefault("cbuffers", {})[stage_name] = cbuffers_info

            # 3. Detect lighting model from shader disassembly
            if stage_name == "fragment":
                try:
                    targets = ctrl.GetDisassemblyTargets(True)
                    spirv_target = None
                    for t in targets:
                        if 'SPIR-V' in t:
                            spirv_target = t
                            break
                    if spirv_target:
                        code = ctrl.DisassembleShader(pid, refl, spirv_target)
                        if code:
                            result["lightingModel"] = _detect_lighting_model(code)
                except Exception as e:
                    result["lightingModelError"] = str(e)[:200]

            # 4. Identify shadow maps and env maps from bound textures
            try:
                tex_lookup = {}
                for t in ctrl.GetTextures():
                    tex_lookup[int(t.resourceId)] = t

                try:
                    ro_bindings = ps.GetReadOnlyResources(stage_enum)
                except Exception:
                    ro_bindings = None

                shadow_maps = []
                env_maps = []

                for i, ro in enumerate(getattr(refl, 'readOnlyResources', [])):
                    if not getattr(ro, 'isTexture', False):
                        continue
                    ro_name = getattr(ro, 'name', 'tex%d' % i)
                    bound_rid = _resolve_bound_resource(ro_bindings, i, ctrl)
                    tex = tex_lookup.get(bound_rid)
                    if not tex:
                        continue

                    fmt = _fmt_str(tex.format)
                    is_depth = any(k in fmt.lower() for k in ['depth', 'd32', 'd24', 'd16'])
                    is_cubemap = tex.arraysize == 6

                    entry = {"slot": i, "name": ro_name, "resourceId": bound_rid,
                             "width": tex.width, "height": tex.height, "format": fmt}

                    if is_depth:
                        entry["role"] = "shadow_map"
                        entry["roleInference"] = {
                            "value": "shadow_map",
                            "basis": "texture-format depth heuristic",
                            "confidence": "low",
                            "observed": False,
                        }
                        shadow_maps.append(entry)
                    elif is_cubemap:
                        entry["role"] = "environment_cubemap"
                        entry["roleInference"] = {
                            "value": "environment_cubemap",
                            "basis": "six-array-slice cubemap heuristic",
                            "confidence": "low",
                            "observed": False,
                        }
                        env_maps.append(entry)

                if shadow_maps:
                    result["shadowMaps"] = shadow_maps
                if env_maps:
                    result["environmentMaps"] = env_maps
            except Exception as e:
                result["textureAnalysisError_%s" % stage_name] = str(e)[:200]

        return result

    return _replay(_do)


def _detect_lighting_model(code):
    """Detect lighting model from shader disassembly."""
    info = {"model": "unknown", "features": []}
    code_lower = code.lower() if code else ""

    # PBR indicators
    if any(k in code_lower for k in ['ggx', 'brdf', 'metallic', 'roughness', 'pbr',
                                       'cooktorrance', 'smith', 'schlick', 'beckmann']):
        info["model"] = "PBR"
    elif any(k in code_lower for k in ['blinnphong', 'blinn', 'phong', 'specular_power']):
        info["model"] = "Blinn-Phong"
    elif any(k in code_lower for k in ['lambert', 'diffuse_only']):
        info["model"] = "Lambert"
    elif 'inversesqrt' in code_lower and 'dot' in code_lower:
        info["model"] = "PBR (inferred)"  # GGX uses InverseSqrt + Dot patterns

    # Feature detection
    if 'shadow' in code_lower or 'drefexplicitlod' in code_lower or 'shadowmap' in code_lower:
        info["features"].append("shadow_mapping")
    if any(k in code_lower for k in ['cascade', 'csm']):
        info["features"].append("cascaded_shadow_maps")
    if any(k in code_lower for k in ['subsurface', 'sss', 'scattering']):
        info["features"].append("subsurface_scattering")
    if any(k in code_lower for k in ['fresnel', 'schlick']):
        info["features"].append("fresnel")
    if any(k in code_lower for k in ['envmap', 'cubemap', 'reflection', 'imagesampleexplicitlod']):
        info["features"].append("environment_reflection")
    if 'ao' in code_lower or 'occlusion' in code_lower:
        info["features"].append("ambient_occlusion")
    if any(k in code_lower for k in ['emissive', 'emission', 'glow', 'bloom']):
        info["features"].append("emissive")
    if any(k in code_lower for k in ['normalmap', 'tangent', 'bitangent', 'tbn']):
        info["features"].append("normal_mapping")

    # Count light loop iterations (look for while/for patterns with light index)
    if 'while' in code_lower and ('child13' in code_lower or 'child14' in code_lower or 'light' in code_lower):
        info["features"].append("multi_light_loop")

    return info


def _parse_light_variables(buf_vars):
    """Parse cbuffer variables and extract lighting-related values."""
    result = {"directionalLights": [], "pointLights": [], "parameters": []}

    for v in buf_vars:
        var_data = _var_dict(v)
        name = var_data.get("name", "")

        # Try to extract float values
        vals = None
        if "value" in var_data:
            val = var_data["value"]
            if isinstance(val, (list, tuple)):
                vals = [float(x) for x in val if isinstance(x, (int, float))]
            elif isinstance(val, dict):
                for k in ["f32v", "f", "x", "r"]:
                    if k in val:
                        v2 = val[k]
                        if isinstance(v2, (list, tuple)):
                            vals = [float(x) for x in v2[:4]]
                        break

        if vals:
            var_data["floatValues"] = vals[:4]

        result["parameters"].append(var_data)

    return result


def _analyze_cbuffer_lighting(cb_data, cb_name, cb_bind, stage_name):
    """Heuristic analysis of raw cbuffer data for lighting parameters."""
    import struct as _struct

    info = {"name": cb_name, "binding": cb_bind, "stage": stage_name, "size": len(cb_data)}

    # Read all float4 values
    float4s = []
    for off in range(0, len(cb_data) - 15, 16):
        try:
            x, y, z, w = _struct.unpack_from("<ffff", cb_data, off)
            float4s.append({"offset": off, "values": [x, y, z, w]})
        except Exception:
            break

    # Heuristic: identify potential light directions (unit vectors)
    directions = []
    colors = []
    matrices = []

    for f4 in float4s:
        x, y, z, w = f4["values"]
        mag = (x * x + y * y + z * z) ** 0.5

        # Unit vector = likely direction
        if 0.95 < mag < 1.05 and abs(w) < 0.1:
            directions.append({"offset": f4["offset"], "direction": [round(x, 4), round(y, 4), round(z, 4)],
                               "hint": "possible light direction"})

        # RGB color (0-1 range, positive)
        elif 0 <= x <= 5 and 0 <= y <= 5 and 0 <= z <= 5 and (x + y + z) > 0.01:
            if x != y or y != z:  # Not a scalar
                colors.append({"offset": f4["offset"], "color": [round(x, 4), round(y, 4), round(z, 4)],
                                "w": round(w, 4), "hint": "possible light color"})

    info["potentialDirections"] = directions[:10]
    info["potentialColors"] = colors[:20]
    info["totalFloat4s"] = len(float4s)

    return info


def _identify_drawcalls(params):
    """Identify DrawCall content by rendering RT thumbnails for each action.

    For each DrawCall in the specified range, captures the render target BEFORE and AFTER
    the draw, computes a pixel diff, and saves a cropped thumbnail showing ONLY what that
    DrawCall contributed. Also collects shader IDs, bound texture info, and vertex AABB.

    Args:
        event_id_min: Start of event range (default 0).
        event_id_max: End of event range (default 999999).
        output_dir: Directory to save per-DrawCall thumbnails (optional).
        render_target: Override RT resource ID (auto-detected if omitted).
    Returns:
        List of DrawCall identifications with thumbnails and metadata.
    """
    eid_min = params.get("event_id_min", 0)
    eid_max = params.get("event_id_max", 999999)
    output_dir = params.get("output_dir", "")
    rt_override = params.get("render_target", 0)

    def _do(ctrl):
        import struct as _struct

        # Get all draw actions in range
        all_actions = ctrl.GetRootActions()
        actions = []

        def _collect(act_list):
            for a in act_list:
                eid = a.eventId
                if eid < eid_min or eid > eid_max:
                    if a.children:
                        _collect(a.children)
                    continue
                flags = int(a.flags)
                # Check if it's an actual draw (has indices)
                if a.numIndices > 0 and (flags & 0x2):  # ActionFlags.Drawcall = 0x2
                    actions.append(a)
                if a.children:
                    _collect(a.children)

        _collect(all_actions)

        if not actions:
            return {"error": "No draw actions found in range %d-%d" % (eid_min, eid_max)}

        # Determine render target
        rt_id = rt_override
        if not rt_id:
            # Use the first action's output RT
            _set_frame_event(ctrl, actions[0].eventId, True)
            ps = ctrl.GetPipelineState()
            outs = ps.GetOutputTargets()
            if outs:
                for o in outs:
                    rid = 0
                    if hasattr(o, 'resource'):
                        rid = int(o.resource)
                    elif hasattr(o, 'resourceId'):
                        rid = int(o.resourceId)
                    # Vulkan: UsedDescriptor style
                    if rid == 0 and hasattr(o, 'descriptor'):
                        desc = o.descriptor
                        if hasattr(desc, 'resource'):
                            rid = int(desc.resource)
                    if rid != 0:
                        rt_id = rid
                        break

        if not rt_id:
            return {"error": "Could not determine render target"}

        # Get RT dimensions
        tex_info = None
        for t in ctrl.GetTextures():
            if int(t.resourceId) == rt_id:
                tex_info = t
                break

        if not tex_info:
            return {"error": "Render target %d not found" % rt_id}

        rt_width = tex_info.width
        rt_height = tex_info.height

        # Create output directory
        if output_dir:
            if not os.path.exists(output_dir):
                os.makedirs(output_dir)

        results = []
        prev_pixels = None

        # For each action, capture RT state and diff
        for idx, action in enumerate(actions):
            eid = action.eventId
            entry = {
                "eventId": eid,
                "name": action.name if hasattr(action, 'name') else "Action",
                "numIndices": action.numIndices,
                "numInstances": action.numInstances,
                "triangles": action.numIndices // 3,
            }

            # Set event to JUST BEFORE this draw (previous event)
            if idx > 0:
                prev_eid = actions[idx - 1].eventId
            else:
                # Find the event just before this action
                prev_eid = max(1, eid - 1)

            # Capture RT AFTER this draw
            _set_frame_event(ctrl, eid, True)

            # Get shader info
            ps = ctrl.GetPipelineState()
            vs_id = ps.GetShader(rd.ShaderStage.Vertex)
            fs_id = ps.GetShader(rd.ShaderStage.Fragment)
            entry["vertexShader"] = int(vs_id) if vs_id else 0
            entry["fragmentShader"] = int(fs_id) if fs_id else 0

            # Get bound texture count and first texture info
            pid = _get_pipeline_obj(ps, ctrl)
            tex_bindings = []
            try:
                refl = None
                if fs_id and int(fs_id) != 0:
                    ep = list(ctrl.GetShaderEntryPoints(fs_id) or [])
                    selection = _pipeline_shader_entry_selection(
                        ps, rd.ShaderStage.Fragment, "fragment", fs_id, ep)
                    selected_entry = selection.get("entry")
                    if selected_entry is not None:
                        refl = ctrl.GetShader(pid, fs_id, selected_entry)
                        if (refl is not None and
                                _shader_reflection_identity_failure(
                                    refl, selected_entry, fs_id, pid,
                                    "fragment", selection) is not None):
                            refl = None
                if refl:
                    ro_bindings = None
                    try:
                        ro_bindings = ps.GetReadOnlyResources(rd.ShaderStage.Fragment)
                    except Exception:
                        pass

                    tex_lookup = {}
                    for t2 in ctrl.GetTextures():
                        tex_lookup[int(t2.resourceId)] = t2

                    for i, ro in enumerate(getattr(refl, 'readOnlyResources', [])):
                        if not getattr(ro, 'isTexture', False):
                            continue
                        ro_name = getattr(ro, 'name', 'tex%d' % i)
                        bound_rid = _resolve_bound_resource(ro_bindings, i, ctrl)
                        t_info = tex_lookup.get(bound_rid)
                        tex_bindings.append({
                            "slot": i,
                            "name": ro_name,
                            "resourceId": bound_rid,
                            "width": t_info.width if t_info else 0,
                            "height": t_info.height if t_info else 0,
                        })
            except Exception:
                pass

            entry["textureCount"] = len(tex_bindings)
            entry["textures"] = tex_bindings[:5]  # First 5 only

            # Try to get vertex AABB from post-VS data
            try:
                mesh_out = ctrl.GetPostVSData(0, 0, rd.MeshDataStage.VSOut)
                if mesh_out and mesh_out.numIndices > 0:
                    vb_rid = mesh_out.vertexResourceId
                    vb_stride = mesh_out.vertexByteStride
                    vb_off = mesh_out.vertexByteOffset
                    n_verts = min(mesh_out.numIndices, 5000)
                    if vb_rid and int(vb_rid) != 0 and vb_stride >= 16:
                        vb_data = ctrl.GetBufferData(vb_rid, vb_off, n_verts * vb_stride)
                        if vb_data and len(vb_data) >= vb_stride:
                            xs, ys, zs = [], [], []
                            actual = min(n_verts, len(vb_data) // vb_stride)
                            for vi in range(actual):
                                base = vi * vb_stride
                                if base + 16 <= len(vb_data):
                                    x, y, z, w = _struct.unpack_from("<ffff", vb_data, base)
                                    if w != 0 and abs(x) < 1e6 and abs(y) < 1e6:
                                        # Clip space -> NDC -> screen
                                        ndc_x = x / w
                                        ndc_y = y / w
                                        screen_x = (ndc_x * 0.5 + 0.5) * rt_width
                                        screen_y = (0.5 - ndc_y * 0.5) * rt_height
                                        xs.append(screen_x)
                                        ys.append(screen_y)
                                        zs.append(z / w if w != 0 else 0)
                            if xs:
                                entry["screenBBox"] = {
                                    "minX": int(max(0, min(xs))),
                                    "minY": int(max(0, min(ys))),
                                    "maxX": int(min(rt_width, max(xs))),
                                    "maxY": int(min(rt_height, max(ys))),
                                    "depth": round(sum(zs) / len(zs), 4),
                                }
                                entry["screenCoverage"] = round(
                                    (max(xs) - min(xs)) * (max(ys) - min(ys)) / (rt_width * rt_height) * 100, 2
                                )
            except Exception:
                pass

            # Save RT thumbnail if output_dir specified
            if output_dir:
                thumb_path = os.path.join(output_dir, "eid_%04d.png" % eid)
                try:
                    save = rd.TextureSave()
                    save.resourceId = rd.ResourceId()
                    # Set the ID value
                    id_obj = save.resourceId
                    # Copy from the actual texture resourceId
                    for t3 in ctrl.GetTextures():
                        if int(t3.resourceId) == rt_id:
                            save.resourceId = t3.resourceId
                            break
                    save.mip = 0
                    save.destType = rd.FileType.PNG
                    ret = ctrl.SaveTexture(save, thumb_path)
                    if hasattr(ret, 'code') and ret.code == rd.ResultCode.Succeeded:
                        entry["thumbnail"] = thumb_path
                    else:
                        entry["thumbnailError"] = str(ret)[:100]
                except Exception as e2:
                    entry["thumbnailError"] = str(e2)[:100]

            results.append(entry)

        # Group by shader
        shader_groups = {}
        for r in results:
            key = "%d/%d" % (r["vertexShader"], r["fragmentShader"])
            if key not in shader_groups:
                shader_groups[key] = []
            shader_groups[key].append(r["eventId"])

        return {
            "renderTarget": rt_id,
            "rtSize": "%dx%d" % (rt_width, rt_height),
            "actionCount": len(results),
            "shaderGroups": shader_groups,
            "actions": results,
        }

    return _replay(_do)


def _debug_vulkan_bindings(params):
    """Debug tool: dump Vulkan descriptor set bindings raw structure."""
    event_id = params.get("event_id")
    stage_name = params.get("stage", "fragment")
    if event_id is None:
        raise ValueError("event_id required")

    stage_map = {
        "vertex": rd.ShaderStage.Vertex, "fragment": rd.ShaderStage.Fragment,
        "pixel": rd.ShaderStage.Fragment, "geometry": rd.ShaderStage.Geometry,
        "compute": rd.ShaderStage.Compute,
        "hull": rd.ShaderStage.Hull, "domain": rd.ShaderStage.Domain,
        "tess_ctrl": rd.ShaderStage.Hull, "tess_eval": rd.ShaderStage.Domain,
    }
    stage = stage_map.get(stage_name.lower(), rd.ShaderStage.Fragment)

    def _introspect(obj, depth=0, max_depth=3):
        """Recursively dump object attributes."""
        if depth >= max_depth:
            return str(obj)[:200]
        if obj is None:
            return None
        if isinstance(obj, (int, float, str, bool)):
            return obj
        # Try list-like first (before int conversion)
        try:
            if hasattr(obj, '__len__') and hasattr(obj, '__getitem__'):
                items = []
                for i in range(min(len(obj), 20)):
                    items.append(_introspect(obj[i], depth + 1, max_depth))
                return {"_list": items, "_len": len(obj)}
        except Exception:
            pass
        # For SWIG objects, dump all non-callable attributes
        result = {"_type": type(obj).__name__}
        attrs_found = False
        for attr in dir(obj):
            if attr.startswith('_'):
                continue
            try:
                val = getattr(obj, attr)
                if callable(val):
                    continue
                attrs_found = True
                result[attr] = _introspect(val, depth + 1, max_depth)
            except Exception as e:
                result[attr] = "ERR:%s" % str(e)[:100]
        # If no useful attrs found, try int/str fallback
        if not attrs_found:
            try:
                result["_int"] = int(obj)
            except (TypeError, ValueError):
                pass
            result["_str"] = str(obj)[:200]
        return result

    def _do(ctrl):
        _set_frame_event(ctrl, int(event_id), True)
        ps = ctrl.GetPipelineState()
        info = {"eventId": int(event_id), "api": str(ctrl.GetAPIProperties().pipelineType)}

        # 1. GetReadOnlyResources
        try:
            ro = ps.GetReadOnlyResources(stage)
            ro_dump = []
            for i, b in enumerate(ro):
                ro_dump.append(_introspect(b, 0, 4))
            info["readOnlyResources"] = {"count": len(ro), "items": ro_dump[:15]}
        except Exception as e:
            info["readOnlyResources"] = {"error": str(e)}

        # 2. GetReadWriteResources
        try:
            rw = ps.GetReadWriteResources(stage)
            info["readWriteResourceCount"] = len(rw)
        except Exception as e:
            info["readWriteResources"] = {"error": str(e)}

        # 3. Try Vulkan-specific pipeline state
        pipe = None
        try:
            pipe = ps.GetVulkanPipelineState()
            info["hasVulkanState"] = True
        except Exception:
            info["hasVulkanState"] = False

        if pipe:
            # Dump descriptor sets
            try:
                desc_sets = pipe.graphics.descriptorSets if hasattr(pipe, 'graphics') else []
                ds_dump = []
                for ds_idx, ds in enumerate(desc_sets):
                    ds_info = _introspect(ds, 0, 5)
                    ds_dump.append(ds_info)
                info["descriptorSets"] = {"count": len(desc_sets), "sets": ds_dump[:5]}
            except Exception as e:
                info["descriptorSets"] = {"error": str(e)}

            # Dump top-level pipe attributes
            try:
                pipe_attrs = {}
                for attr in dir(pipe):
                    if attr.startswith('_'):
                        continue
                    try:
                        val = getattr(pipe, attr)
                        if callable(val):
                            continue
                        pipe_attrs[attr] = type(val).__name__
                    except Exception:
                        pass
                info["pipelineAttrs"] = pipe_attrs
            except Exception:
                pass

        # 4. Try GetDescriptorAccess
        try:
            accesses = ctrl.GetDescriptorAccess()
            acc_dump = []
            for a in accesses[:20]:
                acc_dump.append(_introspect(a, 0, 3))
            info["descriptorAccess"] = {"count": len(accesses), "items": acc_dump}
        except Exception as e:
            info["descriptorAccess"] = {"error": str(e), "type": type(e).__name__}

        # 5. Shader reflection readOnlyResources
        sid = ps.GetShader(stage)
        if sid and int(sid) != 0:
            pid = _get_pipeline_obj(ps, ctrl)
            entries = ctrl.GetShaderEntryPoints(sid)
            if entries:
                selection = _pipeline_shader_entry_selection(
                    ps, stage, stage_name, sid, entries)
                selected_entry = selection.get("entry")
                if selected_entry is None:
                    info["shaderReflection"] = _shader_entry_selection_failure(
                        selection, sid, pid, stage_name)
                    return info
                refl = ctrl.GetShader(pid, sid, selected_entry)
                identity_failure = (
                    _shader_reflection_identity_failure(
                        refl, selected_entry, sid, pid, stage_name, selection)
                    if refl is not None else None)
                if identity_failure is not None:
                    info["shaderReflection"] = identity_failure
                    return info
                if refl:
                    ro_res = getattr(refl, 'readOnlyResources', [])
                    refl_dump = []
                    for i, r in enumerate(ro_res):
                        refl_dump.append(_introspect(r, 0, 3))
                    info["shaderReflection"] = {
                        "readOnlyResourceCount": len(ro_res),
                        "items": refl_dump[:15]
                    }

        return info

    return _replay(_do)


def _resource_export_capture_binding(params):
    """Freeze one resource-export request to the active capture lifecycle."""

    if not _request_capture_loaded():
        raise RuntimeError("No capture is loaded in RenderDoc")
    expected_session = str(
        params.get("expected_capture_session_id",
                   params.get("__replaylab_expected_capture_session_id", "")) or "")
    request_session_id = _request_capture_session_id()
    if (not request_session_id or expected_session != request_session_id or
            not re.match(r"^[0-9a-f]{32}$", expected_session)):
        raise RuntimeError(
            "The active capture session changed before resource export")
    expected_capture_id = str(params.get("expected_capture_id", "") or "").strip().lower()
    if expected_capture_id:
        expected_capture_id = _require_capture_identity(expected_capture_id)
    return expected_capture_id, expected_session


def _resource_export_shader_evidence(event_id, stage_names):
    evidence = {}
    for stage_name in stage_names:
        try:
            evidence[stage_name] = _get_shader_info({
                "event_id": int(event_id),
                "stage": stage_name,
            })
        except Exception as exc:
            evidence[stage_name] = {
                "status": "unavailable",
                "error": str(exc)[:2048],
            }
    return evidence


def _resource_export_raw_evidence(ctrl, event_id, stage_names, shader_evidence):
    """Read exact native shader blobs and bounded CBuffer byte windows."""

    _set_frame_event(ctrl, int(event_id), True)
    pipeline = ctrl.GetPipelineState()
    pipeline_id = _get_pipeline_obj(pipeline, ctrl)
    stages = dict(_available_shader_stages(stage_names))
    result = {"shaderRaw": {}, "cbufferRaw": {}}
    resources = []
    try:
        resources.extend(list(ctrl.GetBuffers() or []))
    except Exception:
        pass
    try:
        resources.extend(list(ctrl.GetResources() or []))
    except Exception:
        pass

    for stage_name in stage_names:
        stage = stages.get(stage_name)
        if stage is None:
            continue
        try:
            shader_id = pipeline.GetShader(stage)
            if not shader_id or int(shader_id) == 0:
                continue
            entries = list(ctrl.GetShaderEntryPoints(shader_id) or [])
            selection = _pipeline_shader_entry_selection(
                pipeline, stage, stage_name, shader_id, entries)
            selected_entry = selection.get("entry")
            if selected_entry is not None:
                reflection = ctrl.GetShader(
                    pipeline_id, shader_id, selected_entry)
                identity_failure = (
                    _shader_reflection_identity_failure(
                        reflection, selected_entry, shader_id, pipeline_id,
                        stage_name, selection)
                    if reflection is not None else None)
                if reflection is not None and identity_failure is None:
                    raw = _shader_raw_bytes(reflection)
                    if raw:
                        result["shaderRaw"][stage_name] = bytes(raw)
        except Exception:
            # The reflected identity and diagnostic remain in get_shader_info.
            pass

        stage_records = []
        stage_evidence = shader_evidence.get(stage_name, {})
        for index, block in enumerate(
                stage_evidence.get("constantBuffers", []) or []):
            if not isinstance(block, dict):
                continue
            resource_id = _safe_int(
                block.get("bufferId", block.get("bufferResourceId", 0)), 0)
            byte_offset = max(0, _safe_int(block.get("byteOffset", 0), 0))
            reflected_size = max(0, _safe_int(
                block.get("byteSize", block.get("size", 0)), 0))
            bound_size = max(0, _safe_int(block.get("boundByteSize", 0), 0))
            byte_size = reflected_size
            if bound_size:
                byte_size = min(byte_size, bound_size) if byte_size else bound_size
            record = {
                "constantBlockIndex": index,
                "bufferResourceId": resource_id,
                "byteOffset": byte_offset,
                "byteSize": byte_size,
            }
            if not resource_id:
                record["reason"] = (
                    "constant block is push/root/inline data or has no buffer-backed resource")
                stage_records.append(record)
                continue
            if byte_size <= 0 or byte_size > 64 * 1024 * 1024:
                record["reason"] = "constant buffer byte window is empty or exceeds 64 MiB"
                stage_records.append(record)
                continue
            resource = _resource_id_lookup(resources, resource_id)
            if resource is None:
                record["reason"] = "constant buffer ResourceId is unavailable"
                stage_records.append(record)
                continue
            try:
                raw = bytes(ctrl.GetBufferData(
                    resource, byte_offset, byte_size) or b"")
                if len(raw) != byte_size:
                    record["reason"] = "RenderDoc returned a truncated constant buffer window"
                else:
                    record["data"] = raw
            except Exception as exc:
                record["reason"] = str(exc)[:2048]
            stage_records.append(record)
        if stage_records:
            result["cbufferRaw"][stage_name] = stage_records
    return result


def _inspect_resource_export(params):
    """Inspect exact EID-bound export inputs without writing an artifact."""

    capture_id, capture_session_id = _resource_export_capture_binding(params)
    request = _resource_export_protocol.validate_inspect_request(
        params, capture_id, capture_session_id)
    stages = _available_shader_stages()
    original_event = _request_visible_event_id(0)

    def _do(ctrl):
        _set_frame_event(ctrl, request["eventId"], True)
        return _resource_export_protocol.inspect_controller(
            ctrl, rd, request, stages)

    result = None
    try:
        result = _replay(_do)
        bound_stages = list(result.get("boundShaderStages", []) or [])
        evidence = _resource_export_shader_evidence(
            request["eventId"], bound_stages)
        result["shaderEvidence"] = {
            stage_name: _resource_export_protocol.condense_shader_evidence(value)
            for stage_name, value in evidence.items()
        }
    finally:
        # This path is also called directly by the built-in integration, where
        # the IPC request-level event tracker is not present. Fail closed if
        # the user's selected event cannot be restored exactly.
        _replay(lambda ctrl: _set_frame_event(ctrl, original_event, True))
    result["replayRestoration"] = {
        "originalEventId": original_event,
        "restoredEventId": original_event,
        "restored": True,
    }
    return result


def _capture_resource_export_bundle(params):
    """Capture one ticket-bound evidence bundle into a Host-managed directory."""

    capture_id, capture_session_id = _resource_export_capture_binding(params)
    request = _resource_export_protocol.validate_capture_request(
        params, capture_id, capture_session_id)
    stages = _available_shader_stages()
    original_event = _request_visible_event_id(0)

    def _capture(ctrl):
        _set_frame_event(ctrl, request["eventId"], True)
        return _resource_export_protocol.capture_controller(
            ctrl, rd, request, stages)

    state = None
    restored = False
    pending_error = None
    try:
        state = _replay(_capture)
        if _capture_session_id != request["captureSessionId"]:
            raise RuntimeError("Capture session changed during resource export")
        bound_stages = list(
            state.get("bundle", {}).get("boundShaderStages", []) or [])
        shader_evidence = _resource_export_shader_evidence(
            request["eventId"], bound_stages)

        def _raw(ctrl):
            return _resource_export_raw_evidence(
                ctrl, request["eventId"], bound_stages, shader_evidence)

        raw_evidence = _replay(_raw)
        _resource_export_protocol.attach_raw_evidence(
            state, shader_evidence, raw_evidence)
        if _capture_session_id != request["captureSessionId"]:
            raise RuntimeError("Capture session changed before resource export publication")
        _replay(lambda ctrl: _set_frame_event(ctrl, original_event, True))
        restored = True
        state.setdefault("bundle", {})["replayRestoration"] = {
            "originalEventId": original_event,
            "restoredEventId": original_event,
            "restored": True,
        }
        return _resource_export_protocol.finalize_capture(
            state, shader_evidence)
    except BaseException as error:
        # Foreground replay preemption intentionally derives from BaseException
        # so broad application error handlers cannot swallow it.  Resource
        # capture still owns a provisional bundle at this point, therefore its
        # cleanup contract must cover cancellation/preemption as well as normal
        # Exceptions.  Preserve the primary failure if cleanup also fails.
        pending_error = error
        if state is not None:
            try:
                _resource_export_protocol.cleanup_capture(state)
            except BaseException as cleanup_error:
                add_note = getattr(error, "add_note", None)
                if callable(add_note):
                    add_note(
                        "resource export provisional-bundle cleanup also failed: %r"
                        % (cleanup_error,)
                    )
        raise
    finally:
        if not restored:
            try:
                _replay(lambda ctrl: _set_frame_event(ctrl, original_event, True))
            except BaseException as restore_error:
                if pending_error is None:
                    raise
                add_note = getattr(pending_error, "add_note", None)
                if callable(add_note):
                    add_note(
                        "resource export replay-event restoration also failed: %r"
                        % (restore_error,)
                    )


def _export_drawcall(params):
    """Export a drawcall's shaders + textures to disk."""
    event_id = params.get("event_id")
    output_dir = params.get("output_dir")
    if event_id is None or not output_dir:
        raise ValueError("event_id and output_dir required")

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    result = {"eventId": int(event_id), "outputDir": output_dir, "files": []}

    for stage_name in ["vertex", "hull", "domain", "geometry", "fragment"]:
        try:
            info = _get_shader_info({"event_id": event_id, "stage": stage_name})
            if "error" in info:
                continue

            # Save disassembly
            if "disassembly" in info:
                for target, code in info["disassembly"].items():
                    if code and not code.startswith("Error"):
                        safe = target.replace(" ", "_").replace("/", "_")
                        fp = os.path.join(output_dir, "%s_%s.txt" % (stage_name, safe))
                        with open(fp, "w", encoding="utf-8") as f:
                            f.write(code)
                        result["files"].append(fp)

            # Save source files
            if "sourceFiles" in info:
                for sf in info["sourceFiles"]:
                    safe = sf["filename"].replace("/", "_").replace("\\", "_")
                    fp = os.path.join(output_dir, "%s_src_%s" % (stage_name, safe))
                    with open(fp, "w", encoding="utf-8") as f:
                        f.write(sf["contents"])
                    result["files"].append(fp)

            # Save bound textures as PNG (with CubeMap support)
            if "boundTextures" in info:
                for tex in info["boundTextures"]:
                    rid = tex.get("resourceId", 0)
                    if not rid:
                        continue
                    role = tex.get("role", "unknown")
                    safe_name = tex.get("name", "tex").replace(" ", "_")
                    fp = os.path.join(output_dir, "%s_slot%d_%s_%s.png" % (stage_name, tex["slot"], safe_name, role))
                    try:
                        save_result = _save_texture({"resource_id": rid, "output_path": fp})
                        # Handle CubeMap: multiple face files returned
                        if isinstance(save_result, dict):
                            if "savedFaces" in save_result:
                                for face in save_result["savedFaces"]:
                                    result["files"].append(face["path"])
                            elif "saved" in save_result:
                                result["files"].append(save_result["saved"])
                    except Exception:
                        pass
        except Exception as e:
            result.setdefault("errors", []).append("%s: %s" % (stage_name, str(e)))

    # Save summary JSON
    summary_fp = os.path.join(output_dir, "summary.json")
    with open(summary_fp, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2, ensure_ascii=False, default=str)
    result["files"].append(summary_fp)

    return result


def _export_to_unity(params):
    """Export a draw call's mesh (OBJ), textures (PNG), and Unity material JSON.

    This is the one-stop tool for bringing a RenderDoc draw call into Unity:
    - Exports the mesh as .obj (with positions, normals, UVs, indices)
    - Exports all bound textures as .png with role-based filenames
    - Generates a Unity-compatible material definition JSON
    - Generates a shader property mapping for Unity Standard/URP/Custom shaders
    """
    import struct as _struct
    import base64 as _b64

    event_id = params.get("event_id")
    output_dir = params.get("output_dir")
    mesh_name = params.get("mesh_name", "exported_mesh")
    if event_id is None or not output_dir:
        raise ValueError("event_id and output_dir required")

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    result = {
        "eventId": int(event_id),
        "outputDir": output_dir,
        "meshFile": None,
        "textures": [],
        "materialFile": None,
        "shaderInfo": None,
        "files": [],
    }

    def _do(ctrl):
        _set_frame_event(ctrl, int(event_id), True)
        ps = ctrl.GetPipelineState()

        # ============================================================
        # 1. EXPORT MESH AS OBJ
        # ============================================================
        mesh_data = None
        try:
            mesh_out = ctrl.GetPostVSData(0, 0, rd.MeshDataStage.VSOut)
            if mesh_out and mesh_out.numIndices > 0:
                mesh_data = _extract_mesh_obj(ctrl, ps, mesh_out, mesh_name, output_dir, event_id=event_id)
                if mesh_data:
                    result["meshFile"] = mesh_data["objPath"]
                    result["files"].append(mesh_data["objPath"])
                    if "fbxPath" in mesh_data:
                        result["fbxFile"] = mesh_data["fbxPath"]
                        result["files"].append(mesh_data["fbxPath"])
                    result["meshStats"] = {
                        "vertices": mesh_data.get("vertexCount", 0),
                        "triangles": mesh_data.get("triangleCount", 0),
                        "hasNormals": mesh_data.get("hasNormals", False),
                        "hasUVs": mesh_data.get("hasUVs", False),
                        "method": mesh_data.get("method", "unknown"),
                    }
        except Exception as e:
            import traceback as _tb
            result["meshError"] = str(e) + "\n" + _tb.format_exc()
            print("[MCP Bridge] export_to_unity mesh error: %s" % str(e))
            _tb.print_exc()

        # ============================================================
        # 2. COLLECT BOUND TEXTURE INFO (no file export — use save_texture / export_drawcall for that)
        # ============================================================
        pid = _get_pipeline_obj(ps, ctrl)
        tex_exports = []

        for stage_name, stage_enum in [("fragment", rd.ShaderStage.Fragment), ("vertex", rd.ShaderStage.Vertex)]:
            sid = ps.GetShader(stage_enum)
            if not sid or int(sid) == 0:
                continue
            entries = ctrl.GetShaderEntryPoints(sid)
            if not entries:
                continue
            selection = _pipeline_shader_entry_selection(
                ps, stage_enum, stage_name, sid, entries)
            selected_entry = selection.get("entry")
            if selected_entry is None:
                result.setdefault("shaderSelectionErrors", {})[stage_name] = (
                    _shader_entry_selection_failure(
                        selection, sid, pid, stage_name))
                continue
            refl = ctrl.GetShader(pid, sid, selected_entry)
            if not refl:
                continue
            identity_failure = _shader_reflection_identity_failure(
                refl, selected_entry, sid, pid, stage_name, selection)
            if identity_failure is not None:
                result.setdefault("shaderSelectionErrors", {})[
                    stage_name] = identity_failure
                continue

            name_lookup = {}
            for r in ctrl.GetResources():
                name_lookup[int(r.resourceId)] = r.name
            tex_lookup = {}
            for t in ctrl.GetTextures():
                tex_lookup[int(t.resourceId)] = t

            try:
                ro_bindings = ps.GetReadOnlyResources(stage_enum)
            except Exception:
                ro_bindings = None

            for i, ro in enumerate(getattr(refl, 'readOnlyResources', [])):
                if not getattr(ro, 'isTexture', False):
                    continue
                ro_name = getattr(ro, 'name', 'tex%d' % i)
                bound_rid = _resolve_bound_resource(ro_bindings, i, ctrl)

                if not bound_rid:
                    continue

                tex_info = tex_lookup.get(bound_rid, None)
                fmt_name = _fmt_str(tex_info.format) if tex_info else "unknown"
                role = _infer_role(ro_name, name_lookup.get(bound_rid, ""), fmt_name)

                tex_entry = {
                    "role": role,
                    "roleInference": {
                        "value": role,
                        "basis": "reflection/resource names and texture-format heuristic",
                        "confidence": "low",
                        "observed": False,
                    },
                    "slot": i,
                    "stage": stage_name,
                    "shaderVar": ro_name,
                    "resourceId": bound_rid,
                    "width": tex_info.width if tex_info else 0,
                    "height": tex_info.height if tex_info else 0,
                    "format": fmt_name,
                    "hint": "Use save_texture(resource_id=%d, output_path=...) to export" % bound_rid,
                }
                tex_exports.append(tex_entry)

        result["textures"] = tex_exports

        # ============================================================
        # 3. GET SHADER INFO FOR UNITY MATERIAL MAPPING
        # ============================================================
        shader_summary = {}
        for stage_name, stage_enum in [("fragment", rd.ShaderStage.Fragment), ("vertex", rd.ShaderStage.Vertex)]:
            sid = ps.GetShader(stage_enum)
            if not sid or int(sid) == 0:
                continue
            shader_summary[stage_name] = {"shaderId": int(sid)}
            entries = ctrl.GetShaderEntryPoints(sid)
            if entries:
                selection = _pipeline_shader_entry_selection(
                    ps, stage_enum, stage_name, sid, entries)
                selected_entry = selection.get("entry")
                if selected_entry is None:
                    shader_summary[stage_name].update(
                        _shader_entry_selection_failure(
                            selection, sid, pid, stage_name))
                    continue
                selected_entry_name = str(
                    getattr(selected_entry, "name", "") or "")
                refl2 = ctrl.GetShader(pid, sid, selected_entry)
                if refl2:
                    identity_failure = _shader_reflection_identity_failure(
                        refl2, selected_entry, sid, pid, stage_name, selection)
                    if identity_failure is not None:
                        shader_summary[stage_name].update(identity_failure)
                        continue
                    shader_summary[stage_name]["entryPoint"] = selected_entry_name
                    shader_summary[stage_name]["inputCount"] = len(refl2.inputSignature)
                    shader_summary[stage_name]["outputCount"] = len(refl2.outputSignature)
                    shader_summary[stage_name]["textureCount"] = sum(1 for r in refl2.readOnlyResources if r.isTexture)
                    shader_summary[stage_name]["cbufferCount"] = len(refl2.constantBlocks)

                    # Get cbuffer values for material parameters
                    cbufs = []
                    try:
                        cbufs_bound = ps.GetConstantBuffers(stage_enum, False)
                    except Exception:
                        cbufs_bound = None

                    for idx, cb in enumerate(refl2.constantBlocks):
                        cb_info = {"name": getattr(cb, 'name', ''), "size": getattr(cb, 'byteSize', 0)}
                        if cbufs_bound and idx < len(cbufs_bound):
                            b = cbufs_bound[idx]
                            try:
                                vrs = ctrl.GetCBufferVariableContents(
                                    pid, sid, stage_enum, selected_entry_name,
                                    idx, b.resource, getattr(b, 'byteOffset', 0), getattr(b, 'byteSize', 0))
                                cb_info["variables"] = [_var_dict(v) for v in vrs]
                            except Exception:
                                cb_info["variables"] = []
                        else:
                            try:
                                null_rid = rd.ResourceId()
                                vrs = ctrl.GetCBufferVariableContents(
                                    pid, sid, stage_enum, selected_entry_name,
                                    idx, null_rid, 0, 0)
                                cb_info["variables"] = [_var_dict(v) for v in vrs]
                            except Exception:
                                cb_info["variables"] = []
                        cbufs.append(cb_info)
                    shader_summary[stage_name]["constantBuffers"] = cbufs

        result["shaderInfo"] = shader_summary

        # ============================================================
        # 4. GENERATE UNITY MATERIAL DEFINITION JSON
        # ============================================================
        unity_mat = {
            "materialName": mesh_name + "_Mat",
            "shader": "Custom/EyePBR",  # Default, user can change
            "renderPipeline": "auto-detect",
            "textures": {},
            "floats": {},
            "colors": {},
            "vectors": {},
        }

        # Map exported textures to Unity material properties
        _ROLE_TO_UNITY = {
            "albedo": {"property": "_MainTex", "urp": "_BaseMap", "hdrp": "_BaseColorMap"},
            "normal": {"property": "_BumpMap", "urp": "_BumpMap", "hdrp": "_NormalMap"},
            "metallic": {"property": "_MetallicGlossMap", "urp": "_MetallicGlossMap", "hdrp": "_MaskMap"},
            "roughness": {"property": "_SpecGlossMap", "urp": "_SpecGlossMap", "hdrp": "_MaskMap"},
            "ao": {"property": "_OcclusionMap", "urp": "_OcclusionMap", "hdrp": "_MaskMap"},
            "emissive": {"property": "_EmissionMap", "urp": "_EmissionMap", "hdrp": "_EmissiveColorMap"},
            "specular": {"property": "_SpecGlossMap", "urp": "_SpecGlossMap", "hdrp": "_SpecularColorMap"},
            "height": {"property": "_ParallaxMap", "urp": "_ParallaxMap", "hdrp": "_HeightMap"},
            "opacity": {"property": "_MainTex", "urp": "_BaseMap", "hdrp": "_BaseColorMap"},
            "environment": {"property": "_EnvCubeMap", "urp": "_ReflectionCubeMap", "hdrp": "_ReflectionCubeMap"},
            "shadow": {"property": "_ShadowMap", "urp": "_ShadowMap", "hdrp": "_ShadowMap"},
            "lightmap": {"property": "_LightMap", "urp": "_LightMap", "hdrp": "_LightMap"},
            "detail": {"property": "_DetailAlbedoMap", "urp": "_DetailAlbedoMap", "hdrp": "_DetailMap"},
            "unknown": {"property": "_Texture_%d", "urp": "_Texture_%d", "hdrp": "_Texture_%d"},
        }

        slot_counter = 0
        for tex in tex_exports:
            role = tex["role"]
            mapping = _ROLE_TO_UNITY.get(role, _ROLE_TO_UNITY["unknown"])
            prop_name = mapping["property"]
            if "%d" in prop_name:
                prop_name = prop_name % slot_counter
                slot_counter += 1

            unity_mat["textures"][prop_name] = {
                "resourceId": tex["resourceId"],
                "role": role,
                "originalSlot": tex["slot"],
                "shaderVar": tex["shaderVar"],
                "dimensions": "%dx%d" % (tex["width"], tex["height"]),
                "urpProperty": mapping["urp"] if "%d" not in mapping["urp"] else mapping["urp"] % (slot_counter - 1),
                "hdrpProperty": mapping["hdrp"] if "%d" not in mapping["hdrp"] else mapping["hdrp"] % (slot_counter - 1),
            }

        # Extract key material floats from cbuffer
        if "fragment" in shader_summary and "constantBuffers" in shader_summary["fragment"]:
            for cb in shader_summary["fragment"]["constantBuffers"]:
                for v in cb.get("variables", []):
                    name = v.get("name", "")
                    floats = v.get("float", [])
                    if not floats:
                        continue
                    name_lower = name.lower()
                    if "roughness" in name_lower or "smooth" in name_lower:
                        unity_mat["floats"]["_Smoothness"] = 1.0 - floats[0] if floats else 0.5
                        unity_mat["floats"]["_Roughness"] = floats[0] if floats else 0.5
                    elif "metallic" in name_lower or "metal" in name_lower:
                        unity_mat["floats"]["_Metallic"] = floats[0] if floats else 0.0
                    elif "color" in name_lower and len(floats) >= 3:
                        unity_mat["colors"]["_Color"] = {"r": floats[0], "g": floats[1], "b": floats[2], "a": floats[3] if len(floats) > 3 else 1.0}
                    elif "emissive" in name_lower and len(floats) >= 3:
                        unity_mat["colors"]["_EmissionColor"] = {"r": floats[0], "g": floats[1], "b": floats[2], "a": floats[3] if len(floats) > 3 else 1.0}

        # Save Unity material JSON
        mat_path = os.path.join(output_dir, mesh_name + "_material.json")
        with open(mat_path, "w", encoding="utf-8") as f:
            json.dump(unity_mat, f, indent=2, ensure_ascii=False, default=str)
        result["materialFile"] = mat_path
        result["files"].append(mat_path)

        # ============================================================
        # 5. GENERATE UNITY IMPORT SCRIPT (C#)
        # ============================================================
        import_script = _generate_unity_import_script(mesh_name, unity_mat, tex_exports, output_dir)
        if import_script:
            result["importScript"] = import_script
            result["files"].append(import_script)

        # Save full summary
        summary_path = os.path.join(output_dir, mesh_name + "_unity_export.json")
        with open(summary_path, "w", encoding="utf-8") as f:
            json.dump(result, f, indent=2, ensure_ascii=False, default=str)
        result["files"].append(summary_path)

        return result

    return _replay(_do)


def _extract_mesh_obj(ctrl, ps, mesh_out, mesh_name, output_dir, event_id=None):
    """Extract mesh data using VBuffer + IBuffer (Model Extractor approach).

    This uses the pipeline state's vertex inputs and buffers directly,
    which is more reliable than GetPostVSData for Vulkan/ANGLE captures.
    Falls back to PostVS if VBuffer approach fails.
    """
    import struct as _struct
    import math as _math

    # ============================================================
    # Method 1: VBuffer + IBuffer + VertexInputs (from Model Extractor)
    # ============================================================
    vbs = ps.GetVBuffers()
    ib = ps.GetIBuffer()
    attrs = ps.GetVertexInputs()

    # Get draw action info for index count
    actions = ctrl.GetRootActions()
    action = None
    cur_eid = int(mesh_out.numIndices) if mesh_out else 0  # Will use actual action

    def _find_action(actions_list, eid_target):
        for a in actions_list:
            if a.eventId == eid_target:
                return a
            if a.children:
                found = _find_action(a.children, eid_target)
                if found:
                    return found
        return None

    # Try to get the action from the current event
    try:
        # The event was already set by caller
        cur_event = ctrl.GetD3D11PipelineState()  # Just to trigger, won't use
    except Exception:
        pass

    def _read_vertex_attr(attr, vbs_list, indices_list, num_components=None):
        """Read vertex attribute data from vertex buffer (from Model Extractor)."""
        vb_idx = attr.vertexBuffer
        if vb_idx >= len(vbs_list):
            return []

        vb_info = vbs_list[vb_idx]
        if vb_info.resourceId == rd.ResourceId.Null():
            return []

        try:
            buf_data = ctrl.GetBufferData(vb_info.resourceId, 0, 0)
        except Exception:
            return []

        fmt = attr.format
        comp_count = num_components or fmt.compCount
        stride = vb_info.byteStride

        if stride == 0 or not buf_data:
            return []

        max_idx = max(indices_list) if indices_list else 0

        comp_map = {
            (rd.CompType.Float, 2): ('e', 2),    # float16
            (rd.CompType.Float, 4): ('f', 4),    # float32
            (rd.CompType.UInt, 1):  ('B', 1),
            (rd.CompType.UInt, 2):  ('H', 2),
            (rd.CompType.UInt, 4):  ('I', 4),
            (rd.CompType.SInt, 1):  ('b', 1),
            (rd.CompType.SInt, 2):  ('h', 2),
            (rd.CompType.SInt, 4):  ('i', 4),
            (rd.CompType.UNorm, 1): ('B', 1),
            (rd.CompType.UNorm, 2): ('H', 2),
            (rd.CompType.SNorm, 1): ('b', 1),
            (rd.CompType.SNorm, 2): ('h', 2),
        }

        key = (fmt.compType, fmt.compByteWidth)
        if key not in comp_map:
            if fmt.compByteWidth == 2:
                char, size = 'e', 2
            else:
                return []
        else:
            char, size = comp_map[key]

        unpack_fmt = '<%d%s' % (comp_count, char)
        is_unorm = fmt.compType == rd.CompType.UNorm
        is_snorm = fmt.compType == rd.CompType.SNorm
        unorm_max = float((2 ** (fmt.compByteWidth * 8)) - 1) if is_unorm else 1.0
        snorm_max = float(2 ** (fmt.compByteWidth * 8 - 1) - 1) if is_snorm else 1.0

        results = []
        for vi in range(max_idx + 1):
            offset = vb_info.byteOffset + attr.byteOffset + vi * stride
            if offset + comp_count * size > len(buf_data):
                results.append(tuple([0.0] * comp_count))
                continue
            try:
                raw = _struct.unpack_from(unpack_fmt, buf_data, offset)
                if is_unorm:
                    vals = tuple(v / unorm_max for v in raw)
                elif is_snorm:
                    vals = tuple(max(-1.0, v / snorm_max) for v in raw)
                else:
                    vals = tuple(float(v) for v in raw)
                cleaned = []
                for v in vals:
                    fv = float(v)
                    if not _math.isfinite(fv) or abs(fv) > 1e9:
                        cleaned.append(0.0)
                    else:
                        cleaned.append(fv)
                results.append(tuple(cleaned))
            except Exception:
                results.append(tuple([0.0] * comp_count))

        return results

    mesh_extracted = False
    positions = []
    normals = []
    uvs = []
    indices = []
    has_normals = False
    has_uvs = False

    if attrs and vbs:
        # Identify attributes (same logic as Model Extractor)
        pos_attr = None
        normal_attr = None
        uv_attr = None

        for attr in attrs:
            if getattr(attr, 'perInstance', False):
                continue
            name_lower = attr.name.lower()

            if pos_attr is None:
                if 'sv_position' not in name_lower and any(k in name_lower for k in ['position', 'pos']):
                    pos_attr = attr
            if normal_attr is None and any(k in name_lower for k in ['normal', 'norm']):
                normal_attr = attr
            if uv_attr is None and any(k in name_lower for k in ['texcoord', 'uv', 'tex']):
                uv_attr = attr

        # Heuristic fallback for position
        if pos_attr is None:
            for attr in attrs:
                if getattr(attr, 'perInstance', False):
                    continue
                name_lower = attr.name.lower()
                if any(k in name_lower for k in ['normal', 'texcoord', 'uv', 'color', 'tangent', 'sv_']):
                    continue
                if attr.format.compCount >= 3 and attr.format.compType == rd.CompType.Float:
                    pos_attr = attr
                    break

        if pos_attr is not None:
            # ---- Read indices (with indexOffset + baseVertex) ----
            # Find the current action to get baseVertex and indexOffset
            _cur_action = None
            def _find_cur(al):
                for a in al:
                    if hasattr(a, 'eventId') and a.eventId == int(event_id):
                        return a
                    if a.children:
                        f = _find_cur(a.children)
                        if f:
                            return f
                return None
            _cur_action = _find_cur(ctrl.GetRootActions())

            num_indices = mesh_out.numIndices if mesh_out else 0
            base_vertex = 0
            if _cur_action:
                base_vertex = getattr(_cur_action, 'baseVertex', getattr(_cur_action, 'vertexOffset', 0))
                num_indices = _cur_action.numIndices

            raw_indices = []
            is_indexed = ib.resourceId != rd.ResourceId.Null()
            if is_indexed:
                try:
                    ib_data = ctrl.GetBufferData(ib.resourceId, 0, 0)
                    # indexOffset: number of indices to skip in the index buffer
                    index_offset = getattr(_cur_action, 'indexOffset', 0) if _cur_action else 0
                    idx_offset_bytes = index_offset * ib.byteStride + ib.byteOffset
                    for i in range(num_indices):
                        off = idx_offset_bytes + i * ib.byteStride
                        if ib.byteStride == 2 and off + 2 <= len(ib_data):
                            raw_indices.append(_struct.unpack_from('<H', ib_data, off)[0])
                        elif ib.byteStride == 4 and off + 4 <= len(ib_data):
                            raw_indices.append(_struct.unpack_from('<I', ib_data, off)[0])
                except Exception:
                    raw_indices = list(range(num_indices))
                # Apply baseVertex offset
                if base_vertex != 0:
                    raw_indices = [idx + base_vertex for idx in raw_indices]
            else:
                raw_indices = list(range(base_vertex, base_vertex + num_indices))

            # ---- Remap indices to compact 0-based ----
            unique_verts = []
            old_to_new = {}
            for old_idx in raw_indices:
                if old_idx not in old_to_new:
                    old_to_new[old_idx] = len(unique_verts)
                    unique_verts.append(old_idx)
            indices = [old_to_new[idx] for idx in raw_indices]

            if indices and unique_verts:
                # ---- Read vertex attrs by unique_verts (precise) ----
                def _read_attr_precise(attr, wanted_comp):
                    """Read vertex data only for vertices in unique_verts."""
                    vb_idx = attr.vertexBuffer
                    if vb_idx >= len(vbs):
                        return []
                    vb_info = vbs[vb_idx]
                    if vb_info.resourceId == rd.ResourceId.Null():
                        return []
                    try:
                        buf_data = ctrl.GetBufferData(vb_info.resourceId, 0, 0)
                    except Exception:
                        return []
                    fmt = attr.format
                    orig_comp = fmt.compCount
                    stride = vb_info.byteStride
                    if stride == 0 or not buf_data:
                        return []

                    comp_map = {
                        (rd.CompType.Float, 2): ('e', 2),
                        (rd.CompType.Float, 4): ('f', 4),
                        (rd.CompType.UInt, 1):  ('B', 1),
                        (rd.CompType.UInt, 2):  ('H', 2),
                        (rd.CompType.UInt, 4):  ('I', 4),
                        (rd.CompType.SInt, 1):  ('b', 1),
                        (rd.CompType.SInt, 2):  ('h', 2),
                        (rd.CompType.SInt, 4):  ('i', 4),
                        (rd.CompType.UNorm, 1): ('B', 1),
                        (rd.CompType.UNorm, 2): ('H', 2),
                        (rd.CompType.SNorm, 1): ('b', 1),
                        (rd.CompType.SNorm, 2): ('h', 2),
                    }
                    key = (fmt.compType, fmt.compByteWidth)
                    if key not in comp_map:
                        if fmt.compByteWidth == 2:
                            char, sz = 'e', 2
                        else:
                            return []
                    else:
                        char, sz = comp_map[key]

                    # Always read original compCount to keep stride alignment correct
                    unpack_fmt = '<%d%s' % (orig_comp, char)
                    elem_size = orig_comp * sz
                    is_unorm = fmt.compType == rd.CompType.UNorm
                    is_snorm = fmt.compType == rd.CompType.SNorm
                    unorm_max = float((2 ** (fmt.compByteWidth * 8)) - 1) if is_unorm else 1.0
                    snorm_max = float(2 ** (fmt.compByteWidth * 8 - 1) - 1) if is_snorm else 1.0

                    results = []
                    for vi in unique_verts:
                        offset = vb_info.byteOffset + attr.byteOffset + vi * stride
                        if offset + elem_size > len(buf_data):
                            results.append(tuple([0.0] * wanted_comp))
                            continue
                        try:
                            raw = _struct.unpack_from(unpack_fmt, buf_data, offset)
                            if is_unorm:
                                vals = tuple(v / unorm_max for v in raw)
                            elif is_snorm:
                                vals = tuple(max(-1.0, v / snorm_max) for v in raw)
                            else:
                                vals = tuple(float(v) for v in raw)
                            # Truncate to wanted components, pad with 0 if not enough
                            cleaned = []
                            for ci in range(wanted_comp):
                                if ci < len(vals):
                                    fv = float(vals[ci])
                                    if not _math.isfinite(fv) or abs(fv) > 1e9:
                                        cleaned.append(0.0)
                                    else:
                                        cleaned.append(fv)
                                else:
                                    cleaned.append(0.0)
                            results.append(tuple(cleaned))
                        except Exception:
                            results.append(tuple([0.0] * wanted_comp))
                    return results

                # Read position (negate X for DX left-hand → right-hand coord system)
                raw_pos = _read_attr_precise(pos_attr, 3)
                positions = [(-p[0] if len(p) > 0 else 0.0, p[1] if len(p) > 1 else 0.0, p[2] if len(p) > 2 else 0.0) for p in raw_pos]

                # Read normals (with packed-encoding detection)
                if normal_attr:
                    raw_norm = _read_attr_precise(normal_attr, 3)
                    # Normalize + detect packed encoding
                    temp_normals = []
                    for n in raw_norm:
                        nx = n[0] if len(n) > 0 else 0.0
                        ny = n[1] if len(n) > 1 else 0.0
                        nz = n[2] if len(n) > 2 else 0.0
                        length = _math.sqrt(nx*nx + ny*ny + nz*nz)
                        if length > 1e-8:
                            nx, ny, nz = nx/length, ny/length, nz/length
                        else:
                            nx, ny, nz = 0.0, 0.0, 1.0
                        temp_normals.append((nx, ny, nz))
                    # Check if normals are valid (not packed/encoded data)
                    if temp_normals:
                        max_abs = max(max(abs(n[0]), abs(n[1]), abs(n[2])) for n in raw_norm)
                        if max_abs > 1.5:
                            # Packed encoding — discard, let importing tool recalculate
                            normals = []
                            has_normals = False
                        else:
                            normals = temp_normals
                            has_normals = len(normals) == len(positions)

                # Read UVs (NO flip — DX UV is already correct for Unity/FBX import)
                if uv_attr:
                    raw_uvs = _read_attr_precise(uv_attr, uv_attr.format.compCount)
                    for uv in raw_uvs:
                        u = uv[0] if len(uv) > 0 else 0.0
                        v = uv[1] if len(uv) > 1 else 0.0
                        uvs.append((u, v))
                    has_uvs = len(uvs) == len(positions)

                if positions:
                    mesh_extracted = True

    # ============================================================
    # Method 2: Fallback to PostVS (original approach)
    # ============================================================
    if not mesh_extracted and mesh_out:
        vb_rid = mesh_out.vertexResourceId
        vb_offset_val = mesh_out.vertexByteOffset
        vb_stride_val = mesh_out.vertexByteStride
        num_verts = mesh_out.numIndices

        if vb_rid and int(vb_rid) != 0 and vb_stride_val > 0 and num_verts > 0:
            try:
                vb_data = ctrl.GetBufferData(vb_rid, vb_offset_val, num_verts * vb_stride_val)
            except Exception:
                vb_data = None

            if vb_data and len(vb_data) >= vb_stride_val:
                # Detect layout from VS output signature
                pos_off = 0
                norm_off = -1
                uv_off = -1
                pid2 = _get_pipeline_obj(ps, ctrl)
                vs_id = ps.GetShader(rd.ShaderStage.Vertex)
                if vs_id and int(vs_id) != 0:
                    entries = ctrl.GetShaderEntryPoints(vs_id)
                    if entries:
                        selection = _pipeline_shader_entry_selection(
                            ps, rd.ShaderStage.Vertex, "vertex", vs_id, entries)
                        selected_entry = selection.get("entry")
                        refl2 = (
                            ctrl.GetShader(pid2, vs_id, selected_entry)
                            if selected_entry is not None else None)
                        if (refl2 is not None and
                                _shader_reflection_identity_failure(
                                    refl2, selected_entry, vs_id, pid2,
                                    "vertex", selection) is not None):
                            refl2 = None
                        if refl2 and refl2.outputSignature:
                            byte_off = 0
                            for sig in refl2.outputSignature:
                                sem = getattr(sig, 'semanticName', '').upper()
                                count = getattr(sig, 'compCount', 4)
                                sz = count * 4
                                if 'POSITION' in sem or 'SV_POSITION' in sem:
                                    pos_off = byte_off
                                elif 'NORMAL' in sem:
                                    norm_off = byte_off
                                elif 'TEXCOORD' in sem and uv_off < 0:
                                    uv_off = byte_off
                                byte_off += sz

                if vb_stride_val >= 32 and norm_off < 0:
                    norm_off = 16
                if vb_stride_val >= 40 and uv_off < 0:
                    uv_off = 32

                actual_verts = min(num_verts, len(vb_data) // vb_stride_val)
                for i in range(actual_verts):
                    base = i * vb_stride_val
                    if base + pos_off + 12 <= len(vb_data):
                        px, py, pz = _struct.unpack_from("<fff", vb_data, base + pos_off)
                        positions.append((px, py, pz))
                    if norm_off >= 0 and base + norm_off + 12 <= len(vb_data):
                        nx, ny, nz = _struct.unpack_from("<fff", vb_data, base + norm_off)
                        normals.append((nx, ny, nz))
                    if uv_off >= 0 and base + uv_off + 8 <= len(vb_data):
                        u, v = _struct.unpack_from("<ff", vb_data, base + uv_off)
                        uvs.append((u, v))

                has_normals = len(normals) == len(positions)
                has_uvs = len(uvs) == len(positions)

                # Use index buffer from PostVS
                if not indices:
                    ib_rid2 = mesh_out.indexResourceId
                    if ib_rid2 and int(ib_rid2) != 0:
                        ib_off2 = mesh_out.indexByteOffset
                        ib_stride2 = mesh_out.indexByteStride
                        try:
                            ib_data = ctrl.GetBufferData(ib_rid2, ib_off2, num_verts * ib_stride2)
                            for i in range(min(num_verts, len(ib_data) // ib_stride2)):
                                if ib_stride2 == 2:
                                    indices.append(_struct.unpack_from("<H", ib_data, i * 2)[0])
                                elif ib_stride2 == 4:
                                    indices.append(_struct.unpack_from("<I", ib_data, i * 4)[0])
                                else:
                                    indices.append(i)
                        except Exception:
                            indices = list(range(num_verts))
                    else:
                        indices = list(range(num_verts))

    if not positions:
        return None

    # ============================================================
    # Write OBJ file
    # ============================================================
    obj_path = os.path.join(output_dir, mesh_name + ".obj")
    num_faces = len(indices) // 3

    with open(obj_path, 'w', encoding='utf-8') as f:
        f.write("# Exported from Bread + Model Extractor\n")
        f.write("# Vertices: %d, Faces: %d\n\n" % (len(positions), num_faces))
        f.write("o %s\n\n" % mesh_name)

        for p in positions:
            f.write("v %.6f %.6f %.6f\n" % (p[0], p[1], p[2]))
        if uvs:
            f.write("\n")
            for uv in uvs:
                f.write("vt %.6f %.6f\n" % (uv[0], uv[1]))
        if normals:
            f.write("\n")
            for n in normals:
                f.write("vn %.6f %.6f %.6f\n" % (n[0], n[1], n[2]))
        f.write("\n")
        # Reverse winding order (swap i1/i2) to match X-axis flip for correct face normals
        for fi in range(num_faces):
            i0 = indices[fi * 3] + 1
            i1 = indices[fi * 3 + 1] + 1
            i2 = indices[fi * 3 + 2] + 1
            if has_uvs and has_normals:
                f.write("f %d/%d/%d %d/%d/%d %d/%d/%d\n" % (i0, i0, i0, i2, i2, i2, i1, i1, i1))
            elif has_uvs:
                f.write("f %d/%d %d/%d %d/%d\n" % (i0, i0, i2, i2, i1, i1))
            elif has_normals:
                f.write("f %d//%d %d//%d %d//%d\n" % (i0, i0, i2, i2, i1, i1))
            else:
                f.write("f %d %d %d\n" % (i0, i2, i1))

    # ============================================================
    # Write FBX file (ASCII 7.4, Unity compatible)
    # ============================================================
    fbx_path = os.path.join(output_dir, mesh_name + ".fbx")
    _write_fbx_ascii(fbx_path, mesh_name, positions, normals, uvs, indices, num_faces)

    return {
        "objPath": obj_path,
        "fbxPath": fbx_path,
        "vertexCount": len(positions),
        "triangleCount": num_faces,
        "hasNormals": has_normals,
        "hasUVs": has_uvs,
        "method": "VBuffer" if mesh_extracted else "PostVS",
    }


def _write_fbx_ascii(filepath, name, positions, normals, uvs, indices, num_faces):
    """Write FBX 7.4 ASCII file (from Model Extractor export_fbx)."""
    import math as _math

    num_verts = len(positions)
    has_normals = len(normals) == num_verts
    has_uvs = len(uvs) == num_verts

    if num_verts == 0 or num_faces == 0:
        return

    model_id = 1000000001
    geom_id = 1000000002
    material_id = 1000000003

    def safe_float(v):
        if not _math.isfinite(v) or abs(v) > 1e9:
            return 0.0
        return v

    flat_pos = []
    for p in positions:
        flat_pos.extend(safe_float(v) for v in p)

    # Reverse winding (swap i1/i2) to match X-axis flip
    fbx_idx = []
    for fi in range(num_faces):
        i0, i1, i2 = indices[fi * 3], indices[fi * 3 + 1], indices[fi * 3 + 2]
        fbx_idx.extend([i0, i2, -(i1 + 1)])

    # Edges
    edge_set = set()
    edges = []
    for fi in range(num_faces):
        base = fi * 3
        tri = [indices[fi * 3], indices[fi * 3 + 1], indices[fi * 3 + 2]]
        for j in range(3):
            v0, v1 = tri[j], tri[(j + 1) % 3]
            ek = (min(v0, v1), max(v0, v1))
            if ek not in edge_set:
                edge_set.add(ek)
                edges.append(base + j)

    def fmt_fa(arr, per=6):
        lines = []
        for i in range(0, len(arr), per):
            lines.append(",".join("%.6f" % v for v in arr[i:i + per]))
        return ",\n\t\t\t\t".join(lines)

    def fmt_ia(arr, per=12):
        lines = []
        for i in range(0, len(arr), per):
            lines.append(",".join(str(v) for v in arr[i:i + per]))
        return ",\n\t\t\t\t".join(lines)

    norm_sec = ""
    if has_normals:
        fn = []
        for fi in range(num_faces):
            for j in range(3):
                idx = indices[fi * 3 + j]
                if idx < len(normals):
                    fn.extend(safe_float(v) for v in normals[idx])
                else:
                    fn.extend([0.0, 0.0, 1.0])
        norm_sec = """
\t\tLayerElementNormal: 0 {
\t\t\tVersion: 102
\t\t\tName: "Normals"
\t\t\tMappingInformationType: "ByPolygonVertex"
\t\t\tReferenceInformationType: "Direct"
\t\t\tNormals: *%d {
\t\t\t\ta: %s
\t\t\t}
\t\t}""" % (len(fn), fmt_fa(fn))

    uv_sec = ""
    uv_idx_list = []
    if has_uvs:
        for fi in range(num_faces):
            for j in range(3):
                uv_idx_list.append(indices[fi * 3 + j])
        flat_uv = []
        for uv in uvs:
            flat_uv.extend(safe_float(v) for v in uv)
        uv_sec = """
\t\tLayerElementUV: 0 {
\t\t\tVersion: 101
\t\t\tName: "UVMap"
\t\t\tMappingInformationType: "ByPolygonVertex"
\t\t\tReferenceInformationType: "IndexToDirect"
\t\t\tUV: *%d {
\t\t\t\ta: %s
\t\t\t}
\t\t\tUVIndex: *%d {
\t\t\t\ta: %s
\t\t\t}
\t\t}""" % (len(flat_uv), fmt_fa(flat_uv), len(uv_idx_list), fmt_ia(uv_idx_list))

    mat_sec = """
\t\tLayerElementMaterial: 0 {
\t\t\tVersion: 101
\t\t\tName: ""
\t\t\tMappingInformationType: "AllSame"
\t\t\tReferenceInformationType: "IndexToDirect"
\t\t\tMaterials: *1 {
\t\t\t\ta: 0
\t\t\t}
\t\t}"""

    layer_entries = ""
    if has_normals:
        layer_entries += """
\t\t\tLayerElement:  {
\t\t\t\tType: "LayerElementNormal"
\t\t\t\tTypedIndex: 0
\t\t\t}"""
    if has_uvs:
        layer_entries += """
\t\t\tLayerElement:  {
\t\t\t\tType: "LayerElementUV"
\t\t\t\tTypedIndex: 0
\t\t\t}"""
    layer_entries += """
\t\t\tLayerElement:  {
\t\t\t\tType: "LayerElementMaterial"
\t\t\t\tTypedIndex: 0
\t\t\t}"""

    now = time.gmtime()

    content = """; FBX 7.4.0 project file
; Exported by Bread (Model Extractor engine)
FBXHeaderExtension:  {
\tFBXHeaderVersion: 1003
\tFBXVersion: 7400
\tCreationTimeStamp:  {
\t\tVersion: 1000
\t\tYear: %d
\t\tMonth: %d
\t\tDay: %d
\t\tHour: %d
\t\tMinute: %d
\t\tSecond: %d
\t\tMillisecond: 0
\t}
\tCreator: "Bread v1.8"
}

GlobalSettings:  {
\tVersion: 1000
\tProperties70:  {
\t\tP: "UpAxis", "int", "Integer", "",1
\t\tP: "UpAxisSign", "int", "Integer", "",1
\t\tP: "FrontAxis", "int", "Integer", "",2
\t\tP: "FrontAxisSign", "int", "Integer", "",1
\t\tP: "CoordAxis", "int", "Integer", "",0
\t\tP: "CoordAxisSign", "int", "Integer", "",1
\t\tP: "UnitScaleFactor", "double", "Number", "",1.0
\t\tP: "OriginalUnitScaleFactor", "double", "Number", "",1.0
\t}
}

Documents:  {
\tCount: 1
\tDocument: 100000000, "", "Scene" {
\t\tProperties70:  {
\t\t\tP: "SourceObject", "object", "", ""
\t\t\tP: "ActiveAnimStackName", "KString", "", "", ""
\t\t}
\t\tRootNode: 0
\t}
}

References:  {
}

Definitions:  {
\tVersion: 100
\tCount: 4
\tObjectType: "GlobalSettings" {
\t\tCount: 1
\t}
\tObjectType: "Model" {
\t\tCount: 1
\t}
\tObjectType: "Geometry" {
\t\tCount: 1
\t}
\tObjectType: "Material" {
\t\tCount: 1
\t}
}

Objects:  {
\tGeometry: %d, "Geometry::%s", "Mesh" {
\t\tVertices: *%d {
\t\t\ta: %s
\t\t}
\t\tPolygonVertexIndex: *%d {
\t\t\ta: %s
\t\t}
\t\tEdges: *%d {
\t\t\ta: %s
\t\t}
\t\tGeometryVersion: 124%s%s%s
\t\tLayer: 0 {
\t\t\tVersion: 100%s
\t\t}
\t}
\tModel: %d, "Model::%s", "Mesh" {
\t\tVersion: 232
\t\tProperties70:  {
\t\t\tP: "RotationActive", "bool", "", "",1
\t\t\tP: "InheritType", "enum", "", "",1
\t\t\tP: "DefaultAttributeIndex", "int", "Integer", "",0
\t\t\tP: "Lcl Translation", "Lcl Translation", "", "A+",0,0,0
\t\t\tP: "Lcl Rotation", "Lcl Rotation", "", "A+",0,0,0
\t\t\tP: "Lcl Scaling", "Lcl Scaling", "", "A+",1,1,1
\t\t}
\t\tShading: T
\t\tCulling: "CullingOff"
\t}
\tMaterial: %d, "Material::DefaultMaterial", "" {
\t\tVersion: 102
\t\tShadingModel: "phong"
\t\tMultiLayer: 0
\t\tProperties70:  {
\t\t\tP: "DiffuseColor", "Color", "", "A",0.8,0.8,0.8
\t\t}
\t}
}

Connections:  {
\tC: "OO",%d,0
\tC: "OO",%d,%d
\tC: "OO",%d,%d
}
""" % (
        now.tm_year, now.tm_mon, now.tm_mday, now.tm_hour, now.tm_min, now.tm_sec,
        geom_id, name, num_verts * 3, fmt_fa(flat_pos),
        len(fbx_idx), fmt_ia(fbx_idx),
        len(edges), fmt_ia(edges),
        norm_sec, uv_sec, mat_sec, layer_entries,
        model_id, name,
        material_id,
        model_id, geom_id, model_id, material_id, model_id,
    )

    with open(filepath, 'w', encoding='ascii') as f:
        f.write(content)


# (Old PostVS-based mesh export code removed - replaced by VBuffer approach above)


def _generate_unity_import_script(mesh_name, unity_mat, tex_exports, output_dir):
    """Generate a C# editor script to auto-import the exported assets into Unity."""
    script_path = os.path.join(output_dir, mesh_name + "_UnityImport.cs")

    tex_assignments = []
    for prop_name, tex_data in unity_mat.get("textures", {}).items():
        tex_assignments.append(
            '            // Slot %s (%s): use save_texture(resource_id=%s) to export, then assign here'
            % (prop_name, tex_data.get("role", "unknown"), tex_data.get("resourceId", 0))
        )

    float_assignments = []
    for prop_name, val in unity_mat.get("floats", {}).items():
        float_assignments.append(
            '            mat.SetFloat("%s", %sf);' % (prop_name, val)
        )

    color_assignments = []
    for prop_name, col in unity_mat.get("colors", {}).items():
        color_assignments.append(
            '            mat.SetColor("%s", new Color(%sf, %sf, %sf, %sf));'
            % (prop_name, col["r"], col["g"], col["b"], col["a"])
        )

    script = '''// Auto-generated Unity Import Script from Bread
// Mesh: %(mesh_name)s | Event ID: exported from RenderDoc capture
//
// Usage: Place this script in Assets/Editor/ and run from menu:
//        RenderDoc > Import %(mesh_name)s

#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using System.IO;

public class Import_%(safe_name)s
{
    [MenuItem("RenderDoc/Import %(mesh_name)s")]
    public static void Import()
    {
        string srcDir = EditorUtility.OpenFolderPanel("Select exported folder", "", "");
        if (string.IsNullOrEmpty(srcDir)) return;

        string destDir = "Assets/RenderDoc_Imports/%(mesh_name)s";
        if (!Directory.Exists(destDir))
            Directory.CreateDirectory(destDir);

        // Copy files to project
        foreach (string file in Directory.GetFiles(srcDir))
        {
            string ext = Path.GetExtension(file).ToLower();
            if (ext == ".obj" || ext == ".mtl" || ext == ".png" || ext == ".json")
            {
                string dest = Path.Combine(destDir, Path.GetFileName(file));
                File.Copy(file, dest, true);
            }
        }
        AssetDatabase.Refresh();

        // Create material
        string texDir = destDir;
        Material mat = new Material(Shader.Find("Standard"));
        mat.name = "%(mesh_name)s_Mat";

        // Assign textures
%(tex_assignments)s

        // Set float properties
%(float_assignments)s

        // Set color properties
%(color_assignments)s

        AssetDatabase.CreateAsset(mat, destDir + "/%(mesh_name)s_Mat.mat");

        // Try to assign material to imported mesh
        string objPath = destDir + "/%(mesh_name)s.obj";
        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(objPath);
        if (prefab != null)
        {
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>();
            foreach (Renderer r in renderers)
            {
                r.sharedMaterial = mat;
            }
            Debug.Log("[Bread] Imported %(mesh_name)s with " + renderers.Length + " renderers");
        }

        AssetDatabase.SaveAssets();
        Debug.Log("[Bread] Import complete: " + destDir);
    }
}
#endif
''' % {
        "mesh_name": mesh_name,
        "safe_name": mesh_name.replace(" ", "_").replace("-", "_"),
        "tex_assignments": "\n".join(tex_assignments) if tex_assignments else "            // No textures to assign",
        "float_assignments": "\n".join(float_assignments) if float_assignments else "            // No float properties",
        "color_assignments": "\n".join(color_assignments) if color_assignments else "            // No color properties",
    }

    with open(script_path, "w", encoding="utf-8") as f:
        f.write(script)

    return script_path


def _pass_display_session_capture_id(capture_session_id):
    """Mirror the Host's non-persistent pass-panel capture identity."""
    session_id = _shader_override_hex(
        capture_session_id, "expected_capture_session_id", 32)
    return hashlib.sha256(
        ("replaylab-pass-display-session/v1:" + session_id).encode("ascii")
    ).hexdigest()


def _load_pass_classification(params):
    """Load one fixed-program pass tree into the capture-bound UI panel."""
    global _pass_panel_ui
    if not HAS_UI:
        raise RuntimeError("Bread Semantic Passes UI is unavailable")
    if _pass_panel_ui is None:
        if not callable(_pass_panel_factory):
            raise RuntimeError("Bread Semantic Passes UI is unavailable")
        _pass_panel_ui = _pass_panel_factory()
    expected_session = _shader_override_hex(
        params.get("expected_capture_session_id"),
        "expected_capture_session_id", 32)
    if not _capture_session_id or expected_session != _capture_session_id:
        raise RuntimeError("Capture session changed before pass-panel publication")
    classification = params.get("classification")
    clean = _pass_panel_protocol.validate_classification(classification)
    binding_mode = str(
        params.get("capture_binding_mode", "project-catalog") or ""
    ).strip()
    if binding_mode == "display-session":
        capture_id = _pass_display_session_capture_id(expected_session)
        if clean["captureId"] != capture_id:
            raise RuntimeError(
                "Display-only pass classification belongs to another capture session")
    elif binding_mode == "project-catalog":
        capture_id = _require_capture_identity(clean["captureId"])
    else:
        raise ValueError("Unsupported pass-panel capture binding mode")
    status = _pass_panel_ui.load(classification)
    _pass_panel_ui.show()
    return {
        "schema": "replaylab-pass-panel-load/v1",
        "schemaVersion": 1,
        "captureId": capture_id,
        "captureSessionId": _capture_session_id,
        "captureBindingMode": binding_mode,
        "panel": status,
        "loaded": True,
        "replayMutation": False,
        "classificationAuthority": "FixedProgram",
        "aiProposalAuthority": "AIProvisional",
    }


def _close_pass_panel(_params):
    """Close the semantic-pass dock through the same native path as its X button."""
    global _pass_panel_ui
    panel = _pass_panel_ui
    _pass_panel_ui = None
    if panel is None:
        return {
            "schema": "replaylab-pass-panel-close/v1",
            "schemaVersion": 1,
            "closed": False,
            "alreadyClosed": True,
        }
    panel.shutdown()
    return {
        "schema": "replaylab-pass-panel-close/v1",
        "schemaVersion": 1,
        "closed": True,
        "alreadyClosed": False,
    }


# ---- Method table ----
_application_ui_controller = None


def _application_ui():
    global _application_ui_controller
    if not HAS_UI or _ctx is None:
        raise RuntimeError("Bread application UI is unavailable")
    if _application_ui_controller is None:
        from .project_ui_control import ApplicationUIController

        def _panel(callbacks, get_panel):
            if not callbacks:
                raise RuntimeError("Bread panel is unavailable")
            callbacks[0]()
            panel = get_panel()
            if panel is None or getattr(panel, "top", None) is None:
                raise RuntimeError("Bread panel could not be opened")
            if not panel.top.isVisible():
                raise RuntimeError("Bread panel did not become visible")

        def _assistant():
            action = _ctx.GetMainWindow().Widget().findChild(
                QtWidgets.QAction, "action_AI_Assistant")
            if action is None:
                raise RuntimeError("Bread AI window action is unavailable")
            action.trigger()

        _application_ui_controller = ApplicationUIController(_ctx, {
            "shader-workspace": lambda: _panel(
                _shader_workspace_callbacks, lambda: _shader_workspace_ui),
            "console": lambda: _panel(
                _shader_console_callbacks, lambda: _shader_console_ui),
            "bread-ai": _assistant,
            "frame-render-flow": lambda: _ensure_frame_render_flow_ui().show(),
        })
    return _application_ui_controller


def _open_document_rpc(params):
    return _invoke_on_ui_sync(lambda: json.loads(open_native_document_json(json.dumps(params))))


def _get_application_ui_state(params):
    return _invoke_on_ui_sync(lambda: _application_ui().inspect(params))


def _control_application_ui(params):
    return _invoke_on_ui_sync(lambda: _application_ui().perform(params))


def _shutdown_application_ui():
    global _application_ui_controller
    document_module = sys.modules.get(__name__ + ".project_document_viewer")
    if document_module is not None:
        document_module.shutdown()
    if _application_ui_controller is not None:
        _application_ui_controller.shutdown()
        _application_ui_controller = None


